def check_imports_are_installed(verbose=True):
    """
    Try to import every module (and submodule) that NEMESIS uses in
    NEMESIS_pipeline_new_temp_2.py. Prints a compact report and returns
    (missing, imported) where each is a list of module strings.
    """
    import importlib

    # Core third-party + submodules you actually import in the code
    # (kept explicit to avoid false positives/negatives)
    modules_to_check = [
        # --- numerical / plotting ---
        "numpy",
        "scipy", "scipy.signal",
        "matplotlib", "matplotlib.pyplot",
        "matplotlib.backends.backend_pdf",
        "matplotlib.gridspec",
        "pandas",

        # --- astronomy toolkits ---
        "astropy", "astropy.io.fits", "astropy.wcs", "astropy.units", "astropy.coordinates",
        "astroquery", "astroquery.mast", "astroquery.gaia", "astroquery.skyview",

        # --- transit search / detrending ---
        "transitleastsquares",
        "wotan",
        "fbpca",
        "lightkurve",

        # --- pipeline utilities explicitly referenced ---
        "astrobase",           # you use astrobase.plotbase.skyview_stamp and friends
        "bs4",                 # BeautifulSoup
        "requests",

        # --- project / domain-specific extras used in this file ---
        "leo_vetter",          # custom vetter module (external/non-pip in many setups)
        #"EDIunplugged",        # EDI vetter (no longer used)
        "lksearch",            # local helper module 
        "tess_stars2px",        #TESS-POINT's import name

        # --- stdlib that appear in imports (always present in Python, but we verify anyway) ---
        "itertools",
        "urllib", "urllib.error",
        "gc",
        "warnings",
    ]

    missing = []
    imported = []

    for mod in modules_to_check:
        try:
            importlib.import_module(mod)
            imported.append(mod)
        except Exception as exc:  # ImportError or submodule errors
            missing.append(f"{mod}  ({type(exc).__name__}: {exc})")

    if verbose:
        print("=== NEMESIS import check ===")
        if imported:
            print(f"OK  : {len(imported)} modules")
            if len(imported) <= 30:
                print("     " + ", ".join(imported))
        if missing:
            print(f"MISS: {len(missing)} modules/submodules")
            for m in missing:
                print("     -", m)
            # quick hints for common tricky ones
            hints = {
                "astrobase": "pip install astrobase",
                "wotan": "pip install wotan",
                "transitleastsquares": "pip install transitleastsquares",
                "fbpca": "pip install fbpca",
                "lightkurve": "pip install lightkurve --upgrade",
                "bs4": "pip install beautifulsoup4",
                "astroquery": "pip install astroquery",
                "leo_vetter": "Install/put on PYTHONPATH (project-local module)",
                "lksearch": "Install/put on PYTHONPATH (project-local module)",
                "EDIunplugged": "pip install EDIunplugged",
                "tess_stars2px": "python -m pip install tess-point",
            }
            print("\nInstall hints:")
            for key, hint in hints.items():
                if any(m.startswith(key) for m in missing):
                    print(f"  • {key}: {hint}")

    return missing, imported

