# Custom Error Functions
class NoImageDataError(RuntimeError):
    """Raised when no TESScut/TPF/FFI image data are available for a TIC+Sector+cadence."""
    pass
def _ensure_hdu_or_raise_OLD(hdu, ID, Sector, cadence):
    """Raise NoImageDataError if nothing usable is in hdu."""
    none_like = (hdu is None) or (isinstance(hdu, list) and all(x is None for x in hdu))
    if none_like:
        raise NoImageDataError(
            f'No Image data for TIC {ID} in Sector {_sec_str(Sector)} with "{cadence}" cadence!!!'
        )

def _ensure_hdu_or_raise(hdu, ID, Sector, cadence):
    """
    Raise NoImageDataError if nothing usable is in hdu.

    Before raising, print one ``[no image data]`` line per requested sector
    that restates the cause recorded by ``gethdu_lksearch`` (see
    ``gethdu_failure_summary``). The exception type and message are
    unchanged from the previous version.

    Parameters
    ----------
    hdu : HDUList, list of HDUList/None, or None
        gethdu output for this target.
    ID : int
        TIC identifier.
    Sector : int or list of int
        Requested sector(s).
    cadence : str
        NEMESIS cadence label.

    Returns
    -------
    None

    Raises
    ------
    NoImageDataError
        If hdu is None or a list of only None.

    Example
    -------
    >>> _ensure_hdu_or_raise(None, 1, 18, "30 minute")   # doctest: +SKIP
    """
    none_like = (hdu is None) or (isinstance(hdu, list) and all(x is None for x in hdu))
    if none_like:
        secs = ([Sector] if (Sector is None or np.isscalar(Sector))
                else list(np.atleast_1d(Sector)))
        for sec in secs:
            print(gethdu_failure_summary(ID, sec), flush=True)
        raise NoImageDataError(
            f'No Image data for TIC {ID} in Sector {_sec_str(Sector)} with "{cadence}" cadence!!!'
        )


