# NEW
def while_loop(command, message, *args, base_delay=1, max_delay=64,
                       max_retries=10, total_timeout=None, **kwargs):
    """
    Call `command(*args, **kwargs)` with exponential back‑off.
    Stops after `max_retries` failures (None = infinite).
    Returns the function’s result or raises the last exception.
    """
    import time, random, socket, urllib, requests, astroquery
    from lightkurve.search import SearchError
    from astroquery.exceptions import RemoteServiceError
    import time as clock
    start=clock.time()

    exceptions = (socket.timeout,
                  urllib.error.URLError,
                  requests.exceptions.RequestException,
                  requests.exceptions.HTTPError,
                  requests.exceptions.ConnectionError,
                  astroquery.exceptions.TimeoutError,
                  RemoteServiceError, SearchError,TimeoutError,
                  IndexError, ValueError)

    start   = time.time()#time.perf_counter()
    tries   = 0
    delay   = base_delay
    
    while True:
        # -- overall timeout check (skip if None) --
        #if total_timeout is not None and time.perf_counter() - start > total_timeout:
        if total_timeout is not None and clock.time() - start > total_timeout:
            print(f"[while_loop] exceeded {total_timeout}s – returning None")
            return None
        try:            
            # ---------- run the callable ----------
            out = command(*args, **kwargs)
            
            if (out is None) or (hasattr(out, "__len__") and len(out) == 0):
                print(f"[{command.__name__}] resulted in no result!!!") 
                raise ValueError("empty result")
            return out
        # ---------- catch transient errors ----------
        except exceptions as err:
            print(message)
            tries += 1
            if max_retries is not None and tries > max_retries:
                print(f"[while_loop] exceeded {max_retries} retries – returning None")
                return None
                
            delay = min(max_delay, base_delay * 2**(tries-1) + random.random())
            print(message)
            print(f"[{command.__name__}] attempt {tries} failed: {err}. "
                  f"Retrying in {delay:.1f}s")
            time.sleep(delay)

