def Make_dirs(Sector, cadence, default_settings, return_paths=False ):
    """
    Create all NEMESIS output directories and write resolved path strings
    back into ``default_settings``.

    This function must be called before any other pipeline step so that
    ``savelcpath``, ``savefigpath``, ``saveReportpath_BLS``,
    ``saveReportpath_TLS``, and ``downloadpath`` are populated in
    ``default_settings``.  It is also responsible for pointing
    ``astroquery``, ``lightkurve``, and related library caches at the
    canonical ``downloadpath``.

    Directory structure created
    ---------------------------
    Under ``default_settings['base_path'] / <sector_tag>/``:

    .. code-block:: text

        NEMESIS_FFI_plots/          (or NEMESIS_TPF_plots/ for short cadence)
        NEMESIS_FFI_LCs/
        NEMESIS_FFI_BLS_Report/
        NEMESIS_FFI_TLS_Report/

    For injection runs (``inject_param_P_RP_T0`` is not ``None``), an
    additional ``injections/Period_{P}_RP_{Rp}/`` branch is inserted.

    Side effects
    ------------
    Mutates ``default_settings`` in-place, adding or updating the keys:
    ``base_path``, ``path``, ``savefigpath``, ``savelcpath``,
    ``saveReportpath_BLS``, ``saveReportpath_TLS``, ``cache_root``,
    ``downloadpath`` (only if not already present).

    Parameters
    ----------
    Sector : int, list of int, or None
        Used to determine the sector-tag component of the directory name
        (``Sector_NNNN`` for a single int, ``Multi_Sector`` otherwise).
    cadence : str
        Determines the cadence-family tag: ``'FFI'`` for 30/10-minute,
        ``'TPF'`` for 2-minute or 20-second.
    default_settings : dict
        NEMESIS settings dict.  Must contain ``base_path`` (set by
        ``full_pipeline`` before this call).  Mutated in-place.
    return_paths : bool, optional
        If ``True``, return the four primary path strings.  Default is
        ``False``.

    Returns
    -------
    path : str or None
        Results root directory (``base_path/sector_tag/``), only returned
        when ``return_paths=True``.
    savefigpath : str or None
        Figure output directory, only returned when ``return_paths=True``.
    savelcpath : str or None
        Light curve CSV output directory, only returned when
        ``return_paths=True``.
    downloadpath : str or None
        Cache/download directory, only returned when ``return_paths=True``.

    Notes
    -----
    When ``return_paths=False`` (the default), the function returns ``None``
    but the side-effect on ``default_settings`` is still applied.

    Examples
    --------
    >>> default_settings = default_NEMESIS_pipeline_settings()
    >>> default_settings['base_path'] = '/data/nemesis/'
    >>> Make_dirs(3, '30 minute', default_settings)
    >>> default_settings['savelcpath']
    '/data/nemesis/Sector_0003/NEMESIS_FFI_LCs/'
    # paths are written back into `default_settings`.
    """
    
    import os, numpy as np, astropy, astroquery
    import lightkurve as lk
    import numbers
    from pathlib import Path

    # ----- tiny local helper: normalize paths (and optional trailing slash) -----
    def _norm(p: str, trail: bool = False) -> str:
        p = str(Path(p).expanduser().resolve())
        if trail and not p.endswith('/'):
            p += '/'
        return p

    # ---------- user inputs ----------
    base_root = (default_settings.get('base_path')
                     or default_settings.get('path')
                     or default_settings.get('savepath')
                     or os.getcwd())
    base_root = _norm(base_root)
    get_all        = bool(default_settings.get('get_all_sectors'))
    inj_params     = default_settings.get('inject_param_P_RP_T0')   # None or (P, Rp, T0)
    

    # ---------- 1.  immutable cache ----------
    cache_root = os.path.join(base_root, "cache")
    # the exact sub-layout (mastDownload/TESSCut/…) is handled by astroquery itself
    os.makedirs(cache_root, exist_ok=True)

    # point every library at that cache (keep your behavior, but guard imports)
    try:
        os.environ["XDG_CACHE_HOME"]          = cache_root
        astropy.utils.data.conf.cache_dir     = cache_root
        astroquery.cache_location             = cache_root
        try:
            from astroquery.mast import Catalogs, Tesscut
            from astroquery.gaia import Gaia
            from astroquery.vizier import Vizier
            from astroquery.skyview import SkyView
            Catalogs.cache_location = cache_root
            Tesscut.cache_location  = cache_root
            Gaia.cache_location     = cache_root
            Vizier.cache_location   = cache_root
            SkyView.cache_location  = cache_root
        except Exception:
            pass
        try:
            lk.conf.cache_dir = cache_root
        except Exception:
            pass
    except Exception:
        # never let cache pointing kill directory setup
        pass

    # ---------- 2.  mutable results root ----------
    if get_all or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"

    #results_root = os.path.join(base_root, "results", sector_tag)
    results_root = os.path.join(base_root, sector_tag)

    # injection branch (only if requested)
    if inj_params is not None:
        try:
            P, Rp, _ = inj_params
            inj_tag        = f"Period_{P:.2f}_RP_{Rp:.2f}"
            results_root   = os.path.join(results_root, "injections", inj_tag)
        except Exception:
            # don't die if inject params are weird; just skip branching
            pass

    # cadence family
    cadence_tag = (
        "FFI"
        if cadence in ("long", "30 minute", "10 minute")
        else "TPF")

    # ---------- 3.  leaf folders ----------
    folders = dict(
        savefig   = os.path.join(results_root, f"NEMESIS_{cadence_tag}_plots"),
        savelc    = os.path.join(results_root, f"NEMESIS_{cadence_tag}_LCs"),
        bls_rep   = os.path.join(results_root, f"NEMESIS_{cadence_tag}_BLS_Report"),
        tls_rep   = os.path.join(results_root, f"NEMESIS_{cadence_tag}_TLS_Report"),
    )
    for path in folders.values():
        os.makedirs(path, exist_ok=True)

    # ---------- 4.  write back into default_settings ----------
    default_settings.update({
        "base_path"   : base_root,
        "path"        : _norm(results_root,trail=True),        # keep old code happy (trailing /)
        "savefigpath" : _norm(folders["savefig"],trail=True),
        "savelcpath"  : _norm(folders["savelc"],trail=True),
        "saveReportpath_BLS": _norm(folders["bls_rep"],trail=True),
        "saveReportpath_TLS": _norm(folders["tls_rep"],trail=True),
        "cache_root"        : _norm(cache_root) 
    })
    
    #check for cache:
    if "downloadpath" not in default_settings:  
        #default_settings["downloadpath"] = cache_root + "/" # immutable cache
        default_settings["downloadpath"] = _norm(cache_root, trail=True)  # your code expects trailing '/'

    if return_paths:
        return (
            default_settings["path"],
            default_settings["savefigpath"],
            default_settings["savelcpath"],
            default_settings["downloadpath"],
        )
