# stolen and modified from lightkurve targetpixelfile.py, REALLY handy to use!
#
def check_wcs(hdu):
    """Returns an astropy.wcs.WCS for the input TESS FFI/TPF.

    Accepts a full HDUList (normal case), or a bare HDU extension
    (PrimaryHDU / BinTableHDU / ImageHDU), which is wrapped automatically.
    Raises a clear TypeError early if something that is neither is passed
    (e.g. an integer or numpy array) so the upstream bug surfaces immediately.

    Parameters
    ----------
    hdu : astropy.io.fits.HDUList or HDU extension

    Returns
    -------
    wcs : astropy.wcs.WCS
    """
    from astropy.io.fits import HDUList
    from astropy.io.fits.hdu.base import _BaseHDU
    from astropy.wcs import WCS

    # ── normalise to HDUList ──────────────────────────────────────────────────
    if not isinstance(hdu, HDUList):
        if not isinstance(hdu, _BaseHDU):
            raise TypeError(
                f"check_wcs: expected an HDUList or HDU extension, "
                f"got {type(hdu).__name__!r}. "
                "Check that plot_sources / plot_cutouts are passing 'hdu' "
                "and not 'Sector' or 'cadence' in that argument position."
            )
        hdu = HDUList([hdu])

    n = len(hdu)

    try:
        origin = hdu[0].header.get("ORIGIN", "")
        if "MAST" in origin:
            # TessCut TPFs: valid WCS only in ext 2; fall back gracefully
            if n > 2:
                return WCS(hdu[2].header)
            elif n > 1:
                return WCS(hdu[1].header)
            else:
                return WCS(hdu[0].header)
        else:
            # Standard NASA Ames TPF: WCS keywords in ext 1 (FLUX column)
            if n > 1:
                wcs_keywords = {
                    "1CTYP5": "CTYPE1", "2CTYP5": "CTYPE2",
                    "1CRPX5": "CRPIX1", "2CRPX5": "CRPIX2",
                    "1CRVL5": "CRVAL1", "2CRVL5": "CRVAL2",
                    "1CUNI5": "CUNIT1", "2CUNI5": "CUNIT2",
                    "1CDLT5": "CDELT1", "2CDLT5": "CDELT2",
                    "11PC5":  "PC1_1",  "12PC5":  "PC1_2",
                    "21PC5":  "PC2_1",  "22PC5":  "PC2_2",
                    "NAXIS1": "NAXIS1", "NAXIS2": "NAXIS2",
                }
                mywcs = {nk: hdu[1].header[ok]
                         for ok, nk in wcs_keywords.items()
                         if hdu[1].header.get(ok) is not None}
                return WCS(mywcs)
            else:
                return WCS(hdu[0].header)
    except (TypeError, IndexError):
        # last-resort fallback: descend from ext 2 → 1 → 0
        if n > 2:
            return WCS(hdu[2].header)
        elif n > 1:
            return WCS(hdu[1].header)
        else:
            return WCS(hdu[0].header)
