def edgeWarn_tesspt2px(outSector,ra,dec,scinfo, aberrate=False, 
                       combinedFits=False,noCollateral=False,
                       verbose=False):
    """
    Checks if a star (based on RA/Dec) is near the edge of a TESS 
    camera for the given sectors.

    This function uses the focal plane geometry (FPG) of TESS cameras
    to determine whether a star is near the edge of the detector. It 
    can account for relativistic aberration, and it supports different 
    FITS image types (calibrated FFIs, combined FITS, or raw CCD).

    Parameters:
    -----------
    outSector : array-like
        Array of TESS sectors in which the target star is observed. 
        Use -1 for sectors where no observation is available.
    ra : float
        The right ascension (RA) of the star in degrees.
    dec : float
        The declination (Dec) of the star in degrees.
    scinfo : object
        A custom object containing sector information and focal plane 
        geometry (FPG) objects. 
        Must contain:
        - `sectors` (list): List of sector numbers.
        - `midtimes` (list): Midpoint times (in JD) for the sectors.
        - `fpgObjs` (list): FPG objects for the sectors.
    aberrate : bool, optional
        If `True`, the function will apply an approximation of relativistic
        aberration to the RA/Dec coordinates (default is `False`).
    combinedFits : bool, optional
        If `True`, the function assumes the star is on a combined FITS 
        image instead of an individual CCD (default is `False`).
    noCollateral : bool, optional
        If `True`, the function assumes the star is in raw CCD coordinates,
        ignoring collateral pixels (default is `False`).
    verbose : bool, optional
        If `True`, additional information will be printed for each sector
        (default is `False`).

    Returns:
    --------
    edge_warnings : array-like
        An array of edge warnings for each sector:
        *  0: Star is not near the edge of the detector.
        *  1: Star is near the edge of the detector.
        * -1: No observation available for that sector.
    """
    from astropy.time import Time
    from astropy.coordinates import SkyCoord
    
    edge_warnings = []
    for S in range(len(outSector)):
        Sector = int(outSector[S])
        if Sector == -1:
            edgeWarn = -1
            edge_warnings = np.append(edge_warnings, edgeWarn)
            continue

        idxs = np.where(scinfo.sectors == Sector)[0]
        if idxs.size == 0:
            # Sector not present in scinfo; mark unknown
            if verbose:
                print(f"Sector {Sector}: not found in scinfo.sectors")
            edgeWarn = -1
            edge_warnings = np.append(edge_warnings, edgeWarn)
            continue

        idxSec = idxs[0]

        starRas = np.array([ra])
        starDecs = np.array([dec])

        if aberrate is True:
            from astropy.time import Time
            from astropy.coordinates import SkyCoord
            useTime = Time(scinfo.midtimes[idxSec], format='jd')
            ccat = SkyCoord(ra=starRas * u.deg, dec=starDecs * u.deg,
                            obstime=useTime, frame='icrs')
            cgcrs = ccat.transform_to('gcrs')
            starRas = np.array(cgcrs.ra.degree)
            starDecs = np.array(cgcrs.dec.degree)

        starInCam, starCcdNum, starFitsXs, starFitsYs, starCcdXs, starCcdYs = (
            scinfo.fpgObjs[idxSec].radec2pix(starRas, starDecs)
        )

        # CHANGE 1: aggregate across all cameras for this sector
        edgeWarn_sector = 0

        for jj, cam in enumerate(starInCam):
            # OPTIONAL: skip cameras where the star is not present
            try:
                if hasattr(cam, "__bool__") and (not cam):
                    continue
            except Exception:
                pass

            # SPOC calibrated FFIs have 44 collateral pixels in x and are 1-based
            xUse = starCcdXs[jj] + 45.0
            yUse = starCcdYs[jj] + 1.0
            xMin = 44.0
            ymaxCoord = 2049
            xmaxCoord = 2093

            if combinedFits is True:
                xUse = starFitsXs[jj]
                yUse = starFitsYs[jj]
                xmaxCoord = 4097
                ymaxCoord = 4097
                xMin = 0.0

            if noCollateral is True:
                xUse = starCcdXs[jj]
                yUse = starCcdYs[jj]
                xMin = 0.0

            # Bounds check for valid pixels
            if not (xUse > xMin and yUse > 0 and xUse < xmaxCoord and yUse < ymaxCoord):
                continue

            edgePix = 6

            # CHANGE 2: compute this-camera hit, then OR-accumulate to sector
            hit = (
                (xUse <= (xMin + edgePix)) or
                (xUse >= (xmaxCoord - edgePix)) or
                (yUse <= edgePix) or
                (yUse >= (ymaxCoord - edgePix))
            )

            if hit and verbose:
                # CHANGE 3: print always the per-sector value you’re evaluating now
                if xUse <= (xMin + edgePix):
                    print(f"xUse<=(xMin+edgePix) in S{Sector}")
                if xUse >= (xmaxCoord - edgePix):
                    print(f"xUse>=(xmaxCoord-edgePix) in S{Sector}")
                if yUse <= edgePix:
                    print(f"yUse<=edgePix in S{Sector}")
                if yUse >= (ymaxCoord - edgePix):
                    print(f"yUse>=(ymaxCoord-edgePix) in S{Sector}")

            edgeWarn_sector |= int(bool(hit))

        # record sector-level result
        edge_warnings = np.append(edge_warnings, edgeWarn_sector if edgeWarn_sector in (0, 1) else 0)

    return edge_warnings.astype(int)
