from pathlib import Path
def find_tesscut_file(
    basedir: str,
    sector: int,
    camera: int,
    ccd: int,
    size: int = 11,
) -> list[Path]:
    """
    Return every file whose name matches
        tess-s00[sector]-[camera]-[ccd]_*[size]x[size]*astrocut.fits
    anywhere under 'basedir'.
    """
    from pathlib import Path

    # zero‑pad the sector the same way TESSCut does
    sector_tag = f"s00{sector:02d}" if sector > 9 else f"s000{sector}"
    # build the pattern – * so RA/Dec can vary, second * so size can vary
    pattern = f"tess-{sector_tag}-{camera}-{ccd}_*_{size}x{size}_astrocut.fits"
    # recursive search
    print(basedir+pattern)
    result = list(Path(basedir).rglob(pattern))
    result = [str(p) for p in result]
    return result[0]

from pathlib import Path
from typing import Iterable, Optional, Union, List

def find_tpf_file(
    basedir: Union[str, Path],
    tic: int,
    sector: int,
    cadence: Optional[Union[int, str]] = None,  # e.g. 120, "2min", "120s", 20, "20s"
    include_gz: bool = True,
) -> Union[Path, List[Path], None]:
    """
    Recursively find SPOC Target Pixel Files (TPFs) on disk.

    Matches patterns like:
      tess*-s{sector:04d}-{tic:016d}-{cadence:04d}-{?}_tp.fits[.gz]

    Parameters
    ----------
    basedir   : directory root to search under
    tic       : TIC ID (int)
    sector    : TESS sector (int)
    cadence   : None (wildcard) or cadence in seconds (e.g. 120, "2min", "120s", 20, "20s")
    include_gz: also match .fits.gz
    first_only: return only the first match (Path) or all (List[Path])

    Returns
    -------
    Path | List[Path] | None
    """

    root = Path(basedir)
    sector_tag = f"s{int(sector):04d}"
    tic_tag    = f"{int(tic):016d}"

    # ---- parse cadence into a 4-digit seconds tag (or wildcard) ----
    def _cad_tag(c):
        if c is None:
            return "*"
        if isinstance(c, str):
            s = c.lower().replace(" ", "")
            if s in {"2min", "2m","2 minute","short","120s","120"}:
                return "0120"
            if s in {"20s", "20sec","20 second","fast","20"}:
                return "0020"
            if s.endswith("s"):
                s = s[:-1]
            try:
                return f"{int(float(s)):04d}"
            except Exception:
                return "*"
        # numeric
        return f"{int(c):04d}"

    cad_tag = _cad_tag(cadence)

    # that single character before `_tp` is often 's' → match any single char
    inst_flag = "?"

    suffixes = ["_tp.fits"]
    if include_gz:
        suffixes.append("_tp.fits.gz")

    patterns = [f"tess*-{sector_tag}-{tic_tag}-{cad_tag}-{inst_flag}{suf}"
                for suf in suffixes]

    hits: List[Path] = []
    for pat in patterns:
        hits.extend(root.rglob(pat))

    # fallback: if you asked for a specific cadence and found nothing, retry with wildcard
    if not hits and cad_tag != "*":
        for suf in suffixes:
            pat = f"tess*-{sector_tag}-{tic_tag}-*-{inst_flag}{suf}"
            hits.extend(root.rglob(pat))

    # unique + sorted for stability
    result = sorted({h.resolve() for h in hits})
    return result[0]




from pathlib import Path
import shutil, os
def _flatten_to_cache(df, cache_root, product_tag, tic_id=None, shard_by_tic=False):
    """
    Move files downloaded by `lksearch` into a cache/mastDownload directory.

    Parameters
    ----------
    df : pandas.DataFrame
        The dataframe returned by `TESSSearch.download`
        (must contain a 'Local Path' column).
    cache_root : Path or str
        e.g.  /…/cache/mastDownload
    product_tag : {'TESSCut', 'TESS'}
        Pick 'TESSCut' for FFI cut-outs, 'TESS' for 2-min / 20-s TPFs.
    tic_id : int or str, optional
        TIC identifier for the target being downloaded. REQUIRED if
        ``shard_by_tic=True``.
    shard_by_tic : bool, default False
        If True (opt-in, non-default), files are stored under an extra
        per-target subdirectory: ``cache_root/product_tag/TIC_{tic_id}/``.
        A single target star will only ever produce a handful of cached
        files, so this keeps every directory's file count trivially low
        regardless of total survey size. If False (default), behavior is
        unchanged: all files land flat in ``cache_root/product_tag/``.

    Returns
    -------
    pandas.DataFrame
        The input ``df`` with ``'Local Path'`` updated to point at the
        (possibly sharded) cache location.

    Raises
    ------
    ValueError
        If ``shard_by_tic=True`` and ``tic_id`` is not provided.
    """    
    from pathlib import Path
    import shutil, os
    
    cache_root = Path(cache_root).expanduser().resolve()
    
    if shard_by_tic:
        if tic_id is None:
            raise ValueError(
                "_flatten_to_cache: shard_by_tic=True requires tic_id to be provided."
            )
        tic_str = f"TIC_{tic_id}"
        target_dir = cache_root / product_tag / tic_str
    else:
        target_dir = cache_root / product_tag  # flat, unchanged default behavior
    
    target_dir.mkdir(parents=True, exist_ok=True)

    new_paths = []
    for path_str in df['Local Path']:
        src = Path(path_str).expanduser().resolve()
        dst = target_dir / src.name           # flat!

        if dst.exists():
            # the file is already cached ; remove the redundant download
            try:
                src.unlink()                  # just delete the duplicate
            except Exception:
                pass                          # not fatal
        else:
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(src), dst)

        new_paths.append(str(dst))
        # ── Clean up .zip files in the same directory as the source ──
        # lksearch downloads a .zip, extracts the .fits, but never deletes
        # the .zip. The .fits has already been moved above; now remove any
        # .zip siblings so the parent directory can actually be rmdir'd.
        src_parent = src.parent
        if src_parent.exists():
            try:
                for entry in src_parent.iterdir():
                    if entry.is_file() and entry.suffix == '.zip':
                        try:
                            entry.unlink()
                        except Exception:
                            pass
            except Exception:
                pass

        # tidy up now-empty auto-generated directories (optional)
        try:
            src.parent.rmdir()                # only works if empty
        except OSError:
            pass

    df['Local Path'] = new_paths             # point at the flat cache
    
    # -----------------------------------------------------------
    #  Clean up any now-empty “mastDownload/” directory tree
    # -----------------------------------------------------------
    mast_dir = (cache_root / "mastDownload").resolve()
    if mast_dir.exists():
        try:
            # Walk from the leaves upward, removing empty dirs
            for root, dirs, files in os.walk(mast_dir, topdown=False):
                # Remove stale .zip files first
                for f in files:
                    if f.endswith('.zip'):
                        try:
                            os.remove(os.path.join(root, f))
                        except Exception:
                            pass
                # Then try to remove empty directories
                for d in dirs:
                    try:
                        Path(root, d).rmdir()
                    except OSError:
                        pass
            mast_dir.rmdir()                    # remove mastDownload/ itself
        except OSError:
            # Something inside wasn’t empty or was in use – just leave it
            pass
    return df

def _ensure_tesscut_dirs(downloadpath, tic_id=None, shard_by_tic=False):
    """
    Make sure astroquery's expected dirs exist under the cache tree.
    Avoids FileNotFoundError for .../mastDownload/TESSCut/tesscut_*.zip
    Parameters
    ----------
    dlroot_path : str
        Download root path.
    tic_id : int or str, optional
        TIC identifier. REQUIRED if ``shard_by_tic=True``.
    shard_by_tic : bool, default False
        If True, creates ``TESSCut/TIC_{tic_id}/`` and
        ``mastDownload/TESSCut/TIC_{tic_id}/`` instead of the flat
        defaults. Opt-in only; default behavior (flat) is unchanged.

    Returns
    -------
    str
        The resolved base path.

    Raises
    ------
    ValueError
        If ``shard_by_tic=True`` and ``tic_id`` is not provided.
    """
    from pathlib import Path
    base = Path(downloadpath).expanduser().resolve()
    # keep this in sync with how astroquery builds paths
    if shard_by_tic:
        if tic_id is None:
            raise ValueError(
                "_ensure_tesscut_dirs: shard_by_tic=True requires tic_id."
            )
        tic_str = f"TIC_{tic_id}"        
        (base / "mastDownload" / "TESSCut" / tic_str).mkdir(parents=True, exist_ok=True)
        (base / "TESSCut" / tic_str).mkdir(parents=True, exist_ok=True)
    else:
        (base / "mastDownload" / "TESSCut").mkdir(parents=True, exist_ok=True)
        (base / "TESSCut").mkdir(parents=True, exist_ok=True)

    return str(base)

