def _get_cached_fits(
    cache_root,
    *,
    product_tag,
    sector,
    camera,
    ccd,
    size,
    target_coord,
    tic_id=None,
    shard_by_tic=False,
    migrate_flat_to_sharded=True,
    migrate_sharded_to_flat=True,
    tol=1*u.arcsec,
):
    """
    Fast lookup of a cached TESScut FITS using deterministic paths first,
    then a tiny per-key SQLite index to avoid directory-wide scans.

    Supports two cache layouts and lazy bidirectional migration between them:

    **Flat layout** (default, ``shard_by_tic=False``)::

        cache_root/product_tag/tess-s0003-3-4_68.41_-51.95_11x11_astrocut.fits

    **Sharded layout** (``shard_by_tic=True``)::

        cache_root/product_tag/TIC_259377017/tess-s0003-3-4_68.41_-51.95_11x11_astrocut.fits

    Migration behavior:

    - ``shard_by_tic=True`` + ``migrate_flat_to_sharded=True``: if a file is
      found in the flat directory, it is moved into the per-TIC subdirectory
      before returning. This lazily migrates a legacy flat cache into the
      sharded layout as targets are accessed.
    - ``shard_by_tic=False`` + ``migrate_sharded_to_flat=True``: if a file is
      found in a per-TIC subdirectory (from a previous sharded run), it is
      moved back into the flat directory before returning. This lazily
      flattens a sharded cache if the user turns sharding off.

    File name pattern (examples)::

      tess-s0003-3-4_68.415501_-51.956232_11x11_astrocut.fits
      tess-s0021-2-1_123.456789_-02.345678_11x11_astrocut.fits

    Strategy
    --------
    1) Try to synthesise the exact filename(s) from inputs and check
       ``Path.exists()`` with a few common RA/Dec string formats (no
       directory listing).
    2) If not found, use (or build once) a *scoped* SQLite index for this
       (sector, camera, ccd, size) tuple and query only those entries within
       a small RA/Dec bounding box; confirm with ``SkyCoord.separation < tol``.

    Parameters
    ----------
    cache_root : str or os.PathLike
        Root of your cache (the directory containing ``product_tag/``).
    product_tag : {'TESSCut', 'TESS'}
        Subdirectory name holding the files.
    sector : int
        TESS sector number.
    camera : int
        TESS camera number.
    ccd : int
        TESS CCD number.
    size : int
        Cutout size (pixels).
    target_coord : astropy.coordinates.SkyCoord
        Target celestial coordinate to match within ``tol``.
    tic_id : int or str, optional
        TIC identifier. Required if ``shard_by_tic=True``. Also used when
        ``shard_by_tic=False`` and ``migrate_sharded_to_flat=True`` to know
        which per-TIC subdirectory to check as a fallback.
    shard_by_tic : bool, default False
        If True, search the per-TIC subdirectory first. Default preserves
        flat-only lookup (unchanged behavior).
    migrate_flat_to_sharded : bool, default True
        If True and ``shard_by_tic=True``, a file found in the flat
        directory is moved into the per-TIC subdirectory before returning.
    migrate_sharded_to_flat : bool, default True
        If True and ``shard_by_tic=False`` and ``tic_id`` is provided, a
        file found in the per-TIC subdirectory is moved back to the flat
        directory before returning.
    tol : astropy Quantity (angle), default 1 arcsec
        Maximum separation allowed between filename RA/Dec and
        ``target_coord``.

    Returns
    -------
    pathlib.Path or None
        Path to the cached FITS if a *unique* match is found; else None.

    Notes
    -----
    - This function never performs a full directory glob. The only time it
      scans filenames is when seeding the per-key index (and then only files
      matching the tight prefix/suffix for the given (sector,camera,ccd,size)).
    - The index lives at: ``<search_dir>/.tess_index.sqlite``
    - When a file is migrated between directories, the SQLite index in the
      source directory is NOT updated (the stale entry points at a now-missing
      file). The next lookup will miss on the stale entry's ``Path.exists()``
      check and fall through to Tier A in the correct directory, so this is
      self-healing with no correctness impact.

    Examples
    --------
    >>> from astropy.coordinates import SkyCoord
    >>> import astropy.units as u
    >>> sc = SkyCoord(ra=68.415501*u.deg, dec=-51.956232*u.deg)
    >>> # Default flat lookup (unchanged behavior):
    >>> result = _get_cached_fits(
    ...     '/path/cache', product_tag='TESSCut',
    ...     sector=3, camera=3, ccd=4, size=11, target_coord=sc)
    >>> # Sharded lookup with flat-to-sharded migration:
    >>> result = _get_cached_fits(
    ...     '/path/cache', product_tag='TESSCut',
    ...     sector=3, camera=3, ccd=4, size=11, target_coord=sc,
    ...     tic_id=259377017, shard_by_tic=True)
    >>> # Flat lookup with sharded-to-flat migration (reverting to flat):
    >>> result = _get_cached_fits(
    ...     '/path/cache', product_tag='TESSCut',
    ...     sector=3, camera=3, ccd=4, size=11, target_coord=sc,
    ...     tic_id=259377017, shard_by_tic=False, migrate_sharded_to_flat=True)
    """
    import os
    import sqlite3
    import shutil
    from pathlib import Path
    import re
    import math
    import astropy.units as u
    from astropy.coordinates import SkyCoord

    cache_root = Path(cache_root).expanduser().resolve()
    flat_dir = cache_root / str(product_tag)

    # Determine the sharded directory (may or may not exist on disk).
    # Needed for both forward and reverse migration.
    if tic_id is not None:
        tic_str = f"TIC_{tic_id}"
        sharded_dir = cache_root / str(product_tag) / tic_str
    else:
        sharded_dir = None

    # Build the ordered list of directories to search.
    if shard_by_tic and sharded_dir is not None:
        # Sharding ON: check sharded first, then flat for migration
        sharded_dir.mkdir(parents=True, exist_ok=True)
        if migrate_flat_to_sharded:
            search_dirs = [sharded_dir, flat_dir]
        else:
            search_dirs = [sharded_dir]
    else:
        # Sharding OFF: check flat first, then sharded for reverse migration
        if migrate_sharded_to_flat and sharded_dir is not None and sharded_dir.exists():
            search_dirs = [flat_dir, sharded_dir]
        else:
            search_dirs = [flat_dir]

    # ── RA/Dec candidate string generation (shared across all search dirs) ──

    sector_tag = f"s{int(sector):04d}"
    prefix = f"tess-{sector_tag}-{int(camera)}-{int(ccd)}_"
    suffix = f"_{int(size)}x{int(size)}_astrocut.fits"

    def _fmt_half_up(x: float, nd: int) -> str:
        from decimal import Decimal, ROUND_HALF_UP, getcontext
        getcontext().prec = 16
        q = Decimal(10) ** -nd
        return str(Decimal(str(x)).quantize(q, rounding=ROUND_HALF_UP))

    ra_deg = float(target_coord.ra.deg)
    dec_deg = float(target_coord.dec.deg)

    def _cands_1axis(x: float):
        vals = []
        for nd in (6, 7, 5):
            try:
                vals.append(f"{x:.{nd}f}")
            except Exception:
                pass
            try:
                vals.append(_fmt_half_up(x, nd))
            except Exception:
                pass
            try:
                s = f"{x:.{nd+3}f}"
                dot = s.find(".")
                if dot >= 0:
                    vals.append(s[:dot + 1 + nd])
            except Exception:
                pass
        seen, uniques = set(), []
        for v in vals:
            if v not in seen:
                seen.add(v)
                uniques.append(v)
        return uniques

    ra_strs = _cands_1axis(ra_deg)
    dec_strs = _cands_1axis(dec_deg)

    # ── Helper: search one directory using Tier A + Tier B ──────────────────

    def _search_one_dir(tag_dir):
        """
        Search a single directory for a matching cached FITS file.
        Returns Path if found, None otherwise. Does not modify the filesystem.
        """
        if not tag_dir.exists():
            return None

        # ── Tier A: deterministic filename candidates ──
        for ra_s in ra_strs:
            for dec_s in dec_strs:
                cand = tag_dir / f"{prefix}{ra_s}_{dec_s}{suffix}"
                if cand.exists():
                    return cand

        # ── Tier B: SQLite index lookup ──
        db_path = tag_dir / ".tess_index.sqlite"
        need_seed = False

        if not db_path.exists():
            need_seed = True
            try:
                with sqlite3.connect(str(db_path)) as con:
                    con.execute(
                        "CREATE TABLE IF NOT EXISTS files ("
                        " sector INTEGER, camera INTEGER, ccd INTEGER,"
                        " size INTEGER, ra REAL, dec REAL,"
                        " path TEXT PRIMARY KEY)"
                    )
                    con.execute(
                        "CREATE INDEX IF NOT EXISTS idx_key "
                        "ON files (sector, camera, ccd, size)"
                    )
                    con.commit()
            except Exception:
                return None

        def _key_has_rows(con) -> bool:
            cur = con.execute(
                "SELECT 1 FROM files WHERE sector=? "
                "AND camera=? AND ccd=? AND size=? LIMIT 1",
                (int(sector), int(camera), int(ccd), int(size)),
            )
            return cur.fetchone() is not None

        def _seed_key(con):
            rx = re.compile(
                rf"^tess-{re.escape(sector_tag)}-{int(camera)}-{int(ccd)}_"
                rf"([+-]?\d+(?:\.\d+)?)_([+-]?\d+(?:\.\d+)?)_"
                rf"{int(size)}x{int(size)}_astrocut\.fits$"
            )
            added = 0
            try:
                with os.scandir(tag_dir) as it:
                    batch = []
                    for de in it:
                        name = de.name
                        if not name.startswith(prefix) or not name.endswith(suffix):
                            continue
                        m = rx.match(name)
                        if not m:
                            continue
                        ra_f, dec_f = map(float, m.groups())
                        full_path = str(tag_dir / name)
                        batch.append((
                            int(sector), int(camera), int(ccd),
                            int(size), ra_f, dec_f, full_path,
                        ))
                        if len(batch) >= 2000:
                            con.executemany(
                                "INSERT OR IGNORE INTO files "
                                "VALUES (?,?,?,?,?,?,?)", batch
                            )
                            con.commit()
                            added += len(batch)
                            batch.clear()
                    if batch:
                        con.executemany(
                            "INSERT OR IGNORE INTO files "
                            "VALUES (?,?,?,?,?,?,?)", batch
                        )
                        con.commit()
                        added += len(batch)
            except Exception:
                return 0
            return added

        rows = []
        try:
            with sqlite3.connect(str(db_path)) as con:
                if need_seed or not _key_has_rows(con):
                    _seed_key(con)

                tol_deg = float(tol.to(u.deg).value)
                ra0 = float(target_coord.ra.deg)
                dec0 = float(target_coord.dec.deg)
                ra_min = ra0 - tol_deg
                ra_max = ra0 + tol_deg
                if ra_min < 0.0:
                    ra_min += 360.0
                if ra_max >= 360.0:
                    ra_max -= 360.0

                if ra_min <= ra_max:
                    cur = con.execute(
                        "SELECT ra, dec, path FROM files "
                        "WHERE sector=? AND camera=? AND ccd=? AND size=? "
                        "AND ra BETWEEN ? AND ? AND dec BETWEEN ? AND ?",
                        (int(sector), int(camera), int(ccd), int(size),
                         ra_min, ra_max, dec0 - tol_deg, dec0 + tol_deg),
                    )
                    rows = cur.fetchall()
                else:
                    cur1 = con.execute(
                        "SELECT ra, dec, path FROM files "
                        "WHERE sector=? AND camera=? AND ccd=? AND size=? "
                        "AND ra >= ? AND dec BETWEEN ? AND ?",
                        (int(sector), int(camera), int(ccd), int(size),
                         ra_min, dec0 - tol_deg, dec0 + tol_deg),
                    )
                    cur2 = con.execute(
                        "SELECT ra, dec, path FROM files "
                        "WHERE sector=? AND camera=? AND ccd=? AND size=? "
                        "AND ra <= ? AND dec BETWEEN ? AND ?",
                        (int(sector), int(camera), int(ccd), int(size),
                         ra_max, dec0 - tol_deg, dec0 + tol_deg),
                    )
                    rows = cur1.fetchall() + cur2.fetchall()
        except Exception:
            rows = []

        if not rows:
            return None

        target = SkyCoord(ra=float(target_coord.ra.deg) * u.deg,
                          dec=float(target_coord.dec.deg) * u.deg)
        matches = []
        for ra_f, dec_f, p in rows:
            cand_coord = SkyCoord(ra=float(ra_f) * u.deg,
                                  dec=float(dec_f) * u.deg)
            if target.separation(cand_coord) < tol and Path(p).exists():
                matches.append(Path(p))

        if len(matches) == 1:
            return matches[0]
        return None

    # ── Main search loop across directories ─────────────────────────────────

    for search_dir in search_dirs:
        found = _search_one_dir(search_dir)

        if found is None:
            continue

        found_parent = found.parent.resolve()

        # ── Case 1: shard_by_tic=True, file found in flat dir ──
        # Migrate flat -> sharded
        if (shard_by_tic
                and sharded_dir is not None
                and migrate_flat_to_sharded
                and found_parent == flat_dir.resolve()):
            sharded_dir.mkdir(parents=True, exist_ok=True)
            dst = sharded_dir / found.name
            if not dst.exists():
                try:
                    shutil.move(str(found), str(dst))
                    found = dst
                except Exception:
                    pass  # move failed; return from flat location
            else:
                # Already in sharded dir (race guard); remove flat copy
                try:
                    found.unlink()
                except Exception:
                    pass
                found = dst

        # ── Case 2: shard_by_tic=False, file found in sharded dir ──
        # Migrate sharded -> flat
        elif (not shard_by_tic
                and sharded_dir is not None
                and migrate_sharded_to_flat
                and found_parent == sharded_dir.resolve()):
            flat_dir.mkdir(parents=True, exist_ok=True)
            dst = flat_dir / found.name
            if not dst.exists():
                try:
                    shutil.move(str(found), str(dst))
                    found = dst
                except Exception:
                    pass  # move failed; return from sharded location
            else:
                # Already in flat dir (race guard); remove sharded copy
                try:
                    found.unlink()
                except Exception:
                    pass
                found = dst

            # Try to remove the now-empty TIC subdirectory
            try:
                sharded_dir.rmdir()  # only succeeds if empty
            except OSError:
                pass

        return found

    return None

def _cache_root_from_settings(default_settings):
    """
    Resolve the canonical cache root (your existing cache path).
    All cache activity (TESScut/TPF/DSS) uses this path.
    """
    from pathlib import Path
    root = Path(default_settings['downloadpath']).expanduser().resolve()
    return root  # Path

def safe_cleanup_cache(default_settings, tic_id=None,
                       remove_tesscut=True, 
                       remove_tpf=False, verbose=False):
    """
    Best-effort cleanup of files under the ONE cache root indicated by default_settings.
    Mirrors your old behavior but without hardcoded /mnt/... paths.
    When ``shard_cache_by_tic`` is enabled and ``tic_id`` is provided,
    only cleans that target's subdirectory. Otherwise cleans the flat
    directory as before.
    """
    from pathlib import Path
    root = _cache_root_from_settings(default_settings)
    shard = bool(default_settings.get('shard_cache_by_tic', False))

    targets = []
    if remove_tesscut:
        base = root / "TESSCut"
        if shard and tic_id is not None:
            tic_str = f"TIC_{tic_id}"
            base = base / tic_str
        targets.append(base)
    if remove_tpf:
        base = root / "TESS"
        if shard and tic_id is not None:
            tic_str = f"TIC_{tic_id}"
            base = base / tic_str
        targets.append(base)

    for base in targets:
        try:
            if base.exists():
                # only remove files, not directories (matches your intent)
                for p in base.rglob("*"):
                    try:
                        if p.is_file():
                            p.unlink()
                    except Exception:
                        pass
            else:
                if verbose:
                    print(f"[cleanup] cache subdir missing → {base}")
        except Exception as e:
            if verbose:
                print(f"[cleanup] skipping {base} → {e}")

# -------------------------------------------------------------------------
# ----------------- cluster-robust helpers (single copy) -----------------
def _wait_for_paths(paths, timeout: float = 0.5, poll: float = 0.05, stable_reads: int = 2):
    """
    Wait until each path in `paths` exists and has stable size for `stable_reads` polls.
    Early-exits as soon as condition is met for any path (you'll open just one).
    Returns True if any path stabilized; False otherwise.
    """
    import os, time
    deadline = time.time() + float(timeout)
    stable_count = {p: 0 for p in paths}

    # fast path: if file already exists and size > 0, confirm once more
    for p in list(paths):
        if os.path.isfile(p) and os.path.getsize(p) > 0:
            stable_count[p] = 1

    last_sizes = {p: (os.path.getsize(p) if os.path.exists(p) else -1) for p in paths}

    while time.time() < deadline:
        any_stable = False
        for p in paths:
            if not os.path.isfile(p):
                stable_count[p] = 0
                continue
            sz = os.path.getsize(p)
            if sz > 0 and sz == last_sizes.get(p, -2):
                stable_count[p] += 1
            else:
                stable_count[p] = 0
            last_sizes[p] = sz
            if stable_count[p] >= stable_reads:
                any_stable = True
        if any_stable:
            return True
        time.sleep(poll)
    return False


def _cache_lock_name(*, product_tag: str, sector: int | None = None,
                     camera: int | None = None, ccd: int | None = None,
                     tic_id: int | str | None = None) -> str:
    """
    Build a narrow-scope lock filename so only jobs touching the same
    resource serialize. Examples:
      flatten_TESSCut_s0001_cam1_ccd4.lock
      flatten_TESS_s0001_tic_24195569.lock
      flatten_TESSCut_generic.lock  (fallback)
    """
    parts = [f"flatten_{product_tag}"]
    if sector is not None:
        parts.append(f"s{int(sector):04d}")
    if camera is not None and ccd is not None:
        parts.append(f"cam{int(camera)}")
        parts.append(f"ccd{int(ccd)}")
    elif tic_id is not None:
        parts.append(f"tic_{tic_id}")
    if len(parts) == 1:
        parts.append("generic")
    return "_".join(parts) + ".lock"


class _CacheLock:
    """
    Best-effort file lock based on creating a lockfile.
    Scope is controlled by the lock name you pass in.
    Lock file is removed on exit; failures to remove are ignored.
    """
    def __init__(self, cache_root: str, name: str, max_wait_s: float = 8.0):
        import os
        self.lock_path = os.path.join(cache_root, name)
        self._max_wait_s = float(max_wait_s)

    def __enter__(self):
        import os, time
        deadline = time.time() + self._max_wait_s
        while True:
            try:
                fd = os.open(self.lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                os.close(fd)
                return self
            except FileExistsError:
                if time.time() >= deadline:
                    # best-effort: proceed without lock after short wait
                    return self
                time.sleep(0.1)

    def __exit__(self, exc_type, exc, tb):
        import os
        try:
            os.remove(self.lock_path)
        except Exception:
            pass

def _sec_str(sector):
    """Safe sector string for logs; won’t blow up on numpy/list types."""
    import numpy as np
    try:
        return str(int(np.asarray(sector).reshape(-1)[0]))
    except Exception:
        return str(sector)
    
class TesscutCounterSemaphore: #NEW, November 5th, 2025
    """
    Cross-process semaphore using a single integer counter file.

    Across all jobs that share `cache_root`, at most `max_slots` code blocks
    guarded by this context manager will run at the same time.

    Implementation
    --------------
    - Counter file: `<cache_root>/.tesscut_counter` storing an integer.
    - Lock file: `<cache_root>/tesscut_counter.lock` managed by `_CacheLock`.

    Usage
    -----
    with TesscutCounterSemaphore(cache_root=downloadpath, max_slots=4):
        # do TESScut / lksearch calls here

    Parameters
    ----------
    cache_root : str or Path
        Shared directory visible to all SLURM/disBatch jobs.
    max_slots : int, default 4
        Maximum simultaneous holders (active TESScut callers).
    poll_interval : float, default 0.5
        Seconds between retries when no slot is available.
    max_wait : float or None, default None
        Maximum number of seconds to wait for a slot. If None, wait forever.
    """

    def __init__(
        self,
        cache_root,
        max_slots: int = 4,
        poll_interval: float = 0.5,
        max_wait: float | None = None,
    ) -> None:
        from pathlib import Path
        self.cache_root = Path(cache_root).expanduser().resolve()
        self.counter_path = self.cache_root / ".tesscut_counter"
        self.lock_name = "tesscut_counter.lock"

        self.max_slots = int(max_slots)
        self.poll_interval = float(poll_interval)
        self.max_wait = max_wait if max_wait is not None else None

    def _read_count(self) -> int:
        try:
            txt = self.counter_path.read_text().strip()
            return int(txt) if txt else 0
        except FileNotFoundError:
            return 0
        except Exception:
            # If file is corrupt, reset to 0 (conservative)
            return 0

    def _write_count(self, value: int) -> None:
        value = max(0, int(value))
        self.counter_path.write_text(f"{value}\n")

    def __enter__(self):
        import time as _time
        deadline = None if self.max_wait is None else (_time.time() + self.max_wait)

        while True:
            # Serialize counter updates via _CacheLock
            with _CacheLock(str(self.cache_root), name=self.lock_name):
                cur = self._read_count()
                if cur < self.max_slots:
                    self._write_count(cur + 1)
                    return self  # acquired a slot

            if deadline is not None and _time.time() >= deadline:
                raise TimeoutError(
                    f"Timed out waiting for TESScut slot "
                    f"(max_slots={self.max_slots}, cur={cur})."
                )

            _time.sleep(self.poll_interval)

    def __exit__(self, exc_type, exc, tb) -> None:
        # Decrement counter under lock; best-effort only.
        try:
            with _CacheLock(str(self.cache_root), name=self.lock_name):
                cur = self._read_count()
                self._write_count(cur - 1)
        except Exception:
            pass
        
def current_tesscut_active(cache_root) -> int: #NEW, November 5th, 2025
    """
    Return approximate number of active TESScut/TESSSearch slots.

    This just reads the shared .tesscut_counter file.
    """
    from pathlib import Path
    path = Path(cache_root).expanduser().resolve() / ".tesscut_counter"
    try:
        txt = path.read_text().strip()
        return int(txt) if txt else 0
    except FileNotFoundError:
        return 0
    except Exception:
        return 0
        
    
    
    
    
def tesssearch_with_radius_growth(
    ID: int,
    *,
    Sector: int,
    exptime: int,
    ffi_or_tpf: str,
    start_pixels: int = 2,
    step_pixels: int = 3,
    max_pixels: int = 32,
    attempts: int | None = None,
    verbose: bool = False,
    search_fn=None,
) -> tuple:
    """
    Perform lksearch.TESSSearch with an expanding search radius when the initial
    sector-constrained query raises a SearchError or yields no matching rows.
    
    Two operating modes:
    1) Backward-compatible (default): keep widening until `n_pix <= max_pixels`.
    2) LIMITED attempts: set `attempts` to an integer (e.g., 2) to try a fixed
       sequence: start at `start_pixels`, then +`step_pixels` exactly
       `attempts` times (stop after success or after attempts exhausted).

    Parameters
    ----------
    ID : int
        TIC identifier (integer). The function will pass target=f"TIC {ID}".
    Sector : int
        TESS Sector to filter on.
    exptime : int
        Exposure time (seconds). Used to subselect rows (e.g., 120, 600, 1800).
    ffi_or_tpf : {"FFI","TPF"}
        Controls whether to read `.tesscut` (FFI) or `.cubedata` (TPF) table.
    start_pixels : int, default 2
        Initial search radius in TESS pixels (1 px ≈ 21 arcsec).
    step_pixels : int, default 3
        Increment (in pixels) to add on each retry.
    max_pixels : int, default 32
        Abort if radius exceeds this many pixels.
    attempts : int or None, default None
        If set (e.g., 2), try exactly this many radii:
            n = start_pixels + i*step_pixels  for i in [0..attempts-1]
        If None, use the original while-loop up to `max_pixels`.        
    verbose : bool, default False
        If True, prints the radius used on each attempt.
    search_fn : callable, optional
        Dependency injection for testing; defaults to lksearch.TESSSearch.

    Returns
    -------
    (result, result_table, used_pixels)
        The lksearch result object; the selected table (tesscut/cubedata)
        filtered to `exptime`; and the radius used (pixels).

    Raises
    ------
    SearchError
        If no results after the configured attempts / max radius.
    ValueError
        If `ffi_or_tpf` is not one of {"FFI","TPF"}.

    Examples
    --------
    >>> # Minimal offline doctest using a fake lksearch result
    >>> class FakeTable(list): pass
    >>> class FakeResult:
    ...     def __init__(self, sectors, exptimes):
    ...         self._rows = list(zip(sectors, exptimes))
    ...         self.colnames = {"sector", "exptime"}
    ...     def __len__(self): return len(self._rows)
    ...     def __getitem__(self, mask):
    ...         new = FakeResult([], [])
    ...         new._rows = [r for r, m in zip(self._rows, mask) if m]
    ...         new.colnames = self.colnames
    ...         return new
    ...     @property
    ...     def sector(self):
    ...         import numpy as np
    ...         return np.array([s for s, _ in self._rows])
    ...     @property
    ...     def exptime(self):
    ...         import numpy as np
    ...         return np.array([e for _, e in self._rows])
    ...     @property
    ...     def tesscut(self):  return FakeTable(self._rows)
    ...     @property
    ...     def cubedata(self): return FakeTable(self._rows)
    >>> calls = {"n": 0}
    >>> def fake_search(*, target, search_radius, exptime, sector=None):
    ...         calls["n"] += 1
    ...         if calls["n"] < 3:
    ...             from lksearch.utils import SearchError
    ...             raise SearchError("simulated")
    ...         px = int(round(search_radius.to_value(unit='arcsec')/21.0))
    ...         return FakeResult([42, 42], [1800, 1800]) if px >= 8 else FakeResult([], [])
    >>> res, tbl, used = tesssearch_with_radius_growth(
    ...     123456789, Sector=42, exptime=1800, ffi_or_tpf="FFI",
    ...     start_pixels=2, step_pixels=3, max_pixels=20, verbose=False,
    ...     search_fn=fake_search,
    ... )
    >>> isinstance(tbl, list) and used >= 8
    True
    """
    import astropy.units as u
    from lksearch.utils import SearchError as LKSearchError
    import lksearch as _lk

    if ffi_or_tpf not in {"FFI", "TPF"}:
        raise ValueError(f"ffi_or_tpf must be 'FFI' or 'TPF', got {ffi_or_tpf!r}")
    if search_fn is None:
        search_fn = _lk.TESSSearch

    def _make_table(res, ffi_or_tpf):
        try:
            res_exp = res[res.exptime == exptime]
        except Exception:
            res_exp = res
        return res_exp.tesscut if ffi_or_tpf == "FFI" else res_exp.cubedata
    
    def _attempt(n_pix: float):
        radius = float(n_pix) * 21.0 * u.arcsec
        if verbose:
            print(f"[lksearch] trying radius {n_pix:.2f} px (~{float(n_pix)*21:.1f}\" )")
        try:
            # Try passing sector if the backend supports it; otherwise omit.
            try:
                res = search_fn(target=f"TIC {ID}", search_radius=radius, exptime=exptime, sector=Sector)
            except TypeError:
                res = search_fn(target=f"TIC {ID}", search_radius=radius, exptime=exptime)
        except LKSearchError:
            return None, None

        # Post-filter to requested Sector if present
        try:
            if hasattr(res, "colnames") and ("sector" in getattr(res, "colnames", [])):
                res = res[res["sector"] == Sector]
            else:
                res = res[res.sector == Sector]
        except Exception:
            # Fall through; emptiness check will govern
            pass

        tbl = _make_table(res,ffi_or_tpf)
        try:
            if len(tbl) > 0:
                return res, tbl
        except Exception:
            pass
        return None, None
    
    
    # ---- Mode 1: limited attempts (e.g., 2 tries: 2 px, then 11 px)
    if isinstance(attempts, int) and attempts >= 1:
        n_pix = float(start_pixels)
        for i in range(attempts):
            res, tbl = _attempt(n_pix)
            if res is not None and tbl is not None:
                return res, tbl, n_pix
            n_pix = n_pix + float(step_pixels)
        raise LKSearchError(
            f"No TESSSearch results for TIC {ID} (Sector {Sector}, exptime={exptime}) "
            f"after {attempts} attempts up to radius {n_pix - float(step_pixels):.2f} px."
        )
        
    # ---- Mode 2: backward-compatible while-loop up to max_pixels
    n_pix = float(start_pixels)
    while n_pix <= float(max_pixels):
        res, tbl = _attempt(n_pix)
        if res is not None and tbl is not None:
            return res, tbl, n_pix
        n_pix += float(step_pixels)
        
    raise LKSearchError(
        f"No TESSSearch results for TIC {ID} (Sector {Sector}, exptime={exptime}) "
        f"up to radius {max_pixels:.2f} px." )
    

    n_pix = int(start_pixels)
    while n_pix <= int(max_pixels):
        radius = n_pix * 21 * u.arcsec
        if verbose:
            print(f"[lksearch] trying radius {n_pix} px (~{n_pix*21}\" )")
        try:
            res = search_fn(target=f"TIC {ID}", search_radius=radius, exptime=exptime)
        except LKSearchError:
            n_pix += int(step_pixels)
            continue

        # Post-filter to requested Sector
        try:
            if hasattr(res, "colnames") and ("sector" in getattr(res, "colnames", [])):
                res = res[res["sector"] == Sector]
            else:
                res = res[res.sector == Sector]
        except Exception:
            # If sector filter fails silently, rely on emptiness check next
            pass

        tbl = _make_table(res,ffi_or_TPF)
        try:
            if len(tbl) > 0:
                return res, tbl, n_pix
        except Exception:
            pass

        n_pix += int(step_pixels)

    raise LKSearchError(
        f"No TESSSearch results for TIC {ID} (Sector {Sector}, exptime={exptime}) "
        f"up to radius {max_pixels} px (~{max_pixels*21} arcsec)."
    )

def verify_lc_matches_cutout(
    lc_time,
    cutout_time,
    *,
    atol_days: float = 1.0e-5,
    min_frac: float = 0.9,
) -> dict:
    """
    Check that a light curve's time stamps come from the cutout it was
    extracted from.

    Every light-curve time should equal some cutout time, since extraction
    only removes cadences (quality mask, clipping). A light curve built from
    another sector matches essentially none. Cutout times are shared by every
    star on a CCD, so this check cannot tell two stars on one CCD apart;
    gethdu_lksearch checks position.

    Parameters
    ----------
    lc_time : array-like
        Light-curve times (BTJD).
    cutout_time : array-like
        ``hdu[1].data['TIME']`` of the cutout.
    atol_days : float
        Match tolerance. 1e-5 d is the tolerance the mask-reproduction gate
        used to line up survey and reproduced cadences.
    min_frac : float
        Fraction of light-curve times that must match.

    Returns
    -------
    dict
        ok, n_lc, n_matched, frac_matched, reasons.

    Examples
    --------
    >>> t = np.arange(1842.5, 1868.8, 0.0208333)
    >>> verify_lc_matches_cutout(t[::3], t)["ok"]
    True
    >>> verify_lc_matches_cutout(t + 57.0, t)["frac_matched"]
    0.0
    """
    lt = np.asarray(lc_time, dtype=float)
    lt = lt[np.isfinite(lt)]
    ct = np.asarray(cutout_time, dtype=float)
    ct = np.sort(ct[np.isfinite(ct)])
    if lt.size == 0 or ct.size == 0:
        return {"ok": False, "n_lc": int(lt.size), "n_matched": 0,
                "frac_matched": 0.0, "reasons": ["empty time array"]}
    idx = np.searchsorted(ct, lt)
    lo = ct[np.clip(idx - 1, 0, ct.size - 1)]
    hi = ct[np.clip(idx, 0, ct.size - 1)]
    nearest = np.minimum(np.abs(lt - lo), np.abs(lt - hi))
    n_matched = int(np.sum(nearest <= atol_days))
    frac = float(n_matched) / float(lt.size)
    ok = frac >= min_frac
    reasons = [] if ok else [
        f"only {n_matched}/{lt.size} light-curve times match cutout times "
        f"within {atol_days:g} d (need {min_frac:.0%})"]
    return {"ok": ok, "n_lc": int(lt.size), "n_matched": n_matched,
            "frac_matched": frac, "reasons": reasons}


def verify_written_lc(
    path: str,
    lc_time,
    *,
    atol_days: float = 1.0e-7,
) -> dict:
    """
    Re-read the Time column of a just-written light curve and compare it
    with the times held in memory. Catches a file on disk that is not the
    one this process wrote. A file that is not on disk is noted, not failed.

    Parameters
    ----------
    path : str
        The final_LC.csv just written.
    lc_time : array-like
        Times of the light curve in memory.
    atol_days : float
        Comparison tolerance (CSV round-trip).

    Returns
    -------
    dict
        ok, reasons, notes.

    Examples
    --------
    >>> import os, tempfile
    >>> p = os.path.join(tempfile.mkdtemp(), "lc.csv")
    >>> pd.DataFrame({"Time": [1.0, 2.0, 3.0]}).to_csv(p, index=False)
    >>> verify_written_lc(p, np.array([1.0, 2.0, 3.0]))["ok"]
    True
    >>> verify_written_lc(p, np.array([5.0, 6.0, 7.0]))["ok"]
    False
    """
    if not os.path.isfile(path):
        return {"ok": True, "reasons": [], "notes": [f"{path} not on disk; skipped"]}
    try:
        disk = pd.read_csv(path, usecols=["Time"])["Time"].to_numpy(dtype=float)
    except Exception as exc:
        return {"ok": False, "notes": [],
                "reasons": [f"could not read {path}: {type(exc).__name__}: {exc}"]}
    mem = np.asarray(lc_time, dtype=float)
    if disk.shape != mem.shape:
        return {"ok": False, "notes": [],
                "reasons": [f"rows on disk {disk.size} != in memory {mem.size}"]}
    same = bool(np.allclose(disk, mem, atol=atol_days, rtol=0.0, equal_nan=True))
    return {"ok": same, "notes": [],
            "reasons": [] if same else ["Time column on disk differs from the "
                                        "light curve in memory"]}


def verify_lc_sector_by_time(
    lc_time,
    sector: int,
    *,
    sector_of_time: "Callable[[float], int] | None" = None,
) -> dict:
    """
    Check that a light curve's first and last times fall in the requested
    sector. This is your ``TESS_Sector_observation_check(T0=np.min(...))``
    and ``(T0=np.max(...))`` test, run automatically.

    Fails only if a time maps to a different sector. A time the map cannot
    place (None, or an error) is a note, so a cadence just outside the
    table's orbit edges cannot cause a false failure.

    Parameters
    ----------
    lc_time : array-like
        Light-curve times (BTJD).
    sector : int
        Sector the light curve is labeled with.
    sector_of_time : callable, optional
        Maps a BTJD time to a sector. Default:
        ``TESS_Sector_observation_check(T0=t)``.

    Returns
    -------
    dict
        ok, sectors (first-time and last-time sector), reasons, notes.

    Examples
    --------
    >>> sot = lambda x: 20 if 1842.0 < x < 1869.0 else (22 if 1899.0 < x < 1927.0 else None)
    >>> verify_lc_sector_by_time([1842.51, 1855.0, 1868.80], 20, sector_of_time=sot)["ok"]
    True
    >>> verify_lc_sector_by_time([1899.32, 1926.47], 20, sector_of_time=sot)["reasons"]
    ['light-curve times fall in sector(s) [22, 22], not 20']
    >>> verify_lc_sector_by_time([1841.9, 1868.80], 20, sector_of_time=sot)["notes"]
    ['time check could not place light-curve times ([None, 20])']
    """
    if sector_of_time is None:
        sector_of_time = lambda t: TESS_Sector_observation_check(T0=t)
    t = np.asarray(lc_time, dtype=float)
    t = t[np.isfinite(t)]
    if t.size == 0:
        return {"ok": False, "sectors": [], "notes": [],
                "reasons": ["light curve has no finite times"]}
    got: list = []
    for v in (float(t.min()), float(t.max())):
        try:
            s = sector_of_time(v)
            if isinstance(s, tuple):
                s = s[-1]
            got.append(int(s) if s is not None else None)
        except Exception:
            got.append(None)
    reasons: list = []
    notes: list = []
    if any(s is not None and s != int(sector) for s in got):
        reasons.append(f"light-curve times fall in sector(s) {got}, not {int(sector)}")
    elif any(s is None for s in got):
        notes.append(f"time check could not place light-curve times ({got})")
    return {"ok": not reasons, "sectors": got, "reasons": reasons, "notes": notes}

def verify_cutout_identity(
    header,
    sector: int,
    *,
    ra: float | None = None,
    dec: float | None = None,
    pos_tol_arcsec: float = 21.0,
    expected_camera: int | None = None,
    expected_ccd: int | None = None,
    filename: str | None = None,
    require_position: bool = False,
    times=None,
    sector_of_time: "Callable[[float], int] | None" = None,
) -> dict:
    """
    Check that a cutout (TESScut or TPF) is the requested sector and the
    requested star.

    Sector: header SECTOR must equal ``sector``. Star: the cutout position
    must lie within ``pos_tol_arcsec`` of (ra, dec). The position comes from
    the header (RA_OBJ / DEC_OBJ) or, failing that, from an astrocut file
    name (tess-sSSSS-C-D_<RA>_<Dec>_NxN_astrocut.fits). Optional extras: a
    camera/CCD comparison with tess-point, reported as a note and never a
    failure because edge stars can legitimately differ, and a time check
    that maps cutout times to a sector with ``sector_of_time``.

    TESScut time stamps are shared by every star on a CCD, so no time-based
    check can tell two stars on one CCD apart. Only the position check can.

    Parameters
    ----------
    header : astropy.io.fits.Header
        Primary header, ``hdu[0].header``.
    sector : int
        Sector the caller asked for.
    ra, dec : float, optional
        Target position in degrees. Needed for the position check.
    pos_tol_arcsec : float
        Position tolerance. 21 arcsec is one TESS pixel.
    expected_camera, expected_ccd : int, optional
        tess-point prediction for this sector.
    filename : str, optional
        Path of the opened file, used when the header has no position.
    require_position : bool
        True: a missing position, or missing ra/dec, fails the check.
        False (default, the v1 behavior): a missing position is only noted.
    times : array-like, optional
        ``hdu[1].data['TIME']``.
    sector_of_time : callable, optional
        Maps a BTJD time to a sector number, for example
        ``lambda t: TESS_Sector_observation_check(T0=t)``. Applied to the
        10th and 90th percentile times, which sit inside the two orbits.
        Fails only when it returns a different sector; no answer is a note.

    Returns
    -------
    dict
        ok (bool); hdr_sector, hdr_camera, hdr_ccd (int, -1 if absent);
        sep_arcsec (float or NaN); pos_source ("header", "filename" or
        "none"); time_sectors (list); reasons (failures); notes (checks
        that could not run, and soft disagreements).

    Examples
    --------
    >>> from astropy.io import fits
    >>> h = fits.Header({"SECTOR": 20, "CAMERA": 4, "CCD": 1,
    ...                  "RA_OBJ": 150.0, "DEC_OBJ": -30.0})
    >>> verify_cutout_identity(h, 20, ra=150.0, dec=-30.0)["ok"]
    True
    >>> verify_cutout_identity(h, 22)["reasons"]
    ['header SECTOR 20 != requested 22']
    >>> verify_cutout_identity(h, 20, ra=150.1, dec=-30.0)["reasons"]
    ['cutout position 311.8 arcsec from target (tol 21)']
    >>> verify_cutout_identity(h, 20, expected_camera=4, expected_ccd=2)["notes"]
    ['header camera/CCD 4/1 != tess-point 4/2']
    >>> h2 = fits.Header({"SECTOR": 20})
    >>> f = "/c/tess-s0020-4-1_304.572863_74.273241_11x11_astrocut.fits"
    >>> r = verify_cutout_identity(h2, 20, ra=304.572863, dec=74.273241,
    ...                            filename=f, require_position=True)
    >>> r["ok"], r["pos_source"]
    (True, 'filename')
    >>> verify_cutout_identity(h2, 20, ra=304.572863, dec=74.273241,
    ...                        require_position=True)["ok"]
    False
    >>> t = np.linspace(1842.6, 1868.7, 100)
    >>> sot = lambda x: 20 if x < 1869.0 else 22
    >>> verify_cutout_identity(h, 20, times=t, sector_of_time=sot)["time_sectors"]
    [20, 20]
    >>> verify_cutout_identity(h, 20, times=t + 57.0, sector_of_time=sot)["reasons"]
    ['cutout times fall in sector(s) [22, 22], not 20']
    """
    import os
    import re

    def _int(v) -> int:
        try:
            return int(v)
        except (TypeError, ValueError):
            return -1

    reasons: list = []
    notes: list = []

    hdr_sector = _int(header.get("SECTOR", -1))
    if hdr_sector < 0:
        reasons.append("header has no SECTOR keyword")
    elif hdr_sector != int(sector):
        reasons.append(f"header SECTOR {hdr_sector} != requested {int(sector)}")

    hdr_cam = _int(header.get("CAMERA", -1))
    hdr_ccd = _int(header.get("CCD", -1))
    if (expected_camera is not None and expected_ccd is not None
            and hdr_cam >= 0 and hdr_ccd >= 0
            and (hdr_cam, hdr_ccd) != (int(expected_camera), int(expected_ccd))):
        notes.append(f"header camera/CCD {hdr_cam}/{hdr_ccd} != tess-point "
                     f"{int(expected_camera)}/{int(expected_ccd)}")

    sep = float("nan")
    pos_source = "none"
    ra_c = dec_c = None
    if header.get("RA_OBJ") is not None and header.get("DEC_OBJ") is not None:
        ra_c, dec_c = float(header["RA_OBJ"]), float(header["DEC_OBJ"])
        pos_source = "header"
    elif filename:
        m = re.match(r"^tess-s\d{4}-\d-\d_([-+]?\d+(?:\.\d+)?)_"
                     r"([-+]?\d+(?:\.\d+)?)_\d+x\d+_astrocut\.fits$",
                     os.path.basename(str(filename)))
        if m:
            ra_c, dec_c = float(m.group(1)), float(m.group(2))
            pos_source = "filename"
    if ra is not None and dec is not None:
        if pos_source == "none":
            msg = "no cutout position (no RA_OBJ/DEC_OBJ, no astrocut file name)"
            (reasons if require_position else notes).append(msg)
        else:
            r1, d1, r2, d2 = np.radians([float(ra), float(dec), ra_c, dec_c])
            hav = (np.sin(0.5 * (d2 - d1)) ** 2
                   + np.cos(d1) * np.cos(d2) * np.sin(0.5 * (r2 - r1)) ** 2)
            sep = float(np.degrees(2.0 * np.arcsin(np.sqrt(min(1.0, hav)))) * 3600.0)
            if sep > pos_tol_arcsec:
                reasons.append(f"cutout position {sep:.1f} arcsec from target "
                               f"(tol {pos_tol_arcsec:g})")
    elif require_position:
        reasons.append("target ra/dec not given; position not checked")

    time_sectors: list = []
    if times is not None and sector_of_time is not None:
        t = np.asarray(times, dtype=float)
        t = t[np.isfinite(t)]
        if t.size == 0:
            notes.append("no finite cutout times; time check skipped")
        else:
            for q in (0.1, 0.9):
                try:
                    s = sector_of_time(float(np.quantile(t, q)))
                    if isinstance(s, tuple):
                        s = s[-1]
                    time_sectors.append(int(s) if s is not None else None)
                except Exception:
                    time_sectors.append(None)
            if any(s is not None and s != int(sector) for s in time_sectors):
                reasons.append(f"cutout times fall in sector(s) {time_sectors}, "
                               f"not {int(sector)}")
            elif any(s is None for s in time_sectors):
                notes.append(f"time check could not place cutout times "
                             f"({time_sectors})")

    return {"ok": not reasons, "hdr_sector": hdr_sector, "hdr_camera": hdr_cam,
            "hdr_ccd": hdr_ccd, "sep_arcsec": sep, "pos_source": pos_source,
            "time_sectors": time_sectors, "reasons": reasons, "notes": notes}

def _gethdu_lksearch_unverified(star, ID, Sector, cadence, default_settings):
    """
    Download a single TESS FFI cutout or TPF from MAST via lksearch.

    Implements a two-stage retrieval strategy:

    1. **Cache-first** — uses ``tess_stars2px`` to predict the Camera/CCD
       for the requested sector, then calls ``_get_cached_fits`` to check
       for an existing local FITS file.  If found, opens and returns it
       immediately without any network query.

    2. **TESSSearch fallback** — if no cached file is found, calls
       ``tesssearch_with_radius_growth`` (via a ``TesscutCounterSemaphore``
       that limits concurrent MAST queries to 4) to download the cutout.
       The downloaded file is flattened into the local cache for future runs.

    This function handles a single sector only.  Multi-sector iteration is
    managed by the calling function ``gethdu``.

    Parameters
    ----------
    star : pd.DataFrame
        Single-row stellar catalog entry.  Must contain ``'ra'`` /
        ``'ra_TIC'`` and ``'dec'`` / ``'dec_TIC'`` columns.
    ID : int
        TIC identifier; used in search queries and log messages.
    Sector : int
        Single TESS sector to retrieve.
    cadence : str
        TESS exposure cadence: ``'30 minute'``, ``'10 minute'``,
        ``'2 minute'``, ``'20 second'``, or legacy aliases
        (``'long'``, ``'short'``, ``'fast'``).  Determines whether a
        TESScut FFI (``'FFI'``) or Target Pixel File (``'TPF'``) is
        requested.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``downloadpath``,
        ``cutoutsize``, ``verbose``.

    Returns
    -------
    hdu : fits.HDUList
        Opened FITS HDUList for the requested sector.  Contains
        PrimaryHDU, BinTableHDU (pixel time series), and ImageHDU
        (aperture mask for TPFs).

    Notes
    -----
    Returns ``None`` if TESSSearch fails after the configured attempts or if
    no matching result is found in the search table; the calling ``gethdu``
    loop handles ``None`` entries gracefully by appending ``None`` to its
    output lists.

    The semaphore ``TesscutCounterSemaphore`` limits simultaneous calls to
    4 to stay within MAST's 5-query/second rate limit for TESScut.
    """
    # ------------------------- imports & small helpers -------------------------
    import os
    import time
    import numpy as np
    import astropy.units as u
    from pathlib import Path
    from astropy.io import fits
    from astropy.coordinates import SkyCoord
    from lksearch.utils import SearchError
    import lksearch

#     def _ensure_tesscut_dirs(dlroot_path: str):
#         base = Path(dlroot_path).expanduser().resolve()
#         (base / "mastDownload" / "TESSCut").mkdir(parents=True, exist_ok=True)
#         (base / "TESSCut").mkdir(parents=True, exist_ok=True)  # your code reads from here later
#         return str(base)

    # ----------------------------- unpack settings -----------------------------
    t_func = time.time()
    shard_by_tic = bool(default_settings.get('shard_cache_by_tic', False))
    downloadpath = Path(default_settings['downloadpath']).expanduser().resolve()
    dlroot       = str(downloadpath).rstrip('/')    # mirror your original behavior
    cutoutsize   = int(default_settings['cutoutsize'])
    verbose      = bool(default_settings['verbose'])
    mast_query_attempts = int(default_settings['mast_query_attempts'])
    if verbose:    
        timer(t_func, time.time(), "gethdu_lksearch: unpack settings took:")

    # --------------------------- cadence -> product ----------------------------
    t0 = time.time()
    cadence_map = {
        'long': (30*u.minute , 'FFI'),
        '30 minute': (30*u.minute , 'FFI'),
        '10 minute': (10*u.minute , 'FFI'),
        'short': ( 2*u.minute , 'TPF'),
        '2 minute': ( 2*u.minute , 'TPF'),
        '20 second': (20*u.second, 'TPF'),
        'fast': (20*u.second, 'TPF')
    }
    if cadence not in cadence_map:
        raise ValueError(f"Unrecognised cadence: {cadence!r}")
    exp_u, ffi_or_tpf = cadence_map[cadence]
    exptime     = int(exp_u.to(u.second).value)
    product_tag = "TESSCut" if ffi_or_tpf == 'FFI' else "TESS"
    if verbose:    
        timer(t0, time.time(), "cadence mapping took:")

    # --------------------------- target coordinates ----------------------------
    t0 = time.time()
    ra_col  = 'ra_TIC' if 'ra_TIC' in star.columns else 'ra'
    dec_col = 'dec_TIC' if 'dec_TIC' in star.columns else 'dec'
    tgt_coord = SkyCoord(star[ra_col].iloc[0]*u.deg,
                         star[dec_col].iloc[0]*u.deg)
    if verbose:    
        timer(t0, time.time(), "target coordinate prep took:")

    # ----------------------------- cache-first path ----------------------------
    t0 = time.time()
    from tess_stars2px import tess_stars2px_function_entry as tess_stars2px
    try:
        out = tess_stars2px(ID, tgt_coord.ra.deg, tgt_coord.dec.deg, aberrate=False)
        _, _, _, outSector, outCam, outCcd, *_ = out
        sector_map = dict(zip(outSector, zip(outCam, outCcd)))  # sector -> (cam, ccd)
    except Exception as e:
        sector_map = {}
        if verbose:
            print(f"[cache-first] tess_stars2px failed → {e}")
    if verbose:            
        timer(t0, time.time(), "tess_stars2px (cache-first metadata) took:")

    t0 = time.time()
    sec_list = [Sector] if isinstance(Sector, (int, np.integer)) else list(np.atleast_1d(Sector))
    for sec in sec_list:
        if sec not in sector_map:
            continue
        cam, ccd = sector_map[sec]
        cached = _get_cached_fits(
            downloadpath,
            product_tag=product_tag,
            sector=sec, camera=cam, ccd=ccd,
            size=cutoutsize, target_coord=tgt_coord, 
            tic_id=ID, shard_by_tic=shard_by_tic)
        
        if cached:
            if verbose:
                print(f"found cached FITS → {os.path.join(dlroot, product_tag, cached.name)}")
            # time the early-return case explicitly before returning
            timer(t0, time.time(), "cache-first open took:")
            return fits.open(cached)
    if verbose:        
        timer(t0, time.time(), "cache-first lookup took:")

    # ---------------------- TESSSearch for missing products --------------------
    t0 = time.time()
    n_TESS_pixels = 5
    # Always initialize to avoid UnboundLocalError on rare paths
    result = None
    result_table = None
    #    
    if verbose:
        print(f"[TESScut throttle] active={current_tesscut_active(downloadpath)} max=4")
    with TesscutCounterSemaphore(cache_root=downloadpath, max_slots=4):
        try:
            # Exactly two attempts total: n_TESS_pixels px, then +5.5 px, then stop.
            result, result_table, used_px = tesssearch_with_radius_growth(
                ID,
                Sector=Sector,
                exptime=exptime,
                ffi_or_tpf=("FFI" if ffi_or_tpf == "FFI" else "TPF"),
                start_pixels=n_TESS_pixels,
                step_pixels=5,
                attempts=mast_query_attempts,          # <-- key change: at most two queries
                verbose=verbose,
            )
        except SearchError as e:
            if verbose:
                print(f"[lksearch] TESSSearch failed for TIC {ID} S{Sector}: {e}")
            result = None
            result_table = None

    if verbose:
        timer(t0, time.time(), "TESSSearch query build took:")


    # -------------------------- pick the best table row ------------------------
    t0 = time.time()
    match_index = None
    target_coord = SkyCoord(ra=float(star[ra_col].values[0])*u.deg,
                            dec=float(star[dec_col].values[0])*u.deg)
    # Defensive guard: if still no usable table, bail gracefully
    if result_table is None:
        if verbose:
            print(f"Sector {_sec_str(Sector)}: TESSSearch produced no result_table.")
        if verbose:
            timer(t0, time.time(), "row selection took:")
        return None
    
    for ix in range(len(result_table)):
        try:
            name = result_table['target_name'][ix]
            if str(ID) in str(name):
                match_index = ix
                break
            if "," in str(name):
                try:
                    ra_str, dec_str = [float(x.strip()) for x in str(name).split(",")]
                    row_coord = SkyCoord(ra=ra_str*u.deg, dec=dec_str*u.deg)
                    if target_coord.separation(row_coord) < 1*u.arcsec:
                        match_index = ix
                        break
                except Exception as e:
                    if verbose: 
                        print(f"[{ix}] coord-parse error: {e}")
        except Exception as err:
            if verbose: 
                print(f"[{ix}] row access error: {err}")

    if match_index is None and len(result_table) > 0:
        match_index = 0
    if match_index is None:
        if verbose:
            print(f"Sector {_sec_str(Sector)}: TESSSearch returned no usable rows.")
        if verbose:            
            timer(t0, time.time(), "row selection took:")
        return None

    final_result = (result_table.cubedata[match_index]
                    if hasattr(result_table, 'cubedata')
                    else result_table[match_index])
    result = final_result
    if verbose:    
        timer(t0, time.time(), "row selection took:")

    if verbose:
        _radius_arcsec = f"{used_px * 21.0}" if used_px is not None else "unknown"
        print(f"TESSSearch query: target=TIC {ID},search_radius={_radius_arcsec}*u.arcsec, exptime={exptime},sector={Sector}")
        print(f"result: {result}")

    # ------------------------ download with backoff + dirs ---------------------
    # prepare dirs
    t0 = time.time()
    extra = 0
    _ensure_tesscut_dirs(dlroot, tic_id=ID, shard_by_tic=shard_by_tic)
    if verbose:    
        timer(t0, time.time(), "ensure TESScut dirs took:")

    # first attempt
    t0 = time.time()
    try:
        # Throttle TESScut download itself
        with TesscutCounterSemaphore(cache_root=downloadpath, max_slots=4):
            result2 = while_loop(
                command=lambda: result.download(
                    download_dir=dlroot,
                    TESScut_size=(cutoutsize+extra, cutoutsize+extra),
                    cache=True
                ),
                message=f'Downloading {ffi_or_tpf} file from TESScut, trying again in a bit'
            )
    except Exception as err:
        if verbose:
            print(f"Sector {_sec_str(Sector)}: TESScut download raised → {err}")
        result2 = None
    if verbose:        
        timer(t0, time.time(), "TESScut download attempt #1 took:")

    # optional retry
    if (result2 is None) or (len(result2) == 0):
        if verbose:
            print(f"TESScut download returned empty result for TIC {ID} sector {Sector}. Retrying once.")
        _ensure_tesscut_dirs(dlroot, tic_id=ID, shard_by_tic=shard_by_tic)
        t1 = time.time()
        try:
            # Throttle the retry as well
            with TesscutCounterSemaphore(cache_root=downloadpath, max_slots=4):
                result2 = while_loop(
                    command=lambda: result.download(
                        download_dir=dlroot,
                        TESScut_size=(cutoutsize+extra, cutoutsize+extra),
                        cache=True
                    ),
                    message=f'Downloading {ffi_or_tpf} file from TESScut, trying again in a bit'
                )
        except Exception as err:
            if verbose:
                print(f"Sector {_sec_str(Sector)}: TESScut second attempt raised → {err}")
            result2 = None
        if verbose:
            timer(t1, time.time(), "TESScut download attempt #2 took:")
    #
    # ------------------------------ flatten to cache (ONCE) --------------------
    t0 = time.time()
    cam_ccd = sector_map.get(int(Sector)) if isinstance(Sector, (int, np.integer)) else None
    cam = cam_ccd[0] if cam_ccd else None
    ccd = cam_ccd[1] if cam_ccd else None
    lock_name = _cache_lock_name(product_tag=product_tag,
                                 sector=int(Sector) if isinstance(Sector, (int, np.integer)) else None,
                                 camera=int(cam) if cam is not None else None,
                                 ccd=int(ccd) if ccd is not None else None,
                                 tic_id=ID if cam is None or ccd is None else None)
    with _CacheLock(str(downloadpath), name=lock_name):
        try:
            result2 = _flatten_to_cache(
                result2,
                cache_root=downloadpath,
                product_tag=product_tag, 
                tic_id=ID, shard_by_tic=shard_by_tic)
        except Exception as err:
            if verbose:
                print(f"[flatten] failed → {err}")
            result2 = None
    if verbose:            
        timer(t0, time.time(), "flatten to cache took:")

    # fallback if flatten yielded nothing
    if (result2 is None) or (len(result2) == 0):
        t0 = time.time()
        try:
            out = tess_stars2px(ID, tgt_coord.ra.deg, tgt_coord.dec.deg, aberrate=False)
            _, _, _, outSector, outCam, outCcd, *_ = out
            sector_map = dict(zip(outSector, zip(outCam, outCcd)))
            if Sector in sector_map:
                cam, ccd = sector_map[Sector]
                cached = _get_cached_fits(
                    downloadpath,
                    product_tag=product_tag,
                    sector=Sector, camera=cam, ccd=ccd,
                    size=cutoutsize, target_coord=tgt_coord, 
                    tic_id=ID, shard_by_tic=shard_by_tic)
                
                if cached:
                    if verbose:
                        print(f"found cached FITS → {os.path.join(dlroot, product_tag, cached.name)}")
                    timer(t0, time.time(), "cache fallback open took:")
                    return fits.open(cached)
        except Exception as e:
            if verbose:
                print(f"Sector {_sec_str(Sector)}: cache lookup failed → {e}")
        if verbose:
            timer(t0, time.time(), "cache fallback path took:")
        return None

    # normalize Local Path values -> list[str]
    t0 = time.time()
    try:
        # pandas DataFrame
        result2['Local Path'] = result2['Local Path'].astype(str).str.replace(r'//','/', regex=True)
        local_paths = [os.path.normpath(p) for p in result2['Local Path']]
    except Exception:
        # astropy Table
        local_paths = [os.path.normpath(str(p).replace('//','/')) for p in result2['Local Path']]
    if verbose:        
        timer(t0, time.time(), "normalize Local Path took:")
        
    # after you compute local_paths = [...]
    t0 = time.time()
    try:
        _ = _wait_for_paths(local_paths)
    except Exception:
        pass
    if verbose:      
        timer(t0, time.time(), "post-flatten wait for Local Path(s) took:")
        

    # ---------------------- verify sector/cam/ccd and open ---------------------
    t0 = time.time()
    aberrate=False
    tesspoint_results = tess_stars2px(ID, star[ra_col].item(), star[dec_col].item(), aberrate=aberrate)
    outID, outEclipLong, outEclipLat, outSector, outCam, outCcd, outColPix, outRowPix, scinfo = tesspoint_results

    Sectors = (np.atleast_1d(int(Sector)) if isinstance(Sector, (int, np.integer))
               else np.atleast_1d(Sector).astype(int))
    common_indices = np.isin(outSector, Sectors)
    if not np.any(common_indices):
        if verbose:
            print(f"Sector {_sec_str(Sector)}: tess_stars2px found no overlap.")
        timer(t0, time.time(), "verify sector/cam/ccd took:")
        return None

    # THIS approach will take LONG time on HPC
#     if ffi_or_tpf == 'FFI':
#         fits_name = find_tesscut_file(
#             basedir = os.path.join(dlroot, 'TESSCut')+'/',
#             sector = int(outSector[common_indices][0]),
#             camera = int(outCam[common_indices][0]),
#             ccd    = int(outCcd[common_indices][0]),
#             size   = cutoutsize
#         )
#     else:
#         fits_name = find_tpf_file(
#             basedir = os.path.join(dlroot, 'TESS')+'/',
#             tic     = ID,
#             sector  = int(outSector[common_indices][0]),
#             cadence = cadence
#         )
    # THIS approach will take LONG time on HPC
    # Do this instead:
    # Choose the appropriate FITS path directly from local_paths
    fits_path = None

    # Expected sector for this target
    expected_sector = int(outSector[common_indices][0])

    if ffi_or_tpf == 'FFI':
        # FFI / TESScut: use sector, camera, ccd, and cutout size in filename
        expected_cam = int(outCam[common_indices][0])
        expected_ccd = int(outCcd[common_indices][0])
        sector_tag = f"s{expected_sector:04d}"

        # tess-s0001-1-4_<RA>_<Dec>_11x11_astrocut.fits
        prefix = f"tess-{sector_tag}-{expected_cam}-{expected_ccd}_"
        suffix = f"_{cutoutsize}x{cutoutsize}_astrocut.fits"

        for p in local_paths:
            name = os.path.basename(p)
            if name.startswith(prefix) and name.endswith(suffix) and os.path.isfile(p):
                fits_path = p
                break

    else:
        # TPF: use sector + TIC in filename, ignore cadence for robustness
        sector_tag = f"s{expected_sector:04d}"
        tic_tag    = f"{int(ID):016d}"

        for p in local_paths:
            name = os.path.basename(p)
            if (f"-{sector_tag}-{tic_tag}-" in name
                and (name.endswith("_tp.fits") or name.endswith("_tp.fits.gz"))
                and os.path.isfile(p)):
                fits_path = p
                break

    # Fallback: if no exact match, pick the first existing local path
    if fits_path is None:
        for p in local_paths:
            if os.path.isfile(p):
                fits_path = p
                break

    if verbose:        
        timer(t0, time.time(), "verify sector/cam/ccd took:")

    if fits_path is None:
        if verbose:
            print(f"Sector {_sec_str(Sector)}: could not locate a Local Path to open.")
        return None
    
    # Do this instead:    
        
    if verbose:        
        timer(t0, time.time(), "find_*(fits) took:")

#     if fits_name is None:
#         if verbose:
#             print(f"Sector {_sec_str(Sector)}: find_* helper returned None.")
#         return None

    # ---------- OPEN: prefer exact Local Path match; else first existing -------
#     t0 = time.time()
#     target_path = os.path.normpath(str(fits_name))

#     fits_path = None
#     for p in local_paths:
#         if p == target_path and os.path.isfile(p):
#             fits_path = p
#             break
#     if fits_path is None:
#         for p in local_paths:
#             if os.path.isfile(p):
#                 fits_path = p
#                 break
#     if verbose:                
#         timer(t0, time.time(), "select/open local FITS path took:")

#     # Fallback: if no exact match, pick the first existing local path
#     if fits_path is None:
#         for p in local_paths:
#             if os.path.isfile(p):
#                 fits_path = p
#                 break

    if verbose:
        print(f"found TESScut file → {fits_path} \n")

    t0 = time.time()
    hdu = fits.open(fits_path, memmap=False)
    if verbose:
        timer(t0, time.time(), "fits.open took:")

    # Remove any unwanted files not matching the selected one, under the lock
    t0 = time.time()
    with _CacheLock(str(downloadpath), name=lock_name):
        try:
            unwanted = [str(p) for p in result2['Local Path'] if str(p) != fits_path]
            for f in unwanted:
                try:
                    if os.path.exists(f):
                        os.remove(f)
                except Exception:
                    pass
        except Exception:
            pass
    if verbose:        
        timer(t0, time.time(), "cleanup of non-selected Local Paths took:")

    # overall
    if verbose:    
        timer(t_func, time.time(), "gethdu_lksearch total took:")
    return hdu

def _gethdu_lksearch_verified(
    star: pd.DataFrame,
    ID: int,
    Sector: int,
    cadence: str,
    default_settings: dict,
) -> "fits.HDUList | None":
    """
    Return the cutout for one TIC ID and one sector, verified to be that
    star and that sector, or None if no verified cutout can be obtained.

    Wraps ``_gethdu_lksearch_unverified`` (the previous ``gethdu_lksearch``,
    unchanged) and checks whatever it returns on all three of its return
    paths: cache-first, cache fallback after a failed flatten, and fresh
    download. A cutout is accepted only if

    1. header SECTOR equals ``Sector``;
    2. the cutout position (header RA_OBJ/DEC_OBJ, else the astrocut file
       name) is within ``identity_pos_tol_arcsec`` of the target; and
    3. its 10th and 90th percentile times do not map to another sector
       under ``TESS_Sector_observation_check``.

    A camera/CCD disagreement with tess-point is printed as a note only.

    Retry. A rejected cutout is closed, the job waits, and retrieval runs
    again, up to ``identity_max_attempts`` attempts in total. The wait
    before attempt k (k >= 2) is ``(k - 1) * identity_retry_wait_s +
    (ID % 10)`` seconds, about 30 s and then 60 s by default. Any wait over
    one second gives the new download a different temporary zip name, and
    the per-TIC offset keeps two jobs that collided from retrying in step.
    Waits are deterministic for a given TIC. NEMESIS writes nothing for this
    sector before a cutout is accepted. If a rejected file comes back
    unchanged (a cache hit, which a retry cannot change), retrying stops.
    Rejected files are left on disk for inspection.

    A first attempt that returns no cutout (sector not served, or search
    failed) returns None at once, as before. A retry that returns no cutout
    moves on to the next attempt.

    Every accepted cutout prints one ``[identity] ... verified <path>`` line,
    so job logs record which file each light curve came from.

    Parameters
    ----------
    star : pd.DataFrame
        Single-row catalog entry with ra/dec (or ra_TIC/dec_TIC) in degrees.
    ID : int
        TIC identifier.
    Sector : int
        Single sector. A non-scalar is passed through unverified, with a
        printed warning, exactly as before.
    cadence : str
        As for ``_gethdu_lksearch_unverified``.
    default_settings : dict
        NEMESIS settings. Optional keys: ``identity_pos_tol_arcsec``
        (default 21.0), ``identity_max_attempts`` (default 3) and
        ``identity_retry_wait_s`` (default 30.0).

    Returns
    -------
    astropy.io.fits.HDUList or None

    Example
    -------
    >>> hdu = gethdu_lksearch(star, 366578561, 20, '30 minute', settings)  # doctest: +SKIP
    """
    import time as _time
    from tess_stars2px import tess_stars2px_function_entry as tess_stars2px

    if not isinstance(Sector, (int, np.integer)):
        print(f"[identity] TIC {ID}: non-scalar Sector {Sector!r}; "
              f"cutout returned UNVERIFIED")
        return _gethdu_lksearch_unverified(star, ID, Sector, cadence,
                                           default_settings)

    sec = int(Sector)
    tol = float(default_settings.get('identity_pos_tol_arcsec', 21.0))
    n_try = max(1, int(default_settings.get('identity_max_attempts', 3)))
    base_wait = max(0.0, float(default_settings.get('identity_retry_wait_s', 30.0)))
    ra_col = 'ra_TIC' if 'ra_TIC' in star.columns else 'ra'
    dec_col = 'dec_TIC' if 'dec_TIC' in star.columns else 'dec'
    ra = float(star[ra_col].iloc[0])
    dec = float(star[dec_col].iloc[0])

    exp_cam = exp_ccd = None
    try:
        out = tess_stars2px(ID, ra, dec, aberrate=False)
        smap = {int(s): (int(c), int(d)) for s, c, d in zip(out[3], out[4], out[5])}
        if sec in smap:
            exp_cam, exp_ccd = smap[sec]
    except Exception:
        pass

    rejected: set = set()
    for attempt in range(1, n_try + 1):
        if attempt > 1:
            wait_s = (attempt - 1) * base_wait + (int(ID) % 10)
            print(f"[identity] TIC {ID} S{sec}: waiting {wait_s:.0f} s "
                  f"before attempt {attempt}/{n_try}")
            _time.sleep(wait_s)
        hdu = _gethdu_lksearch_unverified(star, ID, Sector, cadence,
                                          default_settings)
        if hdu is None:
            if attempt == 1:
                return None
            print(f"[identity] TIC {ID} S{sec}: no cutout returned on "
                  f"attempt {attempt}/{n_try}")
            continue
        try:
            path = str(hdu.filename() or "")
        except Exception:
            path = ""
        if path and path in rejected:
            print(f"[identity] TIC {ID} S{sec}: rejected file came back "
                  f"unchanged (cache hit), not retrying: {path}")
            try:
                hdu.close()
            except Exception:
                pass
            break
        try:
            times = hdu[1].data['TIME']
        except Exception:
            times = None
        chk = verify_cutout_identity(
            hdu[0].header, sec, ra=ra, dec=dec, pos_tol_arcsec=tol,
            expected_camera=exp_cam, expected_ccd=exp_ccd, filename=path,
            require_position=True, times=times,
            sector_of_time=lambda t: TESS_Sector_observation_check(T0=t))
        for note in chk['notes']:
            print(f"[identity] TIC {ID} S{sec}: note: {note} ({path})")
        if chk['ok']:
            print(f"[identity] TIC {ID} S{sec}: verified {path} "
                  f"(sep {chk['sep_arcsec']:.2f} arcsec, position from "
                  f"{chk['pos_source']})")
            return hdu
        print(f"[identity] TIC {ID} S{sec}: attempt {attempt}/{n_try} rejected "
              f"{path}: {'; '.join(chk['reasons'])}")
        rejected.add(path)
        try:
            hdu.close()
        except Exception:
            pass
    print(f"[identity] TIC {ID} S{sec}: no verified cutout; returning None")
    return None




def gethdu_lksearch_OLD(
    star: pd.DataFrame,
    ID: int,
    Sector: int,
    cadence: str,
    default_settings: dict,
) -> "fits.HDUList | None":
    """
    Return the cutout for one TIC ID and one sector, verified to be that
    star and that sector, or None if no verified cutout can be obtained.

    Wraps ``_gethdu_lksearch_unverified`` (the previous ``gethdu_lksearch``,
    unchanged) and checks whatever it returns on all three of its return
    paths: cache-first, cache fallback after a failed flatten, and fresh
    download. A cutout is accepted only if

    1. header SECTOR equals ``Sector``;
    2. the cutout position (header RA_OBJ/DEC_OBJ, else the astrocut file
       name) is within ``identity_pos_tol_arcsec`` of the target; and
    3. its 10th and 90th percentile times do not map to another sector
       under ``TESS_Sector_observation_check``.

    A camera/CCD disagreement with tess-point is printed as a note only.
    A rejected cutout is closed and retrieval is retried, up to
    ``identity_max_attempts`` attempts in total. Rejected files are left on
    disk for inspection. Every accepted cutout prints one
    ``[identity] ... verified <path>`` line, so job logs record which file
    each light curve came from.

    Parameters
    ----------
    star : pd.DataFrame
        Single-row catalog entry with ra/dec (or ra_TIC/dec_TIC) in degrees.
    ID : int
        TIC identifier.
    Sector : int
        Single sector. A non-scalar is passed through unverified, with a
        printed warning, exactly as before.
    cadence : str
        As for ``_gethdu_lksearch_unverified``.
    default_settings : dict
        NEMESIS settings. Optional keys: ``identity_pos_tol_arcsec``
        (default 21.0) and ``identity_max_attempts`` (default 2).

    Returns
    -------
    astropy.io.fits.HDUList or None

    Example
    -------
    >>> hdu = gethdu_lksearch(star, 366578561, 20, '30 minute', settings)  # doctest: +SKIP
    """
    from tess_stars2px import tess_stars2px_function_entry as tess_stars2px

    if not isinstance(Sector, (int, np.integer)):
        print(f"[identity] TIC {ID}: non-scalar Sector {Sector!r}; "
              f"cutout returned UNVERIFIED")
        return _gethdu_lksearch_unverified(star, ID, Sector, cadence,
                                           default_settings)

    sec = int(Sector)
    tol = float(default_settings.get('identity_pos_tol_arcsec', 21.0))
    n_try = max(1, int(default_settings.get('identity_max_attempts', 2)))
    ra_col = 'ra_TIC' if 'ra_TIC' in star.columns else 'ra'
    dec_col = 'dec_TIC' if 'dec_TIC' in star.columns else 'dec'
    ra = float(star[ra_col].iloc[0])
    dec = float(star[dec_col].iloc[0])

    exp_cam = exp_ccd = None
    try:
        out = tess_stars2px(ID, ra, dec, aberrate=False)
        smap = {int(s): (int(c), int(d)) for s, c, d in zip(out[3], out[4], out[5])}
        if sec in smap:
            exp_cam, exp_ccd = smap[sec]
    except Exception:
        pass

    for attempt in range(1, n_try + 1):
        hdu = _gethdu_lksearch_unverified(star, ID, Sector, cadence,
                                          default_settings)
        if hdu is None:
            return None
        try:
            path = str(hdu.filename() or "")
        except Exception:
            path = ""
        try:
            times = hdu[1].data['TIME']
        except Exception:
            times = None
        chk = verify_cutout_identity(
            hdu[0].header, sec, ra=ra, dec=dec, pos_tol_arcsec=tol,
            expected_camera=exp_cam, expected_ccd=exp_ccd, filename=path,
            require_position=True, times=times,
            sector_of_time=lambda t: TESS_Sector_observation_check(T0=t))
        for note in chk['notes']:
            print(f"[identity] TIC {ID} S{sec}: note: {note} ({path})")
        if chk['ok']:
            print(f"[identity] TIC {ID} S{sec}: verified {path} "
                  f"(sep {chk['sep_arcsec']:.2f} arcsec, position from "
                  f"{chk['pos_source']})")
            return hdu
        print(f"[identity] TIC {ID} S{sec}: attempt {attempt}/{n_try} rejected "
              f"{path}: {'; '.join(chk['reasons'])}")
        try:
            hdu.close()
        except Exception:
            pass
    return None


# ---------------------------------------------------------------------------
# Retrieval diagnosis (print-only), added 10-06-2026.
# gethdu, gethdu_lksearch and _ensure_hdu_or_raise keep their signatures,
# return values and exceptions. These helpers only add log lines that say
# WHY no image data came back for a TIC and sector.
# ---------------------------------------------------------------------------
from typing import Any, Dict, List, Tuple

#: Last retrieval outcome per (TIC, sector) in this process.
_GETHDU_DIAG: Dict[Tuple[int, int], Dict[str, Any]] = {}
#: The record is cleared when it reaches this size (bounded memory in long jobs).
_GETHDU_DIAG_MAX: int = 10000

_NO_DATA_KEYS: Tuple[str, ...] = (
    "no tesssearch results", "no data found", "no results", "no products",
)
_TIMEOUT_NAMES = frozenset({"TimeoutError", "Timeout", "ReadTimeout",
                            "ConnectTimeout", "timeout"})
_TIMEOUT_KEYS: Tuple[str, ...] = ("timeout", "timed out", "time-out",
                                  "time limit")
_NETWORK_NAMES = frozenset({"ConnectionError", "HTTPError", "URLError",
                            "RemoteServiceError", "SSLError", "gaierror",
                            "ChunkedEncodingError", "ProtocolError",
                            "IncompleteRead", "RemoteDisconnected",
                            "MaxRetryError", "NewConnectionError"})
_NETWORK_KEYS: Tuple[str, ...] = (
    "connection", "max retries exceeded", "server error",
    "service unavailable", "bad gateway", "temporarily unavailable",
    "name or service not known", "name resolution",
)

_CAUSE_TEXT: Dict[str, str] = {
    "NO_DATA": ("MAST answered and lists no matching cutout for this star in "
                "this sector."),
    "SERVER_TIMEOUT": ("MAST did not answer within its time limit. The data "
                       "may still exist; retry later."),
    "NETWORK": ("MAST could not be reached or returned a server error. The "
                "data may still exist; retry later."),
    "OTHER_ERROR": ("Retrieval raised an unexpected error. This is more "
                    "likely a code or file problem than MAST."),
    "NO_CUTOUT": ("The search ran but no verified cutout came back (for "
                  "example: no row matched the expected camera/CCD, the "
                  "download stayed empty after retries, or the identity "
                  "check rejected the file). See the lines above for which."),
    "RETRIEVED": ("A verified cutout was retrieved, but gethdu discarded it "
                  "afterwards: photon-count QC or a header/metadata error. "
                  "A 'download failed' line above refers to that later step. "
                  "This is about the data, not MAST; retrying will not help."),
}


def _fmt_elapsed(seconds: float) -> str:
    """
    Format a duration for log lines: seconds below 2 minutes, else minutes.

    Parameters
    ----------
    seconds : float
        Elapsed time in seconds.

    Returns
    -------
    str

    Examples
    --------
    >>> _fmt_elapsed(12.34)
    '12.3 s'
    >>> _fmt_elapsed(612.0)
    '10.2 min'
    """
    s = float(seconds)
    return f"{s:.1f} s" if s < 120.0 else f"{s / 60.0:.1f} min"


def _gethdu_diag_key(ID: Any, Sector: Any) -> Tuple[int, int]:
    """
    Build the (TIC, sector) key used by the retrieval record.

    Anything that cannot be read as an integer becomes -1, so building a key
    never raises.

    Parameters
    ----------
    ID : Any
        TIC identifier.
    Sector : Any
        TESS sector.

    Returns
    -------
    (int, int)

    Examples
    --------
    >>> _gethdu_diag_key(416097928, np.int64(18))
    (416097928, 18)
    >>> _gethdu_diag_key(1, None)
    (1, -1)
    """
    def _as_int(x: Any) -> int:
        try:
            return int(x)
        except (TypeError, ValueError):
            return -1
    return _as_int(ID), _as_int(Sector)


def _record_gethdu_diag(key: Tuple[int, int], cause: str, detail: str,
                        elapsed_s: float) -> None:
    """
    Store the latest retrieval outcome for one (TIC, sector).

    Parameters
    ----------
    key : (int, int)
        From ``_gethdu_diag_key``.
    cause : str
        A key of ``_CAUSE_TEXT``.
    detail : str
        Original error as "Type: message", or "".
    elapsed_s : float
        Time spent in retrieval, in seconds.

    Returns
    -------
    None
    """
    if len(_GETHDU_DIAG) >= _GETHDU_DIAG_MAX:
        _GETHDU_DIAG.clear()
    _GETHDU_DIAG[key] = {"cause": str(cause), "detail": str(detail),
                         "elapsed_s": float(elapsed_s)}


def classify_retrieval_error(err: BaseException) -> Tuple[str, str]:
    """
    Sort a cutout-retrieval exception into a plain-language cause.

    The checks run in order and the first match wins:

    1. NO_DATA: the message says the search returned nothing.
    2. SERVER_TIMEOUT: a timeout class anywhere in the exception's class
       hierarchy (builtin, astroquery, requests), or timeout wording.
    3. NETWORK: a connection, HTTP, SSL or DNS class, or matching wording.
    4. OTHER_ERROR: anything else.

    Parameters
    ----------
    err : BaseException
        The exception raised during retrieval.

    Returns
    -------
    (str, str)
        Cause label and its explanation from ``_CAUSE_TEXT``.

    Examples
    --------
    >>> classify_retrieval_error(TimeoutError("Timeout limit of 600 exceeded."))[0]
    'SERVER_TIMEOUT'
    >>> class LKSearchError(Exception): pass
    >>> classify_retrieval_error(LKSearchError("No TESSSearch results for TIC 1 (Sector 18, exptime=1800) up to radius 10.50 px."))[0]
    'NO_DATA'
    >>> classify_retrieval_error(ConnectionResetError("Connection reset by peer"))[0]
    'NETWORK'
    >>> classify_retrieval_error(KeyError("CCD"))[0]
    'OTHER_ERROR'
    """
    names = {c.__name__ for c in type(err).__mro__}
    msg = str(err).lower()
    if any(k in msg for k in _NO_DATA_KEYS):
        cause = "NO_DATA"
    elif (names & _TIMEOUT_NAMES) or any(k in msg for k in _TIMEOUT_KEYS):
        cause = "SERVER_TIMEOUT"
    elif (names & _NETWORK_NAMES) or any(k in msg for k in _NETWORK_KEYS):
        cause = "NETWORK"
    else:
        cause = "OTHER_ERROR"
    return cause, _CAUSE_TEXT[cause]


def _tesspoint_note(star: pd.DataFrame, ID: Any, Sector: Any) -> str:
    """
    State tess-point's prediction for one star and sector, as one sentence.

    Used when MAST returns nothing, to tell "not observed" apart from an
    empty answer for a star that should be on silicon. Runs offline and
    never raises.

    Parameters
    ----------
    star : pd.DataFrame
        Single-row catalog entry with 'ra'/'ra_TIC' and 'dec'/'dec_TIC'.
    ID : Any
        TIC identifier.
    Sector : Any
        TESS sector.

    Returns
    -------
    str

    Example
    -------
    >>> _tesspoint_note(star, 416097928, 18)            # doctest: +SKIP
    'tess-point predicts this star on silicon in S18 (camera 1, CCD 1), ...'
    """
    try:
        from tess_stars2px import tess_stars2px_function_entry as tess_stars2px
        ra_col = 'ra_TIC' if 'ra_TIC' in star.columns else 'ra'
        dec_col = 'dec_TIC' if 'dec_TIC' in star.columns else 'dec'
        out = tess_stars2px(int(ID), float(star[ra_col].iloc[0]),
                            float(star[dec_col].iloc[0]), aberrate=False)
        _, _, _, out_sec, out_cam, out_ccd, *_ = out
        for s, c, d in zip(np.atleast_1d(out_sec), np.atleast_1d(out_cam),
                           np.atleast_1d(out_ccd)):
            if int(s) == int(Sector):
                return (f"tess-point predicts this star on silicon in "
                        f"S{int(Sector)} (camera {int(c)}, CCD {int(d)}), so "
                        f"an empty answer may be transient or a TESScut "
                        f"coverage gap; one retry is reasonable.")
        return (f"tess-point does not place this star on silicon in "
                f"S{int(Sector)}; no data is the expected answer.")
    except Exception as exc:
        return f"tess-point check unavailable ({type(exc).__name__}: {exc})."


def gethdu_failure_summary(ID: Any, Sector: Any) -> str:
    """
    One line saying why a TIC and sector ended with no image data.

    Reads the outcome ``gethdu_lksearch`` recorded for this (TIC, sector)
    in this process.

    Parameters
    ----------
    ID : Any
        TIC identifier.
    Sector : Any
        TESS sector.

    Returns
    -------
    str

    Examples
    --------
    >>> _GETHDU_DIAG.clear()
    >>> gethdu_failure_summary(1, 18).startswith("[no image data] TIC 1 S18: cause not recorded")
    True
    >>> _record_gethdu_diag((1, 18), "SERVER_TIMEOUT", "TimeoutError: Timeout limit of 600 exceeded.", 612.0)
    >>> "SERVER_TIMEOUT after 10.2 min" in gethdu_failure_summary(1, 18)
    True
    >>> _GETHDU_DIAG.clear()
    """
    key = _gethdu_diag_key(ID, Sector)
    tag = f"TIC {ID} S{key[1]}"
    rec = _GETHDU_DIAG.get(key)
    if rec is None:
        return (f"[no image data] {tag}: cause not recorded (gethdu_lksearch "
                f"was not reached for this sector in this process).")
    cause = rec["cause"]
    detail = f" ({rec['detail']})" if rec.get("detail") else ""
    return (f"[no image data] {tag}: {cause} after "
            f"{_fmt_elapsed(rec['elapsed_s'])}. "
            f"{_CAUSE_TEXT.get(cause, '')}{detail}")


def gethdu_lksearch(
    star: pd.DataFrame,
    ID: int,
    Sector: int,
    cadence: str,
    default_settings: dict,
) -> "fits.HDUList | None":
    """
    Return the verified cutout for one TIC ID and one sector, exactly as
    ``_gethdu_lksearch_verified`` does, and log why when none comes back.

    This layer adds log lines only. It calls ``_gethdu_lksearch_verified``
    (the identity-checking wrapper, renamed and otherwise unchanged) with the
    same arguments, returns its result unchanged, and re-raises any exception
    unchanged, so ``gethdu`` behaves exactly as before.

    What it adds:

    1. On an exception: one ``[gethdu diagnosis]`` line with the cause
       (NO_DATA, SERVER_TIMEOUT, NETWORK or OTHER_ERROR), the time spent and
       the original error. For NO_DATA, a second line gives tess-point's
       prediction for the sector.
    2. On a ``None`` return: the same, with cause NO_CUTOUT.
    3. On success: a note only if retrieval took longer than
       ``default_settings['gethdu_slow_warn_s']`` (default 120 s) and
       ``verbose`` is on.

    Every outcome is stored in ``_GETHDU_DIAG`` under (TIC, sector), so
    ``_ensure_hdu_or_raise`` can restate the cause next to the
    ``NoImageDataError`` it raises.

    Parameters
    ----------
    star : pd.DataFrame
        Single-row stellar catalog entry (RA/Dec columns).
    ID : int
        TIC identifier.
    Sector : int
        Single TESS sector.
    cadence : str
        NEMESIS cadence label, e.g. "30 minute".
    default_settings : dict
        NEMESIS settings. Optional new key: ``gethdu_slow_warn_s``.

    Returns
    -------
    fits.HDUList or None
        Exactly what ``_gethdu_lksearch_verified`` returned.

    Raises
    ------
    Exception
        Whatever ``_gethdu_lksearch_verified`` raised, unchanged.

    Example
    -------
    >>> hdu = gethdu_lksearch(star, 416097928, 18, "30 minute", settings)  # doctest: +SKIP
    """
    import time as _time

    settings = default_settings or {}
    key = _gethdu_diag_key(ID, Sector)
    tag = f"TIC {ID} S{key[1]}"
    verbose = bool(settings.get("verbose", False))
    slow_s = float(settings.get("gethdu_slow_warn_s", 120.0))

    t_start = _time.time()
    try:
        hdu = _gethdu_lksearch_verified(star, ID, Sector, cadence,
                                        default_settings)
    except Exception as err:
        elapsed = _time.time() - t_start
        cause, text = classify_retrieval_error(err)
        detail = f"{type(err).__name__}: {err}"
        _record_gethdu_diag(key, cause, detail, elapsed)
        print(f"[gethdu diagnosis] {tag}: {cause} after "
              f"{_fmt_elapsed(elapsed)}. {text} ({detail})", flush=True)
        if cause == "NO_DATA":
            print(f"[gethdu diagnosis] {tag}: "
                  f"{_tesspoint_note(star, ID, Sector)}", flush=True)
        raise

    elapsed = _time.time() - t_start
    if hdu is None:
        _record_gethdu_diag(key, "NO_CUTOUT", "", elapsed)
        print(f"[gethdu diagnosis] {tag}: NO_CUTOUT after "
              f"{_fmt_elapsed(elapsed)}. {_CAUSE_TEXT['NO_CUTOUT']}",
              flush=True)
        print(f"[gethdu diagnosis] {tag}: {_tesspoint_note(star, ID, Sector)}",
              flush=True)
        return hdu

    _record_gethdu_diag(key, "RETRIEVED", "", elapsed)
    if verbose and elapsed > slow_s:
        print(f"[gethdu diagnosis] {tag}: retrieved, but slowly "
              f"({_fmt_elapsed(elapsed)}). MAST was slow, not failing.",
              flush=True)
    return hdu


# --- safe sector string for logs (prevents bogus "array→scalar" errors) ---



def _sec_str(sector):
    """Safe sector string for logs; won’t blow up on numpy/list types."""
    import numpy as np
    try:
        return str(int(np.asarray(sector).reshape(-1)[0]))
    except Exception:
        return str(sector)

