def search_sectors_from_filetype_and_path(
    ID,
    default_settings,
    restrict_to=None,
    require_masks: bool = False,
):
    """
    Discover which TESS sectors have processed light curves on disk.

    Scans ``default_settings['savelcpath']`` for files named exactly
    ``TIC_{ID}_Sector_{XXXX}_final_LC.csv`` and returns the sorted sector
    integers. Matching is anchored on the full ``TIC_{ID}_Sector_`` prefix,
    so a TIC whose digits appear as a substring of another TIC (e.g. 56276
    inside 156276) can no longer contaminate the result.

    Parameters
    ----------
    ID : int
        TIC identifier.
    default_settings : dict
        NEMESIS settings dict. Consumed keys: ``savelcpath``, ``verbose``.
    restrict_to : iterable of int or None
        If given, the returned sectors are intersected with this set. Use
        this to pin the result to the sectors actually processed in the
        current run rather than whatever is on disk.
    require_masks : bool
        If True, a sector is returned only when its companion
        ``_pix_mask.pkl``, ``_bkg_mask.pkl`` and ``_image_fluxes.pkl``
        files are also present in the same directory. Leave False for
        post-hoc use after ``cleanup`` has removed those products.

    Returns
    -------
    np.ndarray of int
        Sorted, unique sector numbers. Empty array if nothing is found.

    Examples
    --------
    >>> search_sectors_from_filetype_and_path(7582552, default_settings)
    array([14, 25, 26])
    >>> search_sectors_from_filetype_and_path(
    ...     7582552, default_settings, restrict_to=[14, 26], require_masks=True)
    array([14, 26])
    """
    import os
    import numpy as np

    savelcpath = default_settings.get("savelcpath")
    verbose = bool(default_settings.get("verbose", False))

    if savelcpath is None or not os.path.isdir(savelcpath):
        if verbose:
            print(f"[search_sectors] savelcpath unusable: {savelcpath}")
        return np.array([], dtype=int)

    prefix = f"TIC_{int(ID)}_Sector_"
    suffix = "_final_LC.csv"

    allowed = None
    if restrict_to is not None:
        allowed = {int(s) for s in np.atleast_1d(restrict_to)}

    found = {}
    for dirpath, _dirnames, filenames in os.walk(savelcpath):
        for fname in filenames:
            if not fname.startswith(prefix) or not fname.endswith(suffix):
                continue
            tag = fname[len(prefix):-len(suffix)]
            if not tag.isdigit():
                continue
            sector = int(tag)
            if allowed is not None and sector not in allowed:
                continue
            found.setdefault(sector, dirpath)

    if require_masks:
        keep = {}
        for sector, dirpath in found.items():
            base = f"TIC_{int(ID)}_Sector_{sector:04d}"
            companions = [f"{base}_pix_mask.pkl",
                          f"{base}_bkg_mask.pkl",
                          f"{base}_image_fluxes.pkl"]
            if all(os.path.isfile(os.path.join(dirpath, c)) for c in companions):
                keep[sector] = dirpath
            elif verbose:
                print(f"[search_sectors] TIC {ID} Sector {sector}: "
                      f"LC present but mask products missing; dropped.")
        found = keep

    return np.array(sorted(found.keys()), dtype=int)

def search_sectors_from_filetype_and_path_OLD(ID,default_settings):    
    """
    Discover which TESS sectors have processed light curves on disk.

    Intended for post-LC-creation use when ``Sector=None`` or
    ``get_all_sectors=True``: after ``LC_creation`` runs across all
    available sectors, this function scans ``savelcpath`` for
    ``TIC_{ID}_Sector_*_final_LC.csv`` files and returns the
    corresponding sorted list of sector integers.

    This replaces the earlier ``(path, ID, cadence)`` call signature;
    all path and cadence information is now drawn from
    ``default_settings``.

    Parameters
    ----------
    ID : int
        TIC identifier whose processed light curves are to be located.
    default_settings : dict
        Standard NEMESIS settings dictionary.  Required keys:
            ``'savelcpath'`` — directory containing ``_final_LC.csv`` files.
            ``'get_all_sectors'`` — bool; controls upstream behavior but
            does not gate this function's search logic.

    Returns
    -------
    sectors : list of int
        Sorted list of sector integers for which a ``_final_LC.csv``
        exists in ``savelcpath``.  Returns an empty list if no files
        are found.

    Notes
    -----
    The search uses ``recursive_search`` to locate
    ``TIC_{ID}_Sector_*_final_LC.csv`` files; sector numbers are
    extracted by parsing the ``Sector_XXXX`` tag from each filename.

    This function does **not** re-download or re-process any data; it
    is a pure filesystem query.

    Examples
    --------
    >>> sectors = search_sectors_from_filetype_and_path(ID, default_settings)
    >>> print(sectors)
    [1, 2, 14, 27]
    """
    savelcpath = default_settings.get("savelcpath")
    #print(path)
    
    #NEED TO UPDATE FOR TRANSIT INJECTION
#     if (cadence=='long') or (cadence=='30 minute') or (cadence=='10 minute'):
#         savelcpath = path+'NEMESIS_FFI_LCs/'        
#     if (cadence=='short') or (cadence=='2 minute') or (cadence=='20 second') or (cadence=='fast'):      
#         savelcpath = path+'NEMESIS_TPF_LCs/'    
    #    
    matched_files=recursive_search(savelcpath,str(ID)+'*final_LC.csv')  
    # now search for all files that have Sector numbers
    # in filename
    #print('matched_files: \n',matched_files)
    sector_list=[]
    for f in matched_files:
        if '_Multi_Sector_' not in f:
            sector_list.append(int(f.split('/')[-1].split('_')[3]))    
    return np.unique(sector_list)
