def check_centroids(ID, Sector, cadence, reference_pixel, default_settings):
    """
    This function will compare the location of the centroids produced by
    the 'SAP' function with the location of the reference pixel.
    Input Parameters
    ----------
    ID : int
        TESS Input Catalog ID number.
    Sector : int or list or None
        TESS Sector Number.         
    cadence : str
        The desired cadence of TESS observations for input target star.
        Valid inputs include:
            * '30 minute'
            * '10 minute'
            * '2 minute'
            * '20 second'
        Deprecated inputs are: 'long', 'short', 'fast'. These will return 
        30-minute, 2-minute and 20 second products, respectfully.            
    reference_pixel: list
        A list of X,Y coordinates of the FFI/TPF Row,Column 
        pixel location of the target star.
    path : str
        Pathname of desired location to store NEMESIS data products.
    savelcpath : str
        Pathname of directory for output NEMESIS light curves.
        
    Returns
    -------
        *
    """   
    import pandas as pd
    import numpy as np

    path          = default_settings.get('path')
    savelcpath    = default_settings.get('savelcpath')
    print('savelcpath:',savelcpath)

    get_all_sectors = default_settings.get('get_all_sectors')
    verbose       = False

    # ── KEY FIX ───────────────────────────────────────────────────────────────
    # An explicit integer sector always wins, even in a multi-sector run.
    # Only fall back to "Multi_Sector" when no concrete sector is available.
    if isinstance(Sector, int):
        sector_tag = f"Sector_{Sector:04d}"
    elif get_all_sectors or Sector is None:
        sector_tag = "Multi_Sector"
    else:
        sector_tag = "Multi_Sector"
        
#     if savelcpath is None:
#         base_path  = default_settings.get('base_path', './')
#         savelcpath = f'{base_path}/TIC_{ID}/{sector_tag}/'
        
    if savelcpath is None:
        Path = generate_injection_path(Sector, default_settings)       
        print('Path:',Path)
        
        if (cadence in ['long', '30 minute', '10 minute']):
            savelcpath = os.path.join(Path, 'NEMESIS_FFI_LCs/')
        elif (cadence in ['short', '2 minute', '20 second', 'fast']):
            savelcpath = os.path.join(Path, 'NEMESIS_TPF_LCs/')            
        
    # ─────────────────────────────────────────────────────────────────────────
    print('check_centroids:', savelcpath, "TIC_" + str(ID) + f"_{sector_tag}_pix_mask")
    pix_mask = readNDarr(savelcpath, "TIC_" + str(ID) + f"_{sector_tag}_pix_mask")
    images   = readNDarr(savelcpath, "TIC_" + str(ID) + f"_{sector_tag}_image_fluxes")

    centxs = []
    centys = []
    if len(np.shape(images)) != 3:
        images = images[0]
    if len(np.shape(pix_mask)) != 2:
        pix_mask = pix_mask[0]

    for x in range(len(images)):
        images_  = images[x]
        centxx, centyy = centroid_quadratic(images_, pix_mask, reference_pixel)
        centxs = np.append(centxs, centxx)
        centys = np.append(centys, centyy)

    return centxs, centys
