#based on https://stackoverflow.com/questions/49618782/get-external-coordinates-of-a-polygon-from-a-numpy-boolean-grid
def check_edge(hdu,mypols):
    """
    This function is used to check if a polygon contains
    the edges of a Full Frame Image (FFI) or Target Pixel
    File (TPF). 
    Input Parameters
    ----------
    hdu : FITS object
        Astropy Header Data Unit List of TESS FFI/TPF for target star.
        Contains PrimaryHDU, BinTableHDU and ImageHDU.
    mypols : Shapely polygon object
        A polygon that outlines the shape of a pixel mask.
    Returns
    -------
        my_tuple: tuple
            Outline of polygon 
    """
    xmin,xmax = 0,  np.shape(hdu[1].data['FLUX'][0])[0]
    ymin,ymax = 0,  np.shape(hdu[1].data['FLUX'][0])[1]
    
    check_list = [xmin,xmax,ymin,ymax]
    my_tuple = mypols[0][0]
#     print(check_list)
#     print(' ')
#     print(my_tuple)
    if len([i for i, v in enumerate(my_tuple) if v[0] == xmin or  v[0] == xmax])>0:
        my_tuple = mypols[1][0]     
    return my_tuple
#
def get_polygon(mask,hdu):
    """
    This function will produce a Shapely Polygon object
    that outlines the input pixel mask.
    Input Parameters
    ----------
    mask: array
        A pixel mask array 
    hdu : FITS object
        Astropy Header Data Unit List of TESS FFI/TPF for target star.
        Contains PrimaryHDU, BinTableHDU and ImageHDU.
    Returns
    -------
        poly: Shapely Polygon object
            This polygon outlines the shape of the pixel mask. Useful
            for checking if pixel coordinates is inside pixel mask.
    """
    import numpy as np
    import rasterio.features
    from shapely.geometry import Point, Polygon

    # Convert your array to 0-1 integers
    #myarray = [[1 if t else 0 for t in row] for row in mask]
    # Build a numpy array
    #myarray = np.array(myarray)
    # Convert the type (don't even know why this was needed in my computer, but raised exception if not converted.
    #myarray = myarray.astype(np.int32)
    #
    myarray = np.array(mask).astype(np.int32)

    # Let the library do the magic. You should take a look at the rasterio.features.shapes output
    #print('L 2772 check:\n type:',type(myarray),'\n shape:',np.shape(myarray),'\n len:',len(myarray))
    mypols = [p[0]['coordinates'] for p in  rasterio.features.shapes(myarray)]
    #
    #mypols isn't always configured the same way, check if it contains edges of FFI/TPF    
    use_these = check_edge(hdu,mypols)
    #
    # grab corners of polygon to make a polygon object with shapely
    poly = Polygon(use_these)
    return poly
#    
def is_point_inside_polygon(pix_coords,poly):
    """
    This function will check if the input pixel coordinates
    are within the input Shapely polygon object.
    Input Parameters
    ----------
    pix_coords: list
        List of input pixel coordinates.
    poly: Shapely Polygon object
        This polygon outlines the shape of the pixel mask. Useful
        for checking if pixel coordinates is inside pixel mask.
    Returns
    -------
        isinside: list
            A list of indices where pixel coordinates 
            are within input Polygon object.
    """
    from shapely.geometry import Point, Polygon
    #check if polygon makes sense
    if poly.is_valid==False:
        print('bad polygon, recheck coordinates of pixel mask')
    
    isinside=[]
    for x in range(len(pix_coords)):
        point = Point(pix_coords[x][0],pix_coords[x][1])
#         point = Point(np.transpose(pix_coords)[0][x],np.transpose(pix_coords)[1][x])
#         print(point,poly.contains(point), poly.intersects(point)) 
#         if (poly.contains(point)==True) or (poly.intersects(point)==True):
#         print(point,point.within(poly)==True , poly.contains(point)==True)
        if (point.within(poly)==True) or (poly.contains(point)==True):
            isinside=np.append(isinside,x)
    isinside = [int(x) for x in isinside]
    return isinside
