# ─────────────────────────────────────────────────────────────────────────────
# Quaternion helper functions (required by new SAP)
# Insert these three functions immediately before the SAP function definition.
# ─────────────────────────────────────────────────────────────────────────────

def get_qdata(sector: int, savepath: str, overwrite: bool = False) -> "fits.HDUList":
    """
    Download or load the TESS engineering quaternion FITS for a given sector
    from the MAST archive.

    Parameters
    ----------
    sector : int
        TESS sector number.
    savepath : str
        Directory where the quaternion FITS file is cached.
    overwrite : bool
        If True, re-download even if the cached file exists.

    Returns
    -------
    fits.HDUList
        Opened quaternion FITS file.  Caller is responsible for closing it.

    Example
    -------
    >>> qdata = get_qdata(sector=3, savepath='/data/quats/')
    >>> qdata.close()
    """
    import os, re, requests
    from astropy.io import fits

    MAST_ENG_URL = "https://archive.stsci.edu/missions/tess/engineering/"
    sector_tag   = f"sector{sector:02d}"
    os.makedirs(savepath, exist_ok=True)
    local_path = os.path.join(savepath, f"sector_{sector:02d}_quaternion.fits")

    if not os.path.isfile(local_path) or overwrite:
        resp = requests.get(MAST_ENG_URL, timeout=30)
        resp.raise_for_status()
        pattern = rf"(tess\d+_{re.escape(sector_tag)}-quat\.fits)"
        matches = re.findall(pattern, resp.text)
        if not matches:
            raise FileNotFoundError(
                f"No quaternion file found for Sector {sector} at {MAST_ENG_URL}"
            )
        url = MAST_ENG_URL + matches[0]
        print(f"[get_qdata] Downloading: {url}")
        with requests.get(url, stream=True, timeout=300) as r:
            r.raise_for_status()
            with open(local_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=65536):
                    f.write(chunk)
    else:
        print(f"[get_qdata] Using cached: {local_path}")

    return fits.open(local_path)


def load_camera_quaternions(qdata: "fits.HDUList", camera: int) -> "pd.DataFrame":
    """
    Extract TIME, Q1, Q2, Q3 for a given camera from a quaternion HDUList.

    Parameters
    ----------
    qdata : fits.HDUList
        Opened TESS quaternion FITS (from get_qdata).
    camera : int
        Camera number 1–4.

    Returns
    -------
    pd.DataFrame
        Columns: TIME, Q1, Q2, Q3.  NaN rows and Inf values are dropped.

    Example
    -------
    >>> qdata = get_qdata(sector=3, savepath='/data/quats/')
    >>> qdf = load_camera_quaternions(qdata, camera=2)
    >>> qdata.close()
    """
    import pandas as pd
    import numpy as np
    from astropy.table import Table

    if camera not in (1, 2, 3, 4):
        raise ValueError(f"camera must be 1–4, got {camera}")

    df     = Table(qdata[camera].data).to_pandas()
    rename = {f"C{camera}_Q{i}": f"Q{i}" for i in (1, 2, 3)}
    missing = [k for k in rename if k not in df.columns]
    if missing:
        raise KeyError(f"Expected columns not found in HDU {camera}: {missing}")

    df = df.rename(columns=rename)[["TIME", "Q1", "Q2", "Q3"]]
    return (df.replace([np.inf, -np.inf], np.nan)
              .dropna(subset=["TIME"])
              .reset_index(drop=True))

def _resolve_quat_savepath(default_settings: dict) -> str:
    """
    Derive a canonical quaternion cache directory from default_settings
    and write it back as default_settings['quat_savepath'].

    Priority
    --------
    1. default_settings['quat_savepath']  — already set by caller; normalise & return.
    2. <downloadpath>/quaternions/         — subdir of the TESScut/TPF cache root.
    3. <base_path>/cache/quaternions/      — fallback if downloadpath is absent.

    The quaternion directory is always *inside* the cache root so that a
    single cache_dir_path setting controls all downloaded artefacts.

    Returns
    -------
    str  Absolute path to the quaternion directory (created if absent,
         trailing '/' included to match NEMESIS path conventions).
    """
    from pathlib import Path

    # 1. Already set: normalise and persist.
    existing = default_settings.get('quat_savepath')
    if existing is not None:
        p = Path(existing).expanduser().resolve()
        p.mkdir(parents=True, exist_ok=True)
        result = str(p) + '/'
        default_settings['quat_savepath'] = result
        return result

    # 2. Derive from downloadpath (the cache root used by TESScut/TPF).
    dl = default_settings.get('downloadpath')
    if dl:
        qp = Path(dl).expanduser().resolve() / 'quaternions'
    else:
        # 3. Fallback: <base_path>/cache/quaternions/
        base = default_settings.get('base_path', '.')
        qp = Path(base).expanduser().resolve() / 'cache' / 'quaternions'
        print(qp)

    qp.mkdir(parents=True, exist_ok=True)
    result = str(qp) + '/'
    default_settings['quat_savepath'] = result
    return result


def prefetch_quaternions(
    sectors,
    default_settings: dict,
    *,
    overwrite: bool = False,
    verbose: bool = False,
) -> dict:
    """
    Pre-download and cache TESS engineering quaternion FITS files for
    every sector in *sectors* before LC creation begins.

    This is a best-effort, non-fatal pre-fetch: any sector that fails
    (network error, missing file on MAST, etc.) is noted in the returned
    status dict but does not raise an exception.  ``SAP()`` will issue
    its own ``RuntimeWarning`` and skip the quaternion mask gracefully
    for sectors that could not be fetched.

    Parameters
    ----------
    sectors : int | list[int] | None
        Sector number(s) to pre-fetch.  None / empty → no-op.
    default_settings : dict
        NEMESIS settings dict.  ``quat_savepath`` is resolved and written
        back here as a side-effect (see ``_resolve_quat_savepath``).
    overwrite : bool
        Re-download even if the cached file exists.
    verbose : bool
        Print per-sector status lines.

    Returns
    -------
    dict  {sector_int: 'cached' | 'downloaded' | 'skipped' | 'failed: <msg>'}

    Examples
    --------
    >>> status = prefetch_quaternions(
    ...     sectors=[3, 4, 5],
    ...     default_settings=default_settings,
    ...     verbose=True,
    ... )
    >>> # Only sectors that could not be fetched have values starting with 'failed'
    >>> failed = {s: v for s, v in status.items() if v.startswith('failed')}
    """
    import numpy as np
    from pathlib import Path

    # ── gate: skip entirely if quaternion masking is disabled ─────────────────
    if not default_settings.get('use_quat_jitter_mask', True):
        if verbose:
            print('[prefetch_quaternions] use_quat_jitter_mask=False — skipping.')
        return {}

    # ── resolve and persist the canonical quat path ───────────────────────────
    quat_path = _resolve_quat_savepath(default_settings)

    # ── normalise sector list ─────────────────────────────────────────────────
    if sectors is None:
        if verbose:
            print('[prefetch_quaternions] sectors=None — nothing to pre-fetch.')
        return {}

    sector_arr = np.atleast_1d(sectors).astype(int).tolist()
    if not sector_arr:
        return {}

    status = {}

    for sec in sector_arr:
        sec = int(sec)
        # Check if already cached (get_qdata does this too, but checking here
        # avoids the HTTP listing request for MAST's engineering index page)
        expected = Path(quat_path) / f'sector_{sec:02d}_quaternion.fits'
        if expected.exists() and not overwrite:
            if verbose:
                print(f'  [quat S{sec:02d}] already cached → {expected.name}')
            status[sec] = 'cached'
            continue

        try:
            hdul = get_qdata(sector=sec, savepath=quat_path, overwrite=overwrite)
            hdul.close()
            status[sec] = 'downloaded'
            if verbose:
                print(f'  [quat S{sec:02d}] downloaded OK → {expected.name}')
        except FileNotFoundError as e:
            # No file on MAST for this sector (very early or very late sectors)
            msg = f'failed: {e}'
            status[sec] = msg
            if verbose:
                print(f'  [quat S{sec:02d}] {msg}')
        except Exception as e:
            msg = f'failed: {type(e).__name__}: {e}'
            status[sec] = msg
            if verbose:
                print(f'  [quat S{sec:02d}] {msg}')

    n_ok   = sum(1 for v in status.values() if v in ('cached', 'downloaded'))
    n_fail = sum(1 for v in status.values() if v.startswith('failed'))
    print(f'[prefetch_quaternions] {n_ok}/{len(sector_arr)} sectors ready'
          + (f'; {n_fail} failed (SAP will degrade gracefully)' if n_fail else '.'))

    return status


# -----------------------------------------------------------------------------
# helper functions for TESS Pixel-Response Function files (using TESS_PRF)
# -----------------------------------------------------------------------------

import os
import tarfile
import urllib.request
from pathlib import Path
from typing import Union, List, Optional


# Two PRF calibration epochs — independent of sector number beyond this mapping.
# TESS had a focus adjustment between Sectors 3 and 4; one calibrated PRF set
# exists for each side of that adjustment. Sector 4 onward all share start_s0004.


def _resolve_prf_cache_dir(default_settings: dict) -> str:
    """
    Resolve the PRF cache directory from NEMESIS settings.

    Mirrors ``_resolve_quat_savepath``. Priority:

    1. ``default_settings['prf_cache_dir']`` if already set (non-None).
    2. ``<cache_dir_path>/prf/`` where ``cache_dir_path`` is the NEMESIS
       shared cache root.
    3. ``<downloadpath>/prf/`` as a fallback.
    4. ``./prf/`` as a last resort.

    The resolved path is written back into ``default_settings['prf_cache_dir']``
    so downstream calls (e.g. inside ``SAP()``) see it without re-resolving.

    Parameters
    ----------
    default_settings : dict
        NEMESIS settings dict (from ``default_NEMESIS_pipeline_settings()``).

    Returns
    -------
    prf_cache_dir : str
        Absolute path to the PRF cache directory (created if absent).

    Examples
    --------
    >>> default_settings['cache_dir_path'] = '/data/NEMESIS/cache/'
    >>> prf_cache_dir = _resolve_prf_cache_dir(default_settings)
    >>> print(prf_cache_dir)
    /data/NEMESIS/cache/prf/
    """
    # Priority 1: already explicitly set
    existing = default_settings.get('prf_cache_dir')
    if existing is not None:
        prf_dir = str(existing)
    else:
        # Priority 2: derive from cache_dir_path
        cache_root = (
            default_settings.get('cache_dir_path')
            or default_settings.get('downloadpath')
            or '.'
        )
        prf_dir = os.path.join(str(cache_root), 'prf', '')

    os.makedirs(prf_dir, exist_ok=True)
    # Write back so it's available everywhere settings are threaded through
    default_settings['prf_cache_dir'] = prf_dir
    return prf_dir


def prefetch_prf(
    sectors: List[int],
    default_settings: dict,
    cameras: tuple = (1, 2, 3, 4),
    overwrite: bool = False,
    verbose: bool = True,
) -> dict:
    """
    Pre-download TESS PRF FITS files from MAST for the epochs required by
    ``sectors``.

    Mirrors ``prefetch_quaternions(sectors, default_settings)``. Resolves the
    PRF cache directory via ``_resolve_prf_cache_dir``, determines which of the
    two PRF epochs (``start_s0001``, ``start_s0004``) are needed for the
    supplied sector list, and downloads only those that are missing.

    Because TESS PRF models are epoch-based (not sector-based), passing
    ``sectors=list(range(1, 27))`` downloads at most two epoch bundles
    (one per camera per epoch = ~20 MB each) regardless of how many sectors
    you supply. If all sectors are ≥ 4, only ``start_s0004`` is fetched.

    Parameters
    ----------
    sectors : list of int
        TESS sector numbers you intend to process. Used only to determine
        which epochs are needed; no per-sector files are written.
    default_settings : dict
        NEMESIS settings dict. ``prf_cache_dir`` is resolved and written back.
    cameras : tuple of int, optional
        Camera numbers to fetch (1–4). Default: all four.
    overwrite : bool, optional
        Re-download even if already cached. Default: False.
    verbose : bool, optional
        Print progress. Default: True.

    Returns
    -------
    status : dict
        Mirrors the structure of ``prefetch_quaternions`` output::

            {
                'prf_cache_dir' : str,          # resolved cache path
                'epochs_needed' : list of str,  # e.g. ['start_s0001', 'start_s0004']
                'cameras'       : tuple,
                <epoch_dir> : {
                    <cam_n> : 'cached' | 'downloaded' | 'failed' | 'skipped'
                },
            }

    Examples
    --------
    >>> all_sectors = list(range(1, 27))
    >>> prf_status = prefetch_prf(all_sectors, default_settings, verbose=True)
    >>> print(prf_status['start_s0004'])
    {'cam_1': 'downloaded', 'cam_2': 'downloaded', ...}
    """
    
    _PRF_EPOCH_MAP = {
        's0001': 'start_s0001',   # Sectors 1–3
        's0004': 'start_s0004',   # Sectors 4–current (and all future sectors)
    }
    _PRF_BASE_URL = 'https://archive.stsci.edu/missions/tess/models/prf_fitsfiles'
    
    prf_cache_dir = _resolve_prf_cache_dir(default_settings)

    if verbose:
        print(f'[prefetch_prf] prf_cache_dir : {prf_cache_dir}')

    # ── Determine which epochs are actually needed ────────────────────────────
    needs_s0001 = any(s <= 3 for s in sectors)
    needs_s0004 = any(s >= 4 for s in sectors)

    epochs_needed = []
    if needs_s0001:
        epochs_needed.append('s0001')
    if needs_s0004:
        epochs_needed.append('s0004')

    if verbose:
        epoch_dirs = [_PRF_EPOCH_MAP[e] for e in epochs_needed]
        print(f'[prefetch_prf] epochs needed : {epoch_dirs}')
        print(f'[prefetch_prf] cameras       : {cameras}')

    status = {
        'prf_cache_dir' : prf_cache_dir,
        'epochs_needed' : [_PRF_EPOCH_MAP[e] for e in epochs_needed],
        'cameras'       : cameras,
    }

    # ── Download loop ─────────────────────────────────────────────────────────
    for epoch_key in epochs_needed:
        epoch_dir  = _PRF_EPOCH_MAP[epoch_key]
        epoch_path = Path(prf_cache_dir) / epoch_dir
        epoch_path.mkdir(parents=True, exist_ok=True)
        status[epoch_dir] = {}

        for cam in cameras:
            cam_key = f'cam_{cam}'

            # Already cached?
            existing_dirs = list(epoch_path.glob(f'cam{cam}_ccd*'))
            if existing_dirs and not overwrite:
                n_fits = sum(
                    len(list(d.glob('*.fits'))) for d in existing_dirs
                )
                if verbose:
                    print(f'  [{epoch_dir}] cam{cam} already cached '
                          f'({n_fits} FITS files) — skipping.')
                status[epoch_dir][cam_key] = 'cached'
                continue

            # Download tgz
            url      = f'{_PRF_BASE_URL}/{epoch_dir}/tess_prf_camera_{cam}.tgz'
            tgz_path = Path(prf_cache_dir) / f'_tmp_{epoch_key}_cam{cam}.tgz'

            if verbose:
                print(f'  [{epoch_dir}] cam{cam}: downloading (~20 MB) ...',
                      end=' ', flush=True)
            try:
                urllib.request.urlretrieve(url, tgz_path)
                if verbose:
                    print('done.', flush=True)
            except Exception as exc:
                if verbose:
                    print(f'FAILED ({exc})', flush=True)
                if tgz_path.exists():
                    tgz_path.unlink()
                status[epoch_dir][cam_key] = 'failed'
                continue

            # Extract
            if verbose:
                print(f'  [{epoch_dir}] cam{cam}: extracting ...',
                      end=' ', flush=True)
            try:
                with tarfile.open(tgz_path, 'r:gz') as tf:
                    tf.extractall(epoch_path)
                tgz_path.unlink()
                if verbose:
                    print('done.', flush=True)
                status[epoch_dir][cam_key] = 'downloaded'
            except Exception as exc:
                if verbose:
                    print(f'FAILED ({exc})', flush=True)
                status[epoch_dir][cam_key] = 'failed'

    if verbose:
        def _prf_cache_summary(prf_cache_dir: Union[str, Path]) -> None:
            """Print a summary of PRF files present in the cache."""
            prf_cache_dir = Path(prf_cache_dir)
            print(f'\n[prefetch_prf] Cache summary: {prf_cache_dir}')
            for epoch_dir in _PRF_EPOCH_MAP.values():
                epoch_path = prf_cache_dir / epoch_dir
                if not epoch_path.exists():
                    print(f'  {epoch_dir}/  — not present')
                    continue
                fits_count = len(list(epoch_path.rglob('*.fits')))
                ccd_dirs   = len(list(epoch_path.glob('cam*_ccd*')))
                print(f'  {epoch_dir}/  — {ccd_dirs} CCD dirs, {fits_count} FITS files')
        #
        _prf_cache_summary(prf_cache_dir)

    return status



# ─────────────────────────────────────────────────────────────────────────────
# Sector-resolution helper (used by full_pipeline initializer)
# ─────────────────────────────────────────────────────────────────────────────

def _resolve_target_sectors(
    ID: int,
    Sector,
    star,
    default_settings: dict,
) -> list[int]:
    """
    Return the concrete list of sector ints that full_pipeline will process.

    For ``Sector=None`` / ``get_all_sectors=True`` the function calls
    ``tess_stars2px`` once to enumerate all observed sectors, then applies
    the same ``last_updated_sector`` cap that ``gethdu`` uses.

    Falls back to an empty list on any error so the initializer never blocks
    the main pipeline.
    """
    import numpy as np

    last_updated_sector = int(default_settings.get('last_updated_sector', 26))
    get_all  = default_settings.get('get_all_sectors', False)
    ra_col   = 'ra_TIC' if 'ra_TIC' in star.columns else 'ra'
    dec_col  = 'dec_TIC' if 'dec_TIC' in star.columns else 'dec'

    if get_all or Sector is None:
        try:
            from tess_stars2px import tess_stars2px_function_entry as t2px
            _, _, _, outSector, *_ = t2px(
                ID, star[ra_col].item(), star[dec_col].item(), aberrate=False)
            sectors = [int(s) for s in np.unique(outSector)
                       if 1 <= int(s) <= last_updated_sector]
        except Exception as e:
            print(f'[_resolve_target_sectors] tess_stars2px failed: {e}')
            sectors = []
    elif isinstance(Sector, (list, np.ndarray)):
        sectors = [int(s) for s in np.atleast_1d(Sector)
                   if 1 <= int(s) <= last_updated_sector]
    elif isinstance(Sector, (int, np.integer)):
        sectors = [int(Sector)] if 1 <= int(Sector) <= last_updated_sector else []
    else:
        sectors = []

    return sectors

def bin_quaternion_features(
    lc_time: "np.ndarray",
    q_time:  "np.ndarray",
    q1: "np.ndarray",
    q2: "np.ndarray",
    q3: "np.ndarray",
    cadence_days: "Optional[float]" = None,
    min_samples:  int = 10,
    time_offset:  float = 0.0,
) -> "Tuple[pd.DataFrame, List[str]]":
    """
    Bin 2-sec quaternion data to LC cadence and compute the 36 QLP feature
    series following Kunimoto et al. (2022), arXiv:2211.04387.

    Feature construction (36 total, all zero-mean / unit-variance):
      - Per bin: mean, std, skew of Q1, Q2, Q3            →  9 base features
      - Same-statistic cross-products (3 pairs × 3 stats)  →  9 features
      - Squares of all 18 above                            → 18 features

    NaN bins (< min_samples quaternion samples) are linearly interpolated
    before normalization so the design matrix has no gaps.

    A raw 'jitter' scalar sqrt(σ_Q1² + σ_Q2² + σ_Q3²) is stored as an
    auxiliary column (pre-normalization) for threshold-based quality flagging
    — see SAP().

    Parameters
    ----------
    lc_time : (N,) ndarray   LC timestamps in BTJD.
    q_time  : (M,) ndarray   Quaternion timestamps in TJD (before offset).
    q1, q2, q3 : (M,) ndarray  Quaternion components for one camera.
    cadence_days : float or None
        Nominal cadence in days; inferred from median(diff(lc_time)) if None.
    min_samples : int
        Minimum quaternion samples per bin; bins below this get NaN (→ interp).
    time_offset : float
        Added to q_time to align TJD → BTJD (days).  Use median(TIMECORR)
        from the LC FITS table.

    Returns
    -------
    feature_df : pd.DataFrame, shape (N, 39)
        36 normalized feature columns + auxiliary 'time', 'n_samples', 'jitter'.
    feature_cols : list[str]
        Ordered names of the 36 normalized feature columns.

    Example
    -------
    >>> feat_df, feat_cols = bin_quaternion_features(
    ...     lc_time=t, q_time=qdf['TIME'].values,
    ...     q1=qdf['Q1'].values, q2=qdf['Q2'].values, q3=qdf['Q3'].values,
    ...     cadence_days=30/1440, min_samples=10, time_offset=0.0
    ... )
    """
    import numpy as np
    import pandas as pd

    lc_time = np.asarray(lc_time, dtype=np.float64)
    q_time  = np.asarray(q_time,  dtype=np.float64) + time_offset
    q1, q2, q3 = (np.asarray(a, dtype=np.float64) for a in (q1, q2, q3))

    if cadence_days is None:
        cadence_days = float(np.nanmedian(np.diff(lc_time)))
    half_cad = cadence_days / 2.0
    n_lc     = len(lc_time)

    # ── Bin assignment via midpoint edges ────────────────────────────────────
    mids  = 0.5 * (lc_time[:-1] + lc_time[1:])
    edges = np.concatenate([[lc_time[0] - half_cad], mids, [lc_time[-1] + half_cad]])
    bin_idx = np.digitize(q_time, edges) - 1
    assigned_lc = lc_time[np.clip(bin_idx, 0, n_lc - 1)]
    valid = (
        (bin_idx >= 0) & (bin_idx < n_lc)
        & (np.abs(q_time - assigned_lc) <= half_cad)
    )

    df_q = pd.DataFrame(
        {"bin": bin_idx[valid], "q1": q1[valid], "q2": q2[valid], "q3": q3[valid]}
    )
    grp    = df_q.groupby("bin")
    counts = grp["q1"].count().reindex(range(n_lc), fill_value=0)
    bad    = counts < min_samples

    # ── Raw per-bin statistics ────────────────────────────────────────────────
    full_idx = pd.RangeIndex(n_lc)
    raw = {}
    for qi, name in [("q1", "Q1"), ("q2", "Q2"), ("q3", "Q3")]:
        raw[f"{name}_mean"] = grp[qi].mean().reindex(full_idx)
        raw[f"{name}_std"]  = grp[qi].std(ddof=1).reindex(full_idx)
        raw[f"{name}_skew"] = grp[qi].skew().reindex(full_idx)

    feat = pd.DataFrame(raw)
    for col in feat.columns:
        feat.loc[bad, col] = np.nan
    base_cols = list(feat.columns)

    # ── Jitter scalar: sqrt(σ_Q1² + σ_Q2² + σ_Q3²) — pre-normalization ──────
    jitter = np.sqrt(
        feat["Q1_std"].values**2 + feat["Q2_std"].values**2 + feat["Q3_std"].values**2
    )

    # ── Cross-products (same statistic, pairs of quaternion dimensions) ───────
    cross_cols = []
    for stat in ["mean", "std", "skew"]:
        for (i, j) in [("Q1", "Q2"), ("Q1", "Q3"), ("Q2", "Q3")]:
            col = f"{i}x{j}_{stat}"
            feat[col] = feat[f"{i}_{stat}"] * feat[f"{j}_{stat}"]
            cross_cols.append(col)

    # ── Squares of all 18 base + cross features ───────────────────────────────
    sq_cols = []
    for col in base_cols + cross_cols:
        sq_col = f"{col}_sq"
        feat[sq_col] = feat[col] ** 2
        sq_cols.append(sq_col)

    feature_cols = base_cols + cross_cols + sq_cols  # 9 + 9 + 18 = 36

    # ── Interpolate NaN; edge-fill for leading / trailing gaps ───────────────
    for col in feature_cols:
        if feat[col].isna().any():
            feat[col] = feat[col].interpolate(method="linear", limit_direction="both")

    # ── Normalize: zero mean, unit variance ───────────────────────────────────
    for col in feature_cols:
        mu, sig = feat[col].mean(), feat[col].std()
        feat[col] = (feat[col] - mu) / sig if sig > 0 else 0.0

    feat["time"]      = lc_time
    feat["n_samples"] = counts.values.astype(int)
    feat["jitter"]    = jitter          # raw scalar stored for diagnostic use

    return feat, feature_cols


# -------------------------------------------------------------------------
# QUALITY-FLAG bitmask helpers
# based on 2^(n-1) for n>1, like TESS quality flags
# flag id 0 -> bit 0 # "good" data
# flag id 1 -> bit 1 # "high quaternion jitter" data
# flag id 2 -> bit 2 # "excess background flux and/or centroid motion" data
# flag id 3 -> bit 4 # "flagged outlier" data
# -------------------------------------------------------------------------
QUALITY_FLAG_BITS = {
    0: np.int16(0),
    1: np.int16(2**(1-1)),
    2: np.int16(2**(2-1)),
    3: np.int16(2**(3-1)),
    4: np.int16(2**(4-1)),
}

def _flag_ids_to_bitmask(flag_ids) -> np.int16:
    """
    Convert flag identities like [1,2,3] into bitmask sum 1+2+4 = 7.
    """
    import numpy as np

    if flag_ids is None:
        return np.int16(0)

    ids = np.atleast_1d(flag_ids).astype(int).tolist()
    bitmask = 0
    for fid in ids:
        if fid == 0:
            continue
        if fid not in QUALITY_FLAG_BITS:
            raise ValueError(
                f"Unknown quality-flag id: {fid}. "
                f"Valid ids: {sorted(QUALITY_FLAG_BITS)}"
            )
        bitmask |= int(QUALITY_FLAG_BITS[fid])
    return np.int16(bitmask)

def _bitmask_to_flag_ids(bitmask) -> list[int]:
    """
    Convert stored bitmask value into flag identities.
    Examples:
        0 -> [0]
        3 -> [1,2]
        6 -> [2,3]
    """
    import pandas as pd

    if pd.isna(bitmask):
        return [0]

    b = int(bitmask)
    if b == 0:
        return [0]

    out = []
    for fid in (1, 2, 3, 4):
        if b & int(QUALITY_FLAG_BITS[fid]):
            out.append(fid)
    return out


def _bitmask_to_flag_string(bitmask) -> str:
    """
    Human-readable representation for CSV export.
    """
    ids = _bitmask_to_flag_ids(bitmask)
    if ids == [0]:
        return "0"
    return "|".join(str(x) for x in ids)


def _decorate_quality_columns(
    df: "pd.DataFrame",
    quality_col: str = "QUALITY_FLAG",
    label_col: str = "QUALITY_FLAGS",
) -> "pd.DataFrame":
    """
    Ensure QUALITY_FLAG is int16 bitmask and attach readable QUALITY_FLAGS.
    """
    import pandas as pd
    import numpy as np

    out = df.copy()
    if quality_col not in out.columns:
        return out

    out[quality_col] = pd.to_numeric(out[quality_col], errors="coerce").fillna(0).astype(np.int16)
    out[label_col] = out[quality_col].map(_bitmask_to_flag_string)
    return out


def _apply_outlier_flag(
    SAP_LC_full: "pd.DataFrame",
    outlier_indices: "np.ndarray",
) -> "pd.DataFrame":
    """
    Set QUALITY_FLAG = 3 on cadences identified by outlier_removal().

    Only cadences currently carrying flag 0 are updated; cadences already
    flagged 1 (quaternion jitter) or 2 (background/centroid) are not
    downgraded — the higher-priority cause is preserved.

    Parameters
    ----------
    SAP_LC_full : pd.DataFrame
        Full-length SAP_LC returned by SAP(); must contain 'QUALITY_FLAG'.
    outlier_indices : np.ndarray[int]
        Positional indices into SAP_LC_full of cadences to flag as outliers.

    Returns
    -------
    pd.DataFrame with QUALITY_FLAG == 3 set on newly identified outliers.

    Example
    -------
    >>> # In outlier_removal(), after identifying bad_ind:
    >>> SAP_LC_full = _apply_outlier_flag(SAP_LC_full, bad_ind)
    >>> clean_LC = SAP_LC_full.loc[SAP_LC_full['QUALITY_FLAG'] == 0]
    """
    import numpy as np

    df = SAP_LC_full.copy()
    if 'QUALITY_FLAG' not in df.columns:
        raise KeyError("SAP_LC_full must contain 'QUALITY_FLAG'.")

    idx = np.asarray(outlier_indices, dtype=int)
    idx = idx[(idx >= 0) & (idx < len(df))]

    if len(idx) == 0:
        return _decorate_quality_columns(df)

    current = df.loc[idx, 'QUALITY_FLAG'].to_numpy(dtype=np.int16)
    df.loc[idx, 'QUALITY_FLAG'] = current | QUALITY_FLAG_BITS[4] # outlier = flag-id 4

    return _decorate_quality_columns(df)


# update docstring
def _filter_lc_by_quality_flags(lc_df, 
                                allowed_quality_flags=None, 
                                quality_col='QUALITY_FLAG', 
                                verbose=False,
                               ):
    """
    Return a copy of lc_df keeping only rows whose QUALITY_FLAG is consistent
    with the requested allowed flag-ids.

    A row is kept when its bitmask has NO bits set that correspond to
    *forbidden* flag-ids (i.e. flag-ids in {1,2,3,4} but not in
    ``allowed_quality_flags``).

    Parameters
    ----------
    lc_df : pd.DataFrame or None
    allowed_quality_flags : list[int] or None
        Flag-ids to tolerate.  None → no filtering.
        Valid ids: {0, 1, 2, 3, 4}.
        0 = clean cadences are included.
        1 = quat-jitter cadences are included.
        2 = background-spike cadences are included.
        3 = outlier cadences are included.
        4 = centroid-excursion cadences are included.
    quality_col : str
    verbose : bool

    Returns
    -------
    pd.DataFrame with reset index.

    Examples
    --------
    >>> # keep clean + centroid-flagged (centroid flag does not corrupt flux)
    >>> lc_clean = _filter_lc_by_quality_flags(lc, allowed_quality_flags=[0, 4])
    >>> # keep everything (no removal)
    >>> lc_all = _filter_lc_by_quality_flags(lc, allowed_quality_flags=[0,1,2,3,4])
    """
    import numpy as np
    import pandas as pd

    if lc_df is None:
        return lc_df

    out = lc_df.copy().reset_index(drop=True)

    if allowed_quality_flags is None:
        return out

    if quality_col not in out.columns:
        if verbose:
            print(f'[{quality_col}] not in LC dataframe; skipping quality filtering.')
        return out

    allowed_ids = set(np.atleast_1d(allowed_quality_flags).astype(int).tolist())
    valid_ids = {0, 1, 2, 3, 4}
    if not allowed_ids.issubset(valid_ids):
        raise ValueError(
            f"allowed_quality_flags must be drawn from {sorted(valid_ids)}; "
            f"got {sorted(allowed_ids)}"
        )

    q = pd.to_numeric(out[quality_col], errors='coerce').fillna(0).astype(np.int16)

    nonzero_ids = {1, 2, 3, 4}
    allowed_nonzero = {x for x in allowed_ids if x in nonzero_ids}
    forbidden_ids = sorted(nonzero_ids - allowed_nonzero)
    forbidden_bitmask = _flag_ids_to_bitmask(forbidden_ids)

    keep = (q.to_numpy(dtype=np.int16) & forbidden_bitmask) == 0

    # If clean flag-id 0 is not allowed, remove rows whose stored bitmask is exactly 0.
    if 0 not in allowed_ids:
        keep &= (q.to_numpy(dtype=np.int16) != 0)

    filtered = out.loc[keep].reset_index(drop=True)

    if verbose:
        print(
            f'[quality filter] keeping flag ids {sorted(allowed_ids)}: '
            f'{len(filtered)}/{len(out)} rows'
        )

    return filtered

def _restore_full_length_lc( SAP_LC_full: "pd.DataFrame", compact_df: "pd.DataFrame",
                            preserve_columns=(
                                "CADENCE_INDEX", "Time",
                                "RAW SAP Flux", "SAP Flux", "SAP Error",
                                "Background Flux","Background Error",
                                "QUALITY_FLAG"),
                           ) -> "pd.DataFrame":
    """
    Rebuild a full-length LC dataframe from compact good-cadence results.

    Rows with QUALITY_FLAG != 0 are retained, but all non-preserved columns
    are set to NaN on those rows.
    """
    import numpy as np
    import pandas as pd

    base_cols = [
        c for c in [
            "CADENCE_INDEX",
            "Time",
            "RAW SAP Flux",
            "SAP Flux",
            "SAP Error",
            "QUALITY_FLAG",
        ]
        if c in SAP_LC_full.columns
    ]
    full = SAP_LC_full[base_cols].copy()

    if compact_df is None or len(compact_df) == 0:
        return full

    if "CADENCE_INDEX" not in compact_df.columns:
        raise KeyError("compact_df must contain 'CADENCE_INDEX'.")

    extra = compact_df.copy()
    drop_if_present = [
        c for c in ["Time", "RAW SAP Flux", "SAP Flux", "SAP Error", "QUALITY_FLAG"]
        if c in extra.columns
    ]
    extra = extra.drop(columns=drop_if_present)

    full = full.merge(extra, on="CADENCE_INDEX", how="left")

    bad = full["QUALITY_FLAG"].to_numpy() != 0
    keep = set(preserve_columns)

    for col in full.columns:
        if col not in keep:
            full.loc[bad, col] = np.nan

    return full

def try_apertures( hdu, reference_pixel, quality_mask, 
                  nearby_star_catalog, ID, rawtime, default_settings,
                  thresholds=(3.0, 5.0, 7.5, 10.0),
                  radii=(1.0, 1.5, 2.0, 2.5),   # pixels, circular only
                 ):
    """
    Grid-search over aperture definitions and select the one minimising
    CDPP × (1 + contamination ratio).

    Evaluates a set of candidate apertures — threshold-based masks at each
    value in ``thresholds``, plus circular masks at each radius in ``radii``
    — and scores each by:

        ``score = CDPP_1hr × (1 + flux_contamination_ratio)``

    where ``CDPP_1hr`` is computed on the raw (un-detrended) SAP flux using
    a 1-hour bin and ``flux_contamination_ratio`` is estimated via
    ``calc_flux_contamination`` with a 3-pixel cone radius.  The aperture
    with the lowest score is returned.

    This function is called by ``SAP`` when
    ``default_settings['do_aperture_optimization'] = True``.

    Parameters
    ----------
    hdu : fits.HDUList
        TESS FFI/TPF HDUList.  Pixel flux cube and timestamps are read from
        ``hdu[1].data['FLUX']`` and ``hdu[1].data['TIME']``.
    reference_pixel : list [x, y]
        Target star coordinates within the cutout; used to centre threshold
        masks and to guard against out-of-bounds reference pixels.
    quality_mask : np.ndarray[bool], shape (T,)
        Boolean bad-cadence mask (``True`` = bad); applied before extracting
        the flux cube used for scoring.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``; passed to
        ``calc_flux_contamination``.
    ID : int
        TIC identifier; passed to ``calc_flux_contamination``.
    rawtime : np.ndarray, shape (T,)
        Full-length timestamp array; used only to compute the cadence
        duration for ``CDPP``.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``cutoutsize``, ``verbose``.
    thresholds : tuple of float, optional
        MAD-sigma thresholds passed to ``thresholdmask``.
        Default is ``(3.0, 5.0, 7.5, 10.0)``.
    radii : tuple of float, optional
        Circular aperture radii (pixels) passed to ``create_circular_mask``.
        Default is ``(1.0, 1.5, 2.0, 2.5)``.

    Returns
    -------
    best_pix_mask : np.ndarray[bool] or None
        Aperture mask with the lowest score.  ``None`` if all candidates
        had fewer than 2 pixels or raised an exception during scoring.
    best_score : float
        The minimum score achieved.  ``np.inf`` if no candidate succeeded.
    scores : dict
        Mapping from candidate key (e.g. ``'thr_5.0'``, ``'circ_r1.5'``)
        to its score value.  Candidates that failed scoring are absent.

    Examples
    --------
    >>> best_mask, best_score, scores = try_apertures(
    ...     hdu, reference_pixel=[5, 5], quality_mask=qm,
    ...     nearby_star_catalog=cat, ID=259377017,
    ...     rawtime=t, default_settings=ds)
    >>> if best_mask is not None:
    ...     pix_mask = best_mask
    """
    from wotan import flatten

    flux   = hdu[1].data['FLUX'][~quality_mask].astype(np.float64)
    rawtime_arr = hdu[1].data['TIME'][~quality_mask].astype(np.float64)
    finite = np.any(np.isfinite(flux), axis=(1, 2))
    flux   = flux[finite]
    t      = rawtime_arr[finite]

    cutoutsize = default_settings.get('cutoutsize')
    cad        = float(np.nanmedian(np.diff(t)))

    bkg_mask = ~thresholdmask(
        hdu, reference_pixel=None, threshold=1/1000,
        use_centroid=False, use_circ=True
    )

    median_image = np.nanmedian(flux, axis=0)

    # guard reference pixel
    rp = list(reference_pixel)
    if rp[0] > cutoutsize or rp[1] > cutoutsize:
        rp = [cutoutsize / 2, cutoutsize / 2]

    candidates = {}

    # --- threshold-based apertures ---
    for thr in thresholds:
        try:
            pm = thresholdmask(
                hdu, rp, threshold=thr,
                use_centroid=False, use_circ=True
            )
            candidates[f'thr_{thr}'] = pm
        except (ValueError, Exception):
            pass

    # --- circular apertures ---
    for r in radii:
        pm = create_circular_mask(median_image, rp, radius=r)
        candidates[f'circ_r{r}'] = pm

    scores = {}
    best_key, best_score, best_mask = None, np.inf, None

    for key, pm in candidates.items():
        if pm.sum() < 2:
            continue
        try:
            rawflux, bkgFlux, rawsap, Naper, Nbkg, bkg_pix = \
                extract_background_flux(flux, bkg_mask, pm)

            # quick contamination estimate (radial cone, cheap)
            fcr, _ = calc_flux_contamination(
                nearby_star_catalog, ID, N_TESS_pixels=3
            )
            fcr = float(np.clip(fcr, 0.0, 1.0))

            # CDPP of raw SAP at 1-hr timescale
            err_approx = np.ones_like(rawsap) * np.nanstd(np.diff(rawsap)) / np.sqrt(2)
            cdpp_val   = CDPP(t, rawsap / np.nanmedian(rawsap),
                              err_approx, 'median', 'ppm', cad,
                              binsize=1.0 / 24.0)

            score = cdpp_val * (1.0 + fcr)
            scores[key] = score

            if score < best_score:
                best_score = score
                best_key   = key
                best_mask  = pm

        except Exception:
            continue

    return best_mask, best_score, scores
