import numpy as np
import pandas as pd
from typing import Iterable
#
def apply_nan_to_flagged_rows(
    df: pd.DataFrame,
    preserve_columns: Iterable[str],
    quality_column: str = "QUALITY_FLAG",
) -> pd.DataFrame:
    """
    NaN non-preserved columns on cadences whose QUALITY_FLAG indicates
    flux-corrupting events.

    Flux-corrupting flags (bits 1|2|4, flag-ids 1/2/3): quaternion jitter,
    background spike, outlier.  These cadences have unreliable photometry.

    Centroid-excursion flag (bit 8, flag-id 4): does NOT corrupt flux.
    Rows where the ONLY active flag is a centroid excursion are left intact
    so that transit-search algorithms still see valid flux at those cadences.

    Parameters
    ----------
    df : pd.DataFrame
        Full-length cadence dataframe.
    preserve_columns : iterable of str
        Columns that keep their original values regardless of flag.
        Centroid columns should remain in preserve_columns so that
        centroid-flagged cadences can still be used for vetting.
    quality_column : str

    Returns
    -------
    pd.DataFrame (copy)

    Examples
    --------
    >>> # A FLAG=8 row (centroid only) keeps its SAP Flux intact:
    >>> x = pd.DataFrame({
    ...     "Time": [1.0, 2.0, 3.0],
    ...     "SAP Flux": [1.0, 0.999, 0.997],
    ...     "PLD Flux": [1.0, 0.999, 0.997],
    ...     "QUALITY_FLAG": [0, 2, 8],   # 2=bkg spike, 8=centroid only
    ... })
    >>> y = apply_nan_to_flagged_rows(x, preserve_columns=["Time","SAP Flux","QUALITY_FLAG"])
    >>> pd.isna(y.loc[1, "PLD Flux"])    # FLAG=2 (bkg) → NaN'd
    True
    >>> pd.isna(y.loc[2, "PLD Flux"])    # FLAG=8 (centroid only) → NOT NaN'd
    False
    """
    import numpy as np
    
    out = df.copy()
    preserve = set(preserve_columns) | {quality_column}
    
#     bad = out[quality_column].to_numpy() != 0

#     for col in out.columns:
#         if col not in preserve:
#             out.loc[bad, col] = np.nan
#     return out

    q = out[quality_column].to_numpy(dtype=np.int16)
    # Only NaN rows where a flux-corrupting bit is set
    bad = (q & int(_FLUX_CORRUPT_MASK)) != 0

    for col in out.columns:
        if col not in preserve:
            out.loc[bad, col] = np.nan
    return out
