# Modified SAP to allow PRF usage instead of just threshold-based masking
from astropy.wcs import WCS
from scipy.ndimage import gaussian_filter
from pathlib import Path
import numpy as np
import pandas as pd
import warnings
import copy
import matplotlib.pyplot as plt

# QUALITY_FLAG_BITS = {1: 1, 2: 2, 3: 4}

QUALITY_FLAG_BITS: dict = {
    0: np.int16(0),   # clean
    1: np.int16(1),   # quaternion jitter     [flux-corrupting]
    2: np.int16(2),   # background spike      [flux-corrupting]
    3: np.int16(4),   # centroid excursion    [diagnostic only — does NOT NaN flux]
    4: np.int16(8),   # outlier               [flux-corrupting]
}
#    
# Bitmask of all flags that corrupt photometry (used by apply_nan_to_flagged_rows)
# Includes quat(1) + bkg(2) + outlier(8); excludes centroid(4).
_FLUX_CORRUPT_MASK: np.int16 = np.int16(
    int(QUALITY_FLAG_BITS[1]) | int(QUALITY_FLAG_BITS[2]) | int(QUALITY_FLAG_BITS[4])
) 

_ALL_FLAG_IDS = frozenset(QUALITY_FLAG_BITS.keys())  # {0,1,2,3,4}

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from matplotlib.colors import Normalize
from astropy.io import fits
from astropy.wcs import WCS
from typing import Optional, Tuple, Callable


# ──────────────────────────────────────────────────────────────────────────────

def compute_prf_aperture_weights(
    hdu: fits.HDUList,
    reference_pixel: list,
    nearby_star_catalog: Optional[pd.DataFrame] = None,
    target_tmag: Optional[float] = None,
    cutoutsize: int = 11,
    prf_weight_threshold: float = 0.01,
    decontaminate: bool = True,
    prf_cache_dir: Optional[str] = None,
    verbose: bool = False,
) -> Tuple[np.ndarray, np.ndarray]:
    """
    Compute a PRF-based soft aperture weight map for a TESS TESScut cutout.

    Uses the official TESS PRF models via the ``TESS_PRF`` package (Bell &
    Higgins 2022, ascl:2207.008) to evaluate the expected pixel-level flux
    distribution of the target star. Optionally subtracts scaled PRF
    contributions from nearby TIC sources to decontaminate the weight map
    before thresholding.

    Intended as a toggle-gated complement to ``thresholdmask`` inside
    NEMESIS's ``SAP()`` via a ``use_prf_weights`` settings flag. Returns both
    a continuous weight map (for optimal flux extraction) and a binary mask
    (drop-in replacement for ``thresholdmask`` output).

    Flux extraction with the returned ``weight_map``::

        n_eff     = weight_map.sum()
        raw_flux  = np.nansum(flux_cube * weight_map[np.newaxis], axis=(1, 2))
        bkg_level = np.nanmedian(flux_cube[:, bkg_mask], axis=1)
        sap_flux  = raw_flux - bkg_level * n_eff

    Parameters
    ----------
    hdu : fits.HDUList
        TESScut HDUList from ``gethdu`` / ``gethdu_lksearch``. Requires a
        PIXELS extension (hdu[1]) with CAMERA, CCD, SECTOR header keywords
        and an APERTURE extension (hdu[2]) with a valid celestial WCS.
    reference_pixel : list of float
        [col, row] position of the target within the cutout (0-indexed pixel
        centers). Same value computed inside ``SAP()``.
    nearby_star_catalog : pd.DataFrame, optional
        TIC neighbor catalog from ``collect_nearby_TIC_params``. Expected
        columns (case-insensitive): 'ra', 'dec', 'Tmag'.
    target_tmag : float, optional
        TESS magnitude of the target. Required for decontamination. If None,
        decontamination is skipped even when ``decontaminate=True``.
    cutoutsize : int, optional
        Side length of the square cutout in pixels. Default: 11.
    prf_weight_threshold : float, optional
        Pixels with ``weight < prf_weight_threshold * peak`` are excluded from
        ``pix_mask``. Default: 0.01 (1% of peak).
    decontaminate : bool, optional
        Subtract scaled neighbor PRF models from the target PRF prior to
        thresholding. Default: True.
    prf_cache_dir : str, optional
        Path to a local PRF cache directory as produced by
        ``cache_tess_prf()`` / ``prefetch_prf()``. The expected layout is::

            <prf_cache_dir>/
              start_s0001/cam1_ccd1/  ...   (Sectors 1–3)
              start_s0004/cam1_ccd1/  ...   (Sectors 4+)

        If None, ``TESS_PRF`` fetches files from MAST on every instantiation
        (requires internet; slow for bulk runs).
    verbose : bool, optional
        Print progress messages. Default: False.

    Returns
    -------
    weight_map : np.ndarray, shape (cutoutsize, cutoutsize), float64
        Unnormalized PRF weight map. ``weight_map.sum()`` gives the effective
        aperture area in pixels.
    pix_mask : np.ndarray, shape (cutoutsize, cutoutsize), bool
        Binary aperture mask. Drop-in replacement for ``thresholdmask`` output.

    Notes
    -----
    - Falls back to an isotropic 2D Gaussian (sigma=0.85 px, FWHM≈2 px) if
      ``TESS_PRF`` is unavailable or PRF instantiation fails.
    - Decontamination subtracts scaled neighbor PRFs; it is not a full
      forward-model scene fit. For >3 bright neighbors within 1 px, prefer
      TGLC-style scene modeling.

    Examples
    --------
    >>> weight_map, pix_mask = compute_prf_aperture_weights(
    ...     hdu=hdu,
    ...     reference_pixel=reference_pixel,
    ...     nearby_star_catalog=nearby_cat,
    ...     target_tmag=12.3,
    ...     prf_cache_dir='/path/to/prf_cache',
    ...     verbose=True,
    ... )
    """
    from pathlib import Path

    hdr0 = hdu[0].header
    hdr1 = hdu[1].header

    # ── Step 1: Read cam / CCD / sector from header ───────────────────────────
    cam    = int(hdr0.get('CAMERA', hdr1.get('CAMERA', 1)))
    ccd    = int(hdr0.get('CCD',    hdr1.get('CCD',    1)))
    sector = int(hdr0.get('SECTOR', hdr1.get('SECTOR', 1)))

    # CCD-level pixel coordinate of the cutout center — used to interpolate
    # the nearest PRF from the 5×5 MAST grid. Approximate is fine.
#     col_ccd = float(hdr1.get('1CRV5P', cutoutsize // 2))
#     row_ccd = float(hdr1.get('2CRV5P', cutoutsize // 2))

    col_ccd = float(hdr1.get('1CRV5P'))
    row_ccd = float(hdr1.get('2CRV5P'))

    if verbose:
        print(f'  [PRF] cam={cam} ccd={ccd} sector={sector} '
              f'col_ccd={col_ccd:.0f} row_ccd={row_ccd:.0f}')

    # ── Derive star position from aperture WCS (preferred over reference_pixel) ─
    # reference_pixel from gethdu may use a different coordinate convention than
    # TESS_PRF.locate(), which expects 0-indexed cutout pixel coords aligned with
    # the aperture-extension WCS. Recomputing from RA_OBJ/DEC_OBJ is robust.
    ref_col = float(reference_pixel[0])
    ref_row = float(reference_pixel[1])
    try:
        ra_obj  = hdu[0].header.get('RA_OBJ',  hdu[1].header.get('RA_OBJ'))
        dec_obj = hdu[0].header.get('DEC_OBJ', hdu[1].header.get('DEC_OBJ'))
        if ra_obj is not None and dec_obj is not None:
            wcs_ap = WCS(hdu[2])
            px = wcs_ap.all_world2pix([[float(ra_obj), float(dec_obj)]], 0)
            ref_col = float(px[0, 0])
            ref_row = float(px[0, 1])
            if verbose:
                print(f'  [PRF] star position from WCS: '
                      f'col={ref_col:.2f} row={ref_row:.2f}')
        elif verbose:
            print('  [PRF] RA_OBJ/DEC_OBJ missing; '
                  'using passed reference_pixel for locate().')
    except Exception as exc:
        if verbose:
            print(f'  [PRF] WCS position failed ({exc}); '
                  'using passed reference_pixel.')

    # ── Step 2: Gaussian fallback ─────────────────────────────────────────────
    def _gaussian_fallback(col: float, row: float) -> np.ndarray:
        """Isotropic 2D Gaussian, sigma=0.85 px (FWHM ≈ 2 px)."""
        y, x = np.mgrid[:cutoutsize, :cutoutsize]
        return np.exp(
            -((x - col) ** 2 + (y - row) ** 2) / (2 * 0.85 ** 2)
        ).astype(np.float64)

    # ── Step 3: Instantiate TESS PRF model ────────────────────────────────────
    prf_model = None
    try:
        import PRF  # pip install TESS_PRF

        if prf_cache_dir is not None:
            epoch_dir = 'start_s0001' if sector <= 3 else 'start_s0004'
            local_dir = str(Path(prf_cache_dir) / epoch_dir)
            prf_model = PRF.TESS_PRF(
                cam, ccd, sector, col_ccd, row_ccd,
                localdatadir=local_dir,
            )
            if verbose:
                print(f'  [PRF] loaded from local cache: {local_dir}')
        else:
            prf_model = PRF.TESS_PRF(cam, ccd, sector, col_ccd, row_ccd)
            if verbose:
                print('  [PRF] loaded from MAST (no local cache set).')

    except ImportError:
        if verbose:
            print('  [PRF] TESS_PRF not installed; using Gaussian fallback.')
    except Exception as exc:
        if verbose:
            print(f'  [PRF] instantiation failed ({exc}); Gaussian fallback.')

    # ── Step 4: Evaluate target PRF at sub-pixel reference position ───────────
    if prf_model is not None:
        try:
            target_prf = np.asarray(
                prf_model.locate(ref_col, ref_row, (cutoutsize, cutoutsize)),
                dtype=np.float64,
            )
        except Exception as exc:
            if verbose:
                print(f'  [PRF] locate() failed ({exc}); Gaussian fallback.')
            target_prf = _gaussian_fallback(ref_col, ref_row)
    else:
        target_prf = _gaussian_fallback(ref_col, ref_row)

    target_prf = np.clip(np.nan_to_num(target_prf, nan=0.0), 0.0, None)

    # ── Step 5: Decontaminate with nearby TIC sources ─────────────────────────
    if decontaminate and nearby_star_catalog is not None and target_tmag is not None:
        wcs = None
        try:
            wcs = WCS(hdu[2])
        except Exception as exc:
            if verbose:
                print(f'  [PRF] WCS unavailable ({exc}); skipping decontamination.')

        if wcs is not None and len(nearby_star_catalog) > 0:
            col_lower = {c.lower(): c for c in nearby_star_catalog.columns}
            ra_key  = col_lower.get('ra')  or col_lower.get('raj2000')
            dec_key = col_lower.get('dec') or col_lower.get('decj2000')
            mag_key = (col_lower.get('tmag') or col_lower.get('tessmag')
                       or col_lower.get('tess_mag'))

            if ra_key and dec_key and mag_key:
                n_sub = 0
                for _, nb in nearby_star_catalog.iterrows():
                    try:
                        px = wcs.all_world2pix(
                            [[float(nb[ra_key]), float(nb[dec_key])]], 0
                        )
                        nb_col, nb_row = float(px[0, 0]), float(px[0, 1])

                        if not (0 <= nb_col < cutoutsize
                                and 0 <= nb_row < cutoutsize):
                            continue
                        if np.hypot(nb_col - ref_col, nb_row - ref_row) < 0.5:
                            continue

                        flux_ratio = 10.0 ** (
                            -0.4 * (float(nb[mag_key]) - target_tmag)
                        )

                        if prf_model is not None:
                            try:
                                nb_prf = np.asarray(
                                    prf_model.locate(
                                        nb_col, nb_row, (cutoutsize, cutoutsize)
                                    ),
                                    dtype=np.float64,
                                )
                            except Exception:
                                nb_prf = _gaussian_fallback(nb_col, nb_row)
                        else:
                            nb_prf = _gaussian_fallback(nb_col, nb_row)

                        nb_prf = np.clip(np.nan_to_num(nb_prf, nan=0.0), 0.0, None)
                        target_prf -= flux_ratio * nb_prf
                        n_sub += 1

                    except Exception as exc:
                        if verbose:
                            print(f'  [PRF] skipping neighbor: {exc}')

                if verbose and n_sub:
                    print(f'  [PRF] subtracted {n_sub} neighbor PRF(s).')
            elif verbose:
                print('  [PRF] could not resolve ra/dec/Tmag columns; '
                      'skipping decontamination.')

    # ── Step 6: Clip, threshold, build binary mask ────────────────────────────
    target_prf = np.clip(target_prf, 0.0, None)
    peak = target_prf.max()

    if peak <= 0.0:
        if verbose:
            print('  [PRF] weight map collapsed after decontamination; '
                  'reverting to Gaussian fallback.')
        target_prf = _gaussian_fallback(ref_col, ref_row)
        peak = target_prf.max()

    weight_map = target_prf.astype(np.float64)
    pix_mask   = weight_map > (prf_weight_threshold * peak)

    if verbose:
        print(f'  [PRF] n_pix={pix_mask.sum()}  '
              f'n_eff={weight_map.sum():.3f}  peak={peak:.4f}')

    return weight_map, pix_mask


def _compute_per_cadence_centroid(
    flux: np.ndarray,
    hdu,
    reference_pixel: list,
    threshold: float = 3.5,
    use_circ: bool = True,
    precomputed_mask: np.ndarray = None,
) -> tuple:
    """
    Compute per-cadence quadratic centroids using an independent loose
    threshold mask, NOT the PRF pix_mask, eliminating the self-referential
    bias present in the original SAP_ALT2 Step 4 inline centroid loop.

    The original code called ``centroid_quadratic(flux[t], pix_mask, ...)``,
    where ``pix_mask`` was derived from the PRF model. If that model was
    miscentered (WCS error, PRF grid interpolation offset), the centroid
    window was biased, which propagated into ``_prf_m.locate()`` per cadence
    — a compounding feedback loop.

    This function builds the spatial window from ``thresholdmask`` at a
    deliberately lower threshold than the SAP aperture (default 3.5σ) so
    the window is generous and independent of any PRF model. ``use_centroid``
    is forced False to avoid any circular seeding.

    Parameters
    ----------
    flux : np.ndarray, shape (N, ny, nx)
        Quality-masked flux cube.
    hdu : fits.HDUList
        TESScut HDUList — passed to ``thresholdmask`` for WCS/header access.
    reference_pixel : list of float
        [col, row] target position in cutout coordinates (0-indexed).
    threshold : float
        Sigma threshold for the loose centroid window mask. Default 3.5.
        Keep below the SAP aperture threshold; raising this narrows the
        window and increases centroid sensitivity to PRF model error.
        Ignored when ``precomputed_mask`` is provided.
    use_circ : bool
        Forwarded to ``thresholdmask`` for the circular fallback aperture.
        Ignored when ``precomputed_mask`` is provided.
    precomputed_mask : np.ndarray[bool], shape (ny, nx), optional
        If provided, skip the internal ``thresholdmask`` call and use this
        mask directly as the centroid window. Pass ``pix_mask`` here when
        in threshold aperture mode so that SAP and SAP_ALT2 produce
        identical centroids on the default path.

    Returns
    -------
    centx : np.ndarray, shape (N,)
        Per-cadence centroid column (x) positions. NaN where estimation
        failed.
    centy : np.ndarray, shape (N,)
        Per-cadence centroid row (y) positions. NaN where estimation
        failed.

    Examples
    --------
    >>> centx, centy = _compute_per_cadence_centroid(
    ...     flux, hdu, reference_pixel, threshold=3.5, use_circ=True)
    >>> print(f'median centroid: ({np.nanmedian(centx):.2f}, {np.nanmedian(centy):.2f})')
    """
    N = flux.shape[0]
    centx = np.full(N, np.nan)
    centy = np.full(N, np.nan)

    # Build spatial window independently of any PRF model.
    # use_centroid=False: prevents any centroid-seeding of the mask itself,
    # which would reintroduce a circular dependency.
    loose_mask = None
    try:
        loose_mask = thresholdmask(
            hdu,
            reference_pixel,
            threshold=threshold,
            use_centroid=False,
            use_circ=use_circ,
        )
    except Exception:
        pass

    if loose_mask is None or not np.any(loose_mask):
        # Last-resort 3×3 box centred on reference pixel.
        ny, nx = flux.shape[1], flux.shape[2]
        loose_mask = np.zeros((ny, nx), dtype=bool)
        r = int(round(float(reference_pixel[1])))
        c = int(round(float(reference_pixel[0])))
        loose_mask[
            max(0, r - 1):min(ny, r + 2),
            max(0, c - 1):min(nx, c + 2),
        ] = True

    for t in range(N):
        try:
            cx, cy = centroid_quadratic(flux[t], loose_mask, reference_pixel)
            centx[t] = float(cx)
            centy[t] = float(cy)
        except Exception:
            pass

    return centx, centy


# -----------------------------------------------------------------------------
# Helper 2 — fixes Critiques 1, 2, 4, 6
# Drop this function directly above SAP_ALT2 in the script.
# -----------------------------------------------------------------------------

def _prf_weighted_flux_pass(
    flux: np.ndarray,
    prf_model,
    ref_col: float,
    ref_row: float,
    centx: np.ndarray,
    centy: np.ndarray,
    bkg_level_per_pix: np.ndarray,
    cutoutsize: int,
    centroid_guard: float = 2.0,
    coverage_threshold: float = 0.75,
    rms_tolerance: float = 1.10,
    rawsap_flux_ref: np.ndarray = None,
    verbose: bool = False,
) -> tuple:
    """
    Per-cadence PRF-weighted flux extraction with corrected normalization and
    improved acceptance criteria. Replaces the Step 4b inline block in the
    original SAP_ALT2.

    The original implementation had four compounding errors:

    1. **Wrong normalization** — divided by ``sum(w²)`` (the matched-filter
       denominator), producing a flux density estimate incompatible with the
       threshold path's aperture sum. Transit depths were systematically
       suppressed because ``sum(w²) < sum(w)`` for fractional weights, and
       the suppression factor varies across cadences. PLD pixel regressors
       built from the raw flux cube have no knowledge of the per-cadence
       ``sum(w²)`` denominator, so detrending further corrupted the signal.

    2. **Mixed L1/L2 norms** — background was subtracted as
       ``bkg × sum(w)`` but the whole result was divided by ``sum(w²)``.
       These two scalings are only equal for binary masks. For soft PRF
       weights the mismatch creates a per-cadence bias that is correlated
       with the PRF shape (and therefore with any centroid drift).

    3. **Weak coverage criterion** — acceptance required only ``N/2``
       valid cadences. Cadences most likely to fail the centroid guard are
       those with elevated jitter or systematics, which are
       disproportionately the same cadences where transit-like dips occur.
       The ``N/2`` check does not catch a second-pass flux with NaN gaps
       concentrated at transit phase.

    4. **No RMS guard** — a noisier PRF flux could silently replace the
       step-3 result if cadence coverage exceeded the threshold.

    This function uses the aperture-sum convention: ``nansum(flux × w)``,
    with background subtracted as ``bkg_per_pix × sum(w)``. When ``w`` is
    binary (threshold path), this reduces exactly to ``nansum(flux * mask)``
    — making PRF and threshold outputs directly comparable and downstream
    PLD / BLS behaviour consistent.

    Parameters
    ----------
    flux : np.ndarray, shape (N, ny, nx)
        Quality-masked flux cube.
    prf_model : PRF.TESS_PRF
        Already-instantiated ``TESS_PRF`` object. **Instantiate once in the
        caller; do not pass None or re-instantiate per cadence.**
    ref_col, ref_row : float
        WCS-derived star position in cutout pixel coordinates (0-indexed).
        Used as fallback when the centroid exceeds ``centroid_guard``.
    centx, centy : np.ndarray, shape (N,)
        Per-cadence centroid estimates from ``_compute_per_cadence_centroid``
        (image-centroid mode) or from ``ref_col/row + pos_corr`` (POS_CORR
        mode). NaN entries fall back to ``ref_col / ref_row`` automatically.
    bkg_level_per_pix : np.ndarray, shape (N,)
        Per-pixel background from ``extract_background_flux``. Must be
        the same array used in the step-3 extraction — do not recompute
        with a different aperture after calling this function.
    cutoutsize : int
        Cutout side-length in pixels.
    centroid_guard : float
        Maximum allowed deviation (px) of centx/centy from
        ref_col/ref_row before the cadence falls back to the reference
        position. Default 2.0.
    coverage_threshold : float
        Minimum fraction of cadences that must be finite for the result
        to be accepted. Default 0.75 (raised from the original 0.50).
    rms_tolerance : float
        Second-pass accepted only if its point-to-point RMS ≤
        ``rms_tolerance × RMS(rawsap_flux_ref)``. Default 1.10
        (10 % slack). Set to ``np.inf`` to disable the RMS check.
    rawsap_flux_ref : np.ndarray, shape (N,), optional
        Step-3 (threshold or static-PRF) SAP flux used for RMS comparison.
        If None, the RMS check is skipped.
    verbose : bool

    Returns
    -------
    rawflux_out : np.ndarray, shape (N,)
        Weighted aperture sum before background subtraction (same units as
        the step-3 ``rawflux``).
    rawsap_flux_out : np.ndarray, shape (N,)
        Background-subtracted weighted aperture sum (same units and scale
        as the step-3 ``rawsap_flux``).
    accepted : bool
        True if the result passed both the coverage and RMS criteria.
        When False the caller should retain the step-3 flux unchanged.

    Examples
    --------
    >>> rf, rsf, ok = _prf_weighted_flux_pass(
    ...     flux, prf_model, ref_col, ref_row,
    ...     centx, centy, bkg_level_per_pix,
    ...     cutoutsize=11,
    ...     rawsap_flux_ref=rawsap_flux,
    ...     verbose=True,
    ... )
    >>> if ok:
    ...     rawflux, rawsap_flux = rf, rsf
    """
    N = flux.shape[0]
    rawflux_c = np.full(N, np.nan)
    rawsap_c  = np.full(N, np.nan)

    for t in range(N):
        # Use centroid if finite and within guard; otherwise fall back to ref.
        _cx = (centx[t]
               if (np.isfinite(centx[t]) and abs(centx[t] - ref_col) < centroid_guard)
               else ref_col)
        _cy = (centy[t]
               if (np.isfinite(centy[t]) and abs(centy[t] - ref_row) < centroid_guard)
               else ref_row)

        try:
            wt = np.clip(
                np.nan_to_num(
                    np.asarray(
                        prf_model.locate(_cx, _cy, (cutoutsize, cutoutsize)),
                        dtype=np.float64,
                    )
                ),
                0.0, None,
            )
            w_sum = float(wt.sum())
            if w_sum <= 0.0:
                continue

            # FIX 1 & 2: aperture-sum convention with consistent L1 background.
            # raw = nansum(flux * w)           — same scale as threshold path
            # bkg = bkg_per_pix * sum(w)       — L1 background, consistent with raw
            # No division by sum(w²): that matched-filter denominator changes
            # the flux scale per-cadence and suppresses transit depth.
            raw          = float(np.nansum(flux[t] * wt))
            bkg_contrib  = float(bkg_level_per_pix[t]) * w_sum
            rawflux_c[t] = raw
            rawsap_c[t]  = raw - bkg_contrib

        except Exception:
            pass

    n_valid = int(np.sum(np.isfinite(rawsap_c)))

    # FIX 3: stricter coverage criterion (0.75 vs original 0.50).
    if n_valid < int(coverage_threshold * N):
        if verbose:
            print(f'  [PRF pass] rejected: {n_valid}/{N} finite cadences '
                  f'(need ≥{coverage_threshold:.0%}); retaining step-3 flux.')
        return rawflux_c, rawsap_c, False

    # FIX 4: RMS guard — reject if the second pass is noisier than step-3.
    if rawsap_flux_ref is not None:
        fin_ref = rawsap_flux_ref[np.isfinite(rawsap_flux_ref)]
        fin_new = rawsap_c[np.isfinite(rawsap_c)]
        if fin_ref.size > 1 and fin_new.size > 1:
            rms_ref = float(np.std(np.diff(fin_ref)))
            rms_new = float(np.std(np.diff(fin_new)))
            if rms_ref > 0.0 and rms_new > rms_tolerance * rms_ref:
                if verbose:
                    print(f'  [PRF pass] rejected: point-to-point RMS '
                          f'{rms_new:.4e} > {rms_tolerance}× ref {rms_ref:.4e}; '
                          f'retaining step-3 flux.')
                return rawflux_c, rawsap_c, False

    if verbose:
        print(f'  [PRF pass] accepted: {n_valid}/{N} finite cadences.')

    return rawflux_c, rawsap_c, True


def mask_out_neighbor_pixels_OLD(
    hdu,
    pix_mask: np.ndarray,
    nearby_star_catalog: pd.DataFrame,
    ID: int,
    reference_pixel: list,
    delta_tmag_threshold: float = 5.0,
    neighbor_excision_radius: float = 1.5,
    blend_threshold_px: float = 2.0,
    min_aperture_pixels: int = 2,
    verbose: bool = False,
) -> tuple:
    """
    Excise aperture pixels contaminated by neighboring stars, with a
    separation-based gate that escalates sub-pixel blends to PRF
    decontamination rather than attempting pixel excision.

    Decision logic (per qualifying neighbor, in order):
        1. ΔTmag >= delta_tmag_threshold  →  skip (flux contribution < ~1%)
        2. separation < blend_threshold_px →  flag as blended; skip excision;
                                              set diagnostics['has_blended_neighbor']
                                              so the caller can escalate to
                                              compute_prf_aperture_weights(decontaminate=True)
        3. otherwise                       →  excise all aperture pixels within
                                              neighbor_excision_radius of the
                                              neighbor's centroid (excluding the
                                              target's reference pixel)

    Neighbor positions are computed DIFFERENTIALLY: the neighbor's WCS offset
    from the target is applied to reference_pixel, cancelling any absolute WCS
    registration error between hdu[2] and the reference_pixel origin.

    Parameters
    ----------
    hdu : fits.HDUList
        TESS FFI/TPF HDU. Requires aperture extension (hdu[2]) with a valid
        celestial WCS.
    pix_mask : np.ndarray, shape (ny, nx), bool
        Current binary aperture mask. Not modified in-place; a copy is returned.
    nearby_star_catalog : pd.DataFrame
        TIC neighbor catalog from collect_nearby_TIC_params.
        Required columns: 'ID' (or 'id'), 'ra', 'dec', 'Tmag' (or 'tmag').
        Column names are matched case-insensitively.
    ID : int
        TIC identifier of the target star.
    reference_pixel : list of float
        [col, row] position of the target within the cutout (0-indexed).
        This pixel is never excised.
    delta_tmag_threshold : float, optional
        Neighbors with ΔTmag >= this value are skipped entirely.
        Default 5.0 (~1% flux contribution threshold).
    neighbor_excision_radius : float, optional
        For neighbors that pass the blend gate, all aperture pixels within
        this many pixels of the neighbor centroid are excised. Default 1.5 px.
    blend_threshold_px : float, optional
        Neighbors closer than this pixel separation from reference_pixel are
        considered unresolvable by pixel excision. They are skipped, and
        diagnostics['has_blended_neighbor'] is set True so the caller can
        escalate to PRF decontamination. Default 2.0 px.
        Rule of thumb: set to ~2 × TESS PSF FWHM (~1 px) = 2.0 px.
    min_aperture_pixels : int, optional
        Minimum pixels required in the trimmed mask before accepting the edit.
        Default 2. If excision would go below this, the original mask is
        returned and diagnostics['reverted'] is True.
    verbose : bool, optional
        Print per-neighbor diagnostics. Default False.

    Returns
    -------
    trimmed_mask : np.ndarray, shape (ny, nx), bool
        Modified aperture mask. Identical to pix_mask if no neighbors
        qualified, all were blended, or excision was reverted.
    diagnostics : dict
        Keys:
        - 'contaminants_in_aperture' : pd.DataFrame
            Qualifying neighbors with at least one pixel within
            neighbor_excision_radius of their centroid (excision candidates only).
        - 'blended_neighbors' : pd.DataFrame
            Neighbors below blend_threshold_px that were skipped.
        - 'has_blended_neighbor' : bool
            True if any qualifying neighbor was closer than blend_threshold_px.
            This is the escalation flag for the caller.
        - 'pixels_excised' : list of (col, row) int tuples
        - 'n_pixels_before' : int
        - 'n_pixels_after' : int
        - 'reverted' : bool
        - 'wcs_failed' : bool

    Notes
    -----
    Escalation pattern in SAP() after Step 2b::

        pix_mask, _diag = mask_out_neighbor_pixels(
            hdu=hdu, pix_mask=pix_mask,
            nearby_star_catalog=nearby_star_catalog,
            ID=ID, reference_pixel=reference_pixel,
            delta_tmag_threshold=default_settings.get('neighbor_excision_dtmag', 5.0),
            neighbor_excision_radius=default_settings.get('neighbor_excision_radius', 1.5),
            blend_threshold_px=default_settings.get('neighbor_blend_threshold_px', 2.0),
            min_aperture_pixels=default_settings.get('neighbor_excision_min_pix', 2),
            verbose=verbose,
        )
        if _diag['has_blended_neighbor'] or _diag['reverted']:
            pix_mask = compute_prf_aperture_weights(
                hdu, reference_pixel, nearby_star_catalog, ID,
                decontaminate=True,
            )

    Examples
    --------
    >>> trimmed, diag = mask_out_neighbor_pixels(
    ...     hdu=hdu, pix_mask=pix_mask,
    ...     nearby_star_catalog=nearby_cat,
    ...     ID=55650590, reference_pixel=[6.0, 6.0],
    ...     blend_threshold_px=2.0, verbose=True,
    ... )
    >>> if diag['has_blended_neighbor']:
    ...     print('Blend detected — escalate to PRF decontamination.')
    """
    diag = {
        'contaminants_in_aperture': pd.DataFrame(),
        'blended_neighbors':        pd.DataFrame(),
        'has_blended_neighbor':     False,
        'pixels_excised':           [],
        'n_pixels_before':          int(pix_mask.sum()),
        'n_pixels_after':           int(pix_mask.sum()),
        'reverted':                 False,
        'wcs_failed':               False,
    }

    if nearby_star_catalog is None or nearby_star_catalog.empty:
        return pix_mask.copy(), diag

    # ── Case-insensitive column lookup ────────────────────────────────────
    col_map = {c.lower(): c for c in nearby_star_catalog.columns}

    def _getcol(df, name):
        return df[col_map[name.lower()]]

    try:
        _ = col_map['id'], col_map['ra'], col_map['dec'], col_map['tmag']
    except KeyError as e:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] Missing required column {e}. '
            'Returning original mask.',
            UserWarning, stacklevel=2,
        )
        return pix_mask.copy(), diag

    # ── WCS ───────────────────────────────────────────────────────────────
    try:
        wcs_ap = WCS(hdu[2])
    except Exception as exc:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] WCS init failed: {exc}. '
            'Returning original mask.',
            UserWarning, stacklevel=2,
        )
        diag['wcs_failed'] = True
        return pix_mask.copy(), diag

    # ── Target row ────────────────────────────────────────────────────────
    ids = _getcol(nearby_star_catalog, 'id').astype(str)
    target_rows = nearby_star_catalog[ids == str(ID)]
    if target_rows.empty:
        if verbose:
            print(f'  [mask_out_neighbor_pixels] TIC {ID} not in catalog.')
        return pix_mask.copy(), diag

    target_tmag = float(_getcol(target_rows, 'tmag').iloc[0])
    target_ra   = float(_getcol(target_rows, 'ra').iloc[0])
    target_dec  = float(_getcol(target_rows, 'dec').iloc[0])

    ref_col = float(reference_pixel[0])
    ref_row = float(reference_pixel[1])

    # ── WCS anchor for differential positioning ───────────────────────────
    # All neighbor positions are expressed as offsets from the target's WCS
    # pixel position, then anchored to reference_pixel. This cancels any
    # absolute WCS registration error between hdu[2] and reference_pixel.
    try:
        tgt_px      = wcs_ap.all_world2pix([[target_ra, target_dec]], 0)
        tgt_wcs_col = float(tgt_px[0, 0])
        tgt_wcs_row = float(tgt_px[0, 1])
    except Exception as exc:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] WCS projection of target '
            f'failed: {exc}. Returning original mask.',
            UserWarning, stacklevel=2,
        )
        diag['wcs_failed'] = True
        return pix_mask.copy(), diag

    if verbose:
        print(f'  [mask_out_neighbor_pixels] WCS target: '
              f'({tgt_wcs_col:.3f}, {tgt_wcs_row:.3f})  '
              f'reference_pixel: ({ref_col:.3f}, {ref_row:.3f})  '
              f'offset: (Δcol={ref_col - tgt_wcs_col:+.3f}, '
              f'Δrow={ref_row - tgt_wcs_row:+.3f})')

    # ── Neighbor WCS projection (differential) ────────────────────────────
    neighbors = nearby_star_catalog[ids != str(ID)].copy()
    if neighbors.empty:
        return pix_mask.copy(), diag

    try:
        world = np.column_stack([
            _getcol(neighbors, 'ra').to_numpy(dtype=float),
            _getcol(neighbors, 'dec').to_numpy(dtype=float),
        ])
        px_coords = wcs_ap.all_world2pix(world, 0)
    except Exception as exc:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] WCS projection failed: {exc}. '
            'Returning original mask.',
            UserWarning, stacklevel=2,
        )
        diag['wcs_failed'] = True
        return pix_mask.copy(), diag

    neighbors = neighbors.copy()
    neighbors['_px_col']     = ref_col + (px_coords[:, 0] - tgt_wcs_col)
    neighbors['_px_row']     = ref_row + (px_coords[:, 1] - tgt_wcs_row)
    neighbors['_delta_tmag'] = (
        _getcol(neighbors, 'tmag').to_numpy(dtype=float) - target_tmag
    )
    neighbors['_sep_px'] = np.sqrt(
        (neighbors['_px_col'] - ref_col) ** 2
        + (neighbors['_px_row'] - ref_row) ** 2
    )

    ny, nx = pix_mask.shape
    ap_rows, ap_cols = np.where(pix_mask)

    trimmed        = pix_mask.copy()
    excised        = []
    qualifying     = []
    blended        = []

    for _, nb in neighbors.iterrows():
        dtmag  = float(nb['_delta_tmag'])
        sep_px = float(nb['_sep_px'])
        nb_id  = nb[col_map['id']]

        # Gate 1: flux contribution below threshold
        if dtmag >= delta_tmag_threshold:
            continue

        # Gate 2: too close to excise -- flag for PRF escalation
        if sep_px < blend_threshold_px:
            blended.append(nb)
            diag['has_blended_neighbor'] = True
            if verbose:
                print(f'  [mask_out_neighbor_pixels] TIC {nb_id} '
                      f'ΔTmag={dtmag:+.2f}  sep={sep_px:.2f} px  '
                      f'< blend_threshold={blend_threshold_px} px  '
                      f'→ BLENDED: skipping excision, flagging for PRF.')
            continue

        # Gate 3: excise pixels within neighbor_excision_radius
        nb_col_f = float(nb['_px_col'])
        nb_row_f = float(nb['_px_row'])

        dists = np.sqrt(
            (ap_cols - nb_col_f) ** 2 + (ap_rows - nb_row_f) ** 2
        )
        within = dists <= neighbor_excision_radius

        if not within.any():
            if verbose:
                print(f'  [mask_out_neighbor_pixels] TIC {nb_id} '
                      f'ΔTmag={dtmag:+.2f}  sep={sep_px:.2f} px  '
                      f'no aperture pixels within r={neighbor_excision_radius} px.')
            continue

        qualifying.append(nb)
        pixels_to_excise = list(zip(
            ap_cols[within].tolist(),
            ap_rows[within].tolist(),
        ))

        if verbose:
            print(f'  [mask_out_neighbor_pixels] TIC {nb_id} '
                  f'ΔTmag={dtmag:+.2f}  sep={sep_px:.2f} px  '
                  f'centroid=({nb_col_f:.2f},{nb_row_f:.2f})  '
                  f'excising {len(pixels_to_excise)} pixel(s): {pixels_to_excise}')

        for c, r in pixels_to_excise:
            if abs(c - ref_col) < 0.5 and abs(r - ref_row) < 0.5:
                if verbose:
                    print(f'    Skipping ({c},{r}): target reference pixel.')
                continue
            if trimmed[r, c]:
                trimmed[r, c] = False
                excised.append((c, r))

    # ── Store blend diagnostics regardless of excision outcome ───────────
    if blended:
        diag['blended_neighbors'] = pd.DataFrame(blended)
    if qualifying:
        diag['contaminants_in_aperture'] = pd.DataFrame(qualifying)

    # ── Revert if aperture too small ──────────────────────────────────────
    if excised and int(trimmed.sum()) < min_aperture_pixels:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] Excision would reduce aperture '
            f'to {int(trimmed.sum())} pixel(s) (< min={min_aperture_pixels}). '
            f'Reverting. Caller should escalate to PRF decontamination.',
            UserWarning, stacklevel=2,
        )
        diag['reverted']      = True
        diag['pixels_excised'] = []
        diag['n_pixels_after'] = int(pix_mask.sum())
        return pix_mask.copy(), diag

    diag['pixels_excised'] = excised
    diag['n_pixels_after'] = int(trimmed.sum())

    if verbose:
        n_excised = diag['n_pixels_before'] - diag['n_pixels_after']
        print(f'  [mask_out_neighbor_pixels] Summary: '
              f'{diag["n_pixels_before"]} → {diag["n_pixels_after"]} px  '
              f'({n_excised} excised)  '
              f'blended={diag["has_blended_neighbor"]}  '
              f'reverted={diag["reverted"]}')

    return trimmed, diag


import numpy as np
import pandas as pd
import warnings
from astropy.wcs import WCS


def mask_out_neighbor_pixels(
    hdu,
    pix_mask: np.ndarray,
    nearby_star_catalog: pd.DataFrame,
    ID: int,
    reference_pixel: list,
    delta_tmag_threshold: float = 5.0,
    neighbor_excision_radius: float = 1.5,
    blend_threshold_px: float = 2.0,
    blend_shrink_radius: float = 1.5,
    min_aperture_pixels: int = 2,
    verbose: bool = False,
) -> tuple:
    """
    Excise aperture pixels contaminated by neighboring stars.

    Decision logic (per qualifying neighbor, in order):
        1. ΔTmag >= delta_tmag_threshold  -> skip (flux contribution < ~1%)
        2. separation < blend_threshold_px -> flag as blended; apply
           target-centric shrink (see below); set has_blended_neighbor=True
        3. otherwise                       -> excise all aperture pixels within
           neighbor_excision_radius of the neighbor's centroid, excluding the
           target reference pixel

    Blended-branch shrink:
        When a neighbor is too close to excise directly (case 2), the aperture
        is trimmed to pixels within `blend_shrink_radius` of `reference_pixel`.
        This reduces the neighbor's PSF-wing contribution without attempting to
        resolve the PSF cores. HAS_BLENDED_NEIGHBOR is set regardless.
        If the shrink would drop the aperture below `min_aperture_pixels`, the
        shrink is skipped (aperture left unchanged) and `blend_shrink_reverted`
        is set in diagnostics.

    Neighbor positions are computed DIFFERENTIALLY: the neighbor's WCS offset
    from the target is applied to reference_pixel, cancelling any absolute WCS
    registration error between hdu[2] and the reference_pixel origin.

    Parameters
    ----------
    hdu : fits.HDUList
        TESS FFI/TPF HDU. Requires aperture extension (hdu[2]) with valid WCS.
    pix_mask : np.ndarray, shape (ny, nx), bool
        Current binary aperture mask. Not modified in-place.
    nearby_star_catalog : pd.DataFrame
        TIC neighbor catalog from collect_nearby_TIC_params.
        Required columns: 'ID'/'id', 'ra', 'dec', 'Tmag'/'tmag'.
    ID : int
        TIC identifier of the target star.
    reference_pixel : list of float
        [col, row] position of the target in the cutout (0-indexed).
    delta_tmag_threshold : float
        Neighbors with ΔTmag >= this value are skipped. Default 5.0.
    neighbor_excision_radius : float
        For resolvable neighbors (sep >= blend_threshold_px), excise aperture
        pixels within this radius of the neighbor centroid. Default 1.5 px.
    blend_threshold_px : float
        Neighbors closer than this separation are classified as blended.
        Default 2.0 px.
    blend_shrink_radius : float
        When a blended neighbor is detected, retain only aperture pixels within
        this radius of reference_pixel. Default 1.5 px.
        Set to np.inf to disable shrinking (restores V3 behavior).
    min_aperture_pixels : int
        Minimum aperture size. Excision or shrink is reverted if the result
        would fall below this threshold. Default 2.
    verbose : bool
        Print per-neighbor diagnostics. Default False.

    Returns
    -------
    trimmed : np.ndarray, bool
        Modified aperture mask (copy of pix_mask with excisions/shrink applied).
    diag : dict
        Diagnostics:
            n_pixels_before     : int
            n_pixels_after      : int
            has_blended_neighbor: bool
            pixels_excised      : list of (col, row) tuples (resolvable path)
            reverted            : bool  (resolvable excision reverted)
            blend_shrink_reverted: bool (blended shrink reverted)
            blended_neighbors   : pd.DataFrame (rows that hit the blend gate)
            contaminants_in_aperture: pd.DataFrame (rows that were excised)
            wcs_failed          : bool

    Example
    -------
    >>> trimmed, diag = mask_out_neighbor_pixels(
    ...     hdu=hdu, pix_mask=pix_mask,
    ...     nearby_star_catalog=tic_catalog,
    ...     ID=220431469, reference_pixel=[5.001, 4.994],
    ...     blend_shrink_radius=1.5, verbose=True,
    ... )
    >>> print(diag['n_pixels_before'], '->', diag['n_pixels_after'])
    >>> print('blended:', diag['has_blended_neighbor'],
    ...       'shrink_reverted:', diag['blend_shrink_reverted'])
    """
    diag = {
        'n_pixels_before':        int(pix_mask.sum()),
        'n_pixels_after':         int(pix_mask.sum()),
        'has_blended_neighbor':   False,
        'pixels_excised':         [],
        'reverted':               False,
        'blend_shrink_reverted':  False,
        'blended_neighbors':      None,
        'contaminants_in_aperture': None,
        'wcs_failed':             False,
    }

    if nearby_star_catalog is None or nearby_star_catalog.empty:
        return pix_mask.copy(), diag

    # ------------------------------------------------------------------ #
    # Column-name normalisation (case-insensitive)
    # ------------------------------------------------------------------ #
    col_lower = {c.lower(): c for c in nearby_star_catalog.columns}
    def _getcol(df, name):
        return df[col_lower[name.lower()]]

    col_map = {
        'id':   col_lower.get('id',   col_lower.get('id',  None)),
        'ra':   col_lower['ra'],
        'dec':  col_lower['dec'],
        'tmag': col_lower.get('tmag', col_lower.get('tmag', None)),
    }
    # Resolve actual column names
    col_map['id']   = next((col_lower[k] for k in col_lower if k in ('id',)),   None)
    col_map['tmag'] = next((col_lower[k] for k in col_lower if k in ('tmag',)), None)
    if col_map['id']   is None: col_map['id']   = _getcol(nearby_star_catalog, 'ID').name
    if col_map['tmag'] is None: col_map['tmag'] = _getcol(nearby_star_catalog, 'Tmag').name

    ids = nearby_star_catalog[col_map['id']].astype(str).values
    try:
        target_row  = nearby_star_catalog[ids == str(ID)].iloc[0]
        target_tmag = float(target_row[col_map['tmag']])
    except IndexError:
        if verbose:
            print(f'  [mask_out_neighbor_pixels] TIC {ID} not found in catalog; '
                  f'returning original mask.')
        return pix_mask.copy(), diag

    ref_col, ref_row = float(reference_pixel[0]), float(reference_pixel[1])

    # ------------------------------------------------------------------ #
    # WCS setup (aperture extension hdu[2])
    # ------------------------------------------------------------------ #
    try:
        wcs_ap = WCS(hdu[2])
        tgt_wcs_col, tgt_wcs_row = wcs_ap.all_world2pix(
            [[float(_getcol(target_row.to_frame().T, 'ra').iloc[0]),
              float(_getcol(target_row.to_frame().T, 'dec').iloc[0])]], 0
        )[0]
    except Exception as exc:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] WCS setup failed: {exc}. '
            'Returning original mask.', UserWarning, stacklevel=2,
        )
        diag['wcs_failed'] = True
        return pix_mask.copy(), diag

    if verbose:
        print(f'  [mask_out_neighbor_pixels] WCS target: '
              f'({tgt_wcs_col:.3f}, {tgt_wcs_row:.3f})  '
              f'reference_pixel: ({ref_col:.3f}, {ref_row:.3f})  '
              f'offset: (Δcol={ref_col - tgt_wcs_col:+.3f}, '
              f'Δrow={ref_row - tgt_wcs_row:+.3f})')

    neighbors = nearby_star_catalog[ids != str(ID)].copy()
    if neighbors.empty:
        return pix_mask.copy(), diag

    try:
        world     = np.column_stack([
            _getcol(neighbors, 'ra').to_numpy(dtype=float),
            _getcol(neighbors, 'dec').to_numpy(dtype=float),
        ])
        px_coords = wcs_ap.all_world2pix(world, 0)
    except Exception as exc:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] WCS projection failed: {exc}. '
            'Returning original mask.', UserWarning, stacklevel=2,
        )
        diag['wcs_failed'] = True
        return pix_mask.copy(), diag

    neighbors = neighbors.copy()
    neighbors['_px_col']     = ref_col + (px_coords[:, 0] - tgt_wcs_col)
    neighbors['_px_row']     = ref_row + (px_coords[:, 1] - tgt_wcs_row)
    neighbors['_delta_tmag'] = (
        _getcol(neighbors, 'tmag').to_numpy(dtype=float) - target_tmag
    )
    neighbors['_sep_px'] = np.sqrt(
        (neighbors['_px_col'] - ref_col) ** 2
        + (neighbors['_px_row'] - ref_row) ** 2
    )

    ap_rows, ap_cols = np.where(pix_mask)
    trimmed          = pix_mask.copy()
    excised          = []
    qualifying       = []
    blended          = []

    for _, nb in neighbors.iterrows():
        dtmag  = float(nb['_delta_tmag'])
        sep_px = float(nb['_sep_px'])
        nb_id  = nb[col_map['id']]

        # Gate 1: negligible flux contribution
        if dtmag >= delta_tmag_threshold:
            continue

        # Gate 2: blended -- shrink aperture toward target instead of excising
        if sep_px < blend_threshold_px:
            blended.append(nb)
            diag['has_blended_neighbor'] = True
            if verbose:
                print(f'  [mask_out_neighbor_pixels] TIC {nb_id} '
                      f'ΔTmag={dtmag:+.2f}  sep={sep_px:.2f} px  '
                      f'< blend_threshold={blend_threshold_px} px  '
                      f'-> BLENDED: shrinking aperture to r<={blend_shrink_radius} px '
                      f'from reference_pixel.')
            continue  # shrink applied after loop (once, not per neighbor)

        # Gate 3: resolvable -- excise pixels near neighbor centroid
        nb_col_f = float(nb['_px_col'])
        nb_row_f = float(nb['_px_row'])
        dists    = np.sqrt(
            (ap_cols - nb_col_f) ** 2 + (ap_rows - nb_row_f) ** 2
        )
        within = dists <= neighbor_excision_radius

        if not within.any():
            if verbose:
                print(f'  [mask_out_neighbor_pixels] TIC {nb_id} '
                      f'ΔTmag={dtmag:+.2f}  sep={sep_px:.2f} px  '
                      f'no aperture pixels within r={neighbor_excision_radius} px.')
            continue

        qualifying.append(nb)
        pixels_to_excise = list(zip(
            ap_cols[within].tolist(),
            ap_rows[within].tolist(),
        ))

        if verbose:
            print(f'  [mask_out_neighbor_pixels] TIC {nb_id} '
                  f'ΔTmag={dtmag:+.2f}  sep={sep_px:.2f} px  '
                  f'centroid=({nb_col_f:.2f},{nb_row_f:.2f})  '
                  f'excising {len(pixels_to_excise)} pixel(s): {pixels_to_excise}')

        for c, r in pixels_to_excise:
            if abs(c - ref_col) < 0.5 and abs(r - ref_row) < 0.5:
                if verbose:
                    print(f'    Skipping ({c},{r}): target reference pixel.')
                continue
            if trimmed[r, c]:
                trimmed[r, c] = False
                excised.append((c, r))

    # ------------------------------------------------------------------ #
    # Post-loop: apply blend shrink if any blended neighbors were found
    # ------------------------------------------------------------------ #
    if diag['has_blended_neighbor'] and np.isfinite(blend_shrink_radius):
        cur_rows, cur_cols = np.where(trimmed)
        dists_from_target  = np.sqrt(
            (cur_cols - ref_col) ** 2 + (cur_rows - ref_row) ** 2
        )
        keep = dists_from_target <= blend_shrink_radius
        n_after_shrink = int(keep.sum())

        if n_after_shrink < min_aperture_pixels:
            warnings.warn(
                f'[mask_out_neighbor_pixels TIC {ID}] Blend shrink to '
                f'r<={blend_shrink_radius} px would reduce aperture to '
                f'{n_after_shrink} pixel(s) (< min={min_aperture_pixels}). '
                f'Skipping shrink; aperture unchanged.',
                UserWarning, stacklevel=2,
            )
            diag['blend_shrink_reverted'] = True
            if verbose:
                print(f'  [mask_out_neighbor_pixels] Blend shrink REVERTED '
                      f'({n_after_shrink} px < min={min_aperture_pixels}).')
        else:
            shrink_mask = np.zeros_like(trimmed, dtype=bool)
            shrink_mask[cur_rows[keep], cur_cols[keep]] = True
            n_dropped = int(trimmed.sum()) - n_after_shrink
            trimmed = shrink_mask
            if verbose:
                print(f'  [mask_out_neighbor_pixels] Blend shrink applied: '
                      f'{int(pix_mask.sum())} -> {n_after_shrink} px '
                      f'({n_dropped} dropped outside r={blend_shrink_radius} px).')

    # ------------------------------------------------------------------ #
    # Resolvable excision revert check
    # ------------------------------------------------------------------ #
    if blended:
        diag['blended_neighbors'] = pd.DataFrame(blended)
    if qualifying:
        diag['contaminants_in_aperture'] = pd.DataFrame(qualifying)

    if excised and int(trimmed.sum()) < min_aperture_pixels:
        warnings.warn(
            f'[mask_out_neighbor_pixels TIC {ID}] Excision would reduce aperture '
            f'to {int(trimmed.sum())} pixel(s) (< min={min_aperture_pixels}). '
            f'Reverting.', UserWarning, stacklevel=2,
        )
        diag['reverted']       = True
        diag['pixels_excised'] = []
        diag['n_pixels_after'] = int(pix_mask.sum())
        return pix_mask.copy(), diag

    diag['pixels_excised'] = excised
    diag['n_pixels_after'] = int(trimmed.sum())

    if verbose:
        n_excised = diag['n_pixels_before'] - diag['n_pixels_after']
        print(f'  [mask_out_neighbor_pixels] Summary: '
              f'{diag["n_pixels_before"]} -> {diag["n_pixels_after"]} px  '
              f'({n_excised} total dropped)  '
              f'blended={diag["has_blended_neighbor"]}  '
              f'blend_shrink_reverted={diag["blend_shrink_reverted"]}  '
              f'reverted={diag["reverted"]}')

    return trimmed, diag

def SAP_ALT5(
    ID: int,
    nearby_star_catalog: "pd.DataFrame",
    Sector: int,
    cadence: str,
    hdu: "fits.HDUList",
    quality_mask: "np.ndarray",
    reference_pixel: list,
    default_settings: dict,
):
    """
    Simple Aperture Photometry with fully coupled aperture evaluation.

    Architecture
    ------------
    Phase A  Generate all candidate aperture masks from enabled methods.
    Phase B  Evaluate every candidate: run neighbor excision, score the
             post-excision mask with a consistent CDPP proxy, select winner.
             Excision catalog is built once and shared across all candidates.
    Phase C  Extract flux from the winning post-excision mask (binary sum
             or PRF-weighted sum).

    Phases A and B are coupled: the CDPP score that determines the winner
    always reflects the post-excision aperture actually used for extraction,
    not the raw candidate.

    Phase A — candidate generation
    --------------------------------
    When ``do_aperture_optimization=True`` (default):

    Threshold candidates
        ``thresholdmask`` at each sigma in ``opt_thresholds``.
    Circular candidates
        Circular disks at each radius in ``opt_radii`` px, intersected
        with ``~bkg_mask``.
    PRF binary candidate (opt-in: ``use_prf_in_optimization=True``)
        Binary mask from ``compute_prf_aperture_weights``.

    When ``do_aperture_optimization=False``:
        Single candidate from ``aperture_method``
        ('threshold' | 'circular' | 'prf').

    A threshold cascade always runs as last resort if no candidates are
    generated.  SPOC aperture overrides the winner for 2-min / 20-s data
    when ``use_SPOC_aperture=True``.

    Phase B — evaluation
    ----------------------
    For every candidate:
        1. Run ``mask_out_neighbor_pixels`` (silent).
        2. If excision reverts (aperture too small): score raw mask,
           set ``HAS_BLENDED_NEIGHBOR`` if applicable.
        3. If post-excision mask < ``neighbor_excision_min_pix``:
           step through ``circular_fallback_radii`` for a replacement.
        4. Score the resulting mask with the inline CDPP proxy.

    Excision catalog is built once before the loop:
        ``neighbor_catalog_source='tic'`` (default, zero extra queries)
        ``neighbor_catalog_source='gaia'`` (one Vizier call; TIC fallback
        on failure).

    Winner = lowest CDPP score.  A comparison table is printed when
    ``verbose=True``.

    Phase C — flux extraction
    --------------------------
    ``use_prf_weights=False`` (default)
        Binary aperture sum: ``nansum(flux * pix_mask)``.
        Recommended for bulk survey; static PRF weights induce correlated
        trends from per-cadence centroid drift.
    ``use_prf_weights=True``
        PRF-weighted sum restricted to the winning aperture footprint.

    New default_settings keys (all optional)
    -----------------------------------------
    Phase A / B:
        ``do_aperture_optimization``   : bool   True
        ``use_prf_in_optimization``    : bool   False
        ``opt_thresholds``             : tuple  (3.0, 5.0, 7.5, 10.0)
        ``opt_radii``                  : tuple  (1.0, 1.5, 2.0, 2.5) px
        ``aperture_method``            : str    'threshold'|'circular'|'prf'
                                                (only when optimization=False)
        ``circular_aperture_radius``   : float  1.5 px
        ``neighbor_catalog_source``    : str    'tic'|'gaia'
        ``neighbor_excision_dtmag``    : float  5.0
        ``neighbor_excision_radius``   : float  1.5 px
        ``neighbor_blend_threshold_px``: float  2.0 px
        ``neighbor_excision_min_pix``  : int    2
        ``circular_fallback_radii``    : tuple  (1.0, 1.5, 2.0)
    Phase C:
        ``use_prf_weights``            : bool   False
        ``prf_cache_dir``              : str|None  None
        ``prf_weight_threshold``       : float  0.01

    Returns  (13-tuple, identical to SAP_ALT3)
    ------------------------------------------
    [0]  bkg_mask
    [1]  pix_mask       post-excision winning aperture
    [2]  flux
    [3]  median_image
    [4]  SAP_LC         columns: QUALITY_FLAG, HAS_BLENDED_NEIGHBOR,
                        APERTURE_FELL_BACK.  attrs: aperture_method,
                        neighbor_catalog_source, has_blended_neighbor,
                        aperture_fell_back, prf_weighted, n_pix_aperture,
                        cdpp_score, blend_threshold_px,
                        neighbor_excision_radius.
    [5]  flux_contamination_ratio
    [6]  quality_flag
    [7]  bkg_level_per_pix
    [8]  bkg_trend
    [9]  bkg_residuals
    [10] quat_jitter
    [11] quat_status
    [12] qlp_result

    All 13 values are None on unrecoverable failure.
    """
    import warnings
    import time as clock
    import numpy as np
    import pandas as pd
    from pathlib import Path

    start = clock.time()
    _FAIL = (None,) * 13

    # =========================================================================
    # 0.  Settings unpack
    # =========================================================================
    cutoutsize               = default_settings.get('cutoutsize')
    threshold                = default_settings.get('threshold')
    verbose                  = default_settings.get('verbose')
    savelcpath               = default_settings.get('savelcpath')
    use_SPOC_aperture        = default_settings.get('use_SPOC_aperture')
    use_centroid             = default_settings.get('use_centroid')
    use_circ                 = default_settings.get('use_circ')
    use_sources_in_aperture  = default_settings.get('use_sources_in_aperture')
    do_aperture_optimization = default_settings.get('do_aperture_optimization')
    for_injections           = default_settings.get('for_injections')
    inject_param_P_RP_T0     = default_settings.get('inject_param_P_RP_T0')
    use_quat                 = default_settings.get('use_quat_jitter_mask', True)
    quat_path                = default_settings.get('quat_savepath', None)
    quat_sigma               = float(default_settings.get('quat_threshold_sigma', 5.0))
    quat_min_samp            = default_settings.get('quat_min_samples', None)
    bkg_sigma                = float(default_settings.get('bkg_threshold_sigma', 5.0))
    cent_sigma               = float(default_settings.get('centroid_threshold_sigma', 5.0))
    bkg_detrend_window       = float(default_settings.get('bkg_detrend_window', 3 / 24))

    use_prf_in_optimization  = bool(default_settings.get('use_prf_in_optimization', False))
    opt_thresholds           = tuple(default_settings.get('opt_thresholds', (3.0, 5.0, 7.5, 10.0)))
    opt_radii                = tuple(default_settings.get('opt_radii', (1.0, 1.5, 2.0, 2.5)))
    aperture_method          = str(default_settings.get('aperture_method', 'threshold')).lower()
    circular_aperture_radius = float(default_settings.get('circular_aperture_radius', 1.5))

    neighbor_catalog_source  = str(default_settings.get('neighbor_catalog_source', 'tic')).lower()
    delta_tmag_threshold     = float(default_settings.get('neighbor_excision_dtmag', 5.0))
    neighbor_excision_radius = float(default_settings.get('neighbor_excision_radius', 1.5))
    blend_threshold_px       = float(default_settings.get('neighbor_blend_threshold_px', 2.0))
    min_aperture_pixels      = int(default_settings.get('neighbor_excision_min_pix', 2))
    circular_fallback_radii  = tuple(default_settings.get('circular_fallback_radii', (1.0, 1.5, 2.0)))

    use_prf_weights          = bool(default_settings.get('use_prf_weights', False))
    prf_cache_dir            = default_settings.get('prf_cache_dir', None)
    prf_weight_threshold     = float(default_settings.get('prf_weight_threshold', 0.01))

    if quat_path is None:
        dl        = default_settings.get('downloadpath', '.')
        quat_path = str(Path(dl).parent / 'quaternions') + '/'
    
    # Auto-derive prf_cache_dir from downloadpath if not explicitly set.
    # Mirrors the quaternion path convention so both caches sit together.
    if prf_cache_dir is None:
        _dl = default_settings.get('downloadpath', '.')
        prf_cache_dir = str(Path(_dl).parent / 'prf')        

    sector_tag = f"Sector_{Sector:04d}" if isinstance(Sector, int) else "Multi_Sector"

    # =========================================================================
    # 1.  Metadata + flux cube
    # =========================================================================
    mean_gain, mean_read_noise = get_gain_and_readout_from_hdu(hdu)
    if verbose:
        print(f'  gain={np.round(mean_gain, 4)}  '
              f'read_noise={np.round(mean_read_noise, 4)}')

    median_image = np.nanmedian(hdu[1].data['FLUX'][~quality_mask], axis=0)
    flux         = hdu[1].data['FLUX'][~quality_mask].astype(np.float64)
    rawtime      = hdu[1].data['TIME'][~quality_mask].astype(np.float64)

    finite_frames = np.any(np.isfinite(flux), axis=(1, 2))
    rawtime = np.ascontiguousarray(rawtime[finite_frames])
    flux    = np.ascontiguousarray(flux[finite_frames])

    if len(rawtime) < 10:
        if verbose:
            print('  Too few finite frames after quality masking; returning None.')
        return _FAIL
    N = len(rawtime)

    # =========================================================================
    # 2.  Background mask + shared helpers
    # =========================================================================
    bkg_mask = ~thresholdmask(
        hdu, reference_pixel=None, threshold=1 / 1000,
        use_centroid=use_centroid, use_circ=use_circ,
    )
    if reference_pixel[0] > cutoutsize or reference_pixel[1] > cutoutsize:
        if verbose:
            print('  reference_pixel outside cutout; centering.')
        reference_pixel = [cutoutsize / 2, cutoutsize / 2]

    ref_col = float(reference_pixel[0])
    ref_row = float(reference_pixel[1])

#     def _circ_mask(radius: float) -> np.ndarray:
#         ny_, nx_ = bkg_mask.shape
#         yy, xx   = np.mgrid[0:ny_, 0:nx_]
#         return (np.sqrt((xx - ref_col)**2 + (yy - ref_row)**2) <= radius) & ~bkg_mask

    # Inline CDPP proxy: rolling-window RMS over a 2-hr transit window on
    # normalised background-subtracted SAP flux.  All candidates are scored
    # on this same metric so comparisons are scale-consistent.
    _cad_days = float(np.nanmedian(np.diff(rawtime))) if len(rawtime) > 1 else 30.0/1440.0
    _n_win    = max(1, int(round(2.0 / 24.0 / _cad_days)))

    def _cdpp_score(pm: np.ndarray) -> float:
        n_ap = int(pm.sum())
        if n_ap < 1:
            return np.inf
        with np.errstate(all='ignore'):
            sap = np.nansum(flux * pm[np.newaxis], axis=(1, 2)) \
                  - np.nanmedian(flux[:, bkg_mask], axis=1) * n_ap
        fin = np.isfinite(sap)
        if fin.sum() < 10:
            return np.inf
        med = np.nanmedian(sap[fin])
        if not np.isfinite(med) or med <= 0:
            return np.inf
        sap_n = sap[fin] / med
        if len(sap_n) < _n_win:
            return float(np.nanstd(sap_n))
        return float(np.nanstd(np.convolve(sap_n, np.ones(_n_win)/_n_win, mode='valid')))

    # =========================================================================
    # 3.  Phase A — Generate candidate aperture masks
    # =========================================================================
    if verbose:
        print('\n  ===== Phase A: Candidate Generation =====')
    #
    candidates = {}   # label -> raw_mask (pre-excision)
    #
    if do_aperture_optimization:
        # Threshold sweep
        for sigma in opt_thresholds:
            try:
                pm = thresholdmask(hdu, reference_pixel, threshold=sigma,
                                   use_centroid=use_centroid, use_circ=use_circ)
                if pm.sum() >= min_aperture_pixels:
                    candidates[f'thr_{sigma:.1f}σ'] = pm
            except Exception:
                pass
        #
        # Circular sweep
        for rad in opt_radii:
            #pm = _circ_mask(rad)
            pm = create_circular_mask(median_image, reference_pixel, radius=rad, snap_to_pixel=True)
            if pm.sum() >= min_aperture_pixels:
                candidates[f'circ_{rad}px'] = pm
        #
        # PRF binary (opt-in)
        if use_prf_in_optimization:
            try:
                _tmag_a = float(nearby_star_catalog.loc[
                    nearby_star_catalog['ID'].astype(str) == str(ID), 'Tmag'].iloc[0])
                _, pm_prf = compute_prf_aperture_weights(
                    hdu=hdu, reference_pixel=reference_pixel,
                    nearby_star_catalog=nearby_star_catalog, target_tmag=_tmag_a,
                    cutoutsize=cutoutsize, prf_weight_threshold=prf_weight_threshold,
                    decontaminate=True, prf_cache_dir=prf_cache_dir, verbose=verbose,
                )
                pm_prf = pm_prf & ~bkg_mask
                if pm_prf.sum() >= min_aperture_pixels:
                    candidates['prf_binary'] = pm_prf
                elif verbose:
                    print('  [ALT5 A] PRF binary mask too small after bkg exclusion; skipped.')
            except Exception as exc:
                if verbose:
                    print(f'  [ALT5 A] PRF candidate failed ({exc}); skipped.')
        #
    else:
        # Single-method path.
        # `aperture_method_param` is written by the LC_creation locking logic
        # after sector 0 completes.  When set it overrides the global
        # threshold / circular_aperture_radius so every sector uses the exact
        # hyperparameter that won in sector 0.
        _locked_param = default_settings.get('aperture_method_param', None)

        if aperture_method == 'prf':
            try:
                _tmag_s = float(nearby_star_catalog.loc[
                    nearby_star_catalog['ID'].astype(str) == str(ID), 'Tmag'].iloc[0])
                _, pm_prf_s = compute_prf_aperture_weights(
                    hdu=hdu, reference_pixel=reference_pixel,
                    nearby_star_catalog=nearby_star_catalog, target_tmag=_tmag_s,
                    cutoutsize=cutoutsize, prf_weight_threshold=prf_weight_threshold,
                    decontaminate=True, prf_cache_dir=prf_cache_dir, verbose=verbose,
                )
                pm_prf_s = pm_prf_s & ~bkg_mask
                if pm_prf_s.sum() >= min_aperture_pixels:
                    candidates['prf_binary'] = pm_prf_s
            except Exception as exc:
                if verbose:
                    print(f'  [ALT5 A] PRF failed ({exc}); falling through to threshold.')

        elif aperture_method == 'circular':
            _rad = float(_locked_param) if _locked_param is not None else circular_aperture_radius
            #pm_c = _circ_mask(_rad)
            pm_c = create_circular_mask(median_image, reference_pixel, radius=_rad, snap_to_pixel=True)
            if pm_c.sum() >= min_aperture_pixels:
                candidates[f'circ_{_rad:.2f}'] = pm_c
            if verbose and _locked_param is not None:
                print(f'  [ALT5 A] locked circular radius={_rad:.2f} px (from sector-0 winner)')

        elif aperture_method == 'threshold':
            _sigma = float(_locked_param) if _locked_param is not None else threshold
            try:
                pm_t = thresholdmask(
                    hdu, reference_pixel, threshold=_sigma,
                    use_centroid=use_centroid, use_circ=use_circ,
                    max_aperture_radius=default_settings.get('max_aperture_radius', None),
                )
                if pm_t.sum() >= min_aperture_pixels:
                    candidates[f'thr_{_sigma:.2f}'] = pm_t
                if verbose and _locked_param is not None:
                    print(f'  [ALT5 A] locked threshold sigma={_sigma:.2f} (from sector-0 winner)')
            except ValueError:
                pass

    # Threshold cascade: absolute fallback if nothing generated yet
    if not candidates:
        for _f in [1.0, 0.5, 1/3, 1/threshold]:
            try:
                pm_fb = thresholdmask(hdu, reference_pixel, threshold=threshold*_f,
                                      use_centroid=use_centroid, use_circ=use_circ)
                if pm_fb.sum() >= min_aperture_pixels:
                    candidates['thr_fallback'] = pm_fb
                    break
            except ValueError:
                pass
        if not candidates:
            if verbose:
                print('  [ALT5 A] No viable candidates generated; returning None.')
            return _FAIL

    if verbose:
        print(f'  {len(candidates)} candidate(s): {list(candidates.keys())}')

    # =========================================================================
    # 4.  Phase B — Evaluate each candidate: excision + CDPP → select winner
    # =========================================================================
    if verbose:
        print('\n  ===== Phase B: Candidate Evaluation =====')

    # Build excision catalog once; shared across all candidate evaluations.
    excision_catalog   = nearby_star_catalog
    excision_target_id = ID
    _catalog_used      = neighbor_catalog_source

    if neighbor_catalog_source == 'gaia':
        try:
            _gdf, _tgt_gaia_id, _ = collect_nearby_Gaia_params(
                ID=ID, hdu=hdu, verbose=False)
            _gcol  = {c.lower(): c for c in _gdf.columns}
            _ra_k  = next((_gcol[k] for k in
                           ['ra','ra_icrs','raj2000','_ra','ra_epoch'] if k in _gcol), None)
            _dec_k = next((_gcol[k] for k in
                           ['dec','de_icrs','decj2000','_de','dec_epoch'] if k in _gcol), None)
            if _ra_k and _dec_k and 'id' in _gcol and 'gmag' in _gcol:
                excision_catalog = pd.DataFrame({
                    'ID':   _gdf[_gcol['id']].astype(str),
                    'ra':   _gdf[_ra_k].to_numpy(float),
                    'dec':  _gdf[_dec_k].to_numpy(float),
                    'Tmag': _gdf[_gcol['gmag']].to_numpy(float),
                })
                excision_target_id = str(_tgt_gaia_id)
                if verbose:
                    print(f'  Excision catalog: Gaia DR3 ({len(_gdf)} sources)')
            else:
                raise ValueError('column mapping failed')
        except Exception as exc:
            if verbose:
                print(f'  Excision catalog: TIC (Gaia unavailable: {exc})')
            _catalog_used = 'tic (gaia fallback)'

    # Evaluate: run excision + score for every candidate (silently)
    # eval_results: label -> (scored_mask, score, raw_npix, exc_npix, nb_diag, has_blend, fell_back)
    eval_results = {}

    for label, raw_mask in candidates.items():
        exc_mask, nb_diag = mask_out_neighbor_pixels(
            hdu=hdu, pix_mask=raw_mask.copy(),
            nearby_star_catalog=excision_catalog, ID=excision_target_id,
            reference_pixel=reference_pixel,
            delta_tmag_threshold=delta_tmag_threshold,
            neighbor_excision_radius=neighbor_excision_radius,
            blend_threshold_px=blend_threshold_px,
            min_aperture_pixels=min_aperture_pixels,
            verbose=False,
        )
        has_blend   = nb_diag['has_blended_neighbor']
        fell_back   = False
        scored_mask = raw_mask.copy() if nb_diag['reverted'] else exc_mask

        if scored_mask.sum() < min_aperture_pixels:
            for rad in circular_fallback_radii:
                #fb = _circ_mask(rad)
                fb = create_circular_mask(median_image, reference_pixel, radius=rad, snap_to_pixel=True)
                
                if fb.sum() >= min_aperture_pixels:
                    scored_mask = fb
                    fell_back   = True
                    break
            if not fell_back:
                scored_mask = raw_mask.copy()

        score = _cdpp_score(scored_mask)
        eval_results[label] = (
            scored_mask, score,
            int(raw_mask.sum()), int(scored_mask.sum()),
            nb_diag, has_blend, fell_back,
        )

    # Select winner (lowest CDPP on post-excision mask)
    winner_label = min(eval_results, key=lambda k: eval_results[k][1])
    (pix_mask, best_score, _, _,
     best_nb_diag, _has_blended_neighbor, _fell_back_to_circular) = eval_results[winner_label]
    aperture_label = winner_label

    # Print comparison table
    if verbose:
        col_w = max(len(k) for k in eval_results) + 2
        print(f'  {"Candidate":<{col_w}} {"raw_px":>7} {"exc_px":>7} '
              f'{"cdpp":>10} {"blended":>8}')
        print('  ' + '-' * (col_w + 36))
        for lbl, (sm, sc, rn, en, nd, hb, fb) in eval_results.items():
            mark = ' ←' if lbl == winner_label else ''
            print(f'  {lbl:<{col_w}} {rn:>7} {en:>7} {sc:>10.6f} {str(hb):>8}{mark}')
        print(f'\n  WINNER: {winner_label}  n_pix={int(pix_mask.sum())}  '
              f'cdpp={best_score:.6f}  blended={_has_blended_neighbor}')
        exc_px = best_nb_diag.get('pixels_excised', [])
        if exc_px:
            print(f'  Excised (winner): {exc_px}')
        bn = best_nb_diag.get('blended_neighbors', pd.DataFrame())
        if _has_blended_neighbor and len(bn) > 0:
            print(f'  Blended sources: {len(bn)} within {blend_threshold_px} px '
                  f'— HAS_BLENDED_NEIGHBOR set')

    # SPOC override (cadence-gated; post-selection)
    if cadence in ('short', '2 minute', '20 second', 'fast') and use_SPOC_aperture:
        try:
            _spoc = (hdu[2].data & 2 > 0) & ~bkg_mask
            if _spoc.sum() >= min_aperture_pixels:
                pix_mask       = _spoc
                best_score     = _cdpp_score(_spoc)
                aperture_label = 'spoc'
                if verbose:
                    print(f'\n  [ALT5] SPOC override: n_pix={int(_spoc.sum())}')
        except TypeError:
            pass

    # =========================================================================
    # 5.  Background extraction (binary; always for diagnostic quantities)
    # =========================================================================
    (rawflux, bkgFlux, rawsap_flux,
     Npixaper, Npixbkg, bkg_level_per_pix) = extract_background_flux(
        flux, bkg_mask, pix_mask, Nsig=3.0
    )

    # =========================================================================
    # 6.  Phase C — Flux extraction
    # =========================================================================
    if verbose:
        print(f'\n  ===== Phase C: Flux Extraction =====')

    weight_map  = None
    _prf_active = False

    if use_prf_weights:
        try:
            _tmag_c = float(nearby_star_catalog.loc[
                nearby_star_catalog['ID'].astype(str) == str(ID), 'Tmag'].iloc[0])
            _wm_c, _ = compute_prf_aperture_weights(
                hdu=hdu, reference_pixel=reference_pixel,
                nearby_star_catalog=nearby_star_catalog, target_tmag=_tmag_c,
                cutoutsize=cutoutsize, prf_weight_threshold=prf_weight_threshold,
                decontaminate=True, prf_cache_dir=prf_cache_dir, verbose=verbose,
            )
            _wm_c  = _wm_c * pix_mask.astype(np.float64)
            _n_eff = float(_wm_c.sum())
            if _n_eff > 0.0:
                _bkg_pp           = np.nanmedian(flux[:, bkg_mask], axis=1)
                rawflux            = np.nansum(flux * _wm_c[np.newaxis], axis=(1, 2))
                bkgFlux            = _bkg_pp * _n_eff
                rawsap_flux        = rawflux - bkgFlux
                bkg_level_per_pix  = _bkg_pp
                weight_map         = _wm_c
                _prf_active        = True
                if verbose:
                    print(f'  [ALT5 C] PRF-weighted: '
                          f'n_eff={_n_eff:.3f}  peak={_wm_c.max():.4f}')
            else:
                if verbose:
                    print('  [ALT5 C] PRF weight map collapsed; using binary.')
        except Exception as exc:
            if verbose:
                print(f'  [ALT5 C] PRF weighting failed ({exc}); using binary.')
    else:
        if verbose:
            print(f'  [ALT5 C] Binary aperture sum  (n_pix={int(pix_mask.sum())})')

    # =========================================================================
    # 7.  Per-cadence centroids
    # =========================================================================
    centx = np.full(N, np.nan)
    centy = np.full(N, np.nan)
    for t in range(N):
        try:
            cx, cy = centroid_quadratic(flux[t], pix_mask, reference_pixel)
            centx[t] = float(cx)
            centy[t] = float(cy)
        except Exception:
            pass

    # =========================================================================
    # 8.  Uncertainty
    # =========================================================================
    sap_flux_error, bkg_flux_error = SAP_and_BKG_uncertainty(
        rawflux=rawsap_flux, bkgFlux=bkgFlux,
        pix_mask=pix_mask, bkg_mask=bkg_mask,
        rawtime=rawtime, gain=mean_gain, read_noise=mean_read_noise,
    )
    #
    # =========================================================================
    # 9.  Flux contamination ratio
    # =========================================================================
    def _safe_contamination(catalog, use_aperture):
        try:
            if use_aperture:
                cat_in = get_sources_in_aperture_mask(
                    ID, hdu, pix_mask, catalog, verbose=False)
                if len(cat_in) < 1:
                    raise ValueError('empty aperture catalog')
                ratio, sigma = calc_flux_contamination(
                    nearby_star_catalog=cat_in, ID=ID)
            else:
                ratio, sigma = calc_flux_contamination(
                    nearby_star_catalog=catalog, ID=ID, N_TESS_pixels=3)
            if not np.isfinite(ratio):
                raise ValueError('non-finite ratio')
            return float(ratio), float(sigma)
        except Exception:
            try:
                ratio, sigma = calc_flux_contamination(
                    nearby_star_catalog=catalog, ID=ID, N_TESS_pixels=3)
                return float(ratio), float(sigma)
            except Exception:
                return 0.0, 0.0

    flux_contamination_ratio, sigma_contamination = _safe_contamination(
        nearby_star_catalog, use_sources_in_aperture)
    #
    # =========================================================================
    # 10.  Transit injection (optional)
    # =========================================================================
    if for_injections and inject_param_P_RP_T0 is not None:
        Period, R_planet_RE, T0 = inject_param_P_RP_T0
        _rawsap_pre   = rawsap_flux.copy()
        
        RawSAP_LC_inj = pd.DataFrame({
            'Time':      rawtime,
            'SAP Flux':  rawsap_flux,
            'SAP Error': sap_flux_error,
        })

        orbit1_start, _, _, _ = TESS_Sector_observation_check(SectorNum=Sector)

        if T0 is None:
            T0 = orbit1_start
            inject_param_P_RP_T0 = [Period, R_planet_RE, T0]
            default_settings['inject_param_P_RP_T0'] = inject_param_P_RP_T0
        #
        inj_LC, inj_params = transit_injection(
            input_LC                 = RawSAP_LC_inj,
            Period                   = Period,
            T0                       = T0,
            ID                       = ID,
            nearby_star_catalog      = nearby_star_catalog,
            Sector                   = Sector,
            default_settings         = default_settings,
            R_planet_RE              = R_planet_RE,
            flux_contamination_ratio = flux_contamination_ratio,   
        )
        #
        inj_params.to_csv(
            savelcpath + f'TIC_{ID}_{sector_tag}_TransitInjected_param.csv', index=False)
        #
        _scale = np.sqrt(
            np.maximum(np.abs(inj_LC['SAP Flux'].to_numpy()), 0.0)
            / np.maximum(np.abs(_rawsap_pre), 1.0)
        )
        rawsap_flux    = inj_LC['SAP Flux'].to_numpy()
        sap_flux_error = sap_flux_error * _scale
        inj_LC['SAP Error'] = sap_flux_error
        inj_LC['BKG Flux']  = bkgFlux
        inj_LC['BKG Error'] = bkg_flux_error
        inj_LC.to_csv(
            savelcpath + f'TIC_{ID}_{sector_tag}_TransitInjected_RAWLC.csv',
            index=False,
        )
        if verbose:
            print(f'\nTransit injection: P={Period} d  Rp={R_planet_RE} RE  '
                  f'T0={T0}  fcr={flux_contamination_ratio:.4f}\n')
    #
    # =========================================================================
    # 11.  Quality bitmask
    # =========================================================================
    from wotan import flatten as _wotan_flatten

    def _mad_flag(arr, nsigma, side='both'):
        fin = np.isfinite(arr)
        if fin.sum() < 5:
            return np.ones(len(arr), dtype=bool)
        med = np.nanmedian(arr[fin])
        mad = np.nanmedian(np.abs(arr[fin] - med)) * 1.4826
        if mad == 0 or not np.isfinite(mad):
            return fin.copy()
        lo, hi = med - nsigma * mad, med + nsigma * mad
        if side == 'both':   return fin & (arr >= lo) & (arr <= hi)
        if side == 'upper':  return fin & (arr <= hi)
        if side == 'lower':  return fin & (arr >= lo)
        return fin & (arr >= lo) & (arr <= hi)

    try:
        _, bkg_trend = _wotan_flatten(
            rawtime, bkg_level_per_pix, window_length=bkg_detrend_window,
            return_trend=True, method='biweight', break_tolerance=0.5)
        bkg_residuals = bkg_level_per_pix - bkg_trend
    except Exception:
        bkg_trend     = np.full(N, np.nanmedian(bkg_level_per_pix))
        bkg_residuals = bkg_level_per_pix - bkg_trend

    bkg_mad_good  = _mad_flag(bkg_residuals, bkg_sigma, side='upper')
    _safe_trend   = np.where(bkg_trend > 0, bkg_trend, np.nan)
    bkg_frac_good = (np.abs(bkg_residuals) / _safe_trend) < 0.05
    bkg_good      = bkg_mad_good | bkg_frac_good

    fin_cent    = np.isfinite(centx) & np.isfinite(centy)
    dx = np.where(fin_cent, centx - np.nanmedian(centx[fin_cent]), np.nan)
    dy = np.where(fin_cent, centy - np.nanmedian(centy[fin_cent]), np.nan)
    cent_good   = _mad_flag(np.sqrt(dx**2 + dy**2), cent_sigma, side='upper') & fin_cent

    quat_good   = np.ones(N, dtype=bool)
    quat_jitter = None
    qlp_result  = None
    quat_status = 'skipped: use_quat_jitter_mask=False'

    if use_quat:
        quat_status = 'skipped: unknown error'
        try:
            camera = int(hdu[0].header.get('CAMERA', hdu[1].header.get('CAMERA', -1)))
            if camera not in (1, 2, 3, 4):
                raise ValueError(f'invalid CAMERA value: {camera}')
            _cad_map = {
                'long': 30/1440, '30 minute': 30/1440, '10 minute': 10/1440,
                'short': 2/1440, '2 minute': 2/1440,
                'fast': 20/86400, '20 second': 20/86400,
            }
            cad_q = _cad_map.get(cadence, float(np.nanmedian(np.diff(rawtime))))
            if quat_min_samp is None:
                quat_min_samp = max(5, int(0.25 * cad_q * 86400.0 / 2.0))
            t_off = 0.0
            try:
                if 'TIMECORR' in hdu[1].columns.names:
                    tc = hdu[1].data['TIMECORR'].astype(np.float64)
                    ftc = tc[np.isfinite(tc)]
                    if len(ftc) > 0:
                        t_off = float(np.median(ftc))
            except Exception:
                pass
            qdata = get_qdata(sector=int(Sector), savepath=quat_path, overwrite=False)
            try:
                qdf = load_camera_quaternions(qdata, camera=camera)
            finally:
                qdata.close()
            feature_df, feature_cols = bin_quaternion_features(
                lc_time=rawtime, q_time=qdf['TIME'].values,
                q1=qdf['Q1'].values, q2=qdf['Q2'].values, q3=qdf['Q3'].values,
                cadence_days=cad_q, min_samples=quat_min_samp, time_offset=t_off,
            )
            j_arr   = feature_df['jitter'].values
            fin_j   = j_arr[np.isfinite(j_arr)]
            if len(fin_j) < 5:
                raise ValueError(f'Only {len(fin_j)} finite jitter bins.')
            med_j   = np.median(fin_j)
            mad_j   = np.median(np.abs(fin_j - med_j)) * 1.4826
            jmask   = ~np.isfinite(j_arr) | (j_arr > med_j + quat_sigma * mad_j)
            quat_good   = ~jmask
            quat_jitter = j_arr
            qlp_result  = {
                'mask': jmask, 'jitter_mask': jmask,
                'outlier_mask': np.zeros(N, dtype=bool),
                'jitter': j_arr, 'feature_df': feature_df,
                'feature_cols': feature_cols, 'detrended_flux': None,
                'best_fit': None, 'bic_values': {}, 'best_knot_spacing': None,
            }
            n_bad = int(jmask.sum())
            quat_status = (f'used (jitter-scalar MAD, σ={quat_sigma:.1f}, '
                           f'min_samples={quat_min_samp}, '
                           f'Δt_bary={t_off * 1440:.2f} min)')
            if verbose:
                print(f'\n  ===== Quaternion Jitter Masking =====\n'
                      f'  [ALT5 quat] S{Sector} | Cam{camera} | '
                      f'cad={cad_q*1440:.1f} min | '
                      f'masked={n_bad}/{N} ({100*n_bad/N:.1f}%) | '
                      f'jitter med={med_j:.4e}  MAD={mad_j:.4e}')
        except FileNotFoundError:
            quat_status = f'skipped: no quaternion file for Sector {Sector}'
        except Exception as exc:
            quat_status = f'skipped: {exc}'

    if verbose:
        print(f'  quaternion status: {quat_status}')

    quality_flag = np.zeros(N, dtype=np.int16)
    quality_flag[~quat_good] |= QUALITY_FLAG_BITS[1]
    quality_flag[~bkg_good]  |= QUALITY_FLAG_BITS[2]
    quality_flag[~cent_good] |= QUALITY_FLAG_BITS[3]
    good = (quality_flag & int(_FLUX_CORRUPT_MASK)) == 0

    if verbose:
        n_j = int(((quality_flag & int(QUALITY_FLAG_BITS[1])) != 0).sum())
        n_b = int(((quality_flag & int(QUALITY_FLAG_BITS[2])) != 0).sum())
        n_c = int(((quality_flag & int(QUALITY_FLAG_BITS[3])) != 0).sum())
        print(f'\n  ===== Quality Flags =====')
        print(f'  QUALITY_FLAG: clean={good.sum()} | '
              f'1=jitter {n_j} | 2=bkg {n_b} | 3=centroid {n_c}')

    # =========================================================================
    # 12.  Normalize + deblend
    # =========================================================================
    med1         = np.nanmedian(rawsap_flux[good])
    sap_flux     = rawsap_flux / med1
    error        = sap_flux_error / med1
    sigma_c_norm = sigma_contamination / med1
    error        = np.sqrt(error**2 + sigma_c_norm**2)
    sap_flux     = sap_flux - flux_contamination_ratio
    med2         = np.nanmedian(sap_flux[good])
    sap_flux     = sap_flux / med2
    error        = error / med2

    # =========================================================================
    # 13.  Output DataFrame
    # =========================================================================
    SAP_LC = pd.DataFrame({
        'CADENCE_INDEX':          np.arange(N, dtype=int),
        'Time':                   rawtime,
        'RAW SAP Flux':           rawsap_flux,
        'SAP Flux':               sap_flux,
        'SAP Error':              error,
        'Background Flux':        bkgFlux,
        'Background Error':       bkg_flux_error,
        'Centroid X Positions':   centx,
        'Centroid Y Positions':   centy,
        'QUALITY_FLAG':           quality_flag,
        'HAS_BLENDED_NEIGHBOR':   np.full(N, _has_blended_neighbor, dtype=bool),
        'APERTURE_FELL_BACK':     np.full(N, _fell_back_to_circular, dtype=bool),
    })
    SAP_LC = _decorate_quality_columns(SAP_LC)
    SAP_LC.attrs['aperture_method']          = aperture_label
    SAP_LC.attrs['neighbor_catalog_source']  = _catalog_used
    SAP_LC.attrs['has_blended_neighbor']     = bool(_has_blended_neighbor)
    SAP_LC.attrs['aperture_fell_back']       = bool(_fell_back_to_circular)
    SAP_LC.attrs['prf_weighted']             = bool(_prf_active)
    SAP_LC.attrs['n_pix_aperture']           = int(pix_mask.sum())
    SAP_LC.attrs['cdpp_score']               = float(best_score)
    SAP_LC.attrs['neighbor_excision_radius'] = neighbor_excision_radius
    SAP_LC.attrs['blend_threshold_px']       = blend_threshold_px
    # ── NEW: parse winner hyperparameter for multi-sector locking ────────────
    _winner_param = None
    _wl = aperture_label   # e.g. 'thr_7.50', 'circ_1.50', 'thr_fallback', 'prf_binary'
    if _wl.startswith('thr_') and _wl != 'thr_fallback':
        try:
            _winner_param = float(_wl.split('_', 1)[1])
        except ValueError:
            pass
    elif _wl.startswith('circ_') and _wl != 'circular_fixed':
        try:
            _winner_param = float(_wl.split('_', 1)[1])
        except ValueError:
            pass
    elif _wl == 'circular_fixed':
        _winner_param = float(default_settings.get('circular_aperture_radius', 1.5))
    # 'prf_binary' and 'thr_fallback' leave _winner_param as None intentionally.
    SAP_LC.attrs['aperture_method_param']  = _winner_param   # NEW
    SAP_LC.attrs['aperture_winner_label']  = aperture_label  # NEW (redundant but explicit)
    
    if verbose:
        print('')
        timer(start, clock.time(), 'SAP_ALT5() total:')

    return (
        bkg_mask, pix_mask, flux, median_image, SAP_LC,
        flux_contamination_ratio, quality_flag,
        bkg_level_per_pix, bkg_trend, bkg_residuals,
        quat_jitter, quat_status, qlp_result,
    )
