def get_GAIA_DR2_sources(ID,hdu, downloadpath,magnitude_limit):#UNUSED BUT USEFUL
    """
    This function will query the GAIA catalog for
    nearby sources using a radial cone search.
    Input Parameters
    ----------
    ID : int
        TESS Input Catalog identification number.
    hdu : FITS object
        Astropy Header Data Unit List of TESS FFI/TPF for target star.
        Contains PrimaryHDU, BinTableHDU and ImageHDU.
    downloadpath : str
        Pathname of directory for cached TESScut, Vizier, MAST queried data products.
    magnitude_limit: float
        Upper limit for faintest magnitudes to include in query.
    Returns
    -------
        * result : pandas dataframe
        Queried result of nearby GAIA sources.
    """     
    #stuff for getting data from MAST
    import astropy
    from astroquery.mast import Catalogs
    from astroquery.mast import Tesscut
    from astropy.coordinates import SkyCoord
    from astroquery.gaia import Gaia
    from astropy.wcs import WCS
    from astropy.io import fits
    import astropy.units as u
    from astropy.coordinates import SkyCoord, Angle
    from astroquery.vizier import Vizier
    import numpy as np
    import pandas as pd
    ###
    # changing cache directories
    Tesscut.cache_location=downloadpath
    Catalogs.cache_location=downloadpath
    Vizier.cache_location=downloadpath
    ###
    starName="TIC "+str(ID)
    pix_scale=21
    #
    ra=hdu[2].header['RA_OBJ']
    dec=hdu[2].header['DEC_OBJ']
    # Get the positions of the Gaia sources
    c1 = SkyCoord(ra,dec, frame='icrs', unit='deg')
    # Use pixel scale for query size
    pix_scale = 21.0
#     Vizier.ROW_LIMIT = -1 # doesn't include target star (?)
    cone = 0.5*np.nanmax(hdu[1].data['FLUX'].shape[1:]) * pix_scale
    cone = 5*pix_scale
    try:
        result = Vizier.query_region(c1, catalog=["I/345/gaia2"],radius=Angle(cone, "arcsec"))
#     result = Vizier.query_region(c1, catalog=["GAIA"],radius=Angle(cone, "arcsec"))
    except requests.exceptions.ConnectionError as CE:
        import time as clock
        clock.sleep(1)
        print(CE,'\ntrying Vizier query again')
        result = Vizier.query_region(c1, catalog=["I/345/gaia2"],radius=Angle(cone, "arcsec"))
        print('')
    #
    no_targets_found_message = ValueError('Either no sources were found in the query region '
                                          'or Vizier is unavailable')
    too_few_found_message = ValueError('No sources found brighter than {:0.1f}'.format(magnitude_limit))
    #
    if result is None:
        raise no_targets_found_message
    elif len(result) == 0:
        raise too_few_found_message
    result = result["I/345/gaia2"].to_pandas() #using GAIA DR2
    result = result[result.Gmag < magnitude_limit]
    #
    #rename RA DEC columns to match TESS query
    result=result.rename(columns={'RA_ICRS': 'ra','DE_ICRS': 'dec', 'pmRA':'pmRA', 'pmDE':'pmDEC'})
    #
    return result
