#
def collect_nearby_TIC_params(ID,N_TESS_pixels,verbose=False,downloadpath=None):
    """
    Queries the TESS Input Catalog (TIC) for stellar parameters of the
    target star and nearby stars within a given radius.  The radius is 
    defined by the number of TESS pixels.

    Parameters:
    -----------
    ID : int or str
        The TIC ID of the target star.
    N_TESS_pixels : float
        The number of TESS pixels to define the radius for nearby star search.
    verbose : bool, optional
        If `True`, additional details will be printed during execution 
        (default is `False`).
    downloadpath : str, optional
        Path to a custom download location for caching the TIC query. 
        If not provided, default cache settings will be used.

    Returns:
    --------
    star : pandas.DataFrame
        DataFrame containing the queried stellar parameters for the target star.
    nearby_star_catalog : pandas.DataFrame
        DataFrame containing stellar parameters for nearby stars within
        the specified radius.
    """
    from astroquery.mast import Catalogs
    if type(downloadpath)!=type(None):
        Catalogs.cache_location=downloadpath

    import astropy.units as u
    radial_cone = (N_TESS_pixels*21.0 * (u.arcsec/u.pixel)* (1 * u.pixel)).to(u.degree).value
    starName='TIC '+str(ID)
    result = while_loop( lambda: Catalogs.query_object(starName,
                                                       radius=radial_cone,
                                                       catalog="TIC").to_pandas(),
                       message = 'Trying TIC query from MAST again')
    #
    result_filtered = result
    #
    star = result_filtered.loc[result_filtered['ID']==str(ID)].reset_index(drop=True)
    if len(star)<1:
        print('TIC ',ID,'star length:',len(star),'result length:',len(result))
        star = result.loc[result['ID']==str(ID)].reset_index(drop=True)
        print('TIC '+str(ID)+' has TIC Disposition '+str(star['disposition'].item()))
        star=result.loc[ (result['GAIA']==star['GAIA'].item()) &
                         (result['duplicate_id']==str(ID)) ].reset_index(drop=True)
        print('TIC ',ID,'new star length:',len(star),'new result length:',len(result))
    star = get_qld(star, verbose)
    nearby_star_catalog = result
    return star,nearby_star_catalog

import numpy as np
from typing import Tuple

def mann2019_mass_radius(
    Kmag: float,
    dist_pc: float,
    feh: float = 0.0,
    use_metallicity: bool = False,
    fallback_mass: float = 0.4,
    fallback_radius: float = 0.4,
    verbose: bool = False,
) -> Tuple[float, float, bool]:
    """
    Estimate M-dwarf stellar mass and radius from absolute 2MASS K_s magnitude.

    Mass relation (Mann et al. 2019, ApJ, 871, 63)
        Eq. 2, fifth-order fit (n = 5), coefficients from Table 6:
            log10(M/M_sun) = sum_{i=0}^{5} a_i * (M_Ks - zp)^i,  zp = 7.5
            a = (-0.642, -0.208, -8.43e-4, 7.87e-3, 1.42e-4, -2.13e-4)
        Intrinsic scatter sigma_e = 0.020 (Table 6); total relation
        uncertainty 2.2 to 3.7 percent over 4.0 <= M_Ks <= 11.0 (Table 7).
        Optional [Fe/H] form (Eq. 5, single-star version, Table 6):
            M = (1 + f [Fe/H]) * 10**(sum_i a'_i (M_Ks - zp)^i),
            a' = (-0.647, -0.207, -6.53e-4, 7.13e-3, 1.84e-4, -1.60e-4),
            f = -0.0035 (consistent with zero; Section 7.5).

    Radius relation (Mann et al. 2015, ApJ, 804, 64)
        Eq. 4, coefficients from Table 1:
            R/R_sun = a + b M_Ks + c M_Ks^2,  (a, b, c) = (1.9515, -0.3520, 0.01680)
        Scatter 2.89 percent. Calibrated over 4.6 < M_Ks < 9.8 (Section 6).
        Optional [Fe/H] form (Eq. 5, Table 1):
            R/R_sun = (1.9305 - 0.3466 M_Ks + 0.01647 M_Ks^2) * (1 - 0.04458 [Fe/H]),
        scatter 2.70 percent.

    Validity window
        Both relations are evaluated only for 4.5 <= M_Ks <= 10.0, the window
        TIC v8 used when applying these same two relations to its Cool Dwarf
        List (Stassun et al. 2019, AJ, 158, 138, Appendix A.1). This keeps
        Case 3 imputations on the same footing as the TIC values used for
        Case 1. Outside the window, or if either output fails the sanity
        clamp, BOTH fallbacks are returned together so that the (M, R) pair
        is always internally consistent.

    Parameters
    ----------
    Kmag : float
        Apparent 2MASS K_s magnitude (TIC column ``Kmag``).
    dist_pc : float
        Distance in parsecs (TIC column ``d``).
    feh : float, optional
        Stellar [Fe/H]. Used only if ``use_metallicity=True`` and finite.
        Default 0.0.
    use_metallicity : bool, optional
        If True and ``feh`` is finite, use the [Fe/H]-dependent coefficient
        sets above. Default False, recommended: the mass term is consistent
        with zero and the radius term reduces scatter only from 2.89 to 2.70
        percent.
    fallback_mass : float, optional
        Mass in M_sun returned when the relations cannot be applied.
        Default 0.4.
    fallback_radius : float, optional
        Radius in R_sun returned when the relations cannot be applied.
        Default 0.4.
    verbose : bool, optional
        Print diagnostics. Default False.

    Returns
    -------
    mass : float
        Stellar mass in M_sun.
    radius : float
        Stellar radius in R_sun.
    used_fallback : bool
        True if the fixed fallback pair was returned.

    Notes
    -----
    M_Ks = Kmag - 5 log10(dist_pc / 10), with no extinction correction.
    Both calibrations also neglect extinction, on the grounds that their
    samples lie within the Local Bubble.

    Example
    -------
    >>> mass, radius, fb = mann2019_mass_radius(Kmag=7.0, dist_pc=10.0)
    >>> print(f"M={mass:.4f} M_sun, R={radius:.4f} R_sun, fallback={fb}")
    M=0.2889 M_sun, R=0.3107 R_sun, fallback=False
    >>> mass, radius, fb = mann2019_mass_radius(Kmag=8.1, dist_pc=15.0)
    >>> print(f"M={mass:.3f} M_sun, R={radius:.3f} R_sun, fallback={fb}")
    M=0.261 M_sun, R=0.286 R_sun, fallback=False
    """
    import numpy as np

    M_KS_MIN, M_KS_MAX = 4.5, 10.0
    ZP = 7.5
    MASS_A = (-0.642, -0.208, -8.43e-4, 7.87e-3, 1.42e-4, -2.13e-4)
    MASS_A_FEH = (-0.647, -0.207, -6.53e-4, 7.13e-3, 1.84e-4, -1.60e-4)
    MASS_F = -0.0035
    RAD_B = (1.9515, -0.3520, 0.01680)
    RAD_B_FEH = (1.9305, -0.3466, 0.01647)
    RAD_F = -0.04458

    def _fallback(reason: str) -> Tuple[float, float, bool]:
        if verbose:
            print(f'  [mann2019] {reason} Using fallback '
                  f'M={fallback_mass}, R={fallback_radius}.')
        return float(fallback_mass), float(fallback_radius), True

    try:
        Kmag = float(Kmag)
        dist_pc = float(dist_pc)
    except (TypeError, ValueError):
        return _fallback(f'Non-numeric inputs: Kmag={Kmag}, dist_pc={dist_pc}.')

    if not (np.isfinite(Kmag) and np.isfinite(dist_pc)) or dist_pc <= 0.0:
        return _fallback(f'Invalid inputs: Kmag={Kmag}, dist_pc={dist_pc}.')

    M_Ks = Kmag - 5.0 * np.log10(dist_pc / 10.0)
    if verbose:
        print(f'  [mann2019] M_Ks = {M_Ks:.4f}')

    if not (M_KS_MIN <= M_Ks <= M_KS_MAX):
        return _fallback(f'M_Ks={M_Ks:.3f} outside [{M_KS_MIN}, {M_KS_MAX}].')

    apply_feh = bool(use_metallicity)
    if apply_feh:
        try:
            feh = float(feh)
        except (TypeError, ValueError):
            feh = np.nan
        if not np.isfinite(feh):
            if verbose:
                print('  [mann2019] use_metallicity=True but feh is not finite; '
                      'using the [Fe/H]-free relations.')
            apply_feh = False

    x = M_Ks - ZP
    if apply_feh:
        mass = (1.0 + MASS_F * feh) * 10.0 ** np.polynomial.polynomial.polyval(x, MASS_A_FEH)
        radius = np.polynomial.polynomial.polyval(M_Ks, RAD_B_FEH) * (1.0 + RAD_F * feh)
    else:
        mass = 10.0 ** np.polynomial.polynomial.polyval(x, MASS_A)
        radius = np.polynomial.polynomial.polyval(M_Ks, RAD_B)

    if not (0.05 < mass < 1.0) or not (0.05 < radius < 1.0):
        return _fallback(f'Unphysical result: M={mass:.4f}, R={radius:.4f}.')

    if verbose:
        print(f'  [mann2019] M={mass:.4f} M_sun, R={radius:.4f} R_sun '
              f'(metallicity terms: {apply_feh})')

    return float(mass), float(radius), False

def get_qld(star,
            verbose,
            mdwarf_fallback_mass: float = 0.4,
            mdwarf_fallback_radius: float = 0.4):    
    """
    Retrieves quadratic limb darkening coefficients 'a' and 'b' 
    for a given star, based on its effective temperature and 
    surface gravity.

    This function calculates the limb darkening coefficients 'a' and 'b'
    by finding the nearest match of the star's effective temperature (Teff)
    and surface gravity (logg) in a pre-defined limb darkening table.
    If the stellar mass or radius is missing or non-finite, it uses a mass-radius
    relation for M-dwarf stars to estimate them.
    
    Handles three cases for missing stellar parameters:

    1. Both ``rad`` and ``mass`` are finite: no imputation, proceeds normally.
    2. One of ``rad`` / ``mass`` is non-finite: imputed via
       ``mass_radius_mdwarf_relation`` (M ~ R in solar units).
    3. Both ``rad`` and ``mass`` are non-finite: imputed using
       ``mann2019_mass_radius`` from the target's ``Kmag`` and ``dist``
       columns (Mann+2019 mass, Mann+2015 radius). If those inputs are
       also unavailable or out of range, falls back to
       ``mdwarf_fallback_mass`` / ``mdwarf_fallback_radius``.

    In cases 2 and 3, imputed values are written back into the DataFrame
    so that ``TLS_func`` and ``BLS_func`` receive finite values and are
    not blocked by their ``np.isfinite`` gate. A boolean column
    ``params_imputed`` is always added (``True`` when any imputation
    occurred).

    Parameters:
    -----------
    star : pandas.DataFrame
        A DataFrame containing stellar parameters for a single star. 
        Expected columns include:
        - 'rad': Stellar radius in solar radii.
        - 'mass': Stellar mass in solar masses.
        - 'Teff': Effective temperature in Kelvin.
        - 'logg': Surface gravity (log g) in cgs units.
        - 'ID': TIC ID of the star.
    mdwarf_fallback_mass : float, optional
        Fallback stellar mass in solar masses used only when both
        ``mass`` / ``rad`` are non-finite AND ``mann2019_mass_radius``
        also cannot produce a valid estimate. Default 0.4 M_sun.
    mdwarf_fallback_radius : float, optional
        Fallback stellar radius in solar radii under the same conditions.
        Default 0.4 R_sun.        
        
    verbose : bool
        If `True`, the function will print additional information during execution.

    Returns:
    --------
    star : pd.DataFrame
        Input DataFrame with ``qld_a``, ``qld_b``, and ``params_imputed``
        columns added (and ``rad``, ``mass``, ``e_rad``, ``e_mass``
        updated in place if imputation occurred).
    Notes
    -----
    Uncertainties on imputed parameters are set to 10% of the imputed
    value, consistent with the existing convention in ``TLS_func``.
    Targets with ``params_imputed=True`` should be flagged in survey
    completeness analysis; derived planetary radii for these targets
    carry additional systematic uncertainty.

    Example
    -------
    >>> star = nearby_star_catalog.loc[nearby_star_catalog['ID'] == str(TIC_ID)].reset_index(drop=True)
    >>> star = get_qld(star, verbose=True)
    >>> print(star['qld_a'].item(), star['qld_b'].item(), star['params_imputed'].item())
    """
    from transitleastsquares import tls_constants
    import numpy as np
    from os import path

    radius = star['rad'].item()
    mass   = star['mass'].item()
    Teff   = star['Teff'].item()
    logg   = star['logg'].item()
    TIC_ID = star['ID'].item()

    imputed = False

    if not np.isfinite(radius) or not np.isfinite(mass):
        imputed = True
        print(f'TIC {TIC_ID} has no known Stellar Mass or Radius in TIC.')

        # ── Case 3: both NaN — attempt Mann+2019/2015 from Kmag + dist ───────
        if not np.isfinite(radius) and not np.isfinite(mass):
            Kmag = star['Kmag'].item()
            dist = star['d'].item()
            mass, radius, used_fallback = mann2019_mass_radius(
                Kmag=Kmag,
                dist_pc=dist,
                fallback_mass=mdwarf_fallback_mass,
                fallback_radius=mdwarf_fallback_radius,
                verbose=verbose,
            )
            if used_fallback:
                print(
                    f'  TIC {TIC_ID}: Mann+2019 estimate unavailable '
                    f'(Kmag={Kmag:.3f}, dist={dist:.1f} pc). '
                    f'Using fixed fallback: M={mass} M_sun, R={radius} R_sun.'
                )
            else:
                print(
                    f'  TIC {TIC_ID}: Both M and R imputed via Mann+2019/2015: '
                    f'M={mass:.4f} M_sun, R={radius:.4f} R_sun.'
                )

        # ── Case 2: one is finite — use M ~ R relation ────────────────────────
        else:
            mass, radius = mass_radius_mdwarf_relation(mass, radius)
            print(
                f'  TIC {TIC_ID}: One parameter was finite. '
                f'Using M ~ R relation: M={mass:.4f} M_sun, R={radius:.4f} R_sun.'
            )

        # ── Write imputed values back so TLS_func / BLS_func see finite params -
        star = star.copy()  # avoid SettingWithCopyWarning on .loc slice
        star['rad']    = radius
        star['mass']   = mass
        star['e_rad']  = radius / 10.0
        star['e_mass'] = mass   / 10.0

        if verbose:
            print(
                f'  Final: M_star={mass:.4f} M_sun, R_star={radius:.4f} R_sun '
                f'(params_imputed=True)'
            )

    star['params_imputed'] = imputed

    # ── Limb-darkening table lookup (unchanged from original) ─────────────────
    ld = np.genfromtxt(
        path.join(tls_constants.resources_dir, 'ld_claret_tess.csv'),
        skip_header=1, delimiter=',', dtype='f8, int32, f8, f8',
        names=['logg', 'Teff', 'a', 'b'],
    )
    nearest_Teff  = ld['Teff'][(np.abs(ld['Teff'] - Teff)).argmin()]
    idx_all_Teffs = np.where(ld['Teff'] == nearest_Teff)
    relevant_lds  = np.copy(ld[idx_all_Teffs])
    idx_nearest   = np.abs(relevant_lds['logg'] - logg).argmin()
    a = relevant_lds['a'][idx_nearest]
    b = relevant_lds['b'][idx_nearest]

    star['qld_a'] = a
    star['qld_b'] = b

    return star
