def format_ax(ax, hdu):
    """
    This function will format the subplot
    used for plotting the input TESS Full Frame Image or 
    Target Pixel File (FFI/TPF).
    Input Parameters
    ----------
    ax : Matplotlib pyplot subplot axis
    hdu : FITS object
        Astropy Header Data Unit List of TESS FFI/TPF for target star.
        Contains PrimaryHDU, BinTableHDU and ImageHDU.
    Returns
    -------
        * Nothing.
    """        
    ax.set_xlim(-0.5, np.shape(hdu[1].data['FLUX'][0])[0] - 0.5)
    ax.set_ylim(-0.5, np.shape(hdu[1].data['FLUX'][0])[1] - 0.5)

    # WCS axes: only set labels through ax.coords — never through
    # ax.set_xlabel / ax.set_ylabel, which add a second independent
    # label on top of the coordinate label.
    ax.coords[0].set_axislabel('RA',  minpad=1)   # was minpad=2
    ax.coords[1].set_axislabel('DEC', minpad=1)   # was minpad=-2  ← caused overlap

    # 'd.dd' (2 dp) is wide enough for unambiguous sky coords on an
    # 11-pix cutout while keeping tick labels from overflowing.
    ax.coords[0].set_major_formatter('d.dd')      # was 'd.ddd'
    ax.coords[1].set_major_formatter('d.dd')

    ax.set_title('Aperture and Background Masks')
    #NEW
    fix_wcs_axis_labels(ax, ra_label="RA", dec_label="DEC", fontsize=10)
#
#
#    
def plot_mask(mask,mask_color,ax):
    """
    This function is used to plot a
    pixel mask on a subplot.
    Input Parameters
    ----------
    mask : array
        Input pixel mask array
    mask_color : str
        Input pixel mask color 
    ax : Matplotlib pyplot subplot axis
    Returns
    -------
        * Nothing.
    """    
    from matplotlib import patches
    irange = np.shape(mask)[0]
    jrange = np.shape(mask)[1]
    for i in range(irange):
        for j in range(jrange):
            if mask[i, j]:
                rect = patches.Rectangle(xy=(j-0.5, i-0.5),width=1,height=1,color=mask_color,fill=False,hatch="//")  
                ax.add_patch(rect)
