def plot_sources(starname,catalogData,cut_catalogData,hdu,ax,
                 Sector,cadence,reference_pixel,
                 pix_mask, default_settings):
    """
    This function will plot catalog sources and centroid positions. 
    Input Parameters
    ----------
    starname : str
        Example: TIC 1234567
    catalogData : astropy.table.table.Table
        A table of nearby TIC sources.
    cut_catalogData : astropy.table.table.Table
        A table of nearby TIC sources that are flagged as being
        within the input photometric aperture pixel mask.
    hdu : FITS object
    Astropy Header Data Unit List of TESS FFI/TPF for target star.
    Contains PrimaryHDU, BinTableHDU and ImageHDU.
    ax : Matplotlib pyplot subplot axis
    Sector : int
        TESS Sector number
    cadence : str
        The desired cadence of TESS observations for input target star.
    reference_pixel : list
        A list of X,Y coordinates of the FFI/TPF Row,Column 
        pixel location of the target star.    
    pix_mask : array
        Input aperture pixel mask array    
    path : str
        Pathname of desired location to store NEMESIS data products.
    savelcpath : str
        Pathname of directory for output NEMESIS light curves.

    Returns
    -------
        * Nothing.
    """    
    # get function settings
    get_all_sectors = default_settings.get('get_all_sectors')
    path = default_settings.get('path')
    savelcpath = default_settings.get('savelcpath')
    verbose = default_settings.get('verbose')
    wcs = check_wcs(hdu)  # use first FFI/TPF
    #
    radecs = np.vstack([np.array(catalogData['ra']),np.array(catalogData['dec'])]).T
    if len(cut_catalogData) >0:
        cut_radecs = np.vstack([np.array(cut_catalogData['ra']),np.array(cut_catalogData['dec'])]).T
    #
    radial_coords = wcs.all_world2pix(radecs, 0)
    if len(cut_catalogData) >0:    
        coords = wcs.all_world2pix(cut_radecs, 0)
    #
    #
    offset=0
    if len(cut_catalogData) >0:    
        df = pd.DataFrame(data=dict(x=coords[:, 0]+offset, y=coords[:, 1]+offset, mag=cut_catalogData['Tmag'], IDs=cut_catalogData['ID']))
        #
        df=df.sort_values(by=['mag']).reset_index()
        del df['index']
    radial_df = pd.DataFrame(data=dict(x=radial_coords[:, 0]+offset, y=radial_coords[:, 1]+offset, mag=catalogData['Tmag'], IDs=catalogData['ID']))
    radial_df=radial_df.sort_values(by=['mag']).reset_index()
    del radial_df['index']
    #
    radial_mag = radial_df.loc[radial_df['IDs']==(starname[4:])]['mag'].item()
    if len(cut_catalogData) >0:  
        try:
            mag = df.loc[df['IDs']==(starname[4:])]['mag'].item()
        except ValueError:
            mag = radial_df.loc[radial_df['IDs']==(starname[4:])]['mag'].item()
    else:
        mag = radial_df.loc[radial_df['IDs']==(starname[4:])]['mag'].item()
    for x in reversed(range(len(radial_df))): #s=base_ms / 2 ** dmag,
        size = (128.0 / 2**((1/2.5)*(radial_df['mag'][x]-mag)))
        ax.scatter(radial_df['x'][x],radial_df['y'][x],s=size,color='green',zorder=10,alpha=0.6)   
        if radial_df['mag'][x] <=16:
            if radial_df['mag'][x]-mag==0:
                pass
            else:
                ax.text(radial_df['x'][x]+0.1,radial_df['y'][x]+0.1,int(radial_df['mag'][x]-mag),\
                         color='black',weight='bold', zorder=100,fontsize=14)
                ax.text(radial_df['x'][x]+0.1,radial_df['y'][x]+0.1,int(radial_df['mag'][x]-mag),\
                         color='pink', zorder=100,fontsize=12)   
    ##########
    if len(cut_catalogData) >0:    
        for x in reversed(range(len(df))): #s=base_ms / 2 ** dmag,
            size = (128.0 / 2**((1/2.5)*(df['mag'][x]-mag)))
            ax.scatter(df['x'][x],df['y'][x],s=size,color='cyan',zorder=10,alpha=0.6)   
            if df['mag'][x] <=16:
                if df['mag'][x]-mag==0:
                    pass
                else:
                    ax.text(df['x'][x]+0.1,df['y'][x]+0.1,int(df['mag'][x]-mag),\
                             color='black',weight='bold', zorder=100,fontsize=14)
                    ax.text(df['x'][x]+0.1,df['y'][x]+0.1,int(df['mag'][x]-mag),\
                             color='pink', zorder=100,fontsize=12)
    #
    ax.scatter(radial_df.loc[radial_df['IDs']==(starname[4:])]['x'],\
                radial_df.loc[radial_df['IDs']==(starname[4:])]['y'],\
                marker='x',c='white',s=15**2,zorder = 11)
    if len(cut_catalogData) >0:    
        df = pd.DataFrame(data=dict(x=coords[:, 0]+offset, y=coords[:, 1]+offset, mag=cut_catalogData['Tmag'], IDs=cut_catalogData['ID']))
        ax.scatter(df.loc[df['IDs']==(starname[4:])]['x'],\
                    df.loc[df['IDs']==(starname[4:])]['y'],\
                    marker='x',c='white',s=15**2,zorder = 11)    
    #
    #now plot centroid positions
    median_image = np.nanmedian(hdu[1].data['FLUX'],axis=0)
    centx,centy = centroid_quadratic(median_image, pix_mask,reference_pixel)
    cutoutsize=np.shape(hdu[1].data['FLUX'][0])[0]
    if verbose==True:
        print('plot_sources: Sector',Sector)
    cxs,cys = check_centroids(ID=int(starname[4:]), Sector=Sector,cadence=cadence, 
                              reference_pixel=reference_pixel, default_settings=default_settings)
    #
    ax.scatter(centx,centy,\
                marker='X',c='red',s=15**2,zorder = 10)
    ax.scatter(reference_pixel[0]-1,reference_pixel[1]-1,\
                marker='X',c='yellow',s=13**2,zorder = 10)
    ax.scatter(cxs,cys,c='purple',marker='.',s=5**2,alpha=0.5,zorder = 9)
#        
#
#
def plot_sources_TIC(
    ID: int,
    hdu,
    ax,
    tic_catalog, 
    pix_mask=None,
    reference_pixel=None,
    Sector=None,
    cadence=None,
    default_settings=None,
    show_centroids: bool = True,
    label_dtmag_max: float = 6.0,
    legend_loc: str = "lower right",
    fontsize: int = 12,
    source_color: str = "cyan",
    in_aperture_edge_color: str = "deepskyblue",
    target_marker_color: str = "white",
    draw_legend=True,
):
    """
    Tpfplotter-style TIC source overlay on a TESS cutout.

    Marker size encodes ΔTmag contrast:
        size = 128 / 2 ** ((Tmag - Tmag_target) / 2.5)

    All sources share ``source_color`` (default cyan, matching the legacy
    NEMESIS palette). Sources inside ``pix_mask`` get an edge ring in
    ``in_aperture_edge_color``. The target is marked with a white X.

    Pixel positions are taken from ``x_pix``/``y_pix`` columns if present
    (added by ``get_sources_in_aperture_mask`` or similar), otherwise
    projected from ``ra``/``dec`` via ``check_wcs(hdu)``.

    Parameters
    ----------
    ID : int
        TIC target identifier.
    hdu : fits.HDUList
        NEMESIS HDUList for WCS and centroid access.
    ax : matplotlib.axes.Axes
        WCS-projected axes (same as used for the image).
    tic_catalog : pd.DataFrame
        From ``collect_nearby_TIC_params``. Required columns: 'ID', 'ra',
        'dec', 'Tmag'. Optional: 'x_pix', 'y_pix'.
    pix_mask : np.ndarray[bool] or None
        Aperture mask for in-aperture source highlighting.
    reference_pixel : list or None
        [col, row] of the target pixel centre; used for centroid overlay
        and as fallback target marker.
    Sector, cadence, default_settings
        Forwarded to ``check_centroids`` when ``show_centroids=True``.
    show_centroids : bool
        Draw centroid markers. Default True.
    label_dtmag_max : float
        Suppress ΔTmag labels fainter than this. Default 6.0.
    legend_loc : str
        Legend placement. Default 'lower right'.
    fontsize : int
        Base font size. Default 12.
    source_color : str
        Fill color for all TIC source markers. Default 'cyan'.
    in_aperture_edge_color : str
        Edge-ring color for in-aperture sources. Default 'deepskyblue'.
    target_marker_color : str
        Color of the target X marker. Default 'white'.

    Returns
    -------
    info : dict
        Keys: 'x', 'y', 'in_aperture', 'target_index'.
    """
    import numpy as np
    from astropy import units as u

    df = tic_catalog.copy().reset_index(drop=True)
    df["ID"] = df["ID"].astype(str)

    # ── pixel positions ───────────────────────────────────────────────────────
    if {"x_pix", "y_pix"}.issubset(df.columns):
        x = df["x_pix"].to_numpy(dtype=float)
        y = df["y_pix"].to_numpy(dtype=float)
    else:
        wcs = check_wcs(hdu)
        ra  = df["ra"].to_numpy(dtype=float)
        dec = df["dec"].to_numpy(dtype=float)
        xy  = wcs.all_world2pix(np.vstack([ra, dec]).T, 0)
        x, y = xy[:, 0], xy[:, 1]

    # ── marker sizes from ΔTmag (tpfplotter convention) ──────────────────────
    tmags = df["Tmag"].to_numpy(dtype=float)

    target_tmag = None
    sel_t = df.loc[df["ID"] == str(ID), "Tmag"]
    if len(sel_t) > 0:
        target_tmag = float(sel_t.iloc[0])
    if target_tmag is None:
        target_tmag = float(np.nanmin(tmags))

    dtmag = tmags - target_tmag
    sizes = 128.0 / 2.0 ** (dtmag / 2.5)

    # ── in-aperture flag ──────────────────────────────────────────────────────
    in_ap = np.zeros(len(df), dtype=bool)
    if pix_mask is not None:
        pm = pix_mask[0] if pix_mask.ndim == 3 else pix_mask
        ny_m, nx_m = pm.shape
        ix = np.round(x).astype(int)
        iy = np.round(y).astype(int)
        valid = (ix >= 0) & (ix < nx_m) & (iy >= 0) & (iy < ny_m)
        in_ap[valid] = pm[iy[valid], ix[valid]]

    # ── scatter: all sources ──────────────────────────────────────────────────
    ax.scatter(x, y, s=sizes, c=source_color, alpha=0.7,
               edgecolors="none", zorder=10)

    # ── edge ring for in-aperture sources ─────────────────────────────────────
    if in_ap.any():
        ax.scatter(x[in_ap], y[in_ap], s=sizes[in_ap],
                   facecolors="none", edgecolors=in_aperture_edge_color,
                   linewidths=1.8, zorder=11)

    # ── target X marker ───────────────────────────────────────────────────────
    target_idx = None
    sel = np.where(df["ID"].values == str(ID))[0]
    if len(sel) > 0:
        target_idx = int(sel[0])
        ax.scatter(x[target_idx], y[target_idx], marker="x",
                   c=target_marker_color, s=15**2, zorder=12, lw=2)
    elif reference_pixel is not None:
        ax.scatter(reference_pixel[0], reference_pixel[1], marker="x",
                   c=target_marker_color, s=15**2, zorder=12, lw=2)

    # ── ΔTmag labels ─────────────────────────────────────────────────────────
    for i in range(len(df)):
        if i == target_idx or dtmag[i] > label_dtmag_max:
            continue
        label = f"{int(round(dtmag[i])):+d}"
        ax.text(x[i] + 0.15, y[i] + 0.15, label,
                color="black", weight="bold",
                fontsize=fontsize - 2, zorder=100)
        ax.text(x[i] + 0.15, y[i] + 0.15, label,
                color="white",
                fontsize=fontsize - 2, zorder=99)

    if draw_legend:
        # Adaptive legend: 3 evenly spaced integer ΔTmag values from 0
        # (target) to the faintest source actually present in the image.
        finite_positive = dtmag[np.isfinite(dtmag) & (dtmag >= 0)]
        max_dt = int(np.ceil(np.nanmax(finite_positive))) if len(finite_positive) > 0 else 4
        n_steps = min(3, max_dt + 1)
        legend_dts = sorted({int(round(v))
                             for v in np.linspace(0, max_dt, n_steps)})

        legend_handles, legend_labels = [], []
        for dm in legend_dts:
            s = 128.0 / 2.0 ** (dm / 2.5)
            h = ax.scatter([], [], s=s, c=source_color, alpha=0.7,
                           edgecolors="none")
            legend_handles.append(h)
            legend_labels.append(fr"$\Delta Tmag = {dm:+d}$")
        if pix_mask is not None:
            h = ax.scatter([], [], s=80, facecolors="none",
                           edgecolors=in_aperture_edge_color, linewidths=1.8)
            legend_handles.append(h)
            legend_labels.append("in aperture")

        ax.legend(legend_handles, legend_labels, loc=legend_loc, ncol=1,
                  fontsize=fontsize - 2, framealpha=0.7,
                  borderpad=0.3, handletextpad=0.6, labelspacing=0.5)


    # ── centroids (identical to plot_sources_gaia) ────────────────────────────
    if show_centroids and pix_mask is not None and reference_pixel is not None:
        try:
            from photutils.centroids import centroid_quadratic
            pm = pix_mask[0] if pix_mask.ndim == 3 else pix_mask
            median_image = np.nanmedian(hdu[1].data["FLUX"], axis=0)
            cx, cy = centroid_quadratic(median_image, mask=~pm,
                                        xpeak=reference_pixel[0],
                                        ypeak=reference_pixel[1])
            ax.scatter(cx, cy, marker="X", c="red", s=15**2, zorder=10)
            ax.scatter(reference_pixel[0] - 1, reference_pixel[1] - 1,
                       marker="X", c="yellow", s=13**2, zorder=10)
            if (default_settings is not None and Sector is not None
                    and cadence is not None):
                cxs, cys = check_centroids(
                    ID=int(ID), Sector=Sector, cadence=cadence,
                    reference_pixel=reference_pixel,
                    default_settings=default_settings,
                )
                ax.scatter(cxs, cys, c="purple", marker=".",
                           s=5**2, alpha=0.5, zorder=9)
        except Exception as exc:
            if default_settings is not None and default_settings.get("verbose"):
                print(f"[plot_sources_TIC] centroid overlay skipped: {exc}")

    return {"x": x, "y": y, "in_aperture": in_ap, "target_index": target_idx,
            "dtmag": dtmag, "target_tmag": target_tmag}

def plot_sources_gaia(
    ID: int,
    hdu,
    ax: plt.Axes,
    gaia_catalog: pd.DataFrame,
    target_gaia_id: str,
    target_gmag: float,
    pix_mask: Optional[np.ndarray] = None,
    reference_pixel: Optional[list] = None,
    Sector: Optional[int] = None,
    cadence: Optional[str] = None,
    default_settings: Optional[dict] = None,
    show_pm: bool = False,
    show_centroids: bool = True,
    apply_pm_correction: bool = True,
    label_dmag_max: float = 6.0,
    legend_loc: str = "lower right",
    fontsize: int = 12,
    source_color: str = "gold",
    in_aperture_edge_color: str = "deepskyblue",
    target_marker_color: str = "white",
    draw_legend = True,
) -> dict:
    """
    Overlay Gaia DR3 sources on a TESS cutout with PM correction to the
    cutout epoch.

    Color/marker convention is intentionally minimal to avoid the
    "two catalogs?" confusion of the previous version:

    * ALL Gaia sources share the same fill color (``source_color``,
      default gold).
    * Sources whose projected position falls inside ``pix_mask`` are
      additionally outlined with a colored ring (``in_aperture_edge_color``,
      default deepskyblue).
    * Marker AREA encodes Gmag contrast: ``128 / 2**(G - G_target)``.
    * The target itself is marked with a white X.
    * One unified legend: ΔG size scale plus an explicit "in aperture" key.

    If ``gaia_catalog`` carries precomputed ``x_pix`` / ``y_pix`` columns
    (i.e. it came from the bbox-aware ``collect_nearby_Gaia_params``),
    those are used directly and the WCS reprojection is skipped.

    Parameters
    ----------
    See previous version. New / changed:
    source_color : str
        Fill color for all Gaia source markers. Default 'gold' (chosen to
        contrast with the red aperture mask and the gray image).
    in_aperture_edge_color : str
        Edge-ring color for in-aperture sources. Default 'deepskyblue'.

    Returns
    -------
    info : dict
        Keys: 'x', 'y', 'in_aperture', 'target_index'.
    """
    df = gaia_catalog.copy().reset_index(drop=True)
    df["ID"] = df["ID"].astype(str)

    # 1. Pixel coords: trust precomputed if present, else reproject.
    if {"x_pix", "y_pix"}.issubset(df.columns):
        x = df["x_pix"].to_numpy(dtype=float)
        y = df["y_pix"].to_numpy(dtype=float)
    else:
        wcs = check_wcs(hdu)
        ra = df["ra"].to_numpy(dtype=float)
        dec = df["dec"].to_numpy(dtype=float)
        if apply_pm_correction and {"pmRA", "pmDEC"}.issubset(df.columns):
            try:
                t0_btjd = float(np.atleast_1d(hdu[1].data["TIME"])[0])
                t0_jd = t0_btjd + 2457000.0
            except Exception:
                t0_jd = 2458324.5
            dt_yr = ((t0_jd - 2457206.375) * u.day).to(u.year).value
            pmra = np.nan_to_num(df["pmRA"].to_numpy(dtype=float))
            pmde = np.nan_to_num(df["pmDEC"].to_numpy(dtype=float))
            cosdec = np.cos(np.deg2rad(dec))
            cosdec = np.where(np.abs(cosdec) < 1e-6, 1.0, cosdec)
            ra = ra + (pmra * dt_yr / 3.6e6) / cosdec
            dec = dec + (pmde * dt_yr / 3.6e6)
        xy = wcs.all_world2pix(np.vstack([ra, dec]).T, 0)
        x, y = xy[:, 0], xy[:, 1]

    # 2. Marker sizes from Gmag contrast.
    gmags = df["Gmag"].to_numpy(dtype=float)
    dmag = gmags - float(target_gmag)
    sizes = 128.0 / 2.0 ** dmag

    # 3. In-aperture flag.
    in_ap = np.zeros(len(df), dtype=bool)
    if pix_mask is not None:
        ny, nx = pix_mask.shape
        ix = np.round(x).astype(int)
        iy = np.round(y).astype(int)
        valid = (ix >= 0) & (ix < nx) & (iy >= 0) & (iy < ny)
        in_ap[valid] = pix_mask[iy[valid], ix[valid]]

    # 4. Single-color scatter for all Gaia sources.
    ax.scatter(x, y, s=sizes, c=source_color, alpha=0.7,
               edgecolors="none", zorder=10)

    # 5. Edge-ring overlay for in-aperture sources (same size, no fill).
    if in_ap.any():
        ax.scatter(x[in_ap], y[in_ap], s=sizes[in_ap],
                   facecolors="none", edgecolors=in_aperture_edge_color,
                   linewidths=1.8, zorder=11)

    # 6. Target X marker.
    target_idx = None
    sel = np.where(df["ID"].values == str(target_gaia_id))[0]
    if len(sel) > 0:
        target_idx = int(sel[0])
        ax.scatter(x[target_idx], y[target_idx], marker="x",
                   c=target_marker_color, s=15 ** 2, zorder=12, lw=2)
    elif reference_pixel is not None:
        ax.scatter(reference_pixel[0], reference_pixel[1], marker="x",
                   c=target_marker_color, s=15 ** 2, zorder=12, lw=2)

    # 7. Numeric ΔG labels (skip target; skip very faint).
    for i in range(len(df)):
        if i == target_idx or dmag[i] > label_dmag_max:
            continue
        label = f"{int(round(dmag[i])):+d}"
        ax.text(x[i] + 0.15, y[i] + 0.15, label,
                color="black", weight="bold",
                fontsize=fontsize - 2, zorder=100)
        ax.text(x[i] + 0.15, y[i] + 0.15, label,
                color="white",
                fontsize=fontsize - 2, zorder=99)

    if draw_legend:
        finite_positive = dmag[np.isfinite(dmag) & (dmag >= 0)]
        max_dm = int(np.ceil(np.nanmax(finite_positive))) if len(finite_positive) > 0 else 4
        n_steps = min(3, max_dm + 1)
        legend_dms = sorted({int(round(v))
                             for v in np.linspace(0, max_dm, n_steps)})

        legend_handles, legend_labels = [], []
        for dm_val in legend_dms:
            s = 128.0 / 2.0 ** dm_val
            h = ax.scatter([], [], s=s, c=source_color, alpha=0.7,
                           edgecolors="none")
            legend_handles.append(h)
            legend_labels.append(fr"$\Delta G = {dm_val:+d}$")
        if pix_mask is not None:
            h = ax.scatter([], [], s=80, facecolors="none",
                           edgecolors=in_aperture_edge_color, linewidths=1.8)
            legend_handles.append(h)
            legend_labels.append("in aperture")

        ax.legend(legend_handles, legend_labels, loc=legend_loc, ncol=1,
                  fontsize=fontsize - 2, framealpha=0.7,
                  borderpad=0.3, handletextpad=0.6, labelspacing=0.5)

    # 9. Optional centroids (unchanged).
    if show_centroids and pix_mask is not None and reference_pixel is not None:
        try:
            from photutils.centroids import centroid_quadratic
            median_image = np.nanmedian(hdu[1].data["FLUX"], axis=0)
            cx, cy = centroid_quadratic(median_image, mask=~pix_mask,
                                        xpeak=reference_pixel[0],
                                        ypeak=reference_pixel[1])
            ax.scatter(cx, cy, marker="X", c="red", s=15 ** 2, zorder=10)
            ax.scatter(reference_pixel[0] - 1, reference_pixel[1] - 1,
                       marker="X", c="yellow", s=13 ** 2, zorder=10)
            if (default_settings is not None and Sector is not None
                    and cadence is not None):
                cxs, cys = check_centroids(
                    ID=int(ID), Sector=Sector, cadence=cadence,
                    reference_pixel=reference_pixel,
                    default_settings=default_settings,
                )
                ax.scatter(cxs, cys, c="purple", marker=".", s=5 ** 2,
                           alpha=0.5, zorder=9)
        except Exception as exc:
            if default_settings is not None and default_settings.get("verbose"):
                print(f"[plot_sources_gaia] centroid overlay skipped: {exc}")

    return {"x": x, "y": y, "in_aperture": in_ap, "target_index": target_idx,
            "dmag": dmag, "target_gmag": target_gmag}


def collect_nearby_Gaia_params(
    ID: int,
    hdu,
    magnitude_limit: Optional[float] = None,
    use_dr2: bool = False,
    pix_scale_arcsec: float = 21.0,
    border_pixels: float = 0.5,
    apply_pm_correction: bool = True,
    keep_target_regardless: bool = True,
    verbose: bool = False,
    downloadpath: Optional[str] = None,
) -> Tuple[pd.DataFrame, str, float]:
    """
    Query Vizier (Gaia DR3 by default) for sources within the TPF/FFI footprint
    and restrict the returned catalog to those whose (optionally PM-corrected)
    positions project inside the cutout's rectangular bounding box.

    Vizier only supports circular cone queries, so the initial radius is set to
    the cutout's half-diagonal plus a small pad; sources outside the rectangle
    are then rejected via WCS reprojection. This eliminates the roughly
    (1 - 4/pi) ~ 21% of sources that fall in the corner-region of the
    circumscribed circle but lie outside the square cutout.

    Returned columns extend NEMESIS conventions with three diagnostic fields:
    ``'x_pix'``, ``'y_pix'`` (projected cutout-pixel positions used by
    ``plot_sources_gaia``) and ``'in_bbox'`` (the spatial filter result).

    Parameters
    ----------
    ID : int
        TIC identifier of the target.
    hdu : astropy.io.fits.HDUList
        TPF/FFI HDUList in the NEMESIS convention. Image shape comes from
        ``hdu[1].data['FLUX'].shape``; WCS comes from ``check_wcs(hdu)``.
    magnitude_limit : float, optional
        Absolute Gmag cutoff. Defaults to target Gmag + 5.0.
    use_dr2 : bool, optional
        Query Gaia DR2 instead of DR3. Default False.
    pix_scale_arcsec : float, optional
        TESS pixel scale in arcsec/pixel. Default 21.0.
    border_pixels : float, optional
        Half-pixel slack on the bounding-box filter so sources exactly on the
        cutout edge are retained. Default 0.5. Set higher (e.g. 1.0 to 2.0)
        to keep just-off-edge sources whose PRF wings contaminate the
        aperture; set 0.0 for a strict pixel-coverage filter.
    apply_pm_correction : bool, optional
        Propagate Gaia positions to the cutout epoch before applying the
        bounding-box cut. Default True. Strongly recommended for M-dwarfs.
    keep_target_regardless : bool, optional
        Retain the target row even if its PM-corrected position falls
        outside the bounding box. Default True (defensive).
    verbose : bool, optional
        Print diagnostics. Default False.
    downloadpath : str, optional
        astroquery cache directory. Default None.

    Returns
    -------
    gaia_df : pd.DataFrame
        Sources inside the cutout bounding box, sorted by Gmag ascending.
        Columns:
        ``['ID', 'ra', 'dec', 'pmRA', 'pmDEC', 'plx',
        'Gmag', 'BPmag', 'RPmag', 'ra_epoch', 'dec_epoch',
        'x_pix', 'y_pix', 'in_bbox']``.
        ``ra_epoch`` / ``dec_epoch`` are PM-propagated sky positions; if
        ``apply_pm_correction=False`` these equal ``ra`` / ``dec``.
    target_gaia_id : str
        Gaia source ID of the target (DR3 or DR2 depending on ``use_dr2``).
    target_gmag : float
        Target Gaia G-band magnitude.

    Examples
    --------
    >>> gdf, gid, gmag = collect_nearby_Gaia_params(
    ...     ID=259377017, hdu=hdu, border_pixels=0.5, verbose=True)
    >>> assert (gdf['x_pix'].between(-0.5, hdu[1].data['FLUX'].shape[2] - 0.5)).all()
    """
    from astroquery.mast import Catalogs, Tesscut
    from astroquery.gaia import Gaia
    from astroquery.vizier import Vizier
    from astropy.coordinates import Angle
    # we don't actually want to cache these queries...
    import tempfile as _tmpfile
    import astropy.utils.data as _aud

    _gaia_tmpdir = _tmpfile.mkdtemp()
    _saved_astropy_cache = _aud.conf.cache_dir

    Catalogs.cache_location = _gaia_tmpdir
    Vizier.cache_location = _gaia_tmpdir
    Gaia.cache_location = _gaia_tmpdir
    _aud.conf.cache_dir = _gaia_tmpdir
    
#     if downloadpath is not None:
#         Catalogs.cache_location = downloadpath
#         Vizier.cache_location = downloadpath

    gaia_cat = "I/345/gaia2" if use_dr2 else "I/355/gaiadr3"
    starname = f"TIC {ID}"

    # ----------------------------------------------------------------------
    # 1. Resolve target's Gaia source ID and Gmag from the TIC.
    # ----------------------------------------------------------------------
    tic_result = Catalogs.query_object(starname, radius=0.005, catalog="TIC")
    ids = np.asarray(tic_result["ID"].data.data, dtype=str)
    k = np.where(ids == str(ID))[0]
    if len(k) == 0:
        raise ValueError(f"TIC {ID} not found in TIC cone query.")
    k = int(k[0])
    dr2_id = str(tic_result["GAIA"].data.data[k])
    gmag_tic = float(tic_result["GAIAmag"].data.data[k])
    if dr2_id in ("", "--"):
        raise ValueError(
            f"No Gaia DR2 ID stored in TIC for TIC {ID}; "
            "supply target_gaia_id and target_gmag manually."
        )

    if use_dr2:
        target_gaia_id = dr2_id
        target_gmag = gmag_tic
    else:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            job = Gaia.launch_job(
                "SELECT dr3_source_id "
                "FROM gaiadr3.dr2_neighbourhood "
                f"WHERE dr2_source_id = {dr2_id}"
            )
        dr3_ids = np.asarray(job.get_results()["dr3_source_id"]).astype(str)
        if len(dr3_ids) == 0:
            raise ValueError(
                f"No Gaia DR3 cross-match for DR2 ID {dr2_id} (TIC {ID})."
            )
        if len(dr3_ids) > 1 and verbose:
            print(f"[Gaia] {len(dr3_ids)} DR3 candidates for DR2 {dr2_id}; "
                  "selecting first.")
        target_gaia_id = str(dr3_ids[0])
        target_gmag = gmag_tic

    if magnitude_limit is None:
        magnitude_limit = target_gmag + 5.0

    # ----------------------------------------------------------------------
    # 2. Build cone radius from cutout half-diagonal + pad.
    # ----------------------------------------------------------------------
    flux_shape = hdu[1].data["FLUX"].shape   # (ncad, ny, nx)
    ny, nx = int(flux_shape[1]), int(flux_shape[2])
    half_diag_pix = 0.5 * np.hypot(ny, nx)
    cone_radius_arcsec = (half_diag_pix + max(border_pixels, 1.0)) * pix_scale_arcsec

    # ----------------------------------------------------------------------
    # 3. WCS center: prefer header object coords, fall back to CRVAL.
    # ----------------------------------------------------------------------
    wcs = check_wcs(hdu)
    hdr0 = hdu[0].header
    if "RA_OBJ" in hdr0 and "DEC_OBJ" in hdr0:
        ra_c, dec_c = float(hdr0["RA_OBJ"]), float(hdr0["DEC_OBJ"])
    else:
        ra_c, dec_c = float(wcs.wcs.crval[0]), float(wcs.wcs.crval[1])
    center = SkyCoord(ra_c, dec_c, frame="icrs", unit="deg")

    # ----------------------------------------------------------------------
    # 4. Vizier query.
    # ----------------------------------------------------------------------
    Vizier.ROW_LIMIT = -1
    try:
        result = Vizier.query_region(
            center, catalog=[gaia_cat],
            radius=Angle(cone_radius_arcsec, "arcsec"),
        )
    except Exception as exc:
        raise RuntimeError(f"Vizier Gaia query failed: {exc}") from exc

    if result is None or len(result) == 0 or gaia_cat not in result.keys():
        raise ValueError(
            f"No Gaia sources returned within {cone_radius_arcsec:.1f}'' of "
            f"({ra_c:.4f}, {dec_c:.4f})."
        )
    df = result[gaia_cat].to_pandas()

    # ----------------------------------------------------------------------
    # 5. Normalise column names to NEMESIS conventions.
    # ----------------------------------------------------------------------
    rename_map = {
        "RA_ICRS": "ra", "DE_ICRS": "dec",
        "pmRA": "pmRA", "pmDE": "pmDEC",
        "Plx": "plx",
        "Gmag": "Gmag", "BPmag": "BPmag", "RPmag": "RPmag",
        "Source": "ID",
    }
    df = df.rename(columns={a: b for a, b in rename_map.items() if a in df.columns})
    keep = [c for c in
            ["ID", "ra", "dec", "pmRA", "pmDEC", "plx", "Gmag", "BPmag", "RPmag"]
            if c in df.columns]
    df = df[keep].copy()
    df["ID"] = df["ID"].astype(str)

    # Magnitude cut first (cheap; reduces downstream WCS work).
    df = df[df["Gmag"] < magnitude_limit].reset_index(drop=True)
    if len(df) == 0:
        raise ValueError(
            f"No Gaia sources with Gmag < {magnitude_limit:.2f} in cone."
        )

    # ----------------------------------------------------------------------
    # 6. Propagate to the cutout epoch (optional).
    # ----------------------------------------------------------------------
    ra = df["ra"].to_numpy(dtype=float)
    dec = df["dec"].to_numpy(dtype=float)

    if apply_pm_correction and {"pmRA", "pmDEC"}.issubset(df.columns):
        # Gaia DR3 reference epoch J2016.0 = JD 2457206.375.
        # NEMESIS HDUs store BTJD = JD - 2457000 in TIME.
        try:
            t0_btjd = float(np.atleast_1d(hdu[1].data["TIME"])[0])
            t0_jd = t0_btjd + 2457000.0
        except Exception:
            t0_jd = 2458324.5  # ~mid Sector 1 fallback
        ref_jd = 2451544.5 if use_dr2 else 2457206.375  # J2000 (DR2) vs J2016
        dt_yr = ((t0_jd - ref_jd) * u.day).to(u.year).value
        pmra = np.nan_to_num(df["pmRA"].to_numpy(dtype=float))
        pmde = np.nan_to_num(df["pmDEC"].to_numpy(dtype=float))
        cosdec = np.cos(np.deg2rad(dec))
        cosdec = np.where(np.abs(cosdec) < 1e-6, 1.0, cosdec)
        ra_e = ra + (pmra * dt_yr / 3.6e6) / cosdec
        dec_e = dec + (pmde * dt_yr / 3.6e6)
    else:
        ra_e, dec_e = ra.copy(), dec.copy()

    df["ra_epoch"] = ra_e
    df["dec_epoch"] = dec_e

    # ----------------------------------------------------------------------
    # 7. Project to cutout pixel coordinates and apply bounding-box filter.
    # ----------------------------------------------------------------------
    xy = wcs.all_world2pix(np.vstack([ra_e, dec_e]).T, 0)
    x_pix, y_pix = xy[:, 0], xy[:, 1]
    df["x_pix"] = x_pix
    df["y_pix"] = y_pix

    lo_x, hi_x = -border_pixels, (nx - 1) + border_pixels
    lo_y, hi_y = -border_pixels, (ny - 1) + border_pixels
    in_bbox = ((x_pix >= lo_x) & (x_pix <= hi_x)
               & (y_pix >= lo_y) & (y_pix <= hi_y)
               & np.isfinite(x_pix) & np.isfinite(y_pix))
    df["in_bbox"] = in_bbox

    keep_mask = in_bbox.copy()
    if keep_target_regardless:
        target_row = (df["ID"].values == str(target_gaia_id))
        keep_mask = keep_mask | target_row

    n_total = len(df)
    df = df[keep_mask].reset_index(drop=True)
    df = df.sort_values("Gmag").reset_index(drop=True)

    if verbose:
        n_kept = len(df)
        cone_area = np.pi * (cone_radius_arcsec / pix_scale_arcsec) ** 2
        rect_area = float(nx * ny)
        expected_fraction = rect_area / cone_area
        print(f"[Gaia] cone returned {n_total} sources (Gmag < "
              f"{magnitude_limit:.2f}); kept {n_kept} inside "
              f"{nx}x{ny} bbox (expected fraction ~{expected_fraction:.2f}).")
        if target_gaia_id not in df["ID"].values:
            print(f"[Gaia] WARNING: target {target_gaia_id} not in returned "
                  "catalog (consider keep_target_regardless=True).")
            
    import shutil as _shutil
    _aud.conf.cache_dir = _saved_astropy_cache
    _shutil.rmtree(_gaia_tmpdir, ignore_errors=True)       

    return df, target_gaia_id, target_gmag   
    
def plot_cutouts_ALT(
    ID, nearby_star_catalog, Sector, cadence, hdu,
    pix_mask, bkg_mask, reference_pixel, ncols, fig, ax,
    cbarpad, default_settings, catalog_source: str = "TIC",):
    """
    Drop-in alternative to ``plot_cutouts`` with a ``catalog_source`` switch.

    When ``catalog_source='gaia'``: queries Gaia DR3 via
    ``collect_nearby_Gaia_params`` (which restricts to the cutout bounding box
    and applies proper-motion correction to the TPF epoch), then draws the
    overlay via ``plot_sources_gaia``. The legacy TIC ΔTmag legend block is
    suppressed in this branch to avoid stacking two inconsistent legends on
    the same axis.

    When ``catalog_source='tic'``: behaves exactly like the original
    ``plot_cutouts``, including the TIC-Tmag legend.

    Parameters
    ----------
    All parameters match ``plot_cutouts`` apart from:
    catalog_source : {'TIC', 'gaia'}
        Which catalog to overlay. Default 'TIC' for backward compatibility.

    Returns
    -------
    gaia_df : pd.DataFrame or None
        The trimmed Gaia DR3 catalog when ``catalog_source='gaia'``; None
        otherwise.
    """
    from astropy.io.fits import HDUList

    get_all_sectors = default_settings.get("get_all_sectors")
    savelcpath = default_settings.get("savelcpath")
    verbose = default_settings.get("verbose")

    # HDU selection (unchanged).
    if type(hdu) is list or (isinstance(hdu, HDUList) and len(hdu) < 3):
        if type(hdu) is list:
            hdu = [h for h in hdu if h is not None]
        hdus = hdu if type(hdu) is list else [hdu]
        bkg_masks = bkg_mask if type(bkg_mask) is list else [bkg_mask]
        pix_masks = pix_mask if type(pix_mask) is list else [pix_mask]
        for i in range(len(hdus)):
            if hdus[i] is not None:
                hdu = hdus[i]
                bkg_mask = bkg_masks[i] if i < len(bkg_masks) else bkg_masks[0]
                pix_mask = pix_masks[i] if i < len(pix_masks) else pix_masks[0]
                try:
                    Sector = hdu[0].header["Sector"]
                except (AttributeError, KeyError, IndexError, TypeError):
                    try:
                        Sector = hdu.header["Sector"]
                    except Exception:
                        pass
                break
    if not isinstance(hdu, HDUList):
        hdu = HDUList([hdu])

    starname = "TIC " + str(ID)

    # Aperture-membership table (still computed for TIC even when plotting Gaia,
    # so the legacy code path remains intact when catalog_source='TIC').
    nearby_star_catalog_in_aperture = get_sources_in_aperture_mask(
        ID, hdu, pix_mask, nearby_star_catalog, verbose=False)
    cdf, cut_cdf = nearby_star_catalog, nearby_star_catalog_in_aperture

    #plot_image_and_mask(hdu, pix_mask, bkg_mask, ax, fig, cbarpad=cbarpad) #OLD
    plot_image_and_mask(hdu, ID, nearby_star_catalog, pix_mask, bkg_mask, 
                        ax, fig, cbarpad=cbarpad)

    format_ax(ax, hdu)

    if Sector is None or type(Sector) is list:
        Sectors = search_sectors_from_filetype_and_path(ID, default_settings)
        if verbose:
            print("plot_cutouts_ALT: Sectors:", Sectors)
        Sector = Sectors[0]
    if verbose:
        print("plot_cutouts_ALT: Sector:", Sector)

    gaia_df = None
    if catalog_source.lower() == "gaia":
        gaia_df, target_gaia_id, target_gmag = collect_nearby_Gaia_params(
            ID=ID, hdu=hdu, verbose=verbose)
        plot_sources_gaia(
            ID, hdu, ax,
            gaia_catalog=gaia_df,
            target_gaia_id=target_gaia_id,
            target_gmag=target_gmag,
            pix_mask=pix_mask,
            reference_pixel=reference_pixel,
            Sector=Sector, cadence=cadence,
            default_settings=default_settings,
            draw_legend=False, # we don't want legend here            
        )
    else:
        plot_sources_TIC(
            ID, hdu, ax,
            tic_catalog=nearby_star_catalog,
            pix_mask=pix_mask,
            reference_pixel=reference_pixel,
            Sector=Sector,
            cadence=cadence,
            default_settings=default_settings,
            draw_legend=False, # we don't want legend here
        )

    plot_orientation(hdu, ax)

    # IMPORTANT: only run the legacy TIC ΔTmag legend block in the TIC branch.
    # In the Gaia branch, plot_sources_gaia already attached its own legend.
    if catalog_source.lower() != "gaia":
        mag = cdf.loc[cdf["ID"] == str(ID)]["Tmag"].item()
        maxmag = np.max(cdf["Tmag"])
        fake_sizes = mag + np.linspace(0, maxmag, 6)
        for f in fake_sizes[::-1]:
            if (f - mag) <= 10:
                size = (0.25 * 128.0 / 2 ** ((1 / 2.5) * (f - mag)))
                ax.scatter(-1, -1, s=size, c="cyan", alpha=0.6, edgecolor=None,
                           zorder=10, label=r"$\Delta Tmag=$ " + str(int(f - mag)))
        handles, labels = ax.get_legend_handles_labels()
        ax.legend(handles[::-1], labels[::-1], ncol=ncols, loc="lower right",
                  fontsize=8, borderpad=0, borderaxespad=0.,
                  handletextpad=0, labelspacing=0, columnspacing=0)

    format_ax(ax,hdu)
    fix_wcs_axis_labels(ax, ra_label="RA", dec_label="DEC", fontsize=10)
    return gaia_df


def plot_image_ALT(ID, nearby_star_catalog, hdu, Sector, cadence,
               ax_placement, fig, fs, ncols, cbarpad,
               default_settings, return_masks=False,draw_legend=True):
    """
    Plot the TESS FFI/TPF median-image cutout with aperture/background masks
    and catalog source overlay (TIC or Gaia DR3).

    This is a drop-in replacement for the deployed ``plot_image``.  The only
    additions are:

    * ``catalog_source`` is read from
      ``default_settings.get('plot_catalog_source', 'TIC')``.
    * When ``catalog_source='gaia'``, ``collect_nearby_Gaia_params`` and
      ``plot_sources_gaia`` are used instead of the TIC overlay path.
    * The return value is extended to
      ``(ax, pix_mask, bkg_mask, gaia_df, target_gaia_id)``
      when ``return_masks=True``, so callers can forward all needed data to
      ``plot_dss_orientation`` without a second catalog query.

    Parameters
    ----------
    (All existing parameters unchanged.)
    return_masks : bool, optional
        If ``True``, returns ``(ax, pix_mask, bkg_mask, gaia_df, target_gaia_id)``.
        If ``False`` (default), returns only ``ax`` for backward compatibility.

    Returns
    -------
    ax : matplotlib.axes.Axes  (always)
    pix_mask : np.ndarray      (only when return_masks=True)
    bkg_mask : np.ndarray      (only when return_masks=True)
    gaia_df : pd.DataFrame or None  (only when return_masks=True)
    target_gaia_id : str or None    (only when return_masks=True)
    """
    from astropy.io.fits import HDUList

    # ── settings ─────────────────────────────────────────────────────────────
    path                 = default_settings.get('path')
    saveReportpath       = default_settings.get('saveReportpath')
    savelcpath           = default_settings.get('savelcpath')
    downloadpath         = default_settings.get('downloadpath')
    get_all_sectors      = default_settings.get('get_all_sectors')
    for_injections       = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    verbose              = default_settings.get('verbose')
    catalog_source       = default_settings.get('plot_catalog_source', 'TIC')

    import os
    import matplotlib.gridspec as gridspec

    if saveReportpath is None:
        Path = generate_injection_path(Sector, default_settings)
        if cadence in ('long', '30 minute', '10 minute'):
            saveReportpath = Path + 'NEMESIS_FFI_TLS_Report/'
        if cadence in ('short', '2 minute', '20 second', 'fast'):
            saveReportpath = Path + 'NEMESIS_TPF_TLS_Report/'

    pix_mask, bkg_mask, images, matched_sectors = get_pix_and_bkg_masks_and_image_fluxes(
        ID, Sector, cadence, default_settings)

    if not isinstance(matched_sectors, (list, tuple, np.ndarray)):
        matched_sectors = [matched_sectors]

    # ── HDU selection (verbatim from deployed plot_image) ─────────────────────
    if type(hdu) is list:
        hdu = [h for h in hdu if h is not None]

        hdus      = hdu
        bkg_masks = bkg_mask if type(bkg_mask) is list else [bkg_mask]
        pix_masks = pix_mask if type(pix_mask) is list else [pix_mask]

        selected = False
        for i in range(len(hdus)):
            if hdus[i] is None:
                continue
            _hdu_i = hdus[i]
            _bkg_i = bkg_masks[i] if i < len(bkg_masks) else bkg_masks[0]
            _pix_i = pix_masks[i] if i < len(pix_masks) else pix_masks[0]
            try:
                _sec_i = int(_hdu_i[0].header['Sector'])
            except (KeyError, IndexError, TypeError):
                try:
                    _sec_i = int(_hdu_i[1].header.get('Sector', Sector))
                except Exception:
                    _sec_i = Sector
            if int(_sec_i) in matched_sectors:
                hdu      = _hdu_i
                bkg_mask = _bkg_i
                pix_mask = _pix_i
                Sector   = _sec_i
                selected = True
                break

        if not selected:
            for i in range(len(hdus)):
                if hdus[i] is not None:
                    hdu      = hdus[i]
                    bkg_mask = bkg_masks[i] if i < len(bkg_masks) else bkg_masks[0]
                    pix_mask = pix_masks[i] if i < len(pix_masks) else pix_masks[0]
                    try:
                        Sector = int(hdu[0].header['Sector'])
                    except Exception:
                        pass
                    break

        if verbose:
            print(f'[plot_image] selected HDU for Sector {Sector}')

    if not isinstance(hdu, HDUList):
        hdu = HDUList([hdu])

    # ── WCS and axis setup (verbatim) ─────────────────────────────────────────
    wcs = check_wcs(hdu)
    ax  = fig.add_subplot(ax_placement, projection=wcs)

    # ── Gaia catalog holder (populated below if catalog_source='gaia') ────────
    gaia_df        = None
    target_gaia_id = None

    try:
        reference_pixel = reference_pixel = get_tess_reference_pixel(hdu[1].header)
        
        
        ax.set_title("TPF Cutout" if cadence in ('short', '2 minute', '20 second', 'fast')
                     else "FFI Cutout", fontsize=fs)

        pm = pix_mask[0] if (pix_mask is not None and np.ndim(pix_mask) == 3) else pix_mask
        bm = bkg_mask[0] if (bkg_mask is not None and np.ndim(bkg_mask) == 3) else bkg_mask
        print(f"[plot_it_all_up] hdu type: {type(hdu)}, is nearby_star_catalog is None: {nearby_star_catalog is None}, for_injections: {default_settings.get('for_injections')}")
        gaia_df, target_gaia_id = _run_cutouts_ALT(
            ID, nearby_star_catalog, Sector, cadence, hdu,
            pm, bm, reference_pixel, ncols, fig, ax,
            cbarpad, default_settings, catalog_source,
            draw_legend,
        )

    except (TypeError, AttributeError, IndexError) as e:
        if verbose:
            print(f"[plot_image] fallback path: {e}")
        try:
            reference_pixel = get_tess_reference_pixel(hdu[1].header)
        except Exception:
            col, row = 5.5, 5.5
            reference_pixel = [col, row]

        pm = pix_mask[0] if (pix_mask is not None and np.ndim(pix_mask) == 3) else pix_mask
        bm = bkg_mask[0] if (bkg_mask is not None and np.ndim(bkg_mask) == 3) else bkg_mask

        if pm is not None and np.ndim(pm) == 2:
            print(f"[plot_it_all_up] hdu type: {type(hdu)}, is nearby_star_catalog is None: {nearby_star_catalog is None}, for_injections: {default_settings.get('for_injections')}")
            gaia_df, target_gaia_id = _run_cutouts_ALT(
                ID, nearby_star_catalog, Sector, cadence, hdu,
                pm, bm, reference_pixel, ncols, fig, ax,
                cbarpad, default_settings, catalog_source,
                draw_legend,
            )

    if return_masks:
        return ax, pix_mask, bkg_mask, gaia_df, target_gaia_id
    else:
        return ax


# =============================================================================
# _run_cutouts_ALT — private helper called by plot_image
# Replaces the inline plot_cutouts_ALT call; returns (gaia_df, target_gaia_id)
# so plot_image can forward them to the caller.
# =============================================================================


def _run_cutouts_ALT(ID, nearby_star_catalog, Sector, cadence, hdu,
                     pix_mask, bkg_mask, reference_pixel, ncols, fig, ax,
                     cbarpad, default_settings, catalog_source, draw_legend):
    """
    Internal helper called by plot_image_ALT.
    Runs the full cutout plot and returns (gaia_df, target_gaia_id).

    TIC path  uses plot_sources_TIC  (tpfplotter style, ΔTmag markers).
    Gaia path uses plot_sources_gaia (tpfplotter style, ΔG markers).
    """
    verbose = default_settings.get("verbose")
    starname = "TIC " + str(ID)

    # Sector resolution
    if Sector is None or type(Sector) is list:
        Sectors = search_sectors_from_filetype_and_path(ID, default_settings)
        if verbose:
            print("plot_cutouts_ALT: Sectors:", Sectors)
        Sector = Sectors[0]
    if verbose:
        print("plot_cutouts_ALT: Sector:", Sector)

    # Image + mask  (7-arg deployed signature)
    plot_image_and_mask(hdu, ID, nearby_star_catalog,
                        pix_mask, bkg_mask, ax, fig, cbarpad=cbarpad)

    # Source overlay
    gaia_df        = None
    target_gaia_id = None

    if catalog_source.lower() == "gaia":
        try:
            gaia_df, target_gaia_id, target_gmag = collect_nearby_Gaia_params(
                ID=ID,
                hdu=hdu,
                verbose=verbose,
                downloadpath=default_settings.get("downloadpath"),
            )
            plot_sources_gaia(
                ID, hdu, ax,
                gaia_catalog=gaia_df,
                target_gaia_id=target_gaia_id,
                target_gmag=target_gmag,
                pix_mask=pix_mask,
                reference_pixel=reference_pixel,
                Sector=Sector,
                cadence=cadence,
                default_settings=default_settings,
                draw_legend=draw_legend,
            )
        except Exception as exc:
            if verbose:
                print(f"[_run_cutouts_ALT] Gaia query/overlay failed → {exc}")
                print("[_run_cutouts_ALT] falling back to TIC overlay")
            # Graceful fallback uses the tpfplotter-style TIC function
            plot_sources_TIC(
                ID, hdu, ax,
                tic_catalog=nearby_star_catalog,
                pix_mask=pix_mask,
                reference_pixel=reference_pixel,
                Sector=Sector,
                cadence=cadence,
                default_settings=default_settings,
                draw_legend=draw_legend,
            )
            gaia_df        = None
            target_gaia_id = None
    else:
        # TIC path: tpfplotter-style TIC overlay
        plot_sources_TIC(
            ID, hdu, ax,
            tic_catalog=nearby_star_catalog,
            pix_mask=pix_mask,
            reference_pixel=reference_pixel,
            Sector=Sector,
            cadence=cadence,
            default_settings=default_settings,
            draw_legend=draw_legend,
        )

    # N/E arrows (both paths)
    plot_orientation(hdu, ax)

    # Axis formatting — exactly once, at the end
    format_ax(ax, hdu)
    #fix_wcs_axis_labels(ax, ra_label="RA", dec_label="DEC", fontsize=10)

    return gaia_df, target_gaia_id


def plot_dss_sources(
    ax,
    hdu=None,              # ADDED: needed for WCS projection fallback
    nearby_star_catalog=None,
    gaia_df=None,
    target_id=None,
    target_gaia_id=None,
    pix_mask=None,
    oversample: int = 21,
    source_color: str = "gold",
    in_aperture_edge_color: str = "deepskyblue",
    target_marker_color: str = "white",
    cone_color: str = "cyan",
    label_dmag_max: float = 5.0,
    fontsize: int = 8,
):
    """
    Overlay catalog sources on the reprojected DSS panel.

    Source positions (in TESS pixel space) are multiplied by ``oversample``
    to get DSS display coordinates, matching the reprojection in
    ``plot_dss_orientation``.

    If the catalog does not carry ``x_pix``/``y_pix`` columns (e.g. the
    standard TIC catalog from ``collect_nearby_TIC_params``), positions are
    projected from ``ra``/``dec`` via ``check_wcs(hdu)``.  ``hdu`` must be
    provided in that case.

    Parameters
    ----------
    ax : matplotlib.axes.Axes
        The DSS panel axes (plain, not WCS-projected).
    hdu : fits.HDUList or None
        NEMESIS HDUList used for WCS projection when ``x_pix``/``y_pix`` are
        absent. Required for TIC catalog without precomputed pixel positions.
    nearby_star_catalog : pd.DataFrame or None
        TIC catalog. Used when ``gaia_df`` is None.
    gaia_df : pd.DataFrame or None
        Gaia DR3 catalog from ``collect_nearby_Gaia_params``. Takes priority
        over ``nearby_star_catalog`` when both are provided.
    target_id : str or int or None
        TIC ID of the target (for TIC path).
    target_gaia_id : str or None
        Gaia source ID of the target (for Gaia path).
    pix_mask : np.ndarray[bool] or None
        Aperture mask for in-aperture highlighting.
    oversample : int
        DSS pixels per TESS pixel. Must match ``plot_dss_orientation``.
        Default 21.
    source_color : str
        Gaia source fill color. Default 'gold'.
    in_aperture_edge_color : str
        Edge-ring color. Default 'deepskyblue'.
    target_marker_color : str
        Target X color. Default 'white'.
    cone_color : str
        TIC source fill color. Default 'cyan'.
    label_dmag_max : float
        Suppress labels fainter than target + this. Default 5.0.
    fontsize : int
        Label font size. Default 8.
    """
    import numpy as np
    from astropy.io.fits import HDUList

    # ── NEW: normalise hdu from list-of-HDULists to single HDUList ────────────
    # In the multi-sector pipeline path, hdu arrives as a plain Python list of
    # HDUList objects. check_wcs() requires a single HDUList or bare HDU.
    # Extract the first non-None element, matching the convention used in
    # plot_cutouts_ALT, plot_image_ALT, and plot_dss_orientation.
    if hdu is not None and type(hdu) is list:
        for _h in hdu:
            if _h is not None:
                hdu = _h
                break
    # If a bare HDU extension slipped through, wrap it.
    if hdu is not None and not isinstance(hdu, HDUList):
        from astropy.io.fits.hdu.base import _BaseHDU
        if isinstance(hdu, _BaseHDU):
            hdu = HDUList([hdu])

    if pix_mask is not None and pix_mask.ndim == 3:
        pix_mask = pix_mask[0]

    use_gaia = (gaia_df is not None
                and {"Gmag"}.issubset(gaia_df.columns))
    use_tic  = (not use_gaia
                and nearby_star_catalog is not None
                and {"Tmag"}.issubset(nearby_star_catalog.columns))

    if not use_gaia and not use_tic:
        return

    def _get_tess_pixels(df, id_col, ra_col, dec_col):
        """
        Return (x_tess, y_tess) arrays in TESS pixel space.
        Uses precomputed columns if available, otherwise projects via WCS.
        """
        if {"x_pix", "y_pix"}.issubset(df.columns):
            return (df["x_pix"].to_numpy(dtype=float),
                    df["y_pix"].to_numpy(dtype=float))
        if hdu is None:
            return None, None
        wcs = check_wcs(hdu)
        ra  = df[ra_col].to_numpy(dtype=float)
        dec = df[dec_col].to_numpy(dtype=float)
        xy  = wcs.all_world2pix(np.vstack([ra, dec]).T, 0)
        return xy[:, 0], xy[:, 1]

    # ── Gaia overlay ──────────────────────────────────────────────────────────
    if use_gaia:
        df = gaia_df.copy().reset_index(drop=True)
        df["ID"] = df["ID"].astype(str)

        x_t, y_t = _get_tess_pixels(df, "ID", "ra", "dec")
        if x_t is None:
            return
        x_dss = x_t * oversample
        y_dss = y_t * oversample

        target_gmag = None
        if target_gaia_id is not None:
            sel = df.loc[df["ID"] == str(target_gaia_id), "Gmag"]
            if len(sel) > 0:
                target_gmag = float(sel.iloc[0])
        if target_gmag is None:
            target_gmag = float(df["Gmag"].min())

        dmag  = df["Gmag"].to_numpy(dtype=float) - target_gmag
        sizes = 128.0 / 2.0 ** dmag

        in_ap = np.zeros(len(df), dtype=bool)
        if pix_mask is not None:
            ny_m, nx_m = pix_mask.shape
            ix = np.round(x_t).astype(int)
            iy = np.round(y_t).astype(int)
            valid = (ix >= 0) & (ix < nx_m) & (iy >= 0) & (iy < ny_m)
            in_ap[valid] = pix_mask[iy[valid], ix[valid]]

        ax.scatter(x_dss, y_dss, s=sizes, c=source_color,
                   alpha=0.7, edgecolors="none", zorder=10)
        if in_ap.any():
            ax.scatter(x_dss[in_ap], y_dss[in_ap], s=sizes[in_ap],
                       facecolors="none", edgecolors=in_aperture_edge_color,
                       linewidths=1.5, zorder=11)

        target_idx = None
        if target_gaia_id is not None:
            sel = np.where(df["ID"].values == str(target_gaia_id))[0]
            if len(sel) > 0:
                target_idx = int(sel[0])
                ax.scatter(x_dss[target_idx], y_dss[target_idx],
                           marker="x", c=target_marker_color,
                           s=12**2, zorder=12, lw=2)

        for i in range(len(df)):
            if i == target_idx or dmag[i] > label_dmag_max:
                continue
            lbl = f"{int(round(dmag[i])):+d}"
            off = 0.15 * oversample
            ax.text(x_dss[i] + off, y_dss[i] + off, lbl,
                    color="black", weight="bold", fontsize=fontsize, zorder=100)
            ax.text(x_dss[i] + off, y_dss[i] + off, lbl,
                    color="white", fontsize=fontsize, zorder=99)

    # ── TIC overlay ───────────────────────────────────────────────────────────
    elif use_tic:
        df = nearby_star_catalog.copy().reset_index(drop=True)
        df["ID"] = df["ID"].astype(str)

        x_t, y_t = _get_tess_pixels(df, "ID", "ra", "dec")
        if x_t is None:
            return
        x_dss = x_t * oversample
        y_dss = y_t * oversample

        target_tmag = None
        if target_id is not None:
            sel = df.loc[df["ID"] == str(target_id), "Tmag"]
            if len(sel) > 0:
                target_tmag = float(sel.iloc[0])
        if target_tmag is None:
            target_tmag = float(df["Tmag"].min())

        dtmag = df["Tmag"].to_numpy(dtype=float) - target_tmag
        sizes = 128.0 / 2.0 ** (dtmag / 2.5)

        in_ap = np.zeros(len(df), dtype=bool)
        if pix_mask is not None:
            ny_m, nx_m = pix_mask.shape
            ix = np.round(x_t).astype(int)
            iy = np.round(y_t).astype(int)
            valid = (ix >= 0) & (ix < nx_m) & (iy >= 0) & (iy < ny_m)
            in_ap[valid] = pix_mask[iy[valid], ix[valid]]

        ax.scatter(x_dss, y_dss, s=sizes, c=cone_color,
                   alpha=0.7, edgecolors="none", zorder=10)
        if in_ap.any():
            ax.scatter(x_dss[in_ap], y_dss[in_ap], s=sizes[in_ap],
                       facecolors="none", edgecolors=in_aperture_edge_color,
                       linewidths=1.5, zorder=11)

        target_idx = None
        if target_id is not None:
            sel = np.where(df["ID"].values == str(target_id))[0]
            if len(sel) > 0:
                target_idx = int(sel[0])
                ax.scatter(x_dss[target_idx], y_dss[target_idx],
                           marker="x", c=target_marker_color,
                           s=12**2, zorder=12, lw=2)

        for i in range(len(df)):
            if i == target_idx or dtmag[i] > label_dmag_max:
                continue
            lbl = f"{int(round(dtmag[i])):+d}"
            off = 0.15 * oversample
            ax.text(x_dss[i] + off, y_dss[i] + off, lbl,
                    color="black", weight="bold", fontsize=fontsize, zorder=100)
            ax.text(x_dss[i] + off, y_dss[i] + off, lbl,
                    color="white", fontsize=fontsize, zorder=99)
