#
def Applying_Mdump_removal(ID,Sector,hdu,SAP_LC,flux,combined_mask,
                          default_settings):
    """
    Apply momentum dump and sector jitter masking to a raw SAP light curve.

    Wraps ``momentumdump_removal`` to produce boolean cadence masks,
    applies them to the flux array and SAP DataFrame, renormalizes the
    clipped SAP flux, and saves the systematics-removed LC to disk.

    Masking logic
    -------------
    ``keep_mdumps = True``
        No cadences are removed.  ``mask_mdump`` is set to ``[NaN]`` and
        all timestamps are retained.  Sector observation boundaries
        ``(t_0, t_1)`` are still looked up from
        ``TESS_Sector_observation_check``.

    ``keep_mdumps = False``
        ``momentumdump_removal`` is called to generate a boolean keep mask.
        Cadences within ``before_after_in_minutes`` of each momentum dump
        event, as well as sector-specific jitter intervals
        (when ``do_sector_jitter_mask=True``), are excluded.
        The clipped SAP flux is renormalized to a median of 1 after masking.

    Parameters
    ----------
    ID : int
        TIC identifier; used to construct output filenames.
    Sector : int
        TESS sector number; used to look up sector observation boundaries
        and jitter intervals.
    hdu : fits.HDUList
        Raw FITS data; used to extract momentum dump timestamps from the
        QUALITY column and to read the Camera header key for camera-specific
        jitter intervals.
    SAP_LC : pd.DataFrame
        Full-length SAP light curve as returned by ``SAP``.  Columns used:
        ``Time``, ``SAP Flux``, ``SAP Error``,
        ``Background Flux``, ``Background Error``.
    flux : np.ndarray, shape (T, ny, nx)
        Quality-masked pixel image cube; momentum dump frames are removed
        in-place so the returned cube is aligned with the clipped LC.
    combined_mask : np.ndarray[bool], shape (T,)
        Boolean good-cadence mask from ``SAP`` (``quality_flag == 0``).
        Used as the initial mask before momentum dump removal.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys:
        ``savelcpath``, ``before_after_in_minutes``, ``keep_mdumps``,
        ``keep_baddata``, ``do_sector_jitter_mask``, ``verbose``.

    Returns
    -------
    mask_mdump : np.ndarray[bool] or list
        Boolean keep mask aligned to ``SAP_LC`` timestamps
        (``True`` = cadence retained).  Returns ``[NaN]`` when
        ``keep_mdumps=True``.
    t_0 : float
        BTJD timestamp of the start of sector observations (orbit 1 start).
    t_1 : float
        BTJD timestamp of the end of sector observations (orbit 2 end).
    flux : np.ndarray, shape (T', ny, nx)
        Pixel image cube with momentum dump frames removed (``T' ≤ T``).
    RAWLC_df : pd.DataFrame
        Full-length SAP LC (identical to input ``SAP_LC``; retained for
        downstream plotting).
    clippedRAWLC_df : pd.DataFrame
        Momentum-dump-masked and renormalized SAP LC.  Columns:
        ``Time``, ``SAP Flux``, ``SAP Error``,
        ``Background Flux``, ``Background Error``,
        ``Centroid X Positions``, ``Centroid Y Positions``.

    Notes
    -----
    The systematics-removed LC is saved to:
    ``{savelcpath}/TIC_{ID}_Sector_{NNNN}_RAW_LC_systematics_removed.csv``
    """    
    # get function settings
    before_after_in_minutes = default_settings.get('before_after_in_minutes')
    savelcpath = default_settings.get('savelcpath')
    keep_mdumps = default_settings.get('keep_mdumps')
    keep_baddata = default_settings.get('keep_baddata')
    verbose = default_settings.get('verbose')
    get_all_sectors = default_settings.get('get_all_sectors')
    #
    do_mdump_removal      = default_settings.get('do_mdump_removal')
    do_sector_jitter_mask = default_settings.get('do_sector_jitter_mask')  
    
    # Step 0: define string tag for sector usage (single or multi)    
    if isinstance(Sector, int):
        sector_tag = f"Sector_{Sector:04d}"
    else:
        sector_tag = "Multi_Sector"    
    #
    import pandas as pd
    ###
    ###
    ### read in data from dataframe
    rawtime   = SAP_LC['Time'].to_numpy(dtype=np.float64)
    sap_flux  = SAP_LC['SAP Flux'].to_numpy(dtype=np.float64)
    sap_error = SAP_LC['SAP Error'].to_numpy(dtype=np.float64)
    bkg_flux  = SAP_LC['Background Flux'].to_numpy(dtype=np.float64)
    bkg_error  = SAP_LC['Background Error'].to_numpy(dtype=np.float64)
    cadence_index = SAP_LC['CADENCE_INDEX'].to_numpy(dtype=int)
    quality_flag  = SAP_LC['QUALITY_FLAG'].to_numpy(dtype=int)
    ###
    if keep_mdumps==True:
        orbit1_start,orbit1_stop, orbit2_start,orbit2_stop = TESS_Sector_observation_check(SectorNum=Sector)
        t_0, t_1 = orbit1_start,orbit2_stop
        
        mask_mdump=[np.nan]
        time=rawtime
        sap_flux=sap_flux
        sap_error=sap_error
        bkg_flux=bkg_flux
        bkg_error=bkg_error        
        clippedRAWLC_df = pd.DataFrame({"CADENCE_INDEX": cadence_index, "Time": time,
                                        "SAP Flux": sap_flux, "SAP Error": sap_error,
                                        "Background Flux": bkg_flux, "Background Error": bkg_error,
                                        "QUALITY_FLAG": quality_flag})
        clippedRAWLC_df.to_csv(savelcpath+"TIC_"+str(ID)+f"_{sector_tag}_RAW_LC_systematics_removed.csv",index=False)
    ###
    ###
    if keep_mdumps==False:
        ### making mask for momentum dumps and bad regions of data
        mask_mdump, t_0, t_1 = momentumdump_removal(
            Sector, before_after_in_minutes, rawtime,
            hdu,combined_mask, keep_baddata, verbose=verbose,
            apply_sector_jitter_mask=do_sector_jitter_mask,   # NEW
        )
        ###
        ###
        ### Applying mask and then saving masked data
        time=rawtime[mask_mdump]
        sap_flux=sap_flux[mask_mdump]
        sap_error=sap_error[mask_mdump]
        bkg_flux=bkg_flux[mask_mdump]
        bkg_error=bkg_error[mask_mdump]
        flux=flux[mask_mdump] # removing frames with momentumdumps
        #
        # renormalize SAP after clipping
        sap_flux = sap_flux / np.nanmedian(sap_flux)
        sap_error = sap_error / np.nanmedian(sap_flux)
        #
        ###
        if verbose==True:
            print('clipped len check:', len(time),len(sap_flux),len(sap_error))
        clippedRAWLC_df = pd.DataFrame({ "CADENCE_INDEX": cadence_index[mask_mdump], "Time": time,
                                        "SAP Flux": sap_flux, "SAP Error": sap_error,
                                        "Background Flux": bkg_flux, "Background Error": bkg_error,
                                        "QUALITY_FLAG": quality_flag[mask_mdump] })
        ###
        clippedRAWLC_df.to_csv(savelcpath+"TIC_"+str(ID)+f"_{sector_tag}_RAW_LC_systematics_removed.csv",index=False)
        ###
    ###
    ###
    return mask_mdump, t_0, t_1, flux, SAP_LC, clippedRAWLC_df
#
#
# helper functions for smoothing and outlier removal based on stellar parameters
#
#
def calculate_semi_major_axis(Period, M_star ,R_star): #will replace SMA_AU_from_Period_to_stellar above
    """
    Calculate the semi-major axis using Kepler's third law.
    
    Parameters:
    ----------
    period : astropy.Quantity
        Orbital period of the planet (in days).
    M_star : astropy.Quantity, optional
        Stellar mass (default is solar mass).
    
    Returns:
    -------
    semi_major_axis : astropy.Quantity
        Semi-major axis in units of AU.
    """
    Period = Period.to(u.second)  # Convert period to seconds
    M_star = M_star.to(u.kg)  # Convert stellar mass to kg
    R_star = R_star.to(u.m)  # Convert stellar mass to kg
    
    from astropy import constants as const
    G = const.G
    
    a_cubed = (G * M_star * Period**2 / (4 * np.pi**2)).to(u.m**3)
    semi_major_axis = a_cubed**(1/3)
    
    scaled_SMA = (semi_major_axis / R_star).decompose() #now unitless 
    SMA_cm = semi_major_axis.to(u.cm)
    return scaled_SMA, SMA_cm.value

def T14(P, R_star, M_star, R_planet, b=0, i=90): #will replace Tdur above
    """
    Estimate the total transit duration (T14) for a planet using Kepler's third law and transit geometry.

    Parameters:
    ----------
    P : float
        Orbital period of the planet (in days).
    R_star : float
        Radius of the star (in solar radii).
    M_star : float
        Mass of the star (in solar masses).
    R_planet : float
        Radius of the planet (in Earth radii).
    b : float, optional
        Impact parameter (default is 0 for central transit).
    i : astropy.Quantity, optional
        Orbital inclination (default is 90 degrees for edge-on orbit).
    
    Returns:
    -------
    transit_duration : astropy.Quantity
        The total transit duration (T14) in days.
    """
    import astropy.units as u
    # add units to inputs
    i=i*u.deg
    P, R_star, M_star, R_planet = P*u.day, R_star*u.R_sun, M_star*u.M_sun, R_planet*u.R_earth
    
    # Convert inclination to radians
    i = i.to(u.radian).value  
    
    # Semi-major axis in AU
    scaled_SMA, SMA_cm = calculate_semi_major_axis(Period=P,M_star=M_star,R_star=R_star)
    a = (SMA_cm*u.cm).to(u.AU)
    
    # Convert units to meters
    R_star = R_star.to(u.m)
    R_planet = R_planet.to(u.m)
    
    k = (R_planet / R_star).decompose().value  # Planet-to-star radius ratio
    
    # Calculate the geometric part of the transit duration (dimensionless)
    piece_A = (P.to(u.second) / np.pi).decompose()  # This will give us a time quantity
    piece_B1 = (R_star / a.to(u.m)).decompose().value  # Dimensionless
    piece_B2 = np.sqrt((1 + k)**2 - b**2)  # Dimensionless
    piece_B3 = 1 / np.sin(i)  # Dimensionless

    # Combine the parts for the full duration calculation
    arcsin_argument = piece_B1 * piece_B2 * piece_B3
    angle_radians = np.arcsin(arcsin_argument)  # Result in radians

    # Multiply by the time factor to get the total transit duration
    T14_seconds = (piece_A * angle_radians)  # Now this is in seconds

    return T14_seconds.to(u.day).value
#
def T23(P, R_star, M_star, R_planet, b=0, i=90):
    """
    Estimate the transit duration between the second and third contact points (T23).

    Parameters:
    ----------
    P : float
        Orbital period of the planet (in days).
    R_star : float
        Radius of the star (in solar radii).
    M_star : float
        Mass of the star (in solar masses).
    R_planet : float
        Radius of the planet (in Earth radii).
    b : float, optional
        Impact parameter (default is 0 for central transit).
    i : astropy.Quantity, optional
        Orbital inclination (default is 90 degrees for edge-on orbit).
    
    Returns:
    -------
    transit_duration : astropy.Quantity
        The total transit duration (T23) in days.
    """
    import astropy.units as u
    # add units to inputs
    i=i*u.deg
    P, R_star, M_star, R_planet = P*u.day, R_star*u.R_sun, M_star*u.M_sun, R_planet*u.R_earth
    
    # Convert inclination to radians
    i = i.to(u.radian).value  
    
    # Semi-major axis in AU
    scaled_SMA, SMA_cm = calculate_semi_major_axis(Period=P,M_star=M_star,R_star=R_star)
    a = (SMA_cm*u.cm).to(u.AU)
    
    # Convert units to meters
    R_star = R_star.to(u.m)
    R_planet = R_planet.to(u.m)
    
    k = (R_planet / R_star).decompose().value  # Planet-to-star radius ratio
    
    # Calculate the geometric part of the transit duration (dimensionless)
    piece_A = (P.to(u.second) / np.pi).decompose()  # This will give us a time quantity
    piece_B1 = (R_star / a.to(u.m)).decompose().value  # Dimensionless
    piece_B2 = np.sqrt((1 - k)**2 - b**2)  # Dimensionless
    piece_B3 = 1 / np.sin(i)  # Dimensionless

    # Combine the parts for the full duration calculation
    arcsin_argument = piece_B1 * piece_B2 * piece_B3
    angle_radians = np.arcsin(arcsin_argument)  # Result in radians

    # Multiply by the time factor to get the full transit duration
    T23_seconds = (piece_A * angle_radians)  # Now this is in seconds

    return T23_seconds.to(u.day).value
#
#
def convert_window_size_in_days_to_points(window_size_in_days,time):
    """
    This function converts a window size into a 
    window size in number of data points, based on the cadence of
    timestamps in input time array.
    Input Parameters
    ----------
    window_size_in_days : float
        Input window size in units of days 
    time : array 
        An array of timestamps from TESS observations.
    Returns
    -------
        * Npts : Number of data points corresponding
        to input window size.
    """      
    cad = np.nanmedian(np.diff(time[np.isfinite(time)]))
    def round_up_to_odd(f):
        return int(np.ceil(f) // 2 * 2 + 1)
    Npts = round_up_to_odd(int((window_size_in_days)/cad))
    return Npts
