#
#
def Smoother( ID: int, nearby_star_catalog, Sector, input_LC,
    default_settings: dict, break_tolerance_in_days: Optional[float] = None,
    # ── mode control ──────────────────────────────────────────────────────────
    mode: str = "uniform",          # "uniform" | "ls"
    # ── shared ────────────────────────────────────────────────────────────────
    transit_dur_factor: float = 3.0,
    # ── LS-mode only ──────────────────────────────────────────────────────────
    rot_divisor: float = 5.0, min_prot_days: float = 0.5,
    # ── robustness controls (fix) ─────────────────────────────────────────────
    min_finite_for_smoothing: int = 15,
):
    """
    Smooth the PLD-corrected light curve with a biweight running window.

    Estimates an appropriate smoothing window from stellar parameters
    (and optionally a Lomb-Scargle rotation period estimate), then runs
    ``wotan.flatten`` with ``method='biweight'`` to produce a detrended LC
    and a fitted trend.

    Two modes are available via the ``mode`` parameter (or via
    ``default_settings['smoother_mode']``; the ``mode`` kwarg takes
    precedence).

    Mode: ``"uniform"`` (default)
    ------------------------------
    Window derived purely from stellar parameters -- guarantees the same
    window across all sectors for a given star, making multi-sector
    concatenated LCs internally consistent:

        ``window = transit_dur_factor * T14(P = T_span/2, R_*, M_*, R_p=1 RE)``

    Mode: ``"ls"``
    ---------------
    Window informed by a Lomb-Scargle rotation-period estimate on the
    SAP flux:

        ``w_rot  = P_rot / rot_divisor``
        ``window = max(transit_floor, w_rot)``

    Falls back to the uniform floor if LS fails or peak FAP > 0.01.

    Robustness (fix)
    ----------------
    Degenerate light curves (e.g. ``cdpp=inf`` targets whose PLD flux is
    all-NaN, contains inf, or has zero scatter) previously reached the
    compiled smoothers and could corrupt the process heap, aborting with
    glibc messages such as ``free(): invalid pointer`` or
    ``corrupted size vs. prev_size``. This version:
      * validates the input flux and skips smoothing on degenerate input,
      * sanitizes non-finite values (inf -> NaN) before the biweight fit,
      * only ever calls the median-filter fallback on NaN-interpolated flux
        with a validated ODD integer window bounded by the array length.
    On any unsalvageable case it returns an empty ``Det_LC`` and an empty
    ``nanmask`` (never ``None``), which the caller already handles as a
    failed target.

    Parameters
    ----------
    ID : int
        TIC identifier; used to look up stellar parameters.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``.
    Sector : int, list, or None
        Sector(s) being processed; used only in verbose output.
    input_LC : pd.DataFrame
        PLD-corrected light curve from ``PLD_model``.  Required columns:
        ``'Time'``, ``'Flux'``, ``'Error'``, ``'Model'``,
        ``'SAP Flux'``, ``'SAP Error'``,
        ``'Background Flux'``, ``'Background Error'``,
        ``'Centroid X Positions'``, ``'Centroid Y Positions'``.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys:
        ``savelcpath``, ``verbose``,
        ``window_size_in_days`` (explicit override; skips all estimation),
        ``smoother_mode`` (overridden by the ``mode`` kwarg).
    break_tolerance_in_days : float or None, optional
        Reserved for ``wotan.flatten`` gap-handling; not currently passed
        through.  Default is ``None``.
    mode : str, optional
        ``"uniform"`` or ``"ls"``.  Default is ``"uniform"``.
    transit_dur_factor : float, optional
        Multiplier on T14 for the transit-preservation window floor.
        Default is ``3.0``.
    rot_divisor : float, optional
        Divisor applied to P_rot for the LS-mode window. Default ``5.0``.
    min_prot_days : float, optional
        LS peaks shorter than this are discarded as aliases. Default ``0.5``.
    min_finite_for_smoothing : int, optional
        Minimum number of finite flux samples required to attempt
        smoothing. Below this (or if robust scatter is zero) the target is
        treated as a failed smoothing. Default ``15``.

    Returns
    -------
    Det_LC : pd.DataFrame
        Detrended light curve (empty, with correct columns, on failure).
    nanmask : np.ndarray of int
        Indices where the detrended flux is finite (empty on failure).

    Examples
    --------
    >>> Det_LC, nm = Smoother(ID, cat, Sector, input_LC2, default_settings)
    >>> Det_LC, nm = Smoother(ID, cat, Sector, input_LC2, default_settings,
    ...                       mode="ls")
    """
    from wotan import flatten
    import pandas as pd

    savelcpath  = default_settings.get('savelcpath')
    verbose     = default_settings.get('verbose')
    user_window = default_settings.get('window_size_in_days')   # explicit override

    # resolve active mode (kwarg beats default_settings key)
    active_mode = default_settings.get('smoother_mode', 'uniform')
    if mode != 'uniform':          # caller passed a non-default kwarg
        active_mode = mode

    # ── unpack input LC arrays ────────────────────────────────────────────────
    time       = input_LC['Time'].to_numpy(dtype=np.float64)
    flux_raw   = input_LC['Flux'].to_numpy(dtype=np.float64)
    flux_error = input_LC['Error'].to_numpy(dtype=np.float64)
    flux_model = input_LC['Model'].to_numpy(dtype=np.float64)
    centx      = input_LC['Centroid X Positions'].to_numpy(dtype=np.float64)
    centy      = input_LC['Centroid Y Positions'].to_numpy(dtype=np.float64)
    sap_flux   = input_LC['SAP Flux'].to_numpy(dtype=np.float64)
    sap_error  = input_LC['SAP Error'].to_numpy(dtype=np.float64)
    bkg_flux   = input_LC['Background Flux'].to_numpy(dtype=np.float64)
    bkg_error  = input_LC['Background Error'].to_numpy(dtype=np.float64)
    #
    cadence_index = (
        input_LC['CADENCE_INDEX'].to_numpy(dtype=int)
        if 'CADENCE_INDEX' in input_LC.columns
        else np.arange(len(time), dtype=int)
    )
    #
    quality_flag = (
        input_LC['QUALITY_FLAG'].to_numpy(dtype=int)
        if 'QUALITY_FLAG' in input_LC.columns
        else np.zeros(len(time), dtype=int)
    )

    # ── clean, empty return used for any unsalvageable case ───────────────────
    # Preserves the (Det_LC, nanmask) contract; the caller's
    # "too few data points masked" branch handles this as a failed target.
    def _failed_return():
        empty_i = np.array([], dtype=int)
        empty_f = np.array([], dtype=np.float64)
        Det_LC_empty = pd.DataFrame({
            'CADENCE_INDEX':        empty_i,
            'Time':                 empty_f,
            'SAP Flux':             empty_f,
            'SAP Error':            empty_f,
            'Background Flux':      empty_f,
            'Background Error':     empty_f,
            'PLD Flux':             empty_f,
            'PLD Error':            empty_f,
            'PLD Model':            empty_f,
            'Detrended Flux':       empty_f,
            'Detrended Error':      empty_f,
            'Fitted Trend':         empty_f,
            'Centroid X Positions': empty_f,
            'Centroid Y Positions': empty_f,
            'QUALITY_FLAG':         empty_i,
        })
        return Det_LC_empty, empty_i

    # ── sanitize + validate input flux BEFORE any compiled smoothing ──────────
    # inf -> NaN so the fit routines never receive non-finite-but-not-NaN values.
    flux_for_fit = np.where(np.isfinite(flux_raw), flux_raw, np.nan)
    finite_mask  = np.isfinite(flux_for_fit)
    n_finite     = int(finite_mask.sum())
    if n_finite > 0:
        med = np.nanmedian(flux_for_fit)
        mad = np.nanmedian(np.abs(flux_for_fit - med))
    else:
        mad = np.nan

    if (n_finite < int(min_finite_for_smoothing)) or (not np.isfinite(mad)) or (mad <= 0.0):
        if verbose:
            print(f'[Smoother] degenerate PLD flux for TIC {ID} '
                  f'(finite={n_finite}, MAD={mad}); skipping smoothing. '
                  f'Target will be treated as a failed light curve downstream.')
        return _failed_return()

    # ── stellar parameters (needed by both modes for the floor) ───────────────
    star   = nearby_star_catalog.loc[
        nearby_star_catalog['ID'] == str(ID)
    ].reset_index(drop=True)
    star   = get_qld(star, verbose)
    R_star = star['rad'].item()
    M_star = star['mass'].item()

    lc_dur   = float(np.nanmax(time) - np.nanmin(time))
    max_P    = lc_dur / 2.0
    cad_days = float(np.nanmedian(np.diff(time)))

    # transit-preservation floor (shared by both modes)
    floor = transit_dur_factor * T14(
        P=max_P, R_star=R_star, M_star=M_star, R_planet=1.0)
    floor = max(floor, 6.0 * cad_days)

    # ── determine smoothing window ────────────────────────────────────────────
    if user_window is not None:
        window_size_in_days = user_window
        if verbose:
            print(f'[Smoother] user-supplied window={window_size_in_days:.3f} d '
                  f'(mode ignored)')

    elif active_mode == 'uniform':
        window_size_in_days = floor
        if verbose:
            print(f'[Smoother] uniform mode: '
                  f'transit-floor window = {window_size_in_days:.3f} d '
                  f'(R*={R_star:.3f}, M*={M_star:.3f})')

    else:
        # ── LS MODE ───────────────────────────────────────────────────────────
        p_rot_est = None
        min_p_ls  = max(min_prot_days, 3.0 * cad_days)
        max_p_ls  = lc_dur / 1.5

        if max_p_ls > min_p_ls and np.sum(np.isfinite(sap_flux)) >= 50:
            try:
                _, power, p_peak, _, peak_fap = LS(
                    time[np.isfinite(sap_flux)],
                    (sap_flux / np.nanmedian(sap_flux))[np.isfinite(sap_flux)],
                    min_period=min_p_ls,
                    max_period=max_p_ls,
                    nterms=1,
                )
                if peak_fap < 0.01:
                    p_rot_est = float(p_peak)
            except Exception as exc:
                if verbose:
                    print(f'[Smoother] LS failed: {exc}')

        if p_rot_est is not None:
            w_rot = p_rot_est / rot_divisor
            window_size_in_days = max(floor, w_rot)
            if verbose:
                if w_rot < floor:
                    print(f'[Smoother] ls mode: P_rot={p_rot_est:.3f} d -> '
                          f'w_rot={w_rot:.3f} d < floor={floor:.3f} d '
                          f'(fast rotator; floor used)')
                else:
                    print(f'[Smoother] ls mode: P_rot={p_rot_est:.3f} d -> '
                          f'window={window_size_in_days:.3f} d '
                          f'(floor={floor:.3f} d)')
        else:
            window_size_in_days = floor
            if verbose:
                print(f'[Smoother] ls mode: LS estimate unavailable; '
                      f'falling back to uniform floor={floor:.3f} d')

    # ── biweight flattening (on inf-sanitized flux) ───────────────────────────
    flatten_lc, trend_lc = flatten(
        time, flux_for_fit,
        window_length=window_size_in_days,
        return_trend=True,
        method='biweight',
        robust=True,
    )

    nanmask = np.where(np.isfinite(flatten_lc))[0]

    # ── SAFE medfilt fallback if biweight produced all NaNs ───────────────────
    # The compiled median filter must never see NaN/inf, and its window must be
    # a valid odd integer < len(array). Otherwise it can corrupt the heap.
    if len(nanmask) < 1:
        if verbose:
            print('[Smoother] biweight returned all NaN; attempting safe medfilt fallback')

        # coerce window to a valid odd integer, bounded by the series length
        try:
            win_pts = int(round(float(
                convert_window_size_in_days_to_points(window_size_in_days, time))))
        except Exception:
            win_pts = 0
        if win_pts < 3:
            win_pts = 3
        if win_pts % 2 == 0:
            win_pts += 1
        n_all   = len(time)
        max_odd = n_all if (n_all % 2 == 1) else (n_all - 1)
        if win_pts > max_odd:
            win_pts = max_odd

        # need enough finite points and a usable odd window to proceed
        if (n_finite < 3) or (win_pts < 3):
            if verbose:
                print(f'[Smoother] medfilt fallback not viable '
                      f'(finite={n_finite}, win_pts={win_pts}); failing cleanly.')
            return _failed_return()

        # interpolate over NaNs so the compiled filter sees only finite values
        flux_interp = flux_for_fit.copy()
        if (~finite_mask).any():
            flux_interp[~finite_mask] = np.interp(
                time[~finite_mask], time[finite_mask], flux_for_fit[finite_mask])

        flatten_lc, trend_lc = flatten(
            time, flux_interp,
            window_length=win_pts,
            return_trend=True,
            method='medfilt',
            robust=True,
        )
        nanmask = np.where(np.isfinite(flatten_lc))[0]

        if len(nanmask) < 1:
            if verbose:
                print('[Smoother] medfilt fallback also produced all NaN; failing cleanly.')
            return _failed_return()

    # ── apply nanmask ─────────────────────────────────────────────────────────
    def _m(a):
        return a[nanmask]

    T          = _m(time)
    F          = _m(flatten_lc)
    FE         = _m(flux_error)
    trend_lc   = _m(trend_lc)
    flux_model = _m(flux_model)
    centx      = _m(centx)
    centy      = _m(centy)
    sap_flux   = _m(sap_flux)
    sap_error  = _m(sap_error)
    bkg_flux   = _m(bkg_flux)
    bkg_error  = _m(bkg_error)
    flux_raw_m = _m(flux_raw)

    cadence_index = _m(cadence_index)
    quality_flag  = _m(quality_flag)

    # ── guard against non-positive trend ──────────────────────────────────────
    TREND_FLOOR = 1e-6
    bad_trend   = ~np.isfinite(trend_lc) | (trend_lc <= TREND_FLOOR)

    safe_trend  = np.where(bad_trend, np.nan, trend_lc)
    det_error   = FE / safe_trend
    det_error   = np.where(bad_trend, np.nan, det_error)
    F           = np.where(bad_trend, np.nan, F)

    if verbose and bad_trend.any():
        print(f'[Smoother] non-positive/NaN trend at {int(bad_trend.sum())} '
              f'cadence(s); detrended flux/error set to NaN '
              f'(dropped by downstream finite filters)')

    Det_LC = pd.DataFrame({
        'CADENCE_INDEX':         cadence_index,
        'Time':                  T,
        'SAP Flux':              sap_flux,
        'SAP Error':             sap_error,
        'Background Flux':       bkg_flux,
        'Background Error':      bkg_error,
        'PLD Flux':              flux_raw_m,
        'PLD Error':             FE,
        'PLD Model':             flux_model,
        'Detrended Flux':        F,
        'Detrended Error':       det_error,
        'Fitted Trend':          trend_lc,
        'Centroid X Positions':  centx,
        'Centroid Y Positions':  centy,
        'QUALITY_FLAG':          quality_flag,
    })
    return Det_LC, nanmask
#
#
#
def quick_outlier_removal(input_LC, flux_type, Nsigma=5, 
                          window_size_in_days=1, method='local'):
    """
    Fast sliding-window outlier mask for a single flux column.

    First detrends the input flux with a biweight filter (``wotan.flatten``),
    then identifies below-median outliers using MAD-scaled sigma clipping in
    fixed-width time windows.  Only downward outliers are flagged; upward
    excursions (e.g. flares) are left intact.

    This function is used inside ``PLD_model`` as a pass-2 outlier gate:
    flagged cadences are assigned zero inverse variance rather than being
    dropped, so they remain in the output array but do not influence the
    PLD solve.

    Parameters
    ----------
    input_LC : pd.DataFrame
        Light curve containing at minimum the columns
        ``'Time'``, ``'{flux_type} Flux'``, ``'{flux_type} Error'``.
    flux_type : str
        Column prefix for the flux to clip.  E.g. ``'SAP'`` → reads
        ``'SAP Flux'`` and ``'SAP Error'``.
    Nsigma : float, optional
        Number of MAD-scaled sigma below the window median to use as the
        lower rejection threshold.  Default is ``5``.
    window_size_in_days : float, optional
        Width of each sliding window in days.  Default is ``1``.
    method : {'local', 'global'}, optional
        ``'local'``  — MAD and median computed within each window.
        ``'global'`` — MAD and median computed over the full LC
                       (more aggressive for stable baselines).
        Default is ``'local'``.

    Returns
    -------
    mask : np.ndarray[bool], shape (T,)
        Boolean keep mask: ``True`` = cadence is not a downward outlier,
        ``False`` = flagged as below-threshold.

    Examples
    --------
    >>> mask = quick_outlier_removal(lc, 'SAP', Nsigma=10,
    ...                               window_size_in_days=1, method='global')
    >>> clean_flux = lc['SAP Flux'].to_numpy()[mask]
    """
    import numpy as np
    from astropy.stats.funcs import median_absolute_deviation as MAD

    # Extract time and flux data
    time = input_LC['Time'].to_numpy(dtype=np.float64)
    rawflux =  input_LC[flux_type+' Flux'].to_numpy(dtype=np.float64)
    error=  input_LC[flux_type+' Error'].to_numpy(dtype=np.float64)
    
    
    # DETREND FIRST
    from wotan import flatten 
    flux, trend_lc = flatten(time, rawflux, window_length=window_size_in_days, \
                                   return_trend=True, method='biweight',robust=True)
    
    # Compute window size and initialize good/bad indices
    cad = np.nanmedian(np.diff(time[np.isfinite(time)]))
    Npts = int(np.round((window_size_in_days / cad) + 1, 1))
    size = len(time)
    window_size = min(Npts, size)
    bins = int(size / Npts) + 2

    # Initialize mask as all True (keep all points initially)
    mask = np.ones_like(time, dtype=bool)

    # Iterate over bins and identify outliers
    for N in range(1, bins):
        start_idx = window_size * (N - 1)
        end_idx = min(N * window_size, size) 
        
        time_in_window = time[window_size * (N - 1):N * window_size]
        flux_in_window = flux[window_size * (N - 1):N * window_size]

        # Determine flux thresholds based on MAD
        if method == "local":
            flux_threshold_lo = np.nanmedian(flux_in_window) - Nsigma * MAD(flux_in_window)
            flux_threshold_hi = np.nanmedian(flux_in_window) + Nsigma * MAD(flux_in_window)
        if method == "global":            
            flux_threshold_lo = np.nanmedian(flux) - Nsigma * MAD(flux)
            flux_threshold_hi = np.nanmedian(flux) + Nsigma * MAD(flux)
        # Identify indices of outliers in current window
        ind_lo = np.where(flux_in_window < flux_threshold_lo)[0]
        ind_hi = np.where(flux_in_window > flux_threshold_hi)[0]

        # Identify single and consecutive outliers
        single_lo = singleoutliers(ind_lo)
        single_hi = singleoutliers(ind_hi)
        consec_lo = consecutive(ind_lo)
#         consec_hi = consecutive(ind_hi)
        
        
        # Ensure single_lo, single_hi, consec_lo, and consec_hi contain integer indices
        single_lo = single_lo.astype(int)
        single_hi = single_hi.astype(int)
        consec_lo = consec_lo.astype(int)
#         consec_hi = consec_hi.astype(int)

        # Combine all outliers (single and consecutive) for the current window
        all_outliers_lo = np.concatenate((single_lo, consec_lo))
#         all_outliers_hi = single_hi#np.concatenate((single_hi, consec_hi))

        # Get the global indices for the outliers
        global_indices_lo = np.arange(start_idx, end_idx)[all_outliers_lo]
#         global_indices_hi = np.arange(start_idx, end_idx)[all_outliers_hi]

        # Update the mask to mark outliers as False
        mask[global_indices_lo] = False
#         mask[global_indices_hi] = False

    return mask
