def _detect_deep_dips(
    residuals: np.ndarray,
    sigma: float = 4.0,
    grow_by: int = 1,
) -> np.ndarray:
    """
    Flag downward outliers in PLD residuals as candidate transit cadences.

    Uses MAD-scaled sigma clipping on the LOWER tail only.  Transit
    cadences are dips (flux < baseline), so only negative deviations
    are flagged.  Flagged regions are optionally grown by ``grow_by``
    cadences on each side to capture ingress/egress neighbours.

    Parameters
    ----------
    residuals : np.ndarray, shape (T,)
        PLD residuals (data minus model).  Should be approximately
        zero-mean with Gaussian-like noise plus transit dips.
    sigma : float, optional
        Number of MAD-scaled sigma below the median to flag.
        Default 4.0.  Lower values are more aggressive (mask more
        cadences); 3.5--5.0 is a reasonable range.
    grow_by : int, optional
        Expand each flagged cadence by this many neighbours on each
        side.  Default 1 (catches one ingress + one egress cadence
        adjacent to each flagged bottom cadence).

    Returns
    -------
    keep_mask : np.ndarray[bool], shape (T,)
        ``True`` = good cadence (retain in PLD fit).
        ``False`` = candidate transit cadence (zero-weight in PLD fit).

    Notes
    -----
    The MAD-to-sigma conversion factor 1.4826 assumes the bulk of the
    residuals are Gaussian.  The median and MAD are computed from all
    cadences including flagged ones; for duty cycles < 10 % the bias
    is negligible.

    Examples
    --------
    >>> resid = f_v - pld_model
    >>> keep = _detect_deep_dips(resid, sigma=4.0, grow_by=1)
    >>> ivar_protected = ivar.copy()
    >>> ivar_protected[~keep] = 0.0
    """
    finite = np.isfinite(residuals)
    med = np.nanmedian(residuals[finite])
    mad = 1.4826 * np.nanmedian(np.abs(residuals[finite] - med))

    if mad < 1e-30:
        # Degenerate case: all residuals identical
        return np.ones(len(residuals), dtype=bool)

    threshold = med - sigma * mad
    keep = residuals >= threshold  # only flag DOWNWARD excursions
    keep[~finite] = False          # also flag NaN/inf cadences

    # Grow flagged regions by ±grow_by cadences
    if grow_by > 0:
        bad = ~keep
        grown = bad.copy()
        for shift in range(1, grow_by + 1):
            if shift < len(grown):
                grown[shift:]  |= bad[:-shift]
                grown[:-shift] |= bad[shift:]
        keep = ~grown

    return keep
#
def get_PLD_model(
    time: np.ndarray,
    input_flux: np.ndarray,
    error: np.ndarray,
    flux: np.ndarray,
    pix_mask: np.ndarray,
    pld_order: int,
    n_pca_terms: int,
    lambda_reg: float,
    ivar: Optional[np.ndarray] = None,
    var_explained_thr: float = 0.95,
) -> np.ndarray:
    """
    Compute the additive PLD systematics model via weighted least squares.

    Constructs a design matrix from fractional pixel-flux basis vectors
    and their polynomial cross-terms, reduces each cross-term block via
    SVD, then solves a ridge-regularised WLS problem to produce an
    additive model of the instrumental systematics.

    Changes vs. original
    --------------------
    ``var_explained_thr`` (new) : when not ``None``, the number of SVD
    components kept for each higher-order cross-term block is the minimum
    needed to explain this fraction of variance in that block, capped at
    ``n_pca_terms``.  Motivation: for a 4-pixel aperture the 3rd-order
    cross-term matrix has rank ≤ 20; keeping a fixed 3 components discards
    85 % of the variance.  The adaptive choice makes the model equally
    faithful across aperture sizes and field crowding levels.  Pass
    ``var_explained_thr=None`` to restore the original fixed-count behaviour.

    Parameters
    ----------
    time : np.ndarray, shape (T,)
        Timestamps in days.  Unused in the solve; retained for API
        compatibility with callers that pass all LC arrays.
    input_flux : np.ndarray, shape (T,)
        SAP flux, normalized to ≈ 1.
    error : np.ndarray, shape (T,)
        1-sigma per-cadence flux uncertainty.
    flux : np.ndarray, shape (T, ny, nx)
        Quality-masked pixel image cube (counts/s).
    pix_mask : np.ndarray[bool], shape (ny, nx)
        Source aperture mask (``True`` = target pixel).
    pld_order : int
        Polynomial cross-term order.  Valid values: 1, 2, 3.
    n_pca_terms : int
        Hard cap on SVD components kept per cross-term block.
    lambda_reg : float
        Ridge regularisation coefficient (L2).  Set to ``0.0`` for
        unregularised least-squares.
    ivar : np.ndarray, shape (T,) or None, optional
        Per-cadence inverse variances.  Computed from ``error`` if ``None``.
        Default is ``None``.
    var_explained_thr : float or None, optional
        Fraction of variance to explain when choosing ``n_pca_terms``
        adaptively per cross-term block (default ``0.95``).  ``None``
        restores the original fixed-count behaviour.

    Returns
    -------
    pld_model : np.ndarray, shape (T,)
        Additive systematics model.  Subtract from flux and add the
        median to produce the detrended LC:
        ``detrended = flux - pld_model + np.nanmedian(pld_model)``.

    Examples
    --------
    >>> model = get_PLD_model(t, sap, err, cube, mask,
    ...                       pld_order=2, n_pca_terms=3,
    ...                       lambda_reg=0.0)
    >>> detrended = sap - model + np.nanmedian(model)
    """
    from itertools import combinations_with_replacement as _cwr
    from numpy.linalg import LinAlgError

    MAX_COMBOS = 5_000

    # ── aperture bounding-box crop ─────────────────────────────────────────
    rows, cols = np.where(pix_mask)
    r0, r1 = int(rows.min()), int(rows.max()) + 1
    c0, c1 = int(cols.min()), int(cols.max()) + 1
    flux_crop = flux[:, r0:r1, c0:c1]
    ap_crop   = pix_mask[r0:r1, c0:c1]
    pld_px    = flux_crop[:, ap_crop]               # (T, Npix)

    # ── first-order fractional pixel fluxes ───────────────────────────────
    f1    = pld_px.reshape(len(pld_px), -1).copy()
    f1    = f1[:, np.isfinite(f1).all(axis=0)]
    denom = np.nansum(pld_px, axis=-1)
    denom = np.where(np.abs(denom) < 1e-12, 1.0, denom)
    X1    = f1 / denom[:, None]
    X1    = np.nan_to_num(X1[:, np.isfinite(X1).any(axis=0)], nan=0.0)
    Npix  = X1.shape[1]

    # ── design matrix ─────────────────────────────────────────────────────
    X_parts = [np.ones((len(flux_crop), 1)), X1]

    for i in range(2, pld_order + 1):
        combos = list(_cwr(range(Npix), i))
        if not combos:
            continue
        if len(combos) > MAX_COMBOS:
            rng    = np.random.RandomState(42)
            combos = [combos[j] for j in
                      rng.choice(len(combos), MAX_COMBOS, replace=False)]

        f2 = np.column_stack([
            np.prod(X1[:, list(c)], axis=1) for c in combos
        ])                                          # (T, n_combos)
        f2 = f2[:, np.any(f2 != 0, axis=0)]
        if f2.shape[1] == 0:
            continue

        U, s, _ = np.linalg.svd(f2, full_matrices=False)

        # ── adaptive truncation ───────────────────────────────────────────
        if var_explained_thr is not None and len(s) > 1:
            sv_sq   = s ** 2
            cum_var = np.cumsum(sv_sq) / sv_sq.sum()
            # number of components to reach threshold
            n_adaptive = int(np.searchsorted(cum_var, var_explained_thr) + 1)
            n_keep = max(1, min(n_adaptive, n_pca_terms, U.shape[1]))
        else:
            n_keep = min(n_pca_terms, U.shape[1])

        X_parts.append(U[:, :n_keep])

    X = np.concatenate(X_parts, axis=1)             # (T, Ncomp)

    # ── weighted least-squares ────────────────────────────────────────────
    if ivar is None:
        ivar = 1.0 / np.maximum(error ** 2, 1e-30)

    bad_ivar = ~np.isfinite(ivar) | (ivar < 0)
    if bad_ivar.any():
        fallback = np.nanmedian(ivar[~bad_ivar]) if (~bad_ivar).any() else 1.0
        ivar = np.where(bad_ivar, fallback, ivar)

    I_reg = np.eye(X.shape[1])
    A     = X.T @ (X * ivar[:, None]) + (lambda_reg + 1e-8) * I_reg
    B     = X.T @ (input_flux * ivar)

    try:
        C = np.linalg.solve(A, B)
    except LinAlgError:
        C = np.linalg.lstsq(A, B, rcond=None)[0]

    return X @ C
#
#
#
def PLD_model( ID, Sector, flux: np.ndarray, pix_mask: np.ndarray, input_LC, 
              default_settings: dict, window: int = 10, max_dur: float = 1.0,
              Nsigma: float = 15.0, N_transits = None, lambda_reg: float = 0.0, 
              cadence_mask=None, do_plot: bool = False,
) -> "pd.DataFrame":
    """
    Two-pass Pixel Level Decorrelation (PLD) with GP-proxy variance inflation.

    Pass 1 solves a standard diagonal-ivar WLS PLD model.  Pass 2 inflates
    the per-cadence weights in regions of high stellar variability (flares,
    starspots) so that PLD fits only instrument systematics, not astrophysical
    signal.

    Behaviour changes vs. original
    --------------------------------
    1. **GP-proxy weighting** (new) — after Pass 1 a biweight trend of the
       residuals estimates the local stellar variability amplitude σ_stellar(t).
       The effective variance for Pass 2 is
       ``σ_eff²(t) = σ_flux²(t) + σ_stellar²(t)``.
       Window controlled by ``default_settings['pld_gp_proxy_window']``
       (default 0.5 d; set to ``None`` to recover original diagonal-ivar
       behaviour).
    2. **Additive detrending** — original used ``flux / model``
       (multiplicative).  Now uses ``flux − model + median(model)``
       normalized to median = 1.  Preserves flare amplitudes and avoids
       biasing transit depths in variable stars.
    3. **Cadence mask is now active** — previously applied as all-``True``
       (no-op); now gates the WLS solve as intended.
    4. **Headless-safe plots** — ``plt.show()`` calls are gated behind
       ``do_plot=True`` so cluster/headless runs do not hang.

    Parameters
    ----------
    ID : int
        TIC identifier; used for verbose logging.
    Sector : int
        TESS sector number; used for verbose logging.
    flux : np.ndarray, shape (T, ny, nx)
        Quality-masked pixel image cube (counts/s), aligned with
        the cadences in ``input_LC``.
    pix_mask : np.ndarray[bool], shape (ny, nx)
        Source aperture mask (``True`` = target pixel).
    input_LC : pd.DataFrame
        Clipped SAP light curve from ``Applying_Mdump_removal``.
        Must contain ``'Time'`` and either ``('SAP Flux', 'SAP Error')``
        or ``('Flux', 'Error')``.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys:
        ``pld_order``, ``n_pca_terms``, ``verbose``,
        ``pld_gp_proxy_window`` (optional, default 0.5 d).
    window : int, optional
        Legacy parameter; not used in current implementation.
        Default is ``10``.
    max_dur : float, optional
        Window size (days) for the Pass-2 outlier gate via
        ``quick_outlier_removal``.  Default is ``1.0``.
    Nsigma : float, optional
        Sigma threshold for outlier identification in the Pass-2 gate.
        Default is ``15.0`` (intentionally high to only zero-weight
        extreme outliers such as flare peaks).
    N_transits : int, optional
        Legacy parameter; not used in current implementation.
        Default is ``3``.
    lambda_reg : float, optional
        Ridge (L2) regularisation coefficient passed to ``get_PLD_model``.
        ``0.0`` = unregularised.  Default is ``0.0``.
    cadence_mask : np.ndarray[bool] or None, optional
        Additional boolean mask applied to valid cadences before the WLS
        solve.  ``None`` = no additional masking.  Default is ``None``.
    do_plot : bool, optional
        If ``True``, show diagnostic plots of the SAP flux, PLD model,
        and detrended output.  Default is ``False``.

    Returns
    -------
    PLD_LC : pd.DataFrame
        All columns of ``input_LC`` preserved, with three columns added
        or updated:
        ``'PLD Flux'`` — detrended, normalized flux.
        ``'PLD Error'`` — propagated uncertainty.
        ``'PLD Model'`` — additive systematics model from Pass 2.
        Outlier cadences (zero-weighted in Pass 2) are restored using
        neighbour-interpolated baseline + astrophysical deviation.

    Examples
    --------
    >>> PLD_LC = PLD_model(ID, Sector, flux, pix_mask,
    ...                    clippedRAWLC_df, default_settings)
    >>> PLD_LC = PLD_model(ID, Sector, flux, pix_mask,
    ...                    clippedRAWLC_df, default_settings,
    ...                    lambda_reg=1e-3, do_plot=True)
    """
    import time as _clock
    import warnings
    import pandas as pd
    import matplotlib.pyplot as plt
    from wotan import flatten

    warnings.simplefilter("ignore")
    t_start = _clock.time()

    # ── settings ──────────────────────────────────────────────────────────────
    pld_order        = default_settings.get('pld_order')
    n_pca_terms      = default_settings.get('n_pca_terms')
    verbose          = default_settings.get('verbose')
    # NEW key: set to None to disable GP proxy and match original behaviour
    gp_proxy_window  = default_settings.get('pld_gp_proxy_window', 0.5)
    N_transits = default_settings.get('N_transits', 3)

    # ── unpack LC columns (handles both 'SAP Flux' and 'Flux' column names) ───
    lc         = input_LC.copy(deep=True)
    time_arr   = lc['Time'].to_numpy(dtype=np.float64)
    n_full     = len(lc)

    def _col(df, *names):
        for n in names:
            if n in df.columns:
                return df[n].to_numpy(dtype=np.float64)
        return np.zeros(len(df), dtype=np.float64)

    input_flux = _col(lc, 'SAP Flux', 'Flux')
    error      = _col(lc, 'SAP Error', 'Error')
    orig_sap   = input_flux.copy()   # keep for outlier restoration
    orig_err   = error.copy()

    if verbose:
        print(f'PLD input shape: {lc.shape}')

    # ── finite / cadence mask ─────────────────────────────────────────────────
    valid = (np.isfinite(time_arr) & np.isfinite(input_flux) &
             np.isfinite(error)    & (np.abs(error) > 1e-12))

    # FIX: cadence_mask was previously applied as all-True (no-op)
    if cadence_mask is not None:
        cm = np.asarray(cadence_mask, dtype=bool)
        if cm.shape == valid.shape:
            valid = valid & cm

    vidx           = np.where(valid)[0]        # indices into original array
    t_v, f_v, e_v = time_arr[valid], input_flux[valid], error[valid]
    flux_v         = flux[valid]
    ivar_diag      = 1.0 / np.maximum(e_v ** 2, 1e-30)

    # ── Pass 1: standard diagonal-ivar WLS ───────────────────────────────────
    pld1 = get_PLD_model(t_v, f_v, e_v, flux_v, pix_mask,
                         pld_order, n_pca_terms, lambda_reg, ivar=ivar_diag)

    # ── GP-proxy: inflate variance where stellar variability is large ─────────
    #
    # After subtracting the Pass-1 PLD model, the residuals contain stellar
    # variability + photon noise.  A biweight trend on those residuals estimates
    # the smooth stellar component σ_stellar(t).  Adding σ_stellar² to σ_flux²
    # is a diagonal approximation to the GP covariance matrix K used in EVEREST
    # (eq. 8), which prevents PLD from absorbing rotational modulation or the
    # slowly-varying envelope of flare sequences.
    if gp_proxy_window is not None and len(t_v) > 10:
        try:
            resid1 = f_v - pld1
            _, stellar_trend = flatten(
                t_v, resid1,
                window_length=float(gp_proxy_window),
                return_trend=True,
                method='biweight',
                break_tolerance=0.5,
            )
            med_trend = np.nanmedian(stellar_trend)
            if not np.isfinite(med_trend):
                # flatten returned all-NaN trend (e.g. too few valid points in
                # window); fall back to diagonal ivar for this star
                stellar_sigma = np.zeros_like(f_v)
            else:
                stellar_sigma = np.abs(stellar_trend - med_trend)
                # clip any remaining NaN/inf from window-edge artefacts to 0
                stellar_sigma = np.where(np.isfinite(stellar_sigma),
                                         stellar_sigma, 0.0)
        except Exception as _exc:
            if verbose:
                print(f'[PLD] GP proxy fallback ({_exc}); using diagonal ivar')
            stellar_sigma = np.zeros_like(f_v)
        ivar2 = 1.0 / np.maximum(e_v ** 2 + stellar_sigma ** 2, 1e-30)
    else:
        ivar2 = ivar_diag

    # ── outlier mask: gates Pass-2 solve, not cadence presence in output ──────
    tmp_lc = pd.DataFrame({'Time': t_v, 'SAP Flux': f_v, 'SAP Error': e_v})
    out_ok = quick_outlier_removal(
        tmp_lc, flux_type='SAP',
        Nsigma=Nsigma, window_size_in_days=max_dur, method='global',
    )
    ivar2_gated          = ivar2.copy()
    ivar2_gated[~out_ok] = 0.0        # zero-weight outliers rather than drop

    # ── Pass 2: GP-proxy weighted WLS ────────────────────────────────────────
    pld2 = get_PLD_model(t_v, f_v, e_v, flux_v, pix_mask,
                         pld_order, n_pca_terms, lambda_reg, ivar=ivar2_gated)
    
    # ── Pass 3 (new): iterative transit protection ────────────────────────────
    #
    # After Pass 2, deep transits (especially short-period) can leak into
    # the PLD fit because the Pass-2 outlier gate (Nsigma=15) is designed
    # for flares, not transits.  This loop detects downward outliers in
    # the PLD residuals (where scatter is low enough to resolve transits),
    # zero-weights them, and re-solves PLD.  Converges in 1--3 iterations.
    #
    # Controlled by two new default_settings keys:
    #   'pld_transit_mask_sigma' : float (default 4.0)
    #   'pld_transit_mask_iter'  : int   (default 3)
    #   'pld_transit_mask_grow'  : int   (default 1)
    #
    # Set 'pld_transit_mask_iter' to 0 to disable entirely (original behaviour).

    _tm_sigma = default_settings.get('pld_transit_mask_sigma', 4.0)
    _tm_iter  = default_settings.get('pld_transit_mask_iter', 3)
    _tm_grow  = default_settings.get('pld_transit_mask_grow', 1)

    _transit_mask_all = np.ones(len(f_v), dtype=bool)  # cumulative mask

    for _it in range(_tm_iter):
        resid = f_v - pld2
        _keep = _detect_deep_dips(resid, sigma=_tm_sigma, grow_by=_tm_grow)

        # How many NEW cadences were flagged this iteration?
        _newly_flagged = int((_transit_mask_all & ~_keep).sum())
        if _newly_flagged == 0:
            if verbose:
                print(f'[PLD] Transit protection iter {_it + 1}: '
                      f'converged (no new cadences flagged)')
            break

        _transit_mask_all &= _keep  # accumulate across iterations

        # Safety: don't mask more than 15 % of cadences total
        _n_good = int((_transit_mask_all & out_ok).sum())
        if _n_good < 0.50 * len(f_v):
            if verbose:
                print(f'[PLD] Transit protection iter {_it + 1}: '
                      f'safety stop — {_n_good}/{len(f_v)} cadences remain')
            # Revert to the mask from the previous iteration
            _transit_mask_all |= ~_keep
            break

        # Rebuild ivar: combine GP-proxy weights + original outlier gate
        # + transit protection mask
        _ivar_protected = ivar2.copy()
        _ivar_protected[~out_ok]            = 0.0   # original outlier gate
        _ivar_protected[~_transit_mask_all] = 0.0   # transit protection

        # Re-solve PLD with transit cadences excluded
        pld2 = get_PLD_model(t_v, f_v, e_v, flux_v, pix_mask,
                             pld_order, n_pca_terms, lambda_reg,
                             ivar=_ivar_protected)

        if verbose:
            _total_masked = int((~_transit_mask_all).sum())
            print(f'[PLD] Transit protection iter {_it + 1}: '
                  f'+{_newly_flagged} cadences flagged '
                  f'({_total_masked} total transit-masked)')

    # ── Additive detrending ───────────────────────────────────────────────────
    # FIX: original used flux / model (multiplicative).
    # Additive form: detrended = flux − model + median(model)
    # then normalized to median = 1.0.
    # For an ideal systematic-only model, median(model) ≈ median(flux) ≈ 1.0,
    # so the two approaches agree out of transit; they diverge for high-amplitude
    # events (flares, deep transits) where the multiplicative form squashes depth.
    med_model      = np.nanmedian(pld2)
    detrended_v    = f_v - pld2 + med_model
    norm           = np.nanmedian(detrended_v)
    detrended_v   /= norm
    pld_error_v    = e_v / norm

    # ── map back to full-length arrays ───────────────────────────────────────
    out_det   = np.full(n_full, np.nan)
    out_err   = np.full(n_full, np.nan)
    out_model = np.full(n_full, np.nan)

    out_det  [vidx] = detrended_v
    out_err  [vidx] = pld_error_v
    out_model[vidx] = pld2       
    
    # ── restore outlier cadences ──────────────────────────────────────────────
    # Original approach used raw SAP deviations, which re-injects systematics
    # and amplifies transit depths via cascading neighbor interpolation.
    # Fix: use the additive-detrended value directly. The PLD model
    # extrapolates reliably at zero-weighted cadences because the pixel-ratio
    # regressors are well-constrained by the remaining cadences.
    med_sap      = np.nanmedian(f_v)
    bad_full_idx = vidx[~out_ok]

    for fi in bad_full_idx:
        # The additive-detrended value is already in out_det[fi]
        # (set by out_det[vidx] = detrended_v above).
        # Only restore if it is NaN (should not happen for valid cadences).
        if not np.isfinite(out_det[fi]):
            left  = (out_det[fi - 1]
                     if (fi > 0          and np.isfinite(out_det[fi - 1])) else None)
            right = (out_det[fi + 1]
                     if (fi < n_full - 1 and np.isfinite(out_det[fi + 1])) else None)
            nbrs     = [v for v in (left, right) if v is not None]
            out_det[fi] = float(np.nanmean(nbrs)) if nbrs else 1.0
        # Error: use original error scaled by norm
        out_err[fi] = orig_err[fi] / norm
        
    # Add this inside PLD_model, right after the restoration loop:
    if verbose:
        print(f'[PLD] Outlier restoration: {len(bad_full_idx)} cadences restored')

    # ── assemble output (preserve all input columns) ──────────────────────────
    PLD_LC              = lc.copy(deep=True)
    PLD_LC['PLD Flux']  = out_det
    PLD_LC['PLD Error'] = out_err
    PLD_LC['PLD Model'] = out_model

    # ── diagnostic plot (gated; original had unconditional plt.show()) ────────
    if do_plot:
        fig, axes = plt.subplots(2, 1, figsize=(12, 5), sharex=True)
        axes[0].plot(time_arr, orig_sap, 'k.', ms=1, label='SAP flux')
        axes[0].plot(time_arr[valid], pld2, color='orange', lw=0.8,
                     label='PLD model (pass 2)')
        axes[0].set_ylabel('Flux')
        axes[0].legend(markerscale=4, fontsize=8)
        axes[1].plot(time_arr, out_det, 'k.', ms=1, label='PLD detrended')
        axes[1].axhline(1.0, color='red', lw=0.5, ls='--')
        axes[1].set_ylabel('Norm. flux')
        axes[1].set_xlabel('Time [BTJD]')
        axes[1].legend(markerscale=4, fontsize=8)
        fig.suptitle(f'TIC {ID}  Sector {Sector}  —  PLD (v2)', fontsize=10)
        plt.tight_layout()
        plt.show()

    if verbose:
        timer(t_start, _clock.time(), 'PLD_model (v2) took:')

    return PLD_LC
#
#
#
def singleoutliers(data, stepsize=1):
    """
    This function will search input data for points that are not
    consecutive.
    Input Parameters
    ----------
    data : array
        Input data to be searched over
    stepsize : int
        Value representing how many consecutive points to search for.
    Returns
    -------
        * single : array
            An array of non-consecutive points.
    """      
    # Split data into chunks where the difference is not equal to the stepsize
    single=np.split(data, np.where(np.diff(data) != stepsize)[0]+1)
    # Filter out sequences that have more than one element, keeping only isolated points
    single = np.array(list(filter(lambda x : len(x) <= 1, single))).flatten() 
    #
    #
    ##sort the indcies and make sure they're integers
    single = np.sort(np.array([np.int64(x) for x in single]))
    single = np.sort(np.asarray(single, dtype=int)) #same thing?    
    return single
#
#
#
def consecutive(data, stepsize=1):
    """
    This function will search input data for points that are
    consecutive.
    Input Parameters
    ----------
    data : array
        Input data to be searched for consecutive values.
    stepsize : int
        Value representing the step between consecutive points (default is 1).
    Returns
    -------
    consec : array
        An array of consecutive points.
    """      
    runs = np.split(data, np.where(np.diff(data) != stepsize)[0] + 1)
    runs = [r for r in runs if len(r) > 1]          # keep only multi-element runs
    if not runs:
        return np.array([], dtype=np.int64)
    return np.concatenate(runs).astype(np.int64)     # single allocation
#
#
#
def outlier_removal(ID,nearby_star_catalog, Sector, input_LC, default_settings, 
                    method='local', window_size_in_days=None):
    """
    Sliding-window sigma-clipping outlier removal on the detrended light curve.

    Iterates over fixed-width time windows and identifies outliers using the
    Median Absolute Deviation (MAD) scaled to the standard deviation.  Outliers
    are classified as either *bad* (isolated, non-consecutive — likely cosmic
    rays or spacecraft artifacts) or *good* (consecutive — likely real
    astrophysical events such as transits or flares).  Only *bad* outliers are
    removed from the final light curve; *good* outliers are retained and saved
    separately for downstream inspection.

    Sigma clipping is asymmetric by default:
    ``Nsigma_low`` applies below the median (preserves transit depths);
    ``Nsigma_high`` applies above.  When ``Nsigma`` is a scalar both
    thresholds are equal.

    When ``remove_outliers=False`` (from ``default_settings``), the function
    returns the input LC unchanged with empty outlier DataFrames.

    Parameters
    ----------
    ID : int
        TIC identifier; used to construct output filenames.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog; used to derive the smoothing window floor via
        ``T14`` when ``window_size_in_days`` is ``None``.
    Sector : int or list or None
        Sector(s) being processed; used to construct the sector-tag string.
    input_LC : pd.DataFrame
        Smoothed light curve from ``Smoother``.  Required columns:
        ``Time``, ``SAP Flux``, ``SAP Error``,
        ``Background Flux``, ``Background Error``,
        ``Detrended Flux``, ``Detrended Error``, ``Fitted Trend``,
        ``PLD Flux``, ``PLD Error``, ``PLD Model``,
        ``Centroid X Positions``, ``Centroid Y Positions``.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys:
        ``remove_outliers``, ``Nsigma``, ``savelcpath``, ``verbose``,
        ``window_size_in_days``, ``get_all_sectors``.

    Returns
    -------
    LC_df : pd.DataFrame
        Final light curve with *bad* outliers removed.  Columns:
        ``Time``, ``SAP Flux``, ``SAP Error``,
        ``Background Flux``, ``Background Error``,
        ``PLD Flux``, ``PLD Error``, ``PLD Model``,
        ``Detrended Flux``, ``Detrended Error``, ``Fitted Trend``,
        ``Centroid X Positions``, ``Centroid Y Positions``.
    good_ind_DF : pd.DataFrame
        Cadences flagged as outliers that are *consecutive* in time
        (retained; likely transits or flares).  Same column schema as
        ``LC_df``.
    bad_ind_DF : pd.DataFrame
        Cadences flagged as outliers that are *isolated* (non-consecutive;
        removed from ``LC_df``).  Same column schema.
    preclipLC_df : pd.DataFrame
        The input ``input_LC`` before any outlier removal is applied;
        used by ``plot_it_all_up`` to show the pre-clipping light curve.

    Notes
    -----
    Saved outputs (to ``savelcpath``):
        ``TIC_{ID}_Sector_{NNNN}_final_LC_preclipped.csv``
        ``TIC_{ID}_Sector_{NNNN}_bad_outliers.csv``
        ``TIC_{ID}_Sector_{NNNN}_good_outliers.csv``
        ``TIC_{ID}_Sector_{NNNN}_final_LC.csv``
    """      
    # get function settings
    remove_outliers = default_settings.get('remove_outliers')
    Nsigma = default_settings.get('Nsigma')
    savelcpath = default_settings.get('savelcpath')
    verbose = default_settings.get('verbose')
    window_size_in_days = default_settings.get('window_size_in_days')
    get_all_sectors = default_settings.get('get_all_sectors')
    #
    # Step 0: define string tag for sector usage (single or multi)  
    if isinstance(Sector, int):
        sector_tag = f"Sector_{Sector:04d}"
    else:
        sector_tag = "Multi_Sector"
    #
    import numpy as np
    import pandas as pd
    from scipy import stats   
    from astropy.stats.funcs import median_absolute_deviation as MAD
    ###
    # interpret Nsigma input
    if type(Nsigma)==list:
        Nsigma_low, Nsigma_high = Nsigma[0], Nsigma[1]
    if (type(Nsigma)==int) or (type(Nsigma)==float):
        Nsigma_low, Nsigma_high = Nsigma, Nsigma #s ame as above as is below    
    ###
    #read in input data
    time = input_LC['Time'].to_numpy(dtype=np.float64)
    sap_flux =  input_LC['SAP Flux'].to_numpy(dtype=np.float64)
    sap_error=  input_LC['SAP Error'].to_numpy(dtype=np.float64)
    bkg_flux =  input_LC['Background Flux'].to_numpy(dtype=np.float64)
    bkg_error=  input_LC['Background Error'].to_numpy(dtype=np.float64)    
    det_flux =  input_LC['Detrended Flux'].to_numpy(dtype=np.float64)
    det_error = input_LC['Detrended Error'].to_numpy(dtype=np.float64)
    trend_lc =  input_LC['Fitted Trend'].to_numpy(dtype=np.float64)
    pld_flux =  input_LC['PLD Flux'].to_numpy(dtype=np.float64)
    pld_error = input_LC['PLD Error'].to_numpy(dtype=np.float64)
    pld_model = input_LC['PLD Model'].to_numpy(dtype=np.float64)
    centx   =   input_LC['Centroid X Positions'].to_numpy(dtype=np.float64)
    centy   =   input_LC['Centroid Y Positions'].to_numpy(dtype=np.float64)
    #
    #
    cadence_index = (
        input_LC['CADENCE_INDEX'].to_numpy(dtype=int)
        if 'CADENCE_INDEX' in input_LC.columns
        else np.arange(len(time), dtype=int)
    )
    #
    quality_flag = (
        input_LC['QUALITY_FLAG'].to_numpy(dtype=int)
        if 'QUALITY_FLAG' in input_LC.columns
        else np.zeros(len(time), dtype=int)
    )    
    #
    #
    #
    preclipLC_df = pd.DataFrame({ "CADENCE_INDEX": cadence_index, "Time": time,
                                 "SAP Flux": sap_flux, "SAP Error": sap_error,
                                 "Background Flux": bkg_flux, "Background Error": bkg_error,
                                 "PLD Flux": pld_flux, "PLD Error": pld_error, "PLD Model": pld_model,
                                 "Detrended Flux": det_flux, "Detrended Error": det_error, "Fitted Trend": trend_lc,
                                 "Centroid X Positions": centx, "Centroid Y Positions": centy, "QUALITY_FLAG": quality_flag,
                                })
    ###
    ###
    #defining window for removing outliers in local noise
    LCDur=(np.nanmax(time) - np.nanmin(time))
    maxP = LCDur/2 #longest period for 2 transits in a light curve (~14 days for TESS single sector LCs)
    R_planet_RE = 1
    #
    star = nearby_star_catalog.loc[nearby_star_catalog['ID']==str(ID)].reset_index(drop=True)
    star = get_qld(star,verbose)    
    R_star, M_star = star['rad'].item(),star['mass'].item()
    #
    if window_size_in_days==None:
        # we want to keep the longest transit for an Earth-like planet for a single sector of data
        # using stellar parameters to determine transit duration
        window_size_in_days = 5* T14(P=maxP, R_star=R_star, M_star=M_star, R_planet=R_planet_RE)
    #
    if remove_outliers==True:
        #needs to be flexible to allow different combos of PLD, DET and SAP
        # use last step in operation's flux (SAP, DET or PLD)
        flux = pld_flux
        error = pld_error
        ###
        if method=='global':
            #global noise level
            flux_threshold_lo = np.nanmedian(flux)-Nsigma_low*MAD(flux)
            flux_threshold_hi = np.nanmedian(flux)+Nsigma_high*MAD(flux)
        ###
        cad = np.nanmedian(np.diff(time[np.isfinite(time)]))
        Npts = int(np.round(((window_size_in_days/cad))+1,1))
        size=len(time)
        window_size=Npts
        if window_size > size:
            window_size = size
        bins = int(size/Npts)+2
        good_ind_lo=[]
        bad_ind_lo=[]
        good_ind_hi=[]
        bad_ind_hi=[]
        for N in range(1,bins):
            window_start = window_size * (N - 1)
            window_stop  = window_start + window_size
            time_in_window = time[window_start : window_stop ]
            flux_in_window = flux[window_start : window_stop ]
            err_in_window = error[window_start : window_stop ]
            if method=="local":
                #local noise
                flux_threshold_lo = np.nanmedian(flux_in_window)-Nsigma_low*MAD(flux_in_window)
                flux_threshold_hi = np.nanmedian(flux_in_window)+Nsigma_high*MAD(flux_in_window)
            ###
            #global noise
            ind_lo = np.where(flux_in_window < flux_threshold_lo)[0]
            ind_hi = np.where(flux_in_window > flux_threshold_hi)[0]
            ###
            single_lo = singleoutliers(ind_lo)
            single_hi = singleoutliers(ind_hi)
            ###
            consec_lo = consecutive(ind_lo)
            consec_hi = consecutive(ind_hi)
            ###
            #map elements identified in window to full input array            
            if len(consec_hi) > 0:
                good_ind_hi = np.append(good_ind_hi, window_start + consec_hi)
            if len(single_hi) > 0:
                bad_ind_hi  = np.append(bad_ind_hi,  window_start + single_hi)
            if len(consec_lo) > 0:
                good_ind_lo = np.append(good_ind_lo, window_start + consec_lo)
            if len(single_lo) > 0:
                bad_ind_lo  = np.append(bad_ind_lo,  window_start + single_lo)
            ###
            #convert matched elements to intergers
            bad_ind_lo=np.sort(np.array([np.int64(x) for x in bad_ind_lo]))
            bad_ind_hi=np.sort(np.array([np.int64(x) for x in bad_ind_hi]))
            good_ind_lo=np.sort(np.array([np.int64(x) for x in good_ind_lo]))
            good_ind_hi=np.sort(np.array([np.int64(x) for x in good_ind_hi]))
            ###
            ### append both high/low results to final arrays
            #bad_ind = np.sort(np.append(bad_ind_lo,bad_ind_hi).flatten())
            ###
            ### MAAAAAYBE we don't want to keep positive outliers after all...
            # good_ind = np.sort(np.append(good_ind_lo,good_ind_hi).flatten())
            #good_ind = np.sort((good_ind_lo).flatten())
            ### MAAAAAYBE we don't want to keep positive outliers after all...            
            #
            #temp_bad_ind = np.append(bad_ind_lo,bad_ind_hi)
            #bad_ind = np.sort(np.append(temp_bad_ind,good_ind_hi).flatten())
            ###
            ###                                  
#             bad_ind=np.sort(np.array([np.int64(x) for x in bad_ind]))
#             good_ind=np.sort(np.array([np.int64(x) for x in good_ind]))
            ###
        # Isolated outliers on both tails are removed.
        # Consecutive LOW outliers (transit-like dips) are preserved.
        # Consecutive HIGH outliers (flare sequences) are also removed.
        bad_ind  = np.sort(np.concatenate([
            bad_ind_lo,    # isolated dips
            bad_ind_hi,    # isolated brightenings
            good_ind_hi,   # consecutive brightenings (flares) # removed for transit searches
        ]).astype(int))
        #
        good_ind = np.sort(good_ind_lo.astype(int))   # consecutive dips only (transit candidates)    
        #
        #
        # finally, remove bad points (keep good points) and make new time,flux, error arrays
        #
        bad_ind = np.asarray(bad_ind, dtype=int) 
        #
        bad_cadence_index = np.asarray(cadence_index)[bad_ind]
        bad_quality_flag  = np.asarray(quality_flag)[bad_ind]
        #
        (badtime, badsap_flux, baderror, badbkg_flux, badbkg_error,
         badflux_detrended, baddet_error, badtrend_lc,
         badpld_detrended, badpld_model, badpld_error,
         badcentx, badcenty) = [np.asarray(arr)[bad_ind] for arr in (
            time, sap_flux, sap_error,
            bkg_flux, bkg_error,
            det_flux, det_error, trend_lc,
            pld_flux, pld_model, pld_error,
            centx, centy)]
        #
        good_ind = np.asarray(good_ind, dtype=int) 
        #
        good_cadence_index = np.asarray(cadence_index)[good_ind]
        good_quality_flag  = np.asarray(quality_flag)[good_ind]
        #
        (goodtime, goodsap_flux, gooderror, goodbkg_flux, goodbkg_error,
         goodflux_detrended, gooddet_error, goodtrend_lc,
         goodpld_detrended, goodpld_model, goodpld_error,
         goodcentx, goodcenty) = [np.asarray(arr)[good_ind] for arr in (
            time, sap_flux, sap_error,
            bkg_flux, bkg_error,            
            det_flux, det_error, trend_lc,
            pld_flux, pld_model, pld_error,
            centx, centy)]
        #
        bad_ind = np.asarray(bad_ind, dtype=int)
        keep    = np.ones(time.size, dtype=bool)     # True everywhere
        keep[bad_ind] = False                        # False at bad rows

        (time,sap_flux,sap_error,
         bkg_flux, bkg_error,         
         det_flux,det_error,trend_lc,
         pld_flux,pld_error,pld_model,
         centx,centy) = [np.asarray(arr)[keep] for arr in (
            time, sap_flux, sap_error,
            bkg_flux, bkg_error,            
            det_flux, det_error, trend_lc,
            pld_flux, pld_error, pld_model,
            centx, centy)]        
        #        
        cadence_index = np.asarray(cadence_index)[keep]
        quality_flag  = np.asarray(quality_flag)[keep]
        #
        import pandas as pd
        #saving flagged data points
        if verbose==True:
            print('saving flagged outliers')
        bad_ind_DF = pd.DataFrame({"CADENCE_INDEX": bad_cadence_index, "Time": badtime,
                                   "SAP Flux": badsap_flux, "SAP Error": baderror,
                                   "Background Flux": badbkg_flux, "Background Error": badbkg_error,
                                   "PLD Flux": badpld_detrended, "PLD Error": badpld_error, 
                                   "PLD Model": badpld_model, 
                                   "Detrended Flux": badflux_detrended, "Detrended Error": baddet_error, 
                                   "Fitted Trend": badtrend_lc,
                                   "Centroid X Positions": badcentx, "Centroid Y Positions": badcenty,
                                   "QUALITY_FLAG": bad_quality_flag,
                                  })

        good_ind_DF = pd.DataFrame({"CADENCE_INDEX": good_cadence_index, "Time": goodtime,
                                    "SAP Flux": goodsap_flux, "SAP Error": gooderror,
                                    "Background Flux": goodbkg_flux, "Background Error": goodbkg_error,
                                    "PLD Flux": goodpld_detrended, "PLD Error": goodpld_error, 
                                    "PLD Model": goodpld_model,
                                    "Detrended Flux": goodflux_detrended, "Detrended Error": gooddet_error,
                                    "Fitted Trend": goodtrend_lc,
                                    "Centroid X Positions": goodcentx, "Centroid Y Positions": goodcenty,
                                    "QUALITY_FLAG": good_quality_flag,
                                   })        
        #
        # this could be interesting to keep but is otherwise unused by pipeline elsewhere
        #bad_ind_DF.to_csv(savelcpath+"TIC_"+str(ID)+f"_{sector_tag}_bad_outliers.txt",index=False)
        #good_ind_DF.to_csv(savelcpath+"TIC_"+str(ID)+f"_{sector_tag}_good_outliers.txt",index=False)
        # this could be interesting to keep but is otherwise unused by pipeline elsewhere
        #
        if verbose==True:
            print('after outlier removal: ',' T', len(time),' Det',len(det_flux), ' trend',len(trend_lc), 'PLD model',len(pld_model),' PLD F',len(pld_flux),' SAP E', len(sap_error))
    ###
    if remove_outliers==False:
        #
        time = np.ascontiguousarray(time, dtype=np.float64)
        sap_flux = np.ascontiguousarray(sap_flux, dtype=np.float64)
        sap_error = np.ascontiguousarray(sap_error, dtype=np.float64)
        bkg_flux = np.ascontiguousarray(bkg_flux, dtype=np.float64)
        bkg_error = np.ascontiguousarray(bkg_error, dtype=np.float64)        
        det_flux = np.ascontiguousarray(det_flux, dtype=np.float64)
        det_error= np.ascontiguousarray(det_error, dtype=np.float64)
        trend_lc = np.ascontiguousarray(trend_lc, dtype=np.float64)
        pld_flux = np.ascontiguousarray(pld_flux, dtype=np.float64)
        pld_error = np.ascontiguousarray(pld_error, dtype=np.float64)
        pld_model = np.ascontiguousarray(pld_model, dtype=np.float64)
        centx = np.ascontiguousarray(centx, dtype=np.float64)
        centy = np.ascontiguousarray(centy, dtype=np.float64)
        #
        # NEW
        time, sap_flux, sap_error, bkg_flux, bkg_error, det_flux, det_error, trend_lc, pld_flux, pld_error, pld_model, centx, centy = map(
            lambda a: np.ascontiguousarray(a, dtype=np.float64),
            (time, sap_flux, sap_error,
             bkg_flux, bkg_error,
             det_flux, det_error, trend_lc,
             pld_flux, pld_error, pld_model,
             centx, centy) )
        #
        good_ind_DF = pd.DataFrame({ "CADENCE_INDEX": [None], "Time": [None],
                                    "SAP Flux": [None], "SAP Error": [None],
                                    "Background Flux": [None], "Background Error": [None], 
                                    "PLD Flux": [None], "PLD Error": [None], "PLD Model": [None],
                                    "Detrended Flux": [None], "Detrended Error": [None], "Fitted Trend": [None],
                                    "Centroid X Positions": [None], "Centroid Y Positions": [None],
                                    "QUALITY_FLAG": [None],
                                   })

        bad_ind_DF = pd.DataFrame({ "CADENCE_INDEX": [None], "Time": [None],
                                    "SAP Flux": [None], "SAP Error": [None],
                                    "Background Flux": [None], "Background Error": [None], 
                                    "PLD Flux": [None], "PLD Error": [None], "PLD Model": [None],
                                    "Detrended Flux": [None], "Detrended Error": [None], "Fitted Trend": [None],
                                    "Centroid X Positions": [None], "Centroid Y Positions": [None],
                                    "QUALITY_FLAG": [None],
                                   })
        #
        if verbose==True:
            print('skipping outlier removal:',' T', len(time),' Det',len(det_flux), ' trend',len(trend_lc), 'PLD model',len(pld_model),' PLD F',len(pld_flux),' SAP E', len(sap_error))
    ###
    ###
    ###
    nanmask =  np.where(np.isfinite(pld_flux)==True)[0]
    time =     time[nanmask]
    sap_flux = sap_flux[nanmask]
    sap_error= sap_error[nanmask]
    bkg_flux = bkg_flux[nanmask]
    bkg_error= bkg_error[nanmask]    
    det_flux = det_flux[nanmask]
    det_error= det_error[nanmask]
    trend_lc = trend_lc[nanmask]
    pld_flux = pld_flux[nanmask]
    pld_error= pld_error[nanmask]
    pld_model= pld_model[nanmask]
    centx =    centx[nanmask]
    centy =    centy[nanmask]
    #
    cadence_index = cadence_index[nanmask]
    quality_flag  = quality_flag[nanmask]
    #
    #
    LC_df = pd.DataFrame({"CADENCE_INDEX": cadence_index, "Time": time,
                          "SAP Flux": sap_flux, "SAP Error": sap_error,
                          "Background Flux": bkg_flux, "Background Error": bkg_error,
                          "PLD Flux": pld_flux, "PLD Error": pld_error, "PLD Model": pld_model,
                          "Detrended Flux": det_flux, "Detrended Error": det_error, "Fitted Trend": trend_lc,
                          "Centroid X Positions": centx, "Centroid Y Positions": centy,
                          "QUALITY_FLAG": quality_flag })    
    #
    ###
    if verbose==True:
        print(f'Saving LC to {savelcpath+"TIC_"+str(ID)+f"_{sector_tag}_final_LC.csv"}')
    LC_df.to_csv(savelcpath+"TIC_"+str(ID)+f"_{sector_tag}_final_LC.csv",index=False)
    ###
    ###
    return LC_df, good_ind_DF, bad_ind_DF, preclipLC_df
#
#
#
def plot_it_all_up(ID, nearby_star_catalog, Sector, cadence, hdu,
                   RAWLC_df, clippedRAWLC_df, LC_df, 
                   good_ind_DF, bad_ind_DF, preclipLC_df, default_settings,
                   # ----- single-sector only (pass None for multi-sector) ----- 
                   median_image=None, pix_mask=None, bkg_mask=None,
                   magnitude_limit=18, dot_scale=20, cbarpad=0.01, 
                   fs = 16,
                   savefigname=None, 
                   # ----- optional SAP diagnostic kwargs ----- 
                   bkg_residuals=None, bkg_trend=None, bkg_level_per_pix=None, 
                   quat_jitter=None, quat_status="not provided", qlp_result=None,
                   quality_flag=None, 
                   target_page_height: float | None = None):
    """
    Unified LC summary figure for both single-sector and multi-sector runs.

    For single-sector calls pass ``median_image``, ``pix_mask``, and
    ``bkg_mask``; the FFI cutout is rendered with a full WCS projection via
    ``plot_cutouts``.  For multi-sector calls leave those three arguments as
    ``None``; the image panel is rendered via ``plot_image`` (which handles
    its own subplot creation from the GridSpec slot).

    All other panels (SAP/PLD/Det/Final LC rows, optional SAP diagnostic
    background + quaternion rows) are identical in both modes.

    Parameters
    ----------
    ID, nearby_star_catalog, Sector, cadence, hdu, RAWLC_df,
    clippedRAWLC_df, LC_df, good_ind_DF, bad_ind_DF, preclipLC_df,
    default_settings
        Same as before.
    median_image : np.ndarray or None
        Median pixel image.  Required for single-sector; pass None for multi.
    pix_mask : np.ndarray or None
        Aperture pixel mask.  Required for single-sector; pass None for multi.
    bkg_mask : np.ndarray or None
        Background pixel mask.  Required for single-sector; pass None for multi.
    magnitude_limit, dot_scale, cbarpad, savefigname
        Plotting cosmetics (ignored for multi-sector where plot_image handles
        magnitude_limit internally).
    bkg_level_per_pix, bkg_trend, bkg_residuals, quat_jitter,
    quat_status, qlp_result, quality_flag
        Optional SAP diagnostics forwarded from SAP() / LC_creation().

    Examples
    --------
    # Single-sector call (backward-compatible with old plot_it_all_up)
    >>> plot_it_all_up(ID, cat, Sector=3, cadence='30 minute', hdu=hdu,
    ...               RAWLC_df=raw, clippedRAWLC_df=clip, LC_df=lc,
    ...               good_ind_DF=g, bad_ind_DF=b, preclipLC_df=pre,
    ...               default_settings=ds,
    ...               median_image=med, pix_mask=pm, bkg_mask=bm)

    # Multi-sector call (backward-compatible with old plot_it_all_up_multi)
    >>> plot_it_all_up(ID, cat, Sector=None, cadence='30 minute', hdu=hdus,
    ...               RAWLC_df=raw, clippedRAWLC_df=clip, LC_df=lc,
    ...               good_ind_DF=g, bad_ind_DF=b, preclipLC_df=pre,
    ...               default_settings=ds)
    """
    # ── imports ───────────────────────────────────────────────────────────────
    import warnings
    import numpy as np
    from astropy.io import fits as _fits
    from astroquery.mast import Catalogs, Tesscut
    from astroquery.gaia import Gaia
    from astroquery.vizier import Vizier
    from matplotlib import pyplot as plt
    from matplotlib.ticker import FormatStrFormatter
    import matplotlib.gridspec as gridspec

    # ── settings ──────────────────────────────────────────────────────────────
    cutoutsize      = default_settings.get('cutoutsize')
    get_all_sectors = default_settings.get('get_all_sectors')
    downloadpath    = default_settings.get('downloadpath')
    savefigpath     = default_settings.get('savefigpath')
    savelcpath      = default_settings.get('savelcpath')
    verbose         = default_settings.get('verbose')
    bkg_sigma_thr   = float(default_settings.get('bkg_threshold_sigma', 5.0))
    quat_sigma_thr  = float(default_settings.get('quat_threshold_sigma', 5.0))

    Tesscut.cache_location  = downloadpath
    Catalogs.cache_location = downloadpath
    Vizier.cache_location   = downloadpath

    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"

    # ── decide single vs multi-sector ─────────────────────────────────────────
    # Single-sector: pix_mask supplied AND hdu is a single HDUList
    _is_single = (
        pix_mask is not None and
        median_image is not None and
        isinstance(hdu, _fits.HDUList)
    )

    # ── stellar parameters ────────────────────────────────────────────────────
    star   = nearby_star_catalog.loc[nearby_star_catalog['ID'] == str(ID)].reset_index(drop=True)
    star   = get_qld(star, verbose)
    R_star = star['rad'].item()
    M_star = star['mass'].item()
    Vmag   = star['Vmag'].item()
    Tmag   = star['Tmag'].item()
    Teff   = star['Teff'].item()

    # ── light curve arrays ────────────────────────────────────────────────────
    rawtime              = RAWLC_df['Time'].to_numpy(dtype=np.float64)
    rawflux              = RAWLC_df['SAP Flux'].to_numpy(dtype=np.float64)
    rawflux_error        = RAWLC_df['SAP Error'].to_numpy(dtype=np.float64)

    clippedrawtime       = clippedRAWLC_df['Time'].to_numpy(dtype=np.float64)
    clippedrawflux       = clippedRAWLC_df['SAP Flux'].to_numpy(dtype=np.float64)
    clippedrawflux_error = clippedRAWLC_df['SAP Error'].to_numpy(dtype=np.float64)

    time             = preclipLC_df['Time'].to_numpy(dtype=np.float64)
    sap_flux         = preclipLC_df['SAP Flux'].to_numpy(dtype=np.float64)
    sap_error        = preclipLC_df['SAP Error'].to_numpy(dtype=np.float64)
    det_error        = preclipLC_df['Detrended Error'].to_numpy(dtype=np.float64)
    pld_error        = preclipLC_df['PLD Error'].to_numpy(dtype=np.float64)
    flux_detrended   = preclipLC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    trend_lc         = preclipLC_df['Fitted Trend'].to_numpy(dtype=np.float64)
    pld_detrended    = preclipLC_df['PLD Flux'].to_numpy(dtype=np.float64)
    pld_model        = preclipLC_df['PLD Model'].to_numpy(dtype=np.float64)

    badtime    = bad_ind_DF['Time'].to_numpy(dtype=np.float64)
    baddetflux = bad_ind_DF['Detrended Flux'].to_numpy(dtype=np.float64)
    goodtime   = good_ind_DF['Time'].to_numpy(dtype=np.float64)
    gooddetflux= good_ind_DF['Detrended Flux'].to_numpy(dtype=np.float64)

    finaltime  = LC_df['Time'].to_numpy(dtype=np.float64)
    finalflux  = LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    finalerror = LC_df['Detrended Error'].to_numpy(dtype=np.float64)

    # ── CDPP ──────────────────────────────────────────────────────────────────
    cad        = np.nanmedian(np.diff(time[np.isfinite(time)]))
    cdpp_sap   = CDPP(clippedrawtime, clippedrawflux, clippedrawflux_error,
                      'median', 'ppm', cad, binsize=1.0/24.0)
    cdpp_det   = CDPP(time, flux_detrended, det_error,
                      'median', 'ppm', cad, binsize=1.0/24.0)
    cdpp_pld   = CDPP(time, pld_detrended, pld_error,
                      'median', 'ppm', cad, binsize=1.0/24.0)
    cdpp_final = CDPP(finaltime, finalflux, finalerror,
                      'median', 'ppm', cad, binsize=1.0/24.0)
    std_sap    = 5 * np.nanstd(clippedrawflux)

    # ── single-sector extras ──────────────────────────────────────────────────
    if _is_single:
        wcs             = check_wcs(hdu)
        col             = hdu[1].header["1CRPX4"]
        row             = hdu[1].header["2CRPX4"]
        reference_pixel = [col, row]
        CCD             = hdu[0].header['CCD']
        Camera          = hdu[0].header['Camera']

    # ── decide whether to draw SAP diagnostic block ───────────────────────────
    _have_bkg  = bkg_level_per_pix is not None
    _have_jit  = quat_jitter is not None
    _have_feat = (qlp_result is not None
                  and qlp_result.get('feature_df') is not None
                  and isinstance(quat_status, str)
                  and quat_status.startswith('used'))
    _add_diag  = _have_bkg or _have_jit or _have_feat

    # ── gridspec layout ───────────────────────────────────────────────────────    
    fig_width = 5
    gutter_col = 2   # index of the narrow spacer column

    if _add_diag:
        n_rows            = 7
        fig_height_inches = 16
        height_ratios     = [2, 2, 1.4, 1, 1, 1, 1]
        row_img           = slice(0, 2)
        row_bkg_ts, row_feat = 2, 0
        row_sap, row_pld, row_det, row_fin = 3, 4, 5, 6
    else:
        n_rows            = 6
        fig_height_inches = 10
        height_ratios     = None           
        row_img           = slice(0, 2)
        row_sap, row_pld, row_det, row_fin = 2, 3, 4, 5
  
    col_widths = [1, 1, 0.15, 1, 1]   # gutter at index 2 (3rd)
    gs1 = gridspec.GridSpec(n_rows, fig_width,
                            height_ratios=height_ratios,
                            width_ratios=col_widths)
    
    fig = plt.figure(figsize=(12, fig_height_inches))

    if _add_diag:
        ax_bkg_ts = fig.add_subplot(gs1[row_bkg_ts, 0:fig_width])
        ax_feat   = fig.add_subplot(gs1[row_feat,   3:fig_width])
        ax_jhist  = fig.add_subplot(gs1[row_feat+1,   3:fig_width])

    ax3 = fig.add_subplot(gs1[row_sap, 0:fig_width])
    ax4 = fig.add_subplot(gs1[row_pld, 0:fig_width])
    ax5 = fig.add_subplot(gs1[row_det, 0:fig_width])
    ax6 = fig.add_subplot(gs1[row_fin, 0:fig_width])

    # ── figure title ──────────────────────────────────────────────────────────
    def _r(N, nd): 
        return np.round(N, nd)

    if _is_single:
        title_str = (
            f"TIC {ID} ; Sector {Sector} ; Camera {Camera} ; CCD {CCD} "
            fr"$R_{{star}}$: {_r(R_star,3)} $R_{{\odot}}$ "
            fr"$M_{{star}}$: {_r(M_star,3)} $M_{{\odot}}$"
            f" ; Teff {_r(Teff,3)} K ; "
            f"Tmag {_r(Tmag,3)} ; Vmag {_r(Vmag,3)}"
        )
    else:
        title_str = (
            f"TIC {ID} Multi-Sector Light Curve "
            fr"$R_{{star}}$: {_r(R_star,3)} $R_{{\odot}}$ ; "
            fr"$M_{{star}}$: {_r(M_star,3)} $M_{{\odot}}$"
            f" ; Teff {_r(Teff,3)} K ; "
            f"Tmag {_r(Tmag,3)} ; Vmag {_r(Vmag,3)}"
        )

    fig.suptitle(title_str, fontsize=fs, x=0.5, y=1.0)
    # ── legend placement cosmetics (layout-only tweak) ──────────────────────
    legend_anchor_x = 1.035
    legend_right_margin = 0.77

    def _legend_outside(ax, vertical='center', **kwargs):
        """Place a 1-column legend just outside the axes with extra right padding."""
        handles, labels = ax.get_legend_handles_labels()
        if len(handles) == 0:
            return None
        if vertical == 'upper':
            loc = 'upper left'
            anchor = (legend_anchor_x, 1.0)
        else:
            loc = 'center left'
            anchor = (legend_anchor_x, 0.5)
        return ax.legend(
            handles,
            labels,
            loc=loc,
            bbox_to_anchor=anchor,
            bbox_transform=ax.transAxes,
            borderaxespad=0.0,
            ncol=1,
            **kwargs,
        )
    #
    #
    #
    if _is_single:
        wcs  = check_wcs(hdu)
        ax1  = fig.add_subplot(gs1[row_img, 0:2], projection=wcs)

        catalog_source = default_settings.get('plot_catalog_source', 'TIC')

        # Normalise masks: _run_cutouts_ALT expects a 2-D array, not 3-D.
        pm = pix_mask[0] if (pix_mask is not None and np.ndim(pix_mask) == 3) else pix_mask
        bm = bkg_mask[0] if (bkg_mask is not None and np.ndim(bkg_mask) == 3) else bkg_mask

        try:
            ref_px = get_tess_reference_pixel(hdu[1].header)
        except Exception:
            ref_px = [5.5, 5.5]

        ax1.set_title("FFI Cutout", fontsize=fs)

        _run_cutouts_ALT(
            ID, nearby_star_catalog, Sector, cadence, hdu,
            pm, bm, ref_px,
            4, fig, ax1, cbarpad, default_settings,
            catalog_source, draw_legend=True,
        )

    else:
        _sectors_for_img = Sector
        #
        ax1 = plot_image(              # capture returned axis
            ID, nearby_star_catalog, hdu, _sectors_for_img, cadence,
            gs1[row_img, 0:2], fig, fs, ncols=4, cbarpad=0,
            default_settings=default_settings,
        )

        # Compact post-formatting for the summary figure.
        # The WCS projection is already applied inside plot_image;
        # we only tighten label density here.
        if ax1 is not None:
            try:
                ax1.coords[0].set_ticks(number=3)     # RA:  ~3 tick marks
                ax1.coords[1].set_ticks(number=3)     # DEC: ~3 tick marks
                ax1.coords[0].ticklabels.set_fontsize(fs - 4)
                ax1.coords[1].ticklabels.set_fontsize(fs - 4)
                ax1.coords[0].set_axislabel('RA',  fontsize=fs - 3, minpad=1)
                ax1.coords[1].set_axislabel('DEC', fontsize=fs - 3, minpad=1)
            except Exception:
                pass   # never let cosmetic formatting kill the figure

    # =========================================================================
    # SAP DIAGNOSTIC PANELS (shared, identical for both modes)
    # =========================================================================
    def _display_cat(flag_arr: np.ndarray) -> np.ndarray:
            """
            Map each cadence's bitmask to a single display category.
            Priority (high→low): quat(1) > bkg(2) > centroid(3) > outlier(4) > clean(0).
            Combined flags (e.g. FLAG=3 = quat+bkg) show under the highest-priority category.
            """
            cat = np.zeros(len(flag_arr), dtype=int)
            # Apply lowest-priority first; higher-priority overwrites.
            cat[(flag_arr & int(QUALITY_FLAG_BITS[4])) != 0] = 4  # outlier
            cat[(flag_arr & int(QUALITY_FLAG_BITS[3])) != 0] = 3  # centroid
            cat[(flag_arr & int(QUALITY_FLAG_BITS[2])) != 0] = 2  # background
            cat[(flag_arr & int(QUALITY_FLAG_BITS[1])) != 0] = 1  # quat jitter
            return cat
        
    if _add_diag:
        # ── flag colour / shape / size palette ────────────────────────────────
        # Good cadences are light grey (small, background layer) so the rarer
        # flagged categories are visually prominent on top.
        _FLAG_COLOR  = {0: 'silver',     1: 'darkorange', 2: 'crimson',
                        3: 'dodgerblue', 4: 'mediumpurple'}
        _FLAG_MARKER = {0: '.',          1: '^',           2: 'D',
                        3: 's',          4: 'X'}
        _FLAG_SIZE   = {0: 2**2,         1: 5**2,          2: 4**2,
                        3: 4**2,         4: 5**2}
        _FLAG_ALPHA  = {0: 0.35,         1: 0.90,          2: 0.90,
                        3: 0.75,         4: 0.90}
        _FLAG_ZORDER = {0: 1,            1: 5,             2: 4,
                        3: 3,            4: 6}
        _FLAG_LABEL  = {
            0: 'Good',
            1: 'Quat jitter',
            2: 'Bkg spike',       # was 'Bkg/Cent'
            3: 'Centroid',        # NEW
            4: 'Outlier',         # was category 3
        }

        qflag = (
            quality_flag
            if (quality_flag is not None and len(quality_flag) == len(rawtime))
            else np.zeros(len(rawtime), dtype=int)
        )
        
        disp_cat = _display_cat(qflag)   # one display category per cadence

        # Panel A — background time series
        if _have_bkg and len(bkg_level_per_pix) == len(rawtime):
            srt = np.argsort(rawtime)

            # Plot FLAG=0 (good) first as the background layer, then each
            # flagged category on top in zorder order so they are never buried.
            for fval in sorted(_FLAG_COLOR, key=lambda k: _FLAG_ZORDER[k]):
                sel = (disp_cat == fval)  # ← bitmask-safe, was: qflag == fval
                if not sel.any():
                    continue
                ax_bkg_ts.scatter(
                    rawtime[sel], bkg_level_per_pix[sel],
                    s=_FLAG_SIZE[fval],
                    c=_FLAG_COLOR[fval],
                    marker=_FLAG_MARKER[fval],
                    alpha=_FLAG_ALPHA[fval],
                    linewidths=0,
                    zorder=_FLAG_ZORDER[fval],
                    label=_FLAG_LABEL[fval],
                )

            if bkg_trend is not None and len(bkg_trend) == len(rawtime):
                ax_bkg_ts.plot(
                    rawtime[srt], bkg_trend[srt],
                    color='steelblue', lw=1.2, zorder=6,
                    label='Biweight trend',
                )
        else:
            ax_bkg_ts.text(
                0.5, 0.5, 'Background data not supplied',
                ha='center', va='center', transform=ax_bkg_ts.transAxes,
                fontsize=10, color='0.5', style='italic',
            )

        ax_bkg_ts.set_ylabel('Bkg (e⁻/s/pix)', fontsize=fs)
        ax_bkg_ts.set_xlim(np.nanmin(rawtime) - 1, np.nanmax(rawtime) + 1)
        ax_bkg_ts.set_yscale('log')
        ax_bkg_ts.tick_params(axis='both', labelsize=fs - 8)
        _legend_outside(ax_bkg_ts, vertical='center', framealpha=0.8)
        ax_bkg_ts.tick_params(axis='both', labelsize=fs - 8)
        ax_bkg_ts.set_yscale('log')

        # Panel B-left — quaternion feature heatmap
        if _have_feat:
            feat_df   = qlp_result['feature_df']
            feat_cols = qlp_result['feature_cols']
            t_feat    = feat_df['time'].values
            feat_arr  = feat_df[feat_cols].values.T
            im = ax_feat.imshow(feat_arr, aspect='auto', cmap='RdBu_r',
                                vmin=-3, vmax=3,
                                extent=[t_feat.min(), t_feat.max(), 36, 0],
                                interpolation='nearest', origin='upper')
            cb = fig.colorbar(im, ax=ax_feat, pad=0.01, fraction=0.04)
            cb.set_label('Norm. value (σ)', fontsize=fs,rotation=270,labelpad=15)
            cb.ax.tick_params(labelsize=fs)
            
            for yd in [9, 18]:
                ax_feat.axhline(yd, color='k', lw=0.8, ls='--', alpha=0.5)
            ax_feat.set_ylabel('Feature index', fontsize=fs)
            ax_feat.set_xlabel('Time (BTJD)', fontsize=fs,labelpad=2)
            ax_feat.invert_yaxis()
            ax_feat.set_yticks([0, 9, 18, 36])
            ax_feat.tick_params(axis='both', labelsize=fs)
            ax_feat.set_title('36 normalized quaternion features',
                              fontsize=fs)
            ax_feat.set_xlim(ax_bkg_ts.get_xlim())
        else:
            ax_feat.axis('off')
            ax_feat.text(0.5, 0.5, f'Quaternion features not computed\n({quat_status[:70]})',
                         ha='center', va='center', transform=ax_feat.transAxes,
                         fontsize=fs, color='0.5', style='italic',
                         bbox=dict(boxstyle='round', fc='lightyellow', ec='0.7'))
            ax_feat.set_title('36 quaternion features [not computed]', fontsize=fs)
        #
        # Panel B-right — jitter histogram
        if _have_jit:
            jitter_arr = np.asarray(quat_jitter, dtype=float)

            _qf = (
                np.asarray(quality_flag, dtype=int)
                if quality_flag is not None and len(quality_flag) == len(rawtime)
                else np.zeros(len(rawtime), dtype=int)
            )

            # ── per-sector sigma normalisation ────────────────────────────────
            # Iterate over the known sector timing table; for each sector that
            # overlaps with rawtime, compute that sector's own median/MAD and
            # express every cadence in that sector as a sigma value.
            # Cadences not matched to any sector are left as NaN (excluded from
            # the histogram but still carry their FLAG status).

            t_arr = np.asarray(rawtime, dtype=float)
            jitter_sigma_ps = np.full(len(t_arr), np.nan)   # per-sector sigma

            _t_finite = t_arr[np.isfinite(t_arr)]
            if len(_t_finite) > 0:
                _t_lo, _t_hi = float(_t_finite.min()), float(_t_finite.max())
            else:
                _t_lo, _t_hi = 0.0, 0.0

            for _sec in range(1, 110):      # 110 covers all sectors in the table
                try:
                    _t0, _, _, _t1 = TESS_Sector_observation_check(SectorNum=_sec)
                except ValueError:
                    break                   # beyond the last entry in the table
                except Exception:
                    continue

                if _t1 < _t_lo or _t0 > _t_hi:
                    continue               # sector not present in this LC

                _sec_mask = (
                    (t_arr >= _t0) & (t_arr <= _t1)
                    & np.isfinite(jitter_arr)
                )
                if _sec_mask.sum() < 5:
                    continue

                _j_sec = jitter_arr[_sec_mask]
                _med   = np.nanmedian(_j_sec)
                _mad   = np.nanmedian(np.abs(_j_sec - _med)) * 1.4826

                if _mad > 0 and np.isfinite(_mad):
                    jitter_sigma_ps[_sec_mask] = (_j_sec - _med) / _mad
                else:
                    # Degenerate sector (all jitter identical); set to 0
                    jitter_sigma_ps[_sec_mask] = 0.0

            # ── histogram ────────────────────────────────────────────────────
            _finite_mask = np.isfinite(jitter_sigma_ps)
            finite_sigma = jitter_sigma_ps[_finite_mask]

            if len(finite_sigma) >= 5:
                ax_jhist.hist(
                    finite_sigma,
                    bins=60,
                    color='steelblue',
                    alpha=0.7,
                    edgecolor='none',
                    label='All cadences',
                )

                # FLAG=1 overlay — flagged points are guaranteed to sit to the
                # right of quat_sigma_thr because jitter_sigma_ps was computed
                # with the same per-sector normalisation SAP() used.
                _flag1_mask  = (_qf == 1) & _finite_mask
                flag1_sigma  = jitter_sigma_ps[_flag1_mask]
                n_flag1      = int(_flag1_mask.sum())

                if n_flag1 > 0:
                    ax_jhist.hist(
                        flag1_sigma,
                        bins=60,
                        color='darkorange',
                        alpha=0.85,
                        edgecolor='none',
                        label=f'FLAG=1 ({n_flag1})',
                    )

                ax_jhist.axvline(
                    quat_sigma_thr,
                    color='red', lw=1.5, ls='--',
                    label=f'Threshold ({quat_sigma_thr:.1f}'+r'$\sigma$)',
                )
                ax_jhist.axvline(
                    0.0, color='k', lw=1.0, ls=':',
                    label='Per-sector median',
                )
                ax_jhist.set_xlabel(
                    'Quaternion scalar (per-sector '+r'$\sigma$ units)', fontsize=fs,
                labelpad=2)
                ax_jhist.set_yscale('log')

                # Warn if any FLAG=1 point falls below threshold (should not happen)
                if n_flag1 > 0 and np.any(flag1_sigma <= quat_sigma_thr):
                    n_below = int(np.sum(flag1_sigma <= quat_sigma_thr))
                    ax_jhist.text(
                        0.03, 0.97,
                        f'{n_below} FLAG=1 cadence(s) below threshold\n'
                        '(sector boundary overlap?)',
                        ha='left', va='top', transform=ax_jhist.transAxes,
                        fontsize=max(fs - 4, 6), color='red',
                        bbox=dict(boxstyle='round,pad=0.2', fc='lightyellow',
                                  ec='0.7', alpha=0.85),
                    )

            else:
                ax_jhist.text(
                    0.5, 0.5, 'Insufficient jitter samples',
                    ha='center', va='center',
                    transform=ax_jhist.transAxes,
                    fontsize=fs, color='0.5',
                )
                ax_jhist.set_xlabel('Quaternion Jitter scalar', fontsize=fs)

            ax_jhist.set_ylabel('N cadences', fontsize=fs)
            ax_jhist.tick_params(axis='both', labelsize=fs)
            _legend_outside(ax_jhist, vertical='center')
    #
    # =========================================================================
    # LC PANELS ax3 – ax6  (identical for single and multi)
    # =========================================================================
    ax3.set_title("Simple Aperture Photometry (SAP) Light Curve and PLD Noise Model",
                  fontsize=fs)
    #
    _n_raw = len(rawtime)

    # source (a): quality flag
    if quality_flag is not None and len(quality_flag) == _n_raw:
        # _qf_mask = quality_flag != 0 #OLD
        _qf_mask = (quality_flag & int(_FLUX_CORRUPT_MASK)) != 0
    elif 'QUALITY_FLAG' in RAWLC_df.columns:
        _qf_mask = RAWLC_df['QUALITY_FLAG'].to_numpy(dtype=int) != 0
    else:
        _qf_mask = np.zeros(_n_raw, dtype=bool)

    # source (b): sector-jitter / mdump cadences — detected via a non-preserved
    # column that is NaN at those positions in the restored full-length CSV.
    # 'Background Flux' is a reliable sentinel: it is not in preserve_columns
    # inside _restore_full_length_lc, so it is NaN for all non-good cadences.
    if 'Background Flux' in clippedRAWLC_df.columns:
        _bkg_col = clippedRAWLC_df['Background Flux'].to_numpy(dtype=float)
        _sector_jitter_mask = ~np.isfinite(_bkg_col)
    else:
        # Fallback: compare timestamps (works when clippedRAWLC_df is still
        # the compact row-subsetted version rather than the full-length one).
        _clipped_set = set(np.round(clippedrawtime, decimals=6))
        _sector_jitter_mask = np.array(
            [np.round(t, 6) not in _clipped_set for t in rawtime],
            dtype=bool, )

    _all_masked = _qf_mask | _sector_jitter_mask   # any-source mask
    _good_raw   = ~_all_masked

    # ── ax3: grey = masked cadences, black = clean cadences ──────────────────
    ax3.set_title(
        "Simple Aperture Photometry (SAP) Light Curve and PLD Noise Model",
        fontsize=fs )

    if _all_masked.any():
        ax3.plot( rawtime[_all_masked], rawflux[_all_masked],
                 marker='.', color='grey', linestyle='none',
                 label='jitter/glare/Mdumps', zorder=-100 )

    ax3.plot( rawtime[_good_raw], rawflux[_good_raw],
             marker='.', color='black', linestyle='none',
             label=(
                 f' SAP Flux \n CDPP: {cdpp_sap:.0f}'
                 + r' $\sigma _{ppm}$ hr$^{-1/2}$' ), zorder=-99 )
    #
    ax3.scatter(time, pld_model, color='yellow', label='PLD model', s=2**2)

    ax4.set_title("PLD Corrected Light Curve with Fitted Trend Line", fontsize=fs)
    ax4.plot(time, pld_detrended, "k.",
             label=f' PLD Flux \n CDPP: {cdpp_pld:.0f}' + r' $\sigma _{ppm}$ hr$^{-1/2}$',
             zorder=-100)
    ax4.scatter(time, trend_lc, color='orange', label='Fitted trend', s=2**2)

    ax5.set_title("PLD Corrected and Smoothed Light Curve", fontsize=fs)
    ax5.plot(time, flux_detrended, "k.",
             label=f' Detrended Flux \n CDPP: {cdpp_det:.0f}' + r' $\sigma _{ppm}$ hr$^{-1/2}$',
             zorder=-100)

    ax6.set_title("PLD Corrected, Smoothed and Outlier Removed Light Curve", fontsize=fs)
    ax6.plot(finaltime, finalflux, "k.",
             label=f' Final Flux \n CDPP: {cdpp_final:.0f}' + r' $\sigma _{ppm}$ hr$^{-1/2}$',
             zorder=-100)

    ax5.plot(badtime,  baddetflux,  'r.', zorder=2, label='bad outliers')
    ax5.plot(goodtime, gooddetflux, 'g.', zorder=2, label='good outliers')

    # momentum dump markers
    try:
        hdu_list = hdu if isinstance(hdu, list) else [hdu]
        for h in hdu_list:
            if h is None:
                continue
            for t_md in get_momentum_dump_times(h):
                for ax_lc in [ax3, ax4, ax5, ax6]:
                    ax_lc.axvline(x=t_md, zorder=-2)
    except Exception:
        pass
    print('')

    # shared axis formatting
    for ax_ in [ax_bkg_ts, ax_jhist, ax_feat]:
        ax_.tick_params(axis='both', which='major', labelsize=fs)
        ax_.tick_params(axis='both', which='minor', labelsize=fs)
    #
    for ax_lc in [ax3, ax4, ax5, ax6]:
        if ax_lc==ax6:
            ax_lc.set_xlabel("Time (BTJD)", fontsize=fs)
        ax_lc.set_xlim(np.min(rawtime) - 1, np.max(rawtime) + 1)
        ax_lc.yaxis.set_major_formatter(FormatStrFormatter('%.4f'))
        ax_lc.tick_params(axis='both', which='major', labelsize=fs)
        ax_lc.tick_params(axis='both', which='minor', labelsize=fs)
        #ax_lc.legend(bbox_to_anchor=(1, 1), loc=2, borderaxespad=0.1,)        
        _legend_outside(ax_lc, vertical='center')
    ax4.set_ylabel("Normalized Relative flux ", fontsize=fs)
    
    
    # ── helper: robust ylim from a 1-D flux array ─────────────────────────────
    def _ylim(flux_arr, n_sig=5.0):
        """median ± n_sig * nanstd, guarded against degenerate arrays."""
        finite = flux_arr[np.isfinite(flux_arr)]
        if len(finite) < 5:
            return None, None
        med = float(np.nanmedian(finite))
        sig = float(np.nanstd(finite))
        if sig == 0 or not np.isfinite(sig):
            return None, None
        return med - n_sig * sig, med + n_sig * sig
    #
    # ── ax3: SAP flux (clipped raw, momentum-dump-removed) ────────────────────
    ylo, yhi = _ylim(clippedrawflux,n_sig=3.0)
    if ylo is not None:
        ax3.set_ylim(ylo, yhi)

    # ── ax4: PLD flux + trend ─────────────────────────────────────────────────
    ylo, yhi = _ylim(finalflux)
    if ylo is not None:
        ax4.set_ylim(ylo, yhi)

    # ── ax5: detrended flux (pre-outlier-removal) ─────────────────────────────
    if ylo is not None:
        ax5.set_ylim(ylo, yhi)

    # ── ax6: final flux (post-outlier-removal) ────────────────────────────────
    if ylo is not None:
        ax6.set_ylim(ylo, yhi)    

    # ── save ─────────────────────────────────────────────────────────────────
    _save_h = float(target_page_height) if target_page_height is not None \
              else float(fig_height_inches)
    gs1.update(left=0.15, right=0.7, top=0.9, bottom=0.15, wspace=0.5, hspace=0.8)
    
    gs1.tight_layout(fig, pad=1)
    fig.set_size_inches(12, _save_h)
    
    for ax_ in [ax_feat, ax_jhist]:
        pos = ax_.get_position()
        ax_.set_position([pos.x0, pos.y0 + 0.01, pos.width, pos.height*0.95])
    # After gs1.update(), nudge ax3-ax6 apart by shrinking their heights slightly
    # and shifting them down incrementally.
    for i, ax_lc in enumerate([ax3, ax4, ax5, ax6]):
        pos = ax_lc.get_position()
        ax_lc.set_position([pos.x0, pos.y0 - i * 0.01, pos.width, pos.height * 0.95])
    
    if savefigname is None:
        if _is_single:
            savefigname = savefigpath + f"TIC_{ID}_{sector_tag}_LC_summary.png"
        else:
            savefigname = savefigpath + f"TIC_{ID}_Multi_Sector_LC_summary.png"
        fig.savefig(savefigname, bbox_inches='tight')
    else:
        fig.savefig(savefigname, bbox_inches='tight')

    plt.close()
