def generate_injection_path(Sector, default_settings):
    """
    Generates the appropriate file path based on the given parameters.

    Parameters:
        path (str): Base directory path.
        Sector (int, list, or None): Sector number(s) (if applicable).
        get_all_sectors (bool): Whether to retrieve all sectors.
        inject_param_P_RP_T0 (tuple): (Period, R_planet_RE, T0) values for injection mode.
        for_injections (bool): Whether this is for an injection scenario.

    Returns:
        str: Generated path.
    """
    # get function settings
    path = default_settings.get('path')
    get_all_sectors = default_settings.get('get_all_sectors')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    for_injections = default_settings.get('for_injections')
    
    if Sector is None:
        get_all_sectors = True
        
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"        

    # Default to input path
    Path = path  

    # Append "Sector_X" or "Multi_Sector" only if not already in path
    if "Sector_" not in path and "Multi_Sector" not in path:
        if isinstance(Sector, int):  # Single sector case
            Path = os.path.join(path, f"{sector_tag}/")
        elif get_all_sectors or Sector is None or isinstance(Sector, list):  # Multiple sectors case
            Path = os.path.join(path, "Multi_Sector/")

    # Append injection parameters if for_injections is True and not already in Path
    if for_injections==True:
        Period, R_planet_RE, T0 = inject_param_P_RP_T0
        injection_string = f"Period_{np.round(Period,2)}_RP_{np.round(R_planet_RE,2)}/"
        
        if injection_string not in Path:  # Prevents duplicate injection parameter paths
            Path = os.path.join(Path, injection_string)

    return Path
#
#
#
def transit_injection(input_LC, Period, T0, ID, nearby_star_catalog, Sector,
                      default_settings,
                      R_planet_RE=None, transit_depth=None,
                      flux_contamination_ratio=0.0,
                      inclination=90, eccentricity=0, ang_periastron=90):
    """
    Inject a limb-darkened transit into a TESS-like light curve using BATMAN.

    The function either uses a specified planet radius (`R_planet_RE`), or
    derives it from a given transit depth (`transit_depth``).  Once the
    planet parameters are established, it builds a BATMAN transit model and
    injects the synthetic transit signal into the input light curve.

    **Dilution-aware injection (V1.96):**  When ``flux_contamination_ratio``
    is non-zero the injection accounts for the fact that only the target
    star transits.  The raw aperture flux ``F`` contains both the target
    and contaminating sources, so a physically correct transit produces::

        F_transit = F_target * (1 - delta) + F_contam
                  = F * [(1 - fcr) * model + fcr]

    where ``fcr = flux_contamination_ratio`` and ``model`` is the BATMAN
    light curve.  Setting ``fcr = 0`` recovers the original multiplicative
    injection ``F * model``.

    **Depth recording (V1.96):**  Two depth values are saved:

    * ``Injected Depth (geometric)`` = (Rp/Rs)^2, the limb-darkening-free
      geometric depth.  Useful for verifying the injection setup.
    * ``Injected Depth (model)`` = 1 - min(synthetic_signal), the actual
      mid-transit depth of the BATMAN model including limb darkening and
      cadence-averaged supersampling.  This is the depth that BLS/TLS
      should recover (before any pipeline processing).

    For injection-recovery comparisons, use ``Injected Depth (model)``
    to avoid the systematic LD-enhancement bias when comparing against
    BLS/TLS box-fit depths.

    Parameters
    ----------
    input_LC : pandas.DataFrame
        Input light curve with at least columns
        ``'Time'``, ``'SAP Flux'``, ``'SAP Error'``.
    Period : float
        Orbital period of the injected transit (days).
    T0 : float
        Mid-transit time (BJD / BTJD).  If earlier than the first
        timestamp, it is advanced by integer periods until it falls
        within the data range.
    ID : int or str
        TIC identifier matching a row in *nearby_star_catalog*.
    nearby_star_catalog : pandas.DataFrame
        Must contain columns ``'ID'``, ``'rad'``, ``'mass'``,
        ``'qld_a'``, ``'qld_b'``.
    Sector : int
        TESS sector number (bookkeeping only).
    default_settings : dict
        Pipeline settings dictionary.
    R_planet_RE : float or None, optional
        Planet radius in Earth radii.  One of *R_planet_RE* or
        *transit_depth* must be provided.
    transit_depth : float or None, optional
        Fractional transit depth (e.g. 0.0001 for 100 ppm).  Used to
        derive *R_planet_RE* if the latter is ``None``.
    flux_contamination_ratio : float, optional
        Fraction of the total aperture flux contributed by neighboring
        sources (``F_contam / F_total``).  Default is 0.0 (no
        contamination), which reproduces the pre-V1.96 behaviour.
        Computed by ``calc_flux_contamination`` inside SAP.
    inclination : float, optional
        Orbital inclination in degrees.  Default 90 (edge-on).
    eccentricity : float, optional
        Orbital eccentricity.  Default 0 (circular).
    ang_periastron : float, optional
        Argument of periastron in degrees.  Default 90.

    Returns
    -------
    inj_LC : pandas.DataFrame
        Copy of the input light curve with the injected transit:
        ``'Time'``, ``'SAP Flux'``, ``'SAP Error'``,
        ``'Injected Model'``.
    inj_params : pandas.DataFrame
        Single-row DataFrame of injected parameters:
        ``'Period'``, ``'T0'``, ``'Planet Radius [RS]'``,
        ``'Injected Radius'``, ``'Injected Depth (geometric)'``,
        ``'Injected Depth (model)'``, ``'SMA [RS]'``,
        ``'flux_contamination_ratio'``, ``'qld_a'``, ``'qld_b'``.

    Raises
    ------
    ValueError
        If neither *R_planet_RE* nor *transit_depth* is provided.

    Notes
    -----
    - Supersampling factor is set to 20 for cadences > 10 min, 10
      otherwise.
    - Limb-darkening coefficients are drawn from the ``qld_a`` / ``qld_b``
      columns of *nearby_star_catalog* (Claret 2017 quadratic law).
    - The ``flux_contamination_ratio`` and LD coefficients are recorded in
      *inj_params* so downstream analysis can audit the dilution and LD
      correction budgets.

    Example
    -------
    >>> inj_lc, inj_params = transit_injection(
    ...     input_LC=df_lc, Period=3.0, T0=1337.5, ID=123456,
    ...     nearby_star_catalog=df_star, Sector=3,
    ...     default_settings=settings, R_planet_RE=2.0,
    ...     flux_contamination_ratio=0.12,
    ... )
    >>> # Compare these two depths to quantify the LD enhancement:
    >>> print(inj_params[['Injected Depth (geometric)',
    ...                    'Injected Depth (model)']].to_string())
    """
    import numpy as np
    import pandas as pd
    import batman
    from astropy import units as u

    # -- unpack settings -----------------------------------------------------
    verbose = default_settings.get('verbose', False)
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')

    # -- arrays --------------------------------------------------------------
    T = input_LC['Time'].to_numpy(dtype=np.float64)
    F = input_LC['SAP Flux'].to_numpy(dtype=np.float64)
    E = input_LC['SAP Error'].to_numpy(dtype=np.float64)
    texp = np.nanmedian(np.diff(T))

    # -- stellar parameters --------------------------------------------------
    star = nearby_star_catalog.loc[
        nearby_star_catalog['ID'] == str(ID)
    ].reset_index(drop=True)
    star = get_qld(star, verbose)
    qld_a  = star['qld_a'].item()
    qld_b  = star['qld_b'].item()
    R_star = star['rad'].item()    # R_sun
    M_star = star['mass'].item()   # M_sun

    # -- unit conversions ----------------------------------------------------
    RS = u.R_sun.to(u.cm)
    RE = u.R_earth.to(u.cm)

    # -- helper: geometric depth <-> radius ----------------------------------
    def expected_transit_depth(RP_RE: float, R_star_Rsun: float) -> float:
        """(Rp/Rs)^2 -- uniform-disk geometric depth."""
        return ((RP_RE * RE) / (R_star_Rsun * RS)) ** 2

    def planet_radius_from_depth(depth: float, R_star_Rsun: float) -> float:
        """Planet radius [R_earth] from geometric depth and Rs [R_sun]."""
        return (R_star_Rsun * RS * np.sqrt(depth)) / RE

    # -- resolve radius / depth ----------------------------------------------
    if R_planet_RE is None and transit_depth is not None:
        R_planet_RE = planet_radius_from_depth(transit_depth, R_star)
        if verbose:
            print(f"Derived planet radius: {R_planet_RE:.3f} R_earth "
                  f"from depth {transit_depth:.1e}")
    elif R_planet_RE is None:
        raise ValueError("Either R_planet_RE or transit_depth must be provided.")

    if R_planet_RE is not None and transit_depth is None:
        transit_depth = expected_transit_depth(R_planet_RE, R_star)

    # -- advance T0 into the data range --------------------------------------
    time_start = T0 + np.ceil((np.nanmin(T) - T0) / Period) * Period

    # -- semi-major axis -----------------------------------------------------
    SMA, SMA_cm = calculate_semi_major_axis(
        Period=Period * u.day,
        R_star=R_star * u.R_sun,
        M_star=M_star * u.M_sun,
    )

    # -- BATMAN model --------------------------------------------------------
    ma           = batman.TransitParams()
    ma.t0        = time_start
    ma.per       = Period
    ma.rp        = (R_planet_RE * RE) / (R_star * RS)
    ma.a         = SMA
    ma.inc       = inclination
    ma.ecc       = eccentricity
    ma.w         = ang_periastron
    ma.u         = [qld_a, qld_b]
    ma.limb_dark = "quadratic"

    import astropy.units as units
    ssf = 20 if (texp * units.day).to(units.minute).value > 10 else 10
    m = batman.TransitModel(ma, T, supersample_factor=ssf, exp_time=texp)
    synthetic_signal = m.light_curve(ma)   # 1.0 OOT, < 1.0 in transit

    # -- actual model depth (includes LD + cadence averaging) ----------------
    model_depth = float(1.0 - np.nanmin(synthetic_signal))

    if verbose:
        ld_mean_intensity = 1.0 - qld_a / 3.0 - qld_b / 6.0
        ld_enhancement    = 1.0 / ld_mean_intensity if ld_mean_intensity > 0 else 1.0
        print(f"  LD coefficients: u1={qld_a:.4f}, u2={qld_b:.4f}")
        print(f"  Geometric depth (Rp/Rs)^2 = {transit_depth:.6f} "
              f"({transit_depth * 1e3:.2f} ppt)")
        print(f"  Model depth (incl. LD)    = {model_depth:.6f} "
              f"({model_depth * 1e3:.2f} ppt)")
        print(f"  LD enhancement factor     = {model_depth / transit_depth:.3f} "
              f"(analytic center-of-disk = {ld_enhancement:.3f})")

    # -- dilution-aware injection --------------------------------------------
    # Physical model:
    #   F_transit = F_target*(1-delta) + F_contam
    #             = F_total * [(1 - fcr)*model + fcr]
    #
    # When fcr = 0 this reduces to F * model (original behaviour).
    fcr = float(flux_contamination_ratio)
    fcr = np.clip(fcr, 0.0, 1.0)
    injectedflux = F * ((1.0 - fcr) * synthetic_signal + fcr)

    if verbose and fcr > 0:
        print(f"  Dilution-aware injection: fcr={fcr:.4f}, "
              f"depth inflation avoided = {1.0 / (1.0 - fcr) - 1.0:.1%}")

    # -- output --------------------------------------------------------------
    inj_LC = pd.DataFrame({
        'Time':           T,
        'SAP Flux':       injectedflux,
        'SAP Error':      E,
        'Injected Model': synthetic_signal,
    })

    Ndigits = 32
    inj_params = pd.DataFrame({
        'Period':                       np.round(ma.per, Ndigits),
        'T0':                           np.round(ma.t0, Ndigits),
        'Planet Radius [RS]':           np.round(ma.rp, Ndigits),
        'Injected Radius':              np.round(R_planet_RE, Ndigits),
        'Injected Depth (geometric)':   np.round(transit_depth, Ndigits),
        'Injected Depth (model)':       np.round(model_depth, Ndigits),
        'SMA [RS]':                     np.round(ma.a, Ndigits),
        'flux_contamination_ratio':     np.round(fcr, Ndigits),
        'qld_a':                        np.round(qld_a, 8),
        'qld_b':                        np.round(qld_b, 8),
    }, index=[0])

    return inj_LC, inj_params
