# FOR SCRAMBLE TEST
def scramble_hdu_orbits(
    hdu,
    Sector: int,
    verbose: bool = True,
) -> None:
    """
    Swap the two TESS orbit image-frame blocks within a single-sector HDU,
    preserving the original time array.

    This is the principled insertion point for the scramble test: by swapping
    frames at the image level *before* SAP extraction, everything downstream
    (SAP flux, PLD pixel regressors, centroids, backgrounds) is automatically
    scrambled in a self-consistent manner.  PLD will fit to scrambled pixel
    context, producing a scrambled PLD model, which is what Kunimoto et al.
    2025 intend by "detrended, searched, and re-detrended using the same
    procedure as the original data."

    Orbit boundaries are taken from ``TESS_Sector_observation_check`` (TESS
    Data Release Notes), not inferred from time gaps, so they are reliable
    regardless of quality masking or missing cadences.

    For unequal-length orbits (common in early sectors due to spacecraft
    anomalies), only ``min(n_orbit1, n_orbit2)`` frames are swapped.  Excess
    frames in the longer orbit are set to NaN in the FLUX/FLUX_ERR columns,
    which downstream SAP/PLD will handle as missing data.

    Parameters
    ----------
    hdu : astropy.io.fits.HDUList
        Single-sector TESScut or TPF HDU.  Modified **in-place**: the
        ``FLUX`` and ``FLUX_ERR`` columns in ``hdu[1].data`` are
        overwritten with scrambled values.
    Sector : int
        TESS sector number (used to look up orbit boundaries).
    verbose : bool
        Print orbit statistics and swap diagnostics.

    Returns
    -------
    None
        The HDU is modified in-place.

    Notes
    -----
    Call this inside ``get_LC_from_FFI``, after the HDU is received but
    before SAP extraction, gated by ``default_settings.get('scramble_orbits', False)``.

    The QUALITY column is NOT scrambled because quality flags are
    time-specific (momentum dumps, scattered light at specific epochs)
    and should remain attached to their original timestamps.

    Examples
    --------
    >>> # Inside get_LC_from_FFI, before SAP:
    >>> if default_settings.get('scramble_orbits', False):
    ...     scramble_hdu_orbits(hdu, Sector, verbose=verbose)
    """
    import numpy as np

    # ── Orbit boundaries from TESS Data Release Notes ─────────────────────
    orbit1_start, orbit1_stop, orbit2_start, orbit2_stop = \
        TESS_Sector_observation_check(SectorNum=Sector)

    time = hdu[1].data['TIME']
    n_total = len(time)

    # Split cadences into orbit 1 and orbit 2 using the mid-gap timestamp
    # (midpoint of the perigee passage between the two orbits)
    mid_gap = 0.5 * (orbit1_stop + orbit2_start)
    idx_o1 = np.where(time <= mid_gap)[0]
    idx_o2 = np.where(time > mid_gap)[0]

    n1 = len(idx_o1)
    n2 = len(idx_o2)

    if n1 == 0 or n2 == 0:
        if verbose:
            print(f"[scramble_hdu_orbits] WARNING: Sector {Sector} has "
                  f"orbit 1={n1}, orbit 2={n2} frames. Cannot scramble.")
        return

    n_swap = min(n1, n2)

    if verbose:
        print(f"\n  ===== Orbit Scrambling =====")
        print(f"  Sector {Sector} orbit boundaries (DRN):")
        print(f"    Orbit 1: [{orbit1_start:.4f}, {orbit1_stop:.4f}] BTJD")
        print(f"    Orbit 2: [{orbit2_start:.4f}, {orbit2_stop:.4f}] BTJD")
        print(f"  Cadences in orbit 1: {n1}, orbit 2: {n2}")
        print(f"  Swapping {n_swap} frames per orbit block")
        if abs(n1 - n2) > 0:
            print(f"  |n1 - n2| = {abs(n1 - n2)} excess frames will be NaN-filled")

    # ── Copy image data (HDU data may be memory-mapped / read-only) ───────
    flux = np.array(hdu[1].data['FLUX'], dtype=np.float32)
    flux_err = np.array(hdu[1].data['FLUX_ERR'], dtype=np.float32)

    # ── Swap orbit blocks ─────────────────────────────────────────────────
    flux_scrambled = flux.copy()
    flux_err_scrambled = flux_err.copy()

    # Orbit 2 frames -> Orbit 1 time positions
    flux_scrambled[idx_o1[:n_swap]] = flux[idx_o2[:n_swap]]
    flux_err_scrambled[idx_o1[:n_swap]] = flux_err[idx_o2[:n_swap]]

    # Orbit 1 frames -> Orbit 2 time positions
    flux_scrambled[idx_o2[:n_swap]] = flux[idx_o1[:n_swap]]
    flux_err_scrambled[idx_o2[:n_swap]] = flux_err[idx_o1[:n_swap]]

    # NaN-fill excess frames from the longer orbit (unswappable cadences)
    if n1 > n_swap:
        flux_scrambled[idx_o1[n_swap:]] = np.nan
        flux_err_scrambled[idx_o1[n_swap:]] = np.nan
    if n2 > n_swap:
        flux_scrambled[idx_o2[n_swap:]] = np.nan
        flux_err_scrambled[idx_o2[n_swap:]] = np.nan

    # ── Write back to HDU ─────────────────────────────────────────────────
    hdu[1].data['FLUX'][:] = flux_scrambled
    hdu[1].data['FLUX_ERR'][:] = flux_err_scrambled

    if verbose:
        n_valid = np.sum(np.isfinite(flux_scrambled[:, 0, 0]))
        n_nan = n_total - n_valid
        print(f"  Result: {n_valid} valid frames, {n_nan} NaN-filled")
        print(f"  ===== Scrambling Complete =====\n")
#
# stream line LC production fron image headers
#
def get_LC_from_FFI(ID, nearby_star_catalog, Sector, cadence,
                    hdu, CCD, Camera, reference_pixel, default_settings, **kwargs):
    """
    Run the full per-sector NEMESIS LC extraction pipeline on a single HDU.

    This is the innermost per-sector workhorse called by ``LC_creation``.
    It executes the following steps in sequence:

        1. Build quality bitmask from the TESS QUALITY array.
        2. Edge check via ``edge_check``; returns ``(None, {})`` if the
           target falls on or near the detector boundary.
        3. Simple Aperture Photometry via ``SAP``, including background
           extraction, deblending, centroid tracking, and quaternion-based
           quality flagging.
        4. Momentum dump and sector jitter masking via
           ``Applying_Mdump_removal`` (gated by ``do_mdump_removal`` and
           ``do_sector_jitter_mask``).
        5. Pixel Level Decorrelation via ``PLD_model``.
        6. Biweight smoothing via ``Smoother``.
        7. Sliding-window outlier removal via ``outlier_removal``.
        8. Save all intermediate and final LC CSVs; call ``plot_it_all_up``
           for the LC summary figure.

    Optional transit injection is applied to the raw SAP flux at step 3
    when ``for_injections=True`` and ``inject_param_P_RP_T0`` is set.

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``.  Must contain
        columns ``ID``, ``rad``, ``mass``, ``Teff``, ``logg``, ``Tmag``,
        ``qld_a``, ``qld_b``.
    Sector : int
        TESS sector number for this HDU.
    cadence : str
        TESS exposure cadence: ``'30 minute'``, ``'10 minute'``,
        ``'2 minute'``, ``'20 second'``, or legacy aliases.
    hdu : fits.HDUList or list of fits.HDUList
        Raw FITS data as returned by ``gethdu``.  For multi-sector HDU
        lists the edge-check logic handles ``None`` entries gracefully.
    CCD : int
        TESS CCD number (1–4) from ``gethdu``.
    Camera : int
        TESS Camera number (1–4) from ``gethdu``.
    reference_pixel : list [x, y]
        Pixel coordinates of the target star within the cutout, as returned
        by ``gethdu``.
    default_settings : dict
        NEMESIS settings dict (must be populated by ``Make_dirs`` before
        this call).  Consumed keys include: ``savelcpath``, ``savefigpath``,
        ``bitmask_string``, ``cutoutsize``, ``minimum_photon_counts``,
        ``threshold``, ``use_SPOC_aperture``, ``use_centroid``,
        ``use_circ``, ``use_sources_in_aperture``, ``do_aperture_optimization``,
        ``do_mdump_removal``, ``do_sector_jitter_mask``, ``before_after_in_minutes``,
        ``keep_mdumps``, ``keep_baddata``, ``pld_order``, ``n_pca_terms``,
        ``window_size_in_days``, ``remove_outliers``, ``Nsigma``,
        ``for_injections``, ``inject_param_P_RP_T0``, ``verbose``.
    **kwargs
        Not currently used; reserved for future per-call overrides.

    Returns
    -------
    LC_df : pd.DataFrame or None
        Final processed light curve with columns:
        ``Time``, ``SAP Flux``, ``SAP Error``,
        ``PLD Flux``, ``PLD Error``, ``PLD Model``,
        ``Detrended Flux``, ``Detrended Error``, ``Fitted Trend``,
        ``Background Flux``, ``Background Error``,
        ``Centroid X Positions``, ``Centroid Y Positions``.
        ``None`` on any unrecoverable failure.
    sap_diag : dict
        SAP diagnostic arrays for this sector.  Keys:
        ``quality_flag``, ``bkg_level_per_pix``, ``bkg_trend``,
        ``bkg_residuals``, ``quat_jitter``, ``quat_status``,
        ``qlp_result``.
        Empty dict ``{}`` on failure.

    Notes
    -----
    Returns ``(None, {})`` in the following cases:
    - Target is on or near the detector edge.
    - No valid image data after quality masking (e.g., all frames NaN).
    - Total photon counts fall below ``minimum_photon_counts``.
    - ``SAP`` returns ``None`` (aperture mask failure).

    Saved outputs (to ``savelcpath``)
    -----------------------------------
    ``TIC_{ID}_Sector_{NNNN}_RAW_LC.csv``
    ``TIC_{ID}_Sector_{NNNN}_RAW_LC_systematics_removed.csv``
    ``TIC_{ID}_Sector_{NNNN}_final_LC_preclipped.csv``
    ``TIC_{ID}_Sector_{NNNN}_bad_outliers.csv``
    ``TIC_{ID}_Sector_{NNNN}_good_outliers.csv``
    ``TIC_{ID}_Sector_{NNNN}_final_LC.csv``
    ``TIC_{ID}_Sector_{NNNN}_pix_mask.pkl``
    ``TIC_{ID}_Sector_{NNNN}_bkg_mask.pkl``
    ``TIC_{ID}_Sector_{NNNN}_image_fluxes.pkl``
    """
    import pandas as pd
    import time as clock
    from astropy.io import fits as _fits

    # ── unpack settings ───────────────────────────────────────────────────────
    path                 = default_settings.get('path')
    savelcpath           = default_settings.get('savelcpath')
    savefigpath          = default_settings.get('savefigpath')
    downloadpath         = default_settings.get('downloadpath')
    bitmask_string       = default_settings.get('bitmask_string')
    get_all_sectors      = default_settings.get('get_all_sectors')
    cutoutsize           = default_settings.get('cutoutsize')
    minimum_photon_counts= default_settings.get('minimum_photon_counts')
    threshold            = default_settings.get('threshold')
    use_SPOC_aperture    = default_settings.get('use_SPOC_aperture')
    use_centroid         = default_settings.get('use_centroid')
    use_circ             = default_settings.get('use_circ')
    use_sources_in_aperture = default_settings.get('use_sources_in_aperture')
    before_after_in_minutes = default_settings.get('before_after_in_minutes')
    keep_mdumps          = default_settings.get('keep_mdumps')
    keep_baddata         = default_settings.get('keep_baddata')
    #
    do_jittermask         = default_settings.get('do_jittermask')
    do_mdump_removal_orig      = default_settings.get('do_mdump_removal')
    do_sector_jitter_mask_orig = default_settings.get('do_sector_jitter_mask')
    #
    pld_order            = default_settings.get('pld_order')
    n_pca_terms          = default_settings.get('n_pca_terms')
    window_size_in_days  = default_settings.get('window_size_in_days')
    remove_outliers      = default_settings.get('remove_outliers')
    Nsigma               = default_settings.get('Nsigma')
    keep_FITS            = default_settings.get('keep_FITS')
    for_injections       = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    verbose              = default_settings.get('verbose')
    
    

    # AFTER — direct reads, no override
    do_mdump_removal      = default_settings.get('do_mdump_removal')
    do_sector_jitter_mask = default_settings.get('do_sector_jitter_mask')
    if verbose:
        print(f'[get_LC_from_FFI] do_mdump_removal={do_mdump_removal}  '
              f'do_sector_jitter_mask={do_sector_jitter_mask}  '
              f'use_quat_jitter_mask={default_settings.get("use_quat_jitter_mask")}')      

    if isinstance(Sector, int):
        sector_tag = f'Sector_{Sector:04d}'
    else:
        sector_tag = 'Multi_Sector'

    # sentinel: populated only on the success path
    sap_diag = {}

    start = clock.time()
    print(f'get_LC_from_FFI hdu type check: {type(hdu)} ; {hdu}')

    # ── bitmask quality array ─────────────────────────────────────────────────
    if isinstance(hdu, list) and not isinstance(hdu, _fits.HDUList):
        quality_mask = [
            pipeline_quality_mask(bitmask_string, h[1].data['QUALITY'], verbose)
            for h in hdu
        ]
    else:
        quality_mask = pipeline_quality_mask(
            bitmask_string, hdu[1].data['QUALITY'], verbose)

    # ── edge check ────────────────────────────────────────────────────────────
    edge_problem = edge_check(ID, nearby_star_catalog, Sector, verbose)
    for e in range(len(edge_problem)):
        if e > 1:
            if edge_problem[e] == 'Y':
                print(f'\n Edge Problem with HDU in Sector '
                      f'{_sec_str(hdu[0].header["SECTOR"])} \n')
                edge_problem_m = np.where(edge_problem == 'Y')[0]
                hdu[edge_problem_m]             = None
                CCD[edge_problem_m]             = None
                Camera[edge_problem_m]          = None
                quality_mask[edge_problem_m]    = None
                reference_pixel[edge_problem_m] = None
        if e < 1:
            if edge_problem[e] == 'Y':
                print(hdu)
                if (hdu is not None) & (type(hdu) is not list):
                    print(type(hdu))
                    print(f'\n Edge Problem with HDU in Sector '
                          f'{_sec_str(hdu[0].header["SECTOR"])} \n')
                hdu            = None
                CCD            = None
                Camera         = None
                quality_mask   = None
                reference_pixel = None

    if isinstance(hdu, list) & (len(edge_problem) > 1):
        hdu            = [x for x in hdu if x is not None]
        CCD            = [x for x in CCD if x is not None]
        Camera         = [x for x in Camera if x is not None]
        quality_mask   = [x for x in quality_mask if x is not None]
        reference_pixel = [x for x in reference_pixel if x is not None]

    if hdu is None:
        if Sector is not None:
            print(f"\n Warning: No usable image data for TIC {ID} in Sector "
                  f"{_sec_str(Sector)} (possibly on edge). Skipping.\n")
        return None, {}

    # ── helper to unpack the 13-value SAP return ──────────────────────────────
    def _unpack_sap(result):
        
        (bkg_mask, pix_mask, flux, median_image, SAP_LC,
         flux_contamination_ratio, quality_flag,
         bkg_level_per_pix, bkg_trend, bkg_residuals,
         quat_jitter, quat_status, qlp_result) = result
        
        bkg_err_mask = (quality_flag == 0)
        
        return (bkg_mask, pix_mask, flux, median_image, SAP_LC,
                flux_contamination_ratio, quality_flag, bkg_err_mask,
                bkg_level_per_pix, bkg_trend, bkg_residuals,
                quat_jitter, quat_status, qlp_result)

    def _make_sap_diag_OLD(qf, bpp, bt, br, qj, qs, qr):
        return dict(
            quality_flag      = qf,
            bkg_level_per_pix = bpp,
            bkg_trend         = bt,
            bkg_residuals     = br,
            quat_jitter       = qj,
            quat_status       = qs,
            qlp_result        = qr,
        )
    
    def _make_sap_diag(qf, bpp, bt, br, qj, qs, qr, qt=None):
        """Bundle SAP diagnostic arrays into the sap_diag dict.

        Parameters
        ----------
        qf  : np.ndarray   quality_flag (int16)
        bpp : np.ndarray   bkg_level_per_pix
        bt  : np.ndarray   bkg_trend
        br  : np.ndarray   bkg_residuals
        qj  : np.ndarray or None   quat_jitter  (length = N_masked)
        qs  : str          quat_status
        qr  : dict or None qlp_result
        qt  : np.ndarray or None   time array aligned to qj  (length = N_masked)
                           Pass SAP_LC['Time'].to_numpy(dtype=np.float64) here.
                           Used in plot_it_all_up to avoid broadcast errors when
                           RAWLC_df has been restored to full cadence length.
        """
        return dict(
            quality_flag      = qf,
            bkg_level_per_pix = bpp,
            bkg_trend         = bt,
            bkg_residuals     = br,
            quat_jitter       = qj,
            quat_status       = qs,
            qlp_result        = qr,
            quat_time         = qt,   # <-- NEW: time axis for quat_jitter
        )
    
    # FOR SCRAMBLE TEST
    if default_settings.get('scramble_orbits')==True:
        scramble_hdu_orbits(hdu, Sector, verbose=verbose) #scrambles hdu time stamps in place
    # FOR SCRAMBLE TEST
    #
    # ── Step 2: SAP ───────────────────────────────────────────────────────────
    if verbose:
        print('\n Step 2: SAP + background/centroid/quaternion quality flagging \n')

    try:
        _sap_result = SAP_ALT5(ID, nearby_star_catalog, Sector, cadence, hdu, 
                               quality_mask, reference_pixel, default_settings)

        if _sap_result[0] is None:
            raise TypeError('SAP returned None — aperture or frame failure.')

        (bkg_mask, pix_mask, flux, median_image, SAP_LC,
         flux_contamination_ratio, quality_flag, bkg_err_mask,
         bkg_level_per_pix, bkg_trend, bkg_residuals,
         quat_jitter, quat_status, qlp_result) = _unpack_sap(_sap_result)

        # populate diagnostic dict immediately after first successful SAP call
        sap_diag = _make_sap_diag(
            quality_flag, bkg_level_per_pix, bkg_trend,
            bkg_residuals, quat_jitter, quat_status, qlp_result,
            qt=SAP_LC['Time'].to_numpy(dtype=np.float64),   # <-- NEW
        )
        # SAP_ALT5 aperture metadata (no-ops for any other SAP variant)
        sap_diag['has_blended_neighbor'] = SAP_LC.attrs.get('has_blended_neighbor',
                                                            False)
        sap_diag['aperture_method']      = SAP_LC.attrs.get('aperture_method',
                                                            'unknown')
        sap_diag['cdpp_score']           = SAP_LC.attrs.get('cdpp_score', 
                                                            np.nan)    
        sap_diag['aperture_method_param'] = SAP_LC.attrs.get('aperture_method_param', None)  # NEW
        sap_diag['aperture_winner_label'] = SAP_LC.attrs.get('aperture_winner_label', None)  # NEW

        check = np.sum(
            flux[:,
                 int(reference_pixel[0]):int(reference_pixel[0]) + 1,
                 int(reference_pixel[1]):int(reference_pixel[1]) + 1])

        if np.isnan(check):
            print(f'\n TIC {ID} in Sector {Sector} may be off the edge of CCD '
                  'or FFI was corrupted. Retrying... \n')
            import time as clock2
            clock2.sleep(1)
            Make_dirs(Sector, cadence, default_settings, return_paths=False)
            _star = nearby_star_catalog.loc[
                nearby_star_catalog['ID'] == str(ID)
            ].reset_index(drop=True)
            hdu, CCD, Camera, quality_mask, reference_pixel = gethdu(
                _star, ID, Sector, cadence, default_settings)                        
            
            
            _sap_result2 = SAP_ALT5(ID, nearby_star_catalog,
                               Sector, cadence, hdu,
                               quality_mask, reference_pixel,
                               default_settings)
            if _sap_result2[0] is None:
                return None, {}
            (bkg_mask, pix_mask, flux, median_image, SAP_LC,
             flux_contamination_ratio, quality_flag, bkg_err_mask,
             bkg_level_per_pix, bkg_trend, bkg_residuals,
             quat_jitter, quat_status, qlp_result) = _unpack_sap(_sap_result2)
            # refresh sap_diag after retry
            sap_diag = _make_sap_diag(
                quality_flag, bkg_level_per_pix, bkg_trend,
                bkg_residuals, quat_jitter, quat_status, qlp_result,
                qt=SAP_LC['Time'].to_numpy(dtype=np.float64),   # <-- NEW
            )

    except TypeError as TE:
        print(f'{TE}\nUnable to create aperture mask. Skipping this target...\n')
        return None, {}

    if len(SAP_LC['SAP Error']) == 0:
        print('\n Uneven array lengths; FFI likely on edge of detector. \n')
        return None, {}

    if verbose:
        timer(start=start, end=clock.time(), message='SAP took:')

    # ── Step 3: Momentum dump / jitter removal ────────────────────────────────
    start = clock.time()
    if verbose:
        print('\n Step 3: Removing momentum dumps and regions of high jitter \n')

    if do_mdump_removal or do_sector_jitter_mask:
        mask_mdump, t_0, t_1, flux, RAWLC_df, clippedRAWLC_df = Applying_Mdump_removal(
            ID=ID, Sector=Sector, hdu=hdu, SAP_LC=SAP_LC,
            flux=flux, combined_mask=bkg_err_mask,
            default_settings=default_settings,
        )
        combined_mask = mask_mdump
    else:
        # skip both — quat masking alone
        orbit1_start, orbit1_stop, orbit2_start, orbit2_stop = \
            TESS_Sector_observation_check(SectorNum=Sector)
        t_0, t_1      = orbit1_start, orbit2_stop
        mask_mdump    = None
        combined_mask = bkg_err_mask
        if verbose:
            print(f'pre-PLD image flux shape {np.shape(flux)} '
                  '; both do_mdump_removal and do_sector_jitter_mask are False '
                  '— relying on quaternion + bkg/centroid quality flags only.')
        RAWLC_df        = SAP_LC
        clippedRAWLC_df = SAP_LC

    # ── Save aperture / background masks and image flux cube ──────────────────
    saveNDarr(pix_mask, savelcpath, f"TIC_{ID}_{sector_tag}_pix_mask")
    saveNDarr(bkg_mask, savelcpath, f"TIC_{ID}_{sector_tag}_bkg_mask")
    saveNDarr(flux,     savelcpath, f"TIC_{ID}_{sector_tag}_image_fluxes")

    # ── Centroids: use values already computed inside SAP ─────────────────────
    cxs = SAP_LC['Centroid X Positions'].to_numpy(dtype=np.float64)
    cys = SAP_LC['Centroid Y Positions'].to_numpy(dtype=np.float64)

    time_arr   = clippedRAWLC_df['Time'].to_numpy(dtype=np.float64)
    sap_flux   = clippedRAWLC_df['SAP Flux'].to_numpy(dtype=np.float64)
    sap_error  = clippedRAWLC_df['SAP Error'].to_numpy(dtype=np.float64)
    bkg_flux_c = clippedRAWLC_df['Background Flux'].to_numpy(dtype=np.float64)
    bkg_error_c= clippedRAWLC_df['Background Error'].to_numpy(dtype=np.float64)

    if len(cxs) != len(time_arr):
        if mask_mdump is not None:
            cxs = cxs[combined_mask]
            cys = cys[combined_mask]
        else:
            cxs = np.ravel(cxs)[combined_mask]
            cys = np.ravel(cys)[combined_mask]

    if verbose:
        print('centroid vs time len check:',
              len(cxs), len(cys), len(time_arr),
              None if mask_mdump is None else len(mask_mdump))
        
    #   
    cadence_index = SAP_LC.loc[combined_mask, 'CADENCE_INDEX'].to_numpy(dtype=int)
    quality_flags = SAP_LC.loc[combined_mask, 'QUALITY_FLAG'].to_numpy(dtype=int)
    #
    clippedRAWLC_df = pd.DataFrame({
        "CADENCE_INDEX":        cadence_index,
        "Time":                 time_arr,
        "SAP Flux":             sap_flux,
        "SAP Error":            sap_error,
        "Background Flux":      bkg_flux_c,
        "Background Error":     bkg_error_c,
        "Centroid X Positions": cxs,
        "Centroid Y Positions": cys,
        "QUALITY_FLAG":         quality_flags
    })
    #
    #
    if verbose:
        timer(start=start, end=clock.time(),
              message='Momentum dump and jitter removal took:')

    # ── Step 4: PLD ───────────────────────────────────────────────────────────
    if verbose:
        print('Step 4: Performing Pixel Level Decorrelation modeling\n')

    input_LC = clippedRAWLC_df.copy()
    PLD_LC = PLD_model(ID=ID, Sector=Sector, flux=flux,
                       pix_mask=pix_mask, input_LC=input_LC,
                       default_settings=default_settings)
    if verbose:
        df_len_check(PLD_LC, message='len check for step 4: ')

    # ── Step 5: Smoothing ─────────────────────────────────────────────────────
    start = clock.time()
    if verbose:
        print('Step 5: Applying smoothing filter\n')
    #
    #
    input_LC2 = pd.DataFrame({
        'CADENCE_INDEX':         PLD_LC['CADENCE_INDEX'].to_numpy(dtype=int),
        'Time':                  PLD_LC['Time'].to_numpy(dtype=np.float64),
        'Flux':                  PLD_LC['PLD Flux'].to_numpy(dtype=np.float64),
        'Error':                 PLD_LC['PLD Error'].to_numpy(dtype=np.float64),
        'Model':                 PLD_LC['PLD Model'].to_numpy(dtype=np.float64),
        'SAP Flux':              PLD_LC['SAP Flux'].to_numpy(dtype=np.float64),
        'SAP Error':             PLD_LC['SAP Error'].to_numpy(dtype=np.float64),
        'Background Flux':       PLD_LC['Background Flux'].to_numpy(dtype=np.float64),
        'Background Error':      PLD_LC['Background Error'].to_numpy(dtype=np.float64),
        'Centroid X Positions':  PLD_LC['Centroid X Positions'].to_numpy(dtype=np.float64),
        'Centroid Y Positions':  PLD_LC['Centroid Y Positions'].to_numpy(dtype=np.float64),
        'QUALITY_FLAG':          PLD_LC['QUALITY_FLAG'].to_numpy(dtype=int),
    })    
    #
    if verbose:
        df_len_check(input_LC2, message='len check RIGHT BEFORE step 5: ')

    Det_LC, nanmask = Smoother(ID=ID, nearby_star_catalog=nearby_star_catalog,
                               Sector=Sector, input_LC=input_LC2,
                               default_settings=default_settings)

    if len(Det_LC['Time'].to_numpy()) < len(PLD_LC['Time'].to_numpy()) / 2:
        print('problem with PLD + smoothing; too few data points masked:',
              len(Det_LC['Time'].to_numpy()))
        return None, {}
    if verbose:
        df_len_check(Det_LC, message='len check for step 5: ')
        timer(start=start, end=clock.time(), message='Smoothing took:')

    # ── Step 6: Outlier removal ───────────────────────────────────────────────
    start = clock.time()
    if verbose:
        print('Step 6: Applying Outlier Removal\n')
        df_len_check(Det_LC, message='len check for step 6: ')
    #
    #
    input_LC3 = pd.DataFrame({
    'CADENCE_INDEX':         Det_LC['CADENCE_INDEX'].to_numpy(dtype=int),
    'Time':                  Det_LC['Time'].to_numpy(dtype=np.float64),
    'SAP Flux':              Det_LC['SAP Flux'].to_numpy(dtype=np.float64),
    'SAP Error':             Det_LC['SAP Error'].to_numpy(dtype=np.float64),
    'Background Flux':       Det_LC['Background Flux'].to_numpy(dtype=np.float64),
    'Background Error':      Det_LC['Background Error'].to_numpy(dtype=np.float64),
    'Detrended Flux':        Det_LC['Detrended Flux'].to_numpy(dtype=np.float64),
    'Detrended Error':       Det_LC['Detrended Error'].to_numpy(dtype=np.float64),
    'Fitted Trend':          Det_LC['Fitted Trend'].to_numpy(dtype=np.float64),
    'PLD Flux':              Det_LC['PLD Flux'].to_numpy(dtype=np.float64),
    'PLD Error':             Det_LC['PLD Error'].to_numpy(dtype=np.float64),
    'PLD Model':             Det_LC['PLD Model'].to_numpy(dtype=np.float64),
    'Centroid X Positions':  Det_LC['Centroid X Positions'].to_numpy(dtype=np.float64),
    'Centroid Y Positions':  Det_LC['Centroid Y Positions'].to_numpy(dtype=np.float64),
    'QUALITY_FLAG':          Det_LC['QUALITY_FLAG'].to_numpy(dtype=int)
    })
    #
    LC_df, good_ind_DF, bad_ind_DF, preclipLC_df = outlier_removal(
        ID=ID, nearby_star_catalog=nearby_star_catalog,
        Sector=Sector, input_LC=input_LC3,
        default_settings=default_settings,
    )    
    #
    # ---------------------------------------------------------------------
    # Rebuild full-length versions for saving/plotting.
    # Keep compact LC_df for downstream transit-search math.
    # ---------------------------------------------------------------------
    RAWLC_df_full = SAP_LC.copy()
    
    # Append outlier bit (flag-id 3 -> bit 4) onto the full-length SAP table
    # before rebuilding the user-facing full-length CSV products.
    if ('CADENCE_INDEX' in bad_ind_DF.columns) and bad_ind_DF['CADENCE_INDEX'].notna().any():
        bad_cadence_idx = bad_ind_DF['CADENCE_INDEX'].dropna().astype(int).to_numpy()
        SAP_LC = _apply_outlier_flag(SAP_LC, bad_cadence_idx)

    clippedRAWLC_df_full = _restore_full_length_lc(
        SAP_LC, clippedRAWLC_df,
        preserve_columns=(
            "CADENCE_INDEX", "Time", "RAW SAP Flux",
            "SAP Flux", "SAP Error", 
            "Background Flux","Background Error",
            "QUALITY_FLAG",
            "HAS_BLENDED_NEIGHBOR",   # ← add
            "APERTURE_FELL_BACK",     # ← add
        ), 
    )

    preclipLC_df_full = _restore_full_length_lc(
        SAP_LC, preclipLC_df,
        preserve_columns=(
            "CADENCE_INDEX", "Time", "RAW SAP Flux",
            "SAP Flux", "SAP Error", 
            "Background Flux","Background Error",
            "QUALITY_FLAG",
        ),
    )

    LC_df_full = _restore_full_length_lc(
        SAP_LC, LC_df,
        preserve_columns=(
            "CADENCE_INDEX", "Time", "RAW SAP Flux",
            "SAP Flux", "SAP Error", 
            "Background Flux","Background Error",
            "QUALITY_FLAG",
        ),
    )    
    
    # decorate with quality flag strings
    RAWLC_df_full = _decorate_quality_columns(SAP_LC.copy())

    clippedRAWLC_df_full = _decorate_quality_columns(
        _restore_full_length_lc(
            SAP_LC, clippedRAWLC_df,
            preserve_columns=(
                "CADENCE_INDEX", "Time", "RAW SAP Flux",
                "SAP Flux", "SAP Error", 
                "Background Flux","Background Error",
                "QUALITY_FLAG",
            ),
        )
    )

    preclipLC_df_full = _decorate_quality_columns(
        _restore_full_length_lc(
            SAP_LC, preclipLC_df,
            preserve_columns=(
                "CADENCE_INDEX", "Time", "RAW SAP Flux",
                "SAP Flux", "SAP Error", 
                "Background Flux","Background Error",
                "QUALITY_FLAG",
            ),
        )
    )

    LC_df_full = _decorate_quality_columns(
        _restore_full_length_lc(
            SAP_LC, LC_df,
            preserve_columns=(
                "CADENCE_INDEX", "Time", "RAW SAP Flux",
                "SAP Flux", "SAP Error", 
                "Background Flux","Background Error",
                "QUALITY_FLAG",
            ),
        )
    )

    good_ind_DF = _decorate_quality_columns(good_ind_DF)
    bad_ind_DF  = _decorate_quality_columns(bad_ind_DF)
    LC_df       = _decorate_quality_columns(LC_df)    
    #    
    #
    # ── Save intermediate products ────────────────────────────────────────────
    #
    #
    RAWLC_df_full.to_csv(
        savelcpath + f"TIC_{ID}_{sector_tag}_RAW_LC.csv", index=False)

    clippedRAWLC_df_full.to_csv(
        savelcpath + f"TIC_{ID}_{sector_tag}_RAW_LC_systematics_removed.csv",
        index=False)

    preclipLC_df_full.to_csv(
        savelcpath + f"TIC_{ID}_{sector_tag}_final_LC_preclipped.csv",
        index=False)

    bad_ind_DF.to_csv(
        savelcpath + f"TIC_{ID}_{sector_tag}_bad_outliers.csv", index=False)

    good_ind_DF.to_csv(
        savelcpath + f"TIC_{ID}_{sector_tag}_good_outliers.csv", index=False)

    LC_df_full.to_csv(
        savelcpath + f"TIC_{ID}_{sector_tag}_final_LC.csv", index=False)    
    

    if verbose:
        timer(start=start, end=clock.time(), message='Outlier Removal took:')

    # ── Step 7: Plot LC summary ───────────────────────────────────────────────
    start = clock.time()
    if verbose:
        print('Step 7: Plotting and Saving FFI and selected apertures\n')
    plot_it_all_up(
        ID=ID, nearby_star_catalog=nearby_star_catalog,
        Sector=Sector, cadence=cadence,
        hdu=hdu, median_image=median_image,
        pix_mask=pix_mask, bkg_mask=bkg_mask,
        RAWLC_df=RAWLC_df_full, clippedRAWLC_df=clippedRAWLC_df_full,
        LC_df=LC_df_full, good_ind_DF=good_ind_DF,
        bad_ind_DF=bad_ind_DF, preclipLC_df=preclipLC_df_full,
        magnitude_limit=18, dot_scale=20, cbarpad=0.01,
        default_settings=default_settings,
        # forward SAP diagnostics to single-sector summary figure
        bkg_level_per_pix = sap_diag.get('bkg_level_per_pix'),
        bkg_trend         = sap_diag.get('bkg_trend'),
        bkg_residuals     = sap_diag.get('bkg_residuals'),
        quat_jitter       = sap_diag.get('quat_jitter'),
        quat_status       = sap_diag.get('quat_status', 'not provided'),
        qlp_result        = sap_diag.get('qlp_result'),
        quality_flag      = sap_diag.get('quality_flag'),
    )    

    if verbose:
        timer(start=start, end=clock.time(), message='Plotting LC Summary took:')
        df_len_check(LC_df, message='FINAL LENGTHs: ')

    return LC_df_full, sap_diag
#
#
#
def LC_creation(ID, nearby_star_catalog, cadence, Sector, default_settings, **kwargs):
    """
    Produce processed TESS light curves for one or more sectors using the
    NEMESIS pipeline (Feliz et al. 2021, https://arxiv.org/abs/2103.05647).

    For each sector, calls ``gethdu`` → ``get_LC_from_FFI`` in sequence.
    Multi-sector results are concatenated and saved as ``Multi_Sector_*``
    CSV files.  SAP diagnostic arrays from all sectors are aggregated into a
    single ``sap_diag`` dict for downstream forwarding to vetting reports.

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar parameters for the target and nearby stars, as returned by
        ``collect_nearby_TIC_params``.  Must include columns ``ID``,
        ``rad``, ``mass``, ``Teff``, ``logg``, ``Tmag``, ``qld_a``,
        ``qld_b``.
    cadence : str
        TESS exposure cadence: ``'30 minute'``, ``'10 minute'``,
        ``'2 minute'``, ``'20 second'``, or legacy aliases.
    Sector : int, list of int, or None
        Sector(s) to process.  ``None`` with ``get_all_sectors=True``
        auto-discovers all available sectors.
    default_settings : dict
        NEMESIS settings dictionary, typically from ``default_NEMESIS_pipeline_settings``
        and already updated by ``Make_dirs`` (paths must be populated).
        Relevant keys: ``get_all_sectors``, ``for_injections``,
        ``inject_param_P_RP_T0``, ``verbose``, ``savelcpath``, ``base_path``.
    **kwargs
        Forwarded to ``get_LC_from_FFI`` for per-call overrides.

    Returns
    -------
    hdu : fits.HDUList or list of fits.HDUList or None
        Raw FITS data from the last successfully processed sector, or a list
        for multi-sector runs.  ``None`` on failure.
    LC_df : pd.DataFrame or None
        Final concatenated light curve across all sectors.  Columns:
        ``Time``, ``SAP Flux``, ``SAP Error``, ``PLD Flux``, ``PLD Error``,
        ``PLD Model``, ``Detrended Flux``, ``Detrended Error``,
        ``Fitted Trend``, ``Background Flux``, ``Background Error``,
        ``Centroid X Positions``, ``Centroid Y Positions``.
        ``None`` on failure.
    sap_diag : dict
        Aggregated SAP diagnostic arrays across all processed sectors.
        Keys: ``quality_flag``, ``bkg_level_per_pix``, ``bkg_trend``,
        ``bkg_residuals``, ``quat_jitter``, ``quat_status``, ``qlp_result``.
        Empty dict ``{}`` on failure or if no diagnostics were produced.

    Notes
    -----
    On any unrecoverable failure (e.g., all sectors on detector edge,
    insufficient photon counts), returns ``(None, None, {})``.

    Saved outputs (per sector)
    --------------------------
    ``TIC_{ID}_Sector_{NNNN}_RAW_LC.csv``
    ``TIC_{ID}_Sector_{NNNN}_RAW_LC_systematics_removed.csv``
    ``TIC_{ID}_Sector_{NNNN}_final_LC_preclipped.csv``
    ``TIC_{ID}_Sector_{NNNN}_bad_outliers.csv``
    ``TIC_{ID}_Sector_{NNNN}_good_outliers.csv``
    ``TIC_{ID}_Sector_{NNNN}_final_LC.csv``
    Multi-sector runs additionally produce ``TIC_{ID}_Multi_Sector_*`` versions.
    """
    import sys
    import time as clock
    import pandas as pd
    import requests

    start = clock.time()

    # ── settings ──────────────────────────────────────────────────────────────
    verbose             = default_settings.get('verbose')
    get_all_sectors     = default_settings.get('get_all_sectors')
    for_injections      = default_settings.get('for_injections')
    inject_param_P_RP_T0= default_settings.get('inject_param_P_RP_T0')
    base_path           = default_settings.get('base_path')

    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = 'Multi_Sector'
    else:
        sector_tag = f'Sector_{Sector:04d}'

    # ── resolve TIC ID ────────────────────────────────────────────────────────
    if not isinstance(ID, int):
        ID = get_TIC_ID(ID, verbose)

    # ── stellar parameters ────────────────────────────────────────────────────
    star = nearby_star_catalog.loc[
        nearby_star_catalog['ID'] == str(ID)
    ].reset_index(drop=True)
    star = get_qld(star, verbose)

    if star is None or len(star) == 0:
        star, nearby_star_catalog = collect_nearby_TIC_params(
            ID, N_TESS_pixels=2, downloadpath=None)

    R_star = star['rad'].item()
    M_star = star['mass'].item()

    if not (np.isfinite(R_star) and np.isfinite(M_star)):
        print(f'TIC {ID} has no known Stellar Mass or Radius in TIC.\n'
              'Using Mass-Radius Relation.')
        M_star, R_star = mass_radius_mdwarf_relation(M_star, R_star)
        if not (np.isfinite(R_star) and np.isfinite(M_star)):
            print(f'TIC {ID}: Mass-Radius relation also failed. '
                  'Cancelling NEMESIS LC production.')
            return None, None, {}
        if verbose:
            print(f'new M_star={M_star:.3f}, R_star={R_star:.3f}')
        star['e_mass'] = M_star * 0.10
        star['e_rad']  = R_star * 0.10

    # ─────────────────────────────────────────────────────────────────────────
    # Helper: aggregate a list of per-sector sap_diag dicts into one.
    # ─────────────────────────────────────────────────────────────────────────
    def _aggregate_sap_diags(diag_list):
        """
        Concatenate array-valued diagnostics; merge feature_dfs across sectors;
        keep last non-None scalar for quat_status / qlp_result structure.
        """
        if not diag_list:
            return {}

        array_keys  = ['quality_flag', 'bkg_level_per_pix',
                        'bkg_trend', 'bkg_residuals', 'quat_jitter']
        scalar_keys = ['quat_status', 'qlp_result']

        agg = {}

        # ── array keys: concatenate ───────────────────────────────────────────
        for k in array_keys:
            arrays = [d[k] for d in diag_list if d.get(k) is not None]
            if arrays:
                try:
                    agg[k] = np.concatenate([np.atleast_1d(a) for a in arrays])
                except Exception:
                    agg[k] = arrays[-1]
            else:
                agg[k] = None

        # ── scalar keys: keep last non-None ───────────────────────────────────
        for k in scalar_keys:
            vals = [d[k] for d in diag_list if d.get(k) is not None]
            agg[k] = vals[-1] if vals else None

        # ── special handling: concatenate feature_dfs across sectors ──────────
        # Each qlp_result dict (one per sector) contains a 'feature_df' with a
        # 'time' column.  Concatenating them gives a single continuous DataFrame
        # that the heatmap imshow can display over the full time baseline.
        feat_dfs = []
        feat_cols_ref = None
        for d in diag_list:
            qr = d.get('qlp_result')
            if qr is not None and isinstance(qr, dict):
                fdf = qr.get('feature_df')
                if fdf is not None:
                    feat_dfs.append(fdf)
                    if feat_cols_ref is None:
                        feat_cols_ref = qr.get('feature_cols')

        if feat_dfs:
            try:
                combined_feat_df = pd.concat(feat_dfs, ignore_index=True
                                             ).sort_values('time'
                                             ).reset_index(drop=True)
                # patch the aggregated qlp_result so the heatmap sees all sectors
                if agg['qlp_result'] is None:
                    agg['qlp_result'] = {}
                agg['qlp_result'] = dict(agg['qlp_result'])   # shallow copy
                agg['qlp_result']['feature_df']   = combined_feat_df
                agg['qlp_result']['feature_cols'] = feat_cols_ref
                # rebuild combined jitter_mask from the concatenated jitter array
                if agg.get('quat_jitter') is not None:
                    jitter_arr = np.asarray(agg['quat_jitter'], dtype=float)
                    finite_j   = jitter_arr[np.isfinite(jitter_arr)]
                    if len(finite_j) >= 5:
                        med_j = np.median(finite_j)
                        mad_j = np.median(np.abs(finite_j - med_j)) * 1.4826
                        # default sigma threshold; plot functions re-derive anyway
                        agg['qlp_result']['jitter_mask'] = (
                            ~np.isfinite(jitter_arr) |
                            (jitter_arr > med_j + 5.0 * mad_j)
                        )
            except Exception:
                pass   # non-fatal; heatmap falls back to last-sector df

        return agg

    # ─────────────────────────────────────────────────────────────────────────
    # Helper: produce and collect the LC + diagnostics for ONE sector.
    # ─────────────────────────────────────────────────────────────────────────
    def print_reference_pixel_diagnostic(
        ID,
        hdu,
        reference_pixel,
        nearby_star_catalog,
        Sector=None,
        label='REFPIX DIAG',
    ):
        """
        Print a per-sector reference-pixel diagnostic comparing the pipeline
        reference pixel against the WCS-projected target RA/Dec.

        Parameters
        ----------
        ID : int or str
            TIC identifier.
        hdu : astropy.io.fits.HDUList
            Single-sector TESS FFI/TPF HDUList.
        reference_pixel : sequence of float
            Pipeline reference pixel for this sector. Expected convention should be
            [col, row] if using NumPy/WCS origin=0 coordinates.
        nearby_star_catalog : pandas.DataFrame
            Catalog containing the target row and RA/Dec columns.
        Sector : int or None, optional
            Sector label for logging only.
        label : str, optional
            Prefix used in diagnostic print statements.

        Returns
        -------
        None
            Prints diagnostics only.

        Examples
        --------
        >>> print_reference_pixel_diagnostic(
        ...     123, hdu, [5.0, 5.0], nearby_star_catalog, Sector=3
        ... )  # doctest: +SKIP
        """
        import numpy as np

        if hdu is None:
            print(f'  [{label}] S{Sector}: hdu is None; skipping.')
            return

        if reference_pixel is None:
            print(f'  [{label}] S{Sector}: reference_pixel is None; skipping.')
            return

        try:
            rp = np.asarray(reference_pixel, dtype=float).reshape(-1)
        except Exception as exc:
            print(f'  [{label}] S{Sector}: bad reference_pixel={reference_pixel!r}; {exc}')
            return

        if rp.size < 2 or not np.all(np.isfinite(rp[:2])):
            print(f'  [{label}] S{Sector}: non-finite reference_pixel={reference_pixel!r}')
            return

        target_row = nearby_star_catalog.loc[
            nearby_star_catalog['ID'].astype(str) == str(ID)
        ]

        if len(target_row) == 0:
            print(f'  [{label}] S{Sector}: TIC {ID} not found in nearby_star_catalog.')
            return

        ra_col = 'ra_TIC' if 'ra_TIC' in target_row.columns else 'ra'
        dec_col = 'dec_TIC' if 'dec_TIC' in target_row.columns else 'dec'

        try:
            ra = float(target_row[ra_col].iloc[0])
            dec = float(target_row[dec_col].iloc[0])
        except Exception as exc:
            print(f'  [{label}] S{Sector}: could not read RA/Dec; {exc}')
            return

        try:
            wcs = check_wcs(hdu)
            wcs_px = wcs.all_world2pix([[ra, dec]], 0)
        except Exception as exc:
            print(f'  [{label}] S{Sector}: WCS projection failed; {type(exc).__name__}: {exc}')
            return

        wcs_col = float(wcs_px[0, 0])
        wcs_row = float(wcs_px[0, 1])

        # Assumes reference_pixel = [col, row].
        ref_col = float(rp[0])
        ref_row = float(rp[1])

        print(f'  [{label}] S{Sector}: reference_pixel = col={ref_col:.3f}, row={ref_row:.3f}')
        print(f'  [{label}] S{Sector}: WCS(RA,Dec)->pix = col={wcs_col:.3f}, row={wcs_row:.3f}')
        print(f'  [{label}] S{Sector}: offset = col:{ref_col - wcs_col:+.3f}, '
              f'row:{ref_row - wcs_row:+.3f}')
    def _process_one_sector(Sector_, hdu_, CCD_, Camera_,
                            quality_mask_, reference_pixel_):
        """
        Run get_LC_from_FFI for a single sector.
        Returns a bundle dict (including 'sap_diag'), or None if no LC.

        Identity checks (added 10-03-2026). gethdu_lksearch has already
        verified the cutout's sector and position before this point.
        1. The cutout header is the requested sector (cheap repeat).
        2. The light curve's times are this cutout's times.
        3. The final_LC.csv on disk holds the same times.
        4. TESS_Sector_observation_check places the light curve's first and
           last times in the requested sector.
        If 2 to 4 fail, the extraction is rerun once from the same verified
        cutout. If they fail again, final_LC.csv is renamed to
        final_LC.IDENTITY_FAIL.csv, which collect_data_2026.py does not
        match, and None is returned.
        """
        if hdu_ is None:
            if verbose:
                print(f'Sector {Sector_}: HDU is None, skipping.')
            return None

        # identity check 1: the cutout is the requested sector
        _ident = verify_cutout_identity(hdu_[0].header, Sector_)
        if not _ident["ok"]:
            print(f"[identity] TIC {ID} S{Sector_}: cutout rejected: "
                  f"{'; '.join(_ident['reasons'])}")
            return None

        _stag = f'Sector_{Sector_:04d}'
        print(f'\nTIC {ID}  Sector {Sector_}')
        print(f'  CCD={CCD_}  Camera={Camera_}  hdu type={type(hdu_).__name__}')

        #diagnostic reference pixel check
        print_reference_pixel_diagnostic(
        ID=ID,
        hdu=hdu_,
        reference_pixel=reference_pixel_,
        nearby_star_catalog=nearby_star_catalog,
        Sector=Sector_,)
        #diagnostic reference pixel check

        _cut_t = hdu_[1].data['TIME']
        _ok = False
        for _try in (1, 2):
            # --- core call: now returns (LC_df, sap_diag) ---
            LC, sec_sap_diag = get_LC_from_FFI(
                ID, nearby_star_catalog, Sector_, cadence,
                hdu_, CCD_, Camera_, reference_pixel_, default_settings
            )
            slcp = default_settings.get('savelcpath')
            if LC is None:
                if _try == 1:
                    return None
                break

            # identity checks 2 to 4
            _final = slcp + f'TIC_{ID}_{_stag}_final_LC.csv'
            _lc_t = np.asarray(LC['Time'], dtype=float)
            _c2 = verify_lc_matches_cutout(_lc_t, _cut_t)
            _c3 = verify_written_lc(_final, _lc_t)
            _c4 = verify_lc_sector_by_time(_lc_t, Sector_)
            if verbose:
                for _n in _c3["notes"] + _c4["notes"]:
                    print(f"[identity] TIC {ID} S{Sector_}: note: {_n}")
            _bad = _c2["reasons"] + _c3["reasons"] + _c4["reasons"]
            if not _bad:
                _ok = True
                break
            print(f"[identity] TIC {ID} S{Sector_}: light curve check failed "
                  f"(try {_try}/2, matched {_c2['n_matched']}/{_c2['n_lc']}): "
                  f"{'; '.join(_bad)}")

        if not _ok:
            if os.path.isfile(_final):
                _q = _final[:-len('.csv')] + '.IDENTITY_FAIL.csv'
                os.replace(_final, _q)
                print(f"[identity] TIC {ID} S{Sector_}: renamed {_final} "
                      f"to {_q}; sector dropped")
            return None

        bundle = dict(
            LC          = LC,
            sap_diag    = sec_sap_diag,           # NEW
            Raw         = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_RAW_LC.csv'),
            Preclip     = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_final_LC_preclipped.csv'),
            Rawclip     = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_RAW_LC_systematics_removed.csv'),
            bad_ind     = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_bad_outliers.csv'),
            good_ind    = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_good_outliers.csv'),
        )

        if for_injections:
            try:
                bundle['inj_LC'] = pd.read_csv(
                    slcp + f'TIC_{ID}_{_stag}_TransitInjected_RAWLC.csv')
                bundle['inj_param'] = pd.read_csv(
                    slcp + f'TIC_{ID}_{_stag}_TransitInjected_param.csv')
            except FileNotFoundError:
                pass

        return bundle
    def _process_one_sector_OLD(Sector_, hdu_, CCD_, Camera_,
                            quality_mask_, reference_pixel_):
        """
        Run get_LC_from_FFI for a single sector.
        Returns a bundle dict (including 'sap_diag'), or None if no LC.
        """
        if hdu_ is None:
            if verbose:
                print(f'Sector {Sector_}: HDU is None — skipping.')
            return None

        _stag = f'Sector_{Sector_:04d}'
        print(f'\nTIC {ID}  Sector {Sector_}')
        print(f'  CCD={CCD_}  Camera={Camera_}  hdu type={type(hdu_).__name__}')
        
        #diagnostic reference pixel check
        print_reference_pixel_diagnostic(
        ID=ID,
        hdu=hdu_,
        reference_pixel=reference_pixel_,
        nearby_star_catalog=nearby_star_catalog,
        Sector=Sector_,)
        #diagnostic reference pixel check     

        # --- core call: now returns (LC_df, sap_diag) ---
        LC, sec_sap_diag = get_LC_from_FFI(
            ID, nearby_star_catalog, Sector_, cadence,
            hdu_, CCD_, Camera_, reference_pixel_, default_settings
        )
        slcp = default_settings.get('savelcpath')

        if LC is None:
            return None

        bundle = dict(
            LC          = LC,
            sap_diag    = sec_sap_diag,           # NEW
            Raw         = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_RAW_LC.csv'),
            Preclip     = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_final_LC_preclipped.csv'),
            Rawclip     = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_RAW_LC_systematics_removed.csv'),
            bad_ind     = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_bad_outliers.csv'),
            good_ind    = pd.read_csv(slcp + f'TIC_{ID}_{_stag}_good_outliers.csv'),
        )

        if for_injections:
            try:
                bundle['inj_LC'] = pd.read_csv(
                    slcp + f'TIC_{ID}_{_stag}_TransitInjected_RAWLC.csv')
                bundle['inj_param'] = pd.read_csv(
                    slcp + f'TIC_{ID}_{_stag}_TransitInjected_param.csv')
            except FileNotFoundError:
                pass

        return bundle

    # ─────────────────────────────────────────────────────────────────────────
    # Helper: concatenate a list of per-sector bundles into final DFs.
    # ─────────────────────────────────────────────────────────────────────────
    def _concat_bundles(bundles, hdus_list):
        LC_df         = pd.concat([b['LC']       for b in bundles], ignore_index=True)
        Raw_LC_df     = pd.concat([b['Raw']      for b in bundles], ignore_index=True)
        Rawclip_LC_df = pd.concat([b['Rawclip']  for b in bundles], ignore_index=True)
        Preclip_LC_df = pd.concat([b['Preclip']  for b in bundles], ignore_index=True)
        good_ind_df   = pd.concat([b['good_ind'] for b in bundles], ignore_index=True)
        bad_ind_df    = pd.concat([b['bad_ind']  for b in bundles], ignore_index=True)

        # aggregate SAP diagnostics across all sectors
        agg_sap_diag = _aggregate_sap_diags([b.get('sap_diag', {}) for b in bundles])

        inj_LCs    = None
        inj_params = None
        if for_injections:
            inj_list = [b['inj_LC']    for b in bundles if 'inj_LC'    in b]
            par_list = [b['inj_param'] for b in bundles if 'inj_param' in b]
            if inj_list:
                inj_LCs    = pd.concat(inj_list,  ignore_index=True)
                inj_params = pd.concat(par_list,  ignore_index=True)

        return (LC_df, Raw_LC_df, Rawclip_LC_df, Preclip_LC_df,
                good_ind_df, bad_ind_df, inj_LCs, inj_params,
                hdus_list, agg_sap_diag)

    # ─────────────────────────────────────────────────────────────────────────
    # BRANCH A: get_all_sectors == True  OR  Sector == None
    # ─────────────────────────────────────────────────────────────────────────
    if get_all_sectors or (Sector is None):
        print(f'TIC {ID} ; Getting All available NEMESIS Light Curves')

        if verbose:
            print('Step 0: Making Directories\n')
        Make_dirs(Sector, cadence, default_settings, return_paths=False)

        if verbose:
            cad_label = 'FFIs' if cadence in ('long', '30 minute', '10 minute') else 'TPFs'
            print(f'Step 1: Obtaining HDUs from {cad_label}\n')

        hdus_raw, CCDs_raw, Cameras_raw, qms_raw, rps_raw = gethdu(
            star, ID, Sector, cadence, default_settings)

        hdus, CCDs, Cameras, quality_masks, reference_pixels = (
            _normalize_gethdu_outputs(
                hdus_raw, CCDs_raw, Cameras_raw, qms_raw, rps_raw))

        if not any(h is not None for h in hdus):
            _ensure_hdu_or_raise(None, ID, Sector, cadence)
            return None, None, {}

        bundles    = []
        valid_hdus = []

        for S in range(len(hdus)):
            if hdus[S] is None:
                continue
            try:
                Sector_ = int(hdus[S][0].header['Sector'])
            except (KeyError, TypeError, IndexError):
                if verbose:
                    print(f'Index {S}: cannot read Sector from header — skipping.')
                continue

            bundle = _process_one_sector(
                Sector_,
                hdus[S], CCDs[S], Cameras[S],
                quality_masks[S], reference_pixels[S],
            )
            if bundle is not None:
                bundles.append(bundle)
                valid_hdus.append(hdus[S])

        if not bundles:
            return None, None, {}

        (LC_df, Raw_LC_df, Rawclip_LC_df, Preclip_LC_df,
         good_ind_df, bad_ind_df,
         all_inj_LCs, all_inj_params,
         hdu, agg_sap_diag) = _concat_bundles(bundles, valid_hdus)

    # ─────────────────────────────────────────────────────────────────────────
    # BRANCH B: Sector is a single int
    # ─────────────────────────────────────────────────────────────────────────
    elif isinstance(Sector, int):
        print(f'TIC {ID}  Sector {Sector} ; Now creating Light Curve')

        if verbose:
            print('Step 0: Making Directories\n')
        Make_dirs(Sector, cadence, default_settings, return_paths=False)

        if verbose:
            print('Step 1: Obtaining HDU from FFI/TPF\n')

        try:
            hdus_raw, CCDs_raw, Cameras_raw, qms_raw, rps_raw = gethdu(
                star, ID, Sector, cadence, default_settings)
        except AttributeError as AE:
            print(AE)
            return None, None, {}

        timer(start, clock.time(), 'gethdu took:')

        hdus, CCDs, Cameras, quality_masks, reference_pixels = (
            _normalize_gethdu_outputs(
                hdus_raw, CCDs_raw, Cameras_raw, qms_raw, rps_raw))

        if not any(h is not None for h in hdus):
            _ensure_hdu_or_raise(None, ID, Sector, cadence)
            return None, None, {}

        bundle = _process_one_sector(
            Sector,
            hdus[0], CCDs[0], Cameras[0],
            quality_masks[0], reference_pixels[0],
        )

        if bundle is None:
            return None, None, {}

        LC_df         = bundle['LC']
        Raw_LC_df     = bundle['Raw']
        Rawclip_LC_df = bundle['Rawclip']
        Preclip_LC_df = bundle['Preclip']
        good_ind_df   = bundle['good_ind']
        bad_ind_df    = bundle['bad_ind']
        all_inj_LCs   = bundle.get('inj_LC')
        all_inj_params= bundle.get('inj_param')
        agg_sap_diag  = bundle.get('sap_diag', {})   # NEW
        hdu           = hdus[0]

    # ─────────────────────────────────────────────────────────────────────────
    # BRANCH C: Sector is a list of ints
    # ─────────────────────────────────────────────────────────────────────────
    else:
        if verbose:
            print('Step 0: Making Directories\n')
        Make_dirs(Sector, cadence, default_settings, return_paths=False)

        bundles    = []
        valid_hdus = []

        for Sector_ in Sector:
            Sector_ = int(Sector_)
            print(f'\nTIC {ID}  Sector {Sector_}')

            if verbose:
                print('Step 1: Obtaining HDU from FFI/TPF\n')

            try:
                hdus_raw, CCDs_raw, Cameras_raw, qms_raw, rps_raw = gethdu(
                    star, ID, Sector_, cadence, default_settings)
            except AttributeError as AE:
                print(AE)
                continue

            timer(start, clock.time(), 'gethdu took:')

            hdus, CCDs, Cameras, quality_masks, reference_pixels = (
                _normalize_gethdu_outputs(
                    hdus_raw, CCDs_raw, Cameras_raw, qms_raw, rps_raw))

            if not any(h is not None for h in hdus):
                if verbose:
                    print(f'Sector {Sector_}: all HDUs None — skipping.')
                continue

            bundle = _process_one_sector(
                Sector_,
                hdus[0], CCDs[0], Cameras[0],
                quality_masks[0], reference_pixels[0],
            )
            if bundle is not None:
                bundles.append(bundle)
                valid_hdus.append(hdus[0])

        if not bundles:
            return None, None, {}

        (LC_df, Raw_LC_df, Rawclip_LC_df, Preclip_LC_df,
         good_ind_df, bad_ind_df,
         all_inj_LCs, all_inj_params,
         hdu, agg_sap_diag) = _concat_bundles(bundles, valid_hdus)

    # ─────────────────────────────────────────────────────────────────────────
    # Multi-sector summary plot
    # ─────────────────────────────────────────────────────────────────────────
    if get_all_sectors or Sector is None or isinstance(Sector, list):
        sectors_for_plot = []
        if isinstance(hdu, list):
            for h in hdu:
                if h is not None:
                    try:
                        sectors_for_plot.append(int(h[0].header['Sector']))
                    except Exception:
                        pass
        if sectors_for_plot:
            plot_it_all_up(
                ID=ID,
                nearby_star_catalog=nearby_star_catalog,
                Sector=sectors_for_plot,          # list of ints
                cadence=cadence,
                hdu=hdu,                          # list of HDULists
                RAWLC_df=Raw_LC_df,
                clippedRAWLC_df=Rawclip_LC_df,
                LC_df=LC_df,
                good_ind_DF=good_ind_df,
                bad_ind_DF=bad_ind_df,
                preclipLC_df=Preclip_LC_df,
                default_settings=default_settings,
                # SAP diagnostics from aggregated dict
                bkg_level_per_pix=agg_sap_diag.get('bkg_level_per_pix'),
                bkg_trend=agg_sap_diag.get('bkg_trend'),
                bkg_residuals=agg_sap_diag.get('bkg_residuals'),
                quat_jitter=agg_sap_diag.get('quat_jitter'),
                quat_status=agg_sap_diag.get('quat_status', 'not provided'),
                qlp_result=agg_sap_diag.get('qlp_result'),
                quality_flag=agg_sap_diag.get('quality_flag'),
            )

    # ─────────────────────────────────────────────────────────────────────────
    # Final checks and saves
    # ─────────────────────────────────────────────────────────────────────────
    if LC_df is None or LC_df.empty:
        print(f'No valid light curves extracted for TIC {ID}.')
        return None, None, {}

    LC_df         = LC_df.sort_values('Time').reset_index(drop=True)
    Raw_LC_df     = Raw_LC_df.sort_values('Time').reset_index(drop=True)
    Rawclip_LC_df = Rawclip_LC_df.sort_values('Time').reset_index(drop=True)
    Preclip_LC_df = Preclip_LC_df.sort_values('Time').reset_index(drop=True)
    good_ind_df   = good_ind_df.sort_values('Time').reset_index(drop=True)
    bad_ind_df    = bad_ind_df.sort_values('Time').reset_index(drop=True)

    savelcpath = default_settings.get('savelcpath')

    if get_all_sectors or not isinstance(Sector, int):
        df_len_check(LC_df, message='Multi-Sector NEMESIS Light Curve Lengths: ')
        if verbose:
            print(f'Saving LC to {savelcpath}TIC_{ID}_Multi_Sector_final_LC.csv')
        LC_df.to_csv(
            savelcpath + f'TIC_{ID}_Multi_Sector_final_LC.csv', index=False)
        Raw_LC_df.to_csv(
            savelcpath + f'TIC_{ID}_Multi_Sector_RAW_LC.csv', index=False)
        Rawclip_LC_df.to_csv(
            savelcpath + f'TIC_{ID}_Multi_Sector_RAW_LC_systematics_removed.csv',
            index=False)
        Preclip_LC_df.to_csv(
            savelcpath + f'TIC_{ID}_Multi_Sector_final_LC_preclipped.csv',
            index=False)
        good_ind_df.to_csv(
            savelcpath + f'TIC_{ID}_Multi_Sector_good_outliers.csv', index=False)
        bad_ind_df.to_csv(
            savelcpath + f'TIC_{ID}_Multi_Sector_bad_outliers.csv', index=False)
        if for_injections and all_inj_LCs is not None:
            all_inj_LCs.to_csv(
                savelcpath + f'TIC_{ID}_Multi_Sector_TransitInjected_RAWLC.csv',
                index=False)
            all_inj_params.to_csv(
                savelcpath + f'TIC_{ID}_Multi_Sector_TransitInjected_param.csv',
                index=False)

    timer(start, clock.time(), 'NEMESIS Light Curve production took:')
    print('')
    return hdu, LC_df, agg_sap_diag
