    try:
        EDI_results = pd.DataFrame({'ID':ID,'Sector':Sector_str,'Flux Contamination':params.fluxContaminationFP, 'Too Many Transits Masked':params.TransMaskFP, 'Odd/Even Transit Variation':params.even_odd_transit_misfit,'Signal is not Unique':params.uniquenessFP,'Secondary Eclipse Found':params.SeFP,'Low Transit Phase Coverage':params.phaseCoverFP, 'Transit Duration Too Long':params.tdurFP, 'Signal is a False Positive':params.FalsePositive},index=[0])
    except AttributeError:
        EDI_results = pd.DataFrame({'ID':ID,'Sector':Sector_str,'Flux Contamination':params.fluxContamFP, 'Too Many Transits Masked':params.transMaskFP, 'Odd/Even Transit Variation':params.evenOddFP,'Signal is not Unique':params.uniqueFP,'Secondary Eclipse Found':params.secEclipseFP,'Low Transit Phase Coverage':params.phaseCoverFP, 'Transit Duration Too Long':params.tranDurFP, 'Signal is a False Positive':params.FalsePositive},index=[0])   
    return EDI_results
