#
def intransit_stats(input_LC, TransitParams_df):    
    """
    Compute per-transit and odd/even transit statistics for a BLS or TLS result.

    Accepts either BLS or TLS best-fit parameters (auto-detected via column
    names) and computes in-transit flux statistics for every individual
    transit event, as well as odd- and even-numbered transit aggregates
    for the odd/even depth mismatch test.

    Parameters
    ----------
    input_LC : pd.DataFrame
        Detrended light curve.  Required columns: ``Time``, ``Flux``.
    TransitParams_df : pd.DataFrame
        Single-row best-fit parameter DataFrame from ``BLS_func`` or
        ``TLS_func``.  Must contain either:
        ``BLS Period [d]``, ``BLS TC [BTJD]``, ``BLS Dur [hrs]``
        (for BLS), or
        ``TLS Period [d]``, ``TLS TC [BTJD]``, ``TLS Dur [hrs]``
        (for TLS).  The algorithm-type is detected automatically via
        column presence.

    Returns
    -------
    transit_stat_dict : dict
        Dictionary with the following keys:

        ``snr`` : float
            Overall transit SNR computed as
            depth / (out-of-transit scatter / sqrt(N_in_transit)).
        ``depth_mean_odd`` : float
            Mean in-transit flux depth for odd-numbered transits
            (1-indexed).
        ``depth_mean_even`` : float
            Mean in-transit flux depth for even-numbered transits.
        ``depth_mean_odd_std`` : float
            Standard deviation of odd transit depths.
        ``depth_mean_even_std`` : float
            Standard deviation of even transit depths.
        ``all_flux_intransit_odd`` : np.ndarray
            All flux values during odd transits, concatenated.
        ``all_flux_intransit_even`` : np.ndarray
            All flux values during even transits, concatenated.
        ``per_transit_count`` : np.ndarray, shape (N_transits,)
            Number of in-transit data points per individual transit event.
        ``transit_depths`` : np.ndarray, shape (N_transits,)
            Mean flux depth (1 − mean_flux) for each transit.
        ``transit_depths_uncertainties`` : np.ndarray, shape (N_transits,)
            Uncertainty on each transit depth (std / sqrt(N_in_transit)).
        ``transit_times`` : list of float
            Mid-transit times in BTJD for all predicted transit events
            within the light curve time span.
        ``snr_per_transit`` : np.ndarray, shape (N_transits,)
            Per-transit SNR using white-noise estimate
            (depth / (out-of-transit std / sqrt(N_in_transit))).
        ``snr_pink_per_transit`` : np.ndarray, shape (N_transits,)
            Per-transit SNR using a pink-noise (correlated noise) estimate.

    Examples
    --------
    >>> stats = intransit_stats(input_LC, BLSbestfitdf)
    >>> print(f"Overall SNR: {stats['snr']:.2f}")
    >>> print(f"Odd depth: {stats['depth_mean_odd']:.4f} ± "
    ...       f"{stats['depth_mean_odd_std']:.4f}")
    """
    
    t = np.array(input_LC['Time'])
    y = np.array(input_LC['Flux'])    
    
    try:
        P = TransitParams_df['BLS Period [d]'].item()
        T0 =TransitParams_df['BLS TC [BTJD]'].item()
        Dur=TransitParams_df['BLS Dur [hrs]'].item()        
    except KeyError: #then input is TLS
        P = TransitParams_df['TLS Period [d]'].item()
        T0 =TransitParams_df['TLS TC [BTJD]'].item()
        Dur=TransitParams_df['TLS Dur [hrs]'].item()        
    transit_times = all_transit_times(T0, t, P)
    transit_duration = Dur
    import astropy.units as u
    transit_duration_in_days = (Dur*u.hour).to(u.day).value
    period=P
    import numpy
    from transitleastsquares.helpers import transit_mask
    all_flux_intransit_odd = numpy.array([])
    all_flux_intransit_even = numpy.array([])
    all_flux_intransit = numpy.array([])
    all_idx_intransit = numpy.array([])
    per_transit_count = numpy.zeros([len(transit_times)])
    transit_depths = numpy.zeros([len(transit_times)])
    transit_depths_uncertainties = numpy.zeros([len(transit_times)])

    for i in range(len(transit_times)):

        depth_mean_odd = numpy.nan
        depth_mean_even = numpy.nan
        depth_mean_odd_std = numpy.nan
        depth_mean_even_std = numpy.nan

        mid_transit = transit_times[i]
        tmin = mid_transit - 0.5 * transit_duration_in_days
        tmax = mid_transit + 0.5 * transit_duration_in_days
        if numpy.isnan(tmin) or numpy.isnan(tmax):
            idx_intransit = []
            flux_intransit = []
            mean_flux = numpy.nan
        else:
            idx_intransit = numpy.where(numpy.logical_and(t > tmin, t < tmax))
            flux_intransit = y[idx_intransit]
            if len(y[idx_intransit]) > 0:
                mean_flux = numpy.mean(y[idx_intransit])
            else:
                mean_flux = numpy.nan
        intransit_points = numpy.size(y[idx_intransit])
        transit_depths[i] = mean_flux
        if len(y[idx_intransit] > 0):
            transit_depths_uncertainties[i] = numpy.std(y[idx_intransit]) / numpy.sqrt(
                intransit_points
            )
        else:
            transit_depths_uncertainties[i] = numpy.nan
        per_transit_count[i] = intransit_points

        # Check if transit odd/even to collect the flux for the mean calculations
        if i % 2 == 0:  # even
            all_flux_intransit_even = numpy.append(
                all_flux_intransit_even, flux_intransit
            )
        else:  # odd
            all_flux_intransit_odd = numpy.append(
                all_flux_intransit_odd, flux_intransit
            )
        if len(all_flux_intransit_odd) > 0:
            depth_mean_odd = numpy.mean(all_flux_intransit_odd)

            depth_mean_odd_std = numpy.std(all_flux_intransit_odd) / numpy.sum(
                len(all_flux_intransit_odd)
            ) ** (0.5)
        if len(all_flux_intransit_even) > 0:
            depth_mean_even = numpy.mean(all_flux_intransit_even)
            depth_mean_even_std = numpy.std(all_flux_intransit_even) / numpy.sum(
                len(all_flux_intransit_even)
            ) ** (0.5)
            
    all_flux_intransit = numpy.concatenate([all_flux_intransit_odd, all_flux_intransit_even])
    depth_mean = numpy.nanmean(all_flux_intransit)
    depth_mean_std = numpy.nanstd(all_flux_intransit) / numpy.nansum(per_transit_count) ** (0.5)
    intransit = transit_mask(t, period, 2 * transit_duration, T0) # cut in hours around transits, not days
    flux_ootr = y[~intransit]
    snr = ((1 - depth_mean) / numpy.nanstd(flux_ootr)) * len(all_flux_intransit) ** (0.5)
    ####
    def snr_stats(input_LC,TransitParams_df,transit_times,per_transit_count):
        """Return snr_per_transit and snr_pink_per_transit"""

        t = np.array(input_LC['Time'])
        y = np.array(input_LC['Flux'])    

        try:
            P = TransitParams_df['BLS Period [d]'].item()
            T0= TransitParams_df['BLS TC [BTJD]'].item()
            Dur=TransitParams_df['BLS Dur [hrs]'].item()        
        except KeyError: #then input is TLS
            P = TransitParams_df['TLS Period [d]'].item()
            T0 =TransitParams_df['TLS TC [BTJD]'].item()
            Dur=TransitParams_df['TLS Dur [hrs]'].item() 
        transit_duration = Dur
        import astropy.units as u
        transit_duration_in_days = (Dur*u.hour).to(u.day).value
        period = P
        import numpy
        snr_per_transit = numpy.zeros([len(transit_times)])
        snr_pink_per_transit = numpy.zeros([len(transit_times)])
        intransit = transit_mask(t, period, 2 * transit_duration, T0) # cut in hours around transits, not days
        flux_ootr = y[~intransit]
        #
        def pink_noise(data, width):
            import numpy
            std = 0
            datapoints = len(data) - width + 1
            if datapoints>0:
                for i in range(datapoints):
                    std += numpy.nanstd(data[i : i + width]) / width ** 0.5
                return std / datapoints
            else:
                for i in range(np.abs(datapoints)):
                    std += numpy.nanstd(data[i : i + width]) / width ** 0.5
                return std / np.abs(datapoints)
        #
        pinknoise = pink_noise(flux_ootr, int(numpy.nanmean(per_transit_count)))
        # Estimate SNR and pink SNR
        # Second run because now the out of transit points are known
        if len(flux_ootr) > 0:
            std = numpy.nanstd(flux_ootr)
        else:
            std = numpy.nan
        for i in range(len(transit_times)):
            mid_transit = transit_times[i]
            tmin = mid_transit - 0.5 * transit_duration_in_days
            tmax = mid_transit + 0.5 * transit_duration_in_days
            if numpy.isnan(tmin) or numpy.isnan(tmax):
                idx_intransit = []
                mean_flux = numpy.nan
            else:
                idx_intransit = numpy.where(numpy.logical_and(t > tmin, t < tmax))
                if len(y[idx_intransit]) > 0:
                    mean_flux = numpy.nanmean(y[idx_intransit])
                else:
                    mean_flux = numpy.nan
            intransit_points = numpy.size(y[idx_intransit])
            try:
                snr_pink_per_transit[i] = (1 - mean_flux) / pinknoise
                if intransit_points > 0 and not numpy.isnan(std):
                    std_binned = std / intransit_points ** 0.5
                    snr_per_transit[i] = (1 - mean_flux) / std_binned
                else:
                    snr_per_transit[i] = 0
                    snr_pink_per_transit[i] = 0
            except:
                snr_per_transit[i] = 0
                snr_pink_per_transit[i] = 0

        return snr_per_transit, snr_pink_per_transit

    snr_per_transit, snr_pink_per_transit = snr_stats(input_LC,TransitParams_df,\
                                                      transit_times,per_transit_count)
    
    transit_stat_dict = dict({'snr':snr,'depth_mean_odd':depth_mean_odd, 'depth_mean_even':depth_mean_even,\
                             'depth_mean_odd_std':depth_mean_odd_std,'depth_mean_even_std':depth_mean_even_std,\
                             'all_flux_intransit_odd':all_flux_intransit_odd,'all_flux_intransit_even':all_flux_intransit_even,\
                             'per_transit_count':per_transit_count,'transit_depths':transit_depths,\
                              'transit_depths_uncertainties':transit_depths_uncertainties,\
                             'transit_times':transit_times,'snr_per_transit':snr_per_transit, \
                              'snr_pink_per_transit':snr_pink_per_transit})
    
    return transit_stat_dict
