# for determining minimum trial duration in fractional transit duration grid
def find_min_trial_duration(input_LC,durations,periods): #not sure if helpful, UNUSED
    # this function takes the duration_grid and period_grid
    # provided by TLS' functions (which are based on stellar params)
    #
    def Special_Bin_func(time,flux,error,binsize):  #<-- doesn't allow empty bins to exist
        import math
        good = np.where(np.isfinite(time)) #finds values that are not +/- inf, NaN
        timefit = time[good]
        fluxfit = flux[good]
        errfit  = error[good]
        timemax = np.max(timefit)
        timemin = np.min(timefit)
        npoints = len(timefit)
        nbins   = int(math.ceil((timemax - timemin)/binsize)) #binsize in days
        bintime = np.full((nbins,), np.nan) #fills array with NaNs to be filled with values
        binflux = np.full((nbins,), np.nan)
        binerr  = np.full((nbins,), np.nan)
        for i in range(0,nbins-1):
            #tobin = [np.where( (timefit >= (timemin + i*binsize)) & (timefit < (timemin + (i+1)*binsize)) )]
#             if len(tobin[0][0]) != 0:            
            tobin = np.where( (timefit >= (timemin + i*binsize)) & (timefit < (timemin + (i+1)*binsize)) )[0]
            if len(tobin) != 0:                
                # inverse variance weighted means
                binflux[i] = ((fluxfit[tobin]/(errfit[tobin]**2.0)).sum()) / ((1.0/errfit[tobin]**2.0).sum())
                bintime[i] = ((timefit[tobin]/(errfit[tobin]**2.0)).sum()) / ((1.0/errfit[tobin]**2.0).sum())
                binerr[i]  = 1.0 / (np.sqrt( (1.0/errfit[tobin]**2.0)).sum() )
        #
        return bintime, binflux, binerr
    #
    def calc_phase_coverage(input_LC,trial_duration,trial_period):
        t,f,e = np.array(input_LC['Time']),np.array(input_LC['Flux']),np.array(input_LC['Error'])
        T0 = np.nanmin(t)
        pf,ff = phasefold(T0,t,trial_period,f)
        binpf,binff,binfe = Special_Bin_func(pf,ff,e,binsize=trial_duration)
        ntotal=len(binpf)
        fin_bin = len(np.where(np.isfinite(binpf))[0])
        phase_coverage = fin_bin / ntotal
        return phase_coverage
    #
    # calculate phase coverage for input lightcurve
    phase_coverage = np.empty(np.size(durations))
    #do min P only
    for c in range(len(phase_coverage)):
        pc = calc_phase_coverage(input_LC,\
                                 trial_duration=durations[c],\
                                 trial_period=np.min(periods))
        phase_coverage[c] = pc
        
    q_ind = np.where(phase_coverage==np.quantile(phase_coverage,0.25,method='nearest'))[0][0]
    min_trial_duration = durations[q_ind]

    if min_trial_duration < (np.nanmedian(np.diff(input_LC['Time']))/2):
        #print('min duration < half cadence!')
        min_trial_duration = (np.nanmedian(np.diff(input_LC['Time'])))*3

    durations=np.array(durations)
    new_durations = durations[durations>=min_trial_duration]
    new_durations = new_durations.tolist()
    
    return new_durations
#
def ResampleLinear1D(periods, targetLength):
    original = np.array(periods, dtype=float)
    index_arr = np.linspace(0, len(periods)-1, num=targetLength, dtype=float)
    index_floor = np.array(index_arr, dtype=int) #Round down
    index_ceil = index_floor + 1
    index_rem = index_arr - index_floor #Remain

    val1 = original[index_floor]
    val2 = original[index_ceil % len(original)]
    new_periods = val1 * (1.0-index_rem) + val2 * index_rem
    assert(len(new_periods) == targetLength)
    return new_periods
#
def optimize_period_duration_grid_sizes(periods,durations,
                                        downsample_by_N_percent,
                                        cadence_of_observations): #not sure if useful/helpful, UNUSED
    #
    print('before adjustment, period grid length = ',f'{len(periods):,}')
    new_periods = ResampleLinear1D(periods, targetLength=int(len(periods)*downsample_by_N_percent))
    print('after adjustment, period grid length = ',f'{len(new_periods):,}')
    print(' ')
    N_dur = 3
    print('before adjustment, duration grid length = ',f'{len(durations):,}')
    new_durations=N_dur*np.array(durations) #adjust duration grid to be longer
    #duration grid cut of unnecessarily short durations on time scales of cadence
    new_durations= new_durations[new_durations > 5*cadence_of_observations]
    print('before adjustment, duration grid length = ',f'{len(new_durations):,}')
    return new_periods, new_durations
#
def compute_sde_optimized(periodogram_power):
    """
    Computes an array of SDE values, ensuring that max(SDE array) matches the classical SDE.

    Parameters:
    - periodogram_power (array-like): Power values from a BLS or TLS periodogram.

    Returns:
    - sde_values (np.ndarray): Array of SDE values.
    """
    P_max = np.max(periodogram_power)  # Maximum power value
    P_mean = np.mean(periodogram_power)  # Mean power
    P_std = np.std(periodogram_power)  # Standard deviation of power

    # Avoid division by zero
    if P_std == 0:
        return np.full_like(periodogram_power, np.nan)

    # Compute an adjusted SDE array that ensures max(SDE_array) = classical SDE
    sde_values = (periodogram_power - P_mean) / P_std

    return sde_values

