from typing import Any, Dict, Optional, Tuple
import numpy as np

def refine_transit_epoch_post_search(
    time: np.ndarray,
    flux: np.ndarray,
    t0_initial: float,
    period_days: float,
    duration_days: float,
    error: Optional[np.ndarray] = None,
    search_width_factor: float = 3.0,
    max_search_days: Optional[float] = None,
    max_search_period_fraction: float = 0.10,
    samples_per_duration: int = 15,
    min_in_transit_cadences: int = 3,
    min_depth: float = 0.0,
    min_snr: float = 0.0,
    min_score_improvement: float = 0.0,
    return_diagnostics: bool = True,
) -> Tuple[float, float, Dict[str, Any]]:
    """
    Refine a detected transit epoch after BLS/TLS using a guarded
    box-matched depth/SNR score.

    The returned T0 is anchored to the first predicted transit at or after
    min(time), which matches NEMESIS' current downstream expectation.

    Parameters
    ----------
    time, flux : np.ndarray
        Detrended light curve arrays. Flux should be normalized near 1.
    t0_initial : float
        Initial detected epoch in BTJD.
    period_days : float
        Orbital period in days.
    duration_days : float
        Transit duration in days.
    error : np.ndarray or None
        Flux uncertainties. If None or invalid, unit weights are used.
    search_width_factor : float
        Half-width of local T0 search in units of duration.
    max_search_days : float or None
        Optional hard cap on half-width in days.
    max_search_period_fraction : float
        Hard cap on half-width as a fraction of period.
    samples_per_duration : int
        Grid density across one transit duration.
    min_in_transit_cadences : int
        Minimum total in-transit cadences required at a trial epoch.
    min_depth : float
        Minimum accepted depth in normalized flux units.
    min_snr : float
        Minimum accepted matched-filter SNR.
    min_score_improvement : float
        Required improvement over the initial T0 score.
    return_diagnostics : bool
        Kept for API symmetry; diagnostics are always returned.

    Returns
    -------
    t0_refined : float
        First refined transit epoch at or after min(time).
    dt_hours : float
        Signed in-period offset from the initial epoch, in hours.
    diagnostics : dict
        Status and scoring details.

    Examples
    --------
    >>> t = np.linspace(0, 10, 1000)
    >>> f = np.ones_like(t)
    >>> f[np.abs(((t - 2.05 + 1.5) % 3.0) - 1.5) < 0.05] -= 0.01
    >>> t0, dt, diag = refine_transit_epoch_post_search(t, f, 2.0, 3.0, 0.10)
    >>> abs(t0 - 2.05) < 0.03
    True
    >>> diag["status"] in {"ok", "no_improvement"}
    True
    """
    time = np.asarray(time, dtype=float)
    flux = np.asarray(flux, dtype=float)

    finite = np.isfinite(time) & np.isfinite(flux)
    if error is not None:
        error = np.asarray(error, dtype=float)
        finite &= np.isfinite(error) & (error > 0)

    if finite.sum() < min_in_transit_cadences:
        return float(t0_initial), 0.0, {
            "status": "insufficient_finite_lc",
            "n_finite": int(finite.sum()),
        }

    t = time[finite]
    y = flux[finite]

    if error is None:
        w = np.ones_like(y)
    else:
        e = error[finite]
        w = 1.0 / np.square(e)
        if not np.all(np.isfinite(w)) or np.nanmax(w) <= 0:
            w = np.ones_like(y)

    if not np.isfinite(period_days) or period_days <= 0:
        return float(t0_initial), 0.0, {"status": "invalid_period"}

    if not np.isfinite(duration_days) or duration_days <= 0:
        return float(t0_initial), 0.0, {"status": "invalid_duration"}

    half_width = search_width_factor * duration_days
    half_width = min(half_width, max_search_period_fraction * period_days)
    if max_search_days is not None:
        half_width = min(half_width, float(max_search_days))

    if half_width <= 0:
        return float(t0_initial), 0.0, {"status": "invalid_search_width"}

    cadence = np.nanmedian(np.diff(np.sort(t)))
    grid_step = min(duration_days / max(samples_per_duration, 1), cadence / 2.0)
    if not np.isfinite(grid_step) or grid_step <= 0:
        grid_step = duration_days / max(samples_per_duration, 1)

    offsets = np.arange(-half_width, half_width + 0.5 * grid_step, grid_step)
    if offsets.size == 0:
        offsets = np.array([0.0])

    def _phase_days(t0_trial: float) -> np.ndarray:
        return ((t - t0_trial + 0.5 * period_days) % period_days) - 0.5 * period_days

    def _weighted_mean(values: np.ndarray, weights: np.ndarray) -> float:
        sw = np.nansum(weights)
        if not np.isfinite(sw) or sw <= 0:
            return np.nan
        return float(np.nansum(values * weights) / sw)

    def _score(offset: float) -> Dict[str, Any]:
        ph = _phase_days(t0_initial + offset)
        in_tr = np.abs(ph) <= 0.5 * duration_days
        side = (
            (np.abs(ph) >= 1.5 * duration_days)
            & (np.abs(ph) <= 4.0 * duration_days)
        )

        if int(in_tr.sum()) < min_in_transit_cadences:
            return {
                "score": -np.inf,
                "depth": np.nan,
                "snr": np.nan,
                "n_in": int(in_tr.sum()),
            }

        # Fall back to broad out-of-transit baseline if local sidebands are sparse.
        if int(side.sum()) < min_in_transit_cadences:
            side = np.abs(ph) > 1.5 * duration_days

        if int(side.sum()) < min_in_transit_cadences:
            return {
                "score": -np.inf,
                "depth": np.nan,
                "snr": np.nan,
                "n_in": int(in_tr.sum()),
            }

        baseline = _weighted_mean(y[side], w[side])
        in_mean = _weighted_mean(y[in_tr], w[in_tr])
        depth = baseline - in_mean

        oot = y[side] - baseline
        scatter = 1.4826 * np.nanmedian(np.abs(oot - np.nanmedian(oot)))
        if not np.isfinite(scatter) or scatter <= 0:
            scatter = np.nanstd(oot)

        if not np.isfinite(scatter) or scatter <= 0:
            return {
                "score": -np.inf,
                "depth": float(depth) if np.isfinite(depth) else np.nan,
                "snr": np.nan,
                "n_in": int(in_tr.sum()),
            }

        snr = depth / (scatter / np.sqrt(int(in_tr.sum())))
        return {
            "score": float(snr),
            "depth": float(depth),
            "snr": float(snr),
            "n_in": int(in_tr.sum()),
        }

    score0 = _score(0.0)
    scores = [_score(float(off)) for off in offsets]
    best_index = int(np.nanargmax([s["score"] for s in scores]))
    best_offset = float(offsets[best_index])
    best = scores[best_index]

    accept = (
        np.isfinite(best["score"])
        and best["n_in"] >= min_in_transit_cadences
        and best["depth"] >= min_depth
        and best["snr"] >= min_snr
        and (best["score"] - score0["score"]) >= min_score_improvement
    )

    if not accept:
        return float(t0_initial), 0.0, {
            "status": "no_improvement",
            "initial_score": score0,
            "best_score": best,
            "half_width_days": float(half_width),
            "grid_step_days": float(grid_step),
        }

    t0_local = float(t0_initial + best_offset)

    # Anchor to first predicted transit at or after min(time).
    n_first = int(np.ceil((np.nanmin(t) - t0_local) / period_days))
    t0_refined = t0_local + n_first * period_days
    if t0_refined < np.nanmin(t) - 1e-10:
        t0_refined += period_days

    # Signed local offset, not the potentially many-period anchor difference.
    dt_hours = best_offset * 24.0

    return float(t0_refined), float(dt_hours), {
        "status": "ok",
        "initial_score": score0,
        "best_score": best,
        "half_width_days": float(half_width),
        "grid_step_days": float(grid_step),
        "offset_days": float(best_offset),
        "offset_hours": float(dt_hours),
    }
#
#
#
def BLS_func(ID, nearby_star_catalog, Sector,cadence,hdu,
             time,flux,error, default_settings):
    """
    Run the Astropy BLS algorithm and assemble all NEMESIS transit search outputs.

    Constructs a period grid from stellar parameters and the light curve
    time span, runs ``astropy.timeseries.BoxLeastSquares``, computes the
    SDE power spectrum, derives physical transit and stellar parameters,
    calls ``intransit_stats`` for per-transit statistics, and saves all
    results to CSV files.

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``.  Required
        columns: ``ID``, ``rad``, ``mass``, ``Teff``, ``logg``,
        ``Tmag``, ``Vmag``, ``GAIAmag``, ``rmag``, ``imag``, ``zmag``,
        ``Jmag``, ``Hmag``, ``Kmag``, ``rho``, ``d``, ``ra``/``ra_TIC``,
        ``dec``/``dec_TIC``.
    Sector : int, list, or None
        Sector(s) being processed; used for output filenames.
    cadence : str
        TESS exposure cadence string.
    hdu : fits.HDUList or list of fits.HDUList
        Raw FITS data; used to extract momentum dump times.
    time : np.ndarray, shape (T,)
        Timestamps in BTJD.
    flux : np.ndarray, shape (T,)
        Normalized detrended flux (median ≈ 1).
    error : np.ndarray, shape (T,)
        Per-cadence flux uncertainty.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``minP``, ``maxP``,
        ``N_transits``, ``oversampling_factor``, ``duration_grid_step``,
        ``get_all_sectors``, ``use_sources_in_aperture``,
        ``for_injections``, ``inject_param_P_RP_T0``, ``verbose``,
        ``saveReportpath_BLS``, ``savelcpath``.

    Returns
    -------
    BLSdf : pd.DataFrame or None
        BLS periodogram.  Columns:
        ``BLS Periods`` (days), ``BLS Power``, ``BLS SDE``
        (= (power − median) / std).
    BLSmodeldf : pd.DataFrame or None
        Best-fit BLS box model.  Columns: ``Time``, ``Model``.
    BLSbestfitdf : pd.DataFrame or None
        Best-fit BLS parameters (single-row).  Columns:
        ``BLS Period [d]``, ``BLS Period Error``, ``BLS TC [BTJD]``,
        ``BLS depth [ppt]``, ``BLS depth Error``, ``BLS SDE``,
        ``BLS FAP`` (always NaN), ``BLS Dur [hrs]``,
        ``BLS Odd Even Mismatch``, ``BLS Transit Count``,
        ``BLS Distinct Transit Count``, ``BLS SNR``, ``RP_RS``,
        ``Planet Radius [RE]``, ``Planet Radius Error``,
        ``q_transit``, ``a_over_R_star``,
        ``CDPP [ppm/sqrt hr]``, ``Time Span [d]``,
        ``Stellar Radius [RS]``, ``Stellar Mass [MS]``, ``Teff [K]``,
        ``Flux Contamination Ratio``,
        ``Vmag``, ``TESSmag``, ``rmag``, ``imag``, ``zmag``,
        ``Jmag``, ``Hmag``, ``Kmag``,
        ``Momentum Dump Rate [d]``, ``RA``, ``DEC``,
        ``logg``, ``rho [g/ccm]``, ``dist [pc]``.
    BLSTCsdf : pd.DataFrame or None
        Per-transit statistics.  Columns:
        ``BLS TCs [BTJD]``, ``BLS Depths``, ``BLS Depths Error``,
        ``SNR Per Transit``, ``SNR Pink Per Transit``.

    Notes
    -----
    Returns ``None`` (implicitly, by falling through) if either ``R_star``
    or ``M_star`` is NaN — BLS requires physical stellar parameters to
    compute transit depth → planet radius.

    Saved outputs (to ``saveReportpath_BLS``)
    -----------------------------------------
    ``TIC_{ID}_{sector_tag}_BLS.csv``
    ``TIC_{ID}_{sector_tag}_BLS_model.csv``
    ``TIC_{ID}_{sector_tag}_BLS_bestfit.csv``
    ``TIC_{ID}_{sector_tag}_BLS_TCs.csv``
    """      
    # get function settings
    N_transits = default_settings.get('N_transits')
    minP = default_settings.get('minP')
    oversampling_factor = default_settings.get('oversampling_factor')
    duration_grid_step = default_settings.get('duration_grid_step')
    #
    path = default_settings.get('path')
    savefigpath = default_settings.get('savefigpath')
    savelcpath= default_settings.get('savelcpath')
    downloadpath= default_settings.get('downloadpath')
    saveReportpath = default_settings.get('saveReportpath_BLS')
    #
    get_all_sectors = default_settings.get('get_all_sectors')
    use_sources_in_aperture = default_settings.get('use_sources_in_aperture')
    for_injections = default_settings.get('for_injections')
    verbose = default_settings.get('verbose')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    maxP = default_settings.get('maxP')
    
    #Step 0: create string tag for sector usage
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"        
    #
    from astropy.timeseries import BoxLeastSquares
    #for reporting BLS model's planet radius
    from astropy import units as u
    import pandas as pd
    R_earth = u.R_earth.to(u.cm)
    R_sun = u.R_sun.to(u.cm)
    if verbose==True:
        print('Beginning BLS transit search')
    ###
    ###
    # calculate CDPP (in ppm per sqrt hour) to save later
    cad = np.nanmedian(np.diff(time[np.isfinite(time)]))
    cdpp = CDPP(time,flux,error,'median','ppm',cad,binsize=(1.0/24.0))
    time_span = np.nanmax(time) - np.nanmin(time)
    #
    from transitleastsquares import period_grid,duration_grid#, catalog_info
    #
    star = nearby_star_catalog.loc[nearby_star_catalog['ID']==str(ID)].reset_index(drop=True)
    star = get_qld(star,verbose)    
    R_star, M_star = star['rad'].item(),star['mass'].item()
    R_star_min, M_star_min = star['e_rad'].item(),star['e_mass'].item()
    R_star_max, M_star_max = R_star_min, M_star_min
    qld = [star['qld_a'].item(), star['qld_b'].item()]
    #
    # First lets make the grid
    # lets pick min/max of orbital period grid
    if maxP is None:
        maxP = time_span/N_transits #orbital periods for grid
    #
    periods = period_grid(R_star=R_star, M_star=M_star, time_span=time_span,\
                          period_min=minP, period_max=maxP,oversampling_factor=oversampling_factor)
    durations= duration_grid(periods,shortest=None,log_step=duration_grid_step)
    
    durations = [d for d in durations if d >= N_transits*cad]
    
    input_LC=pd.DataFrame({'Time':time,'Flux':flux,'Error':error})
    # short cadence data should be fine with default duration_grid
    #if (cadence=='long') or (cadence=='30 minute') or (cadence=='10 minute'): 
    #    durations=find_min_trial_duration(input_LC,durations,periods)
    #ALT GRID TEST
#     periods,durations = optimize_period_duration_grid_sizes(periods,durations,
#             downsample_by_N_percent=0.75,
#             cadence_of_observations=np.nanmedian(np.diff(time)))
    #ALT GRID TEST
    # 
    # mimicking TLS' print statements
    astropy_version = astropy.__version__
    print('Box Least Squares (BLS) from Astropy '+str(astropy_version))
    print('Creating model cache for '+str(len(durations))+' durations')
    print("Searching "+ str(len(time))+" data points, "+ str(len(periods))+ " periods from "+ str(round(min(periods), 3))+ " to "+ str(round(max(periods), 3))+ " days")    
    #
    #shortest is unused in source code definition (why is it there?)
    ###
    if np.isfinite(R_star)==True and np.isfinite(M_star)==True:
        #
        #start BLS search
        bls = BoxLeastSquares(time, flux, error)
        bls_power = bls.power(periods, durations)
        #
        BLS_SDE  = compute_sde_optimized(bls_power.power)
        #
        #
        # check BLS_SDE, if nan mean = nan, this is a junk result, likely due to noisy lightcurve
        if len(np.where(np.isnan(BLS_SDE)==True)[0])==len(BLS_SDE):
            print('')
            print('BLS unable to converge to solution. Check light curve, likely high CDPP.')
            print('Flux Errors are likely non-Gaussian. Trying again with point 2 point RMS uncertainty.')
            BLS_Power = bls_power.power
            if (len(np.where(np.isnan(BLS_Power)==True)[0])==len(BLS_Power)) or (np.nanmedian(BLS_Power)==0):
                #
                error = np.ones_like(flux)*p2p_rms(flux)
                #
                bls = BoxLeastSquares(time, flux, error)
                bls_power = bls.power(periods, durations)
                BLS_SDE  = compute_sde_optimized(bls_power.power)
            # check BLS_SDE again, if still nan, the BLS search failed for this light curve
            if len(np.where(np.isnan(BLS_SDE)==True)[0])==len(BLS_SDE):
                print('')
                print('BLS unable to converge to solution. Check light curve, likely high CDPP.')
                return None, None, None, None
        #
        #BLS results
        index = np.argmax(BLS_SDE) #finds strongest peak in BLS power spectrum
        BLS_Period=bls_power.period[index]
        try:
            BLS_Period_err = HWHM(bls_power.period[::-1],BLS_SDE)
        except (IndexError, ValueError) as E:
            BLS_Period_err = np.nan
        BLS_T0=bls_power.transit_time[index]
        BLS_Depth=bls_power.depth[index]
        BLS_Depth_err=bls_power.depth_err[index]
        BLS_Dur = bls_power.duration[index]
        BLS_sde = BLS_SDE[index]
        # refine transit time
        BLS_T0_refined, BLS_T0_offset_hr, BLS_T0_refine_diag = (
        refine_transit_epoch_post_search(
            time=time,
            flux=flux,
            error=error,
            t0_initial=BLS_T0,
            period_days=BLS_Period,
            duration_days=BLS_Dur,
            search_width_factor=3.0,
            max_search_period_fraction=0.10,
            min_in_transit_cadences=5,
            min_depth=0.0,
            min_snr=0.0,
            min_score_improvement=0.0,
        ))                        
        #
        #count transit times based on T0 and P
        #from transitleastsquares.stats import all_transit_times
        BLS_transit_times = all_transit_times(BLS_T0, time, BLS_Period)
        BLS_transit_count = len(BLS_transit_times)
        #
        R_p = np.sqrt(BLS_Depth)*R_star*R_sun/R_earth
        R_star_err = R_star_min
        R_p_err=R_p * np.sqrt((R_star_err/R_star)**2 + (BLS_Depth_err/BLS_Depth)**2)
        try:
            BLS_model=bls.model(time, BLS_Period, BLS_Dur, BLS_T0)
        except ValueError as e:
            print(f'BLS produced {e}')
            print('No BLS model output')
            BLS_model=np.ones_like(time)
        #
        ###
        import pandas as pd
        #
        BLSdf = pd.DataFrame({"BLS Periods":bls_power.period, "BLS Power": bls_power.power, "BLS SDE":BLS_SDE})
        #
        #check BLS Power Spectrum for oddities (like infinite peaks/depths)
        if np.nanmin(bls_power.power)==-np.inf or np.nanmax(bls_power.power)==np.inf:
            print('')
            print('PROBLEM with BLS: infinite values in Power. Check Light Curve for weird effects.')
            return None,None,None,None
        #
        # Diagnostic only, no control-flow change. The guard above tests
        # bls_power.power for +/-inf and cannot fire on an all-NaN BLS_SDE,
        # which is the case that silently skips TLS in Transit_Pipeline.
        _sde_chk = np.asarray(BLS_SDE, dtype=float)
        if _sde_chk.size and not np.any(np.isfinite(_sde_chk)):
            print('')
            print('[BLS_func] BLS SDE is entirely non-finite. The BLS power '
                  'spectrum is degenerate, typically zero variance after '
                  'normalisation. The BLS bestfit is still written.')
        BLSmodeldf = pd.DataFrame({"Time":time , "Model": BLS_model})
        #      
        #
        # NEW
        Vmag = star['Vmag'].item()
        Tmag = star['Tmag'].item()
        Gmag = star['GAIAmag'].item()
        rmag = star['rmag'].item()
        imag = star['imag'].item()
        zmag = star['zmag'].item()
        Jmag = star['Jmag'].item()
        Hmag = star['Hmag'].item()
        Kmag = star['Kmag'].item()
        Teff= star['Teff'].item()
        ra_col  = 'ra_TIC' if 'ra_TIC' in star.columns else 'ra'
        dec_col = 'dec_TIC' if 'dec_TIC' in star.columns else 'dec'
        ra= star[ra_col].item()
        dec= star[dec_col].item()
        logg= star['logg'].item()
        rho= star['rho'].item()
        dist= star['d'].item()
        # NEW
        ####
        mdump_times = get_momentum_dump_times(hdu)
        # make a guess based on average distance between mdump times
        # this works for south sectors but in north sectors, mdumps aren't consistent
        mdumps = np.nanmedian(np.diff(mdump_times[np.where((np.diff(mdump_times)>1)==True)]))
        ####
        #calculate flux contamination of nearby stars within N TESS pixels (we need pix_mask)
        # 
        if use_sources_in_aperture==True:
            # careful with Path usage here  
            pix_mask, bkg_mask, images, matched_sectors = get_pix_and_bkg_masks_and_image_fluxes(ID, Sector, cadence,
                                                                                                 default_settings)
            #
            nearby_star_catalog_in_aperture = get_sources_in_aperture_mask(ID,hdu,pix_mask,
                                                                           nearby_star_catalog,
                                                                           verbose=False)    
            flux_contamination_ratio, sigma_contamination = calc_flux_contamination(nearby_star_catalog=nearby_star_catalog_in_aperture,
                                                               ID=ID)
            #
            #
            if np.isfinite(flux_contamination_ratio)==False:
                flux_contamination_ratio, sigma_contamination = calc_flux_contamination(nearby_star_catalog=nearby_star_catalog, ID=ID)
        if use_sources_in_aperture==False:
            flux_contamination_ratio, sigma_contamination = calc_flux_contamination(nearby_star_catalog=nearby_star_catalog,
                                                                                    ID=ID)
        ### 
        ###    
        try:
            stats = bls.compute_stats(BLS_Period,BLS_Dur,BLS_T0)
            BLS_Depth_odd,BLS_Depth_odd_err = stats['depth_odd'][0],stats['depth_odd'][1]
            BLS_Depth_even,BLS_Depth_even_err = stats['depth_even'][0],stats['depth_even'][1]
            odd_even_difference = abs(BLS_Depth_odd - BLS_Depth_even)
            odd_even_std_sum = BLS_Depth_odd_err + BLS_Depth_even_err
            odd_even_mismatch = odd_even_difference / odd_even_std_sum
            ###
        except ValueError: #something weird happened with BLS' compute stats function
            BLS_Depth_odd,BLS_Depth_odd_err = np.nan, np.nan
            BLS_Depth_even,BLS_Depth_even_err = np.nan, np.nan
            odd_even_difference = np.nan
            odd_even_std_sum = np.nan
            odd_even_mismatch = np.nan
        #    
        #
        # fractional transit duration
        q_transit = BLS_Dur / BLS_Period #unitless (days/days)
        # a / R_star
        SMA , SMA_cm = calculate_semi_major_axis(Period=BLS_Period*u.day,
                                                 R_star=R_star*u.R_sun, 
                                                 M_star=M_star*u.M_sun) 
        a_over_R_star = ( (SMA_cm*u.cm).to(u.cm) ) / (R_star*R_sun)
        ###
        RHO_SUN_CGS = float((u.M_sun / ((4.0 / 3.0) * np.pi * u.R_sun ** 3)).cgs.value)
        ###
        BLSbestfitdf = pd.DataFrame({"BLS Period [d]":BLS_Period, "BLS Period Error":BLS_Period_err,"BLS TC [BTJD]": BLS_T0, "BLS depth [ppt]":(BLS_Depth)*1e3,"BLS depth Error":(BLS_Depth_err)*1e3,"BLS SDE":BLS_sde, "BLS FAP":np.nan,"BLS Dur [hrs]":BLS_Dur*24, "BLS Odd Even Mismatch":odd_even_mismatch,"BLS Transit Count":BLS_transit_count, "Planet Radius [RE]":R_p,"Planet Radius Error":R_p_err, "q_transit":q_transit,"a_over_R_star":a_over_R_star ,"CDPP [ppm/sqrt hr]": cdpp, 'Time Span [d]':time_span, 'Stellar Radius [RS]':R_star, "Stellar Mass [MS]":M_star,"Teff [K]":Teff, "Flux Contamination Ratio":flux_contamination_ratio,"Vmag":Vmag,"TESSmag":Tmag,"rmag":rmag,"imag":imag,"zmag":zmag,"Jmag":Jmag,"Hmag":Hmag, "Kmag":Kmag,"Momentum Dump Rate [d]":mdumps,"RA":ra, "DEC":dec,"logg":logg,"rho [rho_sun]":rho, "rho [g/ccm]":rho * RHO_SUN_CGS,"dist [pc]":dist}, index=[0])
        #
        #
        # Append more statistics to BLSbestfitdf:
        input_LC = pd.DataFrame({'Time':time,'Flux':flux,'Error':error})
        transit_stat_dict = intransit_stats(input_LC, BLSbestfitdf)
        BLS_depths_arr = transit_stat_dict['transit_depths']
        BLS_depths_arr_uncertainty = transit_stat_dict['transit_depths_uncertainties']
        BLS_rp_rs = (R_p*R_earth) / (R_star*R_sun)
        BLS_snr = transit_stat_dict['snr']
        BLS_per_transit_count = transit_stat_dict['per_transit_count']
        BLS_TCs = transit_stat_dict['transit_times']
        BLS_distinct_transit_count = len(BLS_TCs) - np.count_nonzero(BLS_per_transit_count == 0)
        BLS_snr_per_transit = transit_stat_dict['snr_per_transit']
        BLS_snr_pink_per_transit = transit_stat_dict['snr_pink_per_transit']
        #
        
        BLSbestfitdf['BLS SNR'] = BLS_snr
        BLSbestfitdf['RP_RS'] = BLS_rp_rs
        BLSbestfitdf['BLS Distinct Transit Count'] = BLS_distinct_transit_count
        #
        # reorganize in same order as TLS
        newcolumnsorder = ["BLS Period [d]", "BLS Period Error","BLS TC [BTJD]", "BLS depth [ppt]",\
                           "BLS depth Error","BLS SDE","BLS SNR","BLS FAP","BLS Dur [hrs]",\
                           "BLS Transit Count","BLS Distinct Transit Count",\
                           "BLS Odd Even Mismatch","RP_RS","Planet Radius [RE]",\
                           'Planet Radius Error',"q_transit", "a_over_R_star", "CDPP [ppm/sqrt hr]",\
                           'Time Span [d]','Stellar Radius [RS]',"Stellar Mass [MS]",\
                           "Teff [K]","Flux Contamination Ratio",\
                           "Vmag","TESSmag","rmag","imag","zmag","Jmag","Hmag","Kmag",\
                           "Momentum Dump Rate [d]","RA","DEC","logg","rho [g/ccm]","dist [pc]"]
        BLSbestfitdf = BLSbestfitdf.reindex(columns=newcolumnsorder)
        # new dataframe for per transit stats
        BLSTCsdf = pd.DataFrame({"BLS TCs [BTJD]":BLS_TCs,"BLS Depths":(1-BLS_depths_arr)*1000,"BLS Depths Error":BLS_depths_arr_uncertainty,"SNR Per Transit":BLS_snr_per_transit,"SNR Pink Per Transit":BLS_snr_pink_per_transit})
        #
        ### Vet with EDI-Vetter
#         if for_injections==False:
#             if (type(Sector) is int):
#                 Path=path+'Sector_'+str(Sector)+'/'
#             if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
#                 Path=path+'Multi_Sector/'
#         if for_injections==True:
#             if (type(Sector) is int):
#                 Path=path+'Sector_'+str(Sector)+'/'
#             if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
#                 Path=path+'Multi_Sector/'
#             Period, R_planet_RE, T0 = inject_param_P_RP_T0
#             Path=Path+'Period_'+str(np.round(Period,2))+'_RP_'+str(np.round(R_planet_RE,2))+'/'        
            
        #Path = generate_injection_path(path, Sector, get_all_sectors, inject_param_P_RP_T0, for_injections)
#         Path = generate_injection_path(Sector, default_settings)
        #
        if (Sector==None): #all sectors
            #Sectors = search_sectors_from_filetype_and_path(Path,ID,cadence)
            Sectors = search_sectors_from_filetype_and_path(ID,default_settings)
            Sector_str = str(Sectors[0])+'-'+str(Sectors[-1])
        else:
            if (type(Sector)==int): #single sector
                Sector_str = str(Sector)
            else: #multi-sector
                Sector_str = str(Sector[0])+'-'+str(Sector[-1])        
        # NOT SURE I WANT TO USE EDI IF I'M USING LEO-VETTER
#         EDI_results = pd.DataFrame({'ID':ID,'Sector':Sector_str,\
#                                     'Flux Contamination':None, 'Too Many Transits Masked':None,\
#                                     'Odd/Even Transit Variation':None,'Signal is not Unique':None,\
#                                     'Secondary Eclipse Found':None,'Low Transit Phase Coverage':None,\
#                                     'Transit Duration Too Long':None, 'Signal is a False Positive':None},index=[0])       
        # NOT SURE I WANT TO USE EDI IF I'M USING LEO-VETTER    
        #
        # append injected params to TransitParams_df (if any)
        print(f'inject_param_P_RP_T0: {inject_param_P_RP_T0}')
        if inject_param_P_RP_T0 is not None:
            if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
                injected_params = pd.read_csv(savelcpath+f'TIC_{ID}_Multi_Sector_TransitInjected_param.csv')
            else:                
                injected_params = pd.read_csv(savelcpath+f'TIC_{ID}_{sector_tag}_TransitInjected_param.csv')
            #
            inject_param_P_RP_T0_Depth = [injected_params['Period'].item(),
                                          injected_params['Injected Radius'].item(),
                                          injected_params['T0'].item(),
                                          injected_params['Injected Depth (model)'].item()]

            
            BLSbestfitdf.loc[:, ['Injected Orbital Period (Days)',
                                 'Injected Planet Radius (Earth Radii)',
                                 'Injected T0 (BTJD)', 
                                 'Injected Transit Depth (ppo)' ]] = inject_param_P_RP_T0_Depth
        #            
        #
        if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
            BLSdf.to_csv(saveReportpath+"TIC_"+str(ID)+"_Multi_Sector_BLS.csv",index=False)
            BLSmodeldf.to_csv(saveReportpath+"TIC_"+str(ID)+"_Multi_Sector_BLS_model.csv",index=False)
            BLSbestfitdf.to_csv(saveReportpath+"TIC_"+str(ID)+"_Multi_Sector_BLS_bestfit.csv",index=False)         
            BLSTCsdf.to_csv(saveReportpath+"TIC_"+str(ID)+"_Multi_Sector_BLS_TCs.csv",index=False)
            # NOT SURE I WANT TO USE EDI IF I'M USING LEO-VETTER
            #EDI_results.to_csv(saveReportpath+"TIC_"+str(ID)+"_Multi_Sector_EDI_results.csv",index=[0])
            # NOT SURE I WANT TO USE EDI IF I'M USING LEO-VETTER
        else:
            BLSdf.to_csv(saveReportpath+"TIC_"+str(ID)+f"_{sector_tag}_BLS.csv",index=False)
            BLSmodeldf.to_csv(saveReportpath+"TIC_"+str(ID)+f"_{sector_tag}_BLS_model.csv",index=False)
            BLSbestfitdf.to_csv(saveReportpath+"TIC_"+str(ID)+f"_{sector_tag}_BLS_bestfit.csv",index=False)
            BLSTCsdf.to_csv(saveReportpath+"TIC_"+str(ID)+f"_{sector_tag}_BLS_TCs.csv",index=False)
            # NOT SURE I WANT TO USE EDI IF I'M USING LEO-VETTER
            # EDI_results.to_csv(saveReportpath+"TIC_"+str(ID)+"_Sector_"+str(Sector)+"_EDI_results.csv",index=[0])   
            # NOT SURE I WANT TO USE EDI IF I'M USING LEO-VETTER
        #
        print('')        
        return BLSdf, BLSmodeldf, BLSbestfitdf, BLSTCsdf
    #
    else:
        print(" ")
        print("NaNs in mass or radius")
        print("Stellar Mass: ",M_star," Radius: ", R_star)
        print(" ")
        pass
