def plot_odd_even_transits(LC_df, TLSbestfit_df, TLSTCs_df, TLSmodel_df, ax,fig):
    """
    This function will plot the odd and even numbered transits that are
    modeled by TLS in the input subplot of a pyplot figure.
    Input Parameters
    ----------
    LC_df : pandas dataframe
        The input NEMESIS Light Curve (LC) 
    TLSbestfit_df : pandas dataframe
        The best fit transit parameters corresponding to the strongest
        peak from the TLS transit search.
    TLSTCs_df : pandas dataframe 
        The mid-transit time for each TLS modeled transit within the time series.    
    TLSmodel_df : pandas dataframe
        The TLS transit models corresponding to the best fit transit parameters
        from the TLS transit search.
    ax : pyplot subplot
    fig : pyplot figure
    
    Returns
    -------
        * Nothing.
    """      
    ax.set_title('All Odd / Even Events')
    #
    cadence = np.round(np.nanmedian(np.diff(LC_df['Time'].to_numpy(dtype=np.float64)))*24*60*60) # in seconds
    if (cadence >= 600) & (cadence<=1800):
        markersize=8
    if (cadence > 0) & (cadence<=120):
        markersize=4
    else:
        markersize=8         
    fontsize=12
    #T_C_x_position and T_C_y_position control where the text appears for time stamps of "transit events"
    T_C_x_position = -0.55
    T_C_y_position =0.002
    #
    time =  LC_df['Time'].to_numpy(dtype=np.float64)
    flux =  LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    error = LC_df['Detrended Error'].to_numpy(dtype=np.float64)
    #
    try:
        P = TLSbestfit_df['TLS Period [d]'].item()
        T0 = TLSbestfit_df['TLS TC [BTJD]'].item()
        Dur= TLSbestfit_df['TLS Dur [hrs]'].item()
        Depth = (TLSbestfit_df['TLS depth [ppt]'].item())/1000 #in ppo now
        N_transits = TLSbestfit_df['TLS Distinct Transit Count'].item()
        odd_even_mismatch = (TLSbestfit_df['TLS Odd Even Mismatch'].item()) #in standard deviations
        #XLIM=1.5*Dur
        XLIM=3.5*Dur    
        #
        T_C_array = np.array(TLSTCs_df['TLS TCs [BTJD]'])
        Depths_array = np.array(TLSTCs_df['TLS Depths'])
        Depths_err_array = np.array(TLSTCs_df['TLS Depths Error'])
    except KeyError:
        P = TLSbestfit_df['BLS Period [d]'].item()
        T0 = TLSbestfit_df['BLS TC [BTJD]'].item()
        Dur= TLSbestfit_df['BLS Dur [hrs]'].item()
        Depth = (TLSbestfit_df['BLS depth [ppt]'].item())/1000 #in ppo now
        N_transits = TLSbestfit_df['BLS Distinct Transit Count'].item()
        odd_even_mismatch = (TLSbestfit_df['BLS Odd Even Mismatch'].item()) #in standard deviations
        #XLIM=1.5*Dur
        XLIM=3.5*Dur    
        #
        T_C_array = TLSTCs_df['BLS TCs [BTJD]'].to_numpy(dtype=np.float64)
        Depths_array = TLSTCs_df['BLS Depths'].to_numpy(dtype=np.float64)
        Depths_err_array = TLSTCs_df['BLS Depths Error'].to_numpy(dtype=np.float64)
        
    #
    Modeltime = TLSmodel_df['Time'].to_numpy(dtype=np.float64)
    Modelflux = TLSmodel_df['Model'].to_numpy(dtype=np.float64)
    pf_model,ff_model = phasefold(T0,Modeltime,P,Modelflux)
    #
    # cutting a 1 days worth of data around individual odd/even transits
    # and appending them into odd/even arrays for comparison
    #
    #
    window_size = 1 #day
    EvenDepths=[]
    OddDepths=[]
    Even=[]
    Evenflux=[]
    Odd=[]
    Oddflux=[]
    for x in range(len(T_C_array)):
        if x %2 ==0: #even
            EvenDepths=np.append(EvenDepths,Depths_array[x])
            cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
            cut_t  =  time[cut]
            cut_f  =  flux[cut]
            cut_fe = error[cut]
            if len(cut_f)<1: #in case window size is too small to cut data around
                window_size=1.5
                cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
                cut_t  =  time[cut]
                cut_f  =  flux[cut]
                cut_fe = error[cut]
            ###
            phasefolded,foldedflux = phasefold(T_C_array[x],cut_t,P,cut_f)
            Even=np.append(Even,phasefolded)
            Evenflux=np.append(Evenflux,foldedflux)
        else: #odd
            OddDepths=np.append(OddDepths,Depths_array[x])
            cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
            cut_t  =  time[cut]
            cut_f  =  flux[cut]
            cut_fe = error[cut]
            if len(cut_f)<1: #in case window size is too small to cut data around
                window_size=1.5
                cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
                cut_t  =  time[cut]
                cut_f  =  flux[cut]
                cut_fe = error[cut]
            phasefolded,foldedflux = phasefold(T_C_array[x],cut_t,P,cut_f)
            Odd=np.append(Odd,phasefolded)
            Oddflux=np.append(Oddflux,foldedflux)
    ####
    ### Check if odd/even will overlap, if so increase spacing
    evenmask = np.abs(Even*24)<Dur*3
    oddmask = np.abs(Odd*24)<Dur*3
    Nsig=1
    if len(np.where(oddmask==True)[0])<1:        
        if len(Oddflux) < 1:
            odd_in_transit = np.nan
            oddmin, oddmax  = np.nan,np.nan
        else:
            odd_in_transit = Oddflux
            oddmin, oddmax  = np.nanmin(Oddflux)-Nsig*np.nanstd(Oddflux),np.nanmax(Oddflux)+Nsig*np.nanstd(Oddflux)
    else:        
        odd_in_transit = np.array(Oddflux)[oddmask]
        oddmin, oddmax  = np.nanmin(Oddflux[oddmask])-Nsig*np.nanstd(Oddflux[oddmask]),np.nanmax(Oddflux[oddmask])+Nsig*np.nanstd(Oddflux[oddmask])
    if len(np.where(evenmask==True)[0])<1:        
        if len(Evenflux) < 1:
            even_in_transit = np.nan
            evenmin,evenmax = np.nan,np.nan
        else:
            even_in_transit = Evenflux
            evenmin,evenmax = np.nanmin(Evenflux)-Nsig*np.nanstd(Evenflux),np.nanmax(Evenflux)+Nsig*np.nanstd(Evenflux)
    else:        
        even_in_transit = np.array(Evenflux)[evenmask]
        evenmin,evenmax = np.nanmin(Evenflux[evenmask])-Nsig*np.nanstd(Evenflux[evenmask]),np.nanmax(Evenflux[evenmask])+Nsig*np.nanstd(Evenflux[evenmask])
    #
    spacing = 1* (Depth)
    if (np.round(np.nanmedian(np.diff(time))*60*24,1))<30: #why? 
        spacing=spacing*3
    else:
        spacing=spacing*1.5
    if spacing < 3*np.nanstd(Oddflux):
        spacing = 3*np.nanstd(Oddflux)
    #
    if len(Odd)>1:
        ax.plot(24*Odd,np.array(Oddflux)+spacing,color='grey',marker='.',\
                linestyle='none',markersize=markersize+1, rasterized=True,label='Odd',zorder=-10)
    if len(Even)>1:
        ax.plot(24*Even,np.array(Evenflux)-spacing,color='black',marker='.',\
                linestyle='none',markersize=markersize+1, rasterized=True,label='Even',zorder=-10)
    ax.plot(24*pf_model,ff_model-spacing,'r.-',linewidth=0.5,markersize=1,label='TLS Model',zorder=10)
    ax.plot(24*pf_model,ff_model+spacing,'r.-',linewidth=0.5,markersize=1,zorder=10)
    #
    #
    ymax = np.nanmax(np.nanmean(ff_model)+3*spacing)
    ymin = np.nanmin(np.nanmean(ff_model)-3*spacing)
    if (np.isfinite(evenmin)==True) & (ymin>evenmin-spacing):
        ymin=evenmin-spacing
    if (np.isfinite(oddmax)==True) & (ymax<oddmax+spacing):
        ymax=oddmax+spacing
    #
    ax.vlines(x=0-Dur/2,ymin=ymin+0.5*spacing,ymax=ymax-0.5*spacing,zorder=-100,color='cyan')
    ax.vlines(x=0+Dur/2,ymin=ymin+0.5*spacing,ymax=ymax-0.5*spacing,zorder=-100,color='cyan')
    ax.vlines(x=0,linestyle='--',ymin=ymin+0.5*spacing,ymax=ymax-0.5*spacing,zorder=-100,color='cyan')
    #
    ax.set_xlim(-XLIM,XLIM)
    #
    ax.set_ylim(ymin,ymax)
    ax.set_xlabel('Phase [Hours since '+str(np.round(T0,3))+' [BTJD]')
    ax.set_ylabel('Normalized Flux + Offset')
    #
    #
    #
    tx=0.085
    ty=0.915
    #
    ax.axhline(y=1-spacing-np.nanmean(EvenDepths)/1000,color='green',linestyle='-',zorder=9)
    ax.axhline(y=1+spacing-np.nanmean(OddDepths)/1000,color='green',linestyle='-',label='Odd/Even Mismatch',zorder=9)
    #
    handles, labels = ax.get_legend_handles_labels()
    by_label = dict(zip(labels, handles))
    ax.text(0.025, 1-0.025,\
            'N Transits: \n'+str(N_transits)+'\nO/E mismatch: \n'+str(np.round(odd_even_mismatch,3))+r' ${\sigma}$',
            va='top', transform=ax.transAxes,size=fontsize-2)
    
    ax.text(1.0, 0.9, 'Odd', ha='right', va='top',transform=ax.transAxes,size=fontsize+4,weight='bold')
    ax.text(1.0, 0.1, 'Even', ha='right', va='top',transform=ax.transAxes,size=fontsize+4,weight='bold')
