def plot_power_spectra(TLS_df,TLSbestfit_df, ax):
    """
    This function will plot the TLS power spectrum resulting from the
    TLS transit search.
    
    Input Parameters
    ----------
    TLS_df : pandas dataframe
        The TLS power spectra from the TLS transit search.
    TLSbestfit_df : pandas dataframe
        The best fit transit parameters corresponding to the strongest
        peak from the TLS transit search.
    ax : pyplot subplot
    
    Returns
    -------
        * Nothing.
    Returns
    -------
        *
    """      
    #power spectra
    try:
        TLS_periods= TLS_df['TLS Periods']
        TLS_Power = TLS_df['TLS SDE']
        #
        #best fit params
        P = TLSbestfit_df['TLS Period [d]'].item()
        RP = TLSbestfit_df['Planet Radius [RE]'].item()
        Depth = TLSbestfit_df['TLS depth [ppt]'].item()
        ax.set_ylabel('TLS Power')
        title_str = 'TLS Power Spectrum: '+'Period '+str(np.round(P,3))+' d'+'; Depth '+str(np.round(Depth,3))+' ppt'+'; Planet Radius: '+str(np.round(RP,3))+' RE'        
    except KeyError:
        TLS_periods= TLS_df['BLS Periods']
        TLS_Power = TLS_df['BLS SDE']
        #
        #best fit params
        P = TLSbestfit_df['BLS Period [d]'].item()
        RP = TLSbestfit_df['Planet Radius [RE]'].item()
        Depth = TLSbestfit_df['BLS depth [ppt]'].item()        
        ax.set_ylabel('BLS Power')
        title_str = 'BLS Power Spectrum: '+'Period '+str(np.round(P,3))+' d'+' Depth '+str(np.round(Depth,3))+' ppt'+' Planet Radius: '+str(np.round(RP,3))+' RE'        
    mdumps=TLSbestfit_df['Momentum Dump Rate [d]'].item()
    #
    ax.axvline(x=P,color='r')
    #
    for x in range(1,10):
        if P*x <np.nanmax(TLS_periods):
            ax.axvline(x=x*P,color='r',linestyle='--')
        if P/x >np.nanmin(TLS_periods):
            ax.axvline(x=P/x,color='r',linestyle='--')
    ax.plot(TLS_periods,TLS_Power, color='black', rasterized=True)
    #
    ax.axvline(x=mdumps,color='grey',linestyle='--')
    ax.set_xlabel('Period [days]')
    #
    if (np.nanmax(TLS_periods) > 30) & (np.nanmax(TLS_periods) < 100):
        ax.set_xticks(np.arange(0, np.nanmax(TLS_periods)+1, 5))
    if (np.nanmax(TLS_periods) > 100):
        ax.set_xticks(np.arange(0, np.nanmax(TLS_periods)+1, 10))        
    if np.nanmax(TLS_periods) < 30:
        ax.set_xticks(np.arange(np.nanmin(TLS_periods), np.nanmax(TLS_periods)+1, 1))
    #
    ax.set_title(title_str)
    ax.set_ylim(np.nanmin(TLS_Power)-np.nanstd(TLS_Power),np.nanmax(TLS_Power)+np.nanstd(TLS_Power))
