def plot_image(ID, nearby_star_catalog, hdu, Sector, cadence,
               ax_placement, fig, fs, ncols, cbarpad,
               default_settings,return_masks=False):
    """
    Input Parameters
    ----------

    Returns
    -------
        *
    """
    from astropy.io.fits import HDUList

    # read in default settings
    path                 = default_settings.get('path')
    saveReportpath       = default_settings.get('saveReportpath')
    savelcpath           = default_settings.get('savelcpath')
    downloadpath         = default_settings.get('downloadpath')
    get_all_sectors      = default_settings.get('get_all_sectors')
    for_injections       = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    verbose              = default_settings.get('verbose')
    import os
    import matplotlib.gridspec as gridspec

    if saveReportpath is None:
        Path = generate_injection_path(Sector, default_settings)
        if cadence in ('long', '30 minute', '10 minute'):
            saveReportpath = Path + 'NEMESIS_FFI_TLS_Report/'
        if cadence in ('short', '2 minute', '20 second', 'fast'):
            saveReportpath = Path + 'NEMESIS_TPF_TLS_Report/'

    pix_mask, bkg_mask, images, matched_sectors = get_pix_and_bkg_masks_and_image_fluxes(
        ID, Sector, cadence, default_settings)

    # Normalize matched_sectors to always be iterable
    if not isinstance(matched_sectors, (list, tuple, np.ndarray)):
        matched_sectors = [matched_sectors]

    # ── HDU selection ─────────────────────────────────────────────────────────
    # Same isinstance→type fix as plot_cutouts: HDUList is a list subclass,
    # so only enter this block for plain Python lists of HDULists.
    if type(hdu) is list:
        hdu = [h for h in hdu if h is not None]  # drop Nones

        hdus      = hdu
        bkg_masks = bkg_mask if type(bkg_mask) is list else [bkg_mask]
        pix_masks = pix_mask if type(pix_mask) is list else [pix_mask]

        selected = False
        for i in range(len(hdus)):
            if hdus[i] is None:
                continue
            _hdu_i = hdus[i]
            _bkg_i = bkg_masks[i] if i < len(bkg_masks) else bkg_masks[0]
            _pix_i = pix_masks[i] if i < len(pix_masks) else pix_masks[0]

            try:
                _sec_i = int(_hdu_i[0].header['Sector'])
            except (KeyError, IndexError, TypeError):
                try:
                    _sec_i = int(_hdu_i[1].header.get('Sector', Sector))
                except Exception:
                    _sec_i = Sector

            if int(_sec_i) in matched_sectors:
                hdu      = _hdu_i
                bkg_mask = _bkg_i
                pix_mask = _pix_i
                Sector   = _sec_i
                selected = True
                break

        if not selected:
            for i in range(len(hdus)):
                if hdus[i] is not None:
                    hdu      = hdus[i]
                    bkg_mask = bkg_masks[i] if i < len(bkg_masks) else bkg_masks[0]
                    pix_mask = pix_masks[i] if i < len(pix_masks) else pix_masks[0]
                    try:
                        Sector = int(hdu[0].header['Sector'])
                    except Exception:
                        pass
                    break

        if verbose:
            print(f'[plot_image] selected HDU for Sector {Sector}')

    # Ensure hdu is always an HDUList before any downstream access
    if not isinstance(hdu, HDUList):
        hdu = HDUList([hdu])

    # ── WCS and axis setup ────────────────────────────────────────────────────
    wcs = check_wcs(hdu)
    ax  = fig.add_subplot(ax_placement, projection=wcs)

    try:
        reference_pixel = get_tess_reference_pixel(hdu[1].header)
        ax.set_title("TPF Cutout" if cadence in ('short', '2 minute', '20 second', 'fast')
                     else "FFI Cutout", fontsize=fs)

        pm = pix_mask[0] if (pix_mask is not None and np.ndim(pix_mask) == 3) else pix_mask
        bm = bkg_mask[0] if (bkg_mask is not None and np.ndim(bkg_mask) == 3) else bkg_mask
        #
        plot_cutouts_ALT(ID, nearby_star_catalog, Sector, cadence, hdu,
                 pm, bm, reference_pixel, ncols, fig, ax,
                 cbarpad, default_settings,
                 catalog_source=default_settings.get('plot_catalog_source', 'TIC'))

    except (TypeError, AttributeError, IndexError) as e:
        if verbose:
            print(f"[plot_image] fallback path: {e}")
        try:
            reference_pixel = get_tess_reference_pixel(hdu[1].header)
        except Exception:
            col,row = 5.5, 5.5
            reference_pixel = [col, row]

        pm = pix_mask[0] if (pix_mask is not None and np.ndim(pix_mask) == 3) else pix_mask
        bm = bkg_mask[0] if (bkg_mask is not None and np.ndim(bkg_mask) == 3) else bkg_mask

        if pm is not None and np.ndim(pm) == 2:
            plot_cutouts_ALT(ID, nearby_star_catalog, Sector, cadence, hdu,
                 pm, bm, reference_pixel, ncols, fig, ax,
                 cbarpad, default_settings,
                 catalog_source=default_settings.get('plot_catalog_source', 'TIC'))
    if return_masks==True:
        return ax, pix_mask, bkg_mask
    else:
        return ax
#
#
#
def plot_centroids_in_phase(LC_df,BLSorTLSbestfit_df,ax_placement):#ax):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    fs=12
    ax, axb = ax_placement[0],ax_placement[1]
    ax.set_title("Centroid Motion Mid-Transit",fontsize = fs)
    #
    centx_orig = LC_df['Centroid X Positions'].to_numpy(dtype=np.float64)#-x
    centy_orig = LC_df['Centroid Y Positions'].to_numpy(dtype=np.float64)#-y
    time  = LC_df['Time'].to_numpy(dtype=np.float64)
    #
    centx = centx_orig - np.nanmedian(centx_orig)
    centy = centy_orig - np.nanmedian(centy_orig)
    #
    #
    #
    import astropy.units as u
    try:
        T0 = BLSorTLSbestfit_df['TLS TC [BTJD]'].item()
        P  = BLSorTLSbestfit_df['TLS Period [d]'].item()
        Dur=(BLSorTLSbestfit_df['TLS Dur [hrs]'].item()*u.hour).value
    except KeyError:
        T0 = BLSorTLSbestfit_df['BLS TC [BTJD]'].item()
        P =  BLSorTLSbestfit_df['BLS Period [d]'].item()
        Dur=(BLSorTLSbestfit_df['BLS Dur [hrs]'].item()*u.hour).value
    XLIM=3.5*Dur  
    #
    pfx,xx = phasefold(T0, time,P,centx)
    pfy,yy = phasefold(T0, time,P,centy)
    #
    #
    ax.plot(24*pfx,xx,'k.')
    axb.plot(24*pfy,yy,'k.')
    ax.set_xlim(-XLIM,XLIM)
    axb.set_xlim(-XLIM,XLIM)
    mx = np.where(np.abs(pfx)<XLIM)
    my = np.where(np.abs(pfy)<XLIM)
    sigmalimx = 5*np.nanstd(xx[mx].astype('float32'))
    sigmalimy = 5*np.nanstd(yy[my].astype('float32'))
    if np.abs(sigmalimx)> np.abs(sigmalimy):
        YLIM=np.abs(sigmalimx)+ 1*np.abs(np.nanstd(xx[mx]))
    else:
        YLIM=np.abs(sigmalimy)+ 1*np.abs(np.nanstd(yy[my]))    
    #
    try:  #if this pops up, centroid positions are all NaNs for some reason...
        ax.set_ylim(-YLIM,YLIM)
        axb.set_ylim(-YLIM,YLIM)
    except ValueError:
        ax.set_ylim(-3,3)
        axb.set_ylim(-3,3)
        ax.text(-XLIM/2+0.5 , 0.5, 'Problems with Centroiding', horizontalalignment='center', verticalalignment='center', transform=ax.transData)
        axb.text(-XLIM/2+0.5, 0.5, 'Problems with Centroiding', horizontalalignment='center', verticalalignment='center', transform=ax.transData)        
    ax.set_ylabel(r'$\Delta X$ [pixels]')
    axb.set_ylabel(r'$\Delta Y$ [pixels]')
    #axb.yaxis.label.set_color('red')
    #axb.tick_params(axis='y', colors='red')
#     ax.set_xlabel('Phase [Hours since '+str(np.round(T0,3))+' [BTJD]')
    axb.set_xlabel('Phase [Hours since '+str(np.round(T0,3))+' [BTJD]')
    ax.axhline(y=0,color='purple',linestyle='-')
    axb.axhline(y=0,color='purple',linestyle='-')
    for N in [1,3,5]:
        if N==1:
            c='red'
        if N==3:
            c='green'
        if N==5:
            c='blue'
        ax.axhline( y=+N*np.nanstd(xx[mx].astype('float32')),color=c,
                    linestyle='-',alpha=0.5,zorder=-10)
        ax.axhline( y=-N*np.nanstd(xx[mx].astype('float32')),color=c,
                    linestyle='-',alpha=0.5,zorder=-10)
        axb.axhline( y=+N*np.nanstd(yy[my].astype('float32')),color=c,
                    linestyle='-',alpha=0.5,zorder=-10)
        axb.axhline( y=-N*np.nanstd(yy[my].astype('float32')),color=c,
                    linestyle='-',alpha=0.5,zorder=-10)
#
#
#
def _nemesis_skyview_stamp(
    ra: float,
    dec: float,
    survey: str = 'DSS2 Red',
    scaling: str = 'Linear',
    sizepix: int = 300,
    flip: bool = True,
    convolvewith=None,
    forcefetch: bool = False,
    cachedir=None,
    timeout: float = 30.0,
    retry_failed: bool = False,
    savewcsheader: bool = True,
    fallback_surveys: tuple = ('DSS2 Blue', 'DSS'),
    max_retries: int = 2,
    verbose: bool = False,
) -> tuple:
    """
    Fetch a sky survey image stamp and return ``(stamp, header)``.

    Wrapper around ``astrobase.plotbase.skyview_stamp`` with the following
    hardening over the previous version:

    - Distinguishes network/server failures (transient; retry) from
      empty-result failures (no coverage; quiet).
    - Falls back through ``fallback_surveys`` on empty result from the
      primary survey.
    - Falls back to ``astroquery.skyview.SkyView`` if astrobase is entirely
      unavailable or all astrobase attempts fail.
    - Retries ``max_retries`` times on transient network errors before
      giving up.
    - Never raises; always returns ``(None, None)`` on unrecoverable failure.

    Parameters
    ----------
    ra : float
        Right ascension in decimal degrees (J2000).
    dec : float
        Declination in decimal degrees (J2000).
    survey : str, optional
        Primary SkyView survey identifier. Default ``'DSS2 Red'``.
    scaling : str, optional
        Pixel value scaling passed to astrobase. Default ``'Linear'``.
    sizepix : int, optional
        Output image size in pixels (square). Default ``300``.
    flip : bool, optional
        Flip the image vertically (astrobase convention). Default ``True``.
    convolvewith : array-like or None, optional
        Convolution kernel forwarded to astrobase. Default ``None``.
    forcefetch : bool, optional
        If ``True``, bypass the astrobase cache and re-fetch from the server.
        Default ``False``.
    cachedir : str or None, optional
        Cache directory for astrobase. If ``None``, astrobase uses its
        default location.
    timeout : float, optional
        Per-attempt HTTP timeout in seconds. Default ``30.0``.
    retry_failed : bool, optional
        Forwarded to astrobase (controls its internal retry logic). Default
        ``False`` to avoid double-retrying.
    savewcsheader : bool, optional
        Request WCS header from astrobase. Default ``True``.
    fallback_surveys : tuple of str, optional
        Survey identifiers to try in order if the primary survey returns no
        data. Default ``('DSS2 Blue', 'DSS')``.
    max_retries : int, optional
        Number of retry attempts on transient network/server errors before
        declaring failure. Default ``2``.
    verbose : bool, optional
        Print diagnostic messages. Default ``False``.

    Returns
    -------
    stamp : np.ndarray or None
        2-D image array, or ``None`` on failure.
    header : astropy.io.fits.Header or None
        WCS FITS header, or ``None`` if unavailable or on failure.

    Notes
    -----
    Failure mode taxonomy (all return ``(None, None)``):

    ``[IMPORT]``
        astrobase could not be imported; astroquery fallback also failed.
    ``[NETWORK]``
        DNS resolution or TCP connection failure; transient.
    ``[TIMEOUT]``
        Server did not respond within ``timeout`` seconds; transient.
    ``[EMPTY]``
        Server responded but returned no image data; likely no survey
        coverage at this position.
    ``[ERROR]``
        Unexpected exception in astrobase internals.
    ``[NODATA]``
        astroquery fallback returned no image.

    Examples
    --------
    >>> stamp, hdr = _nemesis_skyview_stamp(
    ...     ra=68.9801, dec=-5.0893,
    ...     sizepix=231,  # 11 TESS pixels * 21 arcsec/pixel
    ...     cachedir='/path/to/cache',
    ...     verbose=True,
    ... )
    >>> if stamp is not None:
    ...     print(stamp.shape, hdr['NAXIS1'])
    """
    import random
    import time
    import numpy as np
    from requests.exceptions import ConnectionError, Timeout, RequestException
    try:
        from urllib3.exceptions import NewConnectionError, MaxRetryError, NameResolutionError
        _urllib3_exc = (NewConnectionError, MaxRetryError, NameResolutionError)
    except ImportError:
        _urllib3_exc = ()

    _NET_EXC = (ConnectionError, Timeout, RequestException, TimeoutError) + _urllib3_exc

    # ── randint patch: guards against float bounds in old astrobase versions ──
    _real_randint = random.randint
    def _safe_randint(a, b):
        try:
            return _real_randint(int(a), int(b))
        except Exception:
            return _real_randint(0, max(int(b), 1))
    random.randint = _safe_randint

    def _try_astrobase(survey_name: str, force: bool) -> tuple:
        """Single attempt via astrobase for one survey. Returns (stamp, hdr) or raises."""
        from astrobase.plotbase import skyview_stamp
        import tempfile
        import astropy.utils.data as aud
        #
        _saved_cache_dir = aud.conf.cache_dir        
        try:
            with tempfile.TemporaryDirectory() as _tmpdir:
                aud.conf.cache_dir = _tmpdir
                out = skyview_stamp(
                    ra=ra, decl=dec,
                    survey=survey_name,
                    scaling=scaling,
                    sizepix=int(sizepix),
                    flip=flip,
                    convolvewith=convolvewith,
                    forcefetch=force,
                    cachedir=_tmpdir,
                    timeout=timeout,
                    retry_failed=False,
                    savewcsheader=savewcsheader,
                    verbose=verbose,
                )
                import os
                print(f"[DEBUG] _tmpdir contents: {os.listdir(_tmpdir)}")
        finally:
            aud.conf.cache_dir = _saved_cache_dir        
        
        if out is None:
            return None, None
        if isinstance(out, tuple):
            if len(out) >= 2:
                return out[0], out[1]
            if len(out) == 1:
                return out[0], None
            return None, None
        return out, None

    def _try_astroquery_fallback(survey_name: str) -> tuple:
        """
        Attempt image retrieval via astroquery.skyview.SkyView.
        Returns (stamp_2d, header) or (None, None).
        astroquery returns a list of HDULists; we take the first image extension.
        """
        try:
            from astropy.coordinates import SkyCoord
            import astropy.units as u
            from astroquery.skyview import SkyView as AQSkyView

            coord = SkyCoord(ra=ra, dec=dec, unit='deg', frame='icrs')
            fov = (sizepix * 1.0 / 3600.0) * u.deg  # ~1 arcsec/pixel for DSS2

            imgs = AQSkyView.get_images(
                position=coord,
                survey=[survey_name],
                radius=fov / 2.0,
                pixels=str(sizepix),
                coordinates='J2000',
                cache=False, #DSS queries are cheap and stateless, it's ok not to cache these
            )
            if not imgs:
                if verbose:
                    print(f'[_nemesis_skyview_stamp] astroquery fallback: '
                          f'no images returned for survey={survey_name}')
                return None, None

            hdul = imgs[0]
            # find first 2-D image extension
            for ext in hdul:
                if hasattr(ext, 'data') and ext.data is not None:
                    arr = np.array(ext.data)
                    if arr.ndim == 2:
                        hdr = ext.header
                        if verbose:
                            print(f'[_nemesis_skyview_stamp] astroquery fallback: '
                                  f'success for survey={survey_name}, '
                                  f'shape={arr.shape}')
                        return arr, hdr
            if verbose:
                print(f'[_nemesis_skyview_stamp] astroquery fallback: '
                      f'HDUList contained no 2-D image data')
            return None, None

        except Exception as aq_err:
            if verbose:
                print(f'[_nemesis_skyview_stamp] astroquery fallback error → {aq_err}')
            return None, None

    # ── Main logic ────────────────────────────────────────────────────────────
    try:
        try:
            import astrobase.plotbase  # noqa: F401
            astrobase_ok = True
        except Exception as imp_err:
            if verbose:
                print(f'[_nemesis_skyview_stamp] [IMPORT] astrobase unavailable → {imp_err}')
            astrobase_ok = False

        all_surveys = [survey] + [s for s in fallback_surveys if s != survey]

        if astrobase_ok:
            for s_idx, s_name in enumerate(all_surveys):
                force_this = forcefetch if s_idx == 0 else True  # force re-fetch on fallback
                for attempt in range(max_retries + 1):
                    try:
                        stamp, hdr = _try_astrobase(s_name, force=force_this)
                        if stamp is not None and np.any(np.isfinite(stamp)):
                            if verbose:
                                print(f'[_nemesis_skyview_stamp] success: '
                                      f'survey={s_name}, attempt={attempt+1}, '
                                      f'shape={stamp.shape}')
                            return stamp, hdr
                        else:
                            # Empty/all-NaN result: no coverage, don't retry
                            if verbose:
                                print(f'[_nemesis_skyview_stamp] [EMPTY] '
                                      f'survey={s_name}: returned None or all-NaN '
                                      f'(no coverage or bad fetch)')
                            break  # try next survey, not next attempt

                    except _NET_EXC as net_err:
                        if verbose:
                            print(f'[_nemesis_skyview_stamp] [NETWORK/TIMEOUT] '
                                  f'survey={s_name}, attempt={attempt+1} → {net_err}')
                        if attempt < max_retries:
                            wait = 2.0 ** attempt  # 1s, 2s backoff
                            if verbose:
                                print(f'[_nemesis_skyview_stamp] retrying in {wait:.0f}s...')
                            time.sleep(wait)
                        continue

                    except Exception as gen_err:
                        if verbose:
                            print(f'[_nemesis_skyview_stamp] [ERROR] '
                                  f'survey={s_name}, attempt={attempt+1} → {gen_err}')
                        break  # unexpected error: skip to next survey

        # ── astroquery fallback ───────────────────────────────────────────────
        if verbose:
            print('[_nemesis_skyview_stamp] attempting astroquery.skyview fallback...')
        for s_name in all_surveys:
            stamp, hdr = _try_astroquery_fallback(s_name)
            if stamp is not None:
                return stamp, hdr

        if verbose:
            print('[_nemesis_skyview_stamp] [NODATA] all surveys and fallbacks exhausted; '
                  f'ra={ra:.4f} dec={dec:.4f}')
        return None, None

    finally:
        random.randint = _real_randint
#
#
#
def plot_dss_orientation(
    ax,
    ID,
    nearby_star_catalog,
    downloadpath,
    hdu=None,
    pix_mask=None,
    bkg_mask=None,
    cutoutsize: int = 11,
    do_DSS_plot: bool = True,
    remove_fits: bool = True,
    show_mask_overlay: bool = True,
    pix_color: str = 'red',
    bkg_color: str = 'pink',
    verbose: bool = True,
):
    """
    Fetch a DSS optical stamp, reproject it onto the TESS WCS pixel grid,
    and render it with N/E arrows and TESS aperture/background mask overlays.

    The reprojected DSS image shares the exact same pixel coordinate system
    as the TESS cutout, so:

    - The mask patches from ``plot_mask`` can be drawn directly in TESS pixel
      coordinates with no WCS reprojection of corners needed.
    - The N/E arrows are drawn with the same ``theta`` as ``plot_orientation``
      (column-axis gradient of RA/Dec across the first TESS pixel row).
    - The displayed image orientation matches the TESS cutout exactly.

    Reprojection uses ``reproject.reproject_interp`` to resample the DSS
    stamp onto a WCS that matches the TESS cutout in pixel scale and
    orientation, but at DSS resolution (i.e. the output is
    ``cutoutsize * oversample`` pixels square, where ``oversample`` sets
    how many DSS output pixels map to one TESS pixel).

    Parameters
    ----------
    ax : matplotlib.axes.Axes
        Plain (non-WCS-projection) axes.
    ID : int
        TIC identifier; used to look up RA/Dec from ``nearby_star_catalog``.
    nearby_star_catalog : pd.DataFrame
        From ``collect_nearby_TIC_params``; must contain 'ID', 'ra', 'dec'.
    downloadpath : str or Path
        Cache directory forwarded to ``_nemesis_skyview_stamp``.
    hdu : fits.HDUList or list of fits.HDUList or None, optional
        TESS FFI/TPF HDUList.  If a plain Python list the first valid element
        is used.  Provides the target WCS (``hdu[2]``) for reprojection.
        If ``None``, falls back to showing the unreprojected DSS stamp with
        DSS-frame N/E arrows and no mask overlay.
    pix_mask : np.ndarray[bool] or None, optional
        Boolean aperture mask, shape ``(ny, nx)`` or ``(ncad, ny, nx)``.
        Drawn directly in TESS pixel coordinates after reprojection.
    bkg_mask : np.ndarray[bool] or None, optional
        Boolean background mask, shape ``(ny, nx)`` or ``(ncad, ny, nx)``.
    cutoutsize : int, optional
        TESS cutout side length in pixels. Default ``11``.
    do_DSS_plot : bool, optional
        Set ``False`` to render 'No DSS image' immediately.
    remove_fits : bool, optional
        Unused; retained for API compatibility.
    show_mask_overlay : bool, optional
        Set ``False`` to suppress mask patches. Default ``True``.
    pix_color : str, optional
        Aperture mask color. Default ``'red'``.
    bkg_color : str, optional
        Background mask color. Default ``'pink'``.
    verbose : bool, optional
        Print diagnostics. Default ``True``.

    Returns
    -------
    None

    Notes
    -----
    The output WCS for reprojection is constructed by taking the TESS aperture
    WCS (``hdu[2]``) and scaling its CDELT by ``1 / oversample``, giving a
    grid that is pixel-aligned with the TESS frame but at higher resolution.
    ``reproject_interp`` then resamples the DSS stamp onto this grid using
    bilinear interpolation.

    Mask patches are drawn exactly as in ``plot_mask``:
    ``Rectangle(xy=(j-0.5, i-0.5), width=1, height=1,
    color=mask_color, fill=False, hatch='//')``
    but scaled by ``oversample`` since the display image is
    ``cutoutsize * oversample`` pixels across.

    Arrows are drawn exactly as in ``plot_orientation``:
    ``ax.arrow``, ``head_width = oversample * 0.2``,
    ``length = oversample * 1.0``, origin ``(oversample, ny_out - 2.5)``,
    where ``theta_E`` is computed from the TESS WCS first-row column gradient.

    Examples
    --------
    >>> fig, ax = plt.subplots()
    >>> plot_dss_orientation(
    ...     ax, ID=259377017, nearby_star_catalog=cat,
    ...     downloadpath='/path/to/cache',
    ...     hdu=hdu, pix_mask=pix_mask, bkg_mask=bkg_mask,
    ... )
    """
    import numpy as np
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches
    from matplotlib import patches as mpl_patches
    from astropy.wcs import WCS
    from astropy.io.fits import HDUList, Header
    import astropy.units as u
    from copy import deepcopy

    oversample = 21   # DSS output pixels per TESS pixel; matches ~1 arcsec/px DSS2 resolution

    ax.set_title("DSS + TESS masks", fontsize=12)
    ax.set_xticks([]); ax.set_yticks([])

    # ── early exits ──────────────────────────────────────────────────────────
    if not do_DSS_plot or nearby_star_catalog is None or len(nearby_star_catalog) == 0:
        ax.text(0.5, 0.5, 'No DSS image', ha='center', va='center',
                transform=ax.transAxes)
        return

    row = nearby_star_catalog.loc[
        nearby_star_catalog['ID'].astype(str) == str(int(ID))
    ]
    if len(row) == 0:
        row = nearby_star_catalog.loc[
            nearby_star_catalog['ID'].astype(str) == str(ID)
        ]
    if len(row) == 0:
        ax.text(0.5, 0.5, 'No DSS image', ha='center', va='center',
                transform=ax.transAxes)
        return

    ra_ctr  = float(row['ra'].iloc[0])
    dec_ctr = float(row['dec'].iloc[0])

    # ── normalise hdu to a single HDUList ────────────────────────────────────
    hdu_single = None
    if hdu is not None:
        if type(hdu) is list:
            for h in hdu:
                if h is not None and isinstance(h, HDUList):
                    hdu_single = h
                    break
        elif isinstance(hdu, HDUList):
            hdu_single = hdu

    # ── TESS WCS ──────────────────────────────────────────────────────────────
    tess_wcs = None
    if hdu_single is not None:
        try:
            tess_wcs = WCS(hdu_single[2])
        except Exception as e:
            if verbose:
                print(f'[plot_dss_orientation] TESS WCS init failed → {e}')

    # ── fetch DSS stamp ───────────────────────────────────────────────────────
    # Fetch at 3x the cutout angular size so reprojection has margin for
    # rotation without running out of source pixels near the edges.
    fetch_factor = 3
    sizepix = int(cutoutsize * oversample * fetch_factor)

    stamp, hdr = _nemesis_skyview_stamp(
        ra=ra_ctr, dec=dec_ctr,
        sizepix=sizepix,
#         cachedir=str(downloadpath),
        cachedir=None, #it's ok not to cache these, DSS query is quick and stateless
        verbose=verbose,
        savewcsheader=True,
        flip=False,   # keep native FITS orientation so WCS header is consistent
    )

    if stamp is None:
        ax.text(0.5, 0.5, 'No DSS image', ha='center', va='center',
                transform=ax.transAxes)
        return

    # ── build DSS WCS ─────────────────────────────────────────────────────────
    dss_wcs = None
    if hdr is not None:
        try:
            dss_wcs = WCS(hdr)
        except Exception as e:
            if verbose:
                print(f'[plot_dss_orientation] DSS WCS init failed → {e}')

    # ── reproject DSS onto TESS-aligned output grid ───────────────────────────
    # Build an output WCS that has the same pointing and orientation as the
    # TESS aperture WCS but at DSS resolution (CDELT / oversample).
    # reproject_interp then resamples the DSS stamp onto this grid so the
    # output image is pixel-aligned with the TESS cutout.
    reprojected = None
    out_wcs     = None

    if tess_wcs is not None and dss_wcs is not None:
        try:
            from reproject import reproject_interp
            from astropy.wcs.utils import proj_plane_pixel_scales

            # Copy TESS WCS and rescale for the oversampled output grid.
            out_wcs = deepcopy(tess_wcs)
            # Scale pixel size down by oversample (finer grid).
            if hasattr(out_wcs.wcs, 'cd') and out_wcs.wcs.has_cd():
                out_wcs.wcs.cd = out_wcs.wcs.cd / oversample
            elif hasattr(out_wcs.wcs, 'cdelt'):
                out_wcs.wcs.cdelt = out_wcs.wcs.cdelt / oversample
            # Scale reference pixel accordingly (CRPIX is 1-based in FITS).
            out_wcs.wcs.crpix = (np.array(out_wcs.wcs.crpix) - 1) * oversample + 1
            out_wcs.array_shape = (cutoutsize * oversample, cutoutsize * oversample)

            out_shape = (cutoutsize * oversample, cutoutsize * oversample)

            reprojected, _ = reproject_interp(
                (stamp, dss_wcs),
                out_wcs,
                shape_out=out_shape,
                order='bilinear',
            )
            if verbose:
                print(f'[plot_dss_orientation] reprojected DSS onto TESS grid: '
                      f'{out_shape}, oversample={oversample}')

        except ImportError:
            if verbose:
                print('[plot_dss_orientation] reproject not installed; '
                      'falling back to unreprojected DSS stamp')
        except Exception as e:
            if verbose:
                print(f'[plot_dss_orientation] reproject failed → {e}; '
                      'falling back to unreprojected DSS stamp')

    # ── display: reprojected or raw stamp ────────────────────────────────────
    if reprojected is not None:
        display_img = reprojected
        ny_out, nx_out = reprojected.shape
        use_tess_frame = True
    else:
        # Fallback: show the raw (unrotated) DSS stamp with DSS-frame arrows.
        # flip=False was used above, so the stamp is in native FITS orientation
        # (y=0 at bottom when displayed with origin='lower').
        display_img = stamp
        ny_out, nx_out = stamp.shape
        use_tess_frame = False

    ax.imshow(display_img, cmap=plt.cm.Greys, origin='lower', zorder=0)

    # ── N/E arrows ────────────────────────────────────────────────────────────
    # Compute theta_E exactly as plot_orientation does:
    #   evaluate RA/Dec at pixel (0,0) and (nx-1, 0) of the displayed frame,
    #   theta_E = arctan2(ddec, dra); theta_N = theta_E + 90 deg.
    # In the TESS frame, use tess_wcs; in the fallback, use dss_wcs.
    wcs_for_arrows = tess_wcs if use_tess_frame else dss_wcs
    if wcs_for_arrows is not None:
        try:
            # Number of TESS (or DSS) pixels across the display image
            n_px_display = cutoutsize if use_tess_frame else nx_out
            sky_00 = wcs_for_arrows.pixel_to_world(0,              0)
            sky_10 = wcs_for_arrows.pixel_to_world(n_px_display - 1, 0)
            dra   = float(sky_10.ra.deg)  - float(sky_00.ra.deg)
            ddec  = float(sky_10.dec.deg) - float(sky_00.dec.deg)
            theta_E = np.arctan2(ddec, dra)
            if dra < 0.0:
                theta_E += np.pi   # match plot_orientation's manual quadrant correction
            theta_N = theta_E + np.pi / 2.0

            # Arrow length and head_width scaled from plot_orientation's
            # 1.0 px / 0.2 head on an 11-px TESS cutout.
            # In the TESS-aligned reprojected frame the image is
            # cutoutsize * oversample pixels wide, so scale accordingly.
            scale     = oversample if use_tess_frame else (ny_out / 11.0)
            arrow_len = 1.0 * scale
            hw        = 0.2 * scale
            x0 = 1.0 * scale
            y0 = ny_out - 2.5 * scale   # upper-left, matching plot_orientation

            x1E, y1E = arrow_len * np.cos(theta_E), arrow_len * np.sin(theta_E)
            ax.arrow(x0, y0, x1E, y1E,
                     head_width=hw, length_includes_head=True,
                     color='black', zorder=5)
            ax.text(x0 + 1.5 * x1E, y0 + 1.5 * y1E,
                    'E', color='black', fontsize=9,
                    ha='center', va='center', zorder=5)

            x1N, y1N = arrow_len * np.cos(theta_N), arrow_len * np.sin(theta_N)
            ax.arrow(x0, y0, x1N, y1N,
                     head_width=hw, length_includes_head=True,
                     color='black', zorder=5)
            ax.text(x0 + 1.5 * x1N, y0 + 1.5 * y1N,
                    'N', color='black', fontsize=9,
                    ha='center', va='center', zorder=5)

        except Exception as e:
            if verbose:
                print(f'[plot_dss_orientation] N/E arrows failed → {e}')

    # ── mask overlay ─────────────────────────────────────────────────────────
    # After reprojection the display image is in TESS pixel coordinates
    # (scaled by oversample).  Mask patches are drawn exactly as plot_mask:
    #   Rectangle(xy=(j*os - 0.5*os, i*os - 0.5*os), width=os, height=os,
    #             color=color, fill=False, hatch='//')
    # where os = oversample.  In the fallback (no reprojection), skip overlay
    # since we don't have a reliable pixel mapping.
    do_overlay = (
        use_tess_frame
        and show_mask_overlay
        and (pix_mask is not None or bkg_mask is not None)
    )

    if do_overlay:
        mask_spec = []
        if bkg_mask is not None:
            mask_spec.append((bkg_mask, bkg_color, 'Background', 2))
        if pix_mask is not None:
            mask_spec.append((pix_mask, pix_color, 'Aperture',   3))

        legend_handles = []
        for mask_arr, color, label, zo in mask_spec:
            if np.ndim(mask_arr) == 3:
                mask_arr = mask_arr[0]

            rows_idx, cols_idx = np.where(mask_arr)
            if len(rows_idx) == 0:
                continue

            patch_drawn = False
            for i, j in zip(rows_idx, cols_idx):
                # Each TESS pixel (j, i) maps to a block of oversample x oversample
                # display pixels starting at (j*os, i*os).
                # Rectangle origin is pixel-corner convention: centre at (j*os, i*os)
                # so xy = (j*os - 0.5*os, i*os - 0.5*os) = ((j-0.5)*os, (i-0.5)*os)
                rect = mpl_patches.Rectangle(
                    xy=((j - 0.5) * oversample, (i - 0.5) * oversample),
                    width=oversample,
                    height=oversample,
                    color=color,
                    fill=False,
                    hatch='//',
                    linewidth=0.8,
                    zorder=zo,
                )
                ax.add_patch(rect)
                patch_drawn = True

            if patch_drawn:
                legend_handles.append(
                    mpatches.Patch(fill=False, hatch='//',
                                   edgecolor=color, label=label)
                )

        if legend_handles:
            ax.legend(handles=legend_handles, loc='lower right',
                      fontsize=7, framealpha=0.5,
                      handlelength=1.5, handleheight=1.0, borderpad=0.4)

        if verbose:
            n_ap  = int(pix_mask.sum()) if pix_mask is not None else 0
            n_bkg = int(bkg_mask.sum()) if bkg_mask is not None else 0
            print(f'[plot_dss_orientation] drew {n_ap} aperture px, '
                  f'{n_bkg} background px at oversample={oversample}')

    elif show_mask_overlay and not use_tess_frame and verbose:
        print('[plot_dss_orientation] mask overlay skipped: '
              'reproject unavailable, falling back to raw DSS orientation')
