# quick check function for if a target in the TIC is  TOI or Community TOI:
def is_TOI_or_CTOI(ID,TOIs=None,CTOIs=None): # UNUSED BUT USEFUL (NEEDS UPDATING AND A CHECK FOR LOCAL FILE
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    import pandas as pd
    pd.set_option('display.max_rows', None)
    pd.set_option('display.max_columns', None)
    pd.set_option('display.width', None)
    pd.set_option('display.max_colwidth', None)
    # read in TOI and CTOI catalogs
    if TOIs is None:
        TOIs = pd.read_csv('https://tev.mit.edu/api/collections/193/download/',sep=',', comment='#')
        TOIs0 = TOIs.loc[:, ~TOIs.columns.str.contains('^Unnamed')]
        # Step 1b: rename columns 
        TOIs=TOIs0.rename(columns={'TIC':'TIC ID'})#, inplace=True)
    if CTOIs is None:
        CTOIs =  pd.read_csv('https://exofop.ipac.caltech.edu/tess/download_ctoi.php?sort=ctoi&output=csv')
        CTOIs0 = CTOIs.loc[:, ~CTOIs.columns.str.contains('^Unnamed')]
        # Step 1b: rename columns (if any need it)
        CTOIs=CTOIs0.rename(columns={'RA': 'ra', 'DEC':'dec','TIC ID':'TIC ID'})#, inplace=True)

    
    if len(CTOIs.loc[CTOIs['TIC ID']==int(ID)])>0:
        is_CTOI=True
    else:
        is_CTOI=False
        
    if len(TOIs.loc[TOIs['TIC ID']==int(ID)])>0:
        is_TOI=True
    else:
        is_TOI=False
    return is_TOI,is_CTOI
