def append_PDF(ID,Sector,cadence, input_files,BLSorTLS, default_settings):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """  
    # get function settings
    get_all_sectors = default_settings.get('get_all_sectors')
    path = default_settings.get('path')
    savelcpath = default_settings.get('savelcpath')
    downloadpath = default_settings.get('downloadpath')
    if BLSorTLS=='BLS':
        saveReportpath = default_settings.get('saveReportpath_BLS')
        report_dir_name_suffix = 'BLS_Report'
    if BLSorTLS=='TLS':
        saveReportpath = default_settings.get('saveReportpath_TLS')        
        report_dir_name_suffix = 'TLS_Report'
    for_injections = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    verbose = default_settings.get('verbose')
    #Step 0: create string tag for sector usage
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"    
    #    
    from PyPDF2 import PdfFileMerger, PdfFileReader, PdfMerger,PdfReader
    import PyPDF2
    ###
    ###
    #merger = PdfFileMerger() #no longer works
    merger = PdfMerger()       
    ###
    if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
        multipage_output_filename = saveReportpath+'TIC_'+str(ID)+'_Multi_Sector_'+report_dir_name_suffix+'_multi_page.pdf'        
    else:    
        multipage_output_filename = saveReportpath+'TIC_'+str(ID)+f'_{sector_tag}_{report_dir_name_suffix}_multi_page.pdf'
    ###
    for x in range(len(input_files)):
        input_file = input_files[x]
        create_PDF_from_PNG(ID,Sector,BLSorTLS,cadence,
                        input_file=input_file, default_settings=default_settings)
        output_file = input_file[:-4]+'.pdf'
        ###
        #pdfinput = PyPDF2.PdfFileReader(open(output_file,'rb')) #no longer works
        pdfinput = PyPDF2.PdfReader(open(output_file,'rb'))
        
        merger.append((pdfinput))
    ###
    ###
    if verbose==True:
        print('append_PDF: multipage_output_filename:',multipage_output_filename)
    merger.write(multipage_output_filename)
    #rm pageN.png files
    for x in range(1,len(input_files)):
        input_file = input_files[x]
        output_file = input_file[:-4]+'.pdf'
        os.system('rm -r '+str(input_file))
        os.system('rm -r '+str(output_file))
