#
#
def _check_harmonic( periods: np.ndarray, power: np.ndarray,
                    p_peak: float, frac: float = 0.05,
                   ) -> tuple:
    """
    Check whether the 2P candidate has higher power than P,
    which would indicate p_peak is actually P_rot/2.

    Returns (harmonic_flag: bool, p_rot_estimate: float).
    """
    p2_target = 2.0 * p_peak
    tol = frac * p2_target
    in_window = np.abs(periods - p2_target) < tol

    if not np.any(in_window) or p2_target > np.nanmax(periods):
        # 2P is outside the searched range; can't determine
        return False, p_peak

    power_at_2p = float(np.nanmax(power[in_window]))
    power_at_p  = float(power[np.argmin(np.abs(periods - p_peak))])

    if power_at_2p > power_at_p:
        return True, p2_target
    return False, p_peak

def _bootstrap_fap( time, flux, error, 
                   observed_peak: float, n_bootstrap: int, 
                   min_period: Optional[float], max_period: Optional[float],
                   nterms_use: int,
                  ) -> float:
    """
    Estimate FAP by counting how often a shuffled light curve exceeds the
    observed peak power. O(n_bootstrap × N_freq) — keep n_bootstrap ≤ 200.
    """
    rng = np.random.default_rng(seed=42)
    exceed = 0
    for _ in range(n_bootstrap):
        f_shuf = rng.permutation(flux)
        _, pw_shuf, pk_shuf, _, _ = LS(
            time, f_shuf, error,
            min_period=min_period, max_period=max_period,
            nterms=nterms_use,
        )
        if pk_shuf >= observed_peak:
            exceed += 1
    return float(exceed) / float(n_bootstrap)

def _ls_results_for_flux( time: np.ndarray, flux: np.ndarray, error: Optional[np.ndarray] = None,
                         min_period: float = 0.5, max_period: Optional[float] = None,
                         nterms: int = 1, n_bootstrap: int = 100,
                         fap_bootstrap: bool = False, harmonic_frac: float = 0.05,
                        ) -> dict:
    """
    Compute all Lomb-Scargle metrics for a single flux array.

    Runs ``LS`` to obtain the periodogram, identifies the peak period,
    checks for a half-period harmonic (which would indicate the true
    rotation period is 2× the detected peak), computes FAP analytically
    or via bootstrap, and optionally computes a 2-term GLS periodogram.

    Parameters
    ----------
    time : np.ndarray, shape (T,)
        Timestamps in days.
    flux : np.ndarray, shape (T,)
        Normalized flux values (finite only; NaNs should be pre-filtered).
    error : np.ndarray, shape (T,) or None, optional
        Per-cadence flux uncertainties.  ``None`` = uniform weights.
        Default is ``None``.
    min_period : float, optional
        Minimum period to search (days).  Default is ``0.5``.
    max_period : float or None, optional
        Maximum period to search (days).  ``None`` defers to the
        ``autopower`` default.  Default is ``None``.
    nterms : int, optional
        Number of Fourier terms.  ``1`` = standard LS, ``2`` = two-term GLS.
        Default is ``1``.
    n_bootstrap : int, optional
        Shuffle resamples for bootstrap FAP estimation.  Used when
        ``nterms > 1`` or ``fap_bootstrap=True``.
        Keep ``≤ 200`` for practical runtime.  Default is ``100``.
    fap_bootstrap : bool, optional
        Force bootstrap FAP even for ``nterms=1``.  Default is ``False``.
    harmonic_frac : float, optional
        Fractional period tolerance when searching for the 2× harmonic.
        A 2P candidate must lie within ``harmonic_frac × 2P`` of the
        detected peak period.  Default is ``0.05``.

    Returns
    -------
    result : dict
        Dictionary with the following keys:

        ``periods`` : np.ndarray — full period grid (days).
        ``power`` : np.ndarray — normalized LS power at each period.
        ``peak_period`` : float — period of the highest peak (days).
        ``peak_power`` : float — LS power at the peak.
        ``power_snr`` : float — ``peak_power / nanmedian(power)``.
        ``fap`` : float — false alarm probability at the peak.
        ``harmonic_flag`` : bool — ``True`` if the 2P candidate has
            higher power than P, suggesting the true rotation period is
            ``2 × peak_period``.
        ``p_rot_est`` : float — harmonic-disambiguated rotation period
            estimate (days); equals ``2 × peak_period`` if
            ``harmonic_flag`` is ``True``, else ``peak_period``.
        ``ls_model`` : astropy.timeseries.LombScargle — fitted model
            object; can be used to compute phase-folded model flux via
            ``ls_model.model(time, peak_period)``.

        If ``nterms == 2``, these additional keys are present:

        ``periods_2t`` : np.ndarray — 2-term period grid.
        ``power_2t`` : np.ndarray — 2-term power.
        ``peak_period_2t`` : float — 2-term peak period.
        ``peak_power_2t`` : float — 2-term peak power.
        ``power_snr_2t`` : float — 2-term power SNR.
        ``fap_2t`` : float — 2-term bootstrap FAP.
        ``ls_model_2t`` : astropy.timeseries.LombScargle — 2-term model.

    Notes
    -----
    Analytic FAP (from ``LS.false_alarm_probability``) is only valid for
    ``nterms=1`` with Gaussian noise.  For ``nterms=2`` the analytic
    formula underestimates FAP because the model has more free parameters
    per frequency; bootstrap FAP is used instead.

    Examples
    --------
    >>> r = _ls_results_for_flux(t, f, e, min_period=0.5, max_period=13.5)
    >>> print(f"P_rot ≈ {r['p_rot_est']:.3f} d  (harmonic={r['harmonic_flag']})")
    >>> print(f"FAP = {r['fap']:.3e}")
    """
    try:
        from astropy.timeseries import LombScargle
    except ImportError:
        from astropy.stats import LombScargle

    finite = np.isfinite(time) & np.isfinite(flux)
    t_c = time[finite]
    f_c = flux[finite]
    e_c = error[finite] if error is not None else None

    # ── 1-term periodogram ────────────────────────────────────────────────────
    periods, power, p1, pw1, pfap1 = LS(
        t_c, f_c, e_c,
        min_period=min_period, max_period=max_period,
        nterms=1,
    )
    snr1 = float(pw1 / np.nanmedian(power)) if np.nanmedian(power) > 0 else np.nan

    # FAP
    ls1 = LombScargle(t_c, f_c, e_c, nterms=1, fit_mean=True)
    if fap_bootstrap or nterms > 1:
        fap1 = _bootstrap_fap(t_c, f_c, e_c, pw1, n_bootstrap,
                              min_period=min_period, max_period=max_period,
                              nterms_use=1)
    else:
        try:
            fap1 = pfap1
        except Exception:
            fap1 = np.nan

    # ── harmonic check ────────────────────────────────────────────────────────
    # Is there a peak near 2 × p1 with comparable or higher power?
    # If so, the true rotation period is likely 2 × p1 (half-period harmonic).
    harmonic_flag, p_rot = _check_harmonic(periods, power, p1, harmonic_frac)

    out = dict(
        periods=periods, power=power,
        peak_period=p1, peak_power=pw1,
        power_snr=snr1, fap=fap1,
        harmonic_flag=harmonic_flag, p_rot_est=p_rot,
        ls_model=ls1,
    )

    # ── optional 2-term periodogram ───────────────────────────────────────────
    if nterms == 2:
        periods_2t, power_2t, p2, pw2, pfap2 = LS(
            t_c, f_c, e_c,
            min_period=min_period, max_period=max_period,
            nterms=2,
        )
        snr2 = float(pw2 / np.nanmedian(power_2t)) if np.nanmedian(power_2t) > 0 else np.nan
        fap2 = _bootstrap_fap(t_c, f_c, e_c, pw2, n_bootstrap,
                              min_period=min_period, max_period=max_period,
                              nterms_use=2)
        ls2 = LombScargle(t_c, f_c, e_c, nterms=2, fit_mean=True)
        out.update(dict(
            periods_2t=periods_2t, power_2t=power_2t,
            peak_period_2t=p2, peak_power_2t=pw2,
            power_snr_2t=snr2, fap_2t=fap2,
            ls_model_2t=ls2,
        ))

    return out

def LC_to_LS( ax, ax1, ax2, ax3, ID, Sector, cadence,
             LC_df, TLS_bestfit_df, default_settings,
             filter_period: Optional[float] = None, nterms: int = 1,
             fap_bootstrap: bool = False, n_bootstrap: int = 100,
            ):
    """
    Render the LS periodogram and phase-folded LC panels for vetting report page 3.

    Computes Lomb-Scargle periodograms for SAP, PLD, and Detrended flux
    via ``_ls_results_for_flux``, renders all four panels in-place on the
    supplied axes, and appends the LS metrics (peak period, power SNR, FAP,
    harmonic flag, estimated rotation period, and optional 2-term results)
    to ``TLS_bestfit_df`` before re-saving the bestfit CSV to disk.

    Panel assignments
    -----------------
    ``ax``  — Filled-area LS power spectrum (SAP=green, PLD=red,
              Detrended=black) with the transit period and harmonics
              marked in cyan.
    ``ax1`` — SAP full phase-folded LC (``fullphasefold``, ``offset=0.25``).
    ``ax2`` — PLD full phase-folded LC.
    ``ax3`` — Detrended full phase-folded LC.

    Parameters
    ----------
    ax, ax1, ax2, ax3 : matplotlib.axes.Axes
        Pre-created subplot axes for the four panels.  Cleared and
        redrawn in-place.
    ID : int
        TIC identifier; used for axis titles and the output CSV filename.
    Sector : int, list, or None
        Sector(s) processed; used for titles and output filename.
    cadence : str
        TESS exposure cadence string.
    LC_df : pd.DataFrame
        Final processed light curve.  Required columns:
        ``Time``, ``SAP Flux``, ``PLD Flux``, ``Detrended Flux``.
    TLS_bestfit_df : pd.DataFrame
        Best-fit transit parameter DataFrame (BLS or TLS); LS metric
        columns are appended and the DataFrame is re-saved to disk.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``minP``, ``N_transits``,
        ``get_all_sectors``, ``verbose``,
        ``saveReportpath_BLS``, ``saveReportpath_TLS``.
    filter_period : float or None, optional
        High-pass filter cutoff for the LS computation (days).
        Default is ``None``.
    nterms : int, optional
        Number of Fourier terms for the LS fit.  ``1`` = standard LS,
        ``2`` = two-term GLS.  Default is ``1``.
    fap_bootstrap : bool, optional
        Force bootstrap FAP estimation even for ``nterms=1``.
        Default is ``False``.
    n_bootstrap : int, optional
        Number of shuffle resamples for bootstrap FAP.  Only used when
        ``nterms > 1`` or ``fap_bootstrap=True``.  Default is ``100``.

    Returns
    -------
    None
        Panels are drawn in-place on the supplied axes.

    Notes
    -----
    Side effect: the following columns are appended to ``TLS_bestfit_df``
    and the bestfit CSV re-saved to disk:
    ``{prefix} LS peak period``, ``{prefix} LS power SNR``,
    ``{prefix} LS FAP``, ``{prefix} harmonic flag``,
    ``{prefix} P_rot est``, and (if ``nterms=2``) ``{prefix} 2term *``
    columns, where ``{prefix}`` is one of ``SAP``, ``PLD``, ``Detrended``.
    """
    # ── settings ──────────────────────────────────────────────────────────────
    get_all_sectors = default_settings.get('get_all_sectors')
    N_transits      = default_settings.get('N_transits', 3)
    min_period      = default_settings.get('minP', 1.0)
    max_period_ds   = default_settings.get('maxP', None)
    save_rpt_bls    = default_settings.get('saveReportpath_BLS')
    save_rpt_tls    = default_settings.get('saveReportpath_TLS')
    verbose         = default_settings.get('verbose', False)
    fs  = 12
    ms  = 1

    # ── transit period / T0 / Dur from bestfit_df ─────────────────────────────
    try:
        P_transit = TLS_bestfit_df['TLS Period [d]'].item()
        T0        = TLS_bestfit_df['TLS TC [BTJD]'].item()
        Dur       = TLS_bestfit_df['TLS Dur [hrs]'].item()
        Depth     = TLS_bestfit_df['TLS depth [ppt]'].item() / 1000
        BLSorTLS  = 'TLS'
    except KeyError:
        P_transit = TLS_bestfit_df['BLS Period [d]'].item()
        T0        = TLS_bestfit_df['BLS TC [BTJD]'].item()
        Dur       = TLS_bestfit_df['BLS Dur [hrs]'].item()
        Depth     = TLS_bestfit_df['BLS depth [ppt]'].item() / 1000
        BLSorTLS  = 'BLS'

    saveReportpath = save_rpt_bls if BLSorTLS == 'BLS' else save_rpt_tls

    # ── sector tag ────────────────────────────────────────────────────────────
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = 'Multi_Sector'
    else:
        sector_tag = f'Sector_{Sector:04d}'

    if max_period_ds is None:
        lc_dur = float(np.nanmax(LC_df['Time']) - np.nanmin(LC_df['Time']))
        max_period_ds = lc_dur / max(N_transits, 2)

    # ── per-flux LS computation (new analytical backbone) ─────────────────────
    flux_specs = [
        ('SAP',       'SAP Flux',       'g'),
        ('PLD',       'PLD Flux',       'r'),
        ('Detrended', 'Detrended Flux', 'k'),
    ]

    results = {}
    for label, col, _ in flux_specs:
        t = LC_df['Time'].to_numpy(dtype=np.float64)
        f = LC_df[col].to_numpy(dtype=np.float64)
        finite = np.isfinite(t) & np.isfinite(f)
        results[label] = _ls_results_for_flux(
            t[finite], f[finite],
            min_period=min_period, max_period=max_period_ds,
            nterms=nterms,
            fap_bootstrap=fap_bootstrap,
            n_bootstrap=n_bootstrap,
        )
        if verbose:
            r = results[label]
            print(f'[LC_to_LS] {label}: P_peak={r["peak_period"]:.3f} d  '
                  f'SNR={r["power_snr"]:.1f}  FAP={r["fap"]:.3e}  '
                  f'harmonic={r["harmonic_flag"]}  P_rot={r["p_rot_est"]:.3f} d')

    # ── convenience aliases ───────────────────────────────────────────────────
    SAP_peak_period = results['SAP']['peak_period']
    SAP_peak_power  = results['SAP']['peak_power']
    PLD_peak_period = results['PLD']['peak_period']
    DET_peak_period = results['Detrended']['peak_period']

    # =========================================================================
    # PANEL 1: LS periodogram  (OLD visual style)
    # =========================================================================
    ax.clear()
    maxpowers = []
    minpowers = []

    color_map   = {'SAP': 'green', 'PLD': 'red', 'Detrended': 'black'}
    peak_map    = {'SAP': SAP_peak_period, 'PLD': PLD_peak_period, 'Detrended': DET_peak_period}
    ls_map      = {'SAP': '--', 'PLD': '--', 'Detrended': '--'}

    for label, col, col_hex in flux_specs:
        r       = results[label]
        periods = r['periods']
        power   = r['power']
        p_rot   = r['p_rot_est']
        c       = color_map[label]

        sde = (power - np.nanmean(power)) / np.nanmedian(power)
        maxpowers.append(np.nanmax(sde))
        minpowers.append(np.nanmin(sde))

        ax.plot(periods, sde, f'{col_hex}-', color=c)
        ax.fill_between(
            periods, y1=sde, y2=0, color=c,
            label=f'{label} ; peak LS period: {np.round(p_rot, 3)} d',
            alpha=0.1,
        )
        ax.axvline(x=p_rot, color=c, linestyle='-.')

    # transit period + harmonics
    ax.axvline(
        x=P_transit, color='cyan',
        label=f'{BLSorTLS} period: {np.round(P_transit, 3)}',
    )
    for x in range(2, 10):
        p_over = P_transit / x
        p_times = P_transit * x
        if p_over > np.nanmin(results['Detrended']['periods']):
            ax.axvline(x=p_over,  color='cyan', linestyle='--')
        if p_times < max_period_ds:
            ax.axvline(x=p_times, color='cyan', linestyle='--')

    ax.set_ylim(np.min(minpowers) - 1, np.max(maxpowers) + 5)
    ax.set_xlabel('Period [days]', fontsize=fs)
    ax.set_ylabel('Standardized LS Power', fontsize=fs)
    ax.legend(loc='upper left', ncol=1, borderaxespad=0., framealpha=0.75)

    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        ax.set_title(f'LS analysis for TIC {ID} in Multi-Sector LCs',
                     x=0.55, y=1.02, fontsize=fs)
    else:
        ax.set_title(f'LS analysis for TIC {ID} in Sector {Sector}',
                     x=0.55, y=1.02, fontsize=fs)

    # =========================================================================
    # PANELS 2–4: full phase-folded LCs  (OLD visual style)
    # =========================================================================
    import astropy.units as u
    transit_duration_in_days = (Dur * u.hour).to(u.day).value
    YLIM = 2 * Depth

    t_arr = LC_df['Time'].to_numpy(dtype=np.float64)

    pfsap, ffsap = fullphasefold(t_arr, T0, P_transit,
                                 LC_df['SAP Flux'].to_numpy(dtype=np.float64), offset=0.25)
    pfpld, ffpld = fullphasefold(t_arr, T0, P_transit,
                                 LC_df['PLD Flux'].to_numpy(dtype=np.float64), offset=0.25)
    pfdet, ffdet = fullphasefold(t_arr, T0, P_transit,
                                 LC_df['Detrended Flux'].to_numpy(dtype=np.float64), offset=0.25)

    ax1.clear(); ax2.clear(); ax3.clear()

    ax1.plot(pfsap, ffsap, 'g.', label='SAP',       markersize=ms)
    ax2.plot(pfpld, ffpld, 'r.', label='PLD',       markersize=ms)
    ax3.plot(pfdet, ffdet, 'k.', label='Detrended', markersize=ms)

    for panel_ax in [ax1, ax2, ax3]:
        for v in [0.25, 0.5, 0.75]:
            panel_ax.axvline(x=v, zorder=-10)

    ax3.set_xlabel('Orbital Phase + offset = 0.25', fontsize=fs)
    ax2.set_ylabel('Normalized Relative Flux',       fontsize=fs)
    ax2.set_title('PLD Light Curve')
    ax3.set_title('Detrended Light Curve')
    ax1.set_title('Full Phase folded LC\nSAP Light Curve', x=0.55, y=1.02, fontsize=fs)

    # y-limits: same logic as OLD — depth-aware, falls back to 5*std
    Nstds = 5
    mask1 = np.where(np.abs(pfsap - 0.25) < 3 * transit_duration_in_days / P_transit)[0]
    if len(mask1) > 3:
        ymin = min(1 - YLIM,
                   np.nanmedian(ffsap[mask1]) - Nstds * np.nanstd(ffsap[mask1]))
        ymax = max(1 + YLIM,
                   np.nanmedian(ffsap[mask1]) + Nstds * np.nanstd(ffsap[mask1]))
    else:
        ymin = np.nanmedian(ffsap) - Nstds * np.nanstd(ffsap)
        ymax = np.nanmedian(ffsap) + Nstds * np.nanstd(ffsap)

    ax1.set_ylim(ymin, ymax)
    ax2.set_ylim(ymin, ymax)
    ax3.set_ylim(ymin, ymax)

    # =========================================================================
    # Append LS metrics to bestfit_df and save  (unchanged from new LC_to_LS)
    # =========================================================================
    for label, col, _ in flux_specs:
        r    = results[label]
        pfix = f'{label} LS'
        TLS_bestfit_df[f'{pfix} Period [days]']   = r['peak_period']
        TLS_bestfit_df[f'{pfix} Power SNR']        = r['power_snr']
        TLS_bestfit_df[f'{pfix} FAP']              = r['fap']
        TLS_bestfit_df[f'{pfix} harmonic flag']    = r['harmonic_flag']
        TLS_bestfit_df[f'{pfix} P_rot [d]']        = r['p_rot_est']

        if nterms == 2 and 'peak_period_2t' in r:
            TLS_bestfit_df[f'{pfix} 2term Period [d]'] = r['peak_period_2t']
            TLS_bestfit_df[f'{pfix} 2term Power SNR']  = r['power_snr_2t']
            TLS_bestfit_df[f'{pfix} 2term FAP']        = r['fap_2t']

    if saveReportpath is not None:
        if get_all_sectors or Sector is None or not isinstance(Sector, int):
            out_path = f'{saveReportpath}TIC_{ID}_Multi_Sector_{BLSorTLS}_bestfit.csv'
        else:
            out_path = f'{saveReportpath}TIC_{ID}_{sector_tag}_{BLSorTLS}_bestfit.csv'
        TLS_bestfit_df.to_csv(out_path, index=False)
#
#
#
def calc_transit_times(T0, t, period):
    """
    Return all mid-transit times within t
    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    if T0 < min(t):
        transit_times = [T0 + period]
    else:
        transit_times = [T0]
    previous_transit_time = transit_times[0]
    transit_number = 0
    while True:
        transit_number = transit_number + 1
        next_transit_time = previous_transit_time + period
        if next_transit_time < (np.min(t) + (np.max(t) - np.min(t))):
            transit_times.append(next_transit_time)
            previous_transit_time = next_transit_time
        else:
            break
    return transit_times
#
def calc_mean_depths(time,flux,T0,P,Dur):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    transit_times = calc_transit_times(T0, time, P)
    transit_depths = np.zeros([len(transit_times)])
    transit_depths_uncertainties = np.zeros([len(transit_times)])
    #
    transit_duration_in_days = Dur#*24 #hrs to days
    #
    for i in range(len(transit_times)):
        #
        depth_mean_odd = np.nan
        depth_mean_even = np.nan
        depth_mean_odd_std = np.nan
        depth_mean_even_std = np.nan
        #
        mid_transit = transit_times[i]#
        tmin = mid_transit - 0.5 * transit_duration_in_days
        tmax = mid_transit + 0.5 * transit_duration_in_days
        #
        if np.isnan(tmin) or np.isnan(tmax):
            idx_intransit = []
            flux_intransit = []
            mean_flux = np.nan
        else:
            idx_intransit = np.where(np.logical_and(time > tmin, time < tmax))[0]
            flux_intransit = flux[idx_intransit]
            if len(flux[idx_intransit]) > 0:
                mean_flux = np.mean(flux[idx_intransit])
            else:
                mean_flux = np.nan
        intransit_points = np.size(flux[idx_intransit])
        transit_depths[i] = mean_flux
        #
    return transit_depths
#
#
def odd_even_cuts(ID,Sector,LC_df,P,T0,Dur,Depth):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    #
    time = LC_df['Time'].to_numpy(dtype=np.float64)
    flux = LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    error =LC_df['Detrended Error'].to_numpy(dtype=np.float64)
    #
    T_C_array = calc_transit_times(T0, time, P)
    Depths_array = calc_mean_depths(time,flux,T0,P,Dur)
    #
    window_size = 1 #day
    EvenDepths=[]
    OddDepths=[]
    Even=[]
    Evenflux=[]
    Odd=[]
    Oddflux=[]
    for x in range(len(T_C_array)):
        if x %2 ==0: #even
            EvenDepths=np.append(EvenDepths,Depths_array[x])
            cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
            cut_t  =  time[cut]
            cut_f  =  flux[cut]
            cut_fe = error[cut]
            if len(cut_f)<1: #in case window size is too small to cut data around
                window_size=1.5
                cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
                cut_t  =  time[cut]
                cut_f  =  flux[cut]
                cut_fe = error[cut]
            ###
            phasefolded,foldedflux = phasefold(T_C_array[x],cut_t,P,cut_f)
            Even=np.append(Even,phasefolded)
            Evenflux=np.append(Evenflux,foldedflux)
            #
            #
        else: #odd
            OddDepths=np.append(OddDepths,Depths_array[x])
            cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
            cut_t  =  time[cut]
            cut_f  =  flux[cut]
            cut_fe = error[cut]
            if len(cut_f)<1: #in case window size is too small to cut data around
                window_size=1.5
                cut = np.where( ((T_C_array[x]-window_size) < time) & ((T_C_array[x]+window_size) > time)  )[0]
                cut_t  =  time[cut]
                cut_f  =  flux[cut]
                cut_fe = error[cut]
            phasefolded,foldedflux = phasefold(T_C_array[x],cut_t,P,cut_f)
            Odd=np.append(Odd,phasefolded)
            Oddflux=np.append(Oddflux,foldedflux)
    return Odd,Oddflux,OddDepths, Even,Evenflux,EvenDepths
