def odd_even_mismatch_plot(ax1,ax2,ax3,ax4,ax5,ax6,ax7,ax8,ax9,ID,Sector,cadence,LC_df,TLSbestfit_df,path):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """  
    #
    c1='red'
    c2='blue'
    #
    #
    markersize=2
    fontsize=12
    #
    time = LC_df['Time'].to_numpy(dtype=np.float64)
    flux = LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    error =LC_df['Detrended Error'].to_numpy(dtype=np.float64)
    #
    try:
        P = TLSbestfit_df['TLS Period [d]'].item()
        T0 = TLSbestfit_df['TLS TC [BTJD]'].item()
        Dur = TLSbestfit_df['TLS Dur [hrs]'].item()
        Depth = TLSbestfit_df['TLS depth [ppt]'].item()/1e3
    except KeyError:
        P = TLSbestfit_df['BLS Period [d]'].item()
        T0 = TLSbestfit_df['BLS TC [BTJD]'].item()
        Dur = TLSbestfit_df['BLS Dur [hrs]'].item()
        Depth = TLSbestfit_df['BLS depth [ppt]'].item()/1e3        
    #
    spacing = 4* (Depth)
    # XLIM=1.5*Dur
    XLIM=3.5*Dur        
    pf,ff= phasefold(T0,time,P,flux)    
    #
    Odd,Oddflux,OddDepths, Even,Evenflux,EvenDepths = odd_even_cuts(ID,Sector,LC_df,0.5*P,T0,Dur,Depth)
    #
    ax1.plot(24*Odd,np.array(Oddflux),color=c1,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Odd')
    ax2.plot(24*Even,np.array(Evenflux),color=c2,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Even')
    #
    #ax1.set_title('Odd')
    ax1.set_xlim(-XLIM,XLIM)
    #
    ax2.set_title('Even')
    ax2.set_xlim(-XLIM,XLIM)
    ax2.set_ylabel('Normalized Flux',fontsize=fontsize)
    #
    ax3.set_title('Both')
    ax3.plot(24*Odd,np.array(Oddflux),color=c1,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Odd')
    ax3.plot(24*Even,np.array(Evenflux),color=c2,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Even')
    ax3.set_xlim(-XLIM,XLIM)
    ax3.set_xlabel('Phase [Hours since '+str(np.round(T0,3))+' [BTJD]',fontsize=fontsize)
    #
    modd = np.abs(24*Odd) < 3*Dur*24
    meven = np.abs(24*Even) < 3*Dur*24
    try:
        depthodd = 1 - np.nanmin(np.array(Oddflux)[modd])
    except ValueError:
        depthodd=None
    try:
        deptheven = 1 - np.nanmin(np.array(Evenflux)[meven]) 
    except ValueError:
        deptheven=None
    if depthodd is not None:
        ax3.axhline(y=1-depthodd,color='green',linestyle='-')
    if deptheven is not None:
        ax3.axhline(y=1-deptheven,color='green',linestyle='--',label='Odd/Even Mismatch')
    #
    Odd,Oddflux,OddDepths, Even,Evenflux,EvenDepths = odd_even_cuts(ID,Sector,LC_df,1.0*P,T0,Dur,Depth)
    #
    ax4.plot(24*Odd,np.array(Oddflux),color=c1,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Odd')
    ax5.plot(24*Even,np.array(Evenflux),color=c2,marker='.',\
             linestyle='none',markersize=markersize+1,rasterized=True,label='Even')
    #
    #ax4.set_title('Odd')
    ax4.set_xlim(-XLIM,XLIM)
    #
    ax5.set_title('Even')
    ax5.set_xlim(-XLIM,XLIM)
    #
    ax6.set_title('Both')
    ax6.plot(24*Odd,np.array(Oddflux),color=c1,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Odd')
    ax6.plot(24*Even,np.array(Evenflux),color=c2,marker='.',\
             linestyle='none',markersize=markersize+1,rasterized=True,label='Even')
    ax6.set_xlim(-XLIM,XLIM)
    ax6.set_xlabel('Phase [Hours since '+str(np.round(T0,3))+' [BTJD]',fontsize=fontsize)
    #
    modd = np.abs(24*Odd) <  3*Dur*24
    meven = np.abs(24*Even) < 3*Dur*24
    try:
        depthodd = 1 - np.nanmin(np.array(Oddflux)[modd])
    except ValueError:
        depthodd=None
    try:
        deptheven = 1 - np.nanmin(np.array(Evenflux)[meven])
    except ValueError:
        deptheven=None
    if depthodd is not None:
        ax6.axhline(y=1-depthodd,color='green',linestyle='-')
    if deptheven is not None:
        ax6.axhline(y=1-deptheven,color='green',linestyle='--',label='Odd/Even Mismatch')
    #
    Odd,Oddflux,OddDepths, Even,Evenflux,EvenDepths = odd_even_cuts(ID,Sector,LC_df,2.0*P,T0,Dur,Depth)
    #
    ax7.plot(24*Odd,np.array(Oddflux),color=c1,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Odd')
    ax8.plot(24*Even,np.array(Evenflux),color=c2,marker='.',\
             linestyle='none',markersize=markersize+1, rasterized=True,label='Even')
    #
    #ax7.set_title('Odd')
    ax7.set_xlim(-XLIM,XLIM)
    #
    ax8.set_title('Even')
    ax8.set_xlim(-XLIM,XLIM)
    #
    ax9.set_title('Both')
    ax9.plot(24*Odd,np.array(Oddflux),color=c1,marker='.',linestyle='none',\
             markersize=markersize+1, rasterized=True,label='Odd')
    ax9.plot(24*Even,np.array(Evenflux),color=c2,marker='.',linestyle='none',\
             markersize=markersize+1,rasterized=True,label='Even')
    ax9.set_xlim(-XLIM,XLIM)
    ax9.set_xlabel('Phase [Hours since '+str(np.round(T0,3))+' [BTJD]',fontsize=fontsize)
#     ax9.set_ylabel('Normalized Flux',fontsize=fontsize)
    # 
    modd = np.abs(24*Odd) < 3*Dur*24
    meven = np.abs(24*Even) < 3*Dur*24
    try:
        depthodd = 1 - np.nanmin(np.array(Oddflux)[modd])
    except ValueError:
        depthodd=None
    try:
        deptheven = 1 - np.nanmin(np.array(Evenflux)[meven])
    except ValueError:
        deptheven=None
    if depthodd is not None:
        ax9.axhline(y=1-depthodd,color='green',linestyle='-')
    if deptheven is not None:
        ax9.axhline(y=1-deptheven,color='green',linestyle='--',label='Odd/Even Mismatch')
    #
    ax1.set_title('All Odd / Even Events at 0.5x Period'+'\n'+'Odd',x=0.55,y=1.02,fontsize=fontsize)
    ax4.set_title('All Odd / Even Events at 1x Period'+'\n'+'Odd',x=0.55,y=1.02,fontsize=fontsize)
    ax7.set_title('All Odd / Even Events at 2x Period'+'\n'+'Odd',x=0.55,y=1.02,fontsize=fontsize)
    #
    Nstds=5
    ymin,ymax = np.nanmedian(ff)-Nstds*np.nanstd(ff),np.nanmedian(ff)+Nstds*np.nanstd(ff)
    #
    YLIM=2*Depth        
    Nstds=5
    mask1= np.where(np.abs(ff)<3*Dur)
    if 1-YLIM > np.nanmedian(ff[mask1])-Nstds*np.nanstd(ff[mask1]):
        ymin=np.nanmedian(ff[mask1])-Nstds*np.nanstd(ff[mask1])
    else:
        ymin=1-YLIM
    if 1+YLIM < np.nanmedian(ff[mask1])+Nstds*np.nanstd(ff[mask1]):
        ymax=np.nanmedian(ff[mask1])+Nstds*np.nanstd(ff[mask1])
    else:
        ymax=1+YLIM            
    ax1.set_ylim(ymin,ymax)
    ax2.set_ylim(ymin,ymax)
    ax3.set_ylim(ymin,ymax)
    ax4.set_ylim(ymin,ymax)
    ax5.set_ylim(ymin,ymax)
    ax6.set_ylim(ymin,ymax)
    ax7.set_ylim(ymin,ymax)
    ax8.set_ylim(ymin,ymax)
    ax9.set_ylim(ymin,ymax)    
