def Vetting_Report_2nd_page(ID, nearby_star_catalog, Sector, LC_df, hdu,
                                path, cadence,
                                TLSbestfit_df, BLSorTLS,
                                default_settings,
                                # --- optional SAP diagnostic kwargs (new) ---
                                bkg_residuals=None, bkg_trend=None, bkg_level_per_pix=None,
                                quat_jitter=None, quat_status="not provided",
                                qlp_result=None, quality_flag=None):
    """
    Produce page 2 of the NEMESIS vetting report: the full LC summary figure.

    Reads all intermediate LC CSVs from disk and calls ``plot_it_all_up``
    to render the full SAP/PLD/Detrended/Final LC panel layout, with
    optional SAP diagnostic panels (background trend, quaternion jitter
    histogram) when the corresponding arrays are provided.

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``.
    Sector : int, list, or None
        Sector(s) processed; used to read the correct CSV files.
    LC_df : pd.DataFrame
        Final processed light curve (used for axis limits).
    hdu : fits.HDUList or list of fits.HDUList
        Raw FITS data; forwarded to ``plot_it_all_up`` for the cutout panel.
    path : str
        Base path (passed through; not directly used).
    cadence : str
        TESS exposure cadence string.
    TLSbestfit_df : pd.DataFrame
        Best-fit transit parameter DataFrame (BLS or TLS); used to
        construct the output filename.
    BLSorTLS : str
        ``'BLS'`` or ``'TLS'``; selects the report directory.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``get_all_sectors``,
        ``for_injections``, ``inject_param_P_RP_T0``, ``verbose``,
        ``saveReportpath_BLS``, ``saveReportpath_TLS``, ``savelcpath``.
    bkg_level_per_pix : np.ndarray or None, optional
        SAP background level per pixel.  Default is ``None``.
    bkg_trend : np.ndarray or None, optional
        Biweight background trend.  Default is ``None``.
    bkg_residuals : np.ndarray or None, optional
        Background residuals after trend removal.  Default is ``None``.
    quat_jitter : np.ndarray or None, optional
        Quaternion jitter scalar array.  Default is ``None``.
    quat_status : str, optional
        Quaternion masking status string.  Default is ``"not provided"``.
    qlp_result : dict or None, optional
        QLP feature dictionary for the jitter heatmap panel.
        Default is ``None``.
    quality_flag : np.ndarray or None, optional
        Integer quality flag array.  Default is ``None``.

    Returns
    -------
    None
        Figure saved to disk as:
        ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page2.png``
    """
    import gc
    import numpy as np
    import pandas as pd

    # ── settings ──────────────────────────────────────────────────────────────
    Nsigma           = default_settings.get('Nsigma')
    verbose          = default_settings.get('verbose')
    get_all_sectors  = default_settings.get('get_all_sectors')
    for_injections   = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    savelcpath       = default_settings.get('savelcpath')
    downloadpath     = default_settings.get('downloadpath')
    savefigpath      = default_settings.get('savefigpath')

    if BLSorTLS == 'BLS':
        report_dir_name_suffix = 'BLS_Report'
        saveReportpath = default_settings.get('saveReportpath_BLS')
    else:
        report_dir_name_suffix = 'TLS_Report'
        saveReportpath = default_settings.get('saveReportpath_TLS')

    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"

    # ── read per-sector LC CSV files from disk ────────────────────────────────
    if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
        Raw_LC_df     = pd.read_csv(savelcpath + f"TIC_{ID}_Multi_Sector_RAW_LC.csv")
        Rawclip_LC_df = pd.read_csv(savelcpath + f"TIC_{ID}_Multi_Sector_RAW_LC_systematics_removed.csv")
        Preclip_LC_df = pd.read_csv(savelcpath + f"TIC_{ID}_Multi_Sector_final_LC_preclipped.csv")
        good_ind_df   = pd.read_csv(savelcpath + f"TIC_{ID}_Multi_Sector_good_outliers.csv")
        bad_ind_df    = pd.read_csv(savelcpath + f"TIC_{ID}_Multi_Sector_bad_outliers.csv")
    else:
        Raw_LC_df     = pd.read_csv(savelcpath + f"TIC_{ID}_{sector_tag}_RAW_LC.csv")
        Rawclip_LC_df = pd.read_csv(savelcpath + f"TIC_{ID}_{sector_tag}_RAW_LC_systematics_removed.csv")
        Preclip_LC_df = pd.read_csv(savelcpath + f"TIC_{ID}_{sector_tag}_final_LC_preclipped.csv")
        good_ind_df   = pd.read_csv(savelcpath + f"TIC_{ID}_{sector_tag}_good_outliers.csv")
        bad_ind_df    = pd.read_csv(savelcpath + f"TIC_{ID}_{sector_tag}_bad_outliers.csv")

    # ── page-2 output filename ────────────────────────────────────────────────
    page_num = 2
    if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
        savefigname = (saveReportpath + f'TIC_{ID}_Multi_Sector_'
                       + report_dir_name_suffix + f'_page{page_num}.png')
    else:
        savefigname = (saveReportpath + f'TIC_{ID}_{sector_tag}_'
                       + report_dir_name_suffix + f'_page{page_num}.png')

    # ── bundle SAP diagnostic kwargs for forwarding ───────────────────────────
    _diag_kwargs = dict(
        bkg_residuals     = bkg_residuals,
        bkg_trend         = bkg_trend,
        bkg_level_per_pix = bkg_level_per_pix,
        quat_jitter       = quat_jitter,
        quat_status       = quat_status,
        qlp_result        = qlp_result,
        quality_flag      = quality_flag,
    )

    # ── dispatch to appropriate plotting function ─────────────────────────────
    if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
        # Multi-sector: use plot_it_all_up_multi
        plot_it_all_up(
            ID=ID,
            nearby_star_catalog=nearby_star_catalog,
            Sector=Sector,
            cadence=cadence,
            hdu=hdu,
            RAWLC_df=Raw_LC_df,
            clippedRAWLC_df=Rawclip_LC_df,
            LC_df=LC_df,
            good_ind_DF=good_ind_df,
            bad_ind_DF=bad_ind_df,
            preclipLC_df=Preclip_LC_df,
            default_settings=default_settings,
            savefigname=savefigname,
            # SAP diagnostics forwarded from caller
            bkg_residuals=bkg_residuals,
            bkg_trend=bkg_trend,
            bkg_level_per_pix=bkg_level_per_pix,
            quat_jitter=quat_jitter,
            quat_status=quat_status,
            qlp_result=qlp_result,
            quality_flag=quality_flag,
            target_page_height=10.0,
            fs = 16-4,
        )
    else:
        # Single sector: use plot_it_all_up
        # We need median_image and pixel masks for this path.
        median_image = np.nanmedian(hdu[1].data['FLUX'], axis=0)
        pix_mask, bkg_mask, images, matched_sectors = \
            get_pix_and_bkg_masks_and_image_fluxes(ID, Sector, cadence, default_settings)

        plot_it_all_up(
            ID=ID,
            nearby_star_catalog=nearby_star_catalog,
            Sector=Sector,
            cadence=cadence,
            hdu=hdu,
            RAWLC_df=Raw_LC_df,
            clippedRAWLC_df=Rawclip_LC_df,
            LC_df=LC_df,
            good_ind_DF=good_ind_df,
            bad_ind_DF=bad_ind_df,
            preclipLC_df=Preclip_LC_df,
            default_settings=default_settings,
            savefigname=savefigname,
            # single-sector image args — triggers single-sector path
            median_image=median_image, pix_mask=pix_mask, bkg_mask=bkg_mask,
            magnitude_limit=18, dot_scale=20, cbarpad=0.01,
            # SAP diagnostics
            bkg_residuals=bkg_residuals,
            bkg_trend=bkg_trend,
            bkg_level_per_pix=bkg_level_per_pix,
            quat_jitter=quat_jitter,
            quat_status=quat_status,
            qlp_result=qlp_result,
            quality_flag=quality_flag,
            target_page_height=10.0,
            fs = 16-4,            
        )

    # ── release memory ────────────────────────────────────────────────────────
    del Raw_LC_df, Rawclip_LC_df, Preclip_LC_df, good_ind_df, bad_ind_df
    gc.collect()
