def get_flux_at_TN(pf, ff, TN, window=None):
    """
    Get the flux value closest to a specific transit contact point (T1, T4, etc.)
    based on a phase-folded light curve (pf, ff). The window is used to limit
    the search to values close to the contact point (TN).

    Parameters:
    ----------
    pf : array-like
        Phase-folded time array (in days).
    ff : array-like
        Corresponding flux values.
    TN : float
        Transit contact point (T1, T4, etc.) in days.
    window : float, optional
        Search window around TN in days. If None, defaults to 2 hours.

    Returns:
    -------
    closest_time : float
        The phase value closest to the transit contact point (TN).
    closest_flux : float
        The flux value corresponding to the closest_time.
    """

    # Set the default window if none is provided
    if window is None:
        window = (2 * u.hour).to(u.day).value  # Default to 2 hours, converted to days

    # Find indices of data points within the specified window around TN
    window_mask = np.abs(pf - TN) <= window

    # If no points are found within the window, expand the window
    if not np.any(window_mask):
        print(f"No points found within window of {window} days around T{TN}. Expanding window...")
        while not np.any(window_mask):
            window *= 2  # Double the window size
            window_mask = np.abs(pf - TN) <= window
            if window > 12/24:  # Optional: prevent the window from expanding too large
                raise ValueError(f"No points found within expanded window around T{TN}.")

    # Get the phase and flux values within the window
    pf_in_window = pf[window_mask]
    ff_in_window = ff[window_mask]

    # Find the index of the phase value closest to TN
    closest_idx = np.argmin(np.abs(pf_in_window - TN))

    # Return the phase and flux values at the closest point
    return pf_in_window[closest_idx], ff_in_window[closest_idx]
