def create_box_model(times, period, epoch, duration, depth): #UNUSED BUT USEFUL
    """Create boxcar model.
    Parameters
    ----------
    times : array
        Times.
    period : float
        Period.
    epoch : float
        Epoch.
    duration  : float
        Duration.
    depth : `~astropy.units.Quantity`
        Depth.
    Returns
    -------
    flux : `~astropy.units.Quantity`
        Flux from boxcar model, in the same unit as ``depth``.
    See also
    --------
    create_box_model_for_tce
    """
    # Make epoch the start of the transit, not the midpoint
    epoch -= duration * 0.5

    mnT = np.min(times)
    mxT = np.max(times)
    
    #calculate orbit numbers
    e0 = int(np.floor((mnT - epoch) / period))
    e1 = int(np.floor((mxT - epoch) / period))
    
    box = np.zeros_like(times)
    for i in range(e0, e1 + 1):
        t0 = period * i + epoch
        t1 = t0 + duration
        idx = (t0 <= times) & (times <= t1)
        box[idx] =1- depth
    box = -box #invert it
    return box+1

def create_box_model_for_phasefolded(pf, period, epoch, duration, depth): #UNUSED BUT USEFUL
    """Create boxcar model.
    Parameters
    ----------
    pf : array
        Phasefolded time stamps
    period : float
        Period.
    epoch : float
        Epoch.
    duration  : float
        Duration.
    depth : `~astropy.units.Quantity`
        Depth.
    Returns
    -------
    flux : `~astropy.units.Quantity`
        Flux from boxcar model, in the same unit as ``depth``.
    See also
    --------
    create_box_model_for_tce
    """
    box = np.zeros_like(pf)
    idx = (pf>=-duration/2)& (pf<=duration/2)
    box[idx] =1- depth
    box = -box #invert it
    return box+1

def bin_ff(pf,ff,duration,cadence):

    Ndur=4
    
    import astropy.units as u
    if ((cadence*u.day).to(u.minute)).value < (10*u.minute).value:
        min_bins = 100
    else:
        min_bins = 25
    nbins = np.max([int(Ndur * duration / cadence), min_bins])
    print('nbins in bin_ff:',nbins, 'vs',int(Ndur * duration / cadence))

    bins = np.linspace(np.nanmin(pf[np.abs(pf) <= Ndur*duration]), np.nanmax(pf[np.abs(pf) <= Ndur*duration]), nbins+1 )
    # Compute histogram denominator (number of points in each bin)
    denom, _ = np.histogram(pf, bins)    
    # Compute histogram numerator (sum of fluxes in each bin)
    num, _ = np.histogram(pf, bins, weights=ff)
    # Identify bins with valid data (denominator > 0)
    valid_bins = denom > 0
    # Initialize binned flux array with NaNs
    binned_flux = np.full(nbins, np.nan)
    # Calculate binned flux where denom > 0
    binned_flux[valid_bins] = num[valid_bins] / denom[valid_bins]
    # Calculate bin centers
    bin_centers = 0.5 * (bins[1:] + bins[:-1])
    # Return only valid bins
    return bin_centers[valid_bins], binned_flux[valid_bins]
