import numpy as np

def nanchecker(mirrored_phases, mirrored_fluxes, check_mirrored_fluxes, Nstd, duration, verbose=False):
    """
    Adjusts the standard deviation threshold to remove NaNs from mirrored fluxes.

    Parameters:
    ----------
    mirrored_phases : tuple
        A tuple containing phase arrays for the target and mirrored fluxes (phase, mirror_phase_L, mirror_phase_R).
    mirrored_fluxes : tuple
        A tuple containing flux arrays for the target and mirrored fluxes (flux, flux_L, flux_R).
    check_mirrored_fluxes : tuple
        A tuple containing mirrored fluxes to check for NaNs (mff, mffL, mffR).
    Nstd : float
        Initial threshold multiplier for standard deviation.
    duration : float
        Duration used for phase comparison.
    verbose : bool, optional
        If True, prints additional information for debugging.

    Returns:
    -------
    tuple
        Indices of non-NaN values for the target and mirrored fluxes (md, mdL, mdR).
    """
    # Unpack variables
    phase, mirror_phase_L, mirror_phase_R = mirrored_phases
    flux, flux_L, flux_R = mirrored_fluxes
    mff, mffL, mffR = check_mirrored_fluxes

    #max_iterations = 20  # Prevent infinite loops
    iteration = 0

    if verbose:
        print(f'Starting Nstd: {Nstd}')

    while Nstd > 0:# and iteration < max_iterations:
        iteration += 1

        # Check if medians of mff, mffL, mffR are NaN
        is_nan = (
            np.isnan(np.nanmedian(mff)) or
            np.isnan(np.nanmedian(mffL)) or
            np.isnan(np.nanmedian(mffR))
        )

        if is_nan:
            if verbose:
                print(f'Nstd: {Nstd} ; Decreasing Nstd.')
            Nstd -= 0.5
            if Nstd <= 0:
                print("Nstd has become non-positive. Exiting to avoid infinite loop.")
                break

            # Recompute md, mdL, mdR with decreased Nstd
            mdL = (
                (np.abs(mirror_phase_L * 24) < 3 * duration * 24) &
                (flux_L < np.nanmedian(flux_L) - Nstd * np.nanstd(flux_L))
            )
            mdR = (
                (np.abs(mirror_phase_R * 24) < 3 * duration * 24) &
                (flux_R < np.nanmedian(flux_R) - Nstd * np.nanstd(flux_R))
            )
            md = (
                (np.abs(phase * 24) < 3 * duration * 24) &
                (flux < np.nanmedian(flux) - Nstd * np.nanstd(flux))
            )

            # Update mff, mffL, mffR based on new md, mdL, mdR
            mff = flux[md]
            mffL = flux_L[mdL]
            mffR = flux_R[mdR]
        else:
            if verbose:
                print(f'Valid mff medians found at Nstd: {Nstd}')
            break  # Valid mff medians, proceed

    if Nstd <= 0:# or iteration >= max_iterations:
        print("Unable to find valid mff medians. Exiting to avoid infinite loop.")

    # After loop, md, mdL, mdR are already computed with the last Nstd
    # Ensure selections are non-empty and medians are not NaN
    if not (np.any(md) and np.any(mdL) and np.any(mdR)):
        print("Selections md, mdL, or mdR are empty. Exiting.")
        return md, mdL, mdR

    median_flux_md = np.nanmedian(flux[md])
    median_flux_mdL = np.nanmedian(flux_L[mdL])
    median_flux_mdR = np.nanmedian(flux_R[mdR])

    if np.isnan(median_flux_md) or np.isnan(median_flux_mdL) or np.isnan(median_flux_mdR):
        print("NaNs found in medians of selected data. Exiting.")
        return md, mdL, mdR

    if verbose:
        print(f'Final Nstd: {Nstd}')
        print('Median checks passed for md, mdL, mdR.')

    non_nan_mirrored_indices = (md, mdL, mdR)
    return non_nan_mirrored_indices
