# HELPER FUNCTIONS FOR mirror_and_model_left_right_transit
# Sub-function to filter phase and flux arrays to +/-3 * transit_duration
#
def filter_phase_range(phase, flux, transit_duration):
    mask = np.where(np.abs(phase) <= 3*transit_duration)[0]
    return phase[mask], flux[mask]

def align_arrays(phase_data, flux_data, phase_model, model_flux):
    """
    Align the model flux to the data flux by interpolating the model flux to match the phase values of the data.

    Parameters:
    ----------
    phase_data : array
        Phase values of the data.
    flux_data : array
        Flux values of the data.
    phase_model : array
        Phase values of the model.
    model_flux : array
        Flux values of the model.

    Returns:
    -------
    phase_data : array
        Phase values of the data (unmodified).
    aligned_model_flux : array
        Model flux interpolated to match the phase values of the data.
    flux_data : array
        Unmodified flux values of the data.
    """
    from scipy.interpolate import interp1d
    # Interpolate the model flux based on the phase values of the data
    
    
    # Remove NaNs from first dataset
    valid_mask_data = np.isfinite(phase_data) & np.isfinite(flux_data)
    phase_data, flux_data = phase_data[valid_mask_data], flux_data[valid_mask_data]

    # Remove NaNs from second dataset
    valid_mask_model = np.isfinite(phase_model) & np.isfinite(model_flux)
    phase_model, model_flux = phase_model[valid_mask_model], model_flux[valid_mask_model]

    # Nested if-statements to perform all checks
    if len(phase_model) == 0 or len(model_flux) == 0:
        raise ValueError("Input arrays 'phase_model' and 'model_flux' must not be empty.")
    elif len(phase_model) != len(model_flux):
        raise ValueError("Input arrays 'phase_model' and 'model_flux' must have the same length.")
    elif np.any(np.isnan(phase_model)) or np.any(np.isnan(model_flux)):
        raise ValueError("Input arrays 'phase_model' and 'model_flux' must not contain NaN values.")
    else:
        # If all checks pass, proceed with interpolation
        interp_model_flux = interp1d(phase_model, model_flux, kind='linear', bounds_error=False, fill_value='extrapolate')

    # Apply the interpolation to the data phase values
    aligned_model_flux = interp_model_flux(phase_data)

    # Return phase, flux, and aligned model flux
    return phase_data, flux_data, aligned_model_flux
    
def robust_transit_depth(phase, flux, transit_duration, quantile=0.01, 
                         sigma_clip_thresh=3.0, fallback_strategy="weighted"):
    """
    Robust estimation of transit depth using sigma clipping, quantiles, and fallback strategies.

    Parameters:
    ----------
    phase : array-like
        Phase-folded array of time values.
    flux : array-like
        Corresponding flux values for the phase-folded light curve.
    transit_duration : float
        Duration of the transit (days).
    quantile : float, optional
        The quantile used to identify the bottom of the transit. Default is 0.01 (1%).
    sigma_clip_thresh : float, optional
        Sigma clipping threshold for removing outliers. Default is 3.0.
    fallback_strategy : str, optional
        Strategy if sigma clipping fails to yield valid results ('weighted', 'no_clip', 'bootstrap'). 
        Default is 'weighted'.

    Returns:
    -------
    depth_estimate : float
        The estimated transit depth.
    depth_uncertainty : float
        The uncertainty (standard deviation) of the transit depth.
    """
    #
    import numpy as np
    from astropy.stats import sigma_clip
    from scipy.stats import median_abs_deviation as mad
    #
    # Step 1: Limit data points to within ±1 transit duration
    in_transit_mask = np.abs(phase) <= 1.5 * transit_duration
    in_transit_flux = flux[in_transit_mask]

    # Step 2: Apply sigma clipping to remove outliers
    flux_clipped = sigma_clip(in_transit_flux, sigma=sigma_clip_thresh)

    # Step 3: Check if too many data points are removed by clipping
    if np.isnan(flux_clipped).all() or len(flux_clipped.compressed()) < 3:
        print(f"Sigma clipping removed too many points or resulted in NaN. Switching to fallback strategy: {fallback_strategy}")

        # Strategy 1: Use weighted median (ignores sigma clipping)
        if fallback_strategy == "weighted":
            weights = np.abs(np.nanmedian(in_transit_flux) - in_transit_flux)  # Weight points based on how far they are from the median
            try:
                depth_estimate = np.average(in_transit_flux, weights=weights)
            except ZeroDivisionError:
                depth_estimate = np.nanmean(in_transit_flux)
            depth_uncertainty = np.std(in_transit_flux)

        # Strategy 2: Skip sigma clipping altogether and use direct quantile
        elif fallback_strategy == "no_clip":
            depth_estimate = np.nanquantile(in_transit_flux, quantile)
            depth_uncertainty = np.std(in_transit_flux)

        # Strategy 3: Bootstrap resampling of the transit depth
        elif fallback_strategy == "bootstrap":
            bootstrapped_depths = []
            for i in range(1000):  # 1000 bootstrap samples
                sample = np.random.choice(in_transit_flux, size=len(in_transit_flux), replace=True)
                bootstrapped_depths.append(np.nanquantile(sample, quantile))
            depth_estimate = np.nanmedian(bootstrapped_depths)
            depth_uncertainty = np.std(bootstrapped_depths)

    else:
        # Step 4: Estimate depth based on the given quantile
        depth_estimate = np.nanquantile(flux_clipped.compressed(), quantile)

        # Step 5: Estimate uncertainty as the standard deviation of clipped flux
        depth_uncertainty = mad(flux_clipped.compressed())

    return 1 - depth_estimate, depth_uncertainty


# Sub-function to compare left/right transit data to the model
def compare_to_model(phase, flux, model_phase, model_flux, transit_results_df):
    #note transit_duration is in HOURS, if phase is also in hours this is fine
    # PHASE IS IN DAYS
    import astropy.units as u
    try:
        Period = transit_results_df['TLS Period [d]'].item()
        T0 = transit_results_df['TLS TC [BTJD]'].item()
        transit_duration = (transit_results_df['TLS Dur [hrs]'].item()*u.hour).value # in hours
        Depth = transit_results_df['TLS depth [ppt]'].item()/1e3 # in ppo
    except KeyError:
        Period = transit_results_df['BLS Period [d]'].item()
        T0 = transit_results_df['BLS TC [BTJD]'].item()
        transit_duration = (transit_results_df['BLS Dur [hrs]'].item()*u.hour).value # in hours
        Depth = transit_results_df['BLS depth [ppt]'].item()/1e3 # in ppo        
    RP = transit_results_df['Planet Radius [RE]'].item() # in Earth Radii
    R_star = transit_results_df['Stellar Radius [RS]'].item()
    M_star = transit_results_df['Stellar Mass [MS]'].item()    
    
    #do conversions
    transit_duration = (transit_duration * u.hour).to(u.day).value # in days
    Period = (Period * u.day).value
    #
    print('compare_to_model transit_duration (in days):',transit_duration)
    # Step 0:  calculate noise for later (duration std)
    in_transit_mask = (phase >= -1 * transit_duration) & (phase <= 1 * transit_duration)
    sigma_LC = np.nanstd(flux[in_transit_mask])
    #
    sigma_LC = np.nanstd(flux[in_transit_mask])
    cadence = np.nanmedian(np.diff(phase))  # in days
    N_intransit = len(flux[in_transit_mask])
    # Photon-noise timing uncertainty (continuous-signal limit)
    if Depth > 0:
        sigma_dur_photon = sigma_LC * cadence / Depth
    else:
        sigma_dur_photon = np.nan
    # Cadence-limited timing resolution: with N_intransit cadences spread
    # across all transit epochs, the minimum resolvable shift in the
    # half-max crossing position is ~ cadence / sqrt(N_intransit).
    if N_intransit > 0:
        sigma_dur_cadence = cadence / np.sqrt(N_intransit)
    else:
        sigma_dur_cadence = cadence
    # Take the larger of the two: photon noise dominates for shallow
    # transits with many cadences; cadence discretization dominates
    # for deep transits with few cadences.
    sigma_dur = max(sigma_dur_photon, sigma_dur_cadence)
    #
    #
    # Filter to +/- 3 transit durations for both the data and the model
    phase_filtered, flux_filtered = filter_phase_range(phase, flux, transit_duration)
    model_phase_filtered, model_flux_filtered = filter_phase_range(model_phase, model_flux, transit_duration)

    # Align flux and model arrays by phase
    # in case of large phase gaps
    if len(model_phase_filtered) == 0 or len(model_flux_filtered) == 0:
        model_phase_filtered, model_flux_filtered = model_phase, model_flux

    
    
    
    phase_filtered, flux_filtered, model_flux_filtered = align_arrays(phase_filtered, 
                                                                      flux_filtered, 
                                                                      model_phase_filtered,
                                                                      model_flux_filtered)

    # Split into left and right halves of the transit (around phase = 0)
    midpoint = np.argmin(np.abs(phase_filtered))
    left_phase, right_phase = phase_filtered[:midpoint], phase_filtered[midpoint:]
    left_flux, right_flux = flux_filtered[:midpoint], flux_filtered[midpoint:]
    left_model_flux, right_model_flux = model_flux_filtered[:midpoint], model_flux_filtered[midpoint:]

    # Align left and right halves based on phase
    left_phase, left_flux, left_model_flux  =   align_arrays(left_phase, 
                                                             left_flux,
                                                             left_phase, 
                                                             left_model_flux)
    right_phase, right_flux, right_model_flux = align_arrays(right_phase,
                                                             right_flux,
                                                             right_phase,
                                                             right_model_flux)

    #mirror left/right slices
    left_phases = np.append(left_phase,-left_phase[::-1])
    left_fluxes = np.append(left_flux,left_flux[::-1])

    right_phases = np.append(right_phase,-right_phase[::-1])
    right_fluxes = np.append(right_flux,right_flux[::-1])        

    q = 1e-3  
    depth_left, depth_left_std =  robust_transit_depth(left_phases,left_fluxes,
                                                         transit_duration, 
                                                         quantile=q,
                                                         sigma_clip_thresh=3.0)
    depth_right, depth_right_std =  robust_transit_depth(right_phases,right_fluxes, 
                                                         transit_duration, 
                                                         quantile=q,
                                                         sigma_clip_thresh=3.0)  
    depth, depth_std =  robust_transit_depth(phase,flux, 
                                             transit_duration, 
                                             quantile=q,
                                             sigma_clip_thresh=3.0)


    print('depth vs std:',depth,depth_std)
    print('depth check (L, R, o): ',depth_left,depth_right,depth,'\n')
    print('depth std check (L, R, o): ',depth_left_std,depth_right_std,depth_std,'\n')
    
    # 2. Calculate transit duration of left/right sides
    T1 = -T14(P=Period,R_planet=RP,R_star=R_star,M_star=M_star)
    T4 = +T14(P=Period,R_planet=RP,R_star=R_star,M_star=M_star)
    T2 = -T23(P=Period,R_planet=RP,R_star=R_star,M_star=M_star)
    T3 = +T23(P=Period,R_planet=RP,R_star=R_star,M_star=M_star)
    #        
    mirror_pf_L_at_T1,mirror_ff_L_at_T1 = get_flux_at_TN(left_phases,left_fluxes,T1,window=transit_duration)
    mirror_pf_L_at_T4,mirror_ff_L_at_T4 = get_flux_at_TN(left_phases,left_fluxes,T4,window=transit_duration)
    duration_left = np.nanmax(mirror_pf_L_at_T4) - np.nanmin(mirror_pf_L_at_T1)
    duration_left_std = sigma_dur * np.sqrt(N_intransit) / np.sqrt(len(left_phase)) 
    #
    mirror_pf_R_at_T1,mirror_ff_R_at_T1 = get_flux_at_TN(right_phases,right_fluxes,T1,window=transit_duration)
    mirror_pf_R_at_T4,mirror_ff_R_at_T4 = get_flux_at_TN(right_phases,right_fluxes,T4,window=transit_duration)
    duration_right = np.nanmax(mirror_pf_R_at_T4) - np.nanmin(mirror_pf_R_at_T1)
    duration_right_std = sigma_dur * np.sqrt(N_intransit) / np.sqrt(len(right_phase)) 
    #
    phase_at_T1,flux_at_T1 = get_flux_at_TN(phase,flux,T1,window=transit_duration)
    phase_at_T4,flux_at_T4 = get_flux_at_TN(phase,flux,T4,window=transit_duration)
    duration = np.nanmax(phase_at_T4) - np.nanmin(phase_at_T1)        
    duration_std = sigma_dur

    # 3. Calculate depth/duration
    symmetry_depth_metric = np.abs( (depth_left  - depth_right)) 

    print('duration check (L, R, O): ',duration_left,duration_right,duration,'\n')
    print('duration std (L,R,O): ',duration_left_std,duration_right_std,duration_std,'\n')
    print('dur vs std:',duration,duration_std)

    symmetry_duration_metric = np.abs( (duration_left  - duration_right)) 
    print('symmetry_duration_metric:',symmetry_duration_metric)
    depth_over_duration = depth / duration        
    symmetry_depth_duration_metric= (symmetry_depth_metric / symmetry_duration_metric) / depth_over_duration        
    # Fractional Transit Duration
    def q_tran(duration,period):
        #make sure they're both in units of days
        duration = (duration * u.day).value
        period = (period * u.day).value
        return duration / period

    q_transit = q_tran(duration,Period)
    q_transit_L = q_tran(duration_left,Period)
    q_transit_R = q_tran(duration_right,Period)

    symmetry_qtran_metric= np.abs(q_transit_L - q_transit_R) / q_transit

    # Return the metrics
    metrics = {
        'Depth': depth,
        'Depth std': depth_std,
        'Depth Left': depth_left,
        'Depth Left std': depth_left_std,
        'Depth Right': depth_right,
        'Depth Right std': depth_right_std,
        'Duration':duration,
        'Duration std':duration_std,
        'Duration Left': duration_left,
        'Duration Left std': duration_left_std,
        'Duration Right': duration_right,
        'Duration Right std': duration_right_std,
        'Symmetry Depth Metric': symmetry_depth_metric,
        'Symmetry Duration Metric': symmetry_duration_metric,
        'Symmetry Depth Over Duration Metric':symmetry_depth_duration_metric,
        'q transit':q_transit,
        'q transit Left':q_transit_L,
        'q transit Right':q_transit_R,
        'symmetry_qtran_metric':symmetry_qtran_metric}
    return metrics, left_phases,left_fluxes , right_phases,right_fluxes
