#
#
def check_transit_symmetry(
    metrics,
    snr=None,
    n_sigma_depth: float = 3.0,
    n_sigma_qtran: float = 5.0,
) -> tuple:
    """
    Assess left/right transit symmetry using uncertainty-normalised
    (SNR-on-the-asymmetry) tests for both transit depth and fractional
    transit duration (q_tran).

    Both tests normalise the absolute left-minus-right difference by the
    combined measurement uncertainty (quadrature sum), producing a
    dimensionless significance.  A TCE is failed if *either* significance
    exceeds its n-sigma threshold.

    Depth test
    ----------
    depth_SNR = |depth_L - depth_R| / sqrt(sigma_dL^2 + sigma_dR^2)
    Fail if depth_SNR > n_sigma_depth.

    qtran test
    ----------
    sigma_qL  = duration_left_std  / Period
    sigma_qR  = duration_right_std / Period
    qtran_SNR = |q_L - q_R| / sqrt(sigma_qL^2 + sigma_qR^2)
    Fail if qtran_SNR > n_sigma_qtran.

    Side effects
    -------------
    The following keys are **written into** the mutable ``metrics`` dict so
    that downstream code (vetting report text, CSV columns) can reference
    them without changing return signatures:

        'Symmetry Depth SNR'        -- depth significance (float)
        'Symmetry qtran SNR'        -- qtran significance (float)
        'Symmetry Depth threshold'  -- n_sigma_depth     (float)
        'Symmetry qtran threshold'  -- n_sigma_qtran     (float)

    Parameters
    ----------
    metrics : dict or single-row pd.DataFrame
        Output of ``compare_to_model``.  Required keys:
            'Depth Left', 'Depth Left std',
            'Depth Right', 'Depth Right std',
            'Duration Left std', 'Duration Right std',
            'q transit', 'q transit Left', 'q transit Right',
            'Duration',
            'Symmetry Depth Metric', 'symmetry_qtran_metric'.
    snr : float, optional
        Unused; retained for API compatibility.
    n_sigma_depth : float, optional
        Significance threshold for the depth asymmetry test.  Default 3.0.
    n_sigma_qtran : float, optional
        Significance threshold for the qtran asymmetry test.  Default 3.0.

    Returns
    -------
    pass_fail : str
        ``'passed'`` or ``'failed'``.
    operation1 : str
        Comparison operator string for the depth test
        (``'<='`` if passed, ``'>'`` if failed).
    operation2 : str
        Comparison operator string for the qtran test
        (``'<'`` if passed, ``'>='`` if failed).
    depth_threshold : float
        ``n_sigma_depth`` (in sigma units).
    qtran_threshold : float
        ``n_sigma_qtran`` (in sigma units).

    Notes
    -----
    * If either combined uncertainty is zero or NaN, the corresponding
      test returns NaN and does not contribute to the pass/fail decision
      (conservative: NaN is treated as passed).
    * ``operation1``/``operation2`` are retained as string operators so
      that ``plot_page3_text`` and related report formatting code works
      without modification.

    Example
    -------
    >>> pf, op1, op2, dthr, qthr = check_transit_symmetry(metrics)
    >>> print(f"Depth asym: {metrics['Symmetry Depth SNR']:.2f} sigma {op1} {dthr}")
    >>> print(f"qtran asym: {metrics['Symmetry qtran SNR']:.2f} sigma {op2} {qthr}")
    """
    import numpy as np

    # ------------------------------------------------------------------ #
    # Helper: extract a Python float from dict value, Series, or array
    # ------------------------------------------------------------------ #
    def _scalar(v):
        try:
            return float(v.item())
        except AttributeError:
            return float(v)

    # ------------------------------------------------------------------ #
    # 1.  Pull values from metrics
    # ------------------------------------------------------------------ #
    depth_L    = _scalar(metrics['Depth Left'])
    sigma_dL   = _scalar(metrics['Depth Left std'])
    depth_R    = _scalar(metrics['Depth Right'])
    sigma_dR   = _scalar(metrics['Depth Right std'])

    q_L        = _scalar(metrics['q transit Left'])
    q_R        = _scalar(metrics['q transit Right'])

    dur_L_std  = _scalar(metrics['Duration Left std'])
    dur_R_std  = _scalar(metrics['Duration Right std'])

    # Recover Period from q_transit and Duration (both in days).
    # q_transit = duration / Period  =>  Period = duration / q_transit
    q_full     = _scalar(metrics['q transit'])
    dur_full   = _scalar(metrics['Duration'])
    Period     = (dur_full / q_full) if (q_full > 0) else np.nan

    # ------------------------------------------------------------------ #
    # 2.  Propagate duration uncertainties -> q uncertainties
    #     sigma_q = sigma_dur / Period   (Period treated as exact)
    # ------------------------------------------------------------------ #
    if np.isfinite(Period) and Period > 0:
        sigma_qL = dur_L_std / Period
        sigma_qR = dur_R_std / Period
    else:
        sigma_qL = np.nan
        sigma_qR = np.nan

    # ------------------------------------------------------------------ #
    # 3.  SNR-on-the-asymmetry: depth
    # ------------------------------------------------------------------ #
    combined_sigma_depth = np.sqrt(sigma_dL**2 + sigma_dR**2)
    if combined_sigma_depth > 0 and np.isfinite(combined_sigma_depth):
        depth_SNR = np.abs(depth_L - depth_R) / combined_sigma_depth
    else:
        depth_SNR = np.nan

    # ------------------------------------------------------------------ #
    # 4.  SNR-on-the-asymmetry: qtran
    # ------------------------------------------------------------------ #
    combined_sigma_qtran = np.sqrt(sigma_qL**2 + sigma_qR**2)
    if combined_sigma_qtran > 0 and np.isfinite(combined_sigma_qtran):
        qtran_SNR = np.abs(q_L - q_R) / combined_sigma_qtran
    else:
        qtran_SNR = np.nan

    # ------------------------------------------------------------------ #
    # 5.  Write SNR values into metrics dict for downstream consumers
    # ------------------------------------------------------------------ #
    metrics['Symmetry Depth SNR']       = depth_SNR
    metrics['Symmetry qtran SNR']       = qtran_SNR
    metrics['Symmetry Depth threshold'] = float(n_sigma_depth)
    metrics['Symmetry qtran threshold'] = float(n_sigma_qtran)

    # ------------------------------------------------------------------ #
    # 6.  Pass / fail + operator strings (preserves old API contract)
    #     NaN -> treated as passed (conservative)
    # ------------------------------------------------------------------ #
    depth_failed = np.isfinite(depth_SNR) and (depth_SNR > n_sigma_depth)
    qtran_failed = np.isfinite(qtran_SNR) and (qtran_SNR > n_sigma_qtran)

    # Depth operator
    if depth_failed:
        operation1 = '>'
    else:
        operation1 = '<='

    # qtran operator
    if qtran_failed:
        operation2 = '>='
    else:
        operation2 = '<'

    # Combined verdict
    pass_fail = 'failed' if (depth_failed or qtran_failed) else 'passed'

    # ------------------------------------------------------------------ #
    # 7.  Verbose diagnostics (replaces old per-branch prints)
    # ------------------------------------------------------------------ #
    print(
        f"Symmetry Depth SNR: {depth_SNR:.4f}  {operation1}  "
        f"threshold: {n_sigma_depth:.1f} sigma, "
        f"{'failed' if depth_failed else 'passed'}"
    )
    print(
        f"Symmetry qtran SNR: {qtran_SNR:.4f}  {operation2}  "
        f"threshold: {n_sigma_qtran:.1f} sigma, "
        f"{'failed' if qtran_failed else 'passed'}"
    )
    print(f" \npass_fail: {pass_fail}\n")

    # ------------------------------------------------------------------ #
    # 8.  Return -- same 5-tuple signature as before
    # ------------------------------------------------------------------ #
    return pass_fail, operation1, operation2, float(n_sigma_depth), float(n_sigma_qtran)


# HELPER FUNCTIONS FOR mirror_and_model_left_right_transit
def symmetry_window_is_degenerate(
    phase: np.ndarray,
    flux: np.ndarray,
    model_phase: np.ndarray,
    model_flux: np.ndarray,
    transit_duration: float,
    cadence: float,
    n_cad_min: float = 0.0,
    verbose: bool = False,
) -> tuple[bool, str]:
    """
    Decide whether the left/right mirror symmetry test can run at all.

    Reproduces, without side effects, the exact window geometry that
    ``compare_to_model`` builds internally, and reports whether that geometry
    is degenerate. It exists because ``compare_to_model`` calls ``align_arrays``
    a second time with ``left_phase`` passed as BOTH the data phase and the
    model phase; when the point nearest phase zero is the first point in the
    window, ``left_phase`` is empty and ``align_arrays`` raises
    ``ValueError("Input arrays 'phase_model' and 'model_flux' must not be
    empty.")``. That exception propagates out of Vetting_Report_4th_page and
    kills pages 4, 5 and 6, so the bestfit CSV never receives
    ``centroid_motion_score`` or any ``LEOVetter_*`` column.

    Geometry reproduced, in order:
      1. window mask   ``|phase| <= 3 * transit_duration``   (filter_phase_range)
      2. finite mask   ``isfinite(phase) & isfinite(flux)``  (align_arrays)
      3. ``midpoint = argmin(|phase_window|)``               (compare_to_model)
      4. left half is ``phase_window[:midpoint]``; empty iff ``midpoint == 0``

    Default behaviour is deliberately minimal: the function returns True only
    for configurations that currently raise. Every input that currently yields
    a symmetry number still yields the identical number, so the completed blind
    catalog is not invalidated. ``n_cad_min > 0`` opts into the stricter
    sampling criterion described below and WILL change values for rows that
    currently succeed.

    Parameters
    ----------
    phase : np.ndarray
        Phase-folded time array of the data, in days, as produced by
        ``phasefold(T0, T, Period, F)``.
    flux : np.ndarray
        Phase-folded flux array matching ``phase``.
    model_phase : np.ndarray
        Phase-folded time array of the transit model, in days.
    model_flux : np.ndarray
        Phase-folded model flux matching ``model_phase``.
    transit_duration : float
        Fitted T14 in DAYS. ``mirror_and_model_left_right_transit`` has already
        converted from hours by this point; passing hours will silently widen
        the window by 24x.
    cadence : float
        Median sampling interval in days, ``np.nanmedian(np.diff(T))``.
        Used only when ``n_cad_min > 0``.
    n_cad_min : float, optional
        Minimum number of cadences the fitted duration must span for the test
        to be attempted. 0.0 (default) disables this criterion, restricting the
        guard to configurations that currently crash. 2.0 is the Nyquist
        argument: a transit sampled once has no resolved ingress or egress, so
        a left-versus-right shape comparison is undefined regardless of whether
        the arithmetic happens to complete.
    verbose : bool, optional
        Print the accepted window geometry. Default False.

    Returns
    -------
    is_degenerate : bool
        True if the caller must skip ``compare_to_model``.
    reason : str
        Human-readable cause, empty string when ``is_degenerate`` is False.
        Intended for the log line the caller emits.

    Example usage
    -------------
    >>> bad, why = symmetry_window_is_degenerate(
    ...     phase=phase, flux=flux,
    ...     model_phase=model_phase, model_flux=model_flux,
    ...     transit_duration=0.0139,   # 20 minutes, in days
    ...     cadence=0.0208,            # 30 minutes, in days
    ...     n_cad_min=0.0, verbose=False)
    >>> bad
    True
    """
    phase = np.asarray(phase, dtype=np.float64)
    flux = np.asarray(flux, dtype=np.float64)
    model_phase = np.asarray(model_phase, dtype=np.float64)
    model_flux = np.asarray(model_flux, dtype=np.float64)

    if not np.isfinite(transit_duration) or transit_duration <= 0.0:
        return True, f"non-physical transit_duration = {transit_duration!r} d"

    # Optional sampling criterion. Off by default.
    if n_cad_min > 0.0 and np.isfinite(cadence) and cadence > 0.0:
        if transit_duration < n_cad_min * cadence:
            return True, (
                f"T14 = {transit_duration * 24.0:.4f} h is below "
                f"{n_cad_min:g} x cadence = {n_cad_min * cadence * 24.0:.4f} h; "
                f"transit is unresolved"
            )

    # --- data side: filter_phase_range, then align_arrays' finite mask -------
    keep = (np.abs(phase) <= 3.0 * transit_duration) & \
           np.isfinite(phase) & np.isfinite(flux)
    n_keep = int(np.count_nonzero(keep))
    if n_keep == 0:
        return True, (
            f"no finite data points inside the +/-3 T14 window "
            f"(T14 = {transit_duration * 24.0:.4f} h)"
        )

    phase_win = phase[keep]
    midpoint = int(np.argmin(np.abs(phase_win)))

    if midpoint == 0:
        return True, (
            f"left half is empty: argmin(|phase|) = 0 with {n_keep} point(s) "
            f"in the +/-3 T14 window (T14 = {transit_duration * 24.0:.4f} h)"
        )
    if n_keep - midpoint < 1:
        # Unreachable by construction (argmin <= n_keep - 1); explicit backstop.
        return True, f"right half is empty with {n_keep} point(s) in the window"

    # --- model side: replicate compare_to_model's fallback --------------------
    m_finite = np.isfinite(model_phase) & np.isfinite(model_flux)
    m_window = (np.abs(model_phase) <= 3.0 * transit_duration) & m_finite
    if int(np.count_nonzero(m_window)) == 0 and int(np.count_nonzero(m_finite)) == 0:
        return True, "model arrays contain no finite samples"

    if verbose:
        print(
            f"[symmetry] window OK: {n_keep} pts, midpoint = {midpoint}, "
            f"T14 = {transit_duration * 24.0:.4f} h, "
            f"cadence = {cadence * 24.0 * 60.0:.2f} min"
        )
    return False, ""

def nan_symmetry_result() -> tuple:
    """
    Return a NaN-filled result with the exact 16-element shape that
    ``mirror_and_model_left_right_transit`` returns on success.

    Element order, matching the unpacking in ``in_versus_out_of_transit_test``:

        0  symmetry_depth_metric   float   NaN
        1  symmetry_qtran_metric   float   NaN
        2  symmetry_flag           str     'indeterminate'
        3  operation1              str     'n/a'
        4  operation2              str     'n/a'
        5  mirror_left             list    [empty float array, empty float array]
        6  mirror_right            list    [empty float array, empty float array]
        7  orig_mirror_left        list    [empty float array, empty float array]
        8  orig_mirror_right       list    [empty float array, empty float array]
        9  depth                   float   NaN
       10  depthL                  float   NaN
       11  depthR                  float   NaN
       12  depth_threshold         float   NaN
       13  qtran_threshold         float   NaN
       14  depth_SNR               float   NaN
       15  qtran_SNR               float   NaN

    Why 'indeterminate' rather than 'failed'. ``nemesis_catalog_rule.
    add_symmetry_flag`` lower-cases ``symmetry_col`` and treats anything outside
    {'passed', 'failed'} as indeterminate and NON-FLAGGING, additionally writing
    ``symmetry_indeterminate``. So this sentinel is already a supported value:
    it does not fire the flag, it is counted separately, and it matches
    ``check_transit_symmetry``'s own NaN-is-passed convention. With
    ``USE_SYMMETRY_GATE = False`` the flag is written as ``prop_flag_symmetry``
    and gates nothing, so no TCE/PC/FA/FP label changes.

    Why the thresholds are NaN rather than 3.0 and 5.0. Those live in
    ``check_transit_symmetry``'s signature defaults. Hardcoding a second copy
    here is the call-site-copy failure mode that produces a recorded threshold
    which differs from the applied one. NaN in ``symmetry_depth_threshold``
    is therefore the marker that the test did not run.

    Returns
    -------
    tuple
        16 elements, as above.

    Example usage
    -------------
    >>> res = nan_symmetry_result()
    >>> len(res), res[2], res[5][0].size
    (16, 'indeterminate', 0)
    """
    empty = lambda: [np.array([], dtype=np.float64),
                     np.array([], dtype=np.float64)]
    return (
        np.nan,             # symmetry_depth_metric
        np.nan,             # symmetry_qtran_metric
        'indeterminate',    # symmetry_flag
        'n/a',              # operation1
        'n/a',              # operation2
        empty(),            # mirror_left
        empty(),            # mirror_right
        empty(),            # orig_mirror_left
        empty(),            # orig_mirror_right
        np.nan,             # depth
        np.nan,             # depthL
        np.nan,             # depthR
        np.nan,             # depth_threshold
        np.nan,             # qtran_threshold
        np.nan,             # depth_SNR
        np.nan,             # qtran_SNR
    )

def nan_vetting_columns(transit_results_df) -> dict:
    """
    NaN-filled replacement for the vetting-metric column block that
    ``in_versus_out_of_transit_test`` normally appends to the bestfit frame.

    Used by ``Vetting_Report_4th_page`` when the vetting computation raises,
    so the page can still write a schema-complete bestfit CSV. A row with the
    columns present and NaN is a searched non-detection; a row with the columns
    ABSENT is invisible to nemesis_catalog_rule and cannot become a TCE, which
    is the failure mode this exists to prevent.

    ``a_over_R_star`` and ``q_transit`` are read from ``transit_results_df``
    rather than NaN-filled, because they are written by BLS_func / TLS_func and
    are unaffected by any vetting failure. Their flags are recomputed with the
    same rules ``in_versus_out_of_transit_test`` uses, so the values agree with
    the normal path.

    Parameters
    ----------
    transit_results_df : pd.DataFrame
        Single-row best-fit frame from ``TransitSearch``.

    Returns
    -------
    dict
        Column name -> value, matching the vet_df schema exactly.

    Example usage
    -------------
    >>> cols = nan_vetting_columns(transit_results_df)
    >>> sorted(cols)[:3]
    ['CDPP_flag', 'CDPP_in_transit', 'CDPP_out_of_transit']
    """
    try:
        q_transit = float(transit_results_df['q_transit'].item())
    except Exception:
        q_transit = np.nan
    try:
        a_over_R_star = float(transit_results_df['a_over_R_star'].item())
    except Exception:
        a_over_R_star = np.nan

    q_flag = ('failed' if (np.isnan(q_transit) or not (0.001 < q_transit < 0.1))
              else 'passed')
    a_flag = ('failed' if (np.isnan(a_over_R_star) or a_over_R_star < 1.5)
              else 'passed')

    return {
        'odd_even_mismatch':        np.nan,
        'odd_even_mismatch_flag':   'indeterminate',
        'SNR':                      np.nan,
        'SNR_flag':                 'indeterminate',
        'symmetry_depth_metric':    np.nan,
        'symmetry_depth_threshold': np.nan,
        'symmetry_depth_SNR':       np.nan,
        'symmetry_qtran_metric':    np.nan,
        'symmetry_qtran_threshold': np.nan,
        'symmetry_qtran_SNR':       np.nan,
        'symmetry_flag':            'indeterminate',
        'CDPP_in_transit':          np.nan,
        'CDPP_out_of_transit':      np.nan,
        'CDPP_ratio':               np.nan,
        'CDPP_flag':                'indeterminate',
        'a_over_R_star':            a_over_R_star,
        'a_over_R_star_flag':       a_flag,
        'q_transit':                q_transit,
        'q_transit_flag':           q_flag,
    }

def mirror_and_model_left_right_transit(ID,Sector,input_LC, 
                                        transit_results_df,BLSorTLSmodel_df,
                                        verbose):
    """
    Performs a comprehensive symmetry analysis for a transit event by comparing
    the left and right mirrored transits to the model and computing various metrics
    such as RMSE, residuals, and chi-squared values. Also generates a plot to 
    visualize the result.
    
    Parameters:
    ----------
    LC_df : pandas.DataFrame
        Light curve dataframe containing 'Time' and 'Detrended Flux'.
    model : pandas.DataFrame
        Transit model dataframe containing 'Time' and 'Model'.
    transit_results_df: pandas.DataFrame
    
    Returns:
    -------
    tuple
        16 elements: (symmetry_depth_metric, symmetry_qtran_metric,
        symmetry_flag, operation1, operation2, mirror_left, mirror_right,
        orig_mirror_left, orig_mirror_right, depth, depthL, depthR,
        depth_threshold, qtran_threshold, depth_SNR, qtran_SNR).

        Any exception returns nan_symmetry_result(): NaN metrics,
        symmetry_flag = 'indeterminate', empty mirror arrays. The symmetry
        verdict is non-gating (USE_SYMMETRY_GATE = False), so degrading it to
        NaN is always preferable to propagating, which would kill pages 5 and
        6 and strip centroid_motion_score and every LEOVetter_* column from
        the bestfit CSV.

        Two failures observed: align_arrays raising on an empty left half
        (caught by symmetry_window_is_degenerate above), and the transit
        contact-point finder raising "No points found within expanded window"
        past its 12-hour ceiling (TIC 341856365 S4).
    """
    try:
        from scipy.stats import median_abs_deviation
        import astropy.units as u
        LC_df = input_LC
        T = LC_df['Time'].to_numpy(dtype=np.float64)
        F = LC_df['Flux'].to_numpy(dtype=np.float64) #modified from NEMESIS
        E = LC_df['Error'].to_numpy(dtype=np.float64) #modified from NEMESIS
        #
        # Remove non-finite values consistently
        valid = np.isfinite(T) & np.isfinite(F) & np.isfinite(E)
        T = T[valid]
        F = F[valid]
        E = E[valid]
        #
        #
        model = BLSorTLSmodel_df #rename for later
        #
        try:
            Period = transit_results_df['TLS Period [d]'].item()
            T0 = transit_results_df['TLS TC [BTJD]'].item()
            transit_duration = (transit_results_df['TLS Dur [hrs]'].item()*u.hour).value # in hours
            Depth = transit_results_df['TLS depth [ppt]'].item()/1e3 # in ppo
        except KeyError:
            Period = transit_results_df['BLS Period [d]'].item()
            T0 = transit_results_df['BLS TC [BTJD]'].item()
            transit_duration = (transit_results_df['BLS Dur [hrs]'].item()*u.hour).value # in hours
            Depth = transit_results_df['BLS depth [ppt]'].item()/1e3 # in ppo        
        R_planet = transit_results_df['Planet Radius [RE]'].item() # in Earth Radii
        R_star = transit_results_df['Stellar Radius [RS]'].item()
        M_star = transit_results_df['Stellar Mass [MS]'].item()    

        #do conversions
        import astropy.units as u
        transit_duration = (transit_duration * u.hour).to(u.day).value # in days
        Period = (Period * u.day).value

        # Phase-fold the light curve
        orig_phase, orig_flux = phasefold(T0, T, Period, F)
        phase,flux = orig_phase, orig_flux #renaming for later

        orig_model_phase, orig_model_flux = phasefold(T0, model['Time'].to_numpy(dtype=np.float64),
                                                      Period, model['Model'].to_numpy(dtype=np.float64))
        model_phase,model_flux = orig_model_phase, orig_model_flux #renaming for later

        # Calculate cadence
        cadence = np.nanmedian(np.diff(T))  # in days
        #
        # ---- degenerate-window guard -------------------------------------------
        # compare_to_model raises ValueError when the +/-3 T14 window has no left
        # half. That kills pages 4, 5 and 6 and strips centroid_motion_score and
        # every LEOVetter_* column from the bestfit CSV. Skip the test instead.
        _degenerate, _reason = symmetry_window_is_degenerate(
            phase=phase, flux=flux,
            model_phase=model_phase, model_flux=model_flux,
            transit_duration=transit_duration,
            cadence=cadence,
            n_cad_min=0.0,
            verbose=verbose,
        )
        if _degenerate:
            print(f"[symmetry] TIC {ID} Sector {Sector}: symmetry test SKIPPED "
                  f"({_reason}). Metrics set to NaN; vetting continues.")
            return nan_symmetry_result()
        # -------------------------------------------------------------------------
        #
        # Execute the main function logic
        metrics, left_phases,left_fluxes , right_phases,right_fluxes = compare_to_model(phase, flux, 
                                                                                        model_phase, model_flux,
                                                                                        transit_results_df)
        symmetry_flag, operation1, operation2, depth_threshold, qtran_threshold = check_transit_symmetry(metrics, snr=None)
        # check_transit_symmetry now mutates metrics to add:
        #   'Symmetry Depth SNR', 'Symmetry qtran SNR',
        #   'Symmetry Depth threshold', 'Symmetry qtran threshold'
        symmetry_depth_metric = metrics['Symmetry Depth Metric'].item()
        symmetry_duration_metric = metrics['Symmetry Duration Metric'].item()
        symmetry_qtran_metric = metrics['symmetry_qtran_metric'].item()
        # Extract the new SNR values (written by check_transit_symmetry)
        depth_SNR = metrics.get('Symmetry Depth SNR', np.nan)
        qtran_SNR = metrics.get('Symmetry qtran SNR', np.nan)
        #pack left,right mirrors for later plotting
        orig_mirror_left = [left_phases,left_fluxes]
        orig_mirror_right = [right_phases,right_fluxes]

        # show binned mirrored data (since it's use for measuring symmetry?)
        def bin_ff(pf,ff,duration):
            bins = np.linspace(-4*duration, 4*duration, int(len(pf)/100))
            denom, _ = np.histogram(pf, bins)
            num, _ = np.histogram(pf, bins, weights=ff)
            denom[num == 0] = 1.0
            return (0.5*(bins[1:] + bins[:-1])), num / denom    

        bin_left_phases, bin_left_fluxes = bin_ff(left_phases,left_fluxes,transit_duration)
        bin_right_phases, bin_right_fluxes = bin_ff(right_phases,right_fluxes,transit_duration)
        mirror_left = [bin_left_phases, bin_left_fluxes]
        mirror_right = [bin_right_phases, bin_right_fluxes]

        depth = metrics['Depth'].item()
        depthL = metrics['Depth Left'].item()
        depthR = metrics['Depth Right'].item()

        return (symmetry_depth_metric, symmetry_qtran_metric, symmetry_flag,
                operation1, operation2,
                mirror_left, mirror_right,
                orig_mirror_left, orig_mirror_right,
                depth, depthL, depthR,
                depth_threshold, qtran_threshold,
                depth_SNR, qtran_SNR)
    except Exception as exc:
        print(f"[symmetry] TIC {ID} Sector {Sector}: symmetry test FAILED "
              f"({type(exc).__name__}: {exc}). Metrics set to NaN; "
              f"vetting continues to pages 5 and 6.", flush=True)
        return nan_symmetry_result()
#
#
#
def in_versus_out_of_transit_test(ID,Sector,LC_df,transit_results_df,BLSorTLSmodel_df,verbose):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    from transitleastsquares import transit_mask
    import pandas as pd
    import astropy.units as u
    #grab odd/even mismatch from TLS
    try:
        O_E_mismatch = transit_results_df['TLS Odd Even Mismatch'].item() # in standard deviations
        Period = transit_results_df['TLS Period [d]'].item()
        T0 = transit_results_df['TLS TC [BTJD]'].item()
        duration = (transit_results_df['TLS Dur [hrs]'].item()*u.hour).to(u.day).value # in days
        N_transits = transit_results_df['TLS Distinct Transit Count'].item()
        Depth = transit_results_df['TLS depth [ppt]'].item()/1e3        
    except KeyError:
        O_E_mismatch = transit_results_df['BLS Odd Even Mismatch'].item() # in standard deviations
        Period = transit_results_df['BLS Period [d]'].item()
        T0 = transit_results_df['BLS TC [BTJD]'].item()
        duration = (transit_results_df['BLS Dur [hrs]'].item()*u.hour).to(u.day).value # in days
        N_transits = transit_results_df['BLS Distinct Transit Count'].item()
        Depth = transit_results_df['BLS depth [ppt]'].item()/1e3        
        
    if np.isnan(O_E_mismatch) or O_E_mismatch >= 5:
        O_E_mismatch_flag = 'failed'
    else:
        O_E_mismatch_flag = 'passed'
    ####
    ####
    #mask transit to calc cdpp_out_of_transit
    T = LC_df['Time'].to_numpy(dtype=np.float64)
    F = LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    E = LC_df['Detrended Error'].to_numpy(dtype=np.float64)
    #
    intransit = transit_mask(T, Period, 2 * duration, T0)
    maskedT = T[~intransit]
    maskedF = F[~intransit]
    maskedE = E[~intransit]
    #
    # compare noise in transit versus out of transit
    timescale=1.0/24.0
    cad = np.nanmedian(np.diff(T[np.isfinite(T)]))
    CDPP_LC = CDPP(T,F,E,'median','ppm',cad,binsize=timescale) # in ppo per sqrt timescale
    CDPP_in_transit = CDPP(T[intransit],F[intransit],E[intransit],\
                           'median','ppm',cad,binsize=timescale) # in ppo per sqrt timescale
    CDPP_out_of_transit = CDPP(T[~intransit],F[~intransit],E[~intransit],\
                               'median','ppm',cad,binsize=timescale) # in ppo per sqrt timescale
    CDPP_ratio = np.abs(CDPP_in_transit - CDPP_out_of_transit)/CDPP_LC # scaled to CDPP of LC on timescale
    if CDPP_ratio < 1/100: #1%
        CDPP_flag='failed'
    else:
        CDPP_flag='passed'
    #
    SNR = np.sqrt(N_transits)*Depth / CDPP(T[~intransit],F[~intransit],E[~intransit],'median','ppo',cad,binsize=timescale)
    #
    if np.isnan(SNR) or SNR < 7:
        SNR_flag = 'failed'
    else:
        SNR_flag = 'passed'
    ####
    ####
    # point to point in/out transit metric 
    pf,ff = phasefold(T0,T,Period,F)
    m = np.abs(pf*24) < 5*duration*24
    maskedpf,maskedff = phasefold(T0,maskedT,Period,maskedF)
    #
    numerator=[]
    for i in range(len(pf[m])-1):
        numerator=np.append(numerator, ff[m][i] - ff[m][i-1])
    denominator=[]
    for j in range(len(maskedpf)-1):
        denominator=np.append(denominator, maskedff[j] - maskedff[j-1])
    num_sum = np.sum(np.array(numerator)**2)
    denom_sum = np.sum(np.array(denominator)**2)
    #
    #
    P2P_in_out = np.sqrt(num_sum / denom_sum)
    #
    import pandas as pd
    input_LC = pd.DataFrame({'Time':T,'Flux':F,'Error':E})
    mirror_tests = mirror_and_model_left_right_transit(ID,Sector,input_LC, 
                                                       transit_results_df,BLSorTLSmodel_df,
                                                       verbose)
    (symmetry_depth_metric, symmetry_qtran_metric, symmetry_flag,
     operation1, operation2,
     mirror_left, mirror_right,
     orig_mirror_left, orig_mirror_right,
     depth, depthL, depthR,
     depth_threshold, qtran_threshold,
     depth_SNR, qtran_SNR) = mirror_tests
    #
    # 
    q_transit = transit_results_df['q_transit'].item()
    if np.isnan(q_transit) or not (0.001 < q_transit < 0.1):
        q_transit_flag = 'failed'
    else:
        q_transit_flag = 'passed'
        
    a_over_R_star = transit_results_df['a_over_R_star'].item()
    #
    if np.isnan(a_over_R_star) or a_over_R_star < 1.5:
        a_over_R_star_flag = 'failed'
    else:
        a_over_R_star_flag = 'passed'
        
    vet_df = pd.DataFrame({
        'odd_even_mismatch': O_E_mismatch,
        'odd_even_mismatch_flag': O_E_mismatch_flag,
        'SNR': SNR,
        'SNR_flag': SNR_flag,
        'symmetry_depth_metric': symmetry_depth_metric,
        'symmetry_depth_threshold': depth_threshold,
        'symmetry_depth_SNR': depth_SNR,           # <-- NEW
        'symmetry_qtran_metric': symmetry_qtran_metric,
        'symmetry_qtran_threshold': qtran_threshold,
        'symmetry_qtran_SNR': qtran_SNR,            # <-- NEW
        'symmetry_flag': symmetry_flag,
        'CDPP_in_transit': CDPP_in_transit,
        'CDPP_out_of_transit': CDPP_out_of_transit,
        'CDPP_ratio': CDPP_ratio,
        'CDPP_flag': CDPP_flag,
        'a_over_R_star': a_over_R_star,
        'a_over_R_star_flag': a_over_R_star_flag,
        'q_transit': q_transit,
        'q_transit_flag': q_transit_flag
    }, index=[0])

    #
    # append vet_df to transit results ("_bestfit.csv")
    for v in range(len(vet_df.columns)):
        transit_results_df[vet_df.columns[v]] = vet_df[vet_df.columns[v]]
    appended_transit_results = transit_results_df
    #
    return vet_df, mirror_left,mirror_right, orig_mirror_left,orig_mirror_right, appended_transit_results
#
#
#
def centroid_analysis(
    ID,
    Sector,
    hdu,
    LC_df,
    transit_results_df,
    ax1,
    ax2,
    ax3,
    ax4,
    verbose: bool = False,
):
    """
    Compute a centroid motion diagnostic for a NEMESIS TCE and render
    it on the Page-4 vetting report axes.

    Only one pass/fail test is applied: the in-transit mean-shift z-score.
    The previous global scatter gate (counting cadences exceeding 5*sigma
    of the full-sector centroid series) has been removed.  That gate is not
    independent of the in-transit test and cannot distinguish genuine
    off-target motion from the coherent in-transit centroid suppression
    that aperture photometry routinely produces during real transits (PSF
    core occulted by planet -> photocenter pulled toward aperture edge).
    For a target with many transits at 30-min cadence, that artifact alone
    generates 5-sigma excursions in the bulk-scatter sense while the
    in-transit mean shift remains negligible.

    The 1-, 3-, and 5-sigma circles on ax1 are retained as visual reference
    for the human reviewer; they are not used for pass/fail gating.

    In-transit mean-shift test
    --------------------------
    Cadences within 3 * T14 of T0 (phase-folded) are classified as
    in-transit; all others are OOT.  The standardized mean-shift score for
    each pixel axis is:

        z_a = |mean(a_in) - mean(a_out)| / (std(a_out) / sqrt(N_in))

    where a is the median-subtracted centroid displacement in that axis.
    The reported centroid_motion_score = mean(z_x, z_y).

    Threshold: score >= 3 -> pval_flag = 'failed'.
    If N_in == 0 or std_out == 0 for both axes -> pval_flag = 'indeterminate'.

    Parameters
    ----------
    ID : int
        TIC identifier.
    Sector : int or list
        Sector(s) being processed.
    hdu : astropy HDUList
        TESS FFI cutout HDU (not modified; kept for API compatibility).
    LC_df : pd.DataFrame
        Processed light curve.  Required columns:
            'Time', 'Centroid X Positions', 'Centroid Y Positions',
            'Detrended Flux'.
    transit_results_df : pd.DataFrame
        Best-fit TCE parameters.  Tries TLS keys first, falls back to BLS.
    ax1 : matplotlib.axes.Axes
        Delta-X vs Delta-Y scatter panel with 1/3/5-sigma circles.
    ax2 : matplotlib.axes.Axes
        Phase-folded Delta-X time series (offset=0.25).
    ax3 : matplotlib.axes.Axes
        Phase-folded Delta-Y time series (offset=0.25).
    ax4 : matplotlib.axes.Axes
        Phase-folded detrended flux (alignment reference).
    verbose : bool
        Print diagnostic values to stdout if True.

    Returns
    -------
    pvalue : float
        centroid_motion_score = mean(z_x, z_y).  np.nan if indeterminate.
    pval_flag : str
        'passed', 'failed', or 'indeterminate'.

    Example usage
    -------------
    pvalue, pval_flag = centroid_analysis(
        ID=259377017, Sector=3, hdu=hdu,
        LC_df=lc_df, transit_results_df=bestfit_df,
        ax1=ax1, ax2=ax2, ax3=ax3, ax4=ax4,
        verbose=True,
    )
    """
    import numpy as np
    import matplotlib.pyplot as plt
    import astropy.units as u
    from transitleastsquares import transit_mask

    # ------------------------------------------------------------------
    # 1. Extract centroid series and TCE parameters
    # ------------------------------------------------------------------
    centx_orig = LC_df['Centroid X Positions'].to_numpy(dtype=np.float64)
    centy_orig = LC_df['Centroid Y Positions'].to_numpy(dtype=np.float64)
    flux       = LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    time       = LC_df['Time'].to_numpy(dtype=np.float64)

    # Median-subtract so the origin is the median centroid position
    centx = centx_orig - np.nanmedian(centx_orig)
    centy = centy_orig - np.nanmedian(centy_orig)

    # TCE parameters -- TLS preferred, BLS fallback
    try:
        Period   = transit_results_df['TLS Period [d]'].item()
        T0       = transit_results_df['TLS TC [BTJD]'].item()
        duration = (transit_results_df['TLS Dur [hrs]'].item() * u.hour).to(u.day).value
        Depth    = transit_results_df['TLS depth [ppt]'].item() / 1e3
    except KeyError:
        Period   = transit_results_df['BLS Period [d]'].item()
        T0       = transit_results_df['BLS TC [BTJD]'].item()
        duration = (transit_results_df['BLS Dur [hrs]'].item() * u.hour).to(u.day).value
        Depth    = transit_results_df['BLS depth [ppt]'].item() / 1e3

    XLIM = 3.5 * duration   # phase window shown in ax2/ax3 (in days)

    # ------------------------------------------------------------------
    # 2. Circle radii for ax1 (visual reference only, not used for gating)
    # ------------------------------------------------------------------
    std_x = np.nanstd(centx)
    std_y = np.nanstd(centy)
    radius     = np.sqrt((5.0 * std_x)**2 + (5.0 * std_y)**2)
    radius3sig = np.sqrt((3.0 * std_x)**2 + (3.0 * std_y)**2)
    radius1sig = np.sqrt((1.0 * std_x)**2 + (1.0 * std_y)**2)

    # ------------------------------------------------------------------
    # 3. ax1 -- Delta-X vs Delta-Y scatter with sigma circles
    # ------------------------------------------------------------------
    angle    = np.linspace(0, 2 * np.pi, 150)
    circ1, = ax1.plot(radius     * np.cos(angle), radius     * np.sin(angle),
                      'b-', label=r'r = 5$\sigma$', zorder=-10)
    circ2, = ax1.plot(radius3sig * np.cos(angle), radius3sig * np.sin(angle),
                      'g-', label=r'r = 3$\sigma$', zorder=-10)
    circ3, = ax1.plot(radius1sig * np.cos(angle), radius1sig * np.sin(angle),
                      'r-', label=r'r = 1$\sigma$', zorder=-10)

    ax1.plot(centx, centy, 'k.', ms=2, rasterized=True, zorder=5)
    x, y = 0, 0
    if np.nanmedian(centx) == 0:
        ax1.plot(x, y, 'rX', markersize=10, zorder=9)
    else:
        ax1.plot(x, y, 'rX', markersize=10, zorder=11)

    ax1.set_xlabel(r'$\Delta X$ [pixels]')
    ax1.set_ylabel(r'$\Delta Y$ [pixels]')
    ax1.axis('equal')
    try:
        ax1.set_xlim(-1.05 * radius, 1.05 * radius)
        ax1.set_ylim(-1.05 * radius, 1.05 * radius)
    except ValueError:
        ax1.set_xlim(-3, 3)
        ax1.set_ylim(-3, 3)
        ax1.text(-1, 0.5, 'Problems with Centroiding',
                 ha='center', va='center', transform=ax1.transData)

    handles = [
        plt.plot([], marker='.', ls='none', color='blue')[0],
        plt.plot([], marker='.', ls='none', color='green')[0],
        plt.plot([], marker='.', ls='none', color='red')[0],
    ]
    ax1.legend(handles=handles,
               labels=[circ1.get_label(), circ2.get_label(), circ3.get_label()],
               loc='upper right', handletextpad=0.01,
               borderaxespad=0, borderpad=0,
               numpoints=1, markerscale=1, labelspacing=0.1, handlelength=1)

    # ------------------------------------------------------------------
    # 4. Phase-fold centroid and flux series (offset=0.25 for display)
    # ------------------------------------------------------------------
    pfx, ffx = fullphasefold(time, T0, Period, centx, offset=0.25)
    pfy, ffy = fullphasefold(time, T0, Period, centy, offset=0.25)
    pf,  ff  = fullphasefold(time, T0, Period, flux,  offset=0.25)

    mx = np.where(np.abs(pfx) < XLIM)
    my = np.where(np.abs(pfy) < XLIM)

    # ------------------------------------------------------------------
    # 5. In-transit / OOT split using transit_mask (3 * duration window)
    # ------------------------------------------------------------------
    intransit = transit_mask(time, Period, 3.0 * duration, T0)

    _, ffxin  = fullphasefold(time[intransit],  T0, Period, centx[intransit],  offset=0.25)
    _, ffxout = fullphasefold(time[~intransit], T0, Period, centx[~intransit], offset=0.25)
    _, ffyin  = fullphasefold(time[intransit],  T0, Period, centy[intransit],  offset=0.25)
    _, ffyout = fullphasefold(time[~intransit], T0, Period, centy[~intransit], offset=0.25)

    N_in_x = int(np.sum(np.isfinite(ffxin)))
    N_in_y = int(np.sum(np.isfinite(ffyin)))

    std_xout = np.nanstd(ffxout)
    std_yout = np.nanstd(ffyout)

    # ------------------------------------------------------------------
    # 6. In-transit mean-shift z-score (the only pass/fail test)
    #    z = |mean(in) - mean(out)| / (std(out) / sqrt(N_in))
    # ------------------------------------------------------------------
    if std_xout == 0 or N_in_x == 0:
        zin_scorex = np.nan
    else:
        zin_scorex = (np.abs(np.nanmean(ffxin) - np.nanmean(ffxout))
                      / (std_xout / np.sqrt(N_in_x)))

    if std_yout == 0 or N_in_y == 0:
        zin_scorey = np.nan
    else:
        zin_scorey = (np.abs(np.nanmean(ffyin) - np.nanmean(ffyout))
                      / (std_yout / np.sqrt(N_in_y)))

    zin_score = np.nanmean([zin_scorex, zin_scorey])

    if np.isnan(zin_score):
        pval_flag = 'indeterminate'
    elif zin_score >= 3.0:
        pval_flag = 'failed'
    else:
        pval_flag = 'passed'

    pvalue = zin_score

    if verbose:
        print(f'[centroid_analysis] TIC {ID} S{Sector}')
        print(f'  N_in_x={N_in_x}  N_in_y={N_in_y}')
        print(f'  zin_scorex={zin_scorex}  zin_scorey={zin_scorey}')
        print(f'  zin_score={zin_score}  pval_flag={pval_flag}')

    # ------------------------------------------------------------------
    # 7. ax2 / ax3 -- Phase-folded Delta-X and Delta-Y with reference lines
    #
    # All lines are derived from the OOT phase-folded centroid distributions,
    # which are what the z-score test actually uses.  Nothing here is derived
    # from ffx[mx] (the old transit-window-clipped subset), which had no
    # principled connection to the pass/fail test.
    #
    # Green solid  : OOT mean -- the baseline the z-score measures offset from
    # Red dashed   : OOT mean +/- 3 * std(OOT) -- per-cadence scatter band;
    #                lets the reviewer see whether individual in-transit points
    #                are outliers relative to OOT scatter.  Note: this is NOT
    #                the z-score threshold (which is on the mean, not individual
    #                points) but is the most useful visual reference.
    # Cyan dashed  : in-transit mean -- the quantity being tested
    # ------------------------------------------------------------------
    mean_xout = np.nanmean(ffxout)
    mean_yout = np.nanmean(ffyout)

    ax2.axhline(y=mean_xout,                    color='green', lw=1.0,          zorder=5)
    ax2.axhline(y=mean_xout + 3.0 * std_xout,   color='red',   lw=1.0, ls='--', zorder=5)
    ax2.axhline(y=mean_xout - 3.0 * std_xout,   color='red',   lw=1.0, ls='--', zorder=5)
    ax2.axhline(y=np.nanmean(ffxin),             color='cyan',  lw=1.5, ls='--', zorder=6)

    ax3.axhline(y=mean_yout,                    color='green', lw=1.0,          zorder=5)
    ax3.axhline(y=mean_yout + 3.0 * std_yout,   color='red',   lw=1.0, ls='--', zorder=5)
    ax3.axhline(y=mean_yout - 3.0 * std_yout,   color='red',   lw=1.0, ls='--', zorder=5)
    ax3.axhline(y=np.nanmean(ffyin),             color='cyan',  lw=1.5, ls='--', zorder=6)

    for _ax in [ax2, ax3, ax4]:
        for xv in [0.25, 0.50, 0.75]:
            _ax.axvline(x=xv, color='green', zorder=-10)

    ax2.plot(pfx, ffx, 'k.', ms=2, rasterized=True)
    ax3.plot(pfy, ffy, 'k.', ms=2, rasterized=True)
    ax4.plot(pf,  ff,  'k.', ms=2, rasterized=True)

    try:
        ax2.set_ylim(mean_xout - 7.0 * std_xout, mean_xout + 7.0 * std_xout)
        ax3.set_ylim(mean_yout - 7.0 * std_yout, mean_yout + 7.0 * std_yout)
    except ValueError:
        for _ax in [ax2, ax3]:
            _ax.set_ylim(-3, 3)
            _ax.set_xlim(-0.25, 1.25)
            _ax.text(0.25, 0.5, 'Problems with Centroiding',
                     ha='center', va='center', transform=_ax.transData)

    Nstds = 5
    mask1 = np.where(np.abs(pf) < 3 * duration)
    ymin  = (np.nanmedian(ff[mask1]) - Nstds * np.nanstd(ff[mask1])
             if 1 - Depth > np.nanmedian(ff[mask1]) - Nstds * np.nanstd(ff[mask1])
             else 1 - Depth)
    ymax  = (np.nanmedian(ff[mask1]) + Nstds * np.nanstd(ff[mask1])
             if 1 + Depth < np.nanmedian(ff[mask1]) + Nstds * np.nanstd(ff[mask1])
             else 1 + Depth)
    ax4.set_ylim(ymin, ymax)

    ax2.set_xlabel('Phase + offset = 0.25')
    ax3.set_xlabel('Phase + offset = 0.25')
    ax4.set_xlabel('Phase + offset = 0.25')
    ax2.set_ylabel(r'$\Delta X$ [pixels]')
    ax3.set_ylabel(r'$\Delta Y$ [pixels]')
    ax4.set_ylabel('Normalized Flux')

    # ------------------------------------------------------------------
    # 8. Panel title and border rendering
    # ------------------------------------------------------------------
    LW = 3
    if pval_flag == 'indeterminate':
        for _ax in [ax2, ax3, ax4]:
            for spine in _ax.spines.values():
                spine.set_color('orange')
                spine.set_linewidth(LW)
        ax2.set_title('Centroid Analysis: indeterminate', color='orange')
    elif pval_flag == 'failed':
        for _ax in [ax2, ax3, ax4]:
            for spine in _ax.spines.values():
                spine.set_color('red')
                spine.set_linewidth(LW)
        ax2.set_title(
            f'Centroid Analysis: failed (z = {zin_score:.2f} > 3)',
            color='red',
        )
    else:
        ax2.set_title('Centroid Analysis: passed', color='black')

    # ------------------------------------------------------------------
    # 9. Return (preserves original API)
    # ------------------------------------------------------------------
    return pvalue, pval_flag
#
#
#
def plot_mirrored_transits_and_collect_vetting_metrics(ID,Sector,LC_df,
                                                       transit_results_df,
                                                       BLSorTLSmodel_df,
                                                       ax1,ax2,ax3,verbose):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    import astropy.units as u
    T = LC_df['Time'].to_numpy(dtype=np.float64)
    F = LC_df['Detrended Flux'].to_numpy(dtype=np.float64)
    E = LC_df['Detrended Error'].to_numpy(dtype=np.float64)
    try:
        Period = transit_results_df['TLS Period [d]'].item()
        T0 = transit_results_df['TLS TC [BTJD]'].item()
        duration = (transit_results_df['TLS Dur [hrs]'].item()*u.hour).value # in hours
        Depth=transit_results_df['TLS depth [ppt]'].item()/1e3
    except KeyError:
        Period = transit_results_df['BLS Period [d]'].item()
        T0 = transit_results_df['BLS TC [BTJD]'].item()
        duration = (transit_results_df['BLS Dur [hrs]'].item()*u.hour).value # in hours
        Depth=transit_results_df['BLS depth [ppt]'].item()/1e3
    pf,ff = phasefold(T0,T,Period,F)
    m = np.abs(pf*24) < 5*duration
    #
    vet_df, mirror_left,mirror_right, orig_mirror_left,orig_mirror_right, appended_transit_results = in_versus_out_of_transit_test(ID,Sector,LC_df,transit_results_df,BLSorTLSmodel_df,verbose)
#     symmetry_metric = vet_df['symmetry'].item() #OLD
    symmetry_depth_metric = vet_df['symmetry_depth_metric'].item()
    #symmetry_duration_metric = vet_df['symmetry_duration_metric'].item() #unused
    symmetry_qtran_metric = vet_df['symmetry_qtran_metric'].item()
    symmetry_flag = vet_df['symmetry_flag'].item()
    #
    #
    mirror_pf_L,mirror_ff_L = mirror_left[0],mirror_left[1]
    mirror_pf_R,mirror_ff_R = mirror_right[0],mirror_right[1]
    #
    orig_mirror_pf_L,orig_mirror_ff_L = orig_mirror_left[0],orig_mirror_left[1]
    orig_mirror_pf_R,orig_mirror_ff_R = orig_mirror_right[0],orig_mirror_right[1]
    #
    ax1.plot(24*orig_mirror_pf_L,orig_mirror_ff_L,'g.')
    ax2.plot(24*orig_mirror_pf_R,orig_mirror_ff_R,'r.')
    ax3.plot(24*pf[m],ff[m],'k.')
    
    ax1.plot(24*mirror_pf_L,mirror_ff_L,color='orange',marker='o',linestyle='none')
    ax2.plot(24*mirror_pf_R,mirror_ff_R,color='orange',marker='o',linestyle='none')
    
    XLIM=3.5*duration
    ax1.set_xlim(-XLIM,XLIM)
    ax2.set_xlim(-XLIM,XLIM)
    ax3.set_xlim(-XLIM,XLIM)
    #
    #
    ax1.text(0.8,0.9,'Left transit'+'\n'+'mirrored',\
             horizontalalignment='center',verticalalignment='center',\
             weight='bold',transform = ax1.transAxes)
    #
    ax2.text(0.8,0.9,'Right transit'+'\n'+'mirrored',\
             horizontalalignment='center',verticalalignment='center',
             weight='bold',transform = ax2.transAxes)
    #
    ax3.text(0.8,0.9,'Original transit',\
             horizontalalignment='center',verticalalignment='center',\
             weight='bold',transform = ax3.transAxes)
    #
    #measure depths
    try:
        mdL = np.abs(mirror_pf_L*24) < 3*duration
        mdR = np.abs(mirror_pf_R*24) < 3*duration
        md = np.abs(pf*24) < 3*duration
        depthL = 1-np.nanquantile(mirror_ff_L[mdL],q=1e-4)
        depthR = 1-np.nanquantile(mirror_ff_R[mdR],q=1e-4)
        depth = 1-np.nanquantile(ff[md],q=1e-4)
    except ValueError:
        depthL = 1-np.nanquantile(mirror_ff_L,q=1e-4)
        depthR = 1-np.nanquantile(mirror_ff_R,q=1e-4)
        depth = 1-np.nanquantile(ff,q=1e-4)
    #
    ax1.axhline(y=1-depthL)
    ax2.axhline(y=1-depthR)
    ax3.axhline(y=1-depth)
    ax1.axvline(x=0)
    ax2.axvline(x=0)
    ax3.axvline(x=0)
    #
    Nstds=5
    ymin,ymax = np.nanmin(ff)-Nstds*np.nanstd(ff),np.nanmax(ff)+Nstds*np.nanstd(ff)
    if ymin< np.nanmedian(ff)-Nstds*np.nanstd(ff):
        ymin,ymax = np.nanmedian(ff)-Nstds*np.nanstd(ff),np.nanmedian(ff)+Nstds*np.nanstd(ff)
        
    YLIM=2*Depth    
    Nstds=5
    mask1= np.where(np.abs(pf)< 3*duration)
    if 1-YLIM > np.nanmedian(ff[mask1])-Nstds*np.nanstd(ff[mask1]):
        ymin=np.nanmedian(ff[mask1])-Nstds*np.nanstd(ff[mask1])
    else:
        ymin=1-YLIM
    if 1+YLIM < np.nanmedian(ff[mask1])+Nstds*np.nanstd(ff[mask1]):
        ymax=np.nanmedian(ff[mask1])+Nstds*np.nanstd(ff[mask1])
    else:
        ymax=1+YLIM                
    #
    ax1.set_ylim(ymin,ymax)
    ax2.set_ylim(ymin,ymax)
    ax3.set_ylim(ymin,ymax)
    #
    ax1.set_xlabel('Phase [Hours since '+str(np.round(T0,5))+' BTJD]')
    ax2.set_xlabel('Phase [Hours since '+str(np.round(T0,5))+' BTJD]')
    ax3.set_xlabel('Phase [Hours since '+str(np.round(T0,5))+' BTJD]')
    ax1.set_ylabel('Normalized Flux')
    ax2.set_ylabel('Normalized Flux')
    ax3.set_ylabel('Normalized Flux')
    string_color='black'
    if symmetry_flag=='failed':      
        LW=3
        for ax in [ax1,ax2, ax3]:
            for axis in ['top', 'bottom', 'left', 'right']:
                ax.spines[axis].set_color('red')
                ax.spines[axis].set_linewidth(LW)

    ax1.set_title('Symmetry Test Result: '+str(symmetry_flag),color=string_color)
    return appended_transit_results
#
#
#
def plot_page3_text(ID,Sector,LC_df,appended_transit_results,fig):
    """

    Input Parameters
    ----------

    Returns
    -------
        *
    """      
    vet_header='Automated Vetting Test Results \n         for TIC '+str(ID) 
    #
    vet_txt_array=['odd_even_mismatch', 'odd_even_mismatch_flag', 'SNR', 'SNR_flag',\
                   'symmetry_depth_metric','symmetry_qtran_metric',
                   'symmetry_depth_SNR','symmetry_qtran_SNR', 'symmetry_flag',\
                   'CDPP_in_transit', 'CDPP_out_of_transit','CDPP_ratio','CDPP_flag',\
                   'centroid_motion_score','centroid_motion_flag',\
                   'a_over_R_star','a_over_R_star_flag',\
                   'q_transit','q_transit_flag']
    
    vet_df = appended_transit_results[vet_txt_array]
    fs=12
    vertspacing=0.0225
    horispacing=0.875
    ###
    #fonty=0.425
    fonty=0.275
    fontx=0.025
    #star stuff
    N=fonty#-0.025
    fig.text(fontx+0.01,N,vet_header, transform=fig.transFigure, size=fs+4)
    N=5
    FS=fs-2
    #
    def symmetry_metric_text_OLD(vet_df):
        symmetry_df = vet_df.filter(regex='symmetry')
        text = 'symmetric_metrics'
        string_text = str(np.round(symmetry_df['symmetry_depth_metric'].item(),4))+' , '+str(np.round(symmetry_df['symmetry_qtran_metric'].item(),4))    
        return text, string_text
    #    
    def symmetry_metric_text(vet_df):
        symmetry_df = vet_df.filter(regex='symmetry')
        text = 'symmetry (depth, qtran)'
        depth_snr_val = symmetry_df['symmetry_depth_SNR'].item()
