import numpy as np
from typing import Dict


def compute_tce_coverage_metrics(
    time: np.ndarray,
    period: float,
    t0: float,
    t14_hours: float,
    min_epochs: int = 2,
) -> Dict[str, float]:
    """
    Compute coverage-related vetting metrics for a single-sector TCE.

    Given the quality-masked LC time array and a recovered ephemeris
    (period, t0, t14_hours), return the number of in-transit cadences,
    the number of distinct observed transit epochs, the expected number
    of transit epochs given the time span, a coverage fraction, a
    single-transit flag, and a lower-bound estimate of the fractional
    period uncertainty.

    Intended for insertion at the final write of `_bestfit.csv` in the
    NEMESIS per-sector vetting flow. Consumed downstream by
    `reconcile_tces_across_sectors`.

    Parameters
    ----------
    time : np.ndarray, shape (T,)
        Monotonic cadence timestamps of the detrended LC in days (BTJD).
        Non-finite entries are dropped before any computation.
    period : float
        Recovered TCE period in days.
    t0 : float
        Recovered transit midtime in days (BTJD). May lie inside,
        before, or after the LC time window; it is folded forward into
        the window modulo `period` as needed.
    t14_hours : float
        Total transit duration (first to fourth contact) in hours.
    min_epochs : int, optional
        Minimum number of distinct observed transit epochs required to
        avoid the single-transit flag. Default 2.

    Returns
    -------
    metrics : dict
        Keys and types:
            'N_in_transit'          : int
            'N_epochs'              : int
            'N_expected_epochs'     : int
            'coverage_fraction'     : float in [0, 1]
            'single_transit_flag'   : bool
            'sigma_P_frac_est'      : float, NaN when N_epochs < 2

    Notes
    -----
    - No flux model is required; only the time axis and ephemeris.
    - Gaps in `time` are handled correctly: a predicted transit falling
      entirely in a gap contributes 0 cadences and is not counted in
      `N_epochs`.
    - `sigma_P_frac_est` is a geometric lower bound of the fractional
      period uncertainty equal to `T14_days / ((N_epochs - 1) * P)`. It
      is intentionally conservative and exists as a floor for the
      period tolerance used in post-detection reconciliation.

    Example
    -------
    >>> import numpy as np
    >>> t = np.arange(0.0, 27.0, 30.0 / 1440.0)
    >>> m = compute_tce_coverage_metrics(
    ...     time=t, period=3.36, t0=1.2, t14_hours=2.1,
    ... )
    >>> m['N_epochs'], m['single_transit_flag']
    (8, False)
    """
    empty = {
        'N_in_transit': 0,
        'N_epochs': 0,
        'N_expected_epochs': 0,
        'coverage_fraction': 0.0,
        'single_transit_flag': True,
        'sigma_P_frac_est': float('nan'),
    }

    t = np.asarray(time, dtype=np.float64)
    t = t[np.isfinite(t)]
    if (t.size == 0
            or not np.isfinite(period) or period <= 0.0
            or not np.isfinite(t0)
            or not np.isfinite(t14_hours) or t14_hours <= 0.0):
        return empty

    t14_days = float(t14_hours) / 24.0
    t_min = float(t.min())
    t_max = float(t.max())

    # Fold t0 forward into [t_min, t_min + period) for deterministic indexing.
    if t0 < t_min:
        k = int(np.ceil((t_min - t0) / period))
        t0_use = t0 + k * period
    elif t0 > t_min + period:
        k = int(np.floor((t0 - t_min) / period))
        t0_use = t0 - k * period
    else:
        t0_use = t0

    if t0_use > t_max:
        return empty

    n_max = int(np.floor((t_max - t0_use) / period))
    expected_midtimes = t0_use + np.arange(n_max + 1) * period
    n_expected = int(expected_midtimes.size)
    if n_expected == 0:
        return empty

    half_dur = 0.5 * t14_days
    n_in_transit_total = 0
    n_epochs_with_data = 0
    for tc in expected_midtimes:
        hits = int(np.count_nonzero(np.abs(t - tc) <= half_dur))
        if hits > 0:
            n_in_transit_total += hits
            n_epochs_with_data += 1

    single_transit_flag = bool(n_epochs_with_data < min_epochs)
    coverage_fraction = (float(n_epochs_with_data) / float(n_expected)
                         if n_expected > 0 else 0.0)

    if n_epochs_with_data >= 2:
        span_obs = (n_epochs_with_data - 1) * period
        sigma_P_frac_est = float(t14_days / max(span_obs, 1e-12))
    else:
        sigma_P_frac_est = float('nan')

    return {
        'N_in_transit': int(n_in_transit_total),
        'N_epochs': int(n_epochs_with_data),
        'N_expected_epochs': int(n_expected),
        'coverage_fraction': float(coverage_fraction),
        'single_transit_flag': single_transit_flag,
        'sigma_P_frac_est': sigma_P_frac_est,
    }
