        print(f"[page4] TIC {ID} Sector {Sector}: vetting metrics FAILED "
              f"({type(_exc).__name__}: {_exc}). Column block NaN-filled; "
              f"bestfit CSV still written.", flush=True)
        appended_transit_results = transit_results_df.copy()
