    plot_page3_text(ID,Sector,LC_df,appended_transit_results,fig)
    #
    gs1.update(wspace=-0.5, hspace=-0.5)
    
    gs1.tight_layout(fig,pad=1)
    fig.set_size_inches(12, 10)  # Ensure consistent size
    
    page_num=4
    if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
        fig.savefig(saveReportpath+'TIC_'+str(ID)+'_Multi_Sector_'+report_dir_name_suffix+'_page'+str(page_num)+'.png')#,bbox_inches='tight')
    else:
        fig.savefig(saveReportpath+'TIC_'+str(ID)+f'_{sector_tag}_{report_dir_name_suffix}_page'+str(page_num)+'.png')#,bbox_inches='tight')
    plt.close()
    #plt.show()
