def all_transit_times(T0, t, period):
    """
    Return all predicted mid-transit times within the time span of t.

    This version is safe whether T0 is before, inside, or after the
    observed baseline.
    """
    import numpy as np

    t = np.asarray(t, dtype=float)
    good = np.isfinite(t)
    if good.sum() == 0 or not np.isfinite(T0) or not np.isfinite(period) or period <= 0:
        return []

    t_min = float(np.nanmin(t[good]))
    t_max = float(np.nanmax(t[good]))

    n_start = int(np.ceil((t_min - T0) / period))
    n_stop = int(np.floor((t_max - T0) / period))

    if n_stop < n_start:
        return []

    return list(T0 + np.arange(n_start, n_stop + 1) * period)

#
def cut_around_T0(T0,lc,time_chunk):
    """
    
    Input Parameters
    ----------

    Returns
    -------
        *
    """          
    import pandas as pd
    #
    cut = np.where( ((T0-time_chunk) < np.array(lc.Time)) & ((T0+time_chunk) > np.array(lc.Time))  )[0]
    #
    newt=np.array(lc.Time)[cut]
    newf=np.array(lc.Flux)[cut]
    newe=np.array(lc.Error)[cut]
    #
    newlc = pd.DataFrame({'Time':newt,'Flux':newf,'Error':newe})
    return newlc
