import numpy as np
from typing import Tuple


def safe_panel_normalization(
    flux: np.ndarray,
    error: np.ndarray,
    fallback_scale: float = 1.0,
    min_scale: float = 1e-6,
) -> Tuple[np.ndarray, np.ndarray, float]:
    """Normalize a per-panel flux/error pair by a guaranteed-positive scale.

    Replaces the pattern::

        norm_med  = np.nanmedian(lc_fp)
        norm_flux = lc_fp / norm_med
        norm_err  = lc_ep / norm_med

    which divides by the local (per-transit-window) median flux. For faint,
    blended, or strongly systematic-affected targets that local median can be
    non-positive, which (a) flips the sign of the error, producing a negative
    ``yerr`` that crashes ``matplotlib.errorbar``, and (b) silently inverts the
    flux panel. This function divides by a scale floored at ``min_scale``,
    falling back to ``fallback_scale`` when the median is non-finite or
    non-positive, and returns the error as a non-negative magnitude with any
    non-finite entries set to NaN (which ``errorbar`` renders as no bar rather
    than raising).

    Parameters
    ----------
    flux : np.ndarray
        Per-panel flux values (e.g. ``lctemp.Flux``).
    error : np.ndarray
        Per-panel 1-sigma uncertainties (e.g. ``lctemp.Error``). Treated as a
        magnitude; the sign is never propagated.
    fallback_scale : float, optional
        Scale used when the flux median is non-finite or <= ``min_scale``.
        Default ``1.0`` (plot the un-normalized detrended values, which are
        already globally normalized to ~1.0, rather than an inverted panel).
    min_scale : float, optional
        Minimum acceptable normalization scale. Default ``1e-6``.

    Returns
    -------
    norm_flux : np.ndarray
        Flux divided by the guarded scale.
    norm_err : np.ndarray
        Non-negative error divided by the guarded scale; non-finite -> NaN.
    scale : float
        The normalization scale actually applied (median or fallback).

    Examples
    --------
    >>> nf, ne, s = safe_panel_normalization(lc_fp, lc_ep)
    >>> bool(np.all(ne[np.isfinite(ne)] >= 0))
    True
    """
    flux = np.asarray(flux, dtype=np.float64)
    error = np.asarray(error, dtype=np.float64)

    med = np.nanmedian(flux) if np.isfinite(flux).any() else np.nan
    scale = med if (np.isfinite(med) and med > min_scale) else float(fallback_scale)

    norm_flux = flux / scale
    norm_err = np.abs(error / scale)
    norm_err[~np.isfinite(norm_err)] = np.nan

    return norm_flux, norm_err, scale
#
#
def _per_transit_snr(
    t0: float,
    lc_time: np.ndarray,
    lc_flux: np.ndarray,
    dur_days: float,
    window_days: float,
    intransit_half_width_factor: float = 1.0,
) -> float:
    """
    Compute a simple per-transit SNR for a single event.

    SNR = |median(in-transit flux) - 1| / RMS(out-of-transit flux)

    The light curve is assumed to be normalised to unit continuum (detrended).
    Returns np.nan if fewer than 2 in-transit OR fewer than 2 out-of-transit
    cadences exist within the zoom window.

    Parameters
    ----------
    t0 : float
        Mid-transit time [BTJD].
    lc_time, lc_flux : np.ndarray
        Time and normalised flux arrays (all data, not pre-clipped).
    dur_days : float
        Transit duration T14 [days].
    window_days : float
        Half-width of the zoom window [days]; defines out-of-transit boundary.
    intransit_half_width_factor : float
        In-transit window = t0 ± factor * dur_days.
        Default 1.0 uses the full T14 as the half-width, capturing ingress and
        egress cadences at 30-min FFI cadence.  Use 0.5 for a pure flat-bottom
        box assessment.

    Returns
    -------
    float
        Per-transit SNR, or np.nan if insufficient cadences.
    """
    window_mask = np.abs(lc_time - t0) <= window_days
    t_win  = lc_time[window_mask]
    f_win  = lc_flux[window_mask]

    in_mask  = np.abs(t_win - t0) <= intransit_half_width_factor * dur_days
    out_mask = ~in_mask

    # Require at least 2 cadences in each region for a meaningful estimate
    if in_mask.sum() < 2 or out_mask.sum() < 2:
        return np.nan

    f_in  = f_win[in_mask]
    f_out = f_win[out_mask]

    continuum  = np.nanmedian(f_out)
    depth_est  = continuum - np.nanmedian(f_in)   # positive for a dip
    noise_est  = np.nanstd(f_out)

    if noise_est <= 0 or not np.isfinite(noise_est) or not np.isfinite(depth_est):
        return np.nan

    return float(depth_est / noise_est)


def _select_transit_indices(
    snr_array: np.ndarray,
    n_best: int = 3,
    n_mid: int = 3,
    n_worst: int = 3,
) -> tuple:
    """
    Return (selected_indices, tier_labels) for stratified SNR-ranked selection.

    Tier labels: 0 = BEST, 1 = MID, 2 = WORST.

    Ranking is performed exclusively on transits with finite SNR.  NaN-SNR
    transits (data gaps) are never ranked into BEST or MID, and are only
    used to pad WORST if there are fewer than n_worst finite transits
    available after filling BEST and MID.  This prevents uninformative
    gap panels from displacing real low-SNR detections in the WORST tier.

    If the total number of finite-SNR transits is insufficient to fill all
    three tiers, tiers are filled in priority order: BEST first, then WORST,
    then MID from whatever remains.

    Within each tier, indices are returned sorted chronologically (ascending).

    Parameters
    ----------
    snr_array : np.ndarray
        Per-transit SNR values (NaN allowed).
    n_best, n_mid, n_worst : int
        Panels per tier (default 3 each = 9 total).

    Returns
    -------
    idx : np.ndarray of int
        Indices into snr_array ordered BEST -> MID -> WORST.
    tiers : np.ndarray of int
        Tier label for each returned index (0=BEST, 1=MID, 2=WORST).
    """
    finite_mask = np.isfinite(snr_array)
    finite_idx  = np.where(finite_mask)[0]
    nan_idx     = np.where(~finite_mask)[0]

    # Rank finite transits by SNR descending
    if len(finite_idx) > 0:
        order      = np.argsort(snr_array[finite_idx])[::-1]   # descending
        finite_ranked = finite_idx[order]
    else:
        finite_ranked = np.array([], dtype=int)

    N_finite = len(finite_ranked)

    # Fill BEST from top of ranked finite pool
    best_idx  = finite_ranked[:n_best]

    # Fill WORST from bottom of ranked finite pool (those not already in BEST)
    remaining_after_best = finite_ranked[n_best:]
    n_worst_finite       = min(n_worst, len(remaining_after_best))
    worst_idx_finite     = remaining_after_best[len(remaining_after_best) - n_worst_finite:]

    # Pad WORST with NaN transits if finite pool is short
    n_worst_nan_needed = n_worst - n_worst_finite
    worst_idx_nan      = nan_idx[:n_worst_nan_needed]
    worst_idx          = np.concatenate([worst_idx_finite, worst_idx_nan])

    # Fill MID from whatever finite transits remain between BEST and WORST
    used          = set(best_idx.tolist()) | set(worst_idx_finite.tolist())
    mid_pool      = np.array([i for i in finite_ranked if i not in used], dtype=int)
    if len(mid_pool) >= n_mid:
        centre  = len(mid_pool) // 2
        half    = n_mid // 2
        mid_idx = mid_pool[max(0, centre - half): centre - half + n_mid]
    else:
        mid_idx = mid_pool   # use whatever is left

    def _sort_by_snr(indices, ascending=False):
        if len(indices) == 0:
            return indices
        snrs = snr_array[indices]
        # Push NaNs to the end regardless of sort direction
        finite  = np.isfinite(snrs)
        fin_idx = indices[finite]
        nan_idx = indices[~finite]
        order   = np.argsort(snrs[finite])
        if not ascending:
            order = order[::-1]
        return np.concatenate([fin_idx[order], nan_idx])

    best_idx  = _sort_by_snr(best_idx,  ascending=False)
    mid_idx   = _sort_by_snr(mid_idx,   ascending=False)
    worst_idx = _sort_by_snr(worst_idx, ascending=True)

    idx   = np.concatenate([best_idx, mid_idx, worst_idx])
    tiers = np.concatenate([
        np.zeros(len(best_idx),  dtype=int),
        np.ones( len(mid_idx),   dtype=int),
        np.full( len(worst_idx), 2, dtype=int),
    ])
    return idx, tiers


# Tier cosmetics: (badge_text, title_color)
# Background colouring is applied only in stratified mode
_TIER_STYLE = {
    0: ("BEST",  "royalblue",  "#d4e6f1"),
    1: ("MID",   "k",          "#f9f9f9"),
    2: ("WORST", "firebrick",  "#fde8e8"),
}

_INTRANSIT_COLOR  = "darkorange"
_OUTTRANSIT_COLOR = "0.35"


def Vetting_Report_5th_page_plot_individual_transits(
    ID,
    Sector,
    cadence,
    LC_df,
    path,
    bestfit_df,
    model_df,
    BLSorTLS,
    default_settings,
    max_panels: int = 9,
    n_dur_window: float = 3.5,
    snr_threshold_for_stratify: int = 9,
    n_best: int = 3,
    n_mid:  int = 3,
    n_worst: int = 3,
    intransit_half_width_factor: float = 1.0,
):
    """
    Produce page 5 of the NEMESIS vetting report: individual transit zoom-ins.

    Selection logic
    ---------------
    * N_total <= max_panels  : all transits in chronological order (unchanged).
    * N_total >  max_panels  : stratified SNR selection --
        ``n_best`` highest-SNR transits, ``n_mid`` median-SNR transits,
        ``n_worst`` lowest-SNR transits, each group presented internally in
        chronological order.  Panel titles carry a BEST / MID / WORST badge
        and a background colour to aid rapid triage.

    Per-transit SNR
    ---------------
    SNR_i = |median(in-transit flux) - 1| / std(out-of-transit flux)
    where "in-transit" is ± dur/2 and "out-of-transit" is the remainder of
    the ±n_dur_window window.  NaN-SNR transits (data gaps) are ranked last
    and preferentially placed in the WORST tier.

    Cadence colouring
    -----------------
    Within each panel, cadences falling inside the model transit window
    (|t - t0| <= dur/2) are plotted in a distinct colour (darkorange) so the
    reviewer can immediately assess in-transit cadence coverage.

    Parameters
    ----------
    ID : int
        TIC identifier.
    Sector : int, list, or None
        Sector(s) processed.
    cadence : str
        TESS exposure cadence string.
    LC_df : pd.DataFrame
        Final processed light curve with columns ``Time``, ``Detrended Flux``,
        ``Detrended Error``.
    path : str
        Base path (passed through).
    bestfit_df : pd.DataFrame
        BLS or TLS best-fit parameters.
    model_df : pd.DataFrame
        Model time series with columns ``Time``, ``Model``.
    BLSorTLS : str
        ``'BLS'`` or ``'TLS'``.
    default_settings : dict
        NEMESIS pipeline settings dict.
    max_panels : int
        Maximum number of transit panels (default 9).
    n_dur_window : float
        Half-window width as a multiple of transit duration (default 3.5).
    snr_threshold_for_stratify : int
        Minimum N_total to activate stratified mode (default 9, i.e. >9).
    n_best, n_mid, n_worst : int
        Panels per tier when stratified (default 3 each).

    Example usage
    -------------
    Vetting_Report_5th_page_plot_individual_transits(
        ID=12345678, Sector=5, cadence='FFI', LC_df=lc, path='/out/',
        bestfit_df=bdf, model_df=mdf, BLSorTLS='TLS',
        default_settings=settings,
    )
    """
    import math
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    import matplotlib.gridspec as gridspec
    import astropy.units as u

    # ── settings ──────────────────────────────────────────────────────────────
    get_all_sectors = default_settings.get('get_all_sectors', False)
    if BLSorTLS == 'TLS':
        report_dir_name_suffix = 'TLS_Report'
        saveReportpath = default_settings.get('saveReportpath_TLS')
    else:
        report_dir_name_suffix = 'BLS_Report'
        saveReportpath = default_settings.get('saveReportpath_BLS')

    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = 'Multi_Sector'
    else:
        sector_tag = f'Sector_{Sector:04d}'
    fs = 10   # base font size

    def _sec_str(s):
        return str(s).zfill(4) if isinstance(s, int) else str(s)

    if (get_all_sectors is True) or (Sector is None) or (not isinstance(Sector, int)):
        sector_tag = 'Multi_Sector'
    else:
        sector_tag = f'Sector_{_sec_str(Sector)}'

    # ── best-fit parameters ───────────────────────────────────────────────────
    if BLSorTLS == 'TLS':
        P       = bestfit_df['TLS Period [d]'].item()
        T0      = bestfit_df['TLS TC [BTJD]'].item()
        Dur_hrs = bestfit_df['TLS Dur [hrs]'].item()
        Depth   = bestfit_df['TLS depth [ppt]'].item() / 1000.0
    else:
        P       = bestfit_df['BLS Period [d]'].item()
        T0      = bestfit_df['BLS TC [BTJD]'].item()
        Dur_hrs = bestfit_df['BLS Dur [hrs]'].item()
        Depth   = bestfit_df['BLS depth [ppt]'].item() / 1000.0

    duration   = (Dur_hrs * u.hour).to(u.day).value   # days
    time_chunk = n_dur_window * duration               # half-window, days

    # ── build working DataFrames ──────────────────────────────────────────────
    input_LC = pd.DataFrame({
        'Time':  LC_df['Time'].to_numpy(dtype=float),
        'Flux':  LC_df['Detrended Flux'].to_numpy(dtype=float),
        'Error': LC_df['Detrended Error'].to_numpy(dtype=float),
    })
    model = pd.DataFrame({
        'Time':  model_df['Time'].to_numpy(dtype=float),
        'Flux':  model_df['Model'].to_numpy(dtype=float),
        'Error': np.nanstd(model_df['Model']) * np.ones(len(model_df)),
    })

    lc_time  = input_LC.Time.to_numpy()
    lc_flux  = input_LC.Flux.to_numpy()
    lc_err   = input_LC.Error.to_numpy()
    flux_norm = lc_flux / np.nanmedian(lc_flux)

    # ── all predicted transit times ───────────────────────────────────────────
    all_TCs  = np.asarray(all_transit_times(T0, lc_time, P))
    N_total  = len(all_TCs)
    
    # ── global shared y-axis range ────────────────────────────────────────────
    # Floor set by 2x the expected depth; ceiling symmetrically above continuum.
    # Expanded by 5-sigma out-of-transit scatter if that is larger.
    Nstds  = 5
    oot_mask = np.ones(len(flux_norm), dtype=bool)
    for tc in all_TCs:
        oot_mask &= np.abs(lc_time - tc) > duration
    oot_scatter = np.nanstd(flux_norm[oot_mask]) if oot_mask.sum() > 0 else np.nanstd(flux_norm)

    YLIM   = max(2.0 * Depth, Nstds * oot_scatter)
    ymin_g = 1.0 - YLIM
    ymax_g = 1.0 + YLIM


    # ── select panels ─────────────────────────────────────────────────────────
    use_stratified = N_total > snr_threshold_for_stratify

    if use_stratified:
        # Compute per-transit SNR
        snr_vals = np.array([
            _per_transit_snr(
                t0=tc,
                lc_time=lc_time,
                lc_flux=flux_norm,
                dur_days=duration,
                window_days=time_chunk,
                intransit_half_width_factor=intransit_half_width_factor,
            )
            for tc in all_TCs
        ])

        sel_idx, tier_labels = _select_transit_indices(
            snr_vals, n_best=n_best, n_mid=n_mid, n_worst=n_worst
        )
        tran_times    = all_TCs[sel_idx]
        transit_tiers = tier_labels
        transit_snrs  = snr_vals[sel_idx]
        n_panels      = len(tran_times)
        stratify_note = (
            f'SNR-stratified: {n_best} best / {n_mid} mid / {n_worst} worst'
            f' of {N_total} transits'
        )
    else:
        tran_times    = all_TCs[:max_panels]
        transit_tiers = np.ones(len(tran_times), dtype=int)  # all MID style
        transit_snrs  = np.full(len(tran_times), np.nan)
        n_panels      = len(tran_times)
        stratify_note = None

    # ── figure layout ─────────────────────────────────────────────────────────
    N_desired_cols = 3
    N_desired_rows = math.ceil(n_panels / N_desired_cols)
    N_desired_rows = max(N_desired_rows, 1)

    fig = plt.figure(figsize=(12, 10))
    gs1 = gridspec.GridSpec(N_desired_rows, N_desired_cols)

    if (get_all_sectors is True) or (Sector is None) or (not isinstance(Sector, int)):
        title_str = f'TIC {ID} Multi-Sector individual distinct transits'
    else:
        title_str = f'TIC {ID} Sector {_sec_str(Sector)} individual distinct transits'

    if stratify_note:
        title_str += f'\n{stratify_note}'
    elif N_total > max_panels:
        title_str += f' (showing first {n_panels} of {N_total})'

    fig.suptitle(title_str, x=0.55, y=1.03, weight='bold', fontsize=fs)

    xlim_hrs = n_dur_window * Dur_hrs

    # ── per-transit panels ────────────────────────────────────────────────────
    for panel_i, (t0temp, tier, snr_i) in enumerate(
        zip(tran_times, transit_tiers, transit_snrs)
    ):
        lctemp    = cut_around_T0(t0temp, input_LC, time_chunk)
        modeltemp = cut_around_T0(t0temp, model,    time_chunk)

        lc_hrs    = 24.0 * (lctemp.Time.to_numpy()    - t0temp)
        model_hrs = 24.0 * (modeltemp.Time.to_numpy() - t0temp)
        lc_fp     = lctemp.Flux.to_numpy()
        lc_ep     = lctemp.Error.to_numpy()

        mcheck   = np.where(np.abs(lc_hrs) < xlim_hrs)[0]
        has_data = len(mcheck) > 0

        ax = fig.add_subplot(gs1[panel_i])

        tier_badge, title_color, bg_color = _TIER_STYLE[int(tier)]

        if has_data:
            norm_flux, norm_err, norm_med = safe_panel_normalization(lc_fp, lc_ep)

            # In-transit vs. out-of-transit colouring
            intransit_mask = np.abs(lc_hrs) <= intransit_half_width_factor * Dur_hrs

            ax.errorbar(
                lc_hrs[~intransit_mask], norm_flux[~intransit_mask],
                yerr=norm_err[~intransit_mask],
                fmt='o', ms=3, color=_OUTTRANSIT_COLOR,
                ecolor=_OUTTRANSIT_COLOR, elinewidth=0.6, alpha=0.7,
                zorder=2,
            )
            ax.errorbar(
                lc_hrs[intransit_mask], norm_flux[intransit_mask],
                yerr=norm_err[intransit_mask],
                fmt='o', ms=3.5, color=_INTRANSIT_COLOR,
                ecolor=_INTRANSIT_COLOR, elinewidth=0.8, alpha=0.9,
                zorder=3,
            )

            # Apply background tinting only when data is present and stratified
            if use_stratified:
                ax.set_facecolor(bg_color)

        else:
            # No data: plain white panel, consistent with original behaviour
            ax.set_facecolor('white')
            ax.text(0.5, 0.5, 'No transit data!',
                    ha='center', va='center', transform=ax.transAxes,
                    fontsize=8, color='gray', style='italic')

        # Model: solid red line
        if len(model_hrs) > 0:
            model_flux_norm = modeltemp.Flux.to_numpy()
            ax.plot(model_hrs, model_flux_norm, 'r-', lw=1.4, zorder=4, alpha=0.9)

        ax.axvline(0, color='gray', lw=0.6, ls=':', zorder=1)
        ax.set_xlim(-xlim_hrs, xlim_hrs)
        ax.set_ylim(ymin_g, ymax_g)

        # Panel title
        chron_num = int(np.argmin(np.abs(all_TCs - t0temp))) + 1
        if use_stratified:
            snr_str = f'  SNR={snr_i:.1f}' if np.isfinite(snr_i) else '  SNR=n/a'
            badge   = f'[{tier_badge}] '
        else:
            snr_str = ''
            badge   = ''

        ax.set_title(
            f'{badge}T{chron_num}{snr_str}',
            fontsize=7.5,
            fontweight='bold' if use_stratified else 'normal',
            color=title_color if use_stratified else 'k',
            pad=3,
        )

        ax.set_xlabel(f'Hours from {np.round(t0temp,4)} BTJD', fontsize=7)
        ax.set_ylabel('Normalized Flux', fontsize=7)
        ax.tick_params(labelsize=7)
        ax.yaxis.set_major_formatter(
            plt.FuncFormatter(lambda x, _: f'{x:.4f}')
        )

    # Hide unused panels
    for extra_i in range(N_desired_rows*N_desired_cols, N_desired_rows * N_desired_cols):
        ax_hide = fig.add_subplot(gs1[extra_i])
        ax_hide.set_visible(False)
    # ── save ──────────────────────────────────────────────────────────────────
    page_num = 5
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        savepath = (saveReportpath + f'TIC_{ID}_Multi_Sector_'
                    + report_dir_name_suffix + f'_page{page_num}.png')
    else:
        savepath = (saveReportpath + f'TIC_{ID}_{sector_tag}_'
                    + report_dir_name_suffix + f'_page{page_num}.png')
    gs1.tight_layout(fig)
    fig.set_size_inches(12, 10)
    fig.savefig(savepath, bbox_inches='tight')
    plt.close()   
