# fix path input (rely on input settings for paths)
def Vetting_Report_6th_page_LEOVetter(ID, nearby_star_catalog, Sector, cadence,
                                      LC_df, path, bestfit_df,BLSorTLS, 
                                      default_settings, verbose):
    """
    Produce page 6 of the NEMESIS vetting report: LEO-Vetter modshift analysis.

    Calls ``plot_modshift_NEMESIS`` to compute all 17 LEO-Vetter false alarm
    and false positive metrics (via ``check_ALL_thresholds``), render the
    modshift figure, and save it as page 6.  The computed metrics are
    appended as ``LEOVetter_*`` prefixed columns to the bestfit CSV on disk.

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``; used to extract
        the target star row for stellar parameters passed to LEO-Vetter.
    Sector : int, list, or None
        Sector(s) processed; used for output filenames.
    cadence : str
        TESS exposure cadence string.
    LC_df : pd.DataFrame
        Final processed light curve.  Required columns:
        ``Time``, ``Detrended Flux``, ``Detrended Error``.
    path : str
        Base path (passed through; not directly used here).
    bestfit_df : pd.DataFrame
        Best-fit parameter DataFrame (BLS or TLS); auto-detected via column
        names.  Provides ``Period``, ``TC``, ``Dur [hrs]``,
        ``Distinct Transit Count``, and ``depth [ppt]``.
        The LEO-Vetter metric columns are appended to this DataFrame and
        re-saved to disk.
    BLSorTLS : str
        ``'BLS'`` or ``'TLS'``; selects the report directory and bestfit CSV.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``get_all_sectors``,
        ``for_injections``, ``inject_param_P_RP_T0``, ``verbose``,
        ``saveReportpath_BLS``, ``saveReportpath_TLS``, ``savelcpath``.
    verbose : bool, optional
        If ``True``, print LEO-Vetter metric results.  Also read from
        ``default_settings``; this kwarg is kept for call-site compatibility.
        Default is ``True``.

    Returns
    -------
    None
        Figure saved to disk as:
        ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page6.png``

        Bestfit CSV updated with appended ``LEOVetter_*`` columns:
        ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_bestfit.csv``
    """
    star = nearby_star_catalog.loc[nearby_star_catalog['ID']==str(ID)].reset_index(drop=True)
    
    get_all_sectors = default_settings.get('get_all_sectors')
    for_injections = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    verbose = default_settings.get('verbose')
    #
    path = default_settings.get('path')
    savefigpath = default_settings.get('savefigpath')
    savelcpath= default_settings.get('savelcpath')
    downloadpath= default_settings.get('downloadpath')
    
    if BLSorTLS=='TLS':
        report_dir_name_suffix = 'TLS_Report'    
        saveReportpath = default_settings.get('saveReportpath_TLS')
    if BLSorTLS=='BLS':
        report_dir_name_suffix = 'BLS_Report'    
        saveReportpath = default_settings.get('saveReportpath_BLS')     
    #Step 0: create string tag for sector usage
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"       
    import os
    #
    try:
        P =   bestfit_df['TLS Period [d]'].item()
        T0 =  bestfit_df['TLS TC [BTJD]'].item() 
        Dur = bestfit_df['TLS Dur [hrs]'].item() 
        N_transits=bestfit_df['TLS Distinct Transit Count'].item()
        Depth=bestfit_df['TLS depth [ppt]'].item()/1000
    except KeyError:
        P =   bestfit_df['BLS Period [d]'].item()
        T0 =  bestfit_df['BLS TC [BTJD]'].item() 
        Dur = bestfit_df['BLS Dur [hrs]'].item() #BLS is coded to output in hours, TLS is in days...
        N_transits=bestfit_df['BLS Distinct Transit Count'].item()        
        Depth=bestfit_df['BLS depth [ppt]'].item()/1000
    #
    RP =  bestfit_df['Planet Radius [RE]'].item()
    transit_duration = Dur
    import astropy.units as u
    transit_duration_in_days = (Dur*u.hour).to(u.day).value
    
    page_num=6
    if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
        savefilename=saveReportpath+'TIC_'+str(ID)+'_Multi_Sector_'+report_dir_name_suffix+'_page'+str(page_num)+'.png'
    else:
        savefilename=saveReportpath+'TIC_'+str(ID)+f'_{sector_tag}_{report_dir_name_suffix}_page'+str(page_num)+'.png'
    #
    metrics = plot_modshift_NEMESIS(ID=ID,LC_df=LC_df,star=star,
                          period=P,dur=transit_duration_in_days,T0=T0,
                          save_file=savefilename, 
                          verbose=verbose)
    #
    # merge bestfit_df with metrics    
    bestfit_df_merged = pd.concat([bestfit_df, metrics.add_prefix('LEOVetter_')], axis=1) # append horizontally
    # resave results
    if verbose==True:
        print('Calculating LEO-Vetter False Alarm and False Positive metrics. \n Appending Results to: ')
    if (get_all_sectors==True) or (Sector is None) or (type(Sector) is not int):
        print(saveReportpath + 'TIC_'+str(ID)+'_Multi_Sector_'+BLSorTLS+'_bestfit.csv', 'file')
        bestfit_df_merged.to_csv(saveReportpath + 'TIC_'+str(ID)+'_Multi_Sector_'+BLSorTLS+'_bestfit.csv')
    else:
        print(saveReportpath + 'TIC_'+str(ID)+f'_{sector_tag}_'+BLSorTLS+'_bestfit.csv', 'file')
        bestfit_df_merged.to_csv(saveReportpath + 'TIC_'+str(ID)+f'_{sector_tag}_'+BLSorTLS+'_bestfit.csv')
#
#
#
def Vetting_Report_multi_page(ID, nearby_star_catalog, Sector, cadence,
                               hdu, BLSorTLS, default_settings,
                               # --- optional SAP diagnostic kwargs (new) ---
                               bkg_residuals=None, bkg_trend=None, bkg_level_per_pix=None,
                               quat_jitter=None, quat_status="not provided",
                               qlp_result=None, quality_flag=None):
    """
    Produce pages 2–6 of the NEMESIS vetting report and merge all pages
    into a single multi-page PDF.

    This is the top-level orchestrator for the multi-page vetting report.
    It reads the BLS/TLS CSV results from disk, recreates page 1 if the
    PNG is missing, calls each page function in sequence, and merges the
    resulting PNGs into a PDF via ``append_PDF``.

    Pages produced
    --------------
    1  ``Vetting_Report``                                — transit search summary
    2  ``Vetting_Report_2nd_page``                   — full LC summary + SAP diagnostics
    3  ``Vetting_Report_3rd_page``                       — LS periodogram + phase-folds
    4  ``Vetting_Report_4th_page``                       — centroid + symmetry tests
    5  ``Vetting_Report_5th_page_plot_individual_transits`` — individual transit zoom-ins
    6  ``Vetting_Report_6th_page_LEOVetter``             — LEO-Vetter modshift analysis

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``.
    Sector : int, list, or None
        Sector(s) processed; used to construct output filenames.
    cadence : str
        TESS exposure cadence string.
    hdu : fits.HDUList or list of fits.HDUList
        Raw FITS data; forwarded to page functions that need the cutout.
    BLSorTLS : str
        ``'BLS'`` or ``'TLS'``; selects which CSV files are read and
        which report directory is used.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``get_all_sectors``,
        ``verbose``, ``for_injections``, ``inject_param_P_RP_T0``,
        ``saveReportpath_BLS``, ``saveReportpath_TLS``, ``savelcpath``.
    bkg_level_per_pix : np.ndarray or None, optional
        SAP background level per pixel (``SAP`` return [7]).
        Forwarded to page 2.  Default is ``None``.
    bkg_trend : np.ndarray or None, optional
        Biweight background trend (``SAP`` return [8]).
        Forwarded to page 2.  Default is ``None``.
    bkg_residuals : np.ndarray or None, optional
        Background residuals after trend removal (``SAP`` return [9]).
        Forwarded to page 2.  Default is ``None``.
    quat_jitter : np.ndarray or None, optional
        Pre-normalisation quaternion jitter scalar (``SAP`` return [10]).
        Forwarded to page 2.  Default is ``None``.
    quat_status : str, optional
        Human-readable quaternion masking status (``SAP`` return [11]).
        Forwarded to page 2.  Default is ``"not provided"``.
    qlp_result : dict or None, optional
        QLP feature dictionary for diagnostic heatmaps (``SAP`` return [12]).
        Forwarded to page 2.  Default is ``None``.
    quality_flag : np.ndarray or None, optional
        Integer quality flag array (``SAP`` return [6]).
        Forwarded to page 2.  Default is ``None``.

    Returns
    -------
    None
        All pages saved as PNGs and merged into a single PDF.

    Notes
    -----
    When any SAP diagnostic kwarg is ``None`` the corresponding panel on
    page 2 renders a placeholder label rather than raising an error.

    Saved outputs
    -------------
    ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page2.png``
    ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page3.png``
    ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page4.png``
    ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page5.png``
    ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report_page6.png``
    ``{saveReportpath}/TIC_{ID}_{sector_tag}_{BLS|TLS}_Report.pdf``
    """

    import gc
    import os
    import pandas as pd

    # ── settings ──────────────────────────────────────────────────────────────
    path              = default_settings.get('path')
    savelcpath        = default_settings.get('savelcpath')
    downloadpath      = default_settings.get('downloadpath')
    get_all_sectors   = default_settings.get('get_all_sectors')
    N_transits        = default_settings.get('N_transits')
    for_injections    = default_settings.get('for_injections')
    inject_param_P_RP_T0 = default_settings.get('inject_param_P_RP_T0')
    verbose           = default_settings.get('verbose')
    # use only desired quality flags
    vetting_quality_flags = default_settings.get('vetting_report_quality_flags')

    if vetting_quality_flags is None:
        vetting_quality_flags = default_settings.get('transit_search_quality_flags', [0])    
    #
    if BLSorTLS == 'BLS':
        saveReportpath         = default_settings.get('saveReportpath_BLS')
        report_dir_name_suffix = 'BLS_Report'
    else:
        saveReportpath         = default_settings.get('saveReportpath_TLS')
        report_dir_name_suffix = 'TLS_Report'

    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"

    # ── read LC and transit-search results from disk ──────────────────────────
    if (get_all_sectors is True) or (Sector is None):
        Sectors = search_sectors_from_filetype_and_path(ID, default_settings)
        all_LCs = []
        for s in Sectors:
            _st = f"Sector_{s:04d}"
            all_LCs.append(pd.read_csv(savelcpath + f'TIC_{ID}_{_st}_final_LC.csv'))
        LC_df = pd.concat(all_LCs)
    else:
        if type(Sector) == list:
            all_LCs = []
            for s in Sector:
                _st = f"Sector_{s:04d}"
                all_LCs.append(pd.read_csv(savelcpath + f'TIC_{ID}_{_st}_final_LC.csv'))
            LC_df = pd.concat(all_LCs)
        else:
            _st   = f"Sector_{Sector:04d}"
            LC_df = pd.read_csv(savelcpath + f'TIC_{ID}_{_st}_final_LC.csv')
            
    LC_df = _filter_lc_by_quality_flags(LC_df, allowed_quality_flags=vetting_quality_flags,
                                        quality_col='QUALITY_FLAG', verbose=verbose ) 
    
    finite_mask = (
        np.isfinite(pd.to_numeric(LC_df['Time'], errors='coerce').to_numpy()) &
        np.isfinite(pd.to_numeric(LC_df['SAP Flux'], errors='coerce').to_numpy()) &
        np.isfinite(pd.to_numeric(LC_df['Detrended Flux'], errors='coerce').to_numpy()) &
        np.isfinite(pd.to_numeric(LC_df['Detrended Error'], errors='coerce').to_numpy()) &
        (pd.to_numeric(LC_df['Detrended Error'], errors='coerce').to_numpy() > 0)
    )

    if verbose:
        print(f"[vetting finite filter] keeping {finite_mask.sum()}/{len(LC_df)} rows")

    LC_df = LC_df.loc[finite_mask].reset_index(drop=True)    

    if BLSorTLS == 'TLS':
        if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
            BLSorTLS_df         = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_TLS.csv')
            BLSorTLSmodel_df    = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_TLS_model.csv')
            BLSorTLSbestfit_df  = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_TLS_bestfit.csv')
            BLSorTLSTCs_df      = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_TLS_TCs.csv')
        else:
            BLSorTLS_df         = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_TLS.csv')
            BLSorTLSmodel_df    = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_TLS_model.csv')
            BLSorTLSbestfit_df  = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_TLS_bestfit.csv')
            BLSorTLSTCs_df      = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_TLS_TCs.csv')
    else:  # BLS
        if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
            BLSorTLS_df         = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_BLS.csv')
            BLSorTLSmodel_df    = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_BLS_model.csv')
            BLSorTLSbestfit_df  = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_BLS_bestfit.csv')
            BLSorTLSTCs_df      = pd.read_csv(saveReportpath + f'TIC_{ID}_Multi_Sector_BLS_TCs.csv')
        else:
            BLSorTLS_df         = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_BLS.csv')
            BLSorTLSmodel_df    = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_BLS_model.csv')
            BLSorTLSbestfit_df  = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_BLS_bestfit.csv')
            BLSorTLSTCs_df      = pd.read_csv(saveReportpath + f'TIC_{ID}_{sector_tag}_BLS_TCs.csv')

    # ── check / re-create page 1 if missing ──────────────────────────────────
    if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
        vet_page1 = (saveReportpath + f'TIC_{ID}_Multi_Sector_'
                     + report_dir_name_suffix + '.png')
    else:
        vet_page1 = (saveReportpath + f'TIC_{ID}_{sector_tag}_'
                     + report_dir_name_suffix + '.png')

    if not os.path.exists(vet_page1):
        print('Page 1 not found — re-creating now...')
        Vetting_Report(ID, nearby_star_catalog, Sector, cadence,
                       hdu, default_settings, BLSorTLS=BLSorTLS)

    # =========================================================================
    # PAGE 2 — Full LC summary (with optional SAP diagnostic panels)
    # =========================================================================
    if verbose:
        print('Adding page 2 of Vetting Report (LC summary)\n')

    Vetting_Report_2nd_page(
        ID, nearby_star_catalog, Sector, LC_df, hdu,
        path, cadence,
        BLSorTLSbestfit_df, BLSorTLS,
        default_settings=default_settings,
        # Forward all SAP diagnostic arrays — any that are None produce
        # graceful placeholder panels rather than errors.
        bkg_residuals     = bkg_residuals,
        bkg_trend         = bkg_trend,
        bkg_level_per_pix = bkg_level_per_pix,
        quat_jitter       = quat_jitter,
        quat_status       = quat_status,
        qlp_result        = qlp_result,
        quality_flag      = quality_flag,
    )

    # =========================================================================
    # PAGE 3 — LS periodogram + full phase-folds + odd/even panels
    # =========================================================================
    if verbose:
        print('Adding page 3 of Vetting Report (LS + phase-folds)\n')

    Vetting_Report_3rd_page(
        ID, Sector, LC_df, path, cadence,
        BLSorTLSbestfit_df, BLSorTLS,
        default_settings=default_settings,
    )

    # =========================================================================
    # PAGE 4 — Centroid analysis + symmetry / mirrored-transit vetting
    # =========================================================================
    if verbose:
        print('Adding page 4 of Vetting Report (centroid + symmetry)\n')

    Vetting_Report_4th_page(
        ID, Sector, LC_df, hdu, path, cadence,
        BLSorTLSbestfit_df, BLSorTLS, BLSorTLSmodel_df,
        default_settings=default_settings,
        verbose=verbose,
    )

    # =========================================================================
    # PAGE 5 — Individual transit zoom-ins
    # =========================================================================
    if verbose:
        print('Adding page 5 of Vetting Report (individual transits)\n')

    Vetting_Report_5th_page_plot_individual_transits(
        ID, Sector, cadence, LC_df, path,
        BLSorTLSbestfit_df, BLSorTLSmodel_df,
        BLSorTLS,
        default_settings=default_settings,
    )

    # =========================================================================
    # PAGE 6 — LEO-Vetter modshift analysis
    # =========================================================================
    if verbose:
        print('Adding page 6 of Vetting Report (LEO-Vetter modshift)\n')

    Vetting_Report_6th_page_LEOVetter(
        ID, nearby_star_catalog, Sector, cadence,
        LC_df, path,
        BLSorTLSbestfit_df, BLSorTLS,
        default_settings=default_settings,
        verbose=verbose,
    )

    print(' ')

    # ── assemble input PNG filenames for PDF merge ────────────────────────────
    if (get_all_sectors is True) or (Sector is None) or (type(Sector) is not int):
        _base = saveReportpath + f'TIC_{ID}_Multi_Sector_{report_dir_name_suffix}'
    else:
        _base = saveReportpath + f'TIC_{ID}_{sector_tag}_{report_dir_name_suffix}'

    input_files = [
        _base + '.png',            # page 1
        _base + '_page2.png',      # page 2
        _base + '_page3.png',      # page 3
        _base + '_page4.png',      # page 4
        _base + '_page5.png',      # page 5
        _base + '_page6.png',      # page 6
    ]

    # ── merge all pages into a single multi-page PDF ──────────────────────────
    append_PDF(ID, Sector, cadence, input_files, BLSorTLS, default_settings)

    # ── release memory ────────────────────────────────────────────────────────
    del LC_df, BLSorTLS_df, BLSorTLSmodel_df, BLSorTLSbestfit_df, BLSorTLSTCs_df
    gc.collect()
#
#
#
def Transit_Pipeline(ID, nearby_star_catalog, Sector,
                     cadence, hdu, input_LC, default_settings,
                     sap_diag=None):
    """
    Run BLS and optionally TLS transit searches, produce transit plots, and
    generate multi-page vetting reports.

    Execution order
    ---------------
    1. BLS search via ``TransitSearch('BLS', ...)`` → ``Transit_plot`` →
       ``Vetting_Report`` (page 1) → ``Vetting_Report_multi_page`` (pages 2–6).
    2. If ``max(BLS SDE) >= SDE_threshold`` and ``do_TLS_Search=True``,
       repeat for TLS.
    3. Best-fit CSV files are re-read after vetting reports so that LS
       columns appended during report generation are included in the returned
       DataFrames.

    Parameters
    ----------
    ID : int
        TIC identifier.
    nearby_star_catalog : pd.DataFrame
        Stellar catalog from ``collect_nearby_TIC_params``.
    Sector : int, list of int, or None
        Sector(s) being processed; used to construct output filenames.
    cadence : str
        TESS exposure cadence string.
    hdu : fits.HDUList or list of fits.HDUList
        Raw FITS data passed through to plotting functions.
    input_LC : pd.DataFrame
        Detrended light curve with columns ``Time``, ``Flux``, ``Error``.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``verbose``, ``SDE_threshold``,
        ``do_TLS_Search``, ``get_all_sectors``, ``saveReportpath_BLS``,
        ``saveReportpath_TLS``.
    sap_diag : dict or None, optional
        SAP diagnostic arrays from ``LC_creation``, forwarded to
        ``Vetting_Report_multi_page`` for diagnostic panels on page 2.
        Keys: ``quality_flag``, ``bkg_level_per_pix``, ``bkg_trend``,
        ``bkg_residuals``, ``quat_jitter``, ``quat_status``, ``qlp_result``.
        ``None`` or empty dict causes those panels to render as placeholders.
        Default is ``None``.

    Returns
    -------
    BLS_PowerSpectrum_df : pd.DataFrame or None
        BLS periodogram.  Columns: ``BLS Periods``, ``BLS SDE``.
    BLS_TransitModel_df : pd.DataFrame or None
        BLS best-fit transit model.  Columns: ``Time``, ``Model``.
    BLS_TransitParams_df : pd.DataFrame or None
        BLS best-fit parameters.  Columns include: ``BLS Period [d]``,
        ``BLS TC [BTJD]``, ``BLS Dur [hrs]``, ``Planet Radius [RE]``,
        ``BLS depth [ppt]``, ``BLS SDE``, plus LS columns appended during
        vetting report generation.
    TLS_PowerSpectrum_df : pd.DataFrame or None
        TLS periodogram, or ``None`` if TLS was not run.
    TLS_TransitModel_df : pd.DataFrame or None
        TLS transit model, or ``None`` if TLS was not run.
    TLS_TransitParams_df : pd.DataFrame or None
        TLS best-fit parameters (same structure as BLS equivalent),
        or ``None`` if TLS was not run.

    Notes
    -----
    Returns ``(None, None, None, None, None, None)`` if BLS produces
    a degenerate power spectrum (all NaN/inf values).

    Saved outputs
    -------------
    ``TIC_{ID}_{sector_tag}_BLS.csv``,  ``_BLS_model.csv``,
    ``_BLS_bestfit.csv``,  ``_BLS_TCs.csv``,  ``_BLS_Report.pdf``
    and TLS equivalents (when TLS is run).
    """   
    import time as clock
    import pandas as pd

    # ── settings ──────────────────────────────────────────────────────────────
    path                = default_settings.get('path')
    verbose             = default_settings.get('verbose')
    SDE_threshold       = default_settings.get('SDE_threshold')
    do_TLS_Search       = default_settings.get('do_TLS_Search')
    get_all_sectors     = default_settings.get('get_all_sectors')
    # Ensure only desired quality-flags are used for transit searching
    allowed_quality_flags = default_settings.get('transit_search_quality_flags', [0])

    _sector_tag = (
        'Multi_Sector'
        if (get_all_sectors or Sector is None or not isinstance(Sector, int))
        else f'Sector_{Sector:04d}'
    )

    # ensure sap_diag is always a dict so **-unpacking is safe
    # _diag = sap_diag if isinstance(sap_diag, dict) else {} #future additions like 'quat_time' are broken here
    
    _VETTING_DIAG_KEYS = frozenset({
        'bkg_residuals',
        'bkg_trend',
        'bkg_level_per_pix',
        'quat_jitter',
        'quat_status',
        'qlp_result',
        'quality_flag',
    })

    _diag = {
        k: v
        for k, v in (sap_diag if isinstance(sap_diag, dict) else {}).items()
        if k in _VETTING_DIAG_KEYS
    }    

    print('Beginning Transit Search!\n')
    start = clock.time()
    
    # use only desired quality flags
    input_LC = _filter_lc_by_quality_flags(input_LC, allowed_quality_flags=allowed_quality_flags,
                                           quality_col='QUALITY_FLAG', verbose=verbose)
    #
    # remove rows that are unusable for transit search
    finite = (
        np.isfinite(pd.to_numeric(input_LC['Time'],  errors='coerce').to_numpy()) &
        np.isfinite(pd.to_numeric(input_LC['Flux'],  errors='coerce').to_numpy()) &
        np.isfinite(pd.to_numeric(input_LC['Error'], errors='coerce').to_numpy()) &
        (pd.to_numeric(input_LC['Error'], errors='coerce').to_numpy() > 0)
    )
    
    input_LC = input_LC[finite]

    if verbose:
        print(f'[Transit_Pipeline finite filter] keeping {finite.sum()}/{len(input_LC)} rows')

    input_LC = input_LC.sort_values('Time').drop_duplicates(subset='Time').reset_index(drop=True)
    
    if len(input_LC) < 10:
        print('problem: too few finite cadences remain after quality/finite filtering')
        return None, None, None, None, None, None

    # ── BLS search ────────────────────────────────────────────────────────────
    BLSorTLS = 'BLS'
    tempstart = clock.time()
    if verbose:
        print(f'\ndoing {BLSorTLS} search')

    PowerSpectrum_df, TransitModel_df, TransitParams_df = TransitSearch(
        BLSorTLS, ID, nearby_star_catalog, Sector,
        cadence, hdu, input_LC, default_settings)

    if isinstance(PowerSpectrum_df, type(None)):
        print('problem with infinite/nan values in BLS Power Spectrum')
        return None, None, None, None, None, None

    # BLS plot
    Transit_plot(ID, nearby_star_catalog, Sector, cadence, hdu, BLSorTLS,
                 input_LC, PowerSpectrum_df, TransitModel_df, TransitParams_df,
                 default_settings)

    # BLS vetting report page 1
    Vetting_Report(ID, nearby_star_catalog, Sector, cadence, hdu,
                   default_settings, BLSorTLS=BLSorTLS)

    # BLS multi-page report — forward SAP diagnostics
    Vetting_Report_multi_page(
        ID, nearby_star_catalog, Sector, cadence, hdu,
        BLSorTLS, default_settings,
        **_diag)

    # re-read bestfit CSV so LS columns appended by vetting reports are included
    try:
        _bls_path = (default_settings.get('saveReportpath_BLS')
                     + f'TIC_{ID}_{_sector_tag}_BLS_bestfit.csv')
        import os
        if os.path.exists(_bls_path):
            TransitParams_df = pd.read_csv(_bls_path)
            if verbose:
                print(f'[Transit_Pipeline] re-read BLS bestfit: {_bls_path}')
    except Exception as _e:
        if verbose:
            print(f'[Transit_Pipeline] could not re-read BLS bestfit: {_e}')

    if verbose:
        timer(start=start, end=clock.time(), message='BLS vetting reports took:')
    #
    if (PowerSpectrum_df is None) or ('BLS SDE' not in PowerSpectrum_df.columns):
        _sde_arr = np.array([], dtype=float)
    else:
        _sde_arr = np.asarray(PowerSpectrum_df['BLS SDE'], dtype=float)

    _finite = np.isfinite(_sde_arr)
    bls_peak_sde = float(np.max(_sde_arr[_finite])) if _finite.any() else float('nan')
    _sde_unknown = not np.isfinite(bls_peak_sde)
    _gate_off = (SDE_threshold is None) or (float(SDE_threshold) <= 0.0)

    _run_tls = bool(do_TLS_Search) and (
        _gate_off or _sde_unknown or (bls_peak_sde >= float(SDE_threshold)))

    if verbose and not _run_tls:
        print(f'\n[Transit_Pipeline] TLS SKIPPED: do_TLS_Search={do_TLS_Search}, '
              f'BLS peak SDE={bls_peak_sde}, SDE_threshold={SDE_threshold}. '
              f'No TLS bestfit will be written for this star-sector.\n')

    if _run_tls:
        if verbose:
            _sde_str = ('nan (degenerate BLS power spectrum)' if _sde_unknown
                        else f'{bls_peak_sde:.2f}')
            print(f'\nBLS max SDE ({_sde_str}) -- running TLS.\n')
        BLSorTLS  = 'TLS'
        tempstart = clock.time()
        print(f'doing {BLSorTLS} search')

        PowerSpectrum_df2, TransitModel_df2, TransitParams_df2 = TransitSearch(
            BLSorTLS, ID, nearby_star_catalog, Sector,
            cadence, hdu, input_LC, default_settings)

        if verbose:
            timer(start=start, end=clock.time(), message='TLS took:')

        if isinstance(PowerSpectrum_df2, type(None)):
            print('problem with infinite/nan values in TLS Power Spectrum')
            return None, None, None, None, None, None

        # TLS plot
        Transit_plot(ID, nearby_star_catalog, Sector, cadence, hdu, BLSorTLS,
                     input_LC, PowerSpectrum_df2, TransitModel_df2,
                     TransitParams_df2, default_settings)

        # TLS vetting report page 1
        Vetting_Report(ID, nearby_star_catalog, Sector, cadence, hdu,
                       default_settings, BLSorTLS)

        # TLS multi-page report — forward SAP diagnostics
        Vetting_Report_multi_page(
            ID, nearby_star_catalog, Sector, cadence, hdu,
            BLSorTLS, default_settings,
            **_diag)

        # re-read TLS bestfit
        try:
            _tls_path = (default_settings.get('saveReportpath_TLS')
                         + f'TIC_{ID}_{_sector_tag}_TLS_bestfit.csv')
            if os.path.exists(_tls_path):
                TransitParams_df2 = pd.read_csv(_tls_path)
                if verbose:
                    print(f'[Transit_Pipeline] re-read TLS bestfit: {_tls_path}')
        except Exception as _e:
            if verbose:
                print(f'[Transit_Pipeline] could not re-read TLS bestfit: {_e}')

        if verbose:
            timer(start=start, end=clock.time(), message='TLS vetting reports took:')

        print('Transit search and multi page report is complete!')
        timer(start=start, end=clock.time(), message='Transit search total:')
        return (PowerSpectrum_df,  TransitModel_df,  TransitParams_df,
                PowerSpectrum_df2, TransitModel_df2, TransitParams_df2)

    else:
        if verbose:
            if bls_peak_sde < SDE_threshold:
                print(f'BLS SDE ({bls_peak_sde:.2f}) < threshold ({SDE_threshold}) — '
                      'skipping TLS.')
            if not do_TLS_Search:
                print('do_TLS_Search=False — only BLS performed.')
            print('Transit search and multi page report is complete!')

        timer(start=start, end=clock.time(), message='Transit search total:')
        return (PowerSpectrum_df, TransitModel_df, TransitParams_df,
                None, None, None)
