def default_NEMESIS_pipeline_settings(return_dict: bool = True):
    """
    Return the default settings dictionary for the NEMESIS pipeline.

    All ``full_pipeline``, ``LC_creation``, and sub-function calls read
    their configuration from this dictionary. Individual keys can be
    overridden by passing ``**kwargs`` to ``full_pipeline``, or by
    modifying the dict before passing it via the ``settings`` argument.

    Parameters
    ----------
    return_dict : bool, optional
        If ``True`` (default), return a ``dict``. If ``False``, return
        ``tuple(settings.values())`` -- preserved for backward compatibility
        with older call sites.

    Returns
    -------
    settings : dict or tuple
        Default NEMESIS settings. When ``return_dict=True``, keys are
        grouped as follows:

        **Path / I/O**
            ``base_path`` (None), ``cache_dir_path`` (None)

        **Sector / cadence control**
            ``get_all_sectors`` (False), ``last_updated_sector`` (26),
            ``do_transit_search`` (True)

        **Aperture photometry**
            ``cutoutsize`` (11), ``minimum_photon_counts`` (1),
            ``threshold`` (7.5), ``use_SPOC_aperture`` (False),
            ``use_centroid`` (False), ``use_circ`` (True),
            ``use_sources_in_aperture`` (False),
            ``do_aperture_optimization`` (True),
            ``aperture_selection_method`` ('threshold'),
            ``aperture_auto_select`` (False),
            ``aperture_auto_contam_thresh`` (0.05),
            ``aperture_auto_tmag_thresh`` (13.0),
            ``prf_weight_threshold`` (0.01), ``prf_decontaminate`` (True),
            ``prf_cache_dir`` (None), ``prf_jitter_sigma`` (0.0),
            ``use_prf_pos_corr`` (False), ``use_centroid_prf`` (False),
            ``bitmask_string`` ('recommended')

        **Momentum dump / jitter masking**
            ``do_mdump_removal`` (True), ``before_after_in_minutes`` (0.0),
            ``keep_mdumps`` (False), ``keep_baddata`` (False),
            ``do_sector_jitter_mask`` (True), ``use_quat_jitter_mask`` (True),
            ``quat_savepath`` (None), ``quat_threshold_sigma`` (5.0),
            ``quat_min_samples`` (None), ``bkg_threshold_sigma`` (5.0),
            ``centroid_threshold_sigma`` (5.0), ``bkg_detrend_window`` (0.5)

        **PLD detrending**
            ``pld_order`` (3), ``n_pca_terms`` (3),
            ``pld_gp_proxy_window`` (0.5)

        **Smoothing**
            ``window_size_in_days`` (None), ``smoother_mode`` ('uniform')

        **Outlier removal**
            ``remove_outliers`` (True), ``Nsigma`` (2)

        **Cleanup / retention flags**
            ``keep_FITS`` (False), ``keep_raw_and_preclip`` (False),
            ``keep_imagedata`` (False), ``keep_extra_files`` (False),
            ``keep_extra_transit_files`` (False)

        **Transit search**
            ``SDE_threshold`` (0), ``do_TLS_Search`` (True),
            ``N_transits`` (3), ``minP`` (0.5), ``maxP`` (None),
            ``oversampling_factor`` (9), ``duration_grid_step`` (1.05),
            ``N_TLS_threads`` (None),
            ``transit_search_quality_flags`` ([0]),
            ``vetting_report_quality_flags`` (None)

        **Transit injection**
            ``for_injections`` (False), ``inject_param_P_RP_T0`` (None)

        **Display / verbosity**
            ``verbose`` (False), ``show_fig`` (False),
            ``return_default_settings`` (False)

    Examples
    --------
    >>> ds = default_NEMESIS_pipeline_settings()
    >>> ds['SDE_threshold'] = 6.0
    >>> ds['do_TLS_Search'] = False
    >>> ds['verbose'] = True

    Backward-compatible tuple usage:
    >>> vals = default_NEMESIS_pipeline_settings(return_dict=False)
    """
    settings = {
        # ── Path / I/O ────────────────────────────────────────────────────────
        'base_path':                        None,
        'cache_dir_path':                   None,
        'shard_cache_by_tic':               False,
        'mast_query_attempts':              2,

        # ── Sector / cadence control ──────────────────────────────────────────
        'get_all_sectors':                  False,
        'last_updated_sector':              26,
        'do_transit_search':                True,
        'scramble_orbits':                  False, # used for scramble test, scrambles orbits per sector

        # ── Aperture photometry ───────────────────────────────────────────────
        'cutoutsize':                       11,
        'minimum_photon_counts':            1,
        'threshold':                        7.5,
        'use_SPOC_aperture':                False,
        'use_centroid':                     False,
        'use_circ':                         True,
        'use_sources_in_aperture':          False,
        'do_aperture_optimization':         False,
        #'plot_catalog_source':              'TIC', # or 'gaia'
        # PRF / aperture-method selection
#         'aperture_selection_method':        'threshold',
        'aperture_auto_select':             False,
        'aperture_auto_contam_thresh':      0.05,
        'aperture_auto_tmag_thresh':        13.0,
#         'prf_weight_threshold':             0.01,
        'prf_decontaminate':                True,
        'prf_cache_dir':                    None,
        'prf_jitter_sigma':                 0.0,
        'use_prf_pos_corr':                 False,
        'use_centroid_prf':                 False,
        # NEW SAP_ALT5
        'use_prf_in_optimization'    : False,
        'opt_thresholds'             : (3.0, 5.0, 7.5, 10.0),
        'opt_radii'                  : (1.0, 1.5, 2.0, 2.5),
        'aperture_method'            : 'threshold',
        'aperture_method_param'      : None,
        'circular_aperture_radius'   : 1.5,
        'neighbor_catalog_source'    : 'tic',
        'plot_catalog_source'        : 'gaia',
        'neighbor_excision_dtmag'    : 5.0,
        'neighbor_excision_radius'   : 1.5,
        'neighbor_blend_threshold_px': 2.0,
        'neighbor_excision_min_pix'  : 2,
        'neighbor_blend_shrink_radius': 1.5,
        'max_aperture_radius'         : 3.0,
        'circular_fallback_radii'    : (1.0, 1.5, 2.0),
        'use_prf_weights'            : False,
        'prf_cache_dir'              : None,   # auto-derived; see below
        'prf_weight_threshold'       : 0.01,
        # Quality bitmask
        'bitmask_string':                   'recommended',

        # ── Momentum dump / jitter masking ────────────────────────────────────
        'do_mdump_removal':                 True,
        'before_after_in_minutes':          0.0,
        'keep_mdumps':                      False,
        'keep_baddata':                     False,
        'do_sector_jitter_mask':            False,
        'use_quat_jitter_mask':             True,
        'quat_savepath':                    None,
        'quat_threshold_sigma':             5.0,
        'quat_min_samples':                 None,   # auto: 25% of cadence in 2-s samples
        'bkg_threshold_sigma':              5.0,
        'centroid_threshold_sigma':         5.0,
        'bkg_detrend_window':               12 / 24,  # days (0.5 d)

        # ── PLD detrending ────────────────────────────────────────────────────
        'pld_order':                        3,
        'n_pca_terms':                      3,
        'pld_gp_proxy_window':              0.5,    # days; None -> single-pass PLD
        'pld_transit_mask_sigma': 4.0,    # MAD-sigma threshold for dip detection
        'pld_transit_mask_iter':  3,      # max refinement iterations (0 = disable)
        'pld_transit_mask_grow':  1,      # grow each flagged cadence by ±N neighbours

        # ── Smoothing ─────────────────────────────────────────────────────────
        'window_size_in_days':              None,
        'smoother_mode':                    'uniform',

        # ── Outlier removal ───────────────────────────────────────────────────
        'remove_outliers':                  True,
        'Nsigma':                           2,

        # ── Cleanup / retention flags ─────────────────────────────────────────
        'keep_FITS':                        False,
        'keep_raw_and_preclip':             False,
        'keep_imagedata':                   False,
        'keep_extra_files':                 False,
        'keep_extra_transit_files':         False,

        # ── Transit search ────────────────────────────────────────────────────
        'SDE_threshold':                    0,
        'do_TLS_Search':                    True,
        'N_transits':                       3,
        'minP':                             0.5,
        'maxP':                             None,
        'oversampling_factor':              9,
        'duration_grid_step':               1.05,
        'N_TLS_threads':                    None,
        'transit_search_quality_flags':     [0],    # 0=clean, 1=jitter, 2=bkg/cent, 3=outlier
        'vetting_report_quality_flags':     None,   # None -> use transit_search_quality_flags

        # ── Transit injection ─────────────────────────────────────────────────
        'for_injections':                   False,
        'inject_param_P_RP_T0':             None,
        
        # ── Diagnostic visuals / report generation ────────────────────────────────
        'do_DSS_plot':              True,   # set False for injections; skips SkyView HTTP fetch
        'do_vetting_report':        True,   # set False to skip all Vetting_Report_* calls (NOT CALLED ANYWHERE!)
        'do_transit_plot':          True,   # set False to skip Transit_plot figure (NOT CALLED ANYWHERE!)
        'do_save_pdf':              True,   # set False to skip append_PDF merge (NOT CALLED ANYWHERE!)

        # ── Display / verbosity ───────────────────────────────────────────────
        'verbose':                          False,
        'show_fig':                         False,
        'return_default_settings':          False,
    }

    if return_dict:
        return settings
    return tuple(settings.values())
#
def cleanup(ID, cadence, Sector, default_settings):
    """
    Conditionally delete NEMESIS intermediate and ancillary data products
    at the end of a pipeline run.

    Each deletion step is gated by a ``keep_*`` boolean flag in
    ``default_settings``.  All deletions are best-effort: individual file
    errors are silently ignored so that a missing file does not abort cleanup
    of the remaining products.

    Deletion steps and their controlling flags
    ------------------------------------------
    ``keep_FITS = False``
        Remove TESScut FITS files from the download cache via
        ``safe_cleanup_cache``.

    ``keep_raw_and_preclip = False``
        Remove per-sector ``_final_LC_preclipped.csv``,
        ``_bad_outliers.csv``, ``_good_outliers.csv``.

    ``keep_imagedata = False``
        Remove per-sector ``_pix_mask.pkl``, ``_bkg_mask.pkl``,
        ``_image_fluxes.pkl``, ``_RAW_LC_systematics_removed.csv``,
        and the multi-sector equivalent.

    ``keep_extra_files = False``
        Clear the astropy download cache and any loose files directly under
        the cache root, plus pattern-matched extras under ``savelcpath``
        (``*_centroids.csv``, ``*_sources_in_aperture.csv``, etc.).

    ``keep_extra_transit_files = False``
        Remove BLS/TLS report PDFs, PNGs, and CSVs for the processed sector.
        For injection runs, also removes ``*_TransitInjected_param.csv`` and
        ``*_TransitInjected_RAWLC.csv``.

    Parameters
    ----------
    ID : int
        TIC identifier; used to construct output filenames.
    cadence : str
        TESS exposure cadence string; used to determine cadence-family tag.
    Sector : int, list of int, or None
        Sector(s) processed; used to construct sector-tag strings.
    default_settings : dict
        NEMESIS settings dict.  Consumed keys: ``path``, ``savefigpath``,
        ``savelcpath``, ``downloadpath``, ``saveReportpath_BLS``,
        ``saveReportpath_TLS``, ``get_all_sectors``, ``verbose``,
        ``keep_FITS``, ``keep_raw_and_preclip``, ``keep_imagedata``,
        ``keep_extra_files``, ``keep_extra_transit_files``,
        ``for_injections``, ``inject_param_P_RP_T0``.

    Returns
    -------
    None
    """
    import os, glob
    from pathlib import Path

    # --- unpack settings ---
    path               = default_settings.get('path')
    savefigpath        = default_settings.get('savefigpath')
    savelcpath         = default_settings.get('savelcpath')
    downloadpath_raw   = default_settings.get('downloadpath')
    saveReportpath_BLS = default_settings.get('saveReportpath_BLS')
    saveReportpath_TLS = default_settings.get('saveReportpath_TLS')

    get_all_sectors            = default_settings.get('get_all_sectors')
    use_sources_in_aperture    = default_settings.get('use_sources_in_aperture')
    verbose                    = default_settings.get('verbose')
    keep_FITS                  = default_settings.get('keep_FITS')
    keep_raw_and_preclip       = default_settings.get('keep_raw_and_preclip')
    keep_imagedata             = default_settings.get('keep_imagedata')
    keep_extra_files           = default_settings.get('keep_extra_files')
    keep_extra_transit_files   = default_settings.get('keep_extra_transit_files')
    for_injections             = default_settings.get('for_injections')
    inject_param_P_RP_T0       = default_settings.get('inject_param_P_RP_T0')

    # --- canonical roots as Paths (single source of truth) ---
    cache_root   = _cache_root_from_settings(default_settings)      # <<— one true cache root
    savefigpath  = Path(savefigpath)        if savefigpath        else None
    savelcpath   = Path(savelcpath)         if savelcpath         else None
    bls_root     = Path(saveReportpath_BLS) if saveReportpath_BLS else None
    tls_root     = Path(saveReportpath_TLS) if saveReportpath_TLS else None
    #Step 0: create string tag for sector usage
    if get_all_sectors or Sector is None or not isinstance(Sector, int):
        sector_tag = "Multi_Sector"
    else:
        sector_tag = f"Sector_{Sector:04d}"                                 

    print('')

    # -------------------------------------------------------------------------
    # keep_FITS == False → use safe_cleanup_cache instead of manual deletes
    # -------------------------------------------------------------------------
    if keep_FITS is False:
        if verbose:
            print('removing FITS from cache')
        # Your original behavior only cleaned TESScut; keep that:
        safe_cleanup_cache(default_settings, tic_id=ID,
                           remove_tesscut=(not keep_FITS), remove_tpf=False, verbose=verbose)

    # -------------------------------------------------------------------------
    # keep_raw_and_preclip == False → remove specific LC CSVs (unchanged logic)
    # -------------------------------------------------------------------------
    if keep_raw_and_preclip is False and savelcpath is not None:
        if verbose:
            print('removing raw and preclipped light curves')

        def _rm(p: Path):
            try:
                if p.exists():
                    p.unlink()
            except Exception:
                pass

        if isinstance(Sector, list):
            for s in Sector:
                _sector_tag = f"Sector_{s:04d}"
                base = f"TIC_{ID}_{_sector_tag}"
                for suffix in ["_final_LC_preclipped.csv",
                               "_bad_outliers.csv",
                               "_good_outliers.csv"]:
                    _rm(savelcpath / f"{base}{suffix}")
        elif Sector is None:
            Sectors = search_sectors_from_filetype_and_path(ID, default_settings)
            if verbose:
                print(f'Sector is None: Sectors = {Sectors}')
            for s in Sectors:
                _sector_tag = f"Sector_{s:04d}"
                base = f"TIC_{ID}_{_sector_tag}"
                for suffix in ["_final_LC_preclipped.csv",
                               "_bad_outliers.csv",
                               "_good_outliers.csv"]:
                    _rm(savelcpath / f"{base}{suffix}")
        else:
            _sector_tag = f"Sector_{Sector:04d}"
            base = f"TIC_{ID}_{_sector_tag}"
            for suffix in ["_final_LC_preclipped.csv",
                           "_bad_outliers.csv",
                           "_good_outliers.csv"]:
                _rm(savelcpath / f"{base}{suffix}")

    # -------------------------------------------------------------------------
    # keep_imagedata == False → remove masks/images/raw-systematics-removed (unchanged)
    # -------------------------------------------------------------------------
    if keep_imagedata is False and savelcpath is not None:
        if verbose:
            print('removing raw-systematics removed LC, image data, aperture and background pixels')

        def _rm(p: Path):
            try:
                if p.exists():
                    p.unlink()
            except Exception:
                pass

        def _rm_im_data_for_sector(base):
            for suffix in ["_pix_mask.pkl",
                           "_bkg_mask.pkl",
                           "_image_fluxes.pkl",
                           "_RAW_LC_systematics_removed.csv"]:
                _rm(savelcpath / f"{base}{suffix}")

        if isinstance(Sector, list):
            for s in Sector:
                _sector_tag = f"Sector_{s:04d}"
                _rm_im_data_for_sector(f"TIC_{ID}_{_sector_tag}")
            _rm(savelcpath / f"TIC_{ID}_Multi_Sector_RAW_LC_systematics_removed.csv")
        elif Sector is None:
            Sectors = search_sectors_from_filetype_and_path(ID, default_settings)
            if verbose:
                print(f'Sector is None: Sectors = {Sectors}')
            for s in Sectors:
                _sector_tag = f"Sector_{s:04d}"
                _rm_im_data_for_sector(f"TIC_{ID}_{_sector_tag}")
            _rm(savelcpath / f"TIC_{ID}_Multi_Sector_RAW_LC_systematics_removed.csv")
        else:
            _sector_tag = f"Sector_{Sector:04d}"
            _rm_im_data_for_sector(f"TIC_{ID}_{_sector_tag}")
    #
    # -------------------------------------------------------------------------
    # keep_extra_files == False → clear astropy cache + top-level cache files
    # -------------------------------------------------------------------------
    if keep_extra_files is False:
        if verbose:
            print('removing all other extra NEMESIS files')
        import astropy
        try:
            astropy.utils.data.clear_download_cache()
        except Exception:
            pass

        # remove only files directly under cache_root (keep subdirs)
        try:
            for f in cache_root.iterdir():
                if f.is_file():
                    try:
                        f.unlink()
                    except Exception:
                        pass
        except Exception:
            pass

        # Exact-filename deletion scoped to THIS TIC + Sector only.
        # Never glob savelcpath: it is shared across concurrent disBatch
        # workers, and a bare '*RAW_LC.csv' glob deletes other targets'
        # in-flight files (cross-worker race).
        if savelcpath is not None:
            _extra_suffixes = ["_bad_outliers.csv",
                               "_good_outliers.csv",
                               "_final_LC_preclipped.csv",
                               "_RAW_LC.csv"]

            def _rm_exact_extra(base: str):
                for suffix in _extra_suffixes:
                    p = savelcpath / f"{base}{suffix}"
                    try:
                        if p.exists():
                            p.unlink()
                    except Exception:
                        pass

            if isinstance(Sector, list):
                for s in Sector:
                    _rm_exact_extra(f"TIC_{ID}_Sector_{s:04d}")
                _rm_exact_extra(f"TIC_{ID}_Multi_Sector")
            elif Sector is None:
                Sectors = search_sectors_from_filetype_and_path(ID, default_settings)
                if verbose:
                    print(f'Sector is None: Sectors = {Sectors}')
                for s in Sectors:
                    _rm_exact_extra(f"TIC_{ID}_Sector_{s:04d}")
                _rm_exact_extra(f"TIC_{ID}_Multi_Sector")
            else:
                _rm_exact_extra(f"TIC_{ID}_Sector_{Sector:04d}")

    # -------------------------------------------------------------------------
    # keep_extra_transit_files == False → remove BLS/TLS reports (unchanged)
    # -------------------------------------------------------------------------
    if keep_extra_transit_files is False:
        if verbose:
            print('removing extra transit searching files')

        BLS_patterns = ["_BLS_Report.pdf", "_BLS_Report.png",
                        "_BLS.png", "_BLS.csv", "_BLS_TCs.csv"]
        TLS_patterns = ["_TLS_Report.pdf", "_TLS_Report.png",
                        "_TLS.png", "_TLS.csv", "_TLS_TCs.csv"]

        if isinstance(Sector, list) or Sector is None or get_all_sectors is True:
            basename = f"TIC_{ID}_Multi_Sector"
        elif isinstance(Sector, int):
            basename = f"TIC_{ID}_{sector_tag}"
        else:
            basename = f"TIC_{ID}_{sector_tag}"

        if bls_root is not None:
            for suffix in BLS_patterns:
                p = bls_root / f"{basename}{suffix}"
                try:
                    if p.exists():
                        p.unlink()
                except Exception:
                    pass

        if tls_root is not None:
            for suffix in TLS_patterns:
                p = tls_root / f"{basename}{suffix}"
                try:
                    if p.exists():
                        p.unlink()
                except Exception:
                    pass

        if for_injections is True and savelcpath is not None:
            for pattern in ['*_TransitInjected_param.csv', '*_TransitInjected_RAWLC.csv']:
                for f in savelcpath.glob(pattern):
                    try:
                        f.unlink()
                    except Exception:
                        pass

    print(' ')
#
# helper fucntion to convert LC_df pandas dataframe to lightkurve LightCurve
def pd_to_lk(LC_df,flux_type='PLD'):
    """
    Convert a NEMESIS ``LC_df`` DataFrame to a ``lightkurve.LightCurve`` object.

    The default ``flux`` and ``flux_err`` columns of the returned
    ``LightCurve`` are set to the flux type specified by ``flux_type``.
    All three flux types (SAP, PLD, Detrended) are also attached as
    additional columns for convenience.

    Parameters
    ----------
    LC_df : pd.DataFrame
        Light curve DataFrame as returned by ``LC_creation`` or
        ``full_pipeline``.  Must contain columns:
        ``Time``, ``SAP Flux``, ``SAP Error``,
        ``PLD Flux``, ``PLD Error``, ``PLD Model``,
        ``Detrended Flux``, ``Detrended Error``.
    flux_type : str, optional
        Which flux type to use as the primary ``flux`` / ``flux_err`` columns.
        Valid values: ``'SAP'``, ``'PLD'``, ``'Detrended'``.
        Default is ``'PLD'``.

    Returns
    -------
    lc : lightkurve.LightCurve
        LightCurve with:
        - ``time`` → ``LC_df['Time']``
        - ``flux`` → ``LC_df['{flux_type} Flux']``
        - ``flux_err`` → ``LC_df['{flux_type} Error']``
        - ``sap_flux``, ``sap_error``
        - ``pld_flux``, ``pld_error``
        - ``detrended_flux``, ``detrended_error``

    Examples
    --------
    >>> lc = pd_to_lk(LC_df, flux_type='Detrended')
    >>> lc.plot()
    """
    import lightkurve as lk
    lc = lk.LightCurve(time=LC_df['Time'].to_numpy(),
                       flux=LC_df[flux_type+' Flux'].to_numpy(),
                       flux_err = LC_df[flux_type+' Error'].to_numpy())
    
    lc['sap_flux']=LC_df['SAP Flux'].to_numpy()
    lc['sap_error']=LC_df['SAP Error'].to_numpy()

    lc['pld_flux']=LC_df['PLD Flux'].to_numpy()
    lc['pld_error']=LC_df['PLD Error'].to_numpy()
    
    lc['detrended_flux']=LC_df['Detrended Flux'].to_numpy()
    lc['detrended_error']=LC_df['Detrended Error'].to_numpy()    
    
    return lc
