#
def full_pipeline(ID, path, cadence, Sector, star=None, settings: dict | None = None, **kwargs):
    """
    End-to-end NEMESIS pipeline: FFI/TPF retrieval → SAP → PLD → detrending
    → outlier removal → BLS/TLS transit search → vetting reports.
    
    This is the primary user-facing entrypoint.  Internally it calls
    ``collect_nearby_TIC_params``, ``Make_dirs``, ``LC_creation``, and
    ``Transit_Pipeline`` in sequence, handling network retries for each MAST
    query step.  Quaternion data are pre-fetched for all target sectors before
    any SAP call, reducing race conditions when jobs run in parallel.
    
    Settings priority (high → low)
    --------------------------------
    ``**kwargs`` > ``settings`` dict > ``default_NEMESIS_pipeline_settings()``
    
    Parameters
    ----------
    ID : int
        TIC identifier, e.g., 259377017.
    path : str
        Root output directory.  All NEMESIS subdirectories are created here
        by ``Make_dirs``.
    cadence : str
        TESS exposure cadence.  Valid values:
        ``'30 minute'``, ``'10 minute'``, ``'2 minute'``, ``'20 second'``.
        Legacy aliases ``'long'``, ``'short'``, ``'fast'`` are accepted.
    Sector : int, list of int, or None
        TESS sector(s) to process.  Pass ``None`` with
        ``get_all_sectors=True`` (via ``**kwargs``) to auto-discover all
        observed sectors up to ``last_updated_sector``.
    star : pd.DataFrame or None, optional
        Pre-fetched stellar catalog row from ``collect_nearby_TIC_params``.
        If ``None``, the catalog is queried from MAST automatically.
        Default is ``None``.
    settings : dict or None, optional
        Pre-built settings dictionary, e.g., the output of
        ``default_NEMESIS_pipeline_settings()`` after user modification.
        Keys present here override internal defaults; ``**kwargs`` override
        ``settings``.  Default is ``None``.
    **kwargs
        Any key accepted by ``default_NEMESIS_pipeline_settings``.
        Common overrides include: ``get_all_sectors``, ``do_transit_search``,
        ``do_TLS_Search``, ``SDE_threshold``, ``minP``, ``maxP``,
        ``N_transits``, ``verbose``, ``keep_FITS``, ``for_injections``,
        ``inject_param_P_RP_T0``.
    
    Returns
    -------
    hdu : fits.HDUList or list of fits.HDUList or None
        Raw FITS data returned by ``gethdu``.  ``None`` if image retrieval
        failed.
    LC_df : pd.DataFrame or None
        Final processed light curve with columns:
        ``Time``, ``SAP Flux``, ``SAP Error``, ``PLD Flux``, ``PLD Error``,
        ``PLD Model``, ``Detrended Flux``, ``Detrended Error``,
        ``Fitted Trend``, ``Background Flux``, ``Background Error``,
        ``Centroid X Positions``, ``Centroid Y Positions``.
        ``None`` if LC production failed.
    transit_results : tuple or None
        6-tuple ``(BLS_PowerSpectrum_df, BLS_TransitModel_df,
        BLS_TransitParams_df, TLS_PowerSpectrum_df, TLS_TransitModel_df,
        TLS_TransitParams_df)``.  TLS entries are ``None`` if BLS SDE did
        not exceed ``SDE_threshold`` or ``do_TLS_Search=False``.
        The entire tuple is ``None`` if ``do_transit_search=False`` or if
        LC production failed.
    default_settings : dict
        The fully resolved settings dictionary used for this run, including
        all path keys populated by ``Make_dirs``.
    
    Examples
    --------
    Minimal single-sector run:
    
    >>> import os
    >>> hdu, LC_df, transit_results, settings = full_pipeline(
    ...     259377017, os.getcwd() + '/', '30 minute', 3)
    
    Multi-sector run with pre-built settings:
    
    >>> ds = default_NEMESIS_pipeline_settings()
    >>> ds['SDE_threshold'] = 6.0
    >>> ds['do_TLS_Search'] = False
    >>> hdu, LC_df, transit_results, settings = full_pipeline(
    ...     259377017, '/data/nemesis/', '2 minute', [3, 4, 5],
    ...     settings=ds)
    
    Auto-discover all sectors and run BLS only:
    
    >>> hdu, LC_df, transit_results, settings = full_pipeline(
    ...     259377017, '/data/nemesis/', '30 minute', None,
    ...     get_all_sectors=True, do_TLS_Search=False, minP=1, N_transits=2)
    """
    import numpy as np
    import pandas as pd
    import astroquery
    import requests
    import urllib.error
    import time as clock

    start = clock.time()

    # ── default settings ──────────────────────────────────────────────────────
    # priority (high → low): kwargs > settings > default_NEMESIS_pipeline_settings()
    _base             = default_NEMESIS_pipeline_settings()
    _user             = settings if settings is not None else {}
    default_settings  = {**_base, **_user, **kwargs}

    verbose = default_settings['verbose']
    if verbose:
        print(__version_message__, '\n')

    default_settings['base_path'] = str(path)

    cache_dir = default_settings.get('cache_dir_path')
    if cache_dir is not None:
        default_settings.setdefault('downloadpath', cache_dir)

    # ── stellar dictionary ────────────────────────────────────────────────────
    if star is None:
        star, nearby_star_catalog = collect_nearby_TIC_params(
            ID, N_TESS_pixels=2)

    # =========================================================================
    # INITIALIZER: canonicalise paths + pre-fetch quaternions
    # =========================================================================

    # 1. Make_dirs must run first so downloadpath is populated in default_settings
    #    before we derive the quat path from it.
    Make_dirs(Sector, cadence, default_settings, return_paths=False)

    # 2. Canonicalise quaternion path (writes back into default_settings)
    _resolve_quat_savepath(default_settings)

    # 3. Resolve which sectors we will actually process
    target_sectors = _resolve_target_sectors(
        ID, Sector, star, default_settings)

    # 4. Pre-fetch quaternions (non-fatal; best-effort)
    if target_sectors:
        prefetch_quaternions(
            sectors=target_sectors,
            default_settings=default_settings,
            overwrite=False,
            verbose=verbose,
        )
    # =========================================================================

    # ── light curve creation ──────────────────────────────────────────────────
    try:
        hdu, LC_df, sap_diag = LC_creation(
            ID, nearby_star_catalog, cadence, Sector, default_settings)

    except (astroquery.exceptions.TimeoutError,
            requests.exceptions.HTTPError,
            requests.exceptions.ConnectionError,
            urllib.error.URLError) as E:
        if verbose:
            print(f'\n{E}\nTrying NEMESIS light curve creation again')
        clock.sleep(1)
        hdu, LC_df, sap_diag = LC_creation(
            ID, nearby_star_catalog, cadence, Sector, default_settings)

    # ── transit search ────────────────────────────────────────────────────────
    if default_settings['do_transit_search']:
        if LC_df is not None:
#             input_LC = pd.DataFrame({
#                 'Time':  LC_df['Time'].to_numpy(dtype=np.float64),
#                 'Flux':  LC_df['Detrended Flux'].to_numpy(dtype=np.float64),
#                 'Error': LC_df['Detrended Error'].to_numpy(dtype=np.float64),
#             })
            input_LC_dict = {
                'Time':  LC_df['Time'].to_numpy(dtype=np.float64),
                'Flux':  LC_df['Detrended Flux'].to_numpy(dtype=np.float64),
                'Error': LC_df['Detrended Error'].to_numpy(dtype=np.float64),
            }

            if 'QUALITY_FLAG' in LC_df.columns:
                input_LC_dict['QUALITY_FLAG'] = LC_df['QUALITY_FLAG'].to_numpy(dtype=int)

            if 'CADENCE_INDEX' in LC_df.columns:
                input_LC_dict['CADENCE_INDEX'] = LC_df['CADENCE_INDEX'].to_numpy(dtype=int)

            input_LC = pd.DataFrame(input_LC_dict)
            print('')
            try:
                transit_results = Transit_Pipeline(
                    ID, nearby_star_catalog, Sector, cadence,
                    hdu, input_LC, default_settings,
                    sap_diag=sap_diag)
            except (astroquery.exceptions.TimeoutError,
                    requests.exceptions.HTTPError,
                    requests.exceptions.ConnectionError,
                    urllib.error.URLError) as E:
                print(E)
                print('trying again in a bit')
                clock.sleep(1)
                print(' ')
                transit_results = Transit_Pipeline(
                    ID, nearby_star_catalog, Sector, cadence,
                    hdu, input_LC, default_settings,
                    sap_diag=sap_diag)

            cleanup(ID, cadence, Sector, default_settings)
            timer(start, clock.time(), 'NEMESIS Pipeline took:')
            return hdu, LC_df, transit_results, default_settings

        else:
            cleanup(ID, cadence, Sector, default_settings)
            timer(start, clock.time(), 'NEMESIS Pipeline took:')
            return None, None, None, default_settings

    else:
        cleanup(ID, cadence, Sector, default_settings)
        timer(start, clock.time(), 'NEMESIS Pipeline took:')
        return hdu, LC_df, None, default_settings
